// ---- Chart.js Global Config (HD rendering on all screens) ----
// Chart.js is loaded from a CDN, which can be blocked or simply unreachable in
// the field. Touching it unguarded here would throw at top level and abort the
// rest of this file: every `const` below would stay uninitialised while the
// hoisted function declarations still look alive, so the app would fail in a
// deeply confusing way instead of just losing its charts.
if (window.Chart) {
    Chart.defaults.devicePixelRatio = Math.max(window.devicePixelRatio || 1, 2);
} else {
    console.warn('[chart] Chart.js tidak termuat — grafik dinonaktifkan, sisa aplikasi tetap berjalan.');
}

// Every chart goes through here. Without Chart.js the canvas is replaced by a
// short note and the caller simply gets null back, so the rest of the render
// (KPIs, repair table, alerts) still runs instead of dying on a missing CDN.
function makeChart(canvasId, config) {
    const canvas = document.getElementById(canvasId);
    if (!canvas) return null;
    if (!window.Chart) {
        const host = canvas.parentNode;
        if (host && !host.querySelector('.chart-unavailable')) {
            const note = document.createElement('div');
            note.className = 'chart-unavailable';
            note.textContent = 'Chart unavailable — the chart library failed to load.';
            host.appendChild(note);
        }
        canvas.style.display = 'none';
        return null;
    }
    canvas.style.display = '';
    return new Chart(canvas, config);
}

// ---- Initialization ----
document.addEventListener('DOMContentLoaded', () => {
    // Light-only theme (warm editorial). Clear any stale dark preference so the
    // app never renders the retired dark mode.
    document.body.classList.remove('dark');

    setupEventListeners();
    setupKeyboardShortcuts();
    showAppVersion();
    watchConnection();
    registerServiceWorker();

    loadImplements();
    loadDamages();
    loadLicenseStock();
    checkStorageUsage();

    if (loadFromStorage()) {
        onDataLoaded();
    }

    // Local data is now in globalData — safe to start cloud sync if cloud is ready.
    _localDataLoaded = true;
    maybeInitCloudSync();
});

function setupEventListeners() {
    // "Sign out & erase this device" in another tab: drop what this tab holds.
    window.addEventListener('storage', e => { if (e.key === ERASE_BROADCAST_KEY && e.newValue) appReload(); });
    // The offline database could not be cleared (the app was open in another tab).
    try {
        if (sessionStorage.getItem(ERASE_INCOMPLETE_KEY)) {
            sessionStorage.removeItem(ERASE_INCOMPLETE_KEY);
            setTimeout(() => showToast('Signed out, but the offline database is still on this device — close the other tabs of this app, sign in, and use "Sign out & erase this device" again', 'warning'), 500);
        }
    } catch (_) {}
    loadUnitGroupPrefs();
    // The damage component list follows the chosen unit's group.
    const dmgUnitEl = document.getElementById('dmgUnit');
    if (dmgUnitEl) {
        let t = null;
        dmgUnitEl.addEventListener('change', onDamageUnitChanged);
        dmgUnitEl.addEventListener('input', () => { clearTimeout(t); t = setTimeout(onDamageUnitChanged, 150); });
    }
    // Global unit search (topbar)
    const gSearch = document.getElementById('globalSearch');
    if (gSearch) {
        let gTimer = null;
        gSearch.addEventListener('input', () => {
            clearTimeout(gTimer);
            gTimer = setTimeout(renderGlobalSearchResults, 150);
        });
        gSearch.addEventListener('keydown', e => {
            if (e.key === 'Enter') {
                const first = document.querySelector('#globalSearchResults .global-search__item');
                if (first) first.click();
            } else if (e.key === 'Escape') {
                closeGlobalSearch();
                gSearch.blur();
            } else if (e.key === 'ArrowDown') {
                const first = document.querySelector('#globalSearchResults .global-search__item');
                if (first) { e.preventDefault(); first.focus(); }
            }
        });
        // In the list: arrows move between results, Escape goes back to the box.
        document.getElementById('globalSearchResults')?.addEventListener('keydown', e => {
            const items = [...document.querySelectorAll('#globalSearchResults .global-search__item')];
            const i = items.indexOf(document.activeElement);
            if (i < 0) return;
            if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
                e.preventDefault();
                const next = items[i + (e.key === 'ArrowDown' ? 1 : -1)];
                if (next) next.focus(); else if (e.key === 'ArrowUp') gSearch.focus();
            } else if (e.key === 'Escape') {
                e.stopPropagation();
                closeGlobalSearch();
                gSearch.focus();
            }
        });
        document.addEventListener('click', e => {
            if (!e.target.closest('#globalSearchWrap')) closeGlobalSearch();
        });
    }

    // Dashboard filters
    document.getElementById('searchInput').addEventListener('input', applyFilter);
    document.getElementById('statusFilter').addEventListener('change', applyFilter);
    document.getElementById('siteFilter').addEventListener('change', applyFilter);
    document.getElementById('componentFilter').addEventListener('change', applyFilter);

    // Edit page search box
    const editSearch = document.getElementById('editSearch');
    if (editSearch) editSearch.addEventListener('input', renderEditTable);

    // Implements page search box
    const implementSearch = document.getElementById('implementSearch');
    if (implementSearch) implementSearch.addEventListener('input', renderImplementsTable);
    const implementCsvInput = document.getElementById('implementCsvInput');
    if (implementCsvInput) implementCsvInput.addEventListener('change', e => {
        const file = e.target.files[0];
        if (file) handleImplementCSVImport(file);
        implementCsvInput.value = '';
    });

    // Damage (Kerusakan) page search + type filter
    const damageSearch = document.getElementById('damageSearch');
    if (damageSearch) damageSearch.addEventListener('input', () => { damageUnitFilter = ''; renderDamageTable(); });
    const damageTypeFilter = document.getElementById('damageTypeFilter');
    if (damageTypeFilter) damageTypeFilter.addEventListener('change', renderDamageTable);

    // License stock page search + filters
    const licenseSearch = document.getElementById('licenseSearch');
    if (licenseSearch) licenseSearch.addEventListener('input', renderLicenseStockTable);
    const licenseTxnFilter = document.getElementById('licenseTxnFilter');
    if (licenseTxnFilter) licenseTxnFilter.addEventListener('change', renderLicenseStockTable);
    const licenseTypeFilter = document.getElementById('licenseTypeFilter');
    if (licenseTypeFilter) licenseTypeFilter.addEventListener('change', renderLicenseStockTable);
    const licenseCsvInput = document.getElementById('licenseCsvInput');
    if (licenseCsvInput) licenseCsvInput.addEventListener('change', e => {
        const file = e.target.files[0];
        if (file) handleLicenseCSVImport(file);
        licenseCsvInput.value = '';
    });

    // Edit page CSV upload
    const editInput = document.getElementById('editCsvInput');
    editInput.addEventListener('change', e => {
        const file = e.target.files[0];
        if (file) handleEditCSVImport(file);
        editInput.value = '';
    });

    // Edit page drag & drop
    const dropZone = document.getElementById('editDropZone');
    dropZone.addEventListener('dragover', e => { e.preventDefault(); dropZone.style.borderColor = themeColor('--info', '#5A7DA0'); });
    dropZone.addEventListener('dragleave', () => { dropZone.style.borderColor = ''; });
    dropZone.addEventListener('drop', e => {
        e.preventDefault();
        dropZone.style.borderColor = '';
        const file = e.dataTransfer.files[0];
        if (file && file.name.endsWith('.csv')) {
            handleEditCSVImport(file);
        } else {
            showToast('Please upload a .csv file', 'error');
        }
    });

    // Restore backup file input
    const restoreInput = document.getElementById('restoreFileInput');
    if (restoreInput) {
        restoreInput.addEventListener('change', e => {
            const file = e.target.files[0];
            if (file) importBackup(file);
            restoreInput.value = '';
        });
    }

    // Attachment file input
    const attachInput = document.getElementById('attachFileInput');
    if (attachInput) {
        attachInput.addEventListener('change', handleAttachFileChange);
    }

    // Restore compact mode preference
    if (localStorage.getItem('editTableCompact') === '1') {
        const table = document.getElementById('editTable');
        if (table) table.classList.add('compact');
        const icon = document.querySelector('#compactToggle i');
        if (icon) icon.className = 'fas fa-expand';
    }

    // Close COA dropdowns on outside click
    document.addEventListener('click', () => {
        document.querySelectorAll('.coa-cell.open').forEach(el => el.classList.remove('open'));
    });
}

// Escape used to reach exactly three of the eighteen modals, even though every
// one of them already has a close function. The rest trapped the keyboard: the
// only way out was the mouse. One map, so a new modal is one line here rather
// than an edit to the key handler.
//
// The value is a function NAME, not the function: most of these are defined
// further down this file and would be undefined at this point.
const MODAL_CLOSERS = {
    unitModal:            'closeModal',
    historyModal:         'closeHistory',
    importReportModal:    'closeImportReport',
    phantomHistoryModal:  'closePhantomHistory',
    emailSettingsModal:   'closeEmailSettingsModal',
    bulkEditModal:        'closeBulkEdit',
    implementModal:       'closeImplementModal',
    unitProfileModal:     'closeUnitProfile',
    damageModal:          'closeDamageModal',
    damageRepairModal:    'closeDamageRepair',
    licenseModal:         'closeLicenseModal',
    licSyncModal:         'closeLicSyncModal',
    inspectionModal:      'closeInspectionModal',
    licenseReqModal:      'closeLicenseRequirements',
    valueMergeModal:      'closeValueMerge',
    masterListsModal:     'closeMasterLists',
    inspectionPlanModal:  'closeInspectionPlanModal',
    categoriesModal:      'closeCategoriesModal',
    damageComponentsModal:'closeDamageComponentsModal',
    accessModal:          'closeAccessModal',
    teamMembersModal:     'closeTeamMembersModal',
    workLogModal:         'closeWorkLogModal',
    leaveModal:           'closeLeaveModal',
    deviceModal:          'closeDeviceModal',
    vehicleModal:         'closeVehicleModal',
    fuelModal:            'closeFuelModal',
    stockModal:           'closeStockModal',
    // Not a plain dismissal: an abandoned breakdown reason has to put the
    // inline cell back, or the grid shows a status that was never saved.
    restoreReportModal:   'closeRestoreReport',
    autoBackupModal:      'closeAutoBackups',
    breakdownReasonModal: 'cancelBreakdownReason'
};

// ============================================================
// UNSAVED TYPING — Back, X and Cancel ask before throwing it away
// ------------------------------------------------------------
// A long damage "Kronologi" typed on a phone was wiped by one accidental
// edge-swipe Back: the closers asked only about photos. Each form's state is
// noted when its modal opens (after the open function has filled it — a
// MutationObserver callback runs after that code), and closing without
// saving asks when it differs.
// ============================================================
const FORM_GUARDS = { damageModal: 'damageForm', workLogModal: 'workLogForm', leaveModal: 'leaveForm',
                      inspectionModal: 'inspectionForm', unitModal: 'unitForm',
                      vehicleModal: 'vehicleForm', fuelModal: 'fuelForm' };
const _formOpenState = {};
const _formReopened = new Set();   // reopened with text a refused save kept

function _formStateKey(formId) {
    let key = JSON.stringify(captureFormState(formId));
    // A check report's results, and a daily report's units, are buttons and
    // chips, not inputs.
    if (formId === 'inspectionForm' && typeof _insResults !== 'undefined') key += JSON.stringify(_insResults || {});
    if (formId === 'workLogForm' && typeof _wlUnits !== 'undefined') key += JSON.stringify(_wlUnits || []);
    return key;
}
function watchFormEdits() {
    if (typeof MutationObserver !== 'function') return;
    Object.keys(FORM_GUARDS).forEach(modalId => {
        const formId = FORM_GUARDS[modalId];
        const m = document.getElementById(modalId);
        if (!m || !document.getElementById(formId)) return;
        let wasOpen = m.classList.contains('open');
        new MutationObserver(() => {
            const open = m.classList.contains('open');
            if (open && !wasOpen) _formOpenState[formId] = _formStateKey(formId);
            if (!open && wasOpen) { delete _formOpenState[formId]; _formReopened.delete(formId); }
            wasOpen = open;
        }).observe(m, { attributes: true, attributeFilter: ['class'] });
    });
}
function formHasUnsavedTyping(formId) {
    if (_formReopened.has(formId)) return true;
    const was = _formOpenState[formId];
    return was != null && was !== _formStateKey(formId);
}
// The question the closers share. True when it is fine to close.
function okToDiscardTyping(formId) {
    return !formHasUnsavedTyping(formId) || confirm('Discard what you typed? It has not been saved.');
}

// Closes the topmost open modal only. Closing all of them at once would
// dismiss the page behind a confirmation dialog the user is still reading.
// The lightbox has its own handler (with arrow-key navigation) and sits above
// everything, so it is checked first.
function closeTopModal() {
    const lightbox = document.getElementById('photoLightbox');
    if (lightbox && lightbox.classList.contains('open')) { closePhotoLightbox(); return true; }

    const open = Array.from(document.querySelectorAll('.modal-overlay.open'));
    if (open.length === 0) {
        if (isNavOpen()) { closeNav(); return true; }
        return false;
    }
    const top = open[open.length - 1];
    const fn = window[MODAL_CLOSERS[top.id]];
    if (typeof fn === 'function') {
        // closeWorkLogModal(force) must be called WITHOUT force, so the
        // unsaved-photo guard still gets to ask.
        fn();
        return true;
    }
    // A modal with no registered closer is a bug, but stranding the keyboard
    // is worse than closing it bluntly.
    console.warn(`[ui] ${top.id} belum terdaftar di MODAL_CLOSERS`);
    top.classList.remove('open');
    return true;
}

// Focus goes back where it came from when a modal closes. Without this, Tab
// after closing restarts at the top of the document and the place the person
// was working is lost — the reason keyboard users avoid modals.
let _focusBeforeModal = null;

function rememberFocus() {
    const el = document.activeElement;
    _focusBeforeModal = (el && el !== document.body) ? el : null;
}

function restoreFocus() {
    const el = _focusBeforeModal;
    _focusBeforeModal = null;
    if (el && document.contains(el) && typeof el.focus === 'function') {
        try { el.focus(); } catch (_) {}
    }
}

// Wiring remember/restore into all eighteen open and close functions would be
// thirty-six edits that the next modal would forget to repeat. Watch the class
// instead: every modal in this app opens and closes by toggling .open.
function watchModalFocus() {
    const overlays = document.querySelectorAll('.modal-overlay');
    if (!overlays.length || typeof MutationObserver !== 'function') return;
    const anyOpen = () => !!document.querySelector('.modal-overlay.open');
    let wasOpen = anyOpen();

    const obs = new MutationObserver(() => {
        const isOpen = anyOpen();
        if (isOpen === wasOpen) return;
        wasOpen = isOpen;
        if (isOpen) return;      // remembered on the way in, below
        restoreFocus();
    });

    overlays.forEach(el => {
        obs.observe(el, { attributes: true, attributeFilter: ['class'] });
    });

    // Remember before the modal opens, while the trigger still has focus —
    // by the time the class lands, focus may already have moved.
    document.addEventListener('mousedown', () => { if (!anyOpen()) rememberFocus(); }, true);
    document.addEventListener('keydown', e => {
        if ((e.key === 'Enter' || e.key === ' ') && !anyOpen()) rememberFocus();
    }, true);
}

// The 34 sortable headers are styled as controls and carry an onclick, but had
// no tabindex, no role and no aria-sort: unreachable by keyboard and silent to
// a screen reader. index.html now gives them tabindex/role; this makes the keys
// work, and marks which column is sorted.
//
// Delegated rather than 34 inline onkeydown attributes, so a new sortable
// column needs nothing but the two attributes.
function setupSortableHeaders() {
    document.addEventListener('keydown', e => {
        if (e.key !== 'Enter' && e.key !== ' ') return;
        const th = e.target.closest && e.target.closest('th[role="button"]');
        if (!th) return;
        e.preventDefault();          // Space would scroll the page
        th.click();
    });
}

// Mark the sorted column. This also lights the .sort-icon: style.css:678 has
// styled th.sorted since the beginning, but nothing ever added the class, so
// the arrow never turned on.
function markSortedHeader(theadSelector, key, asc) {
    const head = document.querySelector(theadSelector);
    if (!head) return;
    head.querySelectorAll('th[role="button"]').forEach(th => {
        const onclick = th.getAttribute('onclick') || '';
        const isThis = key && onclick.includes(`'${key}'`);
        th.classList.toggle('sorted', !!isThis);
        if (isThis) th.setAttribute('aria-sort', asc ? 'ascending' : 'descending');
        else th.removeAttribute('aria-sort');
    });
}

// ============================================================
// ANDROID BACK BUTTON
// ------------------------------------------------------------
// Installed as an app (display: standalone) there is no browser history of
// its own, so Back with nothing to go back to closed the app — and the report
// open in it, photos included, with no question asked. Each layer now has a
// history entry: an open modal, and every page after the first. Back peels
// one layer: it closes the top modal through its own closer (which still asks
// about unsaved photos — cancelling keeps the modal and its entry), or goes
// back to the previous page.
// ============================================================
let _histModals = 0;        // history entries pushed for modals still open
let _popClosing = 0;        // modal closes started by Back (entry already gone)
let _ignorePops = 0;        // pops caused by our own history.go()
let _navFromHistory = false;
let _drawerEntry = false;   // a history entry was pushed for the open phone menu

// ---- Phone menu (drawer) ----
// It used to close only when a page was picked: a tap on the dimmed page,
// Escape and Back did nothing — Back even changed the page behind it. Open,
// it is a layer with its own history entry, like a modal.
function _drawerShell() { return document.getElementById('appShell'); }
function isNavOpen() { const a = _drawerShell(); return !!(a && a.classList.contains('nav-open')); }
function openNav() {
    const a = _drawerShell();
    if (!a || isNavOpen()) return;
    a.classList.add('nav-open');
    if (window.history && typeof history.pushState === 'function') {
        try {
            // A page picked from the menu replaces the menu's entry, so the
            // page underneath keeps its scroll position for Back now.
            const st = history.state;
            if (st && st.ot === 'view') history.replaceState({ ...st, scroll: _pageScroll() }, '');
            history.pushState({ ot: 'drawer', view: currentView }, ''); _drawerEntry = true;
        } catch (_) {}
    }
}
function closeNav() {
    const a = _drawerShell();
    if (!a || !isNavOpen()) return;
    a.classList.remove('nav-open');
    if (!_drawerEntry) return;
    // Decided a microtask later: a link in the menu may have just opened a
    // page or a modal, which takes over the menu's entry (_pushViewHistory,
    // the layer observer). Only an entry nobody took over is stepped back
    // over — and only while it is ours and on top; stepping back blindly can
    // leave the app.
    queueMicrotask(() => {
        if (!_drawerEntry) return;
        _drawerEntry = false;
        if (history.state && history.state.ot === 'drawer') { _ignorePops++; history.back(); }
    });
}
function toggleNav() { if (isNavOpen()) closeNav(); else openNav(); }
// The buttons that open the menu (top bar, phone bottom bar) say whether it
// is open. Watched rather than set in openNav/closeNav: Back and a dialog
// opened from the menu close it too.
(function watchNavButtons() {
    const shell = _drawerShell();
    if (!shell || typeof MutationObserver !== 'function') return;
    new MutationObserver(() => {
        const open = isNavOpen() ? 'true' : 'false';
        document.querySelectorAll('.topbar__burger, .bottom-nav__more').forEach(b => b.setAttribute('aria-expanded', open));
    }).observe(shell, { attributes: true, attributeFilter: ['class'] });
})();

function _openLayers() {
    const lb = document.getElementById('photoLightbox');
    return document.querySelectorAll('.modal-overlay.open').length + (lb && lb.classList.contains('open') ? 1 : 0);
}

function setupBackButton() {
    const shell = _drawerShell();
    if (shell) shell.addEventListener('click', e => { if (e.target === shell && isNavOpen()) closeNav(); });
    // The page sets the scroll position itself on Back (the browser's own
    // restore runs against the old, shorter page and lands in the wrong place).
    try { if ('scrollRestoration' in history) history.scrollRestoration = 'manual'; } catch (_) {}
    if (!window.history || typeof history.pushState !== 'function' || typeof MutationObserver !== 'function') return;
    try { history.replaceState({ ot: 'view', view: currentView || 'dashboard' }, ''); } catch (_) {}
    let layers = _openLayers();
    const obs = new MutationObserver(() => {
        const now = _openLayers();
        if (now > layers) {
            for (let i = layers; i < now; i++) {
                // Opened from the phone menu (History, Master Lists, …): the
                // menu closes and its entry becomes the modal's, or it would
                // be left behind as a Back press that does nothing.
                if (_drawerEntry && history.state && history.state.ot === 'drawer') {
                    _drawerEntry = false;
                    _drawerShell().classList.remove('nav-open');
                    history.replaceState({ ot: 'modal' }, '');
                } else {
                    history.pushState({ ot: 'modal' }, '');
                }
                _histModals++;
            }
        } else if (now < layers) {
            let closed = layers - now;
            // Closed by Back: its entry is already gone.
            const byBack = Math.min(closed, _popClosing);
            _popClosing -= byBack; closed -= byBack;
            // Closed by X / Cancel / Save: drop its entry too, or the next
            // Back would seem to do nothing.
            const drop = Math.min(closed, _histModals);
            if (drop > 0) {
                _histModals -= drop;
                // Only ever step back over an entry that is ours and on top.
                // history.back() is asynchronous: a modal opened (or closed)
                // before it lands shifts what "back" means, and stepping back
                // from a page entry would leave the app altogether.
                if (history.state && history.state.ot === 'modal') { _ignorePops++; history.back(); }
            }
        }
        layers = now;
    });
    document.querySelectorAll('.modal-overlay, #photoLightbox').forEach(el =>
        obs.observe(el, { attributes: true, attributeFilter: ['class'] }));

    window.addEventListener('popstate', e => {
        if (_ignorePops > 0) { _ignorePops--; return; }
        // Back with the phone menu open closes the menu, nothing else.
        if (isNavOpen()) {
            _drawerEntry = false;
            _drawerShell().classList.remove('nav-open');
            return;
        }
        if (_openLayers() > 0) {
            // Back always closes what is open on top, whatever the count says.
            _histModals = Math.max(0, _histModals - 1);
            const before = _openLayers();
            _popClosing++;
            closeTopModal();
            if (_openLayers() >= before) {
                // The closer asked and the person chose to stay: keep the
                // modal, and give it its entry back.
                _popClosing--;
                history.pushState({ ot: 'modal' }, '');
                _histModals++;
            }
            return;
        }
        const st = e.state;
        if (st && st.ot === 'view' && st.view && st.view !== currentView) {
            _navFromHistory = true;
            try { navigateTo(st.view); } finally { _navFromHistory = false; }
            // Back returns to where the person was on that page.
            _setPageScroll(typeof st.scroll === 'number' ? st.scroll : 0);
        }
    });
}

// The page scrolls in .main on wide screens and in the document on phones.
// Only that one is read and set: on a desktop the document can still scroll
// a little (the footer sits below the full-height shell), and moving it
// pushed the top bar off the screen.
function _mainScroller() {
    const m = document.querySelector('.main');
    return m && /auto|scroll/.test(getComputedStyle(m).overflowY) ? m : null;
}
function _pageScroll() {
    const m = _mainScroller();
    return Math.round(m ? m.scrollTop : window.scrollY);
}
function _setPageScroll(y) {
    const m = _mainScroller();
    if (m) m.scrollTop = y; else window.scrollTo(0, y);
}

// A page change gets its own entry (not while a modal is open — those sit on
// top), so Back returns to the page before.
// leavingScroll: where the page being left was scrolled to, read BEFORE the
// views were switched (the shorter new page clamps the scroll position).
function _pushViewHistory(view, leavingScroll) {
    if (_navFromHistory || !window.history || typeof history.pushState !== 'function') return;
    if (_openLayers() > 0) return;
    const st = history.state;
    if (st && st.ot === 'view' && st.view === view) return;
    try {
        // A page picked from the phone menu takes over the menu's entry, so
        // Back from the new page returns to the page before it.
        // (Picking the page already shown adds nothing: closeNav() then pops
        // the menu's entry, so Back is not wasted on a page that is the same.)
        if (st && st.ot === 'drawer') {
            if (st.view === view) return;
            _drawerEntry = false; history.replaceState({ ot: 'view', view }, ''); return;
        }
        // Remember where the page being left was scrolled to, for Back.
        if (st && st.ot === 'view') history.replaceState({ ...st, scroll: leavingScroll != null ? leavingScroll : _pageScroll() }, '');
        history.pushState({ ot: 'view', view }, '');
    } catch (_) {}
}

function setupKeyboardShortcuts() {
    watchModalFocus();
    watchFormEdits();
    setupBackButton();
    setupSortableHeaders();
    document.addEventListener('keydown', e => {
        const tag = e.target.tagName;
        const isTyping = tag === 'INPUT' || tag === 'TEXTAREA' || e.target.isContentEditable;

        if (e.key === 'Escape') {
            // Leave the field first, and leave the modal alone. Escape is the
            // reflex for dismissing a datalist suggestion, and closing the unit
            // form on that keystroke threw away everything typed into it — no
            // confirmation, no undo. Closing stays on the X and Batal buttons.
            if (isTyping) { e.target.blur(); return; }
            closeTopModal();
            return;
        }

        if (isTyping) return;

        if (e.key === '/') {
            e.preventDefault();
            const id = currentView === 'editUnits' ? 'editSearch' : 'searchInput';
            document.getElementById(id)?.focus();
        } else if (e.key === 'n' && currentView === 'editUnits') {
            e.preventDefault();
            showAddForm();
        } else if ((e.ctrlKey || e.metaKey) && e.key === 's') {
            e.preventDefault();
            exportBackup();
        }
    });
}

// Stamp the running build into the footer. Runs regardless of sign-in state,
// so the version is readable even from the login screen.
function showAppVersion() {
    const el = document.getElementById('appVersion');
    if (el) el.textContent = APP_VERSION;
}

// Separate so tests can stand in for it.
function appReload() { window.location.reload(); }

let _updateWatch = null;
let _swRefreshing = false;

// A new service worker has taken over. Reload once so the fresh app shell is
// shown — but never in the middle of something: a deploy used to reload the
// page under an open daily report or inspection, and the text and photos
// typed into it, which live only in memory, were gone.
function handleControllerChange() {
    if (_swRefreshing) return;
    if (!userIsBusy()) { _swRefreshing = true; appReload(); return; }
    showUpdateBanner();
    // Reload by itself once the form is closed — but only when queued
    // offline writes survive a reload (persistent cache). Otherwise the
    // banner waits for the person to choose.
    if (_updateWatch) return;
    _updateWatch = setInterval(() => {
        const durable = !window.cloud || !window.cloud.cacheMode || window.cloud.cacheMode === 'persistent-multitab';
        if (!userIsBusy() && durable && !_swRefreshing) {
            _swRefreshing = true;
            clearInterval(_updateWatch); _updateWatch = null;
            appReload();
        }
    }, 2000);
}

// Something open that a reload would throw away: a form or dialog, or a
// Unit Database cell being typed into.
function userIsBusy() {
    if (document.querySelector('.modal-overlay.open')) return true;
    const a = document.activeElement;
    return !!(a && a.isContentEditable);
}

function showUpdateBanner() {
    if (document.getElementById('updateBanner')) return;
    const bar = document.createElement('div');
    bar.id = 'updateBanner';
    bar.className = 'update-banner';
    bar.setAttribute('role', 'status');
    bar.innerHTML = '<i class="fas fa-rotate"></i><span>A new version is ready.</span>'
        + '<button type="button" class="btn btn-primary btn-sm" onclick="reloadForUpdate()">Reload</button>';
    document.body.appendChild(bar);
}

function reloadForUpdate() {
    if (userIsBusy() && !confirm('A form is still open. Reload now? Anything not saved yet — text and photos — will be lost.')) return;
    if (_updateWatch) { clearInterval(_updateWatch); _updateWatch = null; }
    _swRefreshing = true;
    appReload();
}

function registerServiceWorker() {
    if (!('serviceWorker' in navigator)) return;

    // When a new service worker takes control, reload once so the fresh app
    // shell is shown. Guard against reload loops, and skip the very first
    // install (no previous controller = first visit, nothing to refresh).
    const hadController = !!navigator.serviceWorker.controller;
    navigator.serviceWorker.addEventListener('controllerchange', () => {
        if (hadController) handleControllerChange();
    });

    window.addEventListener('load', () => {
        navigator.serviceWorker.register('./service-worker.js').then(reg => {
            // Check for a newer version on every load.
            reg.update().catch(() => {});
            // If an updated worker is already waiting, activate it now.
            if (reg.waiting) reg.waiting.postMessage('SKIP_WAITING');
            reg.addEventListener('updatefound', () => {
                const nw = reg.installing;
                if (!nw) return;
                nw.addEventListener('statechange', () => {
                    if (nw.state === 'installed' && navigator.serviceWorker.controller) {
                        nw.postMessage('SKIP_WAITING');
                    }
                });
            });
        }).catch(() => { /* offline support is best-effort */ });
    });
}

// ---- Utilities ----
function clean(v) { return (v || '').toString().trim(); }
function isGood(v) { return clean(v).toLowerCase() === 'good'; }
function pct(part, total) { return total > 0 ? Math.round((part / total) * 1000) / 10 : 0; }

// ---- CSV output ----
// Quoting alone does NOT stop a spreadsheet executing a cell: Excel and Google
// Sheets evaluate any cell whose text begins with = + - @ (or a leading tab /
// carriage return) when the file is opened. Every free-text field here —
// Nickname, Remarks, Deskripsi, Catatan — is user supplied and lands in an
// export other people open, so prefix those with an apostrophe, which
// spreadsheets strip on display but never evaluate.
function csvCell(value) {
    let v = value == null ? '' : String(value);
    if (/^[=+\-@\t\r]/.test(v)) v = "'" + v;
    return '"' + v.replace(/"/g, '""') + '"';
}

function toCSV(headers, rows) {
    return [headers, ...rows].map(row => row.map(csvCell).join(',')).join('\n');
}

// ---- Calendar dates (YYYY-MM-DD), always in the viewer's LOCAL time ----
// Every date in this app is a calendar day, not an instant, but the built-ins
// treat them as UTC: `new Date('2026-09-01')` is UTC midnight, and
// `toISOString().slice(0,10)` reports the UTC day. That skews a whole day
// wherever the local date differs from the UTC one — one day EARLY west of
// UTC, and in WIB/WITA any time before 07:00/08:00 local still reports
// yesterday. It stopped being cosmetic once applyExpiredLicenseDowngrades
// began WRITING a tier downgrade off getExpiryStatus.
function parseLocalDate(value) {
    const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(String(value || '').trim());
    if (m) return new Date(+m[1], +m[2] - 1, +m[3]);   // local midnight
    const d = new Date(value);
    return isNaN(d.getTime()) ? null : d;
}

// "YYYY-MM-DD HH:MM:SS" in the viewer's local time — what a spreadsheet shows
// as-is. toISOString() wrote UTC, nine hours behind WIT, and before 09:00
// the date itself read as yesterday.
function toLocalDateTime(ms) {
    const d = new Date(ms);
    if (isNaN(d.getTime())) return '';
    const p = n => String(n).padStart(2, '0');
    return `${toISODate(d)} ${p(d.getHours())}:${p(d.getMinutes())}:${p(d.getSeconds())}`;
}

function toISODate(d = new Date()) {
    if (!d || isNaN(d.getTime())) return '';
    const p = n => String(n).padStart(2, '0');
    return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())}`;
}

// Calendar date exactly one year on, or '' when the input isn't a date.
function addOneYearISO(value) {
    const d = parseLocalDate(value);
    if (!d) return '';
    d.setFullYear(d.getFullYear() + 1);
    return toISODate(d);
}

function getVal(row, key) {
    const k = Object.keys(row).find(h => h.toLowerCase().trim() === key.toLowerCase());
    return k ? uncsvCell(row[k]) : '';
}

// The other half of csvCell(): our exports put a ' in front of a value that
// starts with = + - @ so a spreadsheet does not run it as a formula. Read
// back, "-0.5 m" or "- ganti oli" must not come in as "'-0.5 m".
function uncsvCell(v) {
    return (typeof v === 'string' && /^'[=+\-@\t\r]/.test(v)) ? v.slice(1) : v;
}

// Try multiple header aliases (e.g. "Status Unit" or short "Status") and
// return the first non-empty match. Lets CSVs use either the legacy long
// headers or the shorter ones produced by exportCSV.
function getValAny(row, keys) {
    for (const key of keys) {
        const v = getVal(row, key);
        if (v !== '' && v != null) return v;
    }
    return '';
}

function generateId() {
    return 'u_' + Date.now() + '_' + Math.random().toString(36).substr(2, 5);
}

function showToast(message, type = 'info') {
    const container = document.getElementById('toastContainer');
    const toast = document.createElement('div');
    toast.className = `toast ${type}`;
    const icons = { success: 'check-circle', error: 'times-circle', warning: 'exclamation-circle', info: 'info-circle' };
    // Plain text, always. Toast messages carry unit names, member names,
    // licence types, emails — values other users write — and innerHTML made
    // every one of them a way to run code in whoever saw the toast (usually
    // the Super Admin). Pass values raw; do not escapeHtml them.
    const icon = document.createElement('i');
    icon.className = `fas fa-${icons[type] || icons.info}`;
    toast.append(icon, ' ', String(message == null ? '' : message));
    container.appendChild(toast);
    setTimeout(() => { toast.style.opacity = '0'; setTimeout(() => toast.remove(), 300); }, 4000);
}

// text: an optional line under the spinner saying what is being waited for.
function showLoading(show, text) {
    document.getElementById('loadingOverlay').classList.toggle('active', show);
    const t = document.getElementById('loadingText');
    if (t) t.textContent = show && text ? text : '';
}

// Signing in is not over when signIn() resolves: the profile is read next,
// slowly on a weak signal. The busy state lasts until a screen is shown —
// the app, the pending screen or the sign-in screen again.
let _authBusy = false;
let _authBusyTimer = null;
function setAuthBusy(formId, label, text) {
    _authBusy = true;
    showLoading(true, text);
    setFormBusy(formId, true, label);
    clearTimeout(_authBusyTimer);
    // Safety net: never leave the overlay up if no screen ever follows.
    _authBusyTimer = setTimeout(releaseAuthBusy, 45000);
}
function releaseAuthBusy() {
    clearTimeout(_authBusyTimer);
    if (!_authBusy) return;
    _authBusy = false;
    showLoading(false);
    setFormBusy('signInForm', false);
    setFormBusy('signUpForm', false);
}

// Disables the form's submit buttons while it is being sent, so a second tap
// on a slow signal does not send it twice.
function setFormBusy(formId, busy, busyLabel) {
    const form = document.getElementById(formId);
    if (!form) return;
    form.querySelectorAll('button[type="submit"]').forEach(b => {
        if (busy) {
            if (!b.dataset.idleHtml) b.dataset.idleHtml = b.innerHTML;
            b.disabled = true;
            if (busyLabel) b.textContent = busyLabel;
        } else {
            b.disabled = false;
            if (b.dataset.idleHtml) { b.innerHTML = b.dataset.idleHtml; delete b.dataset.idleHtml; }
        }
    });
}

// A value as a JS string literal that is safe INSIDE an HTML attribute such as
// onclick="fn(${jsArg(id)})". escapeHtml alone is not: the browser decodes
// &#39; back to ' before the handler runs, so '${escapeHtml(x)}' lets a
// stored value close the string and run code. JSON.stringify escapes quotes,
// backslashes and line breaks; escapeHtml then protects the attribute.
function jsArg(v) { return escapeHtml(JSON.stringify(String(v == null ? '' : v))); }
// The same for a list of strings.
function jsArgList(list) { return escapeHtml(JSON.stringify((list || []).map(v => String(v == null ? '' : v)))); }

// A stored photo is only ever a base64 image data URL. Anything else — a
// value written straight to Firestore with a quote in it — renders nothing
// instead of becoming markup.
function safeImageSrc(v) {
    const s = String(v == null ? '' : v);
    return /^data:image\/(png|jpe?g|webp|gif);base64,[A-Za-z0-9+\/=\s]+$/.test(s) ? s : '';
}

// For showToast, which renders text: the value as a string, nothing escaped.
function plainText(v) { return String(v == null ? '' : v); }

function escapeHtml(v) {
    return String(v == null ? '' : v)
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#39;');
}

function formatDuration(ms) {
    if (!ms || ms < 0) return '0h';
    const h = ms / 3600000;
    if (h < 1) return Math.round(ms / 60000) + 'm';
    if (h < 24) return h.toFixed(1) + 'h';
    const d = h / 24;
    return d.toFixed(1) + 'd';
}

// ============================================================
// NAVIGATION
// ============================================================

function navigateTo(view) {
    // Per-user access gating: the user needs at least 'view' on the area.
    if (GATED_VIEWS.includes(view) && !canViewView(view)) {
        showToast('You do not have access to this menu', 'warning');
        view = 'dashboard';
    }
    if (view === 'users' && !isOwner()) {
        showToast('Owner only', 'warning');
        view = 'dashboard';
    }

    const leavingScroll = _pageScroll();
    document.getElementById('viewDashboard').style.display = (view === 'dashboard') ? 'block' : 'none';
    document.getElementById('viewEditUnits').style.display = (view === 'editUnits') ? 'block' : 'none';
    const implView = document.getElementById('viewImplements');
    if (implView) implView.style.display = (view === 'implements') ? 'block' : 'none';
    const damageView = document.getElementById('viewDamage');
    if (damageView) damageView.style.display = (view === 'damage') ? 'block' : 'none';
    const licenseView = document.getElementById('viewLicenseStock');
    if (licenseView) licenseView.style.display = (view === 'licenseStock') ? 'block' : 'none';
    const teamView = document.getElementById('viewTeam');
    if (teamView) teamView.style.display = (view === 'team') ? 'block' : 'none';
    const whView = document.getElementById('viewWarehouse');
    if (whView) whView.style.display = (view === 'warehouse') ? 'block' : 'none';
    const leaderView = document.getElementById('viewLeader');
    if (leaderView) leaderView.style.display = (view === 'leader') ? 'block' : 'none';
    const insView = document.getElementById('viewInspection');
    if (insView) insView.style.display = (view === 'inspection') ? 'block' : 'none';
    const usersView = document.getElementById('viewUsers');
    if (usersView) usersView.style.display = (view === 'users') ? 'block' : 'none';

    const changed = currentView !== view;
    currentView = view;
    _pushViewHistory(view, leavingScroll);
    markActiveNav();
    // A new page opens at its top. On a phone the old scroll position carried
    // over, so a page picked from the menu often opened at its last card and
    // footer. Back restores the old position instead (popstate handler).
    if (changed && !_navFromHistory) _setPageScroll(0);

    // Once cloud sync is live, the in-memory arrays ARE the data — the
    // snapshots keep them current. Re-reading localStorage here swapped them
    // for whatever the cache last managed to store: when the quota was full,
    // that was an older copy, and the next edit pushed it back to the cloud.
    const fromCache = !cloudInitialized;

    if (view === 'dashboard') {
        if (fromCache) loadFromStorage();
        if (globalData.length > 0) {
            document.getElementById('emptyState').style.display = 'none';
            document.getElementById('dashboardContent').style.display = 'block';
            filteredData = scopeDashUnits();
            clearFilter();
            checkPendingAlerts();
        } else {
            document.getElementById('emptyState').style.display = '';
            document.getElementById('dashboardContent').style.display = 'none';
        }
    }

    if (view === 'editUnits') {
        if (fromCache) loadFromStorage();
        renderEditTable();
    }

    if (view === 'implements') {
        if (fromCache) loadImplements();
        renderImplementsTable();
    }

    if (view === 'damage' && currentView !== 'damage') damageUnitFilter = '';
    if (view === 'damage') {
        if (fromCache) loadDamages();
        populateDamageUnitSelect();
        renderDamageTable();
    }

    if (view === 'licenseStock') {
        if (fromCache) loadLicenseStock();
        populateLicenseTypeList();
        renderLicenseSummary();
        renderLicenseStockTable();
    }

    if (view === 'team') {
        populateWorkLogFilters();
        renderTeamView();
    }

    if (view === 'warehouse') {
        populateWarehouseFilters();
        renderWarehouseView();
    }

    if (view === 'inspection') renderInspectionView();

    if (view === 'leader') {
        // Pending sign-ups only load once the owner's user subscription runs.
        if (isOwner()) ensureUsersSubscription();
        renderLeaderView();
    }

    if (view === 'users') {
        ensureUsersSubscription();
        renderUsersView();
    }
    // Page-level UI (headers, switches) listens instead of growing this function.
    document.dispatchEvent(new CustomEvent('ot:view', { detail: { view } }));
}

// ---- Sidebar: one link per page (design F) ----
// Dashboard, Units and Damage are each ONE page; the equipment group is
// picked on the page itself, and the link opens it on the group last shown
// there. goNav(view, group) still opens a page straight on a given group
// (the tests use it to set up a page).
function goNav(view, group) {
    navigateTo(view);
    if (currentView !== view) return;   // refused for lack of access
    if (group) {
        // Switching group on the same page (Agricultural → Heavy) is a new
        // page to the person too.
        _setPageScroll(0);
        if (view === 'dashboard') setDashGroup(group);
        else if (view === 'editUnits') switchEditUnitsGroup(group);
        else if (view === 'damage') setDamageGroup(group === 'all' ? '' : group);
    }
    markActiveNav();
}

// The link of the page on screen lights up — in the sidebar and in the
// phone's bottom bar — and the phone's top row names the page. Pages without
// a button of their own in the bottom bar are reached through More, so More
// lights up for them.
function markActiveNav() {
    const mark = (el, on) => {
        el.classList.toggle('active', on);
        if (on) el.setAttribute('aria-current', 'page'); else el.removeAttribute('aria-current');
    };
    document.querySelectorAll('.nav__link').forEach(el => mark(el, !!el.dataset.view && el.dataset.view === currentView));
    let inBar = false;
    document.querySelectorAll('.bottom-nav__item[data-bnav]').forEach(el => {
        const on = el.dataset.bnav === currentView && !el.hidden;
        inBar = inBar || on;
        mark(el, on);
    });
    const more = document.querySelector('.bottom-nav__more');
    if (more) more.classList.toggle('active', !inBar);
    const title = document.getElementById('topbarTitle');
    const name = document.querySelector(`.nav__link[data-view="${currentView}"] .nav__text`);
    if (title) title.textContent = name ? name.textContent : 'Dashboard';
}

// Areas that make someone "work with" a group, for the menu only.
const NAV_GROUP_AREAS = {
    tractor: ['editUnits', 'implements', 'damage', 'licenseStock'],
    heavy:   ['editUnits', 'damage', 'inspection', 'inspectionApprove']
};
// Pages that belong to one equipment group: listed only for someone who may
// see that group. Access already closes them for an account limited to the
// other group (effectiveAccess); the menu checks the limit itself as well,
// so it never offers a page of the other group.
const NAV_PAGE_GROUP = { implements: 'tractor', licenseStock: 'tractor', inspection: 'heavy' };

function updateNavGroups() {
    const both = hasHeavyUnits() && hasTractorUnits();
    const works = { tractor: NAV_GROUP_AREAS.tractor.some(a => hasAccess(a, 'view')),
                    heavy:   NAV_GROUP_AREAS.heavy.some(a => hasAccess(a, 'view')) };
    // Someone who works with one group only lands on that group's dashboard
    // — not on the other group's, which is not their work.
    const only = works.heavy && !works.tractor ? 'heavy' : works.tractor && !works.heavy ? 'tractor' : '';
    if (only && both && dashGroupPref !== only) {
        if (currentView === 'dashboard') setDashGroup(only, { persist: false });
        else dashGroupPref = only;
    }
    // Per-area access was applied by applyAccessVisibility(); the group limit
    // closes the other group's pages on top of it.
    document.querySelectorAll('.sidebar__nav .nav__link[data-view]').forEach(el => {
        const g = NAV_PAGE_GROUP[el.dataset.view];
        if (g && !unitScopeAllows(g)) el.style.display = 'none';
    });
    // Phone bottom bar: a page the person cannot open has no button.
    document.querySelectorAll('.bottom-nav__item[data-bnav]').forEach(el => {
        const v = el.dataset.bnav;
        el.hidden = (GATED_VIEWS.includes(v) && !canViewView(v)) ||
                    (!!NAV_PAGE_GROUP[v] && !unitScopeAllows(NAV_PAGE_GROUP[v]));
    });
    // A heading whose links are all hidden goes too.
    document.querySelectorAll('.sidebar__nav .nav-group').forEach(grp => {
        const any = [...grp.querySelectorAll('.nav__link')].some(l => l.style.display !== 'none');
        grp.style.display = any ? '' : 'none';
    });
    markActiveNav();
    updateMenuButtonLabel();
}

// ============================================================
// LOCAL STORAGE
// ============================================================

function saveToStorage(data) {
    // A limited session's list must never become this device's copy: the next
    // full session would save it into the rollback ring, and restoring that
    // would delete the other group.
    if (isUnitScoped()) return;
    try {
        const next = JSON.stringify(data);
        let prev = null;
        try { prev = localStorage.getItem(STORAGE_KEY); } catch (_) {}
        localStorage.setItem(STORAGE_KEY, next);
        // The ring keeps what was there BEFORE this save. Storing the state
        // after it made the newest entry always identical to the live data —
        // three slots, two rollback points.
        if (prev && prev !== next) {
            try { writeAutoBackup(JSON.parse(prev)); } catch (_) { /* unreadable old copy: nothing to keep */ }
        }
    } catch (e) {
        showToast('Storage full. Data not saved.', 'error');
    }
}

function writeAutoBackup(data) {
    try {
        const ring = JSON.parse(localStorage.getItem(BACKUP_RING_KEY) || '[]');
        if (!Array.isArray(data)) return;
        // The same state twice is one rollback point, not two.
        const last = ring[ring.length - 1];
        if (last && JSON.stringify(last.units) === JSON.stringify(data)) return;
        ring.push({ at: Date.now(), count: data.length, units: data });
        while (ring.length > BACKUP_RING_SIZE) ring.shift();
        localStorage.setItem(BACKUP_RING_KEY, JSON.stringify(ring));
        _autoBackupFailed = false;
    } catch (e) {
        // This used to be swallowed in silence, which is the worst possible
        // place for silence: the ring quietly stopped updating while the owner
        // went on believing they had three rollback points. Said once per
        // failure run so a full disk does not become a wall of toasts.
        console.error('[backup] auto backup failed:', e);
        if (!_autoBackupFailed) {
            _autoBackupFailed = true;
            showToast('Automatic backup stopped — browser storage is full. Export a backup now.', 'error');
        }
    }
}

function loadFromStorage() {
    try {
        const raw = localStorage.getItem(STORAGE_KEY);
        if (raw) {
            applyUnitScopeToData({ units: JSON.parse(raw) });
            return globalData.length > 0;
        }
    } catch (e) { /* ignore */ }
    applyUnitScopeToData({ units: [] });
    return false;
}

// ============================================================
// INDEXEDDB — ATTACHMENT STORAGE
// ============================================================

const ATTACH_DB_NAME = 'tractorAttachments';
const ATTACH_DB_VERSION = 1;
const ATTACH_STORE = 'files';
const ATTACH_MAX_SIZE = 5 * 1024 * 1024;
const ATTACH_MAX_PER_UNIT = 10;
const ATTACH_ALLOWED_EXT = ['.pdf', '.csv', '.doc', '.docx', '.xls', '.xlsx'];

let _attachDb = null;

function attachDbOpen() {
    if (_attachDb) return Promise.resolve(_attachDb);
    return new Promise((resolve, reject) => {
        if (!window.indexedDB) { reject(new Error('IndexedDB not available')); return; }
        const req = indexedDB.open(ATTACH_DB_NAME, ATTACH_DB_VERSION);
        req.onupgradeneeded = e => {
            const db = e.target.result;
            if (!db.objectStoreNames.contains(ATTACH_STORE)) {
                const store = db.createObjectStore(ATTACH_STORE, { keyPath: 'id' });
                store.createIndex('unitId', 'unitId', { unique: false });
            }
        };
        req.onsuccess = () => { _attachDb = req.result; resolve(_attachDb); };
        req.onerror = () => reject(req.error);
    });
}

function attachDbPut(record) {
    return attachDbOpen().then(db => new Promise((resolve, reject) => {
        const tx = db.transaction(ATTACH_STORE, 'readwrite');
        tx.objectStore(ATTACH_STORE).put(record);
        tx.oncomplete = () => resolve();
        tx.onerror = () => reject(tx.error);
    }));
}

function attachDbGet(id) {
    return attachDbOpen().then(db => new Promise((resolve, reject) => {
        const tx = db.transaction(ATTACH_STORE, 'readonly');
        const req = tx.objectStore(ATTACH_STORE).get(id);
        req.onsuccess = () => resolve(req.result || null);
        req.onerror = () => reject(req.error);
    }));
}

function attachDbDelete(ids) {
    if (!ids || ids.length === 0) return Promise.resolve();
    return attachDbOpen().then(db => new Promise((resolve, reject) => {
        const tx = db.transaction(ATTACH_STORE, 'readwrite');
        const store = tx.objectStore(ATTACH_STORE);
        ids.forEach(id => store.delete(id));
        tx.oncomplete = () => resolve();
        tx.onerror = () => reject(tx.error);
    }));
}

function generateAttachId() {
    return 'att_' + Date.now() + '_' + Math.random().toString(36).slice(2, 7);
}

function formatFileSize(bytes) {
    if (bytes < 1024) return bytes + ' B';
    if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(1) + ' KB';
    return (bytes / (1024 * 1024)).toFixed(1) + ' MB';
}

function attachFileIcon(name) {
    const ext = (name || '').split('.').pop().toLowerCase();
    if (ext === 'pdf') return 'fa-file-pdf';
    if (ext === 'csv') return 'fa-file-csv';
    if (ext === 'doc' || ext === 'docx') return 'fa-file-word';
    if (ext === 'xls' || ext === 'xlsx') return 'fa-file-excel';
    return 'fa-file';
}

// ---- Attachment UI in Edit Table ----

let _currentAttachUnitId = null;
let _pendingAttachPurge = [];

function triggerAttachUpload(unitId) {
    if (!requireEdit('editUnits')) return;
    _currentAttachUnitId = unitId;
    document.getElementById('attachFileInput').click();
}

async function handleAttachFileChange(e) {
    const files = e.target.files;
    if (!files || files.length === 0) return;
    const unitId = _currentAttachUnitId;
    if (!unitId) return;

    const unit = globalData.find(d => d.id === unitId);
    if (!unit) return;
    if (!unit.attachments) unit.attachments = [];

    const currentCount = unit.attachments.length;
    let added = 0;

    for (const file of files) {
        if (currentCount + added >= ATTACH_MAX_PER_UNIT) {
            showToast(`Max ${ATTACH_MAX_PER_UNIT} files per unit`, 'warning');
            break;
        }
        const ext = '.' + file.name.split('.').pop().toLowerCase();
        if (!ATTACH_ALLOWED_EXT.includes(ext)) {
            showToast(`"${file.name}" — file type not supported (PDF, CSV, Word, Excel only)`, 'warning');
            continue;
        }
        if (file.size > ATTACH_MAX_SIZE) {
            showToast(`"${file.name}" — exceeds the 5MB limit`, 'warning');
            continue;
        }

        const attId = generateAttachId();
        const meta = { id: attId, name: file.name, type: file.type, size: file.size, addedAt: new Date().toISOString() };
        try {
            await attachDbPut({ id: attId, unitId, name: file.name, type: file.type, size: file.size, addedAt: meta.addedAt, blob: file });
            unit.attachments.push(meta);
            added++;
        } catch (err) {
            showToast(`Failed to save "${file.name}": ${err.message}`, 'error');
        }
    }

    if (added > 0) {
        saveToStorage(globalData);
        cloudPushUnits([unit]);
        renderEditTable();
        showToast(`${added} file(s) attached`, 'success');
    }

    e.target.value = '';
    _currentAttachUnitId = null;
}

async function downloadAttachment(attId) {
    try {
        const record = await attachDbGet(attId);
        if (!record || !record.blob) {
            showToast('File not available on this device — it was uploaded from another device. Use Export/Import Backup.', 'warning');
            return;
        }
        const blob = record.blob instanceof Blob ? record.blob : new Blob([record.blob], { type: record.type });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = record.name;
        a.click();
        URL.revokeObjectURL(url);
    } catch (err) {
        showToast('Failed to download file: ' + err.message, 'error');
    }
}

async function removeAttachment(unitId, attId) {
    if (!requireEdit('editUnits')) return;
    if (!confirm('Delete this attachment?')) return;
    const unit = globalData.find(d => d.id === unitId);
    if (!unit) return;

    try {
        await attachDbDelete([attId]);
    } catch (err) { /* best effort */ }

    unit.attachments = (unit.attachments || []).filter(a => a.id !== attId);
    saveToStorage(globalData);
    cloudPushUnits([unit]);
    renderEditTable();
    showToast('Attachment deleted', 'success');
}

function renderAttachCell(d) {
    const atts = d.attachments || [];
    let html = '<div class="attach-cell">';
    if (atts.length === 0) {
        html += '<span class="attach-empty">No files</span>';
    }
    atts.forEach(att => {
        // Attachment metadata rides on the unit document, so treat it as data
        // anyone with unit-edit rights could have written.
        const a = { ...att, name: String((att && att.name) || ''), size: Number(att && att.size) || 0 };
        const ext = a.name.split('.').pop().toLowerCase();
        const shortName = a.name.length > 18 ? a.name.slice(0, 15) + '…' + a.name.slice(a.name.lastIndexOf('.')) : a.name;
        html += `<div class="attach-chip attach-chip--${escapeHtml(ext)}" title="${escapeHtml(a.name)} (${escapeHtml(formatFileSize(a.size))})">
            <i class="fas ${escapeHtml(attachFileIcon(a.name))}"></i>
            <span class="attach-chip__name">${escapeHtml(shortName)}</span>
            <button class="btn-icon attach-chip__dl" title="Download" onclick="downloadAttachment(${jsArg(a.id)})"><i class="fas fa-download"></i></button>
            <button class="btn-icon attach-chip__rm" title="Delete" onclick="removeAttachment(${jsArg(d.id)},${jsArg(a.id)})"><i class="fas fa-xmark"></i></button>
        </div>`;
    });
    html += `<button class="btn-icon attach-upload-btn" title="Upload file" onclick="triggerAttachUpload(${jsArg(d.id)})"><i class="fas fa-paperclip"></i></button>`;
    html += '</div>';
    return html;
}

// Compare two field values the way the audit log will store them. logEvent
// coerces both sides through String(), so 2020 and '2020' land as the same
// entry — a strict !== here records a "change" whose Sebelum and Sesudah
// columns read identically on screen. Values arrive as strings from forms and
// CSV but as numbers from a JSON backup, so this is not hypothetical.
function sameStoredValue(a, b) {
    return String(a == null ? '' : a).trim() === String(b == null ? '' : b).trim();
}

// Last-resort client-side gate on every write to the units collection.
//
// Every other guard in this file sits at the call site, so a new caller
// inherits no protection at all. That is exactly how four automatic
// migrations came to rewrite unit names, licences and site assignments under
// accounts that had no edit rights: the rules rejected the writes, but
// logEvent had already recorded them, so the history filled with changes that
// never happened. Guarding the writers themselves means a future caller has to
// opt out deliberately instead of merely forgetting.
//
// Silent by design. Legitimate callers already went through
// requireEdit('editUnits'), which shows the message; a loop over hundreds of
// units must not raise hundreds of toasts.
function canWriteUnits(what) {
    if (hasAccess('editUnits', 'edit')) return true;
    console.warn(`[access] ${what} blocked — no edit rights on units`);
    return false;
}

function addUnits(newUnits) {
    if (!canWriteUnits('addUnits')) {
        return { added: 0, skipped: (newUnits || []).length, skippedDetails: [] };
    }
    const existingSNs = new Set(globalData.map(d => (d.sn || '').toLowerCase()));
    const toAdd = [];
    const skippedDetails = [];
    let skipped = 0;

    const existingById = new Map(globalData.map(d => [d.id, d]));
    newUnits.forEach(u => {
        // Group first. addUnits never invents a group — callers that create a
        // unit stamp it — but it refuses one it cannot read, and refuses an id
        // that already belongs to a unit of the other group.
        const k = 'unitGroup' in u ? normalizeGroupKey(u.unitGroup) : '';
        if (k === null) {
            skipped++;
            skippedDetails.push({ name: u.name, sn: u.sn, reason: `Group "${u.unitGroup}" not recognized` });
            return;
        }
        // Stored on every new unit (a missing one meaning Agricultural, as
        // always): accounts limited to one group read only stamped units.
        u.unitGroup = k || 'tractor';
        if (u.id && existingById.has(u.id) && unitGroupOf(existingById.get(u.id)) !== unitGroupOf(u)) {
            skipped++;
            skippedDetails.push({ name: u.name, sn: u.sn, reason: 'ID already used by a unit in the other group' });
            return;
        }
        // A unit never carries the other group's fields. Tractor inputs today
        // carry none, so for them this deletes nothing.
        otherGroup(unitGroupOf(u)).onlyFields.forEach(f => { delete u[f]; });

        if (!u.id) u.id = generateId();
        const snLower = (u.sn || '').toLowerCase();
        if (snLower && existingSNs.has(snLower)) {
            skipped++;
            skippedDetails.push({ name: u.name, sn: u.sn, reason: 'Duplicate serial number' });
        } else {
            if (!u.downtimeHistory) u.downtimeHistory = [];
            if (!isGood(u.status)) {
                u.breakdownStartedAt = Date.now();
                if (!u.breakdownReason) u.breakdownReason = 'Diset via impor CSV';
            }
            toAdd.push(u);
            if (snLower) existingSNs.add(snLower);
        }
    });

    if (toAdd.length > 0) {
        globalData = [...globalData, ...toAdd];
        saveToStorage(globalData);
        recordChange({ type: 'added', detail: `${toAdd.length} unit(s) added` });
        toAdd.forEach(u => logEvent({ action: 'add', unitId: u.id, unitName: u.name, after: u.sn }));
        cloudPushUnits(toAdd);
    }

    return { added: toAdd.length, skipped, skippedDetails };
}

// The write firewall for unit groups. Drops undefined (Firestore here has no
// ignoreUndefinedProperties), drops unitGroup (a group is set once, at
// creation), and drops fields owned by the other group — so no path, however
// it was reached, can write GPS onto an excavator or Camera AI onto a tractor.
// Two exceptions, both Periksa Data: clearing such a stray field to ''
// (clearStray), and naming the group of a unit whose stored group is
// unreadable (setGroup). A readable group can never be changed.
function guardUnitFields(before, fields, opts) {
    const g = unitGroupOf(before);
    const unreadable = hasUnreadableGroup(before);
    const out = {};
    const dropped = [];
    Object.keys(fields || {}).forEach(k => {
        const v = fields[k];
        if (v === undefined) { dropped.push(k); return; }
        if (k === 'unitGroup') {
            // The one way to set a group after creation: Periksa Data naming
            // the group of a unit whose stored group cannot be read. A
            // readable group stays immutable.
            const to = normalizeGroupKey(v);
            if (opts && opts.setGroup && unreadable && to) { out[k] = to; return; }
            dropped.push(k); return;
        }
        // An unreadable group owns neither group's fields: writing GPS or
        // Camera AI would be a guess about what the unit is.
        if (unreadable && (TRACTOR_ONLY_FIELDS.includes(k) || HEAVY_ONLY_FIELDS.includes(k))) { dropped.push(k); return; }
        if (!fieldAllowedForGroup(k, g) && !(opts && opts.clearStray && v === '')) { dropped.push(k); return; }
        out[k] = v;
    });
    if (dropped.length) console.warn(`[group] ${dropped.join(', ')} diabaikan untuk unit `
        + (unreadable ? `berkelompok "${before.unitGroup}" (tidak dikenal)` : groupDef(g).shortLabel));
    return out;
}

function updateUnit(id, fields, opts) {
    if (!canWriteUnits('updateUnit')) return false;
    const idx = globalData.findIndex(d => d.id === id);
    if (idx === -1) return false;

    const before = { ...globalData[idx] };
    const guarded = guardUnitFields(before, fields, opts);
    // Only a payload the guard emptied is refused; updateUnit(id, {}) keeps
    // today's behaviour.
    if (Object.keys(fields || {}).length && !Object.keys(guarded).length) return false;
    fields = guarded;
    const unit = { ...before, ...fields };

    // Downtime tracking when status changes
    if (fields.status !== undefined && fields.status !== before.status) {
        trackStatusChange(unit, before.status, fields.status);
    }

    globalData[idx] = unit;
    saveToStorage(globalData);
    cloudPushUnits([unit]);
    recordChange({ type: 'updated', detail: `Unit "${unit.name}" updated` });

    // Log each field change
    Object.keys(fields).forEach(field => {
        if (field === 'id' || field === 'downtimeHistory' || field === 'breakdownStartedAt') return;
        if (!sameStoredValue(before[field], fields[field])) {
            logEvent({
                action: 'update',
                unitId: id,
                unitName: unit.name,
                field,
                before: before[field],
                after: fields[field]
            });
        }
    });
    return true;
}

// Bulk-update existing units from parsed CSV rows, matched by serial number.
// Only non-empty CSV fields are applied so a partial CSV (e.g. just
// "Serial Number, Tahun Penerimaan") never blanks out other data.
// Storage/cloud/changelog are written once for the whole batch.
const CSV_UPDATABLE_FIELDS = [
    'name', 'model', 'implement', 'status', 'display', 'gps', 'steering', 'jdlink', 'site',
    'yearReceived', 'userCategory', 'gpsLicense', 'licenseDisplay',
    'gpsLicenseStartDate', 'gpsLicenseEndDate',
    'displayLicenseStartDate', 'displayLicenseEndDate', 'remarks', 'breakdownReason'
];

function bulkUpdateUnitsFromCSV(parsedUnits) {
    if (!canWriteUnits('bulkUpdateUnitsFromCSV')) {
        return { updated: 0, unchanged: 0, failed: [] };
    }
    const bySN = new Map();
    globalData.forEach(d => { const k = (d.sn || '').toLowerCase(); if (k) bySN.set(k, d); });

    let updated = 0, unchanged = 0;
    const failed = [];
    const changedUnits = [];

    parsedUnits.forEach(p => {
        const existing = bySN.get((p.sn || '').toLowerCase());
        if (!existing) {
            failed.push({ sn: p.sn, reason: 'Serial number not found' });
            return;
        }

        const idx = globalData.findIndex(d => d.id === existing.id);
        if (idx === -1) {
            failed.push({ sn: p.sn, reason: 'Unit not found' });
            return;
        }

        const before = { ...globalData[idx] };
        const g = unitGroupOf(before);
        if (hasUnreadableGroup(before)) {
            failed.push({ sn: p.sn, reason: `Unit group "${before.unitGroup}" not recognized — set it first via Data Check` });
            return;
        }
        // A row that names a group can only update a unit of that group: a
        // CSV never moves a unit between groups.
        if (csvExplicitGroup.has(p) && normalizeGroupKey(p.unitGroup) !== g) {
            failed.push({ sn: p.sn, reason: 'Group in the CSV differs from the unit — not moved' });
            return;
        }
        // Nor does a file whose columns belong to the other group: its values
        // for this unit would be dropped and only name/status would land —
        // on what is most likely the wrong unit.
        if (csvInferredGroup.has(p) && p.unitGroup !== g) {
            failed.push({ sn: p.sn, reason: `This file's columns belong to ${groupDef(p.unitGroup).label}, `
                + `but this SN belongs to a ${groupDef(g).label} unit — not updated` });
            return;
        }
        const fields = {};
        (g === 'heavy' ? HEAVY_CSV_UPDATABLE_FIELDS : CSV_UPDATABLE_FIELDS).forEach(f => {
            const val = p[f];
            if (val !== undefined && val !== null && String(val).trim() !== '' &&
                !sameStoredValue(val, before[f])) {
                fields[f] = val;
            }
        });

        if (Object.keys(fields).length === 0) {
            unchanged++;
            return;
        }

        // A CSV can push a unit into Breakdown without naming a reason, which
        // leaves the Alasan Breakdown column blank — the same gap Bulk Edit
        // already guards against. Keep a real reason if one is already on the
        // unit, otherwise record where it came from.
        if (fields.status !== undefined && !isGood(fields.status) && !fields.breakdownReason) {
            if (!(!isGood(before.status) && before.breakdownReason) &&
                !sameStoredValue('Diset via impor CSV', before.breakdownReason)) {
                fields.breakdownReason = 'Diset via impor CSV';
            }
        }

        const unit = { ...before, ...fields };
        if (fields.status !== undefined && fields.status !== before.status) {
            trackStatusChange(unit, before.status, fields.status);
        }

        globalData[idx] = unit;
        Object.keys(fields).forEach(field => {
            logEvent({
                action: 'update',
                unitId: unit.id,
                unitName: unit.name,
                field,
                before: before[field],
                after: fields[field]
            });
        });
        changedUnits.push(unit);
        updated++;
    });

    if (changedUnits.length > 0) {
        saveToStorage(globalData);
        cloudPushUnits(changedUnits);
        recordChange({ type: 'updated', detail: `${changedUnits.length} unit(s) updated via CSV import` });
    }

    return { updated, unchanged, failed };
}
// ============================================================
// OFFLINE-SAFE WRITES
// ------------------------------------------------------------
// Firestore queues writes made offline and replays them later, but the promise
// setDoc() returns only settles once the SERVER confirms. Offline it stays
// pending forever, so anything inside .then() never runs. That is why these two
// helpers exist: the audit entry and the user's confirmation must not depend on
// a promise that will not settle until the signal comes back.
// ============================================================

// Records the failure of a change that was already logged as done. Called from
// .catch(), so the trail says "attempted, then rejected" rather than implying
// the change stuck.
function logEventFailed(entry, err) {
    logEvent({
        ...entry,
        action: 'error',
        before: entry.after != null ? String(entry.after) : '',
        after: `FAILED (${(err && err.code) || 'error'}) — change not saved`
    });
}

// Wraps a cloud write so the user always hears something. Online, the success
// toast waits for the server as before. Offline — or if the server is simply
// slow — it says the change is held on the device, which is the truth.
function saveWithFeedback(promise, successMsg, onError) {
    let settled = false;
    // Offline we know immediately; online we give the server a fair chance
    // before claiming anything.
    const delay = navigator.onLine ? 8000 : 0;
    const timer = setTimeout(() => {
        if (settled) return;
        showToast('Saved on this device — will be sent when the signal returns', 'info');
    }, delay);
    return promise.then(value => {
        settled = true;
        clearTimeout(timer);
        if (successMsg) showToast(successMsg, 'success');
        return value;
    }).catch(err => {
        settled = true;
        clearTimeout(timer);
        // A stale service-worker bundle is not a server refusal, and the
        // caller's own "gagal menyimpan" toast does not tell anyone what to
        // do about it. Say the one thing that fixes it, then let the caller
        // roll back exactly as it would for any other rejection.
        if (err && err.code === 'stale-client') showToast(STALE_CLIENT_MSG, 'warning');
        if (onError) return onError(err);
        throw err;
    });
}

// One place where a cloud write, its audit entry and its user feedback are put
// in the right order for offline. The audit entry is recorded FIRST — logEvent
// writes to the local cache and queues its own cloud push, so it survives a
// signal drop — and only a genuine rejection adds the cancelling entry.
function cloudWrite(auditEntry, promise, successMsg, onError) {
    // An array is allowed because one action can change several fields, and
    // each field gets its own row — updateUnit is the usual case.
    const entries = Array.isArray(auditEntry) ? auditEntry.filter(Boolean)
                  : auditEntry ? [auditEntry] : [];
    entries.forEach(logEvent);
    return saveWithFeedback(promise, successMsg, err => {
        entries.forEach(e => logEventFailed(e, err));
        if (onError) onError(err);
    });
}

const STALE_CLIENT_MSG = 'Reload the page — an old version is still running, changes not sent yet';

// The service worker serves firebase-init.js network-first but falls back to
// the cache when the fetch fails — which on a bad signal is exactly when
// people are saving. A device can therefore be running today's script.js
// against a firebase-init.js from before a function existed, and a bare
// window.cloud.saveDevice(...) then throws a TypeError out of the click
// handler: no toast, no audit row, and the modal stays open over a save that
// never happened. saveWorkLog already guarded this by hand (see the
// saveWorkLogPhotos check); this is that guard, once, for everyone.
//
// Returns null when the method is missing, so callers read:
//     const fn = cloudFn('saveDevice'); if (!fn) return;
function cloudFn(name) {
    const fn = window.cloud && window.cloud[name];
    if (typeof fn === 'function') return fn.bind(window.cloud);
    console.warn(`[cloud] ${name} tidak ada — firebase-init.js lama masih disajikan`);
    showToast(STALE_CLIENT_MSG, 'warning');
    return null;
}

// The same guard for the cloudWrite(...) call sites. There the call is an
// ARGUMENT — cloudWrite(entry, window.cloud.saveDevice(rec), …) — so a missing
// method throws while the arguments are being evaluated, before cloudWrite can
// do anything about it. Returning a rejected promise instead keeps the whole
// existing failure path intact: the cancelling audit row, the rollback, the
// banner. saveWithFeedback recognises the code and explains what to do.
function cloudCall(name, ...args) {
    const fn = window.cloud && window.cloud[name];
    if (typeof fn === 'function') return fn.apply(window.cloud, args);
    console.warn(`[cloud] ${name} tidak ada — firebase-init.js lama masih disajikan`);
    const err = new Error(`window.cloud.${name} is not available`);
    err.code = 'stale-client';
    return Promise.reject(err);
}

// The four oldest modules — units, implements, damage, licenseStock — write
// through the cloudPush*/cloudDelete* helpers rather than cloudWrite. Those
// helpers used to swallow a rejection into a console line and a toast reading
// "perubahan tersimpan lokal", which was not true: the change existed only on
// that device and the audit entry had already been written as if it stuck.
// That is how the history filled with changes the server had refused.
//
// Three things happen on a rejection now:
//   1. a cancelling audit entry, so the trail says the change did not stick;
//   2. a re-read from the server, because a rejected write produces no
//      snapshot of its own — without this the screen keeps showing a value
//      that exists nowhere else, until some unrelated change triggers a sync;
//   3. a toast that names a rules rejection as a rules rejection.
//
// Offline is deliberately NOT this path: Firestore never settles the promise
// while offline, so .catch does not run and the queued write still lands.
function cloudWriteFailed(err, opts) {
    const code = (err && err.code) || 'error';
    console.error(`[cloud] ${opts.what} write failed:`, err);

    logEvent({
        action: 'error',
        unitId: opts.unitId || '',
        unitName: opts.label || '-',
        field: opts.what,
        after: `FAILED (${code}) — change not saved`
    });

    if (opts.resync && navigator.onLine) {
        Promise.resolve().then(opts.resync)
            .catch(e => console.error('[cloud] resync failed:', e));
    }

    showToast(code === 'permission-denied'
        ? `Rejected by the server — ${opts.what} reverted. Your access does not allow this change.`
        : `Failed to save ${opts.what} to the cloud — change reverted`, 'error');
}

// Pull the server's copy back over the local one after a rejected write. Each
// reuses the same snapshot applier the live subscription uses, so there is no
// second code path that could drift from it.
function resyncUnits()      { return window.cloud.getAllUnits(scopeQueryGroup()).then(applyCloudUnitsSnapshot); }
function resyncImplements() { return window.cloud.getAllImplements().then(applyCloudImplementsSnapshot); }
function resyncDamages()    { return window.cloud.getAllDamages(scopeQueryGroup()).then(applyCloudDamagesSnapshot); }
function resyncLicenses()   { return window.cloud.getAllLicenses().then(applyCloudLicenseSnapshot); }

// The status pill in the topbar doubles as the offline indicator: without it a
// field operator has no way to tell a queued save from a finished one.
function updateConnectionLabel() {
    const el = document.getElementById('connectionLabel');
    if (!el) return;
    if (navigator.onLine) {
        delete document.body.dataset.offline;
        el.textContent = `${globalData.length} Units`;
        el.removeAttribute('title');
    } else {
        document.body.dataset.offline = '1';
        // A phone shows only "Offline" — the full sentence squeezed the unit
        // search down to a few letters — but screen readers still hear it.
        el.innerHTML = '<span class="conn-long">Offline — changes saved on this device</span><span class="conn-short" aria-hidden="true">Offline</span>';
        el.title = 'Offline — changes saved on this device';
    }
}

// The sync chip shows the time of the last update; the full date stays in
// its tooltip. onDataLoaded() writes the long form, this shortens it.
document.addEventListener('ot:data', () => {
    const el = document.getElementById('lastUpdated');
    if (!el) return;
    const now = new Date();
    el.textContent = `Updated ${now.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hourCycle: 'h23' })}`;
    el.title = `Last updated: ${now.toLocaleString()}`;
});

function watchConnection() {
    window.addEventListener('online', () => {
        updateConnectionLabel();
        if (typeof renderInspectionSyncNotice === 'function') renderInspectionSyncNotice();
        showToast('Back online — sending pending changes', 'success');
    });
    window.addEventListener('offline', () => {
        updateConnectionLabel();
        if (typeof renderInspectionSyncNotice === 'function') renderInspectionSyncNotice();
        showToast('Signal lost — changes can still be saved on this device', 'warning');
    });
    updateConnectionLabel();
}

// Enough of a deleted unit, in History, to put it back by hand: who it was,
// where, what it carried and its licences. The serial number alone was all
// that remained before.
function deletedUnitSummary(u) {
    const lic = (type, end) => type ? `${type}${end ? ' until ' + end : ''}` : '';
    const bits = [
        u.sn ? `SN ${u.sn}` : '',
        [u.brand, u.model].filter(Boolean).join(' '),
        u.machineType || '',
        u.site ? `site ${u.site}` : '',
        isHeavy(u) ? (u.workTool ? `work tool ${u.workTool}` : '') : (u.implement ? `implement ${u.implement}` : ''),
        u.status ? `status ${u.status}` : '',
        isHeavy(u) ? '' : lic(u.gpsLicense, u.gpsLicenseEndDate),
        isHeavy(u) ? '' : lic(u.licenseDisplay, u.displayLicenseEndDate),
        u.yearReceived ? `received ${u.yearReceived}` : ''
    ].filter(Boolean);
    return bits.join(' · ').slice(0, 400);
}

function deleteUnits(ids) {
    if (!canWriteUnits('deleteUnits')) return { count: 0, removed: [] };
    const idSet = new Set(ids);
    const removed = globalData.filter(d => idSet.has(d.id));
    const count = removed.length;
    globalData = globalData.filter(d => !idSet.has(d.id));
    saveToStorage(globalData);
    if (count > 0) {
        recordChange({ type: 'deleted', detail: `${count} unit(s) deleted` });
        removed.forEach(u => logEvent({ action: 'delete', unitId: u.id, unitName: u.name, before: deletedUnitSummary(u),
                                        unitGroup: hasUnreadableGroup(u) ? '' : unitGroupOf(u) }));
        cloudDeleteUnits(ids);
        // A second delete inside the undo window replaces the undo toast, so
        // the first batch can no longer be undone — purge its files now, or
        // the overwritten list leaves them in IndexedDB for good.
        if (_pendingAttachPurge.length > 0) attachDbDelete(_pendingAttachPurge).catch(() => {});
        _pendingAttachPurge = removed.flatMap(u => (u.attachments || []).map(a => a.id));
    }
    return { count, removed };
}

// ============================================================
// AUDIT LOG
// ============================================================

function logEvent(entry) {
    const ts = Date.now();
    const id = `${ts}_${Math.random().toString(36).slice(2, 10)}`;
    const actor = currentUser ? {
        actorUid:   currentUser.uid,
        actorEmail: currentUser.email || '',
        actorName:  (currentUserDoc && currentUserDoc.displayName)
                    || currentUser.displayName
                    || (currentUser.email || '').split('@')[0],
        actorRole:  (currentUserDoc && currentUserDoc.role) || 'unknown'
    } : { actorUid: '', actorEmail: '', actorName: 'system', actorRole: 'system' };

    const full = {
        id,
        timestamp: ts,
        action:    entry.action || 'edit',
        unitId:    entry.unitId || '',
        unitName:  entry.unitName || '',
        field:     entry.field || '',
        before:    entry.before != null ? String(entry.before) : '',
        after:     entry.after  != null ? String(entry.after)  : '',
        ...actor
    };
    // Which group's accounts may read this row (v167); '' = only unlimited ones.
    // A caller that knows it (a unit being deleted is gone from the list)
    // passes it along.
    full.unitGroup = ['tractor', 'heavy', 'shared'].includes(entry.unitGroup) ? entry.unitGroup : historyGroupOf(full);

    // Local cache — instant render + offline support.
    try {
        const log = JSON.parse(localStorage.getItem(AUDIT_LOG_KEY) || '[]');
        log.unshift(full);
        while (log.length > AUDIT_LOG_MAX) log.pop();
        localStorage.setItem(AUDIT_LOG_KEY, JSON.stringify(log));
    } catch (e) { /* ignore */ }

    // Cloud push — coalesce many calls in the same tick into one batch.
    // Skip if not signed in (auto-migrations), or while a snapshot is being
    // applied (those mutations aren't user-initiated and shouldn't be logged).
    if (!currentUser || suppressCloudWrites || !window.cloud?.addHistoryEvents) return;
    _historyPushQueue.push(full);
    _scheduleHistoryFlush(80);
}

// Backoff for a batch that failed transiently: 5s, 10s, 20s … capped at 5 min,
// reset by the first success. Before, a failed batch waited for the NEXT
// logEvent to carry it, and closing the tab first meant it never left.
let _historyRetryDelay = 0;
function _scheduleHistoryFlush(delay) {
    if (_historyFlushTimer) return;
    _historyFlushTimer = setTimeout(_flushHistoryQueue, delay);
}

// Rules published before v167 refuse the unitGroup key on history rows. Then
// the rows go out without it for the rest of the session rather than being
// lost; the next session tries again.
let _historyWithoutGroup = false;
function _flushHistoryQueue() {
    _historyFlushTimer = null;
    if (!currentUser || !window.cloud?.addHistoryEvents) return;
    const batch = _historyPushQueue.splice(0);
    if (batch.length === 0) return;
    // Decided per send: every batch that went out WITH the key gets one retry
    // without it, however many were in flight when the first refusal came.
    const stripped = _historyWithoutGroup;
    const send = stripped ? batch.map(({ unitGroup, ...rest }) => rest) : batch;
    window.cloud.addHistoryEvents(send).then(() => {
        _historyRetryDelay = 0;
    }).catch(err => {
        console.error('[cloud] history push failed:', err);
        if (err && err.code === 'permission-denied' && !stripped && batch.some(e => 'unitGroup' in e)) {
            _historyWithoutGroup = true;
            _historyPushQueue.unshift(...batch);
            _scheduleHistoryFlush(0);
            return;
        }
        // Refused without the key too: the key was not the cause.
        if (err && err.code === 'permission-denied' && stripped) _historyWithoutGroup = false;
        if (err && err.code === 'permission-denied') {
            // The rules will keep refusing this batch, so putting it back
            // would only cost the next one too. The local cache still has
            // these rows; they just never become shared.
            showHistoryRulesBanner();
            return;
        }
        // Transient failure. splice(0) above already emptied the queue, so
        // without this the batch is simply gone. Capped, because a queue that
        // never drains is a leak and the local cache is the durable copy
        // either way.
        if (_historyPushQueue.length + batch.length <= AUDIT_LOG_MAX) {
            _historyPushQueue.unshift(...batch);
        }
        _historyRetryDelay = Math.min(_historyRetryDelay ? _historyRetryDelay * 2 : 5000, 300000);
        _scheduleHistoryFlush(_historyRetryDelay);
    });
}

function getAuditLog() {
    let local = [];
    try { local = JSON.parse(localStorage.getItem(AUDIT_LOG_KEY) || '[]'); }
    catch (e) {}
    // Cloud is the source of truth; fall back to local when offline or for
    // any entry that hasn't synced yet.
    if (!cloudHistory.length) return local.filter(historyRowInScope);
    const seen = new Set(cloudHistory.map(e => e.id));
    const merged = [...cloudHistory, ...local.filter(e => e.id && !seen.has(e.id))];
    merged.sort((a, b) => (b.timestamp || 0) - (a.timestamp || 0));
    return merged.filter(historyRowInScope).slice(0, AUDIT_LOG_MAX);
}

// The audit log used to be subscribed for everyone the moment they signed in:
// 500 documents, roughly 150 KB, on every app open — for a modal most people
// never open. Worse, the History page is gated on hasAccess('history','view')
// (see below) while the subscription was not, so an account whose History menu
// is hidden still pulled down 500 audit rows complete with every actor's name
// and e-mail. That is not merely wasteful.
//
// So it starts on the first open instead, and only for someone allowed to read
// it. Idempotent: reopening the modal does not resubscribe. tearDownCloudSync
// clears cloudHistoryUnsub, so a new session starts clean.
function startHistorySubscription() {
    if (cloudHistoryUnsub) return;
    if (!window.cloud?.isReady || !window.cloud.subscribeHistory) return;
    if (!hasAccess('history', 'view')) return;
    cloudHistoryUnsub = window.cloud.subscribeHistory(events => {
        cloudHistory = events || [];
        clearRulesBanner('history');
        // Re-render the history modal live if it's currently open
        const modal = document.getElementById('historyModal');
        if (modal && modal.classList.contains('open')) {
            showHistory(modal.dataset.unitId || undefined);
        }
    }, err => {
        console.warn('[cloud] history offline:', err && err.code, err && err.message);
        if (err && err.code === 'permission-denied') {
            showHistoryRulesBanner();
            showToast('History blocked by Firestore rules — see the message in the History panel', 'warning');
        } else if (err && err.code === 'failed-precondition' && scopeHistoryGroups()) {
            // A limited account's History needs one composite index, created
            // once by the owner (README: "Batas kelompok unit").
            showToast('History for this account needs a database index — ask the owner to create it', 'warning');
        }
        // A failed listener is dead: let the next History open try again.
        if (cloudHistoryUnsub) { try { cloudHistoryUnsub(); } catch (_) {} cloudHistoryUnsub = null; }
    }, 500, scopeHistoryGroups());
}

// Access can be revoked mid-session. Drop the stream and the cached rows with
// it, or a demoted account keeps the audit trail it was just cut off from.
function stopHistorySubscription() {
    if (!cloudHistoryUnsub) return;
    try { cloudHistoryUnsub(); } catch (_) {}
    cloudHistoryUnsub = null;
    cloudHistory = [];
}

function showHistory(unitId) {
    if (!hasAccess('history', 'view')) { showToast('You do not have access to History', 'warning'); return; }
    startHistorySubscription();
    document.getElementById('historyModal').dataset.unitId = unitId || '';
    const log = getAuditLog();
    const filtered = unitId ? log.filter(e => e.unitId === unitId) : log;
    const title = unitId
        ? `History: ${escapeHtml((globalData.find(u => u.id === unitId) || {}).name || 'Unit')}`
        : 'Change History';
    document.getElementById('historyTitle').innerHTML = title;

    const modal = document.getElementById('historyModal');
    // Stash filter so live snapshots can re-render with the same scope.
    modal.dataset.unitId = unitId || '';

    // This view is fed by a subscription capped at the newest 500 and then
    // capped again on merge, with nothing on screen saying so. Someone looking
    // for an old change scrolled to the bottom of an ordinary-looking list and
    // concluded it was not there. Say it plainly, and point at Export, which
    // is the only path that reads the whole collection.
    const truncated = filtered.length >= AUDIT_LOG_MAX;
    const countEl = document.getElementById('historyCount');
    if (countEl) {
        countEl.textContent = truncated
            ? `Showing the latest ${filtered.length} — full history via the Export button`
            : `${filtered.length} events`;
    }

    const tbody = document.getElementById('historyBody');
    if (filtered.length === 0) {
        // 'Belum ada riwayat' would be a lie for a unit whose events exist but
        // fall outside the capped window, so separate the two cases.
        tbody.innerHTML = `<tr><td colspan="7" style="text-align:center;padding:24px;color:var(--text-secondary)">${
            unitId
                ? 'No history for this unit in the latest 500 events — use Export for the full history'
                : 'No history yet'
        }</td></tr>`;
    } else {
        tbody.innerHTML = filtered.map(e => {
            const who = e.actorName
                ? `<span class="audit-actor" title="${escapeHtml(e.actorEmail || '')}">${escapeHtml(e.actorName)} <em>(${escapeHtml(e.actorRole || '?')})</em></span>`
                : '<span style="color:var(--text-light)">—</span>';
            return `
            <tr>
                <td data-label="Time" style="white-space:nowrap">${formatUserTime(e.timestamp)}</td>
                <td data-label="Action"><span class="audit-badge audit-${escapeHtml(e.action)}">${escapeHtml(e.action)}</span></td>
                <td data-label="By">${who}</td>
                <td data-label="Unit">${escapeHtml(e.unitName || '-')}</td>
                <td data-label="Field">${escapeHtml(e.field || '-')}</td>
                <td data-label="Before">${escapeHtml(e.before != null ? e.before : '-')}</td>
                <td data-label="After">${escapeHtml(e.after  != null ? e.after  : '-')}</td>
            </tr>`;
        }).join('');
    }
    modal.classList.add('open');
}

function closeHistory() {
    document.getElementById('historyModal').classList.remove('open');
}

function clearHistory() {
    if (!isOwner || !isOwner()) {
        showToast('Only the owner can delete the shared history', 'warning');
        return;
    }
    if (!confirm('Delete the ENTIRE change history for the whole team? This cannot be undone.')) return;
    localStorage.removeItem(AUDIT_LOG_KEY);
    if (window.cloud?.clearHistoryCloud) {
        window.cloud.clearHistoryCloud().then(() => {
            cloudHistory = [];
            showHistory();
            showToast('Team history deleted', 'success');
        }).catch(err => {
            console.error('[cloud] clear history failed:', err);
            showToast('Failed to delete in the cloud — check the console', 'error');
        });
    } else {
        cloudHistory = [];
        showHistory();
        showToast('History deleted', 'success');
    }
}

// ============================================================
// PHANTOM HISTORY — entries for changes the server refused
// ------------------------------------------------------------
// A history entry is written the moment an action is taken, before the server
// answers. When the server then refuses the data write — wrong access area,
// rules not published — the entry stays behind describing a change that never
// happened. It lands because /history is gated on canEditAnything(), edit on
// ANY area, while each data collection is gated on its own area.
//
// Deliberately narrow. It judges only unit field updates, because units are
// the one module whose entries carry a real document id in unitId; every other
// module reuses that field for something else, or has no pointer at all. And
// it judges only the NEWEST entry per unit and field, because an older entry
// in a chain cannot be told apart from one that applied and was later changed
// again. Everything it cannot be sure about it leaves alone — this deletes
// audit data, so under-reaching is the safe direction.
// ============================================================

const PHANTOM_SKIP_FIELDS = new Set(['id', 'downtimeHistory', 'breakdownStartedAt']);
let _phantomHistoryFound = [];

function findPhantomUnitHistory(log) {
    const byUnit = new Map(globalData.map(u => [u.id, u]));
    const newest = new Map();
    // A restore puts values back WITHOUT a per-field history row, so after
    // one a real change legitimately reads as "never happened". Nothing from
    // before the latest restore can be judged: whole-fleet restores (no
    // unitId) cover every unit, an undelete covers its own unit.
    let lastFleetRestore = 0;
    const lastUnitRestore = new Map();
    log.forEach(e => {
        if (!e || e.action !== 'restore') return;
        const ts = e.timestamp || 0;
        if (e.unitId) lastUnitRestore.set(e.unitId, Math.max(lastUnitRestore.get(e.unitId) || 0, ts));
        else lastFleetRestore = Math.max(lastFleetRestore, ts);
    });

    log.forEach(e => {
        if (!e || e.action !== 'update' || !e.unitId || !e.field) return;
        const ts = e.timestamp || 0;
        if (ts <= lastFleetRestore || ts <= (lastUnitRestore.get(e.unitId) || 0)) return;
        if (PHANTOM_SKIP_FIELDS.has(e.field)) return;
        // Other modules prefix unitName with [Tim], [Gudang], [Lisensi]… and
        // put something that is not a unit document id into unitId.
        if (String(e.unitName || '').startsWith('[')) return;
        // Unit is gone: a deleted unit leaves nothing to compare against, and
        // the entry may well be a true record of a change made before deletion.
        if (!byUnit.has(e.unitId)) return;

        const key = `${e.unitId}::${e.field}`;
        const prev = newest.get(key);
        if (!prev || (e.timestamp || 0) > (prev.timestamp || 0)) newest.set(key, e);
    });

    const found = [];
    newest.forEach(e => {
        const unit = byUnit.get(e.unitId);
        // Field not part of the record any more — nothing to compare.
        if (!(e.field in unit)) return;
        const now = unit[e.field];
        // Two conditions, and the second is what keeps this safe. The value
        // must not be what the entry claims it became, AND it must still be
        // exactly what the entry was changing away FROM — the value never
        // moved at all. Requiring only the first would mean that deleting a
        // phantom row exposes the older row beneath it to the next scan, and
        // repeated scans would eat backwards through a legitimate chain.
        if (sameStoredValue(now, e.after)) return;
        if (!sameStoredValue(now, e.before)) return;
        found.push({ entry: e, current: now });
    });
    found.sort((a, b) => (b.entry.timestamp || 0) - (a.entry.timestamp || 0));
    return found;
}

async function scanPhantomHistory() {
    if (!isOwner || !isOwner()) {
        showToast('Only the owner can check the shared history', 'warning');
        return;
    }
    if (!window.cloud?.getAllHistory) {
        showToast('A cloud connection is needed to check the history', 'warning');
        return;
    }
    showLoading(true);
    try {
        // The whole collection, not getAuditLog() — that is capped at 500 twice
        // over, and the rows we are hunting are mostly older than that.
        const log = await window.cloud.getAllHistory();
        _phantomHistoryFound = findPhantomUnitHistory(log);

        if (_phantomHistoryFound.length === 0) {
            showToast(`Checked ${log.length} records — nothing suspicious`, 'success');
            return;
        }
        renderPhantomHistory(log.length);
    } catch (err) {
        console.error('[audit] phantom scan failed:', err);
        showToast('Failed to check the history — check the console', 'error');
    } finally {
        showLoading(false);
    }
}

function renderPhantomHistory(scanned) {
    const actors = new Set(_phantomHistoryFound.map(f => f.entry.actorName || '-'));
    document.getElementById('phantomHistorySummary').textContent =
        `${_phantomHistoryFound.length} of ${scanned} records do not match the current unit data · ${actors.size} actor(s)`;

    document.getElementById('phantomHistoryBody').innerHTML = _phantomHistoryFound.map(f => {
        const e = f.entry;
        return `<tr>
            <td data-label="Time" style="white-space:nowrap">${formatUserTime(e.timestamp)}</td>
            <td data-label="By">${escapeHtml(e.actorName || '-')}</td>
            <td data-label="Unit">${escapeHtml(e.unitName || '-')}</td>
            <td data-label="Field">${escapeHtml(e.field)}</td>
            <td data-label="Before">${escapeHtml(e.before != null && e.before !== '' ? String(e.before) : '(empty)')}</td>
            <td data-label="Recorded as">${escapeHtml(e.after != null ? String(e.after) : '-')}</td>
            <td data-label="Current Value"><strong>${escapeHtml(f.current != null && f.current !== '' ? String(f.current) : '(empty)')}</strong></td>
        </tr>`;
    }).join('');

    document.getElementById('phantomHistoryDeleteBtn').textContent =
        `Delete these ${_phantomHistoryFound.length} rows`;
    document.getElementById('phantomHistoryModal').classList.add('open');
}

function closePhantomHistory() {
    document.getElementById('phantomHistoryModal').classList.remove('open');
    _phantomHistoryFound = [];
}

async function deletePhantomHistory() {
    if (!isOwner || !isOwner()) return;
    if (_phantomHistoryFound.length === 0) return;
    // The service worker can still be serving a firebase-init.js from before
    // this function existed; without the check the delete silently does
    // nothing while the toast says it worked.
    if (!window.cloud?.deleteHistoryEvents) {
        showToast('Reload the page — an old version is still running', 'warning');
        return;
    }
    const n = _phantomHistoryFound.length;
    if (!confirm(`Delete these ${n} history records for the whole team? This cannot be undone.`)) return;

    const ids = _phantomHistoryFound.map(f => f.entry.id).filter(Boolean);
    showLoading(true);
    try {
        await window.cloud.deleteHistoryEvents(ids);
        // getAuditLog() merges the local cache back over the cloud list, so
        // rows deleted only in Firestore reappear on the next render. Prune
        // both or the work is undone the moment the modal closes.
        pruneLocalAuditByIds(ids);
        const gone = new Set(ids);
        cloudHistory = cloudHistory.filter(e => !gone.has(e.id));
        closePhantomHistory();
        showHistory();
        showToast(`${n} false records deleted`, 'success');
    } catch (err) {
        console.error('[audit] phantom delete failed:', err);
        showToast('Failed to delete — check the console', 'error');
    } finally {
        showLoading(false);
    }
}

function pruneLocalAuditByIds(ids) {
    const gone = new Set(ids);
    try {
        const log = JSON.parse(localStorage.getItem(AUDIT_LOG_KEY) || '[]');
        localStorage.setItem(AUDIT_LOG_KEY, JSON.stringify(log.filter(e => e && !gone.has(e.id))));
    } catch (e) { /* ignore */ }
}

// The History view is fed by a capped live subscription (newest 500), so
// exporting what's on screen silently truncated the audit trail. Pull the full
// collection from Firestore instead, falling back to the cached window when
// offline — and say which one the file actually contains.
async function exportHistory() {
    if (!canCsv('export')) return;

    let log = getAuditLog();
    let complete = false;
    if (window.cloud?.isReady && window.cloud.getAllHistory) {
        try {
            showLoading(true);
            const all = (await window.cloud.getAllHistory(scopeHistoryGroups()) || []).filter(historyRowInScope);
            if (Array.isArray(all) && all.length >= log.length) {
                log = all.slice().sort((a, b) => (b.timestamp || 0) - (a.timestamp || 0));
                complete = true;
            }
        } catch (err) {
            console.warn('[cloud] full history fetch failed, exporting cached window:', err);
        } finally {
            showLoading(false);
        }
    }

    if (log.length === 0) { showToast('No history to export', 'warning'); return; }
    // The actor columns matter more here than anywhere else in the app: this
    // export is the only path that sees the whole collection rather than the
    // newest 500, so it is the tool you reach for to answer "who changed this"
    // — and it used to be the one place that dropped the answer.
    const headers = ['Time', 'Action', 'Object', 'Field', 'Before', 'After',
                     'By', 'Email', 'Role', 'ID'];
    const rows = log.map(e => [
        toLocalDateTime(e.timestamp),
        e.action, e.unitName || '', e.field || '',
        e.before != null ? e.before : '', e.after != null ? e.after : '',
        e.actorName || '', e.actorEmail || '', e.actorRole || '', e.id || ''
    ]);
    const csv = [headers, ...rows].map(row => row.map(csvCell).join(',')).join('\n');
    const blob = new Blob(['\uFEFF' + csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `tractor_history_${toISODate()}.csv`;
    a.click();
    URL.revokeObjectURL(url);
    showToast(complete
        ? `${log.length} history events exported (complete)`
        : `${log.length} history events exported — only those stored on this device, not the full history`,
        complete ? 'success' : 'warning');
}

// ============================================================
// BACKUP & RESTORE
// ============================================================

// ============================================================
// BACKUP — what a backup actually contains
// ============================================================
// For three versions this file exported four collections out of fifteen while
// the button read "Download full JSON backup". Everything the Team and
// Warehouse modules hold — people, shift schedules, daily reports, devices,
// stock movements — had no backup at all. One table now drives both the export
// and the restore, so a collection cannot be added to the app and forgotten
// here: adding it is one row.
//
// `read` is the in-memory array. `fullRead` exists for collections whose
// in-memory copy is deliberately incomplete — shifts hold only the subscribed
// 120-day window, so backing up that array would produce a file that looks
// whole and is not, and a REPLACE restore computed against it would delete
// every shift outside the window.
const BACKUP_PARTS = [
    { key: 'implements', label: 'Implement', area: 'implements',
      read: () => globalImplements, write: l => { globalImplements = l; },
      saveLocal: () => saveImplements(), bulk: 'saveImplements',
      deleteOne: id => cloudDeleteImplement(id), resync: () => resyncImplements() },

    { key: 'damages', label: 'Damage Records', area: 'damage',
      read: () => globalDamages, write: l => { globalDamages = l; },
      // Units are restored first, so each record can take its unit's group.
      prepare: r => (r && r.id ? { ...r, unitGroup: damageGroupStamp(r) } : r),
      saveLocal: () => saveDamages(), bulk: 'saveDamages',
      deleteOne: (id, r) => { cloudDeleteDamage(id); dropDamagePhotos(r); },
      resync: () => resyncDamages() },

    { key: 'licenseStock', label: 'License Stock', area: 'licenseStock',
      read: () => globalLicenseStock, write: l => { globalLicenseStock = l; },
      saveLocal: () => saveLicenseStockLocal(), bulk: 'saveLicenses',
      deleteOne: id => cloudDeleteLicense(id), resync: () => resyncLicenses() },

    // What each implement type needs — the whole Purchase Plan hangs on it,
    // and a lost set empties the plan without a word.
    { key: 'licenseRequirements', label: 'License Requirements', area: 'licenseStock',
      read: () => licenseRequirements,
      write: l => { licenseRequirements = l; refreshLicensePlan(); },
      // firestore.rules accept only the known licence values; one odd row in a
      // hand-edited file would sink the whole batch it rides in.
      accept: r => LIC_REQ_OPTIONS.gps.includes(r.gps || '') && LIC_REQ_OPTIONS.display.includes(r.display || '')
          && typeof (r.type || '') === 'string' && String(r.type || '').length <= 120,
      bulk: 'saveLicenseRequirements',
      deleteOne: id => cloudCall('deleteLicenseRequirement', id)
          .catch(err => console.warn(`[restore] deleteLicenseRequirement(${id}) gagal:`, err)) },

    { key: 'userCategories', label: 'User Categories', area: 'editUnits',
      read: () => userCategories, write: l => { userCategories = l; },
      bulk: 'saveUserCategories', deleteOne: id => window.cloud.deleteUserCategory(id) },

    { key: 'damageComponents', label: 'Damage Components', area: 'damage',
      read: () => damageComponents, write: l => { damageComponents = l; },
      bulk: 'saveDamageComponents', deleteOne: id => window.cloud.deleteDamageComponent(id) },

    // The agreed spellings (Site, Brand, Company). Four documents keyed by
    // kind, each with its own edit area, so this one restores through
    // _restoreMasterLists instead of the per-id path. Every active account
    // reads these lists (firestore.rules), so backing them up shows nobody
    // anything new.
    { key: 'masterLists', label: 'Master Lists',
      canView: () => true,
      canEdit: () => MASTER_KINDS.some(canEditMasterList),
      read: () => MASTER_KINDS.map(k => ({ id: k, values: (masterLists[k] || []).slice() })),
      restore: (rows, merge) => _restoreMasterLists(rows, merge) },

    { key: 'teamMembers', label: 'Team Members', area: 'teamMembers',
      read: () => teamMembers, write: l => { teamMembers = l; },
      bulk: 'saveTeamMembers', deleteOne: id => window.cloud.deleteTeamMember(id) },

    { key: 'shifts', label: 'Shift Schedules', area: 'teamShift',
      read: () => teamShifts, write: l => { teamShifts = l; },
      // The subscription is windowed; the backup must not be.
      fullRead: () => window.cloud.getAllShifts(),
      bulk: 'saveShifts', deleteOne: id => window.cloud.deleteShift(id) },

    { key: 'workLogs', label: 'Daily Reports', area: 'teamLog',
      read: () => workLogs, write: l => { workLogs = l; },
      bulk: 'saveWorkLogs',
      deleteOne: (id, r) => { window.cloud.deleteWorkLog(id); if (workLogPhotoCount(r) > 0) _dropPhotoDoc('deleteWorkLogPhotos', id); } },

    { key: 'leaveRequests', label: 'Leave / Sick', area: 'teamLog',
      read: () => leaveRequests, write: l => { leaveRequests = l; },
      bulk: 'saveLeaveRequests',
      deleteOne: (id, r) => { window.cloud.deleteLeaveRequest(id); if (leaveDocCount(r) > 0) _dropPhotoDoc('deleteTeamDocs', id); } },

    { key: 'inspectionPlans', label: 'Inspection Schedules', area: 'inspection',
      read: () => inspectionPlans, write: l => { inspectionPlans = l; },
      bulk: 'saveInspectionPlans', deleteOne: id => window.cloud.deleteInspectionPlan(id) },

    { key: 'inspections', label: 'Inspection Reports', area: 'inspection',
      read: () => inspections, write: l => { inspections = l; },
      bulk: 'saveInspections',
      deleteOne: (id, r) => { window.cloud.deleteInspection(id); if (Number(r && r.photoCount) > 0) _dropPhotoDoc('deleteInspectionPhotos', id); } },

    { key: 'devices', label: 'Inventory Devices', area: 'warehouse',
      read: () => warehouseDevices, write: l => { warehouseDevices = l; },
      bulk: 'saveDevices', deleteOne: id => window.cloud.deleteDevice(id) },

    { key: 'stockItems', label: 'Stock Items', area: 'warehouse',
      read: () => stockLedger, write: l => { stockLedger = l; },
      bulk: 'saveStockItems', deleteOne: id => window.cloud.deleteStockItem(id) },

    { key: 'vehicles', label: 'Vehicles', area: 'warehouse',
      read: () => vehicles, write: l => { vehicles = l; },
      bulk: 'saveVehicles', deleteOne: id => window.cloud.deleteVehicle(id) },

    { key: 'fuelLogs', label: 'Fuel Records', area: 'warehouse',
      read: () => fuelLogs, write: l => { fuelLogs = l; },
      bulk: 'saveFuelLogs',
      deleteOne: (id, r) => { window.cloud.deleteFuelLog(id); if (r && r.hasPhoto) { _fuelPhotoCache.delete(id); _dropPhotoDoc('deleteFuelPhoto', id); } } }
];

// Two collections are left out on purpose, and the UI says so rather than
// leaving it a mystery:
//   users   — role and per-area access. Restoring it would rewrite people's
//             permissions from a file. Accounts belong on the Users page.
//   history — the audit log has its own Export button, reads the whole
//             collection, and has no size limit worth putting in every backup.
const BACKUP_EXCLUDED = [
    { label: 'Accounts & Access', why: 'managed on the Users page, not through a file' },
    { label: 'Audit History', why: 'has its own Export button on the History page' }
];

async function exportBackup() {
    // A backup is a full-dataset export, so it needs the export privilege AND
    // read access to every area it contains — otherwise it is a way around
    // both the CSV privilege and per-area 'none'.
    if (!canCsv('export')) return;
    // A backup of one group is a trap: restoring it with REPLACE deletes the
    // other group.
    if (isUnitScoped()) { showToast('Backup is for accounts that see all unit groups', 'warning'); return; }
    const blocked = ['editUnits', 'implements', 'damage', 'licenseStock']
        .filter(a => !hasAccess(a, 'view'));
    if (blocked.length) {
        showToast('Backup needs access to all data — you do not have full access', 'warning');
        return;
    }

    const includeFiles = globalData.some(u => u.attachments && u.attachments.length > 0)
        && confirm('Include attached files in the backup? (files can be large)');

    const payload = {
        version: 4,
        exportedAt: new Date().toISOString(),
        count: globalData.length,
        units: globalData,
        // Everything else comes from BACKUP_PARTS, so a new collection is one
        // row there instead of an edit in two places that drift apart.
        omitted: []
    };
    const included = [];

    showLoading(true);
    try {
        for (const part of BACKUP_PARTS) {
            // A backup must not become a way around per-area 'none'. Skip what
            // this account may not read — and record it, so the file says what
            // it is missing instead of looking complete.
            if (!(part.canView ? part.canView() : hasAccess(part.area, 'view'))) {
                payload.omitted.push({ key: part.key, label: part.label, why: 'no access' });
                continue;
            }
            let rows = part.read() || [];
            // Not loaded yet: what is in memory is a guess (often empty), and
            // a REPLACE restore of this file would delete the real thing.
            if (cloudInitialized && !part.fullRead && !_loadedParts.has(part.key)) {
                payload.omitted.push({ key: part.key, label: part.label, why: 'not loaded yet — try again shortly' });
                continue;
            }
            if (part.fullRead && window.cloud?.isReady) {
                try {
                    const all = await part.fullRead();
                    if (Array.isArray(all)) rows = all;
                } catch (err) {
                    // Better a short backup that admits it than a short backup
                    // that does not.
                    console.warn(`[backup] ${part.key} full read failed:`, err);
                    payload.omitted.push({ key: part.key, label: part.label, why: 'could not be read in full' });
                }
            }
            payload[part.key] = rows;
            included.push(`${rows.length} ${part.label.toLowerCase()}`);
        }
    } finally {
        showLoading(false);
    }

    // ---- Photos and letters ----
    const photoJobs = [];
    BACKUP_PHOTO_KINDS.forEach(k => {
        (Array.isArray(payload[k.part]) ? payload[k.part] : []).forEach(r => {
            if (r && r.id && k.has(r)) photoJobs.push({ k, id: r.id });
        });
    });
    const kindsWith = BACKUP_PHOTO_KINDS.filter(k => photoJobs.some(j => j.k === k));
    const cloudCanRead = window.cloud?.isReady && kindsWith.every(k => typeof window.cloud[k.get] === 'function');
    const includePhotos = photoJobs.length > 0 && cloudCanRead
        && confirm(`Include ${photoJobs.length} photo & letter documents (${kindsWith.map(k => k.label.toLowerCase()).join(', ')})?\n\n`
            + 'Without them, the backup keeps only the records — the photos cannot be restored from this file. '
            + 'With them, the file can be much larger and needs signal to download.');
    if (includePhotos) {
        showLoading(true);
        const failed = new Map();
        try {
            kindsWith.forEach(k => { payload[k.key] = {}; });
            await _mapLimit(photoJobs, 4, async ({ k, id }) => {
                try {
                    const v = await window.cloud[k.get](id);
                    if (k.present(v)) payload[k.key][id] = v;
                } catch (err) {
                    console.warn(`[backup] ${k.get}(${id}) gagal:`, err);
                    failed.set(k, (failed.get(k) || 0) + 1);
                }
            });
        } finally {
            showLoading(false);
        }
        kindsWith.forEach(k => {
            const n = Object.keys(payload[k.key]).length;
            included.push(`${n} ${k.label.toLowerCase()}`);
            if (failed.get(k)) payload.omitted.push({ key: k.key, label: k.label, why: `${failed.get(k)} failed to download` });
        });
    } else {
        kindsWith.forEach(k => payload.omitted.push({ key: k.key, label: k.label,
            why: cloudCanRead ? 'not included' : 'can only be downloaded while online' }));
    }

    if (includeFiles) {
        const attachArr = [];
        for (const unit of globalData) {
            if (!unit.attachments || unit.attachments.length === 0) continue;
            for (const meta of unit.attachments) {
                try {
                    const rec = await attachDbGet(meta.id);
                    if (rec && rec.blob) {
                        const b64 = await new Promise((resolve, reject) => {
                            const reader = new FileReader();
                            reader.onload = () => resolve(reader.result);
                            reader.onerror = () => reject(reader.error);
                            reader.readAsDataURL(rec.blob instanceof Blob ? rec.blob : new Blob([rec.blob], { type: rec.type }));
                        });
                        attachArr.push({ id: meta.id, unitId: unit.id, name: meta.name, type: meta.type, size: meta.size, dataB64: b64 });
                    }
                } catch (e) { /* skip unavailable */ }
            }
        }
        if (attachArr.length > 0) payload.attachments = attachArr;
    }

    const blob = new Blob([JSON.stringify(payload, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `tractor_backup_${toISODate()}.json`;
    a.click();
    URL.revokeObjectURL(url);
    // Say what it holds AND what it does not. The old toast named the four
    // collections it saved, which read as a complete list when eleven others
    // were missing.
    const missing = payload.omitted.map(o => o.label);
    showToast(`Backup saved: ${globalData.length} units, ${included.join(', ')}`
        + (missing.length ? ` · NOT included: ${missing.join(', ')}` : ''),
        missing.length ? 'warning' : 'success');
}

// ---- localStorage usage guard ----
// Damage photos (base64) are the main storage driver; warn before the ~5MB
// quota is hit so the user can export a backup / prune old photos in time.
let _storageWarnedAt = 0;
let _autoBackupFailed = false;
const STORAGE_WARN_BYTES = 4.5 * 1024 * 1024;
const STORAGE_WARN_REPEAT_MS = 10 * 60 * 1000;

function estimateLocalStorageBytes() {
    let total = 0;
    try {
        for (let i = 0; i < localStorage.length; i++) {
            const k = localStorage.key(i);
            total += (k.length + (localStorage.getItem(k) || '').length) * 2; // UTF-16
        }
    } catch (e) { /* ignore */ }
    return total;
}

// Warns again every STORAGE_WARN_REPEAT_MS while the problem persists. It used
// to latch on a module-level flag, so a user who missed or dismissed the single
// toast got no further signal as writes began failing — and the toast is the
// only indication that anything is wrong until data stops saving.
function checkStorageUsage() {
    const used = estimateLocalStorageBytes();
    if (used <= STORAGE_WARN_BYTES) { _storageWarnedAt = 0; return; }
    const now = Date.now();
    if (_storageWarnedAt && now - _storageWarnedAt < STORAGE_WARN_REPEAT_MS) return;
    _storageWarnedAt = now;
    showToast(`Browser storage almost full (${(used / 1048576).toFixed(1)} MB used) — export a backup now`, 'warning');
}

function triggerRestore() {
    document.getElementById('restoreFileInput').click();
}

// Merge or replace one auxiliary collection from a backup file, mirroring the
// mode chosen for units.
//
// MERGE keeps every record that exists now exactly as it is and only ADDS
// what the file has and the app does not — what the dialog promises. The
// backup copy used to win, so restoring a three-week-old file to recover one
// deleted record quietly undid every approval, re-activated members and moved
// devices back, and wrote nothing to History.
// REPLACE returns the file's records; they are then written WHOLE (see
// _replaceInCloud), not merged into what is there.
function _restoreCollection(items, current, merge) {
    const valid = items.filter(r => r && r.id);
    if (!merge) return valid;
    const have = new Set(current.map(r => r.id));
    return current.concat(valid.filter(r => !have.has(r.id)));
}

// The records of `items` that MERGE adds (ids not present in `current`).
function _restoreAdded(items, current) {
    const have = new Set(current.map(r => r && r.id));
    return items.filter(r => r && r.id && !have.has(r.id));
}

// A REPLACE writes each record as the whole document. The bulk savers upsert
// with merge:true — right for an edit, wrong here: a field added after the
// backup survived the "replace", leaving a record half backup, half today.
// Falls back to the merging saver only when firebase-init.js is an older copy.
function _replaceInCloud(key, rows, fallbackBulk) {
    const replace = window.cloud && typeof window.cloud.replaceDocs === 'function'
        ? list => window.cloud.replaceDocs(key, list) : null;
    return (replace || fallbackBulk)(rows);
}

// Master Lists come back one list at a time, each under its own edit right.
// MERGE adds the file's entries a list does not have yet (same spelling rule
// as the list itself: case, spacing and punctuation do not make a new entry).
// REPLACE loads the file's list — except that an empty list in the file never
// wipes a filled one, the same guard every other collection has.
const _entries = n => `${n} ${n === 1 ? 'entry' : 'entries'}`;
async function _restoreMasterLists(rows, merge) {
    const done = [], skipped = [];
    let total = 0;
    for (const kind of MASTER_KINDS) {
        const row = (rows || []).find(r => r && r.id === kind);
        if (!row || !Array.isArray(row.values)) continue;
        const fileVals = [...new Set(row.values.map(_toolNorm).filter(Boolean))].slice(0, 500);
        if (!canEditMasterList(kind)) { skipped.push(MASTER_DEF[kind].plural); continue; }
        const cur = masterLists[kind] || [];
        let next;
        if (merge) {
            next = cur.slice();
            fileVals.forEach(v => { if (!next.some(x => x.toLowerCase() === v.toLowerCase() || (_simKey(x) && _simKey(x) === _simKey(v)))) next.push(v); });
        } else {
            next = fileVals.length || !cur.length ? fileVals : cur;
        }
        next = [...new Set(next)].sort((a, b) => a.localeCompare(b)).slice(0, 500);
        const changed = JSON.stringify(next) !== JSON.stringify(cur);
        total += next.length;
        if (!changed) { done.push(`${MASTER_DEF[kind].plural} unchanged`); continue; }
        masterLists = { ...masterLists, [kind]: next };
        const fn = cloudFn('saveMasterList');
        if (fn && window.cloud?.isReady && !suppressCloudWrites) {
            fn(kind, next, (currentUser && currentUser.email) || '').catch(err => cloudWriteFailed(err, {
                what: `${MASTER_DEF[kind].label.toLowerCase()} list (restore)`, label: `[Master] ${MASTER_DEF[kind].plural}`
            }));
        }
        logEvent({ action: 'restore', unitName: `[Restore] ${MASTER_DEF[kind].plural}`, field: merge ? 'MERGE' : 'REPLACE',
                   before: _entries(cur.length), after: _entries(next.length) });
        done.push(`${MASTER_DEF[kind].plural} ${cur.length} → ${next.length}`);
    }
    populateMasterDatalists();
    if (!done.length && skipped.length) {
        return { label: 'Master Lists', count: '—', note: `skipped — you do not have edit rights (${skipped.join(', ')})` };
    }
    return { label: 'Master Lists', count: total,
             note: `${merge ? 'merged' : 'replaced'} — ${done.join(', ') || 'nothing in the file'}`
                 + (skipped.length ? ` · skipped (no edit rights): ${skipped.join(', ')}` : '') };
}

// One History row per collection a restore touched, with what it did — a
// restore can rewrite thousands of records and used to leave no trace.
function _logRestore(label, merge, counts) {
    // A collection the file holds no rows of, and that the restore left as it
    // was, is not worth a History row.
    if (!Object.values(counts).some(n => n > 0)) return;
    const bits = merge
        ? [`${counts.added} added`, `${counts.kept} kept as they are`]
        : [`${counts.written} written from the file`, `${counts.deleted} deleted`];
    logEvent({ action: 'restore', unitName: `[Restore] ${label}`, field: merge ? 'MERGE' : 'REPLACE', before: '', after: bits.join(', ') });
}

// The bulk cloud savers only upsert, so a REPLACE restore would leave the
// dropped documents alive in Firestore and the next live snapshot would put
// them straight back — silently undoing the restore. Delete what the restore
// removed, one id at a time (these collections have no bulk delete).
function _cloudDeleteRemoved(previous, kept, deleteOne) {
    if (suppressCloudWrites || !window.cloud?.isReady) return;
    const keptIds = new Set(kept.map(r => r.id));
    previous.forEach(r => { if (r.id && !keptIds.has(r.id)) deleteOne(r.id, r); });
}

// REPLACE keeps a record whose copy in the file has no photo of a kind the
// current one has — a backup from before that photo was taken. The record
// loses the flag, so drop the photo document as well; left behind, nothing
// would ever list or delete it. Only kinds that name a delete ('del').
function _dropUnflaggedPhotos(partKey, before, next) {
    if (suppressCloudWrites || !window.cloud?.isReady) return;
    const nextById = new Map(next.filter(r => r && r.id).map(r => [r.id, r]));
    BACKUP_PHOTO_KINDS.filter(k => k.part === partKey && k.del).forEach(k => {
        before.forEach(r => {
            const n = r && r.id ? nextById.get(r.id) : null;
            if (!n || !k.has(r) || k.has(n)) return;
            k.cache().delete(r.id);
            _dropPhotoDoc(k.del, r.id);
        });
    });
}

// A record's photo or letters live in a document of their own, keyed by the
// record's id. Deleting only the record left that document behind for good —
// nothing lists those collections, so nothing would ever find it again.
function _dropPhotoDoc(fnName, id) {
    const fn = window.cloud && window.cloud[fnName];
    if (typeof fn !== 'function') return;
    Promise.resolve(fn.call(window.cloud, id)).catch(err =>
        console.warn(`[photo-doc] ${fnName}(${id}) failed:`, err));
}

// Photos and letters, one document per record, fetched one at a time — which
// is why they are optional in a backup and the file says so when they are not
// in it. 'has' is true only for a record whose image lives OUTSIDE the record
// (an inline one already travels with the record itself).
const BACKUP_PHOTO_KINDS = [
    { key: 'damagePhotos', label: 'Damage photos', part: 'damages', area: 'damage',
      has: r => !r.photo && !!r.hasPhoto, get: 'getDamagePhoto', save: 'saveDamagePhoto', del: 'deleteDamagePhoto',
      present: v => typeof v === 'string' && v.length > 0, cache: () => _dmgPhotoCache },
    { key: 'damageAfterPhotos', label: 'Damage photos after repair', part: 'damages', area: 'damage',
      has: r => damageHasAfterPhoto(r), get: 'getDamageAfterPhoto', save: 'saveDamageAfterPhoto', del: 'deleteDamageAfterPhoto',
      present: v => typeof v === 'string' && v.length > 0, cache: () => _dmgAfterCache },
    { key: 'workLogPhotos', label: 'Daily report photos', part: 'workLogs', area: 'teamLog',
      has: r => !(Array.isArray(r.photos) && r.photos.length) && Number(r.photoCount) > 0,
      get: 'getWorkLogPhotos', save: 'saveWorkLogPhotos',
      present: v => Array.isArray(v) && v.length > 0, cache: () => _wlPhotoCache },
    { key: 'leaveDocs', label: 'Leave / sick letters', part: 'leaveRequests', area: 'teamLog',
      has: r => leaveDocCount(r) > 0, get: 'getTeamDocs', save: 'saveTeamDocs',
      present: v => Array.isArray(v) && v.length > 0, cache: () => _leaveDocCache },
    { key: 'fuelPhotos', label: 'Fuel receipt photos', part: 'fuelLogs', area: 'warehouse',
      has: r => !!(r && r.hasPhoto), get: 'getFuelPhoto', save: 'saveFuelPhoto', del: 'deleteFuelPhoto',
      present: v => typeof v === 'string' && v.length > 0, cache: () => _fuelPhotoCache },
    { key: 'inspectionPhotos', label: 'Inspection photos', part: 'inspections', area: 'inspection',
      has: r => Number(r.photoCount) > 0, get: 'getInspectionPhotos', save: 'saveInspectionPhotos',
      present: v => !!v && typeof v === 'object' && !Array.isArray(v) && Object.keys(v).length > 0,
      cache: () => _insPhotoCache }
];

// Backups from before photos had their own collections carry them INSIDE the
// records. Restored as they are, they bring back what the split fixed — every
// device downloading every photo, localStorage filling up — and the one-shot
// migration has already set its flag and will not run again. Moved here into
// the file's photo maps, they go out through the same path as a v5 backup.
function splitInlineBackupPhotos(data) {
    if (Array.isArray(data.damages)) {
        data.damages = data.damages.map(r => {
            if (!r || !r.id || typeof r.photo !== 'string' || !r.photo) return r;
            data.damagePhotos = data.damagePhotos && typeof data.damagePhotos === 'object' ? data.damagePhotos : {};
            if (!data.damagePhotos[r.id]) data.damagePhotos[r.id] = r.photo;
            return { ...r, photo: '', hasPhoto: true };
        });
    }
    if (Array.isArray(data.workLogs)) {
        data.workLogs = data.workLogs.map(r => {
            if (!r || !r.id || !Array.isArray(r.photos) || !r.photos.length) return r;
            data.workLogPhotos = data.workLogPhotos && typeof data.workLogPhotos === 'object' ? data.workLogPhotos : {};
            if (!data.workLogPhotos[r.id]) data.workLogPhotos[r.id] = r.photos.slice();
            return { ...r, photos: [], photoCount: r.photos.length };
        });
    }
    return data;
}

// Runs fn over items, at most n at a time. Photos are fetched one document per
// record; firing hundreds of getDoc calls at once only makes them all slow.
async function _mapLimit(items, n, fn) {
    const out = new Array(items.length);
    let next = 0;
    const worker = async () => { while (next < items.length) { const i = next++; out[i] = await fn(items[i], i); } };
    await Promise.all(Array.from({ length: Math.min(n, items.length) }, worker));
    return out;
}

// A restore replaces FOUR collections at once, so it needs edit rights on all
// of them — gating on editUnits alone let a units-only editor wipe implements,
// damage records and licence stock.
function importBackup(file) {
    if (!canCsv('full')) return;
    if (isUnitScoped()) { showToast('Restore is for accounts that see all unit groups', 'warning'); return; }
    // Units are non-negotiable: every backup carries them and the units path
    // below writes unconditionally. The rest are checked per collection as
    // they are restored, so someone with partial rights restores what they may
    // and is told plainly what was left alone.
    if (!hasAccess('editUnits', 'edit')) {
        showToast('Restore needs edit rights on Unit data', 'warning');
        return;
    }
    const reader = new FileReader();
    reader.onload = async e => {
        try {
            const data = JSON.parse(e.target.result);
            if (!data || !Array.isArray(data.units)) {
                showToast('Invalid backup file', 'error');
                return;
            }
            splitInlineBackupPhotos(data);
            const merge = confirm(
                `Backup contains ${data.units.length} units.\n\n` +
                `OK     = MERGE (add only what is missing — every record that exists now is kept exactly as it is)\n` +
                `Cancel = REPLACE (delete current data, load the backup)\n\n` +
                `This choice applies to ALL collections in the file, not just units.`
            );
            if (merge) {
                // By id as well as serial number: a unit whose SN was corrected
                // since the backup has the same id and an old SN, and used to
                // be added again on top of the live one.
                const haveIds = new Set(globalData.map(u => u.id));
                const fresh = data.units.filter(u => !(u && u.id && haveIds.has(u.id)));
                const result = addUnits(fresh);
                const kept = data.units.length - result.added;
                _logRestore('Units', true, { added: result.added, kept });
                showToast(`Backup merged: ${result.added} unit(s) added, ${kept} already there and kept as they are`, 'success');
            } else {
                if (_refuseCrossGroupRestore(data.units)) return;
                const nHeavy = data.units.filter(isHeavy).length;
                if (!confirm(`This will DELETE all ${globalData.length} current units and replace them with the backup contents`
                    + (nHeavy ? ` (including ${nHeavy} ${UNIT_GROUPS.heavy.shortLabel} units)` : '') + `. Continue?`)) return;
                // Mirror the replace to the cloud, otherwise the next units
                // snapshot overwrites localStorage and silently undoes the
                // whole restore (and deleted units come back).
                const previousIds = globalData.map(u => u.id);
                globalData = data.units.map(u => ({ ...u, id: u.id || generateId(), unitGroup: storedUnitGroup(u) }));
                const keptIds = new Set(globalData.map(u => u.id));
                saveToStorage(globalData);
                const dropped = previousIds.filter(id => !keptIds.has(id));
                cloudDeleteUnits(dropped);
                if (!suppressCloudWrites && window.cloud?.isReady && canWriteUnits('restore')) {
                    _replaceInCloud('units', globalData, list => window.cloud.saveUnits(list))
                        .catch(err => cloudWriteFailed(err, { what: 'units (restore)', label: '[Units] restore', resync: resyncUnits }));
                }
                logEvent({ action: 'restore', unitName: '-', after: `${data.units.length} units restored from backup` });
                _logRestore('Units', false, { written: globalData.length, deleted: dropped.length });
                recordChange({ type: 'restored', detail: `${data.units.length} units restored from backup` });
                showToast(`${data.units.length} units restored from backup`, 'success');
            }

            // Every other collection goes through BACKUP_PARTS, in the same
            // mode (merge / replace) the user chose for units. The report
            // afterwards names three different outcomes, and the third is the
            // one that used to be silent: a collection that is simply NOT IN
            // THE FILE. A v3 backup has no Team or Warehouse data at all, and
            // the person restoring it has to know that rather than assume the
            // restore covered everything.
            const report = [];
            // Records each collection actually wrote — photos are restored only
            // for these (a MERGE keeps an existing record's photos too).
            const writtenIds = new Map();
            for (const part of BACKUP_PARTS) {
                let rows = data[part.key];
                if (!Array.isArray(rows)) {
                    report.push({ label: part.label, count: '—', note: 'not in this file' });
                    continue;
                }
                // A collection with its own shape (one document per list).
                if (part.restore) {
                    report.push(await part.restore(rows, merge));
                    continue;
                }
                // Rows the server would refuse sink the whole batch they ride
                // in; leave them out and say how many.
                if (part.prepare) rows = rows.map(part.prepare);
                let refused = 0;
                if (part.accept) {
                    const ok = rows.filter(r => r && part.accept(r));
                    refused = rows.length - ok.length;
                    rows = ok;
                }
                if (!hasAccess(part.area, 'edit')) {
                    report.push({ label: part.label, count: rows.length, note: 'skipped — you do not have edit rights' });
                    continue;
                }
                const bulk = cloudFn(part.bulk);
                if (window.cloud?.isReady && !bulk) {
                    report.push({ label: part.label, count: rows.length, note: 'skipped — an old version is still running, reload the page' });
                    continue;
                }

                // REPLACE has to be computed against what the SERVER holds, not
                // against the in-memory array: shifts only keep the subscribed
                // window, so diffing the array would delete every shift outside
                // it. fullRead gives the real "before".
                let before = part.read() || [];
                if (!merge && part.fullRead && window.cloud?.isReady) {
                    try {
                        const all = await part.fullRead();
                        if (Array.isArray(all)) before = all;
                    } catch (err) {
                        // Without a trustworthy "before" a REPLACE could delete
                        // rows it cannot see. Upsert only, and say so.
                        console.warn(`[restore] ${part.key} full read failed:`, err);
                        report.push({ label: part.label, count: rows.length,
                                      note: 'added only — the old list could not be read, nothing was deleted' });
                        const cur = part.read() || [];
                        const added = _restoreAdded(rows, cur);
                        part.write(cur.concat(added));
                        if (part.saveLocal) part.saveLocal();
                        if (bulk && added.length) bulk(added).catch(e => cloudWriteFailed(e, {
                            what: `${part.label.toLowerCase()} (restore)`,
                            label: `[${part.label}] restore`, resync: part.resync }));
                        writtenIds.set(part.key, new Set(added.map(r => r.id)));
                        _logRestore(part.label, true, { added: added.length, kept: rows.length - added.length });
                        continue;
                    }
                }

                // A file that lists a collection as EMPTY never wipes it: that
                // is far more often a backup taken before the data had loaded
                // than a real wish to delete everything.
                if (!merge && rows.length === 0 && before.length > 0) {
                    report.push({ label: part.label, count: 0,
                                  note: `skipped — the file has 0 rows; the ${before.length} existing ones were not deleted` });
                    continue;
                }
                const next = _restoreCollection(rows, before, merge);
                // MERGE sends only what it adds; re-sending every existing
                // record from this device's copy would overwrite whatever
                // another device changed since it loaded.
                const toWrite = merge ? _restoreAdded(rows, before) : next;
                part.write(next);
                if (part.saveLocal) part.saveLocal();
                const nextIds = new Set(next.map(x => x.id));
                const deleted = merge ? 0 : before.filter(r => r.id && !nextIds.has(r.id)).length;
                _cloudDeleteRemoved(before, next, part.deleteOne);
                if (!merge) _dropUnflaggedPhotos(part.key, before, next);
                if (bulk && toWrite.length) {
                    (merge ? bulk(toWrite) : _replaceInCloud(part.key, toWrite, bulk)).catch(err => cloudWriteFailed(err, {
                        what: `${part.label.toLowerCase()} (restore)`,
                        label: `[${part.label}] restore`,
                        resync: part.resync
                    }));
                }
                writtenIds.set(part.key, new Set(toWrite.map(r => r.id)));
                const counts = merge ? { added: toWrite.length, kept: rows.length - toWrite.length } : { written: next.length, deleted };
                _logRestore(part.label, merge, counts);
                const refusedNote = refused ? ` · ${refused} invalid row(s) left out` : '';
                report.push({ label: part.label, count: rows.length + refused,
                    note: (merge ? `merged — ${counts.added} added, ${counts.kept} kept as they are` : 'replaced') + refusedNote });
            }
            // Photos and letters, for the records this restore actually wrote.
            for (const k of BACKUP_PHOTO_KINDS) {
                const rows = data[k.key];
                const partLabel = (BACKUP_PARTS.find(p => p.key === k.part) || {}).label;
                const partDone = report.some(r => r.label === partLabel && /^(merged|replaced)/.test(r.note));
                const recs = Array.isArray(data[k.part]) ? data[k.part] : [];
                if (!rows || typeof rows !== 'object') {
                    // Only worth a line when the file's records expected one.
                    if (partDone && recs.some(r => r && k.has(r))) {
                        report.push({ label: k.label, count: '—', note: 'not in this file — the records are there, the photos are not' });
                    }
                    continue;
                }
                const wrote = writtenIds.get(k.part);
                const ids = Object.keys(rows).filter(id => k.present(rows[id]) && recs.some(r => r && r.id === id)
                    && (!wrote || wrote.has(id)));
                if (!partDone) {
                    report.push({ label: k.label, count: ids.length, note: 'skipped — the records were not restored' });
                    continue;
                }
                const save = window.cloud && window.cloud[k.save];
                if (window.cloud?.isReady && typeof save !== 'function') {
                    report.push({ label: k.label, count: ids.length, note: 'skipped — an old version is still running, reload the page' });
                    continue;
                }
                ids.forEach(id => k.cache().set(id, rows[id]));
                let failedN = 0;
                if (window.cloud?.isReady && !suppressCloudWrites) {
                    await _mapLimit(ids, 4, id => Promise.resolve(save.call(window.cloud, id, rows[id]))
                        .catch(err => { failedN++; console.warn(`[restore] ${k.save}(${id}) gagal:`, err); }));
                }
                report.push({ label: k.label, count: ids.length,
                    note: failedN ? `${failedN} failed to send` : (merge ? 'merged' : 'replaced') });
            }
            showRestoreReport(report, data.version || 0, merge);

            if (Array.isArray(data.attachments) && data.attachments.length > 0) {
                let restored = 0;
                for (const att of data.attachments) {
                    try {
                        const parts = att.dataB64.split(',');
                        const byteStr = atob(parts.length > 1 ? parts[1] : parts[0]);
                        const bytes = new Uint8Array(byteStr.length);
                        for (let i = 0; i < byteStr.length; i++) bytes[i] = byteStr.charCodeAt(i);
                        const blob = new Blob([bytes], { type: att.type });
                        await attachDbPut({ id: att.id, unitId: att.unitId, name: att.name, type: att.type, size: att.size, addedAt: new Date().toISOString(), blob });
                        restored++;
                    } catch (err) { /* skip invalid */ }
                }
                if (restored > 0) showToast(`${restored} attachment(s) restored`, 'success');
            }

            // Refresh every surface, not just the units table — a restore can
            // be triggered from any view and replaces four collections.
            // Every surface, not just units: a restore can be triggered from
            // any view and now replaces up to eleven collections.
            renderEditTable();
            renderImplementsTable();
            populateLicenseTypeList();
            renderLicenseSummary();
            renderLicenseStockTable();
            renderDamageTable();
            renderUserCategoryOptions();
            renderDamageComponentsList();
            if (typeof renderTeamView === 'function') renderTeamView();
            if (typeof renderDeviceTable === 'function') renderDeviceTable();
            if (typeof renderStockView === 'function') renderStockView();
            scheduleDecisionRefresh();
            filteredData = scopeDashUnits();
            updateDashboard(filteredData);
        } catch (err) {
            showToast('Failed to read backup: ' + err.message, 'error');
        }
    };
    reader.readAsText(file);
}

// ============================================================
// CHANGE ALERT SYSTEM
// ============================================================

function recordChange(change) {
    const changes = JSON.parse(sessionStorage.getItem(PENDING_CHANGES_KEY) || '[]');
    changes.push({ ...change, timestamp: Date.now() });
    sessionStorage.setItem(PENDING_CHANGES_KEY, JSON.stringify(changes));
}

function checkPendingAlerts() {
    const changes = JSON.parse(sessionStorage.getItem(PENDING_CHANGES_KEY) || '[]');
    if (changes.length === 0) return;

    const summary = changes.map(c => c.detail).join('; ');
    document.getElementById('changeBannerText').textContent = `Data updated: ${summary}`;
    document.getElementById('changeBanner').classList.add('show');
    sessionStorage.removeItem(PENDING_CHANGES_KEY);
}

function dismissBanner() {
    document.getElementById('changeBanner').classList.remove('show');
}

// ============================================================
// DOWNTIME TRACKING
// ============================================================

function trackStatusChange(unit, oldStatus, newStatus) {
    const wasGood = isGood(oldStatus);
    const willBeGood = isGood(newStatus);
    if (wasGood && !willBeGood) {
        unit.breakdownStartedAt = Date.now();
    } else if (!wasGood && willBeGood && unit.breakdownStartedAt) {
        const start = unit.breakdownStartedAt;
        const end = Date.now();
        if (!unit.downtimeHistory) unit.downtimeHistory = [];
        unit.downtimeHistory.push({ start, end, durationMs: end - start });
        unit.breakdownStartedAt = null;
        unit.breakdownReason = '';
    }
    // Back to Good by any path: no damage record is behind it any more.
    if (willBeGood && unit.breakdownDamageId) unit.breakdownDamageId = '';
}

// Takes the units to measure; the default (every unit) keeps the old call
// sites — the email report and the decision inbox — fleet-wide.
function computeDowntimeStats(units) {
    const list = units || globalData;
    const now = Date.now();
    const monthStart = new Date();
    monthStart.setDate(1); monthStart.setHours(0, 0, 0, 0);
    const monthStartMs = monthStart.getTime();

    let totalDowntimeMs = 0;
    let totalFailures = 0;
    let totalMonthDowntime = 0;
    const perUnit = [];

    // How far back the downtime record actually goes. MTBF used to divide
    // all-time failures by a FIXED 30 days per unit, so the denominator stood
    // still while the numerator kept growing: an unchanged fleet's MTBF fell
    // from ~30 days to ~2 days over a year, and hit 0 once total downtime
    // passed 30 days per unit. Measure the real observation window instead.
    let earliestEventMs = Infinity;
    list.forEach(u => {
        (u.downtimeHistory || []).forEach(iv => {
            if (typeof iv.start === 'number' && iv.start < earliestEventMs) earliestEventMs = iv.start;
        });
        if (typeof u.breakdownStartedAt === 'number' && u.breakdownStartedAt < earliestEventMs) {
            earliestEventMs = u.breakdownStartedAt;
        }
    });

    list.forEach(u => {
        const history = u.downtimeHistory || [];
        let unitDowntime = 0;
        history.forEach(iv => {
            totalDowntimeMs += iv.durationMs;
            unitDowntime += iv.durationMs;
            totalFailures++;
            if (iv.end >= monthStartMs) {
                totalMonthDowntime += Math.min(iv.durationMs, iv.end - Math.max(iv.start, monthStartMs));
            }
        });
        if (u.breakdownStartedAt) {
            const ongoing = now - u.breakdownStartedAt;
            unitDowntime += ongoing;
            totalDowntimeMs += ongoing;
            totalFailures++;
            const effStart = Math.max(u.breakdownStartedAt, monthStartMs);
            if (now > effStart) totalMonthDowntime += (now - effStart);
        }
        if (unitDowntime > 0) perUnit.push({ id: u.id, name: u.name, downtime: unitDowntime });
    });

    const mttr = totalFailures > 0 ? totalDowntimeMs / totalFailures : 0;

    // Observed window per unit, floored at a day so a fleet whose first
    // breakdown happened minutes ago can't produce an absurd MTBF.
    const DAY_MS = 24 * 3600 * 1000;
    const windowMs = earliestEventMs === Infinity
        ? 30 * DAY_MS                       // nothing recorded yet
        : Math.max(DAY_MS, now - earliestEventMs);
    // When both groups are in the list, each group is credited with its OWN
    // observation window; one old tractor breakdown must not stretch the
    // window of excavators registered last week. A single group uses the
    // original expression verbatim.
    const fleetOperatingMs = (hasHeavyUnits(list) && hasTractorUnits(list))
        ? _groupOperatingMs(list, now)
        : Math.max(1, list.length) * windowMs;
    const uptimeMs = Math.max(0, fleetOperatingMs - totalDowntimeMs);
    const mtbf = totalFailures > 0 ? uptimeMs / totalFailures : 0;

    perUnit.sort((a, b) => b.downtime - a.downtime);
    return {
        mtbf, mttr, totalMonthDowntime, totalFailures,
        observedMs: earliestEventMs === Infinity ? 0 : now - earliestEventMs,
        topOffenders: perUnit.slice(0, 5), topTen: perUnit.slice(0, 10)
    };
}

function _groupOperatingMs(list, now) {
    const DAY_MS = 24 * 3600 * 1000;
    return UNIT_GROUP_KEYS.reduce((sum, g) => {
        const members = list.filter(u => unitGroupOf(u) === g);
        if (!members.length) return sum;
        let earliest = Infinity;
        members.forEach(u => {
            (u.downtimeHistory || []).forEach(iv => { if (typeof iv.start === 'number' && iv.start < earliest) earliest = iv.start; });
            if (typeof u.breakdownStartedAt === 'number' && u.breakdownStartedAt < earliest) earliest = u.breakdownStartedAt;
        });
        const win = earliest === Infinity ? 30 * DAY_MS : Math.max(DAY_MS, now - earliest);
        return sum + members.length * win;
    }, 0);
}

// Hours in breakdown per calendar month, oldest first, for the units given.
// Each recorded interval (and a breakdown still running) is split at month
// boundaries, so a breakdown from 28 Sep to 3 Oct counts in both months; a
// failure counts in the month it started.
function downtimeByMonth(units, count) {
    const now = Date.now();
    const base = new Date(); base.setDate(1); base.setHours(0, 0, 0, 0);
    const months = [];
    for (let i = (count || 6) - 1; i >= 0; i--) {
        const s = new Date(base.getFullYear(), base.getMonth() - i, 1);
        const e = new Date(base.getFullYear(), base.getMonth() - i + 1, 1);
        months.push({ start: s.getTime(), end: Math.min(e.getTime(), now), ms: 0, failures: 0,
            label: s.toLocaleDateString('en-GB', { month: 'long' }).slice(0, 3),
            name: s.toLocaleDateString('en-GB', { month: 'long' }) });
    }
    const add = (a, b) => {
        months.forEach(m => { const o = Math.min(b, m.end) - Math.max(a, m.start); if (o > 0) m.ms += o; });
        const m = months.find(x => a >= x.start && a < x.end);
        if (m) m.failures++;
    };
    (units || []).forEach(u => {
        (u.downtimeHistory || []).forEach(iv => {
            const end = typeof iv.end === 'number' ? iv.end : null;
            const start = typeof iv.start === 'number' ? iv.start
                : (end != null && typeof iv.durationMs === 'number' ? end - iv.durationMs : null);
            if (start != null && end != null && end > start) add(start, end);
        });
        if (typeof u.breakdownStartedAt === 'number' && u.breakdownStartedAt > 0 && u.breakdownStartedAt < now) add(u.breakdownStartedAt, now);
    });
    return months;
}
function _dashHours(ms) {
    const h = ms / 3600000;
    return (h >= 10 || h === 0 ? Math.round(h) : h.toFixed(1)) + ' h';
}

// Downtime per month as plain bars: the current month in the accent colour,
// the five before it in a light tint.
function renderDowntimeTrend(months) {
    const host = document.getElementById('dashTrend');
    if (!host) return;
    const max = Math.max(0, ...months.map(m => m.ms));
    if (!max) { host.innerHTML = '<p class="dash-empty">No downtime recorded in the last six months.</p>'; return; }
    const label = 'Downtime per month: ' + months.map((m, i) =>
        `${m.name}${i === months.length - 1 ? ' so far' : ''} ${_dashHours(m.ms)}`).join(', ');
    host.innerHTML = `
        <div class="dash-trend__bars" role="img" aria-label="${escapeHtml(label)}">${months.map((m, i) => `
            <div class="dash-trend__col${i === months.length - 1 ? ' dash-trend__col--now' : ''}">
                <span class="dash-trend__val">${_dashHours(m.ms)}</span>
                <span class="dash-trend__bar" style="height:${m.ms ? Math.max(3, Math.round(m.ms / max * 150)) : 0}px"></span>
            </div>`).join('')}
        </div>
        <div class="dash-trend__labels" aria-hidden="true">${months.map((m, i) =>
            `<span${i === months.length - 1 ? ' class="dash-trend__now"' : ''}>${escapeHtml(m.label)}</span>`).join('')}</div>`;
}

function renderDowntimeKPIs(units) {
    const list = units || scopeDashUnits();
    const s = computeDowntimeStats(list);
    document.getElementById('kpiMTBF').textContent = formatDuration(s.mtbf);
    document.getElementById('kpiMTTR').textContent = formatDuration(s.mttr);
    // MTBF only means something against the period it was measured over.
    const mtbfSub = document.getElementById('kpiMTBFSub');
    if (mtbfSub) {
        mtbfSub.textContent = s.observedMs > 0
            ? `Average time between failures · observed over ${formatDuration(s.observedMs)}`
            : 'Average time between failures';
    }
    document.getElementById('kpiMonthDowntime').textContent = formatDuration(s.totalMonthDowntime);
    document.getElementById('kpiFailures').textContent = s.totalFailures;

    // This month, by name, for the Reliability card and the Overview strip.
    const months = downtimeByMonth(list, 6);
    const cur = months[months.length - 1];
    const today = new Date();
    const range = document.getElementById('dashMonthRange');
    if (range) range.textContent = `Time units spent in breakdown, 1–${today.getDate()} ${cur.name}`;
    const setText = (id, v) => { const el = document.getElementById(id); if (el) el.textContent = v; };
    setText('dashMonthKpiLabel', `Downtime in ${cur.name}`);
    setText('dashMonthDowntimeLabel', `Downtime in ${cur.name}`);
    setText('dashMonthDowntime', formatDuration(s.totalMonthDowntime));
    setText('dashMonthFailuresLabel', `Failures in ${cur.name}`);
    setText('dashMonthFailures', String(cur.failures));
    setText('dashMonthMTTR', formatDuration(s.mttr));
    setText('dashMonthMTBF', formatDuration(s.mtbf));
    renderDowntimeTrend(months);

    const listEl = document.getElementById('topOffendersList');
    if (!listEl) return;
    if (s.topOffenders.length === 0) {
        listEl.innerHTML = '<div class="top-offender top-offender--empty">No downtime recorded yet</div>';
    } else {
        // Ranked units with their site and number of failures, and the
        // downtime as a bar against the worst one.
        const max = s.topOffenders[0].downtime || 1;
        const byId = new Map(list.map(u => [u.id, u]));
        listEl.innerHTML = `
            <div class="dash-table-wrap">
            <table class="dash-table dash-worst__table">
                <thead><tr><th scope="col" class="dash-worst__rank">#</th><th scope="col">Unit</th><th scope="col" class="dash-worst__site">Site</th>
                    <th scope="col" class="dash-num dash-worst__fails">Failures</th><th scope="col" class="dash-worst__barcol">Downtime</th>
                    <th scope="col" class="dash-num">Time</th></tr></thead>
                <tbody>${s.topOffenders.map((o, i) => {
                    const u = byId.get(o.id) || {};
                    const fails = (u.downtimeHistory || []).length + (u.breakdownStartedAt ? 1 : 0);
                    return `
                    <tr>
                        <td class="dash-worst__rank">${i + 1}</td>
                        <td><button type="button" class="dash-unit" title="View unit profile"
                            onclick="showUnitProfile(${jsArg(o.id)})">${escapeHtml(o.name || 'Unnamed')}</button></td>
                        <td class="dash-muted dash-worst__site">${escapeHtml(u.site || '—')}</td>
                        <td class="dash-num dash-worst__fails">${fails}</td>
                        <td class="dash-worst__barcol"><div class="dash-bar dash-bar--bad" aria-hidden="true"><span style="width:${Math.round(o.downtime / max * 1000) / 10}%"></span></div></td>
                        <td class="dash-num">${formatDuration(o.downtime)}</td>
                    </tr>`;
                }).join('')}
                </tbody>
            </table>
            </div>`;
    }

    destroyChart('downtimeChart');
    if (s.topTen.length > 0) {
        charts.downtimeChart = makeChart('downtimeChart', {
            type: 'bar',
            data: {
                labels: s.topTen.map(u => u.name || 'Unnamed'),
                datasets: [{
                    data: s.topTen.map(u => +(u.downtime / 3600000).toFixed(2)),
                    backgroundColor: themeColor('--dot-bad', '#F04438'), borderRadius: 4, barPercentage: 0.6
                }]
            },
            options: {
                responsive: true, maintainAspectRatio: false, indexAxis: 'y',
                scales: {
                    x: { beginAtZero: true, title: { display: true, text: 'Downtime (hours)', color: dashChartInk(), font: dashChartFont(12) },
                         ticks: { color: dashChartInk(), font: dashChartFont(12) }, grid: dashChartGrid(), border: { display: false } },
                    y: { ticks: { color: dashChartInk(), font: dashChartFont(12) }, grid: { display: false } }
                },
                plugins: { legend: { display: false }, tooltip: { callbacks: { label: ctx => ` ${ctx.parsed.x}h` } } }
            }
        });
    }
}

// Chart text and grid in the design-F palette: Open Sans (--font-sans) in the
// secondary grey, hairline grid in --border.
function dashChartFont(size, weight) {
    const f = { size, family: themeColor('--font-sans', "'Open Sans', 'Segoe UI', sans-serif") };
    if (weight) f.weight = weight;
    return f;
}
function dashChartInk() { return themeColor('--text-secondary', '#475467'); }
function dashChartGrid() { return { color: themeColor('--border', '#EAECF0') }; }

// ============================================================
// DATA PROCESSING
// ============================================================

// The group column is ONLY "Unit Group". "Kelompok", "Group" and the like are
// ordinary column names in a plantation tractor sheet (a crew, a block), and
// must never be read as a unit group.
const CSV_HEAVY_COLUMNS = {
    brand: ['Merek', 'Brand'],
    machineType: ['Jenis Alat', 'Machine Type'],
    assetCode: ['Nomor Lambung', 'Kode Aset', 'Asset Code'],
    workTool: ['Alat Kerja', 'Work Tool'],
    cameraAi: ['Camera AI'], telematicBox: ['Telematic Box'],
    switchLimiter: ['Switch Limiter'], rotaryLamp: ['Rotary Lamp']
};
// Heavy fields whose headers tractor sheets also use for their own purposes.
const CSV_SHARED_HEADER_FIELDS = ['assetCode', 'machineType', 'brand'];

// Infer the file's group from its headers, using only unambiguous markers: the
// four heavy component headers on one side, the John Deere headers on the
// other. 'Nomor Lambung', 'Jenis Alat' and 'Kelompok' are deliberately NOT
// markers — tractor sheets use them too.
function inferCsvGroup(fields) {
    const f = (fields || []).map(x => String(x || '').trim().toLowerCase());
    const has = list => list.some(h => f.includes(h.toLowerCase()));
    const heavy = has(['Camera AI', 'Telematic Box', 'Switch Limiter', 'Rotary Lamp']);
    const tractor = has(['Implement', 'Display', 'GPS', 'Steering', 'JDLink', 'Status Unit Display',
        'Status Unit GPS', 'Status Unit Steering', 'Status Unit JDLink', 'GPS License', 'License Display', 'Display License']);
    if (heavy && !tractor) return 'heavy';
    if (tractor && !heavy) return 'tractor';
    return null;
}

function processData(rows, ctx) {
    const valid = [];
    const rejected = [];
    const groupWarnings = [];
    const fallback = ctx && ctx.fallbackGroup === 'heavy' ? 'heavy' : 'tractor';
    const fileGroup = (ctx && ctx.fileGroup) || null;
    rows.forEach((r, idx) => {
        const unit = {
            id: generateId(),
            name: clean(getVal(r, 'Nickname')),
            model: clean(getVal(r, 'Model')),
            sn: clean(getVal(r, 'Serial Number')),
            implement: clean(getVal(r, 'Implement')),
            status: clean(getValAny(r, ['Status Unit', 'Status'])),
            display: clean(getValAny(r, ['Status Unit Display', 'Display'])),
            gps: clean(getValAny(r, ['Status Unit GPS', 'GPS'])),
            steering: clean(getValAny(r, ['Status Unit Steering', 'Steering'])),
            jdlink: clean(getValAny(r, ['Status Unit JDLink', 'JDLink'])),
            site: clean(getVal(r, 'Site')),
            yearReceived: clean(getVal(r, 'Tahun Penerimaan')) || clean(getVal(r, 'Year Received')),
            userCategory: clean(getVal(r, 'User Category')),
            // Same rules as the licence ledger import: canonical spelling, and
            // dates as YYYY-MM-DD with D/M/YYYY read day-first. Stored raw,
            // '01/10/2026' (1 Oct) was read as 10 Jan — "expired" — and the
            // auto-downgrade then wrote a valid SF-RTK down to SF-1.
            gpsLicense: canonicalLicenseType(clean(getVal(r, 'GPS License'))),
            licenseDisplay: canonicalLicenseType(clean(getValAny(r, ['License Display', 'Display License']))),
            // New dual columns. Fall back to the legacy single-pair columns so
            // importing an old export still works — legacy dates map to GPS.
            gpsLicenseStartDate: csvLicenseDate(clean(getVal(r, 'GPS License Start Date')) || clean(getVal(r, 'License Start Date'))),
            gpsLicenseEndDate:   csvLicenseDate(clean(getVal(r, 'GPS License Expiration Date')) || clean(getVal(r, 'License Expiration Date'))),
            displayLicenseStartDate: csvLicenseDate(clean(getVal(r, 'Display License Start Date'))),
            displayLicenseEndDate:   csvLicenseDate(clean(getVal(r, 'Display License Expiration Date'))),
            remarks: clean(getVal(r, 'Remarks')),
            breakdownReason: clean(getValAny(r, ['Breakdown Reason', 'Alasan Breakdown'])),
            downtimeHistory: [],
            breakdownStartedAt: null
        };
        // Heavy columns are attached only when they carry a value, so a
        // tractor row is exactly today's object.
        Object.keys(CSV_HEAVY_COLUMNS).forEach(k => {
            const v = clean(getValAny(r, CSV_HEAVY_COLUMNS[k]));
            if (v) unit[k] = v;
        });
        const raw = clean(getVal(r, 'Unit Group'));
        const explicit = normalizeGroupKey(raw);
        unit.unitGroup = explicit || fileGroup || fallback;
        // The group it actually lands in — the file's, when the headers say
        // so, not necessarily the open tab.
        if (explicit === null) groupWarnings.push({ row: idx + 2, name: unit.name, sn: unit.sn, value: raw, group: unit.unitGroup });
        if (explicit) csvExplicitGroup.add(unit);
        else if (fileGroup) csvInferredGroup.add(unit);
        if (!unit.sn && !unit.name) {
            rejected.push({ row: idx + 2, reason: 'Missing both nickname and serial number' });
        } else if (!unit.sn) {
            rejected.push({ row: idx + 2, reason: 'Missing serial number', name: unit.name });
        } else {
            valid.push(unit);
        }
    });
    return { valid, rejected, groupWarnings };
}

// 'Unit' when the status is not Good, then the components OF THE UNIT'S GROUP.
// For a tractor the result is identical, in content and order, to the old
// hard-coded Display/GPS/Steering/JDLink list; for a heavy unit it reads
// Camera AI / Telematic Box / Switch Limiter / Rotary Lamp instead of four
// phantom John Deere faults.
function detectIssues(d) {
    const issues = [];
    if (!isGood(d.status)) issues.push('Unit');
    groupDef(unitGroupOf(d)).components.forEach(c => { if (!isGood(d[c.key])) issues.push(c.label); });
    return issues;
}

// With the default groups (['tractor']) this returns today's object in today's
// key order.
function countIssues(data, groups) {
    const counts = { Unit: 0 };
    (groups || ['tractor']).forEach(g => groupDef(g).components.forEach(c => { counts[c.label] = 0; }));
    let totalWithIssues = 0;
    data.forEach(d => {
        const issues = detectIssues(d);
        if (issues.length > 0) totalWithIssues++;
        issues.forEach(i => { if (i in counts) counts[i]++; });
    });
    return { total: totalWithIssues, counts };
}

// ============================================================
// DASHBOARD RENDERING
// ============================================================

// A date that records when something happened cannot be in the future, and a
// mistyped year (2026 → 2062) is the common way it ends up there. Such a row
// then sorts to the top of every table and falls outside every date-range
// filter. Licence dates are deliberately NOT capped — those are meant to be
// in the future. Refreshed rather than hardcoded so a session running past
// midnight still gets the right ceiling.
function capEventDatesToToday() {
    const today = toISODate();
    document.querySelectorAll('input[data-nofuture]').forEach(el => { el.max = today; });
}

function onDataLoaded() {
    document.getElementById('emptyState').style.display = 'none';
    document.getElementById('dashboardContent').style.display = 'block';
    capEventDatesToToday();

    populateFilters();
    populateEditFilters();
    // Keeps the search box and the filters: this runs on every snapshot.
    filteredData = applyFilterLogic();
    updateDashboard(filteredData);
    updateNavGroups();

    const now = new Date().toLocaleString();
    document.getElementById('lastUpdated').textContent = `Updated: ${now}`;

    document.getElementById('connectionDot').classList.add('connected');
    updateConnectionLabel();

    updateEditCount();
    scheduleDecisionRefresh();

    // Persist any premium licence that has expired into its fallback tier.
    scheduleExpiredLicenseDowngrades();

    _tryAutoDailyEmail();
    document.dispatchEvent(new CustomEvent('ot:data'));
}

// ---- Dashboard group scope: Pertanian / Alat Berat / Semua ----
function _issueOptions(scope, withUnit) {
    const opts = [];
    const add = (g, grp) => groupDef(g).components.forEach(c => opts.push({ v: c.label, t: c.label, grp }));
    if (scope === 'all') { add('tractor', UNIT_GROUPS.tractor.shortLabel); add('heavy', UNIT_GROUPS.heavy.shortLabel); }
    else add(scope, '');
    return withUnit ? [{ v: 'Unit', t: 'Unit', grp: '' }].concat(opts) : opts;
}
// Rebuild a filter <select> only when its option list actually differs, so a
// database with no heavy equipment never has its static markup rewritten.
function _syncSelect(sel, allLabel, opts, suffix) {
    if (!sel) return;
    const want = [['', allLabel]].concat(opts.map(o => [o.v, o.t + suffix, o.grp]));
    const have = [...sel.options].map(o => [o.value, o.textContent, o.parentElement.tagName === 'OPTGROUP' ? o.parentElement.label : '']);
    const same = want.length === have.length && want.every((w, i) => w[0] === have[i][0] && w[1] === have[i][1] && (w[2] || '') === have[i][2]);
    if (same) return;
    const cur = sel.value;
    let html = `<option value="">${escapeHtml(allLabel)}</option>`;
    let open = '';
    opts.forEach(o => {
        if ((o.grp || '') !== open) {
            if (open) html += '</optgroup>';
            if (o.grp) html += `<optgroup label="${escapeHtml(o.grp)}">`;
            open = o.grp || '';
        }
        html += `<option value="${escapeHtml(o.v)}">${escapeHtml(o.t + suffix)}</option>`;
    });
    if (open) html += '</optgroup>';
    sel.innerHTML = html;
    sel.value = opts.some(o => o.v === cur) ? cur : '';
}

function syncDashGroupUI() {
    const both = hasHeavyUnits() && hasTractorUnits();
    const scope = effectiveDashGroup();
    const cap = document.getElementById('dashScopeCaption');
    if (cap) {
        cap.hidden = !both;
        if (both) {
            const nH = unitsOfGroup(globalData, 'heavy').length;
            cap.textContent = scope === 'all'
                ? `Scope: all units (${globalData.length - nH} ${UNIT_GROUPS.tractor.label}, ${nH} ${UNIT_GROUPS.heavy.label})`
                : `Scope: ${groupDef(scope).label} · ${unitsOfGroup(globalData, scope).length} units`;
        }
    }
    _syncSelect(document.getElementById('componentFilter'), 'All Components', _issueOptions(scope, false), ' Issues');
    _syncSelect(document.getElementById('issueFilter'), 'All Issues', _issueOptions(scope, true), '');
    syncDashHead();
}

// ---- Page head: date, equipment-group switch, Overview | Reliability ----
// The head also shows on an empty dashboard and follows the account's group
// limit, so it re-syncs on ot:view and ot:gating as well as on every render.
function syncDashHead() {
    const dateEl = document.getElementById('dashDate');
    if (dateEl) {
        const d = new Date();
        dateEl.textContent = d.toLocaleDateString('en-GB', { weekday: 'long' }) + ', '
            + d.toLocaleDateString('en-GB', { day: 'numeric', month: 'long', year: 'numeric' });
    }
    const seg = document.getElementById('dashGroupSeg');
    if (seg) {
        // A switch only where there is somewhere to go: both groups in the
        // fleet, and an account that may see both. A limited account never
        // sees a way to the other group (the sidebar hides it the same way).
        const show = effectiveUnitScope() === 'all' && !document.body.dataset.unitScope
            && hasHeavyUnits() && hasTractorUnits();
        seg.hidden = !show;
        if (show) {
            const cur = effectiveDashGroup();
            seg.querySelectorAll('[data-dash-group]').forEach(b =>
                b.setAttribute('aria-pressed', String(b.dataset.dashGroup === cur)));
        }
    }
    syncDashTabs();
}

// The open tab lasts for the session (a fresh tab opens on Overview). Print
// never hides a pane, so a printed dashboard still carries everything.
const DASH_TAB_KEY = 'ot.dashTab';
let dashTab = (() => {
    try { return sessionStorage.getItem(DASH_TAB_KEY) === 'reliability' ? 'reliability' : 'overview'; }
    catch (_) { return 'overview'; }
})();
function setDashTab(tab, opts) {
    dashTab = tab === 'reliability' ? 'reliability' : 'overview';
    try { sessionStorage.setItem(DASH_TAB_KEY, dashTab); } catch (_) {}
    syncDashTabs();
    const btn = document.querySelector(`#viewDashboard [data-dash-tab="${dashTab}"]`);
    if (opts && opts.focus && btn) {
        btn.focus();
        // From the summary strip further down: bring the tabs back into view.
        const bar = btn.closest('.dash-tabs');
        if (bar && bar.getBoundingClientRect().top < 0) bar.scrollIntoView({ block: 'start' });
    }
    // A chart drawn while its tab was hidden has no size until measured.
    if (dashTab === 'reliability' && charts.downtimeChart) charts.downtimeChart.resize();
}
function syncDashTabs() {
    const host = document.getElementById('dashboardContent');
    if (!host) return;
    if (host.dataset.tab !== 'print') host.dataset.tab = dashTab;
    host.querySelectorAll('[data-dash-tab]').forEach(b => {
        const on = b.dataset.dashTab === dashTab;
        b.classList.toggle('active', on);
        b.setAttribute('aria-selected', String(on));
        b.tabIndex = on ? 0 : -1;
    });
}
// Arrow keys, Home and End move between the two tabs (ARIA tabs pattern).
function dashTabKey(e) {
    const order = ['overview', 'reliability'];
    let i = order.indexOf(dashTab);
    if (e.key === 'ArrowRight' || e.key === 'ArrowLeft') i = (i + 1) % order.length;
    else if (e.key === 'Home') i = 0;
    else if (e.key === 'End') i = order.length - 1;
    else return;
    e.preventDefault();
    setDashTab(order[i], { focus: true });
}
document.addEventListener('ot:view', e => { if (e.detail && e.detail.view === 'dashboard') syncDashHead(); });
document.addEventListener('ot:gating', () => syncDashHead());
// Both panes go on paper. The chart in the hidden one was drawn at no size,
// so every chart is measured again before the page is laid out.
window.addEventListener('beforeprint', () => {
    const host = document.getElementById('dashboardContent');
    if (!host || currentView !== 'dashboard') return;
    host.dataset.tab = 'print';
    Object.values(charts).forEach(c => { try { if (c) c.resize(); } catch (_) {} });
});
window.addEventListener('afterprint', () => {
    const host = document.getElementById('dashboardContent');
    if (host && host.dataset.tab === 'print') { host.dataset.tab = dashTab; syncDashTabs(); }
});

function setDashGroup(g, opts) {
    const sc = effectiveUnitScope();
    if (sc === 'tractor' || sc === 'heavy') { g = sc; opts = { ...(opts || {}), persist: false }; }
    if (!DASH_GROUP_KEYS.includes(g)) return;
    dashGroupPref = g;
    if (!opts || opts.persist !== false) writePref('dashUnitGroup', g);
    sortState.key = null;
    ['componentFilter', 'issueFilter'].forEach(id => { const el = document.getElementById(id); if (el) el.value = ''; });
    populateFilters();
    filteredData = applyFilterLogic();
    updateDashboard(filteredData);
    markActiveNav();
}

function updateDashboard(data) {
    syncDashGroupUI();
    renderNarrative(data);
    renderKPI(data);
    renderDashOverview(data);
    renderStatusChart(data);
    renderSiteChart(data);
    renderLicenseAlerts(data);
    renderStockAlerts();
    renderComponentHealth(data);
    renderDowntimeKPIs();
    renderTable(data);
    renderRepair();
    renderDamageStats();
    updateFilterCount(data);
}

// ---- Narrative summary sentence (editorial style) ----
function renderNarrative(data) {
    const el = document.getElementById('dashNarrative');
    if (!el) return;
    if (!data.length) { el.style.display = 'none'; return; }

    const total = data.length;
    const sites = [...new Set(data.map(d => d.site).filter(Boolean))].length || 1;
    const breakdown = data.filter(d => !isGood(d.status)).length;
    const issues = data.filter(d => detectIssues(d).length > 0).length;
    // Expired and expiring are two different facts; "akan expire" counted both.
    const al = _buildAlertList(scopeDashUnits());
    const expired = al.expiredCount || 0;
    const soon = al.soonCount != null ? al.soonCount : Math.max(0, al.total - expired);

    const clauses = [
        breakdown === 0 ? 'all units are operating today' : `${breakdown} unit${breakdown === 1 ? ' is' : 's are'} in breakdown`
    ];
    if (issues > 0) clauses.push(`${issues} running with component issues`);
    if (expired > 0) clauses.push(`${expired} license${expired === 1 ? ' has' : 's have'} expired`);
    if (soon > 0) clauses.push(`${soon} license${soon === 1 ? '' : 's'} expiring in the next 30 days`);

    let tail;
    if (clauses.length === 1) tail = clauses[0];
    else tail = clauses.slice(0, -1).join(', ') + ', and ' + clauses[clauses.length - 1];

    // The noun names the group only when the dashboard is not the plain
    // agricultural view, so that sentence reads exactly as it always has.
    const scope = effectiveDashGroup();
    let noun = total === 1 ? 'unit' : 'units';
    if (scope === 'heavy') noun = `${UNIT_GROUPS.heavy.shortLabel} units`;
    else if (scope === 'all') {
        const nH = data.filter(isHeavy).length;
        noun = `units (${total - nH} ${UNIT_GROUPS.tractor.shortLabel}, ${nH} ${UNIT_GROUPS.heavy.shortLabel})`;
    }
    el.textContent = `${total} ${noun} across ${sites} site${sites === 1 ? '' : 's'} — ${tail}.`;
    el.style.display = '';
}

// ---- KPI Cards ----
function renderKPI(data) {
    const total = data.length;
    const good = data.filter(d => isGood(d.status)).length;
    const breakdown = total - good;
    const withIssues = data.filter(d => detectIssues(d).length > 0).length;
    const healthRate = pct(good, total);

    document.getElementById('kpiTotal').textContent = total;
    document.getElementById('kpiGood').textContent = good;
    document.getElementById('kpiBreakdown').textContent = breakdown;
    document.getElementById('kpiIssue').textContent = withIssues;
    document.getElementById('kpiHealth').textContent = healthRate + '%';

    document.getElementById('kpiGoodPct').textContent = pct(good, total) + '% of total';
    document.getElementById('kpiBreakdownPct').textContent = pct(breakdown, total) + '% of total';
    document.getElementById('kpiIssuePct').textContent = pct(withIssues, total) + '% of total';

    document.getElementById('kpiGoodBar').style.width = pct(good, total) + '%';
    document.getElementById('kpiBreakdownBar').style.width = pct(breakdown, total) + '%';
    document.getElementById('kpiIssueBar').style.width = pct(withIssues, total) + '%';
    document.getElementById('kpiHealthBar').style.width = healthRate + '%';
}

// ---- Overview cards (design F) ----
// Everything here is read from the same list as the KPI cards (the scope and
// the filter bar), and only ever adds markup of its own: the captured tables,
// chips and rings above and below keep rendering exactly as they did.
function renderDashOverview(data) {
    const now = Date.now();
    const scope = effectiveDashGroup();
    const total = data.length;
    const good = data.filter(d => isGood(d.status)).length;
    const down = data.filter(d => !isGood(d.status));

    // Breakdown card: how long the longest running breakdown has lasted.
    const starts = down.map(d => d.breakdownStartedAt).filter(t => typeof t === 'number' && t > 0 && t <= now);
    const longest = document.getElementById('dashBreakdownLongest');
    if (longest) {
        longest.hidden = !starts.length;
        longest.textContent = starts.length ? `Longest ${dashSpan(now - Math.min(...starts))}` : '';
    }

    // Licences card: John Deere only, so not on the Heavy dashboard.
    const lic = _buildAlertList(data);
    const licCard = document.getElementById('dashLicCard');
    if (licCard) licCard.hidden = scope === 'heavy';
    const due = document.getElementById('dashLicDue');
    if (due) due.textContent = lic.soonCount;
    const exp = document.getElementById('dashLicExpired');
    if (exp) { exp.hidden = !lic.expiredCount; exp.textContent = `${lic.expiredCount} expired`; }

    // Fleet health ring: the health rate, as the arc of a circle r=38.
    const rate = pct(good, total);
    const arc = document.getElementById('dashHealthArc');
    const C = 2 * Math.PI * 38;
    if (arc) arc.setAttribute('stroke-dasharray', `${(C * rate / 100).toFixed(1)} ${C.toFixed(1)}`);
    const sub = document.getElementById('dashHealthSub');
    if (sub) sub.textContent = `${good} of ${total} unit${total === 1 ? '' : 's'} in good condition`;

    renderDashAttention(data, now);
    renderDashSites(data);
    renderDashParts(data, scope);
}

// "3 days", "5 hours": how long something has been going on.
function dashSpan(ms) {
    const h = Math.floor(ms / 3600000);
    if (h < 1) return 'under 1 hour';
    if (h < 24) return `${h} hour${h === 1 ? '' : 's'}`;
    const d = Math.floor(h / 24);
    return `${d} day${d === 1 ? '' : 's'}`;
}

// Needs attention: units in breakdown (longest first), then licences that
// expired or expire within 30 days — the same licences as License Alerts.
const DASH_ATTENTION_ROWS = 8;
const DASH_ICON_STOP = '<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m15 9-6 6"></path><path d="m9 9 6 6"></path><polygon points="7.86 2 16.14 2 22 7.86 22 16.14 16.14 22 7.86 22 2 16.14 2 7.86 7.86 2"></polygon></svg>';
const DASH_ICON_KEY = '<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="7.5" cy="15.5" r="5.5"></circle><path d="m21 2-9.6 9.6"></path><path d="m15.5 7.5 3 3L22 7l-3-3"></path></svg>';
function renderDashAttention(data, now) {
    const host = document.getElementById('dashAttention');
    if (!host) return;
    const inbox = document.getElementById('dashAttnInbox');
    if (inbox) inbox.hidden = !canViewView('leader');

    // The newest open damage record says what broke when the unit itself
    // carries no breakdown reason. Matched by id or SN first, so liveUnitFor
    // (a search of every unit) only runs on the few records that may fit.
    const open = (globalDamages || []).filter(r => !r.resolved);
    const openDamage = u => {
        const sn = String(u.sn || '').toLowerCase();
        const recs = open.filter(r => (r.unitId === u.id || (sn && String(r.sn || '').toLowerCase() === sn))
            && liveUnitFor(r) === u);
        recs.sort((a, b) => String(b.date || '').localeCompare(String(a.date || '')));
        return recs.length ? (recs[0].description || recs[0].component || '') : '';
    };
    const rows = [];
    data.filter(d => !isGood(d.status)).forEach(u => {
        const t = u.breakdownStartedAt;
        const ms = typeof t === 'number' && t > 0 && t <= now ? now - t : null;
        rows.push({ u, kind: 'down', order: 0, rank: ms == null ? 0 : -ms,
            issue: u.breakdownReason || openDamage(u) || '—', status: u.status || 'Breakdown',
            since: ms == null ? '—' : dashSpan(ms) });
    });
    // Same selection as renderLicenseAlerts / _buildAlertList.
    data.filter(u => !isHeavy(u)).forEach(u => ['gps', 'display'].forEach(kind => {
        const end = getLicenseEndDate(u, kind);
        if (!end) return;
        const s = getExpiryStatus(end);
        if (effectiveLicense(u, kind).downgraded) return;
        if (!(s.kind === 'expired' || s.kind === 'soon' || (s.kind === 'ok' && s.daysLeft <= 30))) return;
        const what = kind === 'gps' ? 'GPS' : 'Display';
        const type = kind === 'gps' ? u.gpsLicense : u.licenseDisplay;
        const days = Math.abs(s.daysLeft);
        const n = `${days} day${days === 1 ? '' : 's'}`;
        rows.push({ u, kind: 'license', order: 1, rank: s.daysLeft,
            issue: `${what} license${type ? ' ' + type : ''} ${s.kind === 'expired' ? 'expired' : 'expires'}`,
            status: 'License', since: s.daysLeft < 0 ? n : s.daysLeft === 0 ? 'today' : `in ${n}` });
    }));
    rows.sort((a, b) => a.order - b.order || a.rank - b.rank);

    if (!rows.length) {
        host.innerHTML = `<p class="dash-empty">Nothing needs attention: no unit is in breakdown${
            effectiveDashGroup() === 'heavy' ? '' : ' and no license is due in the next 30 days'}.</p>`;
        return;
    }
    const shown = rows.slice(0, DASH_ATTENTION_ROWS);
    const site = r => escapeHtml(r.u.site || '—');
    host.innerHTML = `
        <div class="dash-table-wrap">
        <table class="dash-table dash-attn__table">
            <thead><tr><th scope="col">Unit</th><th scope="col">Issue</th><th scope="col">Site</th>
                <th scope="col">Status</th><th scope="col" class="dash-num">Since</th></tr></thead>
            <tbody>${shown.map(r => `
                <tr class="dash-attn__row dash-attn__row--${r.kind}">
                    <td class="dash-attn__unit"><button type="button" class="dash-unit" title="View unit profile"
                        onclick="showUnitProfile(${jsArg(r.u.id)})">${escapeHtml(r.u.name || r.u.sn || 'Unnamed')}</button></td>
                    <td class="dash-attn__issue">${escapeHtml(r.issue)}<span class="dash-attn__site-inline"> · ${site(r)}</span></td>
                    <td class="dash-attn__site">${site(r)}</td>
                    <td class="dash-attn__status"><span class="dash-chip dash-chip--${r.kind === 'down' ? 'bad' : 'info'}">${
                        r.kind === 'down' ? DASH_ICON_STOP : DASH_ICON_KEY}${escapeHtml(r.status)}</span></td>
                    <td class="dash-attn__since dash-num">${escapeHtml(r.since)}</td>
                </tr>`).join('')}
            </tbody>
        </table>
        </div>
        ${rows.length > shown.length ? `<p class="dash-card__foot">Showing ${shown.length} of ${rows.length} — the rest are in Unit Detail and License Alerts below.</p>` : ''}`;
}

// Sites: good units out of all units per site, largest site first.
function renderDashSites(data) {
    const host = document.getElementById('dashSites');
    if (!host) return;
    const map = new Map();
    data.forEach(d => {
        const s = d.site || 'Unknown';
        const e = map.get(s) || { good: 0, total: 0 };
        e.total++;
        if (isGood(d.status)) e.good++;
        map.set(s, e);
    });
    const sites = [...map.entries()].sort((a, b) => b[1].total - a[1].total || a[0].localeCompare(b[0]));
    host.innerHTML = sites.length ? sites.map(([s, e]) => `
        <div class="dash-site">
            <div class="dash-site__row"><span class="dash-site__name">${escapeHtml(s)}</span>
                <span class="dash-site__count">${e.good} / ${e.total} good</span></div>
            <div class="dash-bar" aria-hidden="true"><span style="width:${pct(e.good, e.total)}%"></span></div>
        </div>`).join('') : '<p class="dash-empty">No units.</p>';
}

// Faulty parts: units whose component is not Good, per component of each
// group in scope (the same reading as detectIssues), in the component's colour.
const DASH_PART_ICONS = {
    display: '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="3" y="4" width="18" height="12" rx="2"></rect><path d="M8 20h8"></path><path d="M12 16v4"></path></svg>',
    gps: '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="12" r="7"></circle><circle cx="12" cy="12" r="2.5"></circle><path d="M12 2v3"></path><path d="M12 19v3"></path><path d="M2 12h3"></path><path d="M19 12h3"></path></svg>',
    steering: '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="12" r="9"></circle><circle cx="12" cy="12" r="2.5"></circle><path d="M9.5 12H3.2"></path><path d="M14.5 12h6.3"></path><path d="M12 14.5v6.3"></path></svg>',
    jdlink: '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="10" r="2"></circle><path d="M12 12v9"></path><path d="M8.5 6.5a5 5 0 0 0 0 7"></path><path d="M15.5 6.5a5 5 0 0 1 0 7"></path></svg>',
    cameraAi: '<i class="fas fa-camera" aria-hidden="true"></i>',
    telematicBox: '<i class="fas fa-satellite-dish" aria-hidden="true"></i>',
    switchLimiter: '<i class="fas fa-toggle-on" aria-hidden="true"></i>',
    rotaryLamp: '<i class="fas fa-lightbulb" aria-hidden="true"></i>'
};
function renderDashParts(data, scope) {
    const host = document.getElementById('dashParts');
    if (!host) return;
    let groups = scope === 'all' ? UNIT_GROUP_KEYS.filter(g => data.some(u => unitGroupOf(u) === g)) : [scope];
    if (!groups.length) groups = groupsInScope(scope);
    host.innerHTML = groups.map(g => {
        const members = data.filter(u => unitGroupOf(u) === g);
        return groupDef(g).components.map(c => {
            const n = members.filter(u => !isGood(u[c.key])).length;
            const token = '--color-' + c.key.replace(/[A-Z]/g, m => '-' + m.toLowerCase());
            return `<span class="dash-part${n ? '' : ' dash-part--none'}" style="--part:var(${token})">${
                DASH_PART_ICONS[c.key] || ''}<span class="dash-part__name">${escapeHtml(c.label)}</span><span class="dash-part__n">${n}</span></span>`;
        }).join('');
    }).join('');
}

// ---- Status Chart (Donut) ----
function renderStatusChart(data) {
    const good = data.filter(d => isGood(d.status)).length;
    const breakdown = data.length - good;

    destroyChart('statusChart');
    charts.statusChart = makeChart('statusChart', {
        type: 'doughnut',
        data: {
            labels: ['Good', 'Breakdown'],
            datasets: [{ data: [good, breakdown], backgroundColor: [themeColor('--dot-good', '#17B26A'), themeColor('--dot-bad', '#F04438')], borderWidth: 0, hoverOffset: 6 }]
        },
        options: {
            responsive: true, maintainAspectRatio: false, cutout: '70%',
            plugins: {
                legend: { position: 'bottom', labels: { padding: 16, usePointStyle: true, pointStyle: 'circle', color: dashChartInk(), font: dashChartFont(13) } },
                tooltip: { callbacks: { label: ctx => { const t = ctx.dataset.data.reduce((a, b) => a + b, 0); return ` ${ctx.label}: ${ctx.parsed} (${pct(ctx.parsed, t)}%)`; } } }
            }
        }
    });
}

// ---- Site Chart (Horizontal Bar) ----
function renderSiteChart(data) {
    const siteMap = {};
    data.forEach(d => {
        const s = d.site || 'Unknown';
        if (!siteMap[s]) siteMap[s] = { good: 0, breakdown: 0 };
        if (isGood(d.status)) siteMap[s].good++; else siteMap[s].breakdown++;
    });

    const labels = Object.keys(siteMap).sort();

    destroyChart('siteChart');
    charts.siteChart = makeChart('siteChart', {
        type: 'bar',
        data: {
            labels,
            datasets: [
                { label: 'Good', data: labels.map(s => siteMap[s].good), backgroundColor: themeColor('--dot-good', '#17B26A'), borderRadius: 4, barPercentage: 0.6 },
                { label: 'Breakdown', data: labels.map(s => siteMap[s].breakdown), backgroundColor: themeColor('--dot-bad', '#F04438'), borderRadius: 4, barPercentage: 0.6 }
            ]
        },
        options: {
            responsive: true, maintainAspectRatio: false, indexAxis: 'y',
            scales: {
                x: { stacked: true, beginAtZero: true, ticks: { stepSize: 1, color: dashChartInk(), font: dashChartFont(12) }, grid: dashChartGrid(), border: { display: false } },
                y: { stacked: true, ticks: { color: dashChartInk(), font: dashChartFont(12) }, grid: { display: false } }
            },
            plugins: {
                legend: { position: 'top', align: 'end', labels: { usePointStyle: true, pointStyle: 'circle', padding: 12, color: dashChartInk(), font: dashChartFont(12) } },
                tooltip: { callbacks: { label: ctx => ` ${ctx.dataset.label}: ${ctx.parsed.x} units` } }
            }
        }
    });
}

// ---- License Alerts ----
function renderLicenseAlerts(data) {
    const section = document.getElementById('licenseAlertsSection');
    const container = document.getElementById('licenseAlertsCards');
    const summary = document.getElementById('licenseAlertsSummary');

    const SOON_DAYS = 30;
    const alerts = [];

    data.filter(u => !isHeavy(u)).forEach(unit => {
        ['gps', 'display'].forEach(kind => {
            const end = getLicenseEndDate(unit, kind);
            if (!end) return;
            const s = getExpiryStatus(end);
            // Auto-downgraded premium (expired SF-RTK/G5 Advance) is now on its
            // stable fallback tier — no action needed, so drop it from alerts.
            if (effectiveLicense(unit, kind).downgraded) return;
            if (s.kind === 'expired' || (s.kind === 'soon' || (s.kind === 'ok' && s.daysLeft <= SOON_DAYS))) {
                const licName = kind === 'display'
                    ? (unit.licenseDisplay || 'Display')
                    : (unit.gpsLicense || 'GPS');
                alerts.push({
                    unit,
                    kind,
                    licName,
                    endDate: end,
                    status: s.kind === 'expired' ? 'expired' : 'soon',
                    daysLeft: s.daysLeft,
                    label: s.label
                });
            }
        });
    });

    if (alerts.length === 0) {
        section.style.display = 'none';
        return;
    }

    alerts.sort((a, b) => a.daysLeft - b.daysLeft);

    const expiredCount = alerts.filter(a => a.status === 'expired').length;
    const soonCount = alerts.filter(a => a.status === 'soon').length;

    section.style.display = '';
    summary.innerHTML = [
        expiredCount ? `<span class="la-chip expired"><i class="fas fa-circle-xmark"></i> ${expiredCount} Expired</span>` : '',
        soonCount ? `<span class="la-chip soon"><i class="fas fa-triangle-exclamation"></i> ${soonCount} Expiring ≤${SOON_DAYS}d</span>` : ''
    ].filter(Boolean).join('');

    container.innerHTML = alerts.map(a => {
        const meta = [a.licName, a.unit.model, a.unit.site, `Exp: ${a.endDate}`]
            .filter(Boolean).map(escapeHtml).join(' · ');
        return `
        <div class="la-card ${a.status}">
            <div class="la-card__icon">
                <i class="fas fa-${a.status === 'expired' ? 'circle-xmark' : 'triangle-exclamation'}"></i>
            </div>
            <div class="la-card__body">
                <div class="la-card__name">${escapeHtml(a.unit.name || a.unit.sn)}</div>
                <div class="la-card__meta">${meta}</div>
            </div>
            <div class="la-card__badge">${escapeHtml(a.label)}</div>
        </div>
    `;
    }).join('');
}

// ---- Low license stock (dashboard) ----
function _lowStockList() {
    const sum = computeLicenseSummary();
    return Object.keys(sum)
        .filter(t => (sum[t].in > 0 || sum[t].out > 0) && sum[t].sisa <= LICENSE_LOW_STOCK_THRESHOLD)
        .sort((a, b) => sum[a].sisa - sum[b].sisa)
        .map(t => ({ type: t, sisa: sum[t].sisa }));
}

function renderStockAlerts() {
    const section = document.getElementById('stockAlertsSection');
    const cards = document.getElementById('stockAlertsCards');
    if (!section || !cards) return;
    // Licence stock is about John Deere licences; nothing to say about it on
    // a heavy-equipment dashboard.
    if (effectiveDashGroup() === 'heavy') { section.style.display = 'none'; return; }
    const low = _lowStockList();
    if (!low.length) { section.style.display = 'none'; return; }
    section.style.display = '';
    cards.innerHTML = low.map(l => `
        <div class="stock-alert-card ${l.sisa <= 0 ? 'empty' : ''}" onclick="navigateTo('licenseStock')" title="Open License Stock">
            <i class="fas fa-${l.sisa <= 0 ? 'circle-xmark' : 'triangle-exclamation'}"></i>
            <span class="stock-alert-card__type">${escapeHtml(l.type)}</span>
            <span class="stock-alert-card__n">${l.sisa} left</span>
        </div>`).join('');
}

// ---- Email Alert (EmailJS) ----
function _getEmailSettings() {
    try { return JSON.parse(localStorage.getItem('emailjs_settings') || '{}'); }
    catch { return {}; }
}

function openEmailSettingsModal() {
    const s = _getEmailSettings();
    document.getElementById('emailjsPublicKey').value  = s.publicKey  || '';
    document.getElementById('emailjsServiceId').value  = s.serviceId  || '';
    document.getElementById('emailjsTemplateId').value = s.templateId || '';
    document.getElementById('emailjsRecipient').value  = s.recipient  || '';
    document.getElementById('emailjsAutoDaily').checked = !!s.autoDaily;
    document.getElementById('emailSettingsModal').classList.add('open');
}
function closeEmailSettingsModal() {
    document.getElementById('emailSettingsModal').classList.remove('open');
}
function saveEmailSettings() {
    const s = {
        publicKey:  document.getElementById('emailjsPublicKey').value.trim(),
        serviceId:  document.getElementById('emailjsServiceId').value.trim(),
        templateId: document.getElementById('emailjsTemplateId').value.trim(),
        recipient:  document.getElementById('emailjsRecipient').value.trim(),
        autoDaily:  document.getElementById('emailjsAutoDaily').checked
    };
    if (!s.publicKey || !s.serviceId || !s.templateId || !s.recipient) {
        showToast('Fill in all EmailJS fields', 'warning'); return;
    }
    localStorage.setItem('emailjs_settings', JSON.stringify(s));
    closeEmailSettingsModal();
    showToast('Email settings saved', 'success');
}

// SF/G5 licences are John Deere only, so heavy units never produce an alert.
// Called with no argument (the email report, the decision inbox) it stays
// fleet-wide.
function _buildAlertList(units) {
    const SOON_DAYS = 30;
    const lines = [];
    let expiredCount = 0, soonCount = 0;

    (units || globalData).filter(u => !isHeavy(u)).forEach(unit => {
        ['gps', 'display'].forEach(kind => {
            const end = getLicenseEndDate(unit, kind);
            if (!end) return;
            const s = getExpiryStatus(end);
            if (effectiveLicense(unit, kind).downgraded) return; // on fallback tier — not an alert
            if (s.kind === 'expired' || s.kind === 'soon' || (s.kind === 'ok' && s.daysLeft <= SOON_DAYS)) {
                const licName = kind === 'display' ? (unit.licenseDisplay || 'Display') : (unit.gpsLicense || 'GPS');
                const tag = s.kind === 'expired' ? 'EXPIRED' : 'EXPIRING';
                if (s.kind === 'expired') expiredCount++; else soonCount++;
                lines.push({
                    daysLeft: s.daysLeft,
                    text: `${tag} | ${unit.name || '-'} | ${unit.model || '-'} | ${unit.sn || '-'} | ${licName} | ${unit.site || '-'} | ${end} | ${s.label}`
                });
            }
        });
    });
    lines.sort((a, b) => a.daysLeft - b.daysLeft);
    return { expiredCount, soonCount, total: lines.length, lines: lines.map(l => l.text) };
}

function sendLicenseAlertEmail() {
    const s = _getEmailSettings();
    if (!s.publicKey || !s.serviceId || !s.templateId || !s.recipient) {
        showToast('Set up EmailJS first — click the gear icon', 'warning');
        openEmailSettingsModal();
        return;
    }

    const report = _buildAlertList();
    if (report.total === 0) {
        showToast('No license alerts to send', 'info'); return;
    }

    const today = new Date().toLocaleDateString('en-GB', { weekday:'long', year:'numeric', month:'long', day:'numeric' });
    const lowStock = _lowStockList();
    const body = [
        `License Alert Report — ${today}`,
        `Expired: ${report.expiredCount} | Expiring soon: ${report.soonCount}`,
        '',
        'Status | Unit | Model | Serial Number | License | Site | Expiry Date | Remaining',
        '—'.repeat(60),
        ...report.lines,
        ...(lowStock.length ? ['', 'LOW LICENSE STOCK', ...lowStock.map(l => `${l.type} | ${l.sisa} left`)] : [])
    ].join('\n');

    const btn = document.getElementById('btnEmailAlert');
    btn.disabled = true;
    btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Sending…';

    emailjs.init(s.publicKey);
    emailjs.send(s.serviceId, s.templateId, {
        to_email: s.recipient,
        subject: `License Alert: ${report.expiredCount} expired, ${report.soonCount} expiring soon`,
        message: body
    }).then(() => {
        showToast(`Alert report sent to ${s.recipient}`, 'success');
        localStorage.setItem('emailjs_last_sent', new Date().toDateString());
    }).catch(err => {
        console.error('[emailjs]', err);
        showToast('Failed to send email — check the EmailJS settings', 'error');
    }).finally(() => {
        btn.disabled = false;
        btn.innerHTML = '<i class="fas fa-envelope"></i> Email Report';
    });
}

function _tryAutoDailyEmail() {
    const s = _getEmailSettings();
    if (!s.autoDaily || !s.publicKey) return;
    const lastSent = localStorage.getItem('emailjs_last_sent');
    if (lastSent === new Date().toDateString()) return;
    const report = _buildAlertList();
    if (report.total === 0) return;
    sendLicenseAlertEmail();
}

// ---- Component Health ----
// Each group's rings are measured against that group's own units. The old
// denominator was every unit, so a single excavator — which has no Display or
// GPS at all — pulled a fully healthy tractor fleet below 100%.
function renderComponentHealth(data) {
    const grid = document.getElementById('componentGrid');
    const scope = effectiveDashGroup();
    let groups = scope === 'all'
        ? UNIT_GROUP_KEYS.filter(g => data.some(u => unitGroupOf(u) === g))
        : [scope];
    if (!groups.length) groups = scope === 'all' ? UNIT_GROUP_KEYS.slice() : [scope];
    const captions = groups.length > 1;

    grid.innerHTML = groups.map(g => {
        const members = data.filter(u => unitGroupOf(u) === g);
        const total = members.length;
        const rings = groupDef(g).components.map(c => {
            const goodCount = members.filter(d => isGood(d[c.key])).length;
            const rate = pct(goodCount, total);
            const color = COMPONENT_COLORS[c.key];
            const circumference = 2 * Math.PI * 28;
            const offset = circumference - (rate / 100) * circumference;
            return `
        <div class="component-stat">
            <div class="component-stat__name">${c.label}</div>
            <div class="component-stat__ring">
                <svg width="72" height="72" viewBox="0 0 72 72">
                    <circle cx="36" cy="36" r="28" fill="none" style="stroke:var(--border-light)" stroke-width="6"/>
                    <circle cx="36" cy="36" r="28" fill="none" stroke="${color}" stroke-width="6"
                        stroke-dasharray="${circumference}" stroke-dashoffset="${offset}" stroke-linecap="round"/>
                </svg>
                <div class="component-stat__ring-text" style="color:${color}">${rate}%</div>
            </div>
            <div class="component-stat__detail">${goodCount} / ${total} Good</div>
        </div>`;
        }).join('');
        return (captions ? `<div class="component-grid__group">${escapeHtml(groupDef(g).label)}</div>` : '') + rings;
    }).join('');
}

// ---- Detail Table ----
// True when anything is narrowing the dashboard list. Used to tell "there is
// no data" apart from "your filter matched nothing" — the second needs a way
// back out, the first does not.
function dashboardFilterActive() {
    const val = id => (document.getElementById(id) || {}).value || '';
    return !!(val('searchInput') || val('statusFilter') || val('siteFilter') || val('componentFilter'));
}

// ---- Dashboard table per scope ----
// Agricultural: today's 17 columns, header captured from the static markup.
// Heavy: its own 15. "Semua": 10 columns with a Kelompok column and one
// "Komponen" cell summarising whatever each unit's group monitors.
const DETAIL_COLSPAN = { tractor: 17, heavy: 16, all: 10 };
function renderDetailHead(scope) {
    const head = document.querySelector('#detailTable thead');
    if (!head || _detailHeadGroup === scope) return;
    const s = (k, l) => sortTh(k, l, 'sortTable');
    if (scope === 'tractor') head.innerHTML = DETAIL_HEADS.tractor;
    else if (scope === 'heavy') head.innerHTML = `<tr>${s('no', 'No')}${s('name', 'Nickname')}${s('brand', 'Brand')}${s('model', 'Model')}${s('sn', 'Serial Number')}
        ${s('machineType', 'Machine Type')}${s('assetCode', 'Asset No.')}${s('workTool', 'Work Tool')}${s('status', 'Status')}
        ${UNIT_GROUPS.heavy.components.map(c => s(c.key, c.label)).join('')}
        ${s('site', 'Site')}${s('yearReceived', 'Year Received')}${s('userCategory', 'User Category')}</tr>`;
    else head.innerHTML = `<tr>${s('no', 'No')}${s('name', 'Nickname')}${s('unitGroup', 'Group')}${s('model', 'Model')}
        ${s('sn', 'Serial Number')}${s('status', 'Status')}<th>Components</th>
        ${s('site', 'Site')}${s('yearReceived', 'Year Received')}${s('userCategory', 'User Category')}</tr>`;
    _detailHeadGroup = scope;
    markSortedHeader('#detailTable thead', sortState.key, sortState.asc);
}
function _statusCell(d) {
    return !isGood(d.status) && d.breakdownReason
        ? `<span class="badge badge-breakdown bd-clickable" data-reason="${escapeHtml(d.breakdownReason)}" onclick="showBreakdownPopover(event, this.dataset.reason)"><i class="fas fa-xmark"></i> ${escapeHtml(d.status)}</span>`
        : `<span class="badge ${isGood(d.status) ? 'badge-good' : 'badge-breakdown'}"><i class="fas fa-${isGood(d.status) ? 'check' : 'xmark'}"></i> ${escapeHtml(d.status)}</span>`;
}
function _dash(v) { return escapeHtml(v || '') || '<span style="color:var(--text-light);font-size:11px">—</span>'; }
function _catCell(d) {
    return d.userCategory ? `<span class="badge badge-cat" style="font-size:10px">${escapeHtml(d.userCategory)}</span>` : '<span style="color:var(--text-light);font-size:11px">—</span>';
}
function _detailRowHeavy(d, i) {
    return `
        <tr class="${!isGood(d.status) ? 'row-breakdown' : ''}">
            <td>${i + 1}</td>
            <td><strong class="unit-link" title="View unit profile" onclick="showUnitProfile(${jsArg(d.id)})">${escapeHtml(d.name)}</strong>${openDamageChipFor(d)}</td>
            <td>${_dash(d.brand)}</td>
            <td>${escapeHtml(d.model)}</td>
            <td style="font-family:monospace;font-size:12px">${escapeHtml(d.sn)}</td>
            <td>${_dash(d.machineType)}</td><td>${_dash(d.assetCode)}</td><td>${_dash(d.workTool)}</td>
            <td>${_statusCell(d)}</td>
            ${UNIT_GROUPS.heavy.components.map(c => `<td class="${isGood(d[c.key]) ? 'cell-good' : 'cell-bad'}">${escapeHtml(d[c.key] || '') || '—'}</td>`).join('')}
            <td>${escapeHtml(d.site)}</td><td>${_dash(d.yearReceived)}</td><td>${_catCell(d)}</td>
        </tr>`;
}
function _detailRowAll(d, i) {
    const comp = detectIssues(d).filter(x => x !== 'Unit');
    return `
        <tr class="${!isGood(d.status) ? 'row-breakdown' : ''}">
            <td>${i + 1}</td>
            <td><strong class="unit-link" title="View unit profile" onclick="showUnitProfile(${jsArg(d.id)})">${escapeHtml(d.name)}</strong>${openDamageChipFor(d)}</td>
            <td>${escapeHtml(groupDef(unitGroupOf(d)).shortLabel)}</td>
            <td>${escapeHtml(d.model)}</td>
            <td style="font-family:monospace;font-size:12px">${escapeHtml(d.sn)}</td>
            <td>${_statusCell(d)}</td>
            <td>${comp.length ? comp.map(x => `<span class="badge-component ${issueBadgeClass(x)}">${escapeHtml(x)}</span>`).join(' ') : '<span class="cell-good">All good</span>'}</td>
            <td>${escapeHtml(d.site)}</td><td>${_dash(d.yearReceived)}</td><td>${_catCell(d)}</td>
        </tr>`;
}

function renderTable(data) {
    _openDmgIdx = null;
    const scope = effectiveDashGroup();
    renderDetailHead(scope);
    const tbody = document.getElementById('detailBody');
    // An empty tbody under a 17-column header used to be the whole answer when
    // a filter matched nothing: no row, no message, and #emptyState does not
    // help because it is gated on globalData.length, not on the filtered list.
    if (!data || data.length === 0) {
        const span = DETAIL_COLSPAN[scope];
        tbody.innerHTML = dashboardFilterActive()
            ? `<tr><td colspan="${span}" style="text-align:center;padding:24px;color:var(--text-secondary)">
                   No units match the filter.
                   <button class="btn btn-secondary btn-sm" style="margin-left:8px" onclick="clearFilter()">
                       <i class="fas fa-filter-circle-xmark"></i> Clear filter</button>
               </td></tr>`
            : `<tr><td colspan="${span}" style="text-align:center;padding:24px;color:var(--text-secondary)">No units yet.</td></tr>`;
        return;
    }
    if (scope === 'heavy') { tbody.innerHTML = data.map(_detailRowHeavy).join(''); return; }
    if (scope === 'all') { tbody.innerHTML = data.map(_detailRowAll).join(''); return; }
    tbody.innerHTML = data.map((d, i) => {
        const isBD = !isGood(d.status);
        return `
        <tr class="${isBD ? 'row-breakdown' : ''}">
            <td>${i + 1}</td>
            <td><strong class="unit-link" title="View unit profile" onclick="showUnitProfile(${jsArg(d.id)})">${escapeHtml(d.name)}</strong></td>
            <td>${escapeHtml(d.model)}</td>
            <td style="font-family:monospace;font-size:12px">${escapeHtml(d.sn)}</td>
            <td>${escapeHtml(d.implement || '')}</td>
            <td>${!isGood(d.status) && d.breakdownReason
                ? `<span class="badge badge-breakdown bd-clickable" data-reason="${escapeHtml(d.breakdownReason)}" onclick="showBreakdownPopover(event, this.dataset.reason)"><i class="fas fa-xmark"></i> ${escapeHtml(d.status)}</span>`
                : `<span class="badge ${isGood(d.status) ? 'badge-good' : 'badge-breakdown'}"><i class="fas fa-${isGood(d.status) ? 'check' : 'xmark'}"></i> ${escapeHtml(d.status)}</span>`
            }</td>
            <td class="${isGood(d.display) ? 'cell-good' : 'cell-bad'}">${escapeHtml(d.display)}</td>
            <td class="${isGood(d.gps) ? 'cell-good' : 'cell-bad'}">${escapeHtml(d.gps)}</td>
            <td class="${isGood(d.steering) ? 'cell-good' : 'cell-bad'}">${escapeHtml(d.steering)}</td>
            <td class="${isGood(d.jdlink) ? 'cell-good' : 'cell-bad'}">${escapeHtml(d.jdlink)}</td>
            <td>${escapeHtml(d.site)}</td>
            <td>${escapeHtml(d.yearReceived || '') || '<span style="color:var(--text-light);font-size:11px">—</span>'}</td>
            <td>${d.userCategory ? `<span class="badge badge-cat" style="font-size:10px">${escapeHtml(d.userCategory)}</span>` : '<span style="color:var(--text-light);font-size:11px">—</span>'}</td>
            <td>${licenseTypeBadge(d, 'gps')}</td>
            <td>${licenseBadgeFor(d, 'gps')}</td>
            <td>${licenseTypeBadge(d, 'display')}</td>
            <td>${licenseBadgeFor(d, 'display')}</td>
        </tr>`;
    }).join('');
}

// ---- Sorting ----
function _resolveSortValue(d, key) {
    if (key === 'gpsExpiry') return getLicenseEndDate(d, 'gps');
    if (key === 'displayExpiry') return getLicenseEndDate(d, 'display');
    if (key === 'unitGroup') return groupDef(unitGroupOf(d)).shortLabel;
    return d[key] || '';
}

function sortTable(key) {
    if (sortState.key === key) { sortState.asc = !sortState.asc; } else { sortState.key = key; sortState.asc = true; }
    if (key === 'no') { sortState.key = null; filteredData = [...applyFilterLogic()]; }
    else {
        filteredData.sort((a, b) => {
            const va = String(_resolveSortValue(a, key) ?? "").toLowerCase(), vb = String(_resolveSortValue(b, key) ?? "").toLowerCase();
            if (va < vb) return sortState.asc ? -1 : 1;
            if (va > vb) return sortState.asc ? 1 : -1;
            return 0;
        });
    }
    markSortedHeader('#detailTable thead', sortState.key, sortState.asc);
    renderTable(filteredData);
    updateFilterCount(filteredData);
}

// ---- Repair & Maintenance ----
// ---- Damage statistics (dashboard) ----
// Which group a damage record belongs to: its live unit's group, or — for a
// record whose unit is gone — the group stamped on the record itself.
function damageInScope(r) {
    const scope = effectiveDashGroup();
    if (scope === 'all') return true;
    const u = liveUnitFor(r);
    const g = u ? unitGroupOf(u) : (normalizeGroupKey(r.unitGroup) === 'heavy' ? 'heavy' : 'tractor');
    return g === scope;
}

function renderDamageStats() {
    const recs = globalDamages.filter(damageInScope);
    const section = document.getElementById('damageStatsSection');
    if (!section) return;
    if (!recs.length) {
        section.style.display = 'none';
        destroyChart('damageTrendChart');
        return;
    }
    section.style.display = '';

    const open = recs.filter(r => !r.resolved).length;
    const totalEl = document.getElementById('damageStatsTotal');
    if (totalEl) totalEl.textContent = `${recs.length} records · ${open} open`;

    // Counts per damage type
    const typeColors = { 'Mekanis': 'var(--danger)', 'Software': 'var(--info)', 'Device Precision': 'var(--warning)' };
    const counts = {};
    recs.forEach(r => { const t = r.damageType || 'Lainnya'; counts[t] = (counts[t] || 0) + 1; });
    const typeOrder = DAMAGE_TYPES.concat(Object.keys(counts).filter(t => !DAMAGE_TYPES.includes(t)));
    document.getElementById('damageTypeChips').innerHTML = typeOrder
        .filter(t => counts[t])
        .map(t => `<div class="damage-type-chip"><span class="dot" style="background:${typeColors[t] || 'var(--text-light)'}"></span>${escapeHtml(damageTypeLabel(t))}<strong>${counts[t]}</strong></div>`)
        .join('');

    // Monthly trend, last 6 months
    const months = [];
    const now = new Date();
    for (let i = 5; i >= 0; i--) {
        const d = new Date(now.getFullYear(), now.getMonth() - i, 1);
        months.push({
            key: `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`,
            label: d.toLocaleDateString('en-GB', { month: 'short' })
        });
    }
    const byMonth = months.map(m => recs.filter(r => (r.date || '').startsWith(m.key)).length);
    destroyChart('damageTrendChart');
    charts.damageTrendChart = makeChart('damageTrendChart', {
        type: 'bar',
        data: { labels: months.map(m => m.label), datasets: [{ data: byMonth, backgroundColor: themeColor('--accent', '#0F766E'), borderRadius: 4, barPercentage: 0.55 }] },
        options: {
            plugins: { legend: { display: false } },
            scales: { y: { beginAtZero: true, ticks: { precision: 0, color: dashChartInk(), font: dashChartFont(12) }, grid: dashChartGrid(), border: { display: false } },
                      x: { ticks: { color: dashChartInk(), font: dashChartFont(12) }, grid: { display: false } } },
            maintainAspectRatio: false
        }
    });

    // Top-5 most frequently damaged units (live name via liveUnitFor)
    const perUnit = {};
    recs.forEach(r => {
        const lu = liveUnitFor(r);
        const name = (lu ? lu.name : r.unitName) || '(no name)';
        perUnit[name] = (perUnit[name] || 0) + 1;
    });
    const top = Object.entries(perUnit).sort((a, b) => b[1] - a[1]).slice(0, 5);
    const max = top.length ? top[0][1] : 1;
    document.getElementById('damageTopUnits').innerHTML = top.map(([name, n]) => `
        <div class="damage-top-row">
            <span class="damage-top-row__name" title="${escapeHtml(name)}">${escapeHtml(name)}</span>
            <span class="damage-top-row__bar"><span style="width:${Math.round(n / max * 100)}%"></span></span>
            <span class="damage-top-row__n">${n}</span>
        </div>`).join('');
}

// Reads the dashboard's scope, not every unit: with a group selected, the
// repair chips, charts and table describe that group only.
function renderRepair(scope) {
    const list = scope || scopeDashUnits();
    const issueFilterVal = document.getElementById('issueFilter').value;
    const issueData = countIssues(list, groupsInScope(effectiveDashGroup()));
    const chipColors = {
        Unit: themeColor('--danger', '#BF4D43'), Display: COMPONENT_COLORS.display,
        GPS: COMPONENT_COLORS.gps, Steering: COMPONENT_COLORS.steering,
        JDLink: COMPONENT_COLORS.jdlink
    };
    UNIT_GROUPS.heavy.components.forEach(c => { chipColors[c.label] = COMPONENT_COLORS[c.key]; });

    document.getElementById('issueSummary').innerHTML = Object.entries(issueData.counts).map(([key, count]) => `
        <div class="issue-chip">
            <span class="issue-chip__dot" style="background:${chipColors[key]}"></span>
            <span class="issue-chip__label">${key}</span>
            <span class="issue-chip__count">${count}</span>
        </div>`).join('');

    // Top Issue Chart
    const sorted = Object.entries(issueData.counts).filter(([, v]) => v > 0).sort((a, b) => b[1] - a[1]);
    destroyChart('topIssueChart');
    charts.topIssueChart = makeChart('topIssueChart', {
        type: 'bar',
        data: { labels: sorted.map(x => x[0]), datasets: [{ data: sorted.map(x => x[1]), backgroundColor: sorted.map(x => chipColors[x[0]]), borderRadius: 4, barPercentage: 0.5 }] },
        options: { responsive: true, maintainAspectRatio: false, indexAxis: 'y',
            scales: { x: { beginAtZero: true, ticks: { stepSize: 1, color: dashChartInk(), font: dashChartFont(12) }, grid: dashChartGrid(), border: { display: false } }, y: { ticks: { color: dashChartInk(), font: dashChartFont(12, 600) }, grid: { display: false } } },
            plugins: { legend: { display: false } } }
    });

    // Issues by Site Chart
    const siteCounts = {};
    list.forEach(d => { if (detectIssues(d).length > 0) { const s = d.site || 'Unknown'; siteCounts[s] = (siteCounts[s] || 0) + 1; } });
    const siteLabels = Object.keys(siteCounts).sort();
    destroyChart('issueBySiteChart');
    charts.issueBySiteChart = makeChart('issueBySiteChart', {
        type: 'bar',
        data: { labels: siteLabels, datasets: [{ data: siteLabels.map(s => siteCounts[s]), backgroundColor: themeColor('--dot-warn', '#F79009'), borderRadius: 4, barPercentage: 0.5 }] },
        options: { responsive: true, maintainAspectRatio: false,
            scales: { y: { beginAtZero: true, ticks: { stepSize: 1, color: dashChartInk(), font: dashChartFont(12) }, grid: dashChartGrid(), border: { display: false } }, x: { ticks: { color: dashChartInk(), font: dashChartFont(12) }, grid: { display: false } } },
            plugins: { legend: { display: false } } }
    });

    // Repair Table
    let repairRows = list.filter(d => detectIssues(d).length > 0);
    if (issueFilterVal) repairRows = repairRows.filter(d => detectIssues(d).includes(issueFilterVal));
    const repairBody = document.getElementById('repairBody');
    if (repairRows.length === 0) {
        repairBody.innerHTML = issueFilterVal
            ? `<tr><td colspan="6" style="text-align:center;padding:24px;color:var(--text-secondary)">
                   No units with <strong>${escapeHtml(issueFilterVal)}</strong> issues.
                   <button class="btn btn-secondary btn-sm" style="margin-left:8px"
                           onclick="document.getElementById('issueFilter').value='';renderRepair()">
                       <i class="fas fa-filter-circle-xmark"></i> Show all</button>
               </td></tr>`
            : `<tr><td colspan="6" style="text-align:center;padding:24px;color:var(--text-secondary)">
                   No units with issues. All components read normal.</td></tr>`;
        return;
    }
    repairBody.innerHTML = repairRows.map((d, i) => `
        <tr>
            <td>${i + 1}</td>
            <td><strong>${escapeHtml(d.name)}</strong></td>
            <td>${escapeHtml(d.model)}</td>
            <td style="font-family:monospace;font-size:12px">${escapeHtml(d.sn)}</td>
            <td>${detectIssues(d).map(x => `<span class="badge-component ${issueBadgeClass(x)}">${escapeHtml(x)}</span>`).join(' ')}</td>
            <td>${escapeHtml(d.site)}</td>
        </tr>`).join('');
}

// ============================================================
// FILTERS
// ============================================================

function populateFilters(units) {
    const pool = units || scopeDashUnits();
    const statuses = [...new Set(pool.map(d => d.status))].filter(Boolean).sort();
    const sites = [...new Set(pool.map(d => d.site))].filter(Boolean).sort();
    // Rebuilt on every snapshot, so the choice is carried across — otherwise
    // a teammate's edit silently reset someone's Breakdown filter.
    const fill = (id, head, list) => {
        const el = document.getElementById(id);
        const keep = el.value;
        el.innerHTML = head + list.map(s => `<option value="${escapeHtml(s)}">${escapeHtml(s)}</option>`).join('');
        if (keep && list.includes(keep)) el.value = keep;
    };
    fill('statusFilter', `<option value="">All Status</option>`, statuses);
    fill('siteFilter', `<option value="">All Sites</option>`, sites);
}

function applyFilterLogic() {
    const keyword = document.getElementById('searchInput').value.toLowerCase();
    const statusVal = document.getElementById('statusFilter').value;
    const siteVal = document.getElementById('siteFilter').value;
    const compVal = document.getElementById('componentFilter').value;

    // The group scope is applied here, inside the filter, so every re-render —
    // a snapshot, a reset, a restore — keeps the group the user chose.
    return scopeDashUnits().filter(d => {
        if (statusVal && d.status !== statusVal) return false;
        if (siteVal && d.site !== siteVal) return false;
        const hay = isHeavy(d) ? `${d.name} ${d.brand || ''} ${d.model} ${d.sn} ${d.machineType || ''} ${d.assetCode || ''}` : `${d.name} ${d.model} ${d.sn}`;
        if (keyword && !hay.toLowerCase().includes(keyword)) return false;
        if (compVal && !detectIssues(d).includes(compVal)) return false;
        return true;
    });
}

function applyFilter() {
    filteredData = applyFilterLogic();
    sortState.key = null;
    updateDashboard(filteredData);
}

function clearFilter() {
    document.getElementById('searchInput').value = '';
    document.getElementById('statusFilter').value = '';
    document.getElementById('siteFilter').value = '';
    document.getElementById('componentFilter').value = '';
    filteredData = scopeDashUnits();
    sortState.key = null;
    updateDashboard(filteredData);
}

function updateFilterCount(data) {
    const el = document.getElementById('filterCount');
    const total = scopeDashUnits().length;
    el.textContent = data.length === total ? `${total} units` : `${data.length} of ${total} units`;
}

// ============================================================
// EXPORT
// ============================================================

function exportCSV(data) {
    if (!canCsv('export')) return;
    const exportData = Array.isArray(data) ? data : filteredData;
    if (exportData.length === 0) { showToast('No data to export', 'warning'); return; }
    // Three shapes. No heavy rows: today's file, verbatim. Heavy only: its own
    // columns. Mixed: today's 21 columns plus the heavy ones. Every shape that
    // holds heavy rows carries "Unit Group", so exporting and re-importing as
    // new units keeps each unit in its group.
    const heavyN = exportData.filter(isHeavy).length;
    if (heavyN) { exportUnitsCSVGrouped(exportData, heavyN === exportData.length); return; }
    const headers = ['No', 'Nickname', 'Model', 'Serial Number', 'Implement', 'Status', 'Display', 'GPS', 'Steering', 'JDLink', 'Site',
                     'Year Received', 'User Category', 'GPS License', 'Display License',
                     'GPS License Start Date', 'GPS License Expiration Date',
                     'Display License Start Date', 'Display License Expiration Date', 'Remarks', 'Breakdown Reason'];
    const rows = exportData.map((d, i) => [i + 1, d.name, d.model, d.sn, d.implement || '', d.status, d.display, d.gps, d.steering, d.jdlink, d.site,
                     d.yearReceived || '', d.userCategory || '',
                     effectiveLicense(d, 'gps').type || '', effectiveLicense(d, 'display').type || '',
                     d.gpsLicenseStartDate || d.licenseStartDate || '',
                     d.gpsLicenseEndDate   || d.licenseEndDate   || '',
                     d.displayLicenseStartDate || '',
                     d.displayLicenseEndDate   || '',
                     d.remarks || '',
                     (!isGood(d.status) && d.breakdownReason) ? d.breakdownReason : '']);
    const csv = [headers, ...rows].map(row => row.map(csvCell).join(',')).join('\n');
    const blob = new Blob(['\uFEFF' + csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `tractor_monitoring_${toISODate()}.csv`;
    a.click();
    URL.revokeObjectURL(url);
    showToast(`${exportData.length} unit(s) exported to CSV`, 'success');
}

function exportUnitsCSVGrouped(exportData, heavyOnly) {
    const HEAVY_COLS = ['Brand', 'Machine Type', 'Asset Code', 'Work Tool', ...UNIT_GROUPS.heavy.components.map(c => c.label)];
    const heavyCells = d => [d.brand || '', d.machineType || '', d.assetCode || '', d.workTool || '',
                             ...UNIT_GROUPS.heavy.components.map(c => d[c.key] || '')];
    let headers, rows, prefix;
    if (heavyOnly) {
        headers = ['No', 'Unit Group', 'Nickname', 'Brand', 'Model', 'Serial Number', 'Machine Type', 'Asset Code', 'Work Tool', 'Status',
                   ...UNIT_GROUPS.heavy.components.map(c => c.label),
                   'Site', 'Year Received', 'User Category', 'Remarks', 'Breakdown Reason'];
        rows = exportData.map((d, i) => [i + 1, 'heavy', d.name, d.brand || '', d.model, d.sn, d.machineType || '', d.assetCode || '', d.workTool || '',
                   d.status, ...UNIT_GROUPS.heavy.components.map(c => d[c.key] || ''),
                   d.site, d.yearReceived || '', d.userCategory || '', d.remarks || '',
                   (!isGood(d.status) && d.breakdownReason) ? d.breakdownReason : '']);
        prefix = UNIT_GROUPS.heavy.csvPrefix;
    } else {
        headers = ['No', 'Nickname', 'Model', 'Serial Number', 'Implement', 'Status', 'Display', 'GPS', 'Steering', 'JDLink', 'Site',
                   'Year Received', 'User Category', 'GPS License', 'Display License',
                   'GPS License Start Date', 'GPS License Expiration Date',
                   'Display License Start Date', 'Display License Expiration Date', 'Remarks', 'Breakdown Reason',
                   'Unit Group', ...HEAVY_COLS];
        rows = exportData.map((d, i) => {
            const h = isHeavy(d);
            // A row never reads the other group's fields.
            return [i + 1, d.name, d.model, d.sn, h ? '' : (d.implement || ''), d.status,
                h ? '' : d.display, h ? '' : d.gps, h ? '' : d.steering, h ? '' : d.jdlink, d.site,
                d.yearReceived || '', d.userCategory || '',
                h ? '' : (effectiveLicense(d, 'gps').type || ''), h ? '' : (effectiveLicense(d, 'display').type || ''),
                h ? '' : (d.gpsLicenseStartDate || d.licenseStartDate || ''),
                h ? '' : (d.gpsLicenseEndDate || d.licenseEndDate || ''),
                h ? '' : (d.displayLicenseStartDate || ''), h ? '' : (d.displayLicenseEndDate || ''),
                d.remarks || '', (!isGood(d.status) && d.breakdownReason) ? d.breakdownReason : '',
                unitGroupOf(d), ...(h ? heavyCells(d) : HEAVY_COLS.map(() => ''))];
        });
        prefix = 'unit_monitoring';
    }
    const csv = [headers, ...rows].map(row => row.map(csvCell).join(',')).join('\n');
    const blob = new Blob(['\uFEFF' + csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `${prefix}_${toISODate()}.csv`;
    a.click();
    URL.revokeObjectURL(url);
    showToast(`${exportData.length} unit(s) exported to CSV`, 'success');
}

// Export the units currently visible in the Edit Units table (honors its
// search + status/site filters and sort). Falls back to all units when no
// filter is active.
function exportEditCSV() {
    exportCSV(getEditTableRows());
}

