function destroyChart(id) {
    if (charts[id]) { charts[id].destroy(); delete charts[id]; }
    const oldCanvas = document.getElementById(id);
    if (oldCanvas) {
        const newCanvas = document.createElement('canvas');
        newCanvas.id = id;
        oldCanvas.parentNode.replaceChild(newCanvas, oldCanvas);
    }
}

// ============================================================
// EDIT UNITS PAGE
// ============================================================

function updateEditCount() {
    const el = document.getElementById('editUnitCount');
    if (!el) return;
    // Unchanged until heavy equipment exists.
    if (!hasHeavyUnits()) { el.textContent = `${globalData.length} unit(s) in database`; return; }
    const g = effectiveEditGroup();
    el.textContent = `${unitsOfGroup(globalData, g).length} ${groupDef(g).label} · ${globalData.length} unit(s) in database`;
}

function toggleImportPanel() {
    document.getElementById('importPanel').classList.toggle('open');
}

function handleEditCSVImport(file) {
    if (!canCsv('full')) return;
    if (!requireEdit('editUnits')) return;
    showLoading(true);
    Papa.parse(file, {
        header: true,
        skipEmptyLines: true,
        complete: result => {
            const tab = effectiveEditGroup();
            const { valid, rejected, groupWarnings } = processData(result.data,
                { fallbackGroup: tab, fileGroup: inferCsvGroup(result.meta && result.meta.fields) });

            // Split rows into brand-new units vs updates to existing SNs
            const existingSNs = new Set(globalData.map(d => (d.sn || '').toLowerCase()).filter(Boolean));
            const newUnits = [];
            const updateCandidates = [];
            valid.forEach(u => {
                if (existingSNs.has((u.sn || '').toLowerCase())) updateCandidates.push(u);
                else newUnits.push(u);
            });

            // Asked BEFORE anything is written: new units about to land in the
            // group other than the open tab. Cancel aborts the whole import.
            const offTab = newUnits.filter(u => u.unitGroup !== tab);
            if (offTab.length && !confirm(
                `${offTab.length} new unit(s) will be added as ${groupDef(otherGroup(tab).key).label}, not ${groupDef(tab).label}. Continue?\n\n` +
                `Cancel = cancel the whole import (nothing is written).`)) {
                showLoading(false);
                document.getElementById('importPanel').classList.remove('open');
                showToast('Import cancelled — nothing was written', 'info');
                return;
            }
            const notes = [];
            // Implements list: the list's spelling, or nothing. A new unit
            // lands with no implement; an update leaves the old one.
            if (implementListActive()) valid.forEach(u => {
                if (unitGroupOf(u) !== 'tractor' || !u.implement) return;
                const r = checkImplementValue(u.implement, null);
                if (r.ok) { u.implement = r.value; return; }
                notes.push({ name: u.name, sn: u.sn, reason: `Implement "${r.value}" is not in the Implements list — `
                    + (existingSNs.has((u.sn || '').toLowerCase()) ? 'left unchanged' : 'left empty') });
                u.implement = '';
            });
            if (masterListActive('heavyBrand')) valid.forEach(u => {
                if (unitGroupOf(u) !== 'heavy' || !u.brand) return;
                const r = checkMasterValue('heavyBrand', u.brand, null);
                if (r.ok) { u.brand = r.value; return; }
                notes.push({ name: u.name, sn: u.sn, reason: `Brand "${r.value}" is not in the Heavy Equipment Brand list — `
                    + (existingSNs.has((u.sn || '').toLowerCase()) ? 'left unchanged' : 'left empty') });
                delete u.brand;
            });
            if (masterListActive('site')) valid.forEach(u => {
                if (!u.site) return;
                const r = checkMasterValue('site', u.site, null);
                if (r.ok) { u.site = r.value; return; }
                notes.push({ name: u.name, sn: u.sn, reason: `Site "${r.value}" is not in the Site list — `
                    + (existingSNs.has((u.sn || '').toLowerCase()) ? 'left unchanged' : 'left empty') });
                u.site = '';
            });
            groupWarnings.forEach(w => notes.push({ name: w.name, sn: w.sn,
                reason: `Unknown Unit Group "${w.value}" — read as ${groupDef(w.group || tab).label}` }));
            valid.forEach(u => {
                const g = unitGroupOf(u);
                // Tractor sheets keep their own "Nomor Lambung" and "Jenis
                // Alat" columns (see inferCsvGroup). Dropping them is right;
                // calling it a mistake on every row is not.
                const ignored = otherGroup(g).onlyFields.filter(f => !sameStoredValue(u[f], ''))
                    .filter(f => !(g === 'tractor' && CSV_SHARED_HEADER_FIELDS.includes(f)));
                if (ignored.length) notes.push({ name: u.name, sn: u.sn,
                    reason: `column(s) ${ignored.join(', ')} ignored: not used by ${groupDef(g).shortLabel}` });
            });
            const blank = newUnits.filter(u => u.unitGroup === 'heavy' && HEAVY_COMPONENT_KEYS.every(k => sameStoredValue(u[k], ''))).length;
            if (blank) notes.push({ name: `${blank} unit`, sn: '-',
                reason: `${UNIT_GROUPS.heavy.shortLabel} with no component status — counted as having issues until filled in` });

            let updateResult = { updated: 0, unchanged: 0, failed: [] };
            let updatesAsSkipped = [];
            if (updateCandidates.length > 0) {
                const bySn = new Map(globalData.map(u => [(u.sn || '').toLowerCase(), u]));
                const goodHeld = updateCandidates.filter(p => {
                    const u = bySn.get((p.sn || '').toLowerCase());
                    if (!u || !isHeavy(u)) return false;
                    return ['status', ...HEAVY_COMPONENT_KEYS].some(f => {
                        const v = p[f];
                        return v !== undefined && v !== null && String(v).trim() !== '' && !sameStoredValue(v, u[f])
                            && isGood(v) && !isGood(u[f]) && openDamageHolders(u, f).length > 0;
                    });
                }).length;
                const doUpdate = confirm(
                    `${updateCandidates.length} unit(s) with the same Serial Number already exist in the database.\n\n` +
                    (goodHeld ? `${goodHeld} heavy unit(s) would be set Good (status or a component) while damage records still hold them in Breakdown — those records stay open.\n\n` : '') +
                    `OK = UPDATE the fields filled in the CSV\n` +
                    `Cancel = SKIP (only add new units)`
                );
                if (doUpdate) {
                    updateResult = bulkUpdateUnitsFromCSV(updateCandidates);
                } else {
                    updatesAsSkipped = updateCandidates.map(u => ({ name: u.name, sn: u.sn, reason: 'Duplicate serial number' }));
                }
            }

            const { added, skipped, skippedDetails } = addUnits(newUnits);
            showImportReport({
                total: result.data.length, added,
                skipped: skipped + updatesAsSkipped.length,
                skippedDetails: [...skippedDetails, ...updatesAsSkipped],
                rejected,
                updated: updateResult.updated,
                unchanged: updateResult.unchanged,
                updateFailed: updateResult.failed,
                notes
            });
            renderEditTable();
            showLoading(false);
            document.getElementById('importPanel').classList.remove('open');
        },
        error: err => {
            showToast('Failed to read CSV: ' + err.message, 'error');
            showLoading(false);
        }
    });
}

// `notes` carries the unit-group warnings (unknown Unit Group values, columns
// of the other group that were ignored, heavy units with no component status).
// A tractor CSV produces none, so its toast and report are unchanged.
function showImportReport({ total, added, skipped, skippedDetails, rejected, updated = 0, unchanged = 0, updateFailed = [], notes = [] }) {
    const hasIssues = skipped > 0 || rejected.length > 0 || updateFailed.length > 0 || notes.length > 0;
    const type = (added > 0 || updated > 0) ? (hasIssues ? 'warning' : 'success') : 'warning';

    const parts = [`${added} added`];
    if (updated > 0) parts.push(`${updated} updated`);
    if (unchanged > 0) parts.push(`${unchanged} unchanged`);
    if (skipped > 0) parts.push(`${skipped} duplicate(s) skipped`);
    if (rejected.length > 0) parts.push(`${rejected.length} rejected`);
    if (updateFailed.length > 0) parts.push(`${updateFailed.length} update failed`);
    const summary = parts.join(' · ');
    showToast(`Import: ${summary} (from ${total} rows)`, type);

    if (!hasIssues) return;

    const rows = [
        ...skippedDetails.map(d => `<tr><td>${escapeHtml(d.name || '-')}</td><td style="font-family:monospace">${escapeHtml(d.sn || '-')}</td><td>${escapeHtml(d.reason)}</td></tr>`),
        ...updateFailed.map(f => `<tr><td>-</td><td style="font-family:monospace">${escapeHtml(f.sn || '-')}</td><td>${escapeHtml(f.reason)}</td></tr>`),
        ...rejected.map(r => `<tr><td>${escapeHtml(r.name || '-')}</td><td>Row ${r.row}</td><td>${escapeHtml(r.reason)}</td></tr>`),
        ...notes.map(n => `<tr><td>${escapeHtml(n.name || '-')}</td><td style="font-family:monospace">${escapeHtml(n.sn || '-')}</td><td>${escapeHtml(n.reason)}</td></tr>`)
    ].join('');

    document.getElementById('importReportBody').innerHTML = rows;
    document.getElementById('importReportSummary').textContent = summary;
    document.getElementById('importReportModal').classList.add('open');
}

// A restore used to end with one toast naming the collections it had written.
// Anything absent from the file produced no line at all, so a v3 backup looked
// like a complete restore. This lists every collection the app knows about,
// including the ones that were not in the file and the ones skipped for lack
// of rights — the two outcomes people most need to see.
function showRestoreReport(rows, version, merge) {
    const missing = rows.filter(r => r.note === 'not in this file').length;
    const done = rows.filter(r => /^(merged|replaced)/.test(r.note)).length;
    const summary = `${done} collection(s) ${merge ? 'merged' : 'replaced'}`
        + (missing ? ` · ${missing} collection(s) not in this file` : '');

    const excluded = BACKUP_EXCLUDED.map(e =>
        `<tr><td>${escapeHtml(e.label)}</td><td>—</td><td>never backed up — ${escapeHtml(e.why)}</td></tr>`).join('');
    const body = rows.map(r =>
        `<tr><td data-label="Collection">${escapeHtml(r.label)}</td>`
        + `<td data-label="Count">${escapeHtml(String(r.count))}</td>`
        + `<td data-label="Details">${escapeHtml(r.note)}</td></tr>`).join('');

    const note = document.getElementById('restoreReportNote');
    if (note) {
        note.innerHTML = version < 4
            ? `<strong>Old backup (v${version || '?'}).</strong> This file was made before Team and Inventory data were included in backups, so that data is not in it and was not changed at all.`
            : '';
        note.style.display = version < 4 ? '' : 'none';
    }
    const sum = document.getElementById('restoreReportSummary');
    if (sum) sum.textContent = summary;
    const tbody = document.getElementById('restoreReportBody');
    if (tbody) tbody.innerHTML = body + excluded;
    const modal = document.getElementById('restoreReportModal');
    if (modal) modal.classList.add('open');
    else showToast(summary, missing ? 'warning' : 'success');
}

// ---- Auto backup ring ----
// writeAutoBackup() has pushed a full copy of the units array into
// localStorage on every save since the first version, keeping three. Nothing
// in the repo ever read it: the quota — the same quota the damage photos were
// moved out of — was paying for three rollback points nobody could reach.
// These three functions are that missing half.
function readAutoBackups() {
    try {
        const ring = JSON.parse(localStorage.getItem(BACKUP_RING_KEY) || '[]');
        return Array.isArray(ring) ? ring.slice().reverse() : [];   // newest first
    } catch (e) { return []; }
}

function showAutoBackups() {
    if (!isOwner || !isOwner()) { showToast('Only the owner can restore automatic backups', 'warning'); return; }
    const ring = readAutoBackups();
    const list = document.getElementById('autoBackupList');
    if (list) {
        list.innerHTML = ring.length === 0
            ? '<li style="color:var(--text-secondary);padding:8px 0">No automatic backups on this device yet.</li>'
            : ring.map((b, i) => {
                const when = b.at ? new Date(b.at).toLocaleString('en-GB',
                    { day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' }) : '—';
                return `<li>
                    <span><strong>${escapeHtml(when)}</strong>
                        <span style="color:var(--text-secondary)"> · ${Number(b.count) || 0} units</span></span>
                    <button class="btn btn-secondary btn-sm" onclick="restoreAutoBackup(${i})">
                        <i class="fas fa-rotate-left"></i> Restore</button>
                </li>`;
            }).join('');
    }
    document.getElementById('autoBackupModal').classList.add('open');
}

function closeAutoBackups() {
    document.getElementById('autoBackupModal').classList.remove('open');
}

// Goes through the same cloud-mirrored replace as a file restore. A local-only
// rollback would be undone by the next units snapshot, and the units it
// removed would come straight back.
// A unit's group never changes, so a backup copy and the live copy of the
// same id always agree on it — unless something went wrong. A REPLACE restore
// that would change a live unit's group is refused before anything is written:
// the write is set(merge:true), so the old group would come back alongside
// fields of the new one.
// opts.auto: the rollback ring, which is this device's own earlier state.
function _refuseCrossGroupRestore(units, opts) {
    const auto = !!(opts && opts.auto);
    // A group this version cannot read, coming in from a FILE, would land as a
    // tractor that is not one — and GANTI writes every row, so refuse before
    // anything moves. GABUNG goes through addUnits, which skips such rows and
    // names them. The rollback ring is exempt: every entry is a copy of what
    // was live, so refusing it would make rollback impossible for as long as
    // one such unit exists — and a restored one is fenced exactly like a live
    // one (guardUnitFields, Periksa Data → Tetapkan kelompok).
    const unreadable = auto ? [] : (units || []).filter(hasUnreadableGroup);
    if (unreadable.length) {
        const kinds = [...new Set(unreadable.map(u => String(u.unitGroup)))].slice(0, 3)
            .map(v => `"${v}"`).join(', ');
        showToast(`Restore cancelled: ${unreadable.length} unit(s) in the backup have an unknown group (${kinds}). `
            + `Change the value in the file to "tractor" or "heavy", or choose MERGE — those units will be skipped.`, 'error');
        return true;
    }
    // Only two READABLE groups can conflict. A side whose group is unreadable
    // is not a group to protect: restoring over it (or back to it) changes
    // nothing the firewall does not already fence.
    const live = new Map(globalData.map(u => [u.id, u]));
    const conflicts = (units || []).filter(u => u && u.id && live.has(u.id)
        && !hasUnreadableGroup(u) && !hasUnreadableGroup(live.get(u.id))
        && unitGroupOf(live.get(u.id)) !== unitGroupOf(u));
    if (!conflicts.length) return false;
    showToast(`Restore cancelled: ${conflicts.length} unit(s) in the backup have a different group from the current data (same id). `
        + (auto ? 'Delete those units first, or restore from a backup file.' : 'Delete those units first, or choose MERGE.'), 'error');
    return true;
}

function restoreAutoBackup(index) {
    if (!isOwner || !isOwner()) return;
    if (!canWriteUnits('restore cadangan otomatis')) return;
    const ring = readAutoBackups();
    const entry = ring[index];
    if (!entry || !Array.isArray(entry.units)) { showToast('That backup cannot be read', 'error'); return; }

    if (_refuseCrossGroupRestore(entry.units, { auto: true })) return;
    const when = entry.at ? new Date(entry.at).toLocaleString('en-GB') : 'unknown time';
    if (!confirm(`Restore ${entry.units.length} unit(s) to their state at ${when}?\n\n`
        + `The ${globalData.length} current unit(s) will be replaced. Other data (damage, licenses, team, inventory) is not changed.`)) return;

    const previousIds = globalData.map(u => u.id);
    globalData = entry.units.map(u => ({ ...u, id: u.id || generateId(), unitGroup: storedUnitGroup(u) }));
    const keptIds = new Set(globalData.map(u => u.id));
    saveToStorage(globalData);
    cloudDeleteUnits(previousIds.filter(id => !keptIds.has(id)));
    cloudPushUnits(globalData);
    logEvent({ action: 'restore', unitName: '-', after: `${globalData.length} unit(s) restored from automatic backup (${when})` });
    closeAutoBackups();
    renderEditTable();
    filteredData = scopeDashUnits();
    updateDashboard(filteredData);
    showToast(`${globalData.length} unit(s) restored to their state at ${when}`, 'success');
}

function closeRestoreReport() {
    const m = document.getElementById('restoreReportModal');
    if (m) m.classList.remove('open');
}

function closeImportReport() {
    document.getElementById('importReportModal').classList.remove('open');
}

// ---- Edit Table ----
// Compute the rows shown in the Edit Units table — honors the search box,
// status/site filters and the active sort. Shared by renderEditTable() and
// the Export CSV button so both stay in sync.
// ---- Units per implement / work tool ----
// Agricultural units carry an implement, heavy units a work tool (Alat
// Kerja). The summary counts the open tab's units by that field, under the
// status and site filters but not the search box, and a row of it filters
// the table. Spellings that differ only in case or spacing count together.
//
// An implement reads "Type — Brand" (implementOptionLabel), so the summary
// counts per TYPE and lists the brands under each one: "Bed Ripper 2 —
// Gessner 1 · ISJ 1". Clicking the type filters every unit of that type,
// clicking a brand only that brand's. Work tools have no brand.
let editToolFilter = '';           // '' = all, TOOL_NONE = none set, typeKey, or typeKey + TOOL_SEP + brandKey
const TOOL_NONE = '__none__';
const TOOL_SEP = '\u0001';
let _toolSummaryOpen = false;
let editMissingFilter = '';        // a REQUIRED_UNIT_FIELDS key: only units missing it
// Key fields per group: what a unit needs for the summaries, the per-company
// split and the inspection list to be right.
const REQUIRED_UNIT_FIELDS = {
    tractor: ['model', 'implement', 'site', 'yearReceived'],
    heavy:   ['brand', 'model', 'machineType', 'assetCode', 'workTool', 'site', 'yearReceived']
};
const REQUIRED_FIELD_LABEL = {
    brand: 'brand', model: 'model', implement: 'implement', site: 'site', yearReceived: 'year received',
    machineType: 'machine type', assetCode: 'asset no.', workTool: 'work tool'
};

function toolFieldOf(g) { return g === 'heavy' ? 'workTool' : 'implement'; }
const _toolNorm = v => String(v || '').trim().replace(/\s+/g, ' ');

const _splitTool = raw => raw.split(/\s+[—–]\s+|\s+-\s+/).map(_toolNorm).filter(Boolean);

// How "brand-like" each name is: + each time it is the brand half of a
// unit's "Type — Brand", − each time it is the type half, and decisively so
// when the Implements database says. Used to recognise an old "Brand — Type"
// value written the other way round ("ISS — Final Cultivator").
function _knownImplementBrands() {
    const score = new Map();
    const add = (name, n) => { const k = _toolNorm(name).toLowerCase(); if (k) score.set(k, (score.get(k) || 0) + n); };
    globalImplements.forEach(i => { add(i.brand, 1000); add(i.equipmentType, -1000); });
    // Each distinct spelling counts once, so ten units sharing one reversed
    // value do not outvote the rest of the fleet.
    const pairs = new Set();
    new Set(globalData.map(u => _toolNorm(u && u.implement).toLowerCase())).forEach(raw => {
        const parts = _splitTool(raw);
        if (parts.length === 2) { add(parts[0], -1); add(parts[1], 1); pairs.add(parts[0] + '|' + parts[1]); }
    });
    score.pairs = pairs;
    return score;
}

// { type, brand } of one unit's implement / work tool. Prefers the
// Implements record the text refers to; otherwise splits "Type — Brand".
function toolPartsOf(u, g, brands) {
    const raw = _toolNorm(u && u[toolFieldOf(g)]);
    if (!raw) return { type: '', brand: '' };
    if (g === 'heavy') return { type: raw, brand: '' };
    const imp = matchImplementForUnit(raw);
    if (imp && _toolNorm(imp.equipmentType)) return { type: _toolNorm(imp.equipmentType), brand: _toolNorm(imp.brand) };
    const parts = _splitTool(raw);
    if (parts.length < 2) return { type: raw, brand: '' };
    let [type, brand] = [parts[0], parts.slice(1).join(' — ')];
    const known = brands || _knownImplementBrands();
    // Judged on the OTHER spellings only: "A — B" and "B — A" vote for
    // opposite answers about this very pair, so both are left out.
    const a = type.toLowerCase(), b = brand.toLowerCase();
    const pairs = known.pairs || new Set();
    const ab = pairs.has(a + '|' + b) ? 1 : 0, ba = pairs.has(b + '|' + a) ? 1 : 0;
    const scType = (known.get(a) || 0) + ab - ba;
    const scBrand = (known.get(b) || 0) - ab + ba;
    if (scType > 0 && scType > scBrand) [type, brand] = [brand, type];
    return { type, brand };
}

function toolKeyOf(u, g, brands) {
    const t = toolPartsOf(u, g, brands).type.toLowerCase();
    return t || TOOL_NONE;
}
function _toolFullKey(u, g, brands) {
    const p = toolPartsOf(u, g, brands);
    if (!p.type) return TOOL_NONE;
    return p.type.toLowerCase() + TOOL_SEP + p.brand.toLowerCase();
}
// Does unit u pass the summary filter?
function toolFilterMatch(u, g, filter, brands) {
    if (!filter) return true;
    return filter.includes(TOOL_SEP) ? _toolFullKey(u, g, brands) === filter : toolKeyOf(u, g, brands) === filter;
}

// Most common spelling wins as the label.
function _pickLabel(spellings) {
    return [...spellings.entries()].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))[0][0];
}

function toolSummaryRows(g) {
    const statusVal = document.getElementById('editStatusFilter')?.value || '';
    const siteVal = document.getElementById('editSiteFilter')?.value || '';
    const units = unitsOfGroup(globalData, g)
        .filter(d => (!statusVal || d.status === statusVal) && (!siteVal || d.site === siteVal));
    const known = _knownImplementBrands();
    const map = new Map();
    units.forEach(u => {
        const p = toolPartsOf(u, g, known);
        const k = p.type ? p.type.toLowerCase() : TOOL_NONE;
        const cur = map.get(k) || { key: k, spell: new Map(), count: 0, brands: new Map() };
        cur.count++;
        if (p.type) {
            cur.spell.set(p.type, (cur.spell.get(p.type) || 0) + 1);
            const bk = p.brand.toLowerCase();
            const b = cur.brands.get(bk) || { key: k + TOOL_SEP + bk, spell: new Map(), count: 0, none: !p.brand };
            b.count++;
            if (p.brand) b.spell.set(p.brand, (b.spell.get(p.brand) || 0) + 1);
            cur.brands.set(bk, b);
        }
        map.set(k, cur);
    });
    const rows = [...map.values()].map(r => ({
        key: r.key, count: r.count,
        label: r.key === TOOL_NONE ? '' : _pickLabel(r.spell),
        brands: [...r.brands.values()].map(b => ({ key: b.key, count: b.count, none: b.none, label: b.none ? '' : _pickLabel(b.spell) }))
            .sort((a, b) => a.none - b.none || b.count - a.count || a.label.localeCompare(b.label))
    })).sort((a, b) =>
        (a.key === TOOL_NONE) - (b.key === TOOL_NONE) || b.count - a.count || a.label.localeCompare(b.label));
    return { rows, total: units.length };
}

function renderToolSummary() {
    const box = document.getElementById('toolSummary');
    if (!box) return;
    const g = effectiveEditGroup();
    const { rows, total } = toolSummaryRows(g);
    if (!total) { box.style.display = 'none'; box.innerHTML = ''; return; }
    const nounEn = g === 'heavy' ? 'Work Tool' : 'Implement';
    const named = rows.filter(r => r.key !== TOOL_NONE);
    const none = rows.filter(r => r.key === TOOL_NONE);
    const withTool = named.reduce((n, r) => n + r.count, 0);
    const kinds = named.length;
    const brandCount = new Set(named.flatMap(r => r.brands.filter(b => !b.none).map(b => b.label.toLowerCase()))).size;
    const LIMIT = 8;
    // "No …" always shows: units missing the field are the thing to fix.
    const shown = (_toolSummaryOpen || named.length <= LIMIT ? named : named.slice(0, LIMIT)).concat(none);
    const max = Math.max(...rows.map(r => r.count));
    const brandLine = r => {
        // A type nobody gave a brand has nothing to break down.
        if (!r.brands.length || (r.brands.length === 1 && r.brands[0].none)) return '';
        return `<div class="tool-brands">${r.brands.map(b => {
            const on = editToolFilter === b.key;
            return `<button type="button" class="tool-brand${on ? ' is-on' : ''}${b.none ? ' tool-brand--none' : ''}" aria-pressed="${on}"
                title="${on ? 'Click again to show all' : 'Show only these units in the table'}" onclick="setEditToolFilter(${jsArg(b.key)})">${
                escapeHtml(b.none ? 'No brand' : b.label)} <b>${b.count}</b></button>`;
        }).join('')}</div>`;
    };
    box.innerHTML = `
        <div class="tool-summary__head">
            <div class="tool-summary__title"><i class="fas ${g === 'heavy' ? 'fa-screwdriver-wrench' : 'fa-trailer'}"></i>
                Units per ${nounEn}${g === 'heavy' ? '' : ' Type'}</div>
            <div class="tool-summary__meta">${withTool} of ${total} units have ${nounEn === 'Implement' ? 'an implement' : 'a work tool'} · ${kinds} ${kinds === 1 ? 'type' : 'types'}${
                brandCount ? ` · ${brandCount} ${brandCount === 1 ? 'brand' : 'brands'}` : ''}
                ${editToolFilter ? `<button type="button" class="btn btn-secondary btn-sm" onclick="setEditToolFilter('')">
                    <i class="fas fa-filter-circle-xmark"></i> Show all</button>` : ''}</div>
        </div>
        <div class="tool-summary__list">
            ${shown.map(r => {
                const pct = Math.round(r.count / total * 100);
                const on = editToolFilter === r.key;
                const name = r.key === TOOL_NONE ? `No ${nounEn.toLowerCase()}` : r.label;
                return `<div class="tool-item">
                    <button type="button" class="tool-row${on ? ' is-on' : ''}${r.key === TOOL_NONE ? ' tool-row--none' : ''}"
                        aria-pressed="${on}" title="${on ? 'Click again to show all' : 'Show only these units in the table'}"
                        onclick="setEditToolFilter(${jsArg(r.key)})">
                    <span class="tool-row__name">${escapeHtml(name)}</span>
                    <span class="tool-row__bar"><span style="width:${Math.max(3, Math.round(r.count / max * 100))}%"></span></span>
                    <span class="tool-row__count">${r.count}<small>${pct}%</small></span>
                </button>${brandLine(r)}</div>`;
            }).join('')}
        </div>
        ${named.length > LIMIT ? `<button type="button" class="tool-summary__more" onclick="toggleToolSummary()">
            ${_toolSummaryOpen ? 'Show less' : `+${named.length - LIMIT} more types`}</button>` : ''}`;
    box.style.display = '';
}

function setEditToolFilter(key) {
    editToolFilter = editToolFilter === key ? '' : (key || '');
    renderEditTable();
}

function toggleToolSummary() {
    _toolSummaryOpen = !_toolSummaryOpen;
    renderToolSummary();
}

function getEditTableRows() {
    const query = (document.getElementById('editSearch')?.value || '').toLowerCase().trim();
    const statusVal = (document.getElementById('editStatusFilter')?.value || '');
    const siteVal = (document.getElementById('editSiteFilter')?.value || '');

    const g = effectiveEditGroup();
    let rows = unitsOfGroup(globalData, g);
    if (query) rows = rows.filter(d => (g === 'heavy'
        ? `${d.name} ${d.brand || ''} ${d.model} ${d.sn} ${d.machineType || ''} ${d.assetCode || ''} ${d.workTool || ''} ${d.site}`
        : `${d.name} ${d.model} ${d.sn} ${d.implement || ''} ${d.site}`).toLowerCase().includes(query));
    if (statusVal) rows = rows.filter(d => d.status === statusVal);
    if (siteVal) rows = rows.filter(d => d.site === siteVal);
    if (editMissingFilter === MISSING_ANY) {
        const fields = REQUIRED_UNIT_FIELDS[g] || [];
        rows = rows.filter(d => fields.some(f => isFieldMissing(d, f)));
    } else if (editMissingFilter) rows = rows.filter(d => isFieldMissing(d, editMissingFilter));
    if (editQuickFilter && !(editQuickFilter === 'license' && !groupDef(g).hasLicences)) {
        rows = rows.filter(d => quickFilterMatch(d, editQuickFilter));
    }
    if (editToolFilter) {
        const known = _knownImplementBrands();
        rows = rows.filter(d => toolFilterMatch(d, g, editToolFilter, known));
    }

    if (editSortState.key && editSortState.key !== 'no') {
        const k = editSortState.key;
        rows.sort((a, b) => {
            const va = String(_resolveSortValue(a, k) ?? "").toLowerCase(), vb = String(_resolveSortValue(b, k) ?? "").toLowerCase();
            if (va < vb) return editSortState.asc ? -1 : 1;
            if (va > vb) return editSortState.asc ? 1 : -1;
            return 0;
        });
    }
    return rows;
}

function toggleCompactMode() {
    const table = document.getElementById('editTable');
    if (!table) return;
    const isCompact = table.classList.toggle('compact');
    localStorage.setItem('editTableCompact', isCompact ? '1' : '');
    const icon = document.querySelector('#compactToggle i');
    if (icon) {
        icon.className = isCompact ? 'fas fa-expand' : 'fas fa-compress';
    }
}

// ---- Edit Units: one table per group ----
// The tractor header is captured from the static markup at startup and put
// back verbatim; only the heavy tab gets a header built here.
const EDIT_COLSPAN = { tractor: 21, heavy: 20 };
function sortTh(key, label, fn) {
    return `<th tabindex="0" role="button" onclick="${fn}('${key}')">${label} <span class="sort-icon"><i class="fas fa-sort"></i></span></th>`;
}
function heavyEditHead() {
    const s = (k, l) => sortTh(k, l, 'sortEditTable');
    return `<tr>
        <th class="col-check"><input type="checkbox" id="selectAll" aria-label="Select all units" onchange="toggleSelectAll()"></th>
        ${s('no', 'No')}${s('name', 'Nickname')}${s('brand', 'Brand')}${s('model', 'Model')}${s('sn', 'Serial Number')}
        ${s('machineType', 'Machine Type')}${s('assetCode', 'Asset No.')}${s('workTool', 'Work Tool')}${s('status', 'Status')}
        ${UNIT_GROUPS.heavy.components.map(c => s(c.key, c.label)).join('')}
        ${s('site', 'Site')}${s('yearReceived', 'Year Received')}${s('userCategory', 'User Category')}
        <th>Remarks</th><th>Attachments</th><th class="col-actions">Actions</th>
    </tr>`;
}
function renderEditHead() {
    const g = effectiveEditGroup();
    const head = document.querySelector('#editTable thead');
    if (head && _editHeadGroup !== g) {
        head.innerHTML = g === 'heavy' ? heavyEditHead() : EDIT_HEADS.tractor;
        _editHeadGroup = g;
    }
    markSortedHeader('#editTable thead', editSortState.key, editSortState.asc);
}

// The group is picked in the sidebar (Agricultural / Heavy Equipment) or in
// the page head's switch, and the page says which one it is showing.
function renderEditGroupTabs() {
    const g = effectiveEditGroup();
    const title = document.getElementById('editTableTitle');
    if (title) title.textContent = `Unit Database — ${groupDef(g).label}`;
    const hint = document.getElementById('importHint');
    if (hint) {
        if (!hint.dataset.tractor) hint.dataset.tractor = hint.innerHTML;
        hint.innerHTML = g === 'heavy'
            ? `New units go into ${escapeHtml(UNIT_GROUPS.heavy.label)} unless the "Unit Group" column says otherwise. Duplicate serial numbers are skipped.`
            : hint.dataset.tractor;
    }
    syncUnitsHead();
}

// ---- Units page head (design F) ----
// "24 agricultural units across 3 sites", counted from the group on screen.
// The group switch is only for accounts that may see both groups: a limited
// account is never offered the other one.
const UNITS_NOUN = { tractor: 'agricultural', heavy: 'heavy equipment' };
function syncUnitsHead() {
    const g = effectiveEditGroup();
    const sub = document.getElementById('unitsHeadSub');
    if (sub) {
        const units = unitsOfGroup(globalData, g);
        const sites = new Set(units.map(u => _toolNorm(u.site)).filter(Boolean)).size;
        const n = units.length;
        sub.textContent = !n ? `No ${UNITS_NOUN[g]} units yet`
            : `${n} ${UNITS_NOUN[g]} unit${n === 1 ? '' : 's'}`
              + (sites ? ` ${sites === 1 ? 'at' : 'across'} ${sites} site${sites === 1 ? '' : 's'}` : '');
    }
    const seg = document.getElementById('unitsGroupSeg');
    if (seg) {
        seg.hidden = isUnitScoped();
        seg.querySelectorAll('[data-units-group]').forEach(b =>
            b.setAttribute('aria-pressed', String(b.dataset.unitsGroup === g)));
    }
}

// ---- Units: missing key details ----
// One line above the table when units of the group lack a key field
// (REQUIRED_UNIT_FIELDS). "Show them" uses the missing-field filter: the one
// field when only one is short, otherwise any of them (MISSING_ANY).
const MISSING_ANY = '*';
function _missingTarget(g) {
    const units = unitsOfGroup(globalData, g);
    const per = (REQUIRED_UNIT_FIELDS[g] || []).map(f => ({ f, n: units.filter(u => isFieldMissing(u, f)).length }))
        .filter(m => m.n).sort((a, b) => b.n - a.n);
    const unitsShort = units.filter(u => per.some(m => isFieldMissing(u, m.f))).length;
    return { per, unitsShort, target: per.length === 1 ? per[0].f : MISSING_ANY };
}
function renderUnitsMissingBanner() {
    const box = document.getElementById('unitsMissingBanner');
    if (!box) return;
    const { per, unitsShort, target } = _missingTarget(effectiveEditGroup());
    if (!unitsShort) { box.hidden = true; return; }
    const list = per.map(m => `${m.n} ${m.n === 1 ? 'has' : 'have'} no ${escapeHtml(REQUIRED_FIELD_LABEL[m.f])}`).join(', ');
    document.getElementById('unitsMissingText').innerHTML =
        `<strong>${unitsShort} unit${unitsShort === 1 ? ' is' : 's are'} missing key details</strong> — ${list}.`;
    const on = editMissingFilter === target;
    const link = document.getElementById('unitsMissingShow');
    link.textContent = on ? 'Show all units' : 'Show them';
    link.setAttribute('aria-pressed', String(on));
    box.hidden = false;
}
function toggleMissingUnits() {
    const { target } = _missingTarget(effectiveEditGroup());
    setEditMissingFilter(editMissingFilter === target ? '' : target, true);
}

// ---- Units: quick filters ----
// All · Breakdown · Faulty part · License due, each with its count among the
// group's units at the chosen site. Breakdown is the Status filter's own
// "Breakdown"; Faulty part (a component not Good, as the dashboard counts
// issues) and License due (a GPS or display licence expired or within 30
// days, as the table's red and amber badges say) are editQuickFilter. One
// chip at a time. "All" is lit only while nothing narrows the list (search
// and site aside), and clears the status, part, licence, implement and
// missing-field filters.
let editQuickFilter = '';          // '' | 'faulty' | 'license'
function unitHasFaultyPart(u) {
    return groupDef(unitGroupOf(u)).components.some(c => !isGood(u[c.key]));
}
function unitLicenseDue(u) {
    if (isHeavy(u)) return false;
    return ['gps', 'display'].some(kind => {
        const s = getExpiryStatus(getLicenseEndDate(u, kind));
        return (s.kind === 'expired' || s.kind === 'soon') && !effectiveLicense(u, kind).downgraded;
    });
}
function quickFilterMatch(u, key) {
    return key === 'faulty' ? unitHasFaultyPart(u) : key === 'license' ? unitLicenseDue(u) : true;
}
function renderUnitsQuickFilters() {
    const box = document.getElementById('unitsQuick');
    if (!box) return;
    const g = effectiveEditGroup();
    const siteVal = document.getElementById('editSiteFilter')?.value || '';
    const statusVal = document.getElementById('editStatusFilter')?.value || '';
    const units = unitsOfGroup(globalData, g).filter(d => !siteVal || d.site === siteVal);
    if (editQuickFilter === 'license' && !groupDef(g).hasLicences) editQuickFilter = '';
    const chips = [
        { key: 'all', label: 'All', n: units.length, on: !statusVal && !editQuickFilter && !editToolFilter && !editMissingFilter },
        { key: 'breakdown', label: 'Breakdown', n: units.filter(u => u.status === 'Breakdown').length, on: statusVal === 'Breakdown' },
        { key: 'faulty', label: 'Faulty part', n: units.filter(unitHasFaultyPart).length, on: editQuickFilter === 'faulty' }
    ];
    if (groupDef(g).hasLicences) chips.push({ key: 'license', label: 'License due', n: units.filter(unitLicenseDue).length, on: editQuickFilter === 'license' });
    // The chips are redrawn by the click they handle: keep keyboard focus on
    // the one that was pressed.
    const had = document.activeElement && document.activeElement.closest && document.activeElement.closest('#unitsQuick [data-key]');
    box.innerHTML = chips.map(c => `<button type="button" class="units-chip${c.on ? ' is-on' : ''}" data-key="${c.key}" aria-pressed="${c.on}"
        ${!c.n && !c.on && c.key !== 'all' ? 'disabled' : ''} onclick="setUnitsQuickFilter('${c.key}')">${c.label} · ${c.n}</button>`).join('');
    if (had) box.querySelector(`[data-key="${had.dataset.key}"]:not(:disabled)`)?.focus();
}
function setUnitsQuickFilter(key) {
    const sf = document.getElementById('editStatusFilter');
    if (key === 'all') {
        editQuickFilter = ''; editToolFilter = ''; editMissingFilter = '';
        if (sf) sf.value = '';
    } else if (key === 'breakdown') {
        editQuickFilter = '';
        if (sf) sf.value = sf.value === 'Breakdown' ? '' : 'Breakdown';
    } else {
        editQuickFilter = editQuickFilter === key ? '' : key;
        if (sf) sf.value = '';
    }
    renderEditTable();
}

// ---- Units: the More menu (Import CSV, Backup, Restore, Auto Backups) ----
// A disclosure button and a short list of buttons: arrow keys move through
// it, Escape or a tap outside closes it, and an item closes it as it runs.
function _unitsMoreItems() {
    return [...document.querySelectorAll('#unitsMoreMenu > button')].filter(b => b.offsetParent !== null && !b.disabled);
}
function toggleUnitsMore(open) {
    const menu = document.getElementById('unitsMoreMenu');
    const btn = document.getElementById('unitsMoreBtn');
    if (!menu || !btn) return;
    const show = open === undefined ? menu.hidden : !!open;
    if (show === !menu.hidden) return;
    menu.hidden = !show;
    btn.setAttribute('aria-expanded', String(show));
    if (show) { const first = _unitsMoreItems()[0]; if (first) first.focus(); }
}
document.addEventListener('keydown', e => {
    const more = e.target && e.target.closest && e.target.closest('#unitsMore');
    if (!more) return;
    const menu = document.getElementById('unitsMoreMenu');
    const btn = document.getElementById('unitsMoreBtn');
    if (e.key === 'Escape' && !menu.hidden) {
        // Only the menu: the page-wide Escape (a later listener on document)
        // closes the top dialog.
        e.stopImmediatePropagation();
        toggleUnitsMore(false);
        btn.focus();
        return;
    }
    if (!['ArrowDown', 'ArrowUp', 'Home', 'End'].includes(e.key)) return;
    e.preventDefault();
    if (menu.hidden) { toggleUnitsMore(true); return; }
    const items = _unitsMoreItems();
    if (!items.length) return;
    const i = items.indexOf(document.activeElement);
    const next = e.key === 'Home' ? 0 : e.key === 'End' ? items.length - 1
        : e.key === 'ArrowDown' ? (i + 1) % items.length : (i <= 0 ? items.length - 1 : i - 1);
    items[next].focus();
});
document.addEventListener('pointerdown', e => {
    const menu = document.getElementById('unitsMoreMenu');
    if (menu && !menu.hidden && !(e.target.closest && e.target.closest('#unitsMore'))) toggleUnitsMore(false);
});
document.addEventListener('focusout', e => {
    if (!(e.target.closest && e.target.closest('#unitsMore'))) return;
    // Tabbing out of the menu closes it; moving between its items does not.
    if (!(e.relatedTarget && e.relatedTarget.closest && e.relatedTarget.closest('#unitsMore'))) {
        const menu = document.getElementById('unitsMoreMenu');
        if (menu && !menu.hidden && e.relatedTarget) toggleUnitsMore(false);
    }
});
document.addEventListener('click', e => {
    const item = e.target.closest && e.target.closest('#unitsMoreMenu > button');
    if (!item) return;
    // The item's own onclick has run by now (it is on the button itself).
    // Import CSV hands focus to the upload area it just opened.
    toggleUnitsMore(false);
    const drop = document.getElementById('editDropZone');
    if (/toggleImportPanel/.test(item.getAttribute('onclick') || '') && document.getElementById('importPanel')?.classList.contains('open')) drop?.focus();
    else if (!document.querySelector('.modal-overlay.open')) document.getElementById('unitsMoreBtn')?.focus({ preventScroll: true });
});
// The upload area is a button to the keyboard too.
document.addEventListener('keydown', e => {
    if (e.target && e.target.id === 'editDropZone' && (e.key === 'Enter' || e.key === ' ')) { e.preventDefault(); e.target.click(); }
});

// ---- Units: Good / Breakdown in colour ----
// The rows' markup is fixed (the golden tests compare it byte for byte), so
// the status and part cells are coloured without touching it: the CSS Custom
// Highlight API paints ranges over their text, styled by ::highlight(units-
// good / units-bad) in f-theme/units.css. Repainted whenever the rows change
// or a cell is typed into. A browser without the API shows plain text.
const UNIT_STATE_FIELDS = new Set(['status', ...COMPONENT_KEYS, ...HEAVY_COMPONENT_KEYS]);
function paintUnitStates() {
    if (!(window.CSS && CSS.highlights && typeof Highlight === 'function')) return;
    const good = new Highlight(), bad = new Highlight();
    document.querySelectorAll('#editBody .inline-edit[data-field]').forEach(el => {
        if (!UNIT_STATE_FIELDS.has(el.dataset.field) || !clean(el.textContent)) return;
        const r = document.createRange();
        r.selectNodeContents(el);
        (isGood(el.textContent) ? good : bad).add(r);
    });
    CSS.highlights.set('units-good', good);
    CSS.highlights.set('units-bad', bad);
}
(() => {
    const body = document.getElementById('editBody');
    if (!body || typeof MutationObserver !== 'function') return;
    new MutationObserver(paintUnitStates).observe(body, { subtree: true, childList: true, characterData: true });
})();

// ---- Units: data completeness and units per implement, folded ----
// Both cards filter the table but are not what the page is read for, so they
// sit behind one line ("Data 96% complete · 5 implement types") until
// opened. The choice is remembered on this device; a filter set from either
// card (or from the Decision inbox) opens it, so what narrows the table is
// always on screen.
function unitsInsightsOpen() {
    if (editToolFilter || (editMissingFilter && editMissingFilter !== MISSING_ANY)) return true;
    try { return localStorage.getItem('unitsInsightsOpen') === '1'; } catch (_) { return false; }
}
function syncUnitsInsights() {
    const btn = document.getElementById('unitsInsightsBtn');
    const body = document.getElementById('unitsInsightsBody');
    if (!btn || !body) return;
    const dq = document.getElementById('dataQuality');
    const ts = document.getElementById('toolSummary');
    const hasDq = dq && dq.style.display !== 'none';
    const hasTs = ts && ts.style.display !== 'none';
    document.getElementById('unitsInsights').hidden = !hasDq && !hasTs;
    const g = effectiveEditGroup();
    const parts = [];
    const pct = hasDq && dq.querySelector('.dq__pct');
    if (pct) parts.push(`Data ${pct.textContent} complete`);
    if (hasTs) {
        const kinds = toolSummaryRows(g).rows.filter(r => r.key !== TOOL_NONE).length;
        parts.push(`${kinds} ${g === 'heavy' ? 'work tool' : 'implement'} type${kinds === 1 ? '' : 's'}`);
    }
    document.getElementById('unitsInsightsMeta').textContent = parts.join(' · ');
    const open = unitsInsightsOpen();
    body.hidden = !open;
    btn.setAttribute('aria-expanded', String(open));
}
function toggleUnitsInsights() {
    const open = document.getElementById('unitsInsightsBody').hidden;
    try { localStorage.setItem('unitsInsightsOpen', open ? '1' : ''); } catch (_) {}
    // Folding it away also drops a filter it was holding, or the table
    // would stay narrowed by something no longer on screen.
    if (!open && (editToolFilter || (editMissingFilter && editMissingFilter !== MISSING_ANY))) {
        editToolFilter = '';
        if (editMissingFilter !== MISSING_ANY) editMissingFilter = '';
        renderEditTable();
        return;
    }
    syncUnitsInsights();
}

// The page head follows the account (its group limit) and the data; a
// change of limit drops the quick filter with the other filters
// (applyRoleGating clears those). The menu closes when the page is left.
let _unitsScopeSeen = null;
document.addEventListener('ot:gating', () => {
    const sc = effectiveUnitScope();
    if (_unitsScopeSeen !== null && sc !== _unitsScopeSeen) editQuickFilter = '';
    _unitsScopeSeen = sc;
    syncUnitsHead();
});
document.addEventListener('ot:data', syncUnitsHead);
document.addEventListener('ot:view', () => toggleUnitsMore(false));

function switchEditUnitsGroup(g, opts) {
    const sc = effectiveUnitScope();
    if (sc === 'tractor' || sc === 'heavy') { g = sc; opts = { ...(opts || {}), persist: false }; }
    if (!UNIT_GROUP_KEYS.includes(g)) return;
    editUnitsGroup = g;
    _editGroupPicked = true;
    if (!opts || opts.persist !== false) writePref('editUnitsGroup', g);
    editSortState = { key: null, asc: true };
    editToolFilter = '';
    editMissingFilter = '';
    editQuickFilter = '';
    ['editSearch', 'editStatusFilter', 'editSiteFilter'].forEach(id => {
        const el = document.getElementById(id); if (el) el.value = '';
    });
    populateEditFilters();
    renderEditTable();
    markActiveNav();
}

function _editRowHeavy(d, i, ce) {
    const remarks = d.remarks || '';
    const remarksShort = remarks.length > 40 ? remarks.slice(0, 40) + '…' : remarks;
    const id = escapeHtml(d.id);
    const cell = (label, field, style) =>
        `<td data-label="${label}"${style ? ` style="${style}"` : ''}><span class="inline-edit" contenteditable="${ce}" data-id="${id}" data-field="${field}" onblur="saveInlineEdit(this)">${escapeHtml(d[field] == null ? '' : d[field])}</span></td>`;
    return `
        <tr>
            <td class="col-check"><input type="checkbox" class="unit-check" data-id="${id}" onchange="updateSelectedCount()"></td>
            <td>${i + 1}</td>
            <td data-label="Nickname"><span class="inline-edit" contenteditable="${ce}" data-id="${id}" data-field="name" onblur="saveInlineEdit(this)">${escapeHtml(d.name == null ? '' : d.name)}</span>${inspectionChipFor(d)}${openDamageChipFor(d)}</td>${cell('Brand', 'brand')}${cell('Model', 'model')}
            <td data-label="SN" style="font-family:monospace;font-size:12px">${escapeHtml(d.sn)}</td>
            ${cell('Machine Type', 'machineType')}${cell('Asset No.', 'assetCode')}${cell('Work Tool', 'workTool')}
            ${cell('Status', 'status')}
            ${UNIT_GROUPS.heavy.components.map(c => cell(c.label, c.key)).join('')}
            ${cell('Site', 'site')}${cell('Year Received', 'yearReceived')}
            <td data-label="User Category">${d.userCategory ? `<span class="badge badge-cat" style="font-size:10px">${escapeHtml(d.userCategory)}</span>` : '<span style="color:var(--text-light);font-size:11px">—</span>'}</td>
            <td data-label="Remarks" style="max-width:180px;font-size:12px;color:var(--text-secondary)" title="${escapeHtml(remarks)}">${escapeHtml(remarksShort) || '<span style="color:var(--text-light)">—</span>'}</td>
            <td class="col-attach" data-label="Attachments">${renderAttachCell(d)}</td>
            <td class="col-actions">
                <div class="row-actions">
                    <button class="btn btn-secondary" title="Profile" onclick="showUnitProfile(${jsArg(d.id)})"><i class="fas fa-eye"></i></button>
                    <button class="btn btn-secondary" title="History" onclick="showHistory(${jsArg(d.id)})"><i class="fas fa-clock-rotate-left"></i></button>
                    <button class="btn btn-secondary" title="Edit" onclick="editUnit(${jsArg(d.id)})"><i class="fas fa-pen"></i></button>
                    <button class="btn btn-secondary" title="Delete" onclick="deleteUnit(${jsArg(d.id)})"><i class="fas fa-trash" style="color:var(--danger)"></i></button>
                </div>
            </td>
        </tr>`;
}

// While someone is typing in a Unit Database cell, the table is NOT rebuilt.
// Rebuilding replaced the focused cell, the browser fired its blur, and the
// half-typed value was saved (or, during a units snapshot, kept only on this
// device under a success toast). The rebuild runs once the cell is left.
let _editRenderPending = false;
let _rebuildingEditTable = false;
function _editCellFocused() {
    const a = document.activeElement;
    return !!(a && a.isContentEditable && a.closest && a.closest('#editBody'));
}
document.addEventListener('focusout', e => {
    if (!_editRenderPending || !(e.target && e.target.closest && e.target.closest('#editBody'))) return;
    // After the cell's own onblur save; and not while focus just moved to the
    // next cell (Tab).
    setTimeout(() => {
        if (_editRenderPending && !_editCellFocused()) { _editRenderPending = false; renderEditTable(); }
    }, 0);
});

function renderEditTable() {
    if (_editCellFocused()) { _editRenderPending = true; return; }
    _openDmgIdx = null;
    // A blur fired by the rebuild itself must not count as an edit.
    _rebuildingEditTable = true;
    try { _renderEditTable(); } finally { _rebuildingEditTable = false; }
}

function _renderEditTable() {
    renderEditHead();
    renderEditGroupTabs();
    renderUnitsMissingBanner();
    renderUnitsQuickFilters();
    renderDataCompleteness();
    renderToolSummary();
    syncUnitsInsights();
    updateEditCount();
    // A re-render (search, filter, a cloud snapshot) draws fresh, unticked
    // rows — so the selection is dropped with them. Re-reading the OLD boxes
    // here kept "Delete selected" armed for rows no longer on screen.
    document.querySelectorAll('.unit-check').forEach(cb => { cb.checked = false; });
    selectedUnitIds.clear();
    updateSelectedCount();

    const selectAllBox = document.getElementById('selectAll');
    if (selectAllBox) selectAllBox.checked = false;

    const query = (document.getElementById('editSearch')?.value || '').toLowerCase().trim();
    const statusVal = (document.getElementById('editStatusFilter')?.value || '');
    const siteVal = (document.getElementById('editSiteFilter')?.value || '');

    const rows = getEditTableRows();

    const tbody = document.getElementById('editBody');
    const group = effectiveEditGroup();
    const shown = document.getElementById('unitsShownCount');
    if (shown) {
        const all = unitsOfGroup(globalData, group).length;
        shown.textContent = !all ? '' : rows.length === all ? `Showing all ${all}` : `Showing ${rows.length} of ${all}`;
    }
    if (rows.length === 0) {
        const empty = group === 'heavy'
            ? `No ${escapeHtml(UNIT_GROUPS.heavy.label)} units yet. Click <strong>Add unit</strong>, or <strong>Import CSV</strong> from the More menu, to get started.`
            : 'No units yet. Click <strong>Add unit</strong>, or <strong>Import CSV</strong> from the More menu, to get started.';
        tbody.innerHTML = `<tr><td colspan="${EDIT_COLSPAN[group]}" style="text-align:center;padding:24px;color:var(--text-secondary)">${(query || statusVal || siteVal || editToolFilter || editMissingFilter || editQuickFilter) ? 'No units match the filter' : empty}</td></tr>`;
        return;
    }

    const _ceEdit = hasAccess('editUnits', 'edit') ? 'true' : 'false'; // inline editing off for view-only
    if (group === 'heavy') {
        tbody.innerHTML = rows.map((d, i) => _editRowHeavy(d, i, _ceEdit)).join('');
        return;
    }
    tbody.innerHTML = rows.map((d, i) => {
        const remarks = d.remarks || '';
        const remarksShort = remarks.length > 40 ? remarks.slice(0, 40) + '…' : remarks;
        // A cell without data-label is display:none in card mode
        // (style.css). Two here stay unlabelled on purpose: the row number
        // means nothing once rows are stacked as cards, and bulk-select is a
        // desktop action — a checkbox column on a phone mostly produces
        // accidental selections. Everything else must carry a label, or the
        // column silently vanishes on the device the field team actually uses.
        return `
        <tr>
            <td class="col-check"><input type="checkbox" class="unit-check" data-id="${escapeHtml(d.id)}" onchange="updateSelectedCount()"></td>
            <td>${i + 1}</td>
            <td data-label="Nickname"><span class="inline-edit" contenteditable="${_ceEdit}" data-id="${escapeHtml(d.id)}" data-field="name" onblur="saveInlineEdit(this)">${escapeHtml(d.name)}</span></td>
            <td data-label="Model"><span class="inline-edit" contenteditable="${_ceEdit}" data-id="${escapeHtml(d.id)}" data-field="model" onblur="saveInlineEdit(this)">${escapeHtml(d.model)}</span></td>
            <td data-label="SN" style="font-family:monospace;font-size:12px">${escapeHtml(d.sn)}</td>
            <td data-label="Implement"><span class="inline-edit" contenteditable="${_ceEdit}" data-id="${escapeHtml(d.id)}" data-field="implement" onblur="saveInlineEdit(this)">${escapeHtml(d.implement || '')}</span></td>
            <td data-label="Status"><span class="inline-edit" contenteditable="${_ceEdit}" data-id="${escapeHtml(d.id)}" data-field="status" onblur="saveInlineEdit(this)">${escapeHtml(d.status)}</span></td>
            <td data-label="Display"><span class="inline-edit" contenteditable="${_ceEdit}" data-id="${escapeHtml(d.id)}" data-field="display" onblur="saveInlineEdit(this)">${escapeHtml(d.display)}</span></td>
            <td data-label="GPS"><span class="inline-edit" contenteditable="${_ceEdit}" data-id="${escapeHtml(d.id)}" data-field="gps" onblur="saveInlineEdit(this)">${escapeHtml(d.gps)}</span></td>
            <td data-label="Steering"><span class="inline-edit" contenteditable="${_ceEdit}" data-id="${escapeHtml(d.id)}" data-field="steering" onblur="saveInlineEdit(this)">${escapeHtml(d.steering)}</span></td>
            <td data-label="JDLink"><span class="inline-edit" contenteditable="${_ceEdit}" data-id="${escapeHtml(d.id)}" data-field="jdlink" onblur="saveInlineEdit(this)">${escapeHtml(d.jdlink)}</span></td>
            <td data-label="Site"><span class="inline-edit" contenteditable="${_ceEdit}" data-id="${escapeHtml(d.id)}" data-field="site" onblur="saveInlineEdit(this)">${escapeHtml(d.site)}</span></td>
            <td data-label="Year Received"><span class="inline-edit" contenteditable="${_ceEdit}" data-id="${escapeHtml(d.id)}" data-field="yearReceived" onblur="saveInlineEdit(this)">${escapeHtml(d.yearReceived || '')}</span></td>
            <td data-label="User Category">${d.userCategory ? `<span class="badge badge-cat" style="font-size:10px">${escapeHtml(d.userCategory)}</span>` : '<span style="color:var(--text-light);font-size:11px">—</span>'}</td>
            <td data-label="GPS License">${licenseTypeBadge(d, 'gps')}</td>
            <td data-label="GPS Expiry">${licenseBadgeFor(d, 'gps')}</td>
            <td data-label="Display License">${licenseTypeBadge(d, 'display')}</td>
            <td data-label="Display Expiry">${licenseBadgeFor(d, 'display')}</td>
            <td data-label="Remarks" style="max-width:180px;font-size:12px;color:var(--text-secondary)" title="${escapeHtml(remarks)}">${escapeHtml(remarksShort) || '<span style="color:var(--text-light)">—</span>'}</td>
            <td class="col-attach" data-label="Attachments">${renderAttachCell(d)}</td>
            <td class="col-actions">
                <div class="row-actions">
                    <button class="btn btn-secondary" title="Profile" onclick="showUnitProfile(${jsArg(d.id)})"><i class="fas fa-eye"></i></button>
                    <button class="btn btn-secondary" title="History" onclick="showHistory(${jsArg(d.id)})"><i class="fas fa-clock-rotate-left"></i></button>
                    <button class="btn btn-secondary" title="Edit" onclick="editUnit(${jsArg(d.id)})"><i class="fas fa-pen"></i></button>
                    <button class="btn btn-secondary" title="Delete" onclick="deleteUnit(${jsArg(d.id)})"><i class="fas fa-trash" style="color:var(--danger)"></i></button>
                </div>
            </td>
        </tr>`; }).join('');
}

function sortEditTable(key) {
    if (key === 'no') { editSortState.key = null; }
    else if (editSortState.key === key) { editSortState.asc = !editSortState.asc; }
    else { editSortState.key = key; editSortState.asc = true; }
    markSortedHeader('#editTable thead', editSortState.key, editSortState.asc);
    renderEditTable();
}

function populateEditFilters() {
    const pool = unitsOfGroup(globalData, effectiveEditGroup());
    const statuses = [...new Set(pool.map(d => d.status))].filter(Boolean).sort();
    const sites = [...new Set(pool.map(d => d.site))].filter(Boolean).sort();
    const sf = document.getElementById('editStatusFilter');
    const sif = document.getElementById('editSiteFilter');
    if (sf) {
        const cur = sf.value;
        sf.innerHTML = '<option value="">All Status</option>' + statuses.map(s => `<option value="${escapeHtml(s)}">${escapeHtml(s)}</option>`).join('');
        sf.value = cur;
    }
    if (sif) {
        const cur = sif.value;
        sif.innerHTML = '<option value="">All Sites</option>' + sites.map(s => `<option value="${escapeHtml(s)}">${escapeHtml(s)}</option>`).join('');
        sif.value = cur;
    }
}

// ---- Inline Edit ----
// A heavy unit set back to Good by hand (status or a component) while open
// damage records still hold that place in Breakdown. Asked, not refused — the
// unit may really run again — but the records stay open, and Data Check keeps
// listing the unit until they are marked done. changes: [{ unit, fields }].
function confirmGoodWithOpenDamage(changes) {
    const hits = [];
    changes.forEach(({ unit, fields }) => {
        if (!unit || !isHeavy(unit) || !fields) return;
        ['status', ...HEAVY_COMPONENT_KEYS].forEach(f => {
            if (fields[f] === undefined || !isGood(fields[f]) || isGood(unit[f])) return;
            const held = openDamageHolders(unit, f);
            if (held.length) hits.push({ unit, f, held });
        });
    });
    if (!hits.length) return true;
    const units = new Set(hits.map(h => h.unit.id));
    if (units.size === 1) {
        const h = hits[0];
        const all = [...new Map(hits.flatMap(x => x.held).map(d => [d.id, d])).values()];
        const list = all.slice(0, 3).map(d => `${d.damageType}${d.component ? ' / ' + d.component : ''} (${d.date})`).join('; ');
        return confirm(`"${h.unit.name || h.unit.sn}" has ${all.length} open damage record(s): ${list}${all.length > 3 ? '; …' : ''}.\n\n`
            + 'Setting it Good does not close them — mark them done in Damage instead.\n\nSet Good anyway?');
    }
    return confirm(`${units.size} heavy unit(s) still have open damage records holding them in Breakdown.\n\n`
        + 'Setting them Good does not close those records — mark them done in Damage instead.\n\nSet Good anyway?');
}

function saveInlineEdit(el) {
    // A blur caused by redrawing the table, or one that lands while a cloud
    // snapshot is being applied, is not the person finishing an edit.
    if (_rebuildingEditTable || suppressCloudWrites) return;
    if (!hasAccess('editUnits', 'edit')) {
        // Revert the DOM if a view-only user somehow triggered this
        const id = el.dataset.id;
        const field = el.dataset.field;
        const unit = globalData.find(d => d.id === id);
        if (unit) el.textContent = unit[field] || '';
        return;
    }
    const id = el.dataset.id;
    const field = el.dataset.field;
    const newValue = clean(el.textContent);
    const unit = globalData.find(d => d.id === id);

    // Tractor rows keep the strict comparison verbatim — including the writes it
    // makes today to normalise whitespace or a numeric year. For a heavy unit
    // an absent field left empty is not a change: comparing undefined !== ''
    // used to write '' to Firestore and toast "diperbarui" on a mere click.
    const changed = unit && (isHeavy(unit) ? !sameStoredValue(unit[field], newValue) : unit[field] !== newValue);
    // Same reason as editUnit: the firewall would drop the write anyway, but
    // silently, leaving the cell showing a value that was never saved.
    if (changed && hasUnreadableGroup(unit)
        && (TRACTOR_ONLY_FIELDS.includes(field) || HEAVY_ONLY_FIELDS.includes(field))) {
        el.textContent = unit[field] || '';
        showToast(`This unit's group ("${plainText(unit.unitGroup)}") is unknown — set it first via Data Check`, 'warning');
        return;
    }
    if (changed && (field === 'site' || field === 'brand') && !hasUnreadableGroup(unit)) {
        const kind = field === 'brand' ? 'heavyBrand' : 'site';
        const label = field === 'brand' ? 'Brand' : 'Site';
        const r = checkMasterValue(kind, newValue, unit[field]);
        if (!r.ok) {
            el.textContent = unit[field] || '';
            showToast(`${label} "${r.value}" ${masterNotInList(kind)}`, 'warning');
            return;
        }
        if (r.value !== newValue) el.textContent = r.value;
        if (r.value === (unit[field] || '')) return;
        if (updateUnit(id, { [field]: r.value })) showToast(`${label} updated`, 'success');
        return;
    }
    if (changed && field === 'implement') {
        const r = checkImplementValue(newValue, unit.implement);
        if (!r.ok) {
            el.textContent = unit.implement || '';
            showToast(`Implement "${r.value}" ${IMPLEMENT_NOT_IN_LIST}`, 'warning');
            return;
        }
        if (r.value !== newValue) el.textContent = r.value;
        if (r.value === unit.implement) return;
        if (updateUnit(id, { implement: r.value })) showToast('Implement updated', 'success');
        return;
    }
    if (changed) {
        // Intercept status changing TO Breakdown → prompt for reason
        if (field === 'status' && !isGood(newValue) && isGood(unit.status)) {
            _pendingBreakdown = { unitId: id, fields: { status: newValue }, isInline: true, el };
            document.getElementById('breakdownReasonText').value = '';
            document.getElementById('breakdownReasonModal').classList.add('open');
            return;
        }
        if (!confirmGoodWithOpenDamage([{ unit, fields: { [field]: newValue } }])) {
            el.textContent = unit[field] || '';
            return;
        }
        if (updateUnit(id, { [field]: newValue })) {
            showToast(`${COMPONENT_LABELS[field] || UNIT_FIELD_LABELS[field] || field.charAt(0).toUpperCase() + field.slice(1)} updated`, 'success');
        }
    }
}

// ---- Breakdown reason modal ----
function confirmBreakdownReason() {
    const reason = (document.getElementById('breakdownReasonText').value || '').trim();
    if (!reason) {
        showToast('Enter a breakdown reason', 'warning');
        document.getElementById('breakdownReasonText').focus();
        return;
    }
    const p = _pendingBreakdown;
    if (!p) return;
    _pendingBreakdown = null;
    document.getElementById('breakdownReasonModal').classList.remove('open');

    p.fields.breakdownReason = reason;
    if (p.isInline) {
        updateUnit(p.unitId, p.fields);
        showToast('Status updated — breakdown reason recorded', 'success');
    } else {
        _commitSaveUnit(p.unitId, p.fields);
    }
}

function cancelBreakdownReason() {
    const p = _pendingBreakdown;
    _pendingBreakdown = null;
    document.getElementById('breakdownReasonModal').classList.remove('open');
    // Revert inline edit cell if it was an inline change
    if (p && p.isInline && p.el) {
        const unit = globalData.find(d => d.id === p.unitId);
        if (unit) p.el.textContent = unit.status || 'Good';
    }
}

// ---- Breakdown popover (dashboard) ----
function showBreakdownPopover(event, reason) {
    event.stopPropagation();
    const pop = document.getElementById('breakdownPopover');
    pop.textContent = reason;
    pop.style.display = 'block';
    const rect = event.currentTarget.getBoundingClientRect();
    pop.style.top = (rect.bottom + window.scrollY + 8) + 'px';
    pop.style.left = (rect.left + window.scrollX + rect.width / 2) + 'px';

    const dismiss = (e) => {
        if (!pop.contains(e.target)) {
            pop.style.display = 'none';
            document.removeEventListener('click', dismiss);
        }
    };
    setTimeout(() => document.addEventListener('click', dismiss), 0);
}

// ---- Select / Delete ----
function toggleSelectAll() {
    const checked = document.getElementById('selectAll').checked;
    document.querySelectorAll('.unit-check').forEach(cb => { cb.checked = checked; });
    updateSelectedCount();
}

function updateSelectedCount() {
    selectedUnitIds.clear();
    document.querySelectorAll('.unit-check:checked').forEach(cb => selectedUnitIds.add(cb.dataset.id));
    const count = selectedUnitIds.size;
    document.getElementById('selectedCount').textContent = count;
    document.getElementById('btnDeleteSelected').style.display = count > 0 ? '' : 'none';
    const bulk = document.getElementById('btnBulkEdit');
    const bulkCount = document.getElementById('bulkEditCount');
    if (bulkCount) bulkCount.textContent = count;
    if (bulk) bulk.style.display = count > 0 ? '' : 'none';
    // The table card shows its action bar only while rows are ticked.
    document.querySelector('.units-table-card')?.classList.toggle('has-selection', count > 0);
}

// ---- Bulk edit selected units ----
function openBulkEdit() {
    if (!requireEdit('editUnits')) return;
    if (selectedUnitIds.size === 0) return;
    document.getElementById('bulkEditTitle').textContent = `${selectedUnitIds.size} unit(s)`;
    ['bulkChkSite', 'bulkChkStatus', 'bulkChkCategory', 'bulkChkYear', 'bulkChkImplement', 'bulkChkWorkTool', 'bulkChkBrand'].forEach(id => {
        const el = document.getElementById(id); if (el) el.checked = false;
    });
    document.getElementById('bulkSite').value = '';
    document.getElementById('bulkYear').value = '';
    document.getElementById('bulkImplement').value = '';
    const wt = document.getElementById('bulkWorkTool'); if (wt) wt.value = '';
    const br = document.getElementById('bulkBrand'); if (br) br.value = '';
    // The selection is always one tab's rows (renderEditTable clears it), so
    // only that group's own field is offered: Implement for agricultural units,
    // Alat Kerja for heavy equipment.
    const g = effectiveEditGroup();
    document.querySelectorAll('#bulkEditModal [data-group-only]').forEach(el => {
        el.style.display = el.dataset.groupOnly === g ? '' : 'none';
    });
    if (g === 'heavy') populateHeavySuggestionLists();
    // Category options
    const cat = document.getElementById('bulkCategory');
    cat.innerHTML = '<option value="">—</option>' +
        (userCategories || []).map(c => `<option value="${escapeHtml(c.name)}">${escapeHtml(c.name)}</option>`).join('');
    populateImplementUnitList();
    populateMasterDatalists();
    document.getElementById('bulkEditModal').classList.add('open');
}

function closeBulkEdit() {
    document.getElementById('bulkEditModal').classList.remove('open');
}

function applyBulkEdit() {
    if (!requireEdit('editUnits')) return;
    const ids = [...selectedUnitIds];
    if (ids.length === 0) { closeBulkEdit(); return; }

    const fields = {};
    if (document.getElementById('bulkChkSite').checked)     fields.site = document.getElementById('bulkSite').value.trim();
    if (document.getElementById('bulkChkStatus').checked)   fields.status = document.getElementById('bulkStatus').value;
    if (document.getElementById('bulkChkCategory').checked) fields.userCategory = document.getElementById('bulkCategory').value;
    if (document.getElementById('bulkChkYear').checked)     fields.yearReceived = document.getElementById('bulkYear').value.trim();
    const bg = effectiveEditGroup();
    if (bg !== 'heavy' && document.getElementById('bulkChkImplement').checked) fields.implement = document.getElementById('bulkImplement').value.trim();
    if (bg === 'heavy' && document.getElementById('bulkChkWorkTool')?.checked) fields.workTool = document.getElementById('bulkWorkTool').value.trim();
    if (bg === 'heavy' && document.getElementById('bulkChkBrand')?.checked) fields.brand = document.getElementById('bulkBrand').value.trim();

    if (Object.keys(fields).length === 0) { showToast('Tick at least one field to change', 'warning'); return; }
    if (fields.site) {
        const r = checkMasterValue('site', fields.site, null);
        if (!r.ok) { showToast(`Site "${r.value}" ${masterNotInList('site')}`, 'warning'); return; }
        fields.site = r.value;
    }
    if (fields.brand) {
        const r = checkMasterValue('heavyBrand', fields.brand, null);
        if (!r.ok) { showToast(`Brand "${r.value}" ${masterNotInList('heavyBrand')}`, 'warning'); return; }
        fields.brand = r.value;
    }
    if (fields.implement) {
        const r = checkImplementValue(fields.implement, null);
        if (!r.ok) { showToast(`Implement "${r.value}" ${IMPLEMENT_NOT_IN_LIST}`, 'warning'); return; }
        fields.implement = r.value;
    }

    // A ticked box with an empty input clears that field on every selected unit
    // and there is no undo, so make the destructive part explicit rather than
    // hiding it behind the generic confirm.
    const labels = { site: 'Site', status: 'Status', userCategory: 'User Category',
                     yearReceived: 'Year Received', implement: 'Implement', workTool: 'Work Tool', brand: 'Brand' };
    const cleared = Object.keys(fields).filter(k => fields[k] === '');
    if (cleared.length) {
        const names = cleared.map(k => labels[k] || k).join(', ');
        if (!confirm(`The following fields will be CLEARED on ${ids.length} unit(s): ${names}.\n\n` +
                     `This cannot be undone. Continue?`)) return;
    }
    if (!confirm(`Apply changes to ${ids.length} unit(s)?`)) return;
    if (fields.status !== undefined && !confirmGoodWithOpenDamage(ids.map(id => ({ unit: globalData.find(u => u.id === id), fields })))) return;

    let n = 0;
    ids.forEach(id => {
        const unit = globalData.find(u => u.id === id);
        const perUnit = { ...fields };
        // Only stamp a placeholder reason on units that were actually running;
        // never overwrite an existing diagnosis on a unit already broken down.
        if (perUnit.status === 'Breakdown') {
            if (unit && !isGood(unit.status) && unit.breakdownReason) {
                // keep the real reason
            } else {
                perUnit.breakdownReason = 'Diset massal (bulk edit)';
            }
        }
        if (updateUnit(id, perUnit)) n++;
    });
    closeBulkEdit();
    renderEditTable();
    showToast(`${n} unit(s) updated`, 'success');
}

function deleteUnit(id) {
    if (!requireEdit('editUnits')) return;
    const unit = globalData.find(d => d.id === id);
    if (!unit) return;
    if (!confirm(`Delete unit "${unit.name || unit.sn}"${unit.sn ? ` (SN ${unit.sn})` : ''}?\n\nIt is removed on every device. You can undo for 10 seconds.`)) return;
    const { removed } = deleteUnits([id]);
    renderEditTable();
    showUndoToast(`Unit "${unit.name || unit.sn}" deleted`, removed);
}

function deleteSelected() {
    if (!requireEdit('editUnits')) return;
    const count = selectedUnitIds.size;
    if (count === 0) return;
    // Implements and damage records already asked; units — the largest, and
    // the ones every other record points at — went in one tap, on every
    // device, with a 10-second undo on this one only.
    const g = groupDef(effectiveEditGroup()).label;
    if (!confirm(`Delete ${count} ${g} unit(s)?\n\nThey are removed on every device. You can undo for 10 seconds.`)) return;
    if (count > 10) {
        const typed = prompt(`To delete ${count} units, type the number ${count}:`, '');
        if (String(typed == null ? '' : typed).trim() !== String(count)) { showToast('Not deleted — the number did not match', 'info'); return; }
    }
    const { removed } = deleteUnits([...selectedUnitIds]);
    renderEditTable();
    showUndoToast(`${count} unit(s) deleted`, removed);
}

// ---- Undo Toast ----
function showUndoToast(message, units) {
    if (!units || units.length === 0) return;
    lastDeletedUnits = units;
    if (undoTimer) clearTimeout(undoTimer);
    document.querySelectorAll('.undo-toast').forEach(t => t.remove());

    const container = document.getElementById('toastContainer');
    const toast = document.createElement('div');
    toast.className = 'toast info undo-toast';
    toast.innerHTML = `<i class="fas fa-trash"></i> <span>${escapeHtml(message)}</span> <button class="toast-undo-btn" onclick="undoDelete()">UNDO</button>`;
    container.appendChild(toast);

    undoTimer = setTimeout(() => {
        toast.style.opacity = '0';
        setTimeout(() => toast.remove(), 300);
        lastDeletedUnits = null;
        undoTimer = null;
        if (_pendingAttachPurge.length > 0) {
            attachDbDelete(_pendingAttachPurge).catch(() => {});
            _pendingAttachPurge = [];
        }
    }, 10000);
}

function undoDelete() {
    if (!lastDeletedUnits || lastDeletedUnits.length === 0) return;
    if (!requireEdit('editUnits')) return;
    _pendingAttachPurge = [];
    const restored = lastDeletedUnits;
    globalData = [...globalData, ...restored];
    saveToStorage(globalData);
    cloudPushUnits(restored);
    restored.forEach(u => logEvent({ action: 'restore', unitId: u.id, unitName: u.name, after: 'undelete' }));
    recordChange({ type: 'restored', detail: `${restored.length} unit(s) restored` });
    renderEditTable();
    showToast(`${restored.length} unit(s) restored`, 'success');
    lastDeletedUnits = null;
    if (undoTimer) { clearTimeout(undoTimer); undoTimer = null; }
    document.querySelectorAll('.undo-toast').forEach(t => t.remove());
}

// ---- Modal: Add / Edit ----
// ---- Implement picker (unit form ↔ Implements database) ----
// Options read "equipmentType — brand" (e.g. "HDR Ripper — Gessner"). Free
// text is still allowed, so legacy values, inline edits and CSV imports keep
// working unchanged.
function implementOptionLabel(imp) {
    const parts = [imp.equipmentType, imp.brand].map(v => (v || '').trim()).filter(Boolean);
    return parts.length ? parts.join(' — ') : (imp.profileName || '').trim();
}

// The previous "profileName — equipmentType" label, kept so units saved with
// the old format still resolve back to their implement.
function _implementLegacyLabel(imp) {
    return `${imp.profileName || ''}${imp.equipmentType ? ' — ' + imp.equipmentType : ''}`.trim();
}

function populateImplementUnitList() {
    const list = document.getElementById('implementUnitList');
    if (!list) return;
    const labels = [...new Set(globalImplements
        .map(implementOptionLabel)
        .filter(Boolean))]
        .sort((a, b) => a.localeCompare(b));
    list.innerHTML = labels.map(l => `<option value="${escapeHtml(l)}"></option>`).join('');
    const input = document.getElementById('formImplement');
    if (input) input.placeholder = implementListActive() ? 'Pick from the Implements list…' : 'Type the implement…';
    populateMasterDatalists();
}

// Find the implement record a unit's free-text implement value refers to.
function matchImplementForUnit(text) {
    const t = (text || '').toLowerCase().trim();
    if (!t) return null;
    return globalImplements.find(imp =>
        implementOptionLabel(imp).toLowerCase() === t ||
        _implementLegacyLabel(imp).toLowerCase() === t ||
        (imp.profileName || '').toLowerCase() === t) || null;
}

// ---- Implement must come from the Implements list ----
// Once the Implements list has entries, a unit's implement is one of them:
// the form, Bulk Edit, inline edit and CSV import all refuse anything else,
// and save the list's own spelling ("bed ripper - gessner" is stored as
// "Bed Ripper — Gessner"). A value already on a unit is never forced off it —
// it stays until someone changes it; Data Check lists those.
function implementListActive() { return globalImplements.length > 0; }

// The list record a typed value means: exact label first, then by type and
// brand (any case, either order, "-" or "—").
function findImplementRecord(text) {
    const t = _toolNorm(text);
    if (!t) return null;
    const exact = matchImplementForUnit(t);
    if (exact) return exact;
    const p = toolPartsOf({ implement: t }, 'tractor');
    const type = p.type.toLowerCase(), brand = p.brand.toLowerCase();
    return globalImplements.find(imp => _toolNorm(imp.equipmentType).toLowerCase() === type
        && _toolNorm(imp.brand).toLowerCase() === brand) || null;
}

// { ok, value } for a new implement value. `previous` is what the unit holds
// now: keeping an old off-list value is allowed, choosing a new one is not.
function checkImplementValue(text, previous) {
    const t = _toolNorm(text);
    if (!t) return { ok: true, value: '' };
    if (!implementListActive()) return { ok: true, value: t };
    const imp = findImplementRecord(t);
    if (imp) return { ok: true, value: implementOptionLabel(imp) };
    if (previous != null && _toolNorm(previous) === t) return { ok: true, value: previous };
    return { ok: false, value: t };
}

const IMPLEMENT_NOT_IN_LIST = 'is not in the Implements list — pick one from the list, or add it in the Implements menu first';

function updateImplementHint() {
    const hint = document.getElementById('formImplementHint');
    const input = document.getElementById('formImplement');
    if (!hint || !input) return;
    const t = _toolNorm(input.value);
    if (!implementListActive()) {
        hint.className = 'form-hint';
        hint.textContent = 'The Implements list is empty, so any text is accepted.';
        return;
    }
    const id = document.getElementById('editUnitId').value;
    const unit = id ? globalData.find(u => u.id === id) : null;
    const r = checkImplementValue(t, unit ? unit.implement : null);
    const imp = t ? findImplementRecord(t) : null;
    hint.className = 'form-hint' + (r.ok ? (imp ? ' form-hint--ok' : '') : ' form-hint--bad');
    hint.textContent = !t ? 'Pick from the Implements list, or leave empty.'
        : imp ? `In the Implements list${imp.code ? ' · code ' + imp.code : ''}${r.value !== t ? ' · saved as "' + r.value + '"' : ''}`
        : r.ok ? 'Current value — not in the Implements list. Pick one from the list when you can.'
        : `"${t}" ${IMPLEMENT_NOT_IN_LIST}.`;
}

// One form, two groups. The other group's sections are hidden AND disabled,
// so they are neither validated nor read. A heavy unit therefore never reaches
// the John Deere component selects — whose "isGood(x) ? 'Good' : 'Breakdown'"
// preselect turned every blank field into 'Breakdown' and wrote it on Save.
function setUnitFormGroup(g) {
    document.getElementById('formUnitGroup').value = g;
    document.querySelectorAll('#unitForm [data-group-only]').forEach(el => {
        const match = el.dataset.groupOnly === g;
        el.style.display = match ? '' : 'none';
        el.querySelectorAll('input, select, textarea').forEach(i => { i.disabled = !match; });
    });
    document.querySelectorAll('#unitForm option[data-temp]').forEach(o => o.remove());
    const legend = document.getElementById('unitFormLegend');
    if (legend) legend.textContent = g === 'heavy' ? 'Category & Notes' : 'Category, License & Notes';
    if (g === 'heavy') populateHeavySuggestionLists();
}

function populateHeavySuggestionLists() {
    const heavy = globalData.filter(isHeavy);
    const fill = (id, items) => {
        const el = document.getElementById(id);
        if (el) el.innerHTML = items.map(v => `<option value="${escapeHtml(v)}"></option>`).join('');
    };
    fill('heavyMachineTypeList', _mergeSuggestions(HEAVY_MACHINE_TYPES, heavy.map(u => u.machineType)));
    fill('heavyWorkToolList', _mergeSuggestions(HEAVY_WORK_TOOLS, heavy.map(u => u.workTool)));
}

// A heavy component with no value shows "— belum diisi —" and is not sent,
// instead of being silently turned into 'Breakdown' (or written as '').
function setHealthSelect(el, v) {
    if (isGood(v)) { el.value = 'Good'; return; }
    if (!sameStoredValue(v, '')) { el.value = 'Breakdown'; return; }
    el.insertAdjacentHTML('afterbegin', '<option value="" data-temp>— not set —</option>');
    el.value = '';
}

function showAddForm() {
    if (!requireEdit('editUnits')) return;
    _unitFormShown = null;
    const g = effectiveEditGroup();
    document.getElementById('modalTitle').textContent = g === 'heavy' ? `Add ${UNIT_GROUPS.heavy.label}` : 'Add Unit';
    document.getElementById('editUnitId').value = '';
    document.getElementById('unitForm').reset();
    setUnitFormGroup(g);
    renderUserCategoryOptions();
    populateImplementUnitList();
    updateImplementHint();
    document.getElementById('unitModal').classList.add('open');
}

function editUnit(id) {
    if (!requireEdit('editUnits')) return;
    const unit = globalData.find(d => d.id === id);
    if (!unit) return;
    // The tractor form would read its absent components as 'Breakdown' and
    // write them back on Save — the damage the unit's group exists to stop.
    if (hasUnreadableGroup(unit)) {
        // showToast renders HTML, and this value is by definition one nobody
        // vetted — escape it.
        showToast(`This unit's group ("${plainText(unit.unitGroup)}") is unknown. Set it first via Decision Inbox → Data Check.`, 'warning');
        return;
    }

    const g = unitGroupOf(unit);
    setUnitFormGroup(g);
    if (g === 'heavy') { editHeavyUnit(unit); return; }

    document.getElementById('modalTitle').textContent = 'Edit Unit';
    document.getElementById('editUnitId').value = id;
    // `|| ''`: an absent field assigned as-is shows — and saves — "undefined".
    document.getElementById('formName').value = unit.name || '';
    document.getElementById('formModel').value = unit.model || '';
    document.getElementById('formSN').value = unit.sn || '';
    populateImplementUnitList();
    document.getElementById('formImplement').value = unit.implement || '';
    document.getElementById('formSite').value = unit.site || '';
    document.getElementById('formYearReceived').value = unit.yearReceived || '';
    document.getElementById('formStatus').value = isGood(unit.status) ? 'Good' : 'Breakdown';
    document.getElementById('formDisplay').value = isGood(unit.display) ? 'Good' : 'Breakdown';
    document.getElementById('formGPS').value = isGood(unit.gps) ? 'Good' : 'Breakdown';
    document.getElementById('formSteering').value = isGood(unit.steering) ? 'Good' : 'Breakdown';
    document.getElementById('formJDLink').value = isGood(unit.jdlink) ? 'Good' : 'Breakdown';

    // License & notes
    renderUserCategoryOptions();
    document.getElementById('formUserCategory').value   = unit.userCategory || '';
    document.getElementById('formGpsLicense').value     = unit.gpsLicense || '';
    document.getElementById('formLicenseDisplay').value = unit.licenseDisplay || '';
    // New dual-license date pairs; fall back to legacy licenseStartDate /
    // licenseEndDate (which were GPS-license dates historically) if the new
    // GPS-specific fields are empty.
    document.getElementById('formGpsLicenseStart').value =
        unit.gpsLicenseStartDate || unit.licenseStartDate || '';
    document.getElementById('formGpsLicenseEnd').value =
        unit.gpsLicenseEndDate || unit.licenseEndDate || '';
    document.getElementById('formDisplayLicenseStart').value = unit.displayLicenseStartDate || '';
    document.getElementById('formDisplayLicenseEnd').value   = unit.displayLicenseEndDate || '';
    document.getElementById('formRemarks').value        = unit.remarks || '';

    // Show breakdown reason if this unit is currently in Breakdown
    const bdBox = document.getElementById('breakdownReasonDisplay');
    const bdInfo = document.getElementById('breakdownReasonInfo');
    if (!isGood(unit.status) && unit.breakdownReason) {
        bdInfo.textContent = unit.breakdownReason;
        bdBox.style.display = '';
    } else {
        bdInfo.textContent = '';
        bdBox.style.display = 'none';
    }

    _unitFormShown = readUnitForm('tractor');
    updateImplementHint();
    document.getElementById('unitModal').classList.add('open');
}

function editHeavyUnit(unit) {
    const set = (id, v) => { document.getElementById(id).value = v == null ? '' : v; };
    document.getElementById('modalTitle').textContent = `Edit ${UNIT_GROUPS.heavy.label}`;
    set('editUnitId', unit.id);
    set('formName', unit.name); set('formModel', unit.model); set('formSN', unit.sn);
    set('formHeavyBrand', unit.brand);
    set('formMachineType', unit.machineType); set('formAssetCode', unit.assetCode); set('formWorkTool', unit.workTool);
    set('formSite', unit.site); set('formYearReceived', unit.yearReceived);
    document.getElementById('formStatus').value = isGood(unit.status) ? 'Good' : 'Breakdown';
    HEAVY_FORM_SELECTS.forEach(([key, elId]) => setHealthSelect(document.getElementById(elId), unit[key]));
    renderUserCategoryOptions();
    set('formUserCategory', unit.userCategory);
    set('formRemarks', unit.remarks);
    const bdBox = document.getElementById('breakdownReasonDisplay');
    const bdInfo = document.getElementById('breakdownReasonInfo');
    const show = !isGood(unit.status) && unit.breakdownReason;
    bdInfo.textContent = show ? unit.breakdownReason : '';
    bdBox.style.display = show ? '' : 'none';
    _unitFormShown = readUnitForm('heavy');
    updateImplementHint();
    document.getElementById('unitModal').classList.add('open');
}
const HEAVY_FORM_SELECTS = [['cameraAi', 'formCameraAi'], ['telematicBox', 'formTelematicBox'],
                            ['switchLimiter', 'formSwitchLimiter'], ['rotaryLamp', 'formRotaryLamp']];

// Checked on the form, not inside updateUnit, so the message appears once and
// a bulk CSV import is not stopped row by row.
//
// addUnits has always rejected a duplicate serial number; updateUnit never
// looked at it, so the edit form could quietly create a second unit with the
// same SN. That matters more than it sounds: SN is the key a CSV import
// matches on, so a duplicate makes every later import ambiguous about which
// unit it is updating. saveDevice already does this correctly.
function checkUnitFields(id, fields) {
    if (fields.implement !== undefined) {
        const unit = id ? globalData.find(u => u.id === id) : null;
        const r = checkImplementValue(fields.implement, unit ? unit.implement : null);
        if (!r.ok) {
            showToast(`Implement "${r.value}" ${IMPLEMENT_NOT_IN_LIST}`, 'warning');
            const el = document.getElementById('formImplement');
            if (el) el.focus();
            return false;
        }
        fields.implement = r.value;
    }
    if (fields.brand !== undefined) {
        const unit = id ? globalData.find(u => u.id === id) : null;
        const r = checkMasterValue('heavyBrand', fields.brand, unit ? unit.brand : null);
        if (!r.ok) {
            showToast(`Brand "${r.value}" ${masterNotInList('heavyBrand')}`, 'warning');
            const el = document.getElementById('formHeavyBrand');
            if (el) el.focus();
            return false;
        }
        fields.brand = r.value;
    }
    if (fields.site !== undefined) {
        const unit = id ? globalData.find(u => u.id === id) : null;
        const r = checkMasterValue('site', fields.site, unit ? unit.site : null);
        if (!r.ok) {
            showToast(`Site "${r.value}" ${masterNotInList('site')}`, 'warning');
            const el = document.getElementById('formSite');
            if (el) el.focus();
            return false;
        }
        fields.site = r.value;
    }
    const sn = (fields.sn || '').trim();
    if (sn) {
        const clash = globalData.find(u => u.id !== id && (u.sn || '').toLowerCase() === sn.toLowerCase());
        if (clash) {
            // Serial numbers are unique across BOTH groups. Name the group only
            // when the clash is in the other one, so the tractor message is
            // unchanged.
            const self = id ? globalData.find(u => u.id === id) : null;
            const mine = self ? unitGroupOf(self) : normalizeGroupKey(fields.unitGroup) || 'tractor';
            const where = unitGroupOf(clash) !== mine ? ` (${groupDef(unitGroupOf(clash)).shortLabel})` : '';
            showToast(`SN "${sn}" is already used by unit "${clash.name || '-'}"${where}`, 'warning');
            return false;
        }
    }
    // A duplicate asset code is unusual but not impossible (a re-painted hull),
    // so it asks rather than refuses.
    const code = (fields.assetCode || '').trim();
    if (code) {
        const dup = globalData.find(u => u.id !== id && isHeavy(u) && (u.assetCode || '').trim().toLowerCase() === code.toLowerCase());
        if (dup && !confirm(`Asset number "${code}" is already used by "${dup.name || '-'}". Save anyway?`)) return false;
    }
    // An end date before its start date leaves the unit reading "expired" while
    // its licence has not begun — and applyExpiredLicenseDowngrades acts on it.
    const ranges = [
        ['GPS', fields.gpsLicenseStartDate, fields.gpsLicenseEndDate],
        ['Display', fields.displayLicenseStartDate, fields.displayLicenseEndDate]
    ];
    for (const [label, from, to] of ranges) {
        if (from && to && to < from) {
            showToast(`The ${label} license expiry date is earlier than its start date`, 'warning');
            return false;
        }
    }
    return true;
}

function heavyFormFields() {
    const val = id => document.getElementById(id).value.trim();
    const f = {
        name: val('formName'), model: val('formModel'), sn: val('formSN'), brand: val('formHeavyBrand'),
        machineType: val('formMachineType'), assetCode: val('formAssetCode'), workTool: val('formWorkTool'),
        site: val('formSite'), yearReceived: val('formYearReceived'),
        status: document.getElementById('formStatus').value,
        userCategory: document.getElementById('formUserCategory').value,
        remarks: val('formRemarks')
    };
    // A component left on "— belum diisi —" is simply not sent.
    HEAVY_FORM_SELECTS.forEach(([key, elId]) => {
        const v = document.getElementById(elId).value;
        if (v !== '') f[key] = v;
    });
    return f;
}

function saveUnit(event) {
    event.preventDefault();
    if (!requireEdit('editUnits')) return;

    const id = document.getElementById('editUnitId').value;
    // The group of an existing unit comes from the unit — it cannot change.
    const existing = id ? globalData.find(d => d.id === id) : null;
    const g = existing ? unitGroupOf(existing)
                       : (document.getElementById('formUnitGroup').value === 'heavy' ? 'heavy' : 'tractor');
    const full = readUnitForm(g);
    // Editing writes only what the person CHANGED on the form, compared with
    // what it showed when it opened. Writing the whole form rewrote fields
    // nobody touched: a category not in the list became '', a blank
    // component became 'Breakdown', and a status another device set while
    // the form was open was quietly set back.
    let fields = full;
    if (existing && _unitFormShown) {
        fields = {};
        Object.keys(full).forEach(k => { if (full[k] !== _unitFormShown[k]) fields[k] = full[k]; });
        if (!Object.keys(fields).length) {
            showToast('No changes', 'info');
            closeModal(true);
            return;
        }
    }
    // Stamped here — BEFORE the breakdown-reason stash below. A new unit saved
    // as Breakdown goes through that stash and is committed later from it, so
    // stamping afterwards would be lost and the unit would land as a tractor.
    if (!id) fields.unitGroup = g;

    const checked = { ...full, ...fields };
    if (!checkUnitFields(id, checked)) return;
    // checkUnitFields stores the Implements list's own spelling.
    if (fields.implement !== undefined) fields.implement = checked.implement;
    if (fields.site !== undefined) fields.site = checked.site;
    if (fields.brand !== undefined) fields.brand = checked.brand;

    if (existing && !confirmGoodWithOpenDamage([{ unit: existing, fields }])) return;

    // If status is changing TO Breakdown, prompt for a reason first.
    if (fields.status !== undefined && !isGood(fields.status)) {
        const existingUnit = id ? globalData.find(d => d.id === id) : null;
        const wasGood = existingUnit ? isGood(existingUnit.status) : true;
        if (wasGood) {
            _pendingBreakdown = { unitId: id, fields, isInline: false };
            document.getElementById('breakdownReasonText').value = '';
            document.getElementById('breakdownReasonModal').classList.add('open');
            return;
        }
    }

    _commitSaveUnit(id, fields);
}

let _unitFormShown = null;   // the edit form's values when it opened

function readUnitForm(g) {
    return g === 'heavy' ? heavyFormFields() : {
        name: document.getElementById('formName').value.trim(),
        model: document.getElementById('formModel').value.trim(),
        sn: document.getElementById('formSN').value.trim(),
        implement: document.getElementById('formImplement').value.trim(),
        site: document.getElementById('formSite').value.trim(),
        yearReceived: document.getElementById('formYearReceived').value.trim(),
        status: document.getElementById('formStatus').value,
        display: document.getElementById('formDisplay').value,
        gps: document.getElementById('formGPS').value,
        steering: document.getElementById('formSteering').value,
        jdlink: document.getElementById('formJDLink').value,
        userCategory: document.getElementById('formUserCategory').value,
        gpsLicense: document.getElementById('formGpsLicense').value,
        licenseDisplay: document.getElementById('formLicenseDisplay').value,
        gpsLicenseStartDate: document.getElementById('formGpsLicenseStart').value || '',
        gpsLicenseEndDate:   document.getElementById('formGpsLicenseEnd').value   || '',
        displayLicenseStartDate: document.getElementById('formDisplayLicenseStart').value || '',
        displayLicenseEndDate:   document.getElementById('formDisplayLicenseEnd').value   || '',
        remarks: document.getElementById('formRemarks').value.trim()
    };
}

function _commitSaveUnit(id, fields) {
    if (!requireEdit('editUnits')) return;
    if (id) {
        const nm = fields.name || ((globalData.find(d => d.id === id) || {}).name) || '';
        if (updateUnit(id, fields)) showToast(`Unit "${nm}" updated`, 'success');
        else showToast(`Unit "${nm}" not saved — no changes you are allowed to write`, 'warning');
    } else {
        const firstHeavy = fields.unitGroup === 'heavy' && !hasHeavyUnits();
        const newUnit = { id: generateId(), ...fields, downtimeHistory: [], breakdownStartedAt: null };
        const { added, skippedDetails } = addUnits([newUnit]);
        const reason = skippedDetails && skippedDetails[0] && skippedDetails[0].reason;
        if (added > 0) {
            showToast(`Unit "${fields.name}" added`, 'success');
            // The scope selector exists only when both groups do; with
            // heavy units alone the dashboard simply shows them.
            if (firstHeavy) showToast(hasTractorUnits()
                ? `${UNIT_GROUPS.heavy.label} shows on the Dashboard via the ${UNIT_GROUPS.heavy.label} / All scope`
                : `${UNIT_GROUPS.heavy.label} now shows on the Dashboard`, 'info');
        } else if (!reason || reason === 'Duplicate serial number') {
            showToast(`Duplicate serial number "${fields.sn}" — unit not added`, 'warning');
        } else {
            showToast(`${reason} — unit not added`, 'warning');
        }
    }

    closeModal(true);
    renderEditTable();
}

// Auto-fill expiration to start + 1 year (still editable). One helper per
// license kind so the onchange on each start-date input targets the right
// expiration field.
function autoFillGpsLicenseEnd()     { _autoFillEnd('formGpsLicenseStart',     'formGpsLicenseEnd'); }
function autoFillDisplayLicenseEnd() { _autoFillEnd('formDisplayLicenseStart', 'formDisplayLicenseEnd'); }
function _autoFillEnd(startId, endId) {
    const startEl = document.getElementById(startId);
    const endEl = document.getElementById(endId);
    if (!startEl || !endEl) return;
    if (!startEl.value) return;
    if (endEl.value) return;
    const end = addOneYearISO(startEl.value);
    if (!end) return;
    endEl.value = end;
}

// Compute expiry status for a single end-date string.
// Returns one of: { kind: 'none'|'expired'|'soon'|'ok', label, daysLeft }
function getExpiryStatus(endDate) {
    if (!endDate) return { kind: 'none', label: '—' };
    const end = parseLocalDate(endDate);
    if (!end) return { kind: 'none', label: '—' };
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    end.setHours(0, 0, 0, 0);
    const days = Math.round((end - today) / 86400000);
    if (days < 0)  return { kind: 'expired', label: `Expired ${-days}d ago`, daysLeft: days };
    if (days <= 30) return { kind: 'soon',    label: `${days}d left`,        daysLeft: days };
    return { kind: 'ok', label: `${days}d left`, daysLeft: days };
}

// Auto-downgrade: a premium license that has EXPIRED falls back to the lower
// tier (GPS SF-RTK → SF-1, Display G5 Advance → G5 Basic). Display-only —
// the stored value stays as-is; renewing the date brings the premium tier back.
function effectiveLicense(unit, kind) {
    const rawType = kind === 'display' ? (unit.licenseDisplay || '') : (unit.gpsLicense || '');
    const end = getLicenseEndDate(unit, kind);
    const status = getExpiryStatus(end);
    const premium  = kind === 'display' ? 'G5 Advance' : 'SF-RTK';
    const fallback = kind === 'display' ? 'G5 Basic'   : 'SF-1';
    const downgraded = rawType === premium && status.kind === 'expired';
    // Already written down to the fallback tier by applyExpiredLicenseDowngrades:
    // rawType and end carry no trace of that any more, so the archived expiry is
    // what says it happened. Requiring an empty end date keeps a unit that was
    // simply issued a fresh fallback licence from being mislabelled.
    const archived = kind === 'display' ? unit.displayLicenseExpiredAt : unit.gpsLicenseExpiredAt;
    if (!downgraded && rawType === fallback && archived && !end) {
        return { type: fallback, rawType, premium, fallback, downgraded: true, status, end: archived };
    }
    return { type: downgraded ? fallback : rawType, rawType, premium, fallback, downgraded, status, end };
}

// Once a premium licence's expiry has passed the receiver really is running on
// the lower tier, so write that into the data instead of only painting it:
// SF-RTK → SF-1, G5 Advance → G5 Basic, clearing the expiry date because the
// fallback tier has none. The premium tier is not lost — it stays in the
// licence-stock ledger, and recording a new Distribusi restores it with fresh
// dates. Idempotent: once a unit reads SF-1 it no longer matches.
let _downgradeScanQueued = false;
function scheduleExpiredLicenseDowngrades() {
    if (_downgradeScanQueued) return;
    _downgradeScanQueued = true;
    // Deferred so it runs outside applyCloudUnitsSnapshot's suppressCloudWrites
    // window — otherwise the change would never reach Firestore.
    setTimeout(() => { _downgradeScanQueued = false; applyExpiredLicenseDowngrades(); }, 0);
}

function applyExpiredLicenseDowngrades() {
    // Viewers must not write; their session would just fail against the rules.
    if (!hasAccess('editUnits', 'edit')) return 0;
    // A device copy reloaded when an account limit changed may be weeks old:
    // writing whole units from it would undo newer changes in the cloud.
    if (_unitsFromDeviceOnly) return 0;
    let n = 0;
    globalData.slice().forEach(u => {
        // SF/G5 licences are John Deere only — and a unit of unreadable group
        // is not known to be one.
        if (isHeavy(u) || hasUnreadableGroup(u)) return;
        const fields = {};
        // Only a date written as YYYY-MM-DD is trusted enough to act on: a
        // stored '01/10/2026' reads month-first, looks expired, and would
        // downgrade a licence that is still valid — permanently.
        if (u.gpsLicense === 'SF-RTK' && isoDistributionDate(getLicenseEndDate(u, 'gps')) &&
            getExpiryStatus(getLicenseEndDate(u, 'gps')).kind === 'expired') {
            fields.gpsLicense = 'SF-1';
            // Keep the expiry that caused the downgrade. Blanking it outright
            // destroyed the only record of when the premium tier ran out, and
            // the only way to tell a unit that was downgraded from one that
            // never held a premium licence at all.
            fields.gpsLicenseExpiredAt = getLicenseEndDate(u, 'gps');
            fields.gpsLicenseEndDate = '';
            // getLicenseEndDate falls back to the legacy field, so clear it too.
            if (u.licenseEndDate) fields.licenseEndDate = '';
        }
        if (u.licenseDisplay === 'G5 Advance' && isoDistributionDate(getLicenseEndDate(u, 'display')) &&
            getExpiryStatus(getLicenseEndDate(u, 'display')).kind === 'expired') {
            fields.licenseDisplay = 'G5 Basic';
            fields.displayLicenseExpiredAt = getLicenseEndDate(u, 'display');
            fields.displayLicenseEndDate = '';
        }
        if (Object.keys(fields).length && updateUnit(u.id, fields)) n++;
    });
    if (n > 0) {
        showToast(`${n} unit(s) automatically moved to the fallback tier (license expired)`, 'info');
        if (currentView === 'editUnits') renderEditTable();
        else if (currentView === 'dashboard') updateDashboard(filteredData);
    }
    return n;
}

// Render the license-type badge for a table cell, showing the effective tier
// (with a small marker + tooltip when auto-downgraded).
function licenseTypeBadge(unit, kind) {
    const eff = effectiveLicense(unit, kind);
    if (!eff.type) return '<span style="color:var(--text-light);font-size:11px">—</span>';
    if (eff.downgraded) {
        const tt = `Auto-downgraded from ${eff.premium} (expired ${eff.end})`;
        return `<span class="badge badge-cat" style="font-size:10px" title="${escapeHtml(tt)}"><i class="fas fa-arrow-turn-down" style="font-size:9px;opacity:.7"></i> ${escapeHtml(eff.type)}</span>`;
    }
    return `<span class="badge badge-good" style="font-size:10px">${escapeHtml(eff.type)}</span>`;
}

// Pick the effective end date for a license kind. Falls back to the legacy
// `licenseEndDate` for `gps` only, since historically that single field
// stored the GPS-license expiry. Display kind has no legacy fallback.
function getLicenseEndDate(unit, kind) {
    if (!unit) return '';
    if (kind === 'display') return unit.displayLicenseEndDate || '';
    return unit.gpsLicenseEndDate || unit.licenseEndDate || '';
}

// Render an expiry badge for either 'gps' or 'display' license.
function licenseBadgeFor(unit, kind) {
    const end = getLicenseEndDate(unit, kind);
    const s = getExpiryStatus(end);
    if (s.kind === 'none') return '<span style="color:var(--text-light);font-size:11px">—</span>';
    // Auto-downgraded premium → show a neutral "on fallback tier" badge instead
    // of a red expired one (the receiver still works on SF-1 / G5 Basic).
    const eff = effectiveLicense(unit, kind);
    if (eff.downgraded) {
        const tt = `Auto-fallback from ${eff.premium} (expired ${end})`;
        return `<span class="license-badge license-badge--ok" title="${escapeHtml(tt)}"><i class="fas fa-circle-check"></i> ${escapeHtml(eff.fallback)}</span>`;
    }
    const cls = `license-badge license-badge--${s.kind}`;
    const icon = s.kind === 'expired' ? 'circle-xmark'
               : s.kind === 'soon'    ? 'triangle-exclamation'
               : 'circle-check';
    const labelName = kind === 'display' ? (unit.licenseDisplay || 'Display') : (unit.gpsLicense || 'GPS');
    const tt = `${labelName} · Expires: ${end}`;
    return `<span class="${cls}" title="${escapeHtml(tt)}"><i class="fas fa-${icon}"></i> ${escapeHtml(s.label)}</span>`;
}

// force: after a save, when nothing typed is being thrown away.
function closeModal(force) {
    if (!force && document.getElementById('unitModal').classList.contains('open') && !okToDiscardTyping('unitForm')) return;
    document.getElementById('unitModal').classList.remove('open');
}

// ============================================================
// IMPLEMENTS — CRUD, storage, render, modal
// ============================================================

const IMPLEMENT_FIELDS = [
    { key: 'profileName',        inputId: 'implProfileName',        label: 'Profile Name' },
    { key: 'brand',              inputId: 'implBrand',              label: 'Brand' },
    { key: 'equipmentType',      inputId: 'implEquipmentType',      label: 'Type of Equipment' },
    { key: 'code',               inputId: 'implCode',               label: 'Code' },
    { key: 'lateralOffset',      inputId: 'implLateralOffset',      label: 'Lateral Offset' },
    { key: 'centerOfRotation',   inputId: 'implCenterOfRotation',   label: 'Center of Rotation' },
    { key: 'rearConnection',     inputId: 'implRearConnection',     label: 'Rear Connection' },
    { key: 'operation',          inputId: 'implOperation',          label: 'Operation' },
    { key: 'workingWidth',       inputId: 'implWorkingWidth',       label: 'Working Width' },
    { key: 'workPoint',          inputId: 'implWorkPoint',          label: 'Work Point' },
    { key: 'workRecording',      inputId: 'implWorkRecording',      label: 'Work Recording' },
    { key: 'connectingType',     inputId: 'implConnectingType',     label: 'Connecting Type' },
    { key: 'implementReceiver',  inputId: 'implImplementReceiver',  label: 'Implement Receiver' }
];

function generateImplementId() {
    return 'imp_' + Date.now() + '_' + Math.random().toString(36).substr(2, 5);
}

// ---- Chart of Account dynamic list ----
function renderChartOfAccountsInputs(values) {
    const container = document.getElementById('implChartOfAccountsList');
    if (!container) return;
    const list = (Array.isArray(values) && values.length) ? values : [''];
    container.innerHTML = list.map(v => `
        <div class="coa-row">
            <input type="text" class="form-input coa-input" value="${escapeHtml(v)}" placeholder="e.g. 5100-001 Spare Parts">
            <button type="button" class="btn btn-secondary coa-remove" onclick="removeChartOfAccountRow(this)" title="Remove">
                <i class="fas fa-xmark"></i>
            </button>
        </div>
    `).join('');
}

function addChartOfAccountRow() {
    const container = document.getElementById('implChartOfAccountsList');
    if (!container) return;
    const row = document.createElement('div');
    row.className = 'coa-row';
    row.innerHTML = `
        <input type="text" class="form-input coa-input" placeholder="e.g. 5100-001 Spare Parts">
        <button type="button" class="btn btn-secondary coa-remove" onclick="removeChartOfAccountRow(this)" title="Remove">
            <i class="fas fa-xmark"></i>
        </button>
    `;
    container.appendChild(row);
    row.querySelector('input').focus();
}

function removeChartOfAccountRow(btn) {
    const row = btn.closest('.coa-row');
    if (row) row.remove();
    // Always keep at least one empty row so the UI never looks empty.
    const container = document.getElementById('implChartOfAccountsList');
    if (container && container.children.length === 0) {
        renderChartOfAccountsInputs(['']);
    }
}

function collectChartOfAccounts() {
    return Array.from(document.querySelectorAll('#implChartOfAccountsList .coa-input'))
        .map(i => i.value.trim())
        .filter(Boolean);
}

// ---- Storage ----
function loadImplements() {
    // Agricultural only: not for a heavy-equipment-only account.
    if (!unitScopeAllows('tractor')) { globalImplements = []; updateImplementCount(); return false; }
    try {
        const raw = localStorage.getItem(IMPLEMENTS_STORAGE_KEY);
        globalImplements = raw ? JSON.parse(raw) : [];
    } catch (e) {
        globalImplements = [];
    }
    updateImplementCount();
    return globalImplements.length > 0;
}

function saveImplements() {
    try {
        localStorage.setItem(IMPLEMENTS_STORAGE_KEY, JSON.stringify(globalImplements));
    } catch (e) {
        showToast('Storage is full. Implement not saved.', 'error');
    }
}

function updateImplementCount() {
    const el = document.getElementById('implementCount');
    const n = globalImplements.length;
    if (el) el.textContent = `${n} ${n === 1 ? 'profile' : 'profiles'}`;
}

// ---- Tractors per implement type (Unit Database) ----
// Keys match the Unit Database's implement filter (toolKeyOf): the type in
// lower case, or TOOL_NONE for tractors with no implement.
let _implUseAll = false;
const IMPL_USE_LIMIT = 11;

function implementUseRows() {
    const known = _knownImplementBrands();
    const map = new Map();
    let none = 0;
    const tractors = unitsOfGroup(globalData, 'tractor');
    tractors.forEach(u => {
        const t = toolPartsOf(u, 'tractor', known).type;
        if (!t) { none++; return; }
        const k = t.toLowerCase();
        const cur = map.get(k) || { key: k, spell: new Map(), count: 0 };
        cur.count++;
        cur.spell.set(t, (cur.spell.get(t) || 0) + 1);
        map.set(k, cur);
    });
    const rows = [...map.values()].map(r => ({ key: r.key, count: r.count, label: _pickLabel(r.spell) }))
        .sort((a, b) => b.count - a.count || a.label.localeCompare(b.label));
    return { rows, none, total: tractors.length };
}

function toggleImplementUseAll() {
    _implUseAll = !_implUseAll;
    renderImplementUseTiles();
}

function renderImplementUseTiles() {
    const sec = document.getElementById('implUseSection');
    const box = document.getElementById('implUseTiles');
    if (!sec || !box) return;
    const { rows, none, total } = implementUseRows();
    sec.hidden = !total;
    if (!total) { box.innerHTML = ''; return; }
    // A tile opens Units filtered to those tractors — for whoever may open Units.
    const canOpen = canViewView('editUnits');
    const cut = rows.length > IMPL_USE_LIMIT + 1 && !_implUseAll;
    const tile = (key, n, label, extra) => {
        const inner = `<span class="fp-use__n">${n}</span><span class="fp-use__label">${escapeHtml(label)}</span>`;
        return canOpen
            ? `<button type="button" class="fp-use__tile${extra}" aria-label="${escapeHtml(label)}: ${n} ${n === 1 ? 'tractor' : 'tractors'}, show them in Units"
                onclick="openUnitsForImplement(${jsArg(key)})">${inner}</button>`
            : `<div class="fp-use__tile${extra}">${inner}</div>`;
    };
    box.innerHTML = (cut ? rows.slice(0, IMPL_USE_LIMIT) : rows).map(r => tile(r.key, r.count, r.label, '')).join('')
        + (none ? tile(TOOL_NONE, none, 'No implement set', ' fp-use__tile--warn') : '')
        + (rows.length > IMPL_USE_LIMIT + 1 ? `<button type="button" class="fp-use__tile fp-use__tile--more" aria-expanded="${_implUseAll}" onclick="toggleImplementUseAll()">${
            _implUseAll ? 'Show fewer' : `+${rows.length - IMPL_USE_LIMIT} more types`}</button>` : '');
}

function openUnitsForImplement(key) {
    navigateTo('editUnits');
    if (currentView !== 'editUnits') return;   // no access to Units
    switchEditUnitsGroup('tractor', { persist: false });
    setEditToolFilter(key);
}

// Unit snapshots change the tractor counts.
document.addEventListener('ot:data', () => { if (currentView === 'implements') renderImplementUseTiles(); });

// Equipment types in the Implements list, for the Type filter.
function populateImplementTypeFilter() {
    const sel = document.getElementById('implementTypeFilter');
    if (!sel) return;
    const byKey = new Map();
    globalImplements.forEach(d => {
        const t = _toolNorm(d.equipmentType);
        if (t && !byKey.has(t.toLowerCase())) byKey.set(t.toLowerCase(), t);
    });
    const cur = sel.value;
    sel.innerHTML = '<option value="">All types</option>' + [...byKey.entries()]
        .sort((a, b) => a[1].localeCompare(b[1]))
        .map(([k, t]) => `<option value="${escapeHtml(k)}">${escapeHtml(t)}</option>`).join('');
    sel.value = byKey.has(cur) ? cur : '';
}

// ---- Render ----
function renderImplementsTable() {
    updateImplementCount();
    renderImplementUseTiles();
    populateImplementTypeFilter();
    // A re-render (search, filter, a cloud snapshot) draws fresh, unticked
    // rows — so the selection is dropped with them. Re-reading the OLD boxes
    // here kept "Delete selected" armed for rows no longer on screen.
    document.querySelectorAll('.impl-check').forEach(cb => { cb.checked = false; });
    selectedImplementIds.clear();
    updateSelectedImplementCount();

    const selectAllBox = document.getElementById('selectAllImpl');
    if (selectAllBox) selectAllBox.checked = false;

    const query = (document.getElementById('implementSearch')?.value || '').toLowerCase().trim();
    const typeVal = document.getElementById('implementTypeFilter')?.value || '';
    const rows = globalImplements.filter(d =>
        (!typeVal || _toolNorm(d.equipmentType).toLowerCase() === typeVal)
        && (!query || `${d.profileName} ${d.brand || ''} ${d.equipmentType} ${d.code || ''} ${d.operation} ${d.connectingType} ${d.workingWidth}`
            .toLowerCase().includes(query)));
    const shown = document.getElementById('implementShown');
    if (shown) shown.textContent = rows.length === globalImplements.length ? '' : `${rows.length} of ${globalImplements.length}`;

    const tbody = document.getElementById('implementBody');
    if (!tbody) return;

    if (rows.length === 0) {
        tbody.innerHTML = `<tr><td colspan="11" style="text-align:center;padding:24px;color:var(--text-secondary)">${
            query || typeVal ? 'No implements match your search'
                  : 'No implements yet. Click <strong>Add implement</strong> to get started.'
        }</td></tr>`;
        return;
    }

    tbody.innerHTML = rows.map((d, i) => {
        const coaList = Array.isArray(d.chartOfAccounts) ? d.chartOfAccounts.filter(Boolean) : [];
        let coaCell;
        if (!coaList.length) {
            coaCell = '<span style="color:var(--text-light);font-size:11px">—</span>';
        } else if (coaList.length === 1) {
            coaCell = `<span class="badge badge-cat" style="font-size:10px">${escapeHtml(coaList[0])}</span>`;
        } else {
            const first = `<span class="badge badge-cat" style="font-size:10px">${escapeHtml(coaList[0])}</span>`;
            const rest = coaList.slice(1).map(c => `<span class="badge badge-cat" style="font-size:10px;margin:2px 0">${escapeHtml(c)}</span>`).join('');
            coaCell = `<div class="coa-cell">${first}<span class="coa-more" onclick="this.parentElement.classList.toggle('open');event.stopPropagation()">+${coaList.length - 1} more</span><div class="coa-dropdown">${rest}</div></div>`;
        }
        return `
        <tr>
            <td class="col-check"><input type="checkbox" class="impl-check" data-id="${escapeHtml(d.id)}" onchange="updateSelectedImplementCount()"></td>
            <td>${i + 1}</td>
            <td data-label="Profile Name"><strong>${escapeHtml(d.profileName)}</strong></td>
            <td data-label="Brand" class="fp-muted">${escapeHtml(d.brand || '') || '—'}</td>
            <td data-label="Equipment Type">${_toolNorm(d.equipmentType) ? `<span class="fp-chip fp-chip--neutral">${escapeHtml(_toolNorm(d.equipmentType))}</span>` : '<span class="fp-muted">—</span>'}</td>
            <td data-label="Code">${escapeHtml(d.code || '')}</td>
            <td data-label="Working Width">${escapeHtml(d.workingWidth)}</td>
            <td data-label="Operation">${escapeHtml(d.operation)}</td>
            <td data-label="Connecting Type">${escapeHtml(d.connectingType)}</td>
            <td data-label="Chart of Account" style="max-width:240px;white-space:nowrap">${coaCell}</td>
            <td class="col-actions">
                <div class="row-actions">
                    <button class="btn btn-secondary" title="Edit" aria-label="Edit ${escapeHtml(d.profileName || 'implement')}" onclick="editImplement(${jsArg(d.id)})"><i class="fas fa-pen" aria-hidden="true"></i></button>
                    <button class="btn btn-secondary" title="Delete" aria-label="Delete ${escapeHtml(d.profileName || 'implement')}" onclick="deleteImplement(${jsArg(d.id)})"><i class="fas fa-trash" style="color:var(--danger)" aria-hidden="true"></i></button>
                </div>
            </td>
        </tr>`;
    }).join('');
}

// ---- Selection ----
function toggleSelectAllImplements() {
    const checked = document.getElementById('selectAllImpl').checked;
    document.querySelectorAll('.impl-check').forEach(cb => { cb.checked = checked; });
    updateSelectedImplementCount();
}

function updateSelectedImplementCount() {
    selectedImplementIds.clear();
    document.querySelectorAll('.impl-check:checked').forEach(cb => selectedImplementIds.add(cb.dataset.id));
    const count = selectedImplementIds.size;
    const countEl = document.getElementById('selectedImplCount');
    const btn = document.getElementById('btnDeleteSelectedImpl');
    if (countEl) countEl.textContent = count;
    if (btn) btn.style.display = count > 0 ? '' : 'none';
}

// ---- Modal: Add / Edit ----
function showAddImplementForm() {
    if (!requireEdit('implements')) return;
    document.getElementById('implementModalTitle').textContent = 'Add Implement';
    document.getElementById('editImplementId').value = '';
    document.getElementById('implementForm').reset();
    renderChartOfAccountsInputs(['']);
    populateMasterDatalists();
    document.getElementById('implementModal').classList.add('open');
}

function editImplement(id) {
    if (!requireEdit('implements')) return;
    const imp = globalImplements.find(d => d.id === id);
    if (!imp) return;

    document.getElementById('implementModalTitle').textContent = 'Edit Implement';
    document.getElementById('editImplementId').value = id;
    IMPLEMENT_FIELDS.forEach(f => {
        const el = document.getElementById(f.inputId);
        if (el) el.value = imp[f.key] || '';
    });
    renderChartOfAccountsInputs(imp.chartOfAccounts || ['']);
    populateMasterDatalists();
    document.getElementById('implementModal').classList.add('open');
}

function saveImplement(event) {
    event.preventDefault();
    if (!requireEdit('implements')) return;

    const id = document.getElementById('editImplementId').value;
    const data = {};
    IMPLEMENT_FIELDS.forEach(f => {
        const el = document.getElementById(f.inputId);
        data[f.key] = el ? el.value.trim() : '';
    });
    data.chartOfAccounts = collectChartOfAccounts();
    {
        const prev = id ? (globalImplements.find(d => d.id === id) || {}).brand : null;
        const r = checkMasterValue('brand', data.brand, prev);
        if (!r.ok) {
            showToast(`Brand "${r.value}" ${masterNotInList('brand')}`, 'warning');
            const el = document.getElementById('implBrand');
            if (el) el.focus();
            return;
        }
        data.brand = r.value;
    }

    if (id) {
        // Update existing
        const idx = globalImplements.findIndex(d => d.id === id);
        if (idx !== -1) {
            const before = { ...globalImplements[idx] };
            // Units name an implement by its "Type — Brand" label. Found
            // BEFORE the record changes: afterwards their text no longer
            // resolves to it, and they would read as off-list.
            const oldRec = globalImplements[idx];
            const followers = (_toolNorm(before.equipmentType) !== _toolNorm(data.equipmentType) || _toolNorm(before.brand) !== _toolNorm(data.brand))
                ? unitsOfGroup(globalData, 'tractor').filter(u => u.implement && findImplementRecord(u.implement) === oldRec) : [];
            globalImplements[idx] = { ...before, ...data, updatedAt: Date.now() };
            saveImplements();
            cloudPushImplement(globalImplements[idx]);
            if (followers.length && hasAccess('editUnits', 'edit')) {
                const label = implementOptionLabel(globalImplements[idx]);
                updateUnitsBatch(new Map(followers.map(u => [u.id, { implement: label }])));
            }
            const moved = _toolNorm(before.equipmentType) !== _toolNorm(data.equipmentType)
                ? _carryLicenseRequirement(before.equipmentType, data.equipmentType) : '';
            if (followers.length || moved) showToast([followers.length ? `${followers.length} unit(s) now use the new name` : '', moved].filter(Boolean).join(' · '), 'info');
            // Audit log per changed field
            IMPLEMENT_FIELDS.forEach(f => {
                if (before[f.key] !== data[f.key]) {
                    logEvent({
                        action: 'update',
                        unitId: id,
                        unitName: `[Implement] ${data.profileName}`,
                        field: f.label,
                        before: before[f.key],
                        after: data[f.key]
                    });
                }
            });
            const beforeCoa = JSON.stringify(before.chartOfAccounts || []);
            const afterCoa = JSON.stringify(data.chartOfAccounts);
            if (beforeCoa !== afterCoa) {
                logEvent({
                    action: 'update',
                    unitId: id,
                    unitName: `[Implement] ${data.profileName}`,
                    field: 'Chart of Account',
                    before: (before.chartOfAccounts || []).join(', '),
                    after: data.chartOfAccounts.join(', ')
                });
            }
            showToast(`Implement "${data.profileName}" updated`, 'success');
        }
    } else {
        // Create new
        const newImp = {
            id: generateImplementId(),
            ...data,
            createdAt: Date.now(),
            updatedAt: Date.now()
        };
        globalImplements.push(newImp);
        saveImplements();
        cloudPushImplement(newImp);
        logEvent({
            action: 'add',
            unitId: newImp.id,
            unitName: `[Implement] ${newImp.profileName}`,
            after: newImp.equipmentType || newImp.profileName
        });
        showToast(`Implement "${newImp.profileName}" added`, 'success');
    }

    closeImplementModal();
    renderImplementsTable();
}

function closeImplementModal() {
    document.getElementById('implementModal').classList.remove('open');
}

// ---- Delete ----
function deleteImplement(id) {
    if (!requireEdit('implements')) return;
    const imp = globalImplements.find(d => d.id === id);
    if (!imp) return;
    if (!confirm(`Delete implement "${imp.profileName}"?`)) return;

    globalImplements = globalImplements.filter(d => d.id !== id);
    saveImplements();
    cloudDeleteImplement(id);
    logEvent({
        action: 'delete',
        unitId: imp.id,
        unitName: `[Implement] ${imp.profileName}`,
        before: imp.equipmentType || imp.profileName
    });
    renderImplementsTable();
    showToast(`Implement "${imp.profileName}" deleted`, 'success');
}

function deleteSelectedImplements() {
    if (!requireEdit('implements')) return;
    const count = selectedImplementIds.size;
    if (count === 0) return;
    if (!confirm(`Delete ${count} selected implement(s)?`)) return;

    const idSet = new Set(selectedImplementIds);
    const removed = globalImplements.filter(d => idSet.has(d.id));
    globalImplements = globalImplements.filter(d => !idSet.has(d.id));
    saveImplements();
    removed.forEach(imp => cloudDeleteImplement(imp.id));
    removed.forEach(imp => logEvent({
        action: 'delete',
        unitId: imp.id,
        unitName: `[Implement] ${imp.profileName}`,
        before: imp.equipmentType || imp.profileName
    }));
    renderImplementsTable();
    showToast(`${count} implement(s) deleted`, 'success');
}

// ---- Implements CSV: export / template / import ----
// Header aliases accepted on import (besides the canonical label).
function _implementColAliases(field) {
    const map = {
        equipmentType: ['Type of Equipment', 'Equipment Type'],
        profileName:   ['Profile Name', 'Profile'],
        workingWidth:  ['Working Width'],
        connectingType:['Connecting Type']
    };
    return map[field.key] || [field.label];
}

function exportImplementsCSV() {
    if (!canCsv('export')) return;
    if (globalImplements.length === 0) { showToast('No implements to export', 'warning'); return; }
    const headers = ['No', ...IMPLEMENT_FIELDS.map(f => f.label), 'Chart of Account'];
    const rows = globalImplements.map((d, i) => [
        i + 1,
        ...IMPLEMENT_FIELDS.map(f => d[f.key] || ''),
        (Array.isArray(d.chartOfAccounts) ? d.chartOfAccounts.filter(Boolean) : []).join('; ')
    ]);
    const csv = [headers, ...rows].map(row =>
        row.map(csvCell).join(',')).join('\n');
    const blob = new Blob(['﻿' + csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `implements_${toISODate()}.csv`;
    a.click();
    URL.revokeObjectURL(url);
    showToast(`${globalImplements.length} implement(s) exported to CSV`, 'success');
}

function downloadImplementTemplate() {
    if (!canCsv('export')) return;
    const headers = ['No', ...IMPLEMENT_FIELDS.map(f => f.label), 'Chart of Account'];
    // One example row (No is ignored on import).
    const sample = ['1', 'JNR Leopard E 10.0', 'John Deere', 'Scooping', 'IMP-001', '0 m', '1.2 m', '0.8 m',
        'Tillage', '3', 'Center', 'Manual', 'Drawbar', 'iGrade',
        '159361_Scooping; 159201_Offset Harrow'];
    const csv = [headers, sample].map(row =>
        row.map(csvCell).join(',')).join('\n');
    const blob = new Blob(['﻿' + csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'template_implements.csv';
    a.click();
    URL.revokeObjectURL(url);
}

function handleImplementCSVImport(file) {
    if (!canCsv('full')) return;
    if (!requireEdit('implements')) return;
    showLoading(true);
    Papa.parse(file, {
        header: true,
        skipEmptyLines: true,
        complete: result => {
            const added = [];
            let rejected = 0;
            let duplicates = 0;
            let badBrand = 0;
            // Profile name + code identify an implement. Without this,
            // re-importing an export doubled the whole list.
            const implKey = o => `${String(o.profileName || '').trim().toLowerCase()}|${String(o.code || '').trim().toLowerCase()}`;
            const seenImpl = new Set(globalImplements.map(implKey));
            result.data.forEach(row => {
                const obj = { id: generateImplementId() };
                IMPLEMENT_FIELDS.forEach(f => {
                    obj[f.key] = (getValAny(row, _implementColAliases(f)) || '').toString().trim();
                });
                if (!obj.profileName) { rejected++; return; }
                if (obj.brand) {
                    const r = checkMasterValue('brand', obj.brand, null);
                    if (!r.ok) { badBrand++; return; }
                    obj.brand = r.value;
                }
                if (seenImpl.has(implKey(obj))) { duplicates++; return; }
                seenImpl.add(implKey(obj));
                const coaRaw = (getValAny(row, ['Chart of Account', 'Chart of Accounts', 'COA']) || '').toString();
                obj.chartOfAccounts = coaRaw.split(/[;\n]/).map(s => s.trim()).filter(Boolean);
                obj.createdAt = Date.now();
                obj.updatedAt = Date.now();
                added.push(obj);
            });

            if (added.length > 0) {
                globalImplements.push(...added);
                saveImplements();
                if (!suppressCloudWrites && window.cloud?.isReady) {
                    // A rejected import used to survive only on the importer's
                    // device: the rows rendered as normal implements, existed
                    // nowhere else, and vanished on the next snapshot with no
                    // explanation. Roll the rows back out and say so instead.
                    const addedIds = new Set(added.map(o => o.id));
                    window.cloud.saveImplements(added).catch(err => {
                        globalImplements = globalImplements.filter(o => !addedIds.has(o.id));
                        saveImplements();
                        renderImplementsTable();
                        cloudWriteFailed(err, {
                            what: `import of ${added.length} implement(s)`,
                            label: '[Implement] Import CSV',
                            resync: resyncImplements
                        });
                    });
                }
                logEvent({ action: 'add', unitName: '[Implement] Import CSV', after: `${added.length} implement(s)` });
                renderImplementsTable();
            }

            showLoading(false);
            const msg = `Implement import: ${added.length} added` + (rejected ? `, ${rejected} skipped (Profile Name empty)` : '')
                + (duplicates ? `, ${duplicates} skipped (Profile Name + Code already exist)` : '')
                + (badBrand ? `, ${badBrand} skipped (brand not in the Brand list)` : '');
            showToast(msg, added.length ? 'success' : 'warning');
        },
        error: err => {
            showToast('Failed to read CSV: ' + err.message, 'error');
            showLoading(false);
        }
    });
}

// ============================================================
// DAMAGE LOG (KERUSAKAN)
// ============================================================

function generateDamageId() {
    return 'dmg_' + Date.now() + '_' + Math.random().toString(36).substr(2, 5);
}

// ---- Photo: compress/resize an image File to a JPEG data URL ----
// Resizes to DAMAGE_PHOTO_MAX_DIM on the longest side, then lowers quality
// until the data URL fits under DAMAGE_PHOTO_MAX_BYTES (Firestore 1MB doc cap).
// opts lets a caller ask for a tighter budget than the damage-photo defaults —
// a work log holds several photos in one document, so each gets less room.
function compressImageToDataURL(file, opts = {}) {
    const maxDim = opts.maxDim || DAMAGE_PHOTO_MAX_DIM;
    const maxBytes = opts.maxBytes || DAMAGE_PHOTO_MAX_BYTES;
    const startQuality = opts.quality || DAMAGE_PHOTO_QUALITY;
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onerror = () => reject(new Error('Failed to read the file'));
        reader.onload = () => {
            const img = new Image();
            img.onerror = () => reject(new Error('The file is not a valid image'));
            img.onload = () => {
                let { width, height } = img;
                const max = maxDim;
                if (width > height && width > max) { height = Math.round(height * max / width); width = max; }
                else if (height > max) { width = Math.round(width * max / height); height = max; }
                const canvas = document.createElement('canvas');
                canvas.width = width; canvas.height = height;
                canvas.getContext('2d').drawImage(img, 0, 0, width, height);
                let q = startQuality;
                let out = canvas.toDataURL('image/jpeg', q);
                while (out.length > maxBytes && q > 0.3) {
                    q -= 0.1;
                    out = canvas.toDataURL('image/jpeg', q);
                }
                resolve(out);
            };
            img.src = reader.result;
        };
        reader.readAsDataURL(file);
    });
}

// The damage form has two photo slots: 'before' — the photo of the damage,
// the one every record has always had — and 'after', taken once it is
// repaired. Each has its own input, preview and loading line.
const DMG_PHOTO_SLOTS = {
    before: { input: 'dmgPhotoInput', wrap: 'dmgPhotoPreviewWrap', img: 'dmgPhotoPreview', loading: 'dmgPhotoLoading' },
    after:  { input: 'dmgAfterInput', wrap: 'dmgAfterPreviewWrap', img: 'dmgAfterPreview', loading: 'dmgAfterLoading' }
};

async function handleDamagePhotoChange(event, side) {
    const file = event.target.files && event.target.files[0];
    event.target.value = '';
    if (!file) return;
    if (!file.type.startsWith('image/')) {
        showToast('The file must be an image (photo)', 'warning');
        return;
    }
    const gen = _dmgFormGen;
    _dmgPhotoBusy++;
    try {
        const data = await compressImageToDataURL(file);
        // The form was closed, or opened for another record, meanwhile.
        if (gen !== _dmgFormGen || !document.getElementById('damageModal').classList.contains('open')) return;
        if (side === 'after') { _dmgAfterData = data; _dmgAfterDirty = true; _dmgAfterLoading = false; }
        else { _dmgPhotoData = data; _dmgPhotoDirty = true; _dmgPhotoLoading = false; }
        setDamagePhotoPreview(side === 'after' ? 'after' : 'before');
    } catch (err) {
        showToast(err.message || 'Failed to process the photo', 'error');
    } finally {
        if (gen === _dmgFormGen) _dmgPhotoBusy = Math.max(0, _dmgPhotoBusy - 1);
    }
}

// No side = both slots.
function setDamagePhotoPreview(side) {
    if (!side) { setDamagePhotoPreview('before'); setDamagePhotoPreview('after'); return; }
    const ids = DMG_PHOTO_SLOTS[side];
    const data = side === 'after' ? _dmgAfterData : _dmgPhotoData;
    const busy = side === 'after' ? _dmgAfterLoading : _dmgPhotoLoading;
    const wrap = document.getElementById(ids.wrap);
    const img = document.getElementById(ids.img);
    if (!wrap || !img) return;
    const loading = document.getElementById(ids.loading);
    if (loading) loading.style.display = (busy && !data) ? '' : 'none';
    if (data) {
        img.src = data;
        wrap.style.display = '';
    } else {
        img.removeAttribute('src');
        wrap.style.display = 'none';
    }
}

function removeDamagePhoto(side) {
    side = side === 'after' ? 'after' : 'before';
    // Removing also ends any wait for the old one: its load is ignored now.
    if (side === 'after') { _dmgAfterData = ''; _dmgAfterDirty = true; _dmgAfterLoading = false; }
    else { _dmgPhotoData = ''; _dmgPhotoDirty = true; _dmgPhotoLoading = false; }
    const input = document.getElementById(DMG_PHOTO_SLOTS[side].input);
    if (input) input.value = '';
    setDamagePhotoPreview(side);
}

// ============================================================
// DAMAGE PHOTOS — stored apart from the record, fetched on demand
// ------------------------------------------------------------
// Same arrangement as work-log photos, for the same reason and with the same
// three rules. damageRecords is subscribed whole with no limit(), so an inline
// data URL was pulled down by every device on every app open — roughly 150 KB
// per photo, never expiring. It also rode along into localStorage through
// saveDamages(), where a few dozen photos exhausted the ~5 MB origin quota and
// took unit saves and the automatic backup ring down with it.
//
// The record keeps only hasPhoto. The image lives in damagePhotos/{recordId}
// and is read one document at a time, when somebody opens it. This collection
// must never be subscribed.
// ============================================================

const _dmgPhotoCache = new Map();   // damage record id -> data URL
// The photo after the repair: damagePhotos/{recordId}__after, flagged on the
// record by hasAfterPhoto. Same rules, same fetch-on-open.
const _dmgAfterCache = new Map();   // damage record id -> data URL

function damageHasPhoto(rec) {
    if (!rec) return false;
    // Records written before the split still carry the image inline. An empty
    // string means the inline copy was cleared on migration, so fall through to
    // hasPhoto rather than reporting none.
    if (rec.photo) return true;
    return !!rec.hasPhoto;
}

function damageHasAfterPhoto(rec) {
    return !!(rec && rec.hasAfterPhoto);
}

// A miss is not remembered: a photo sent from another phone that has not
// reached the server yet would otherwise read "not found" until a reload.
async function loadDamagePhoto(id) {
    const rec = globalDamages.find(d => d.id === id);
    if (rec && rec.photo) return rec.photo;
    if (_dmgPhotoCache.get(id)) return _dmgPhotoCache.get(id);
    if (!window.cloud || !window.cloud.getDamagePhoto) return '';
    const photo = await window.cloud.getDamagePhoto(id);
    if (photo) _dmgPhotoCache.set(id, photo);
    return photo;
}

async function loadDamageAfterPhoto(id) {
    if (_dmgAfterCache.get(id)) return _dmgAfterCache.get(id);
    if (!window.cloud || !window.cloud.getDamageAfterPhoto) return '';
    const photo = await window.cloud.getDamageAfterPhoto(id);
    if (photo) _dmgAfterCache.set(id, photo);
    return photo;
}

function damagePhotoCaption(rec, side) {
    if (side === 'after') return rec && rec.resolvedAt ? `After · repaired ${rec.resolvedAt}` : 'After repair';
    return rec && rec.date ? `Before · ${rec.date}` : 'Before';
}

// Opens a damage record's photos at the side that was tapped. That side shows
// as soon as it is here — on a weak signal it used to wait for the other
// side's download too. The other side (each lives in its own document) is
// fetched after and joins the open viewer, so the two can be flipped or put
// side by side. The tapped side failing is said, and nothing opens; the other
// side failing only leaves it out.
async function openDamagePhotos(id, side, btn) {
    const want = side === 'after' ? 'after' : 'before';
    const other = want === 'after' ? 'before' : 'after';
    const rec = globalDamages.find(d => d.id === id) || null;
    const load = s => (s === 'after' ? loadDamageAfterPhoto : loadDamagePhoto)(id);
    const original = btn ? btn.innerHTML : '';
    if (btn) { btn.disabled = true; btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i>'; }
    let first = '';
    try {
        first = await load(want);
    } catch (err) {
        console.error('[damage] photo load failed:', err);
        showToast(navigator.onLine
            ? 'Failed to load the damage photo'
            : 'The photo needs a signal to load', 'error');
        return;
    } finally {
        if (btn) { btn.disabled = false; btn.innerHTML = original; }
    }
    if (!first) { showToast('Photo not found', 'warning'); return; }
    openPhotoLightbox(first, 0, { captions: [damagePhotoCaption(rec, want)] });

    if (!(other === 'after' ? damageHasAfterPhoto(rec) : damageHasPhoto(rec))) return;
    let second = '';
    try { second = await load(other); } catch (err) { console.warn('[damage] other photo load failed:', err); }
    // Only while the viewer still shows just the tapped photo.
    if (!second || _lightboxPhotos.length !== 1 || _lightboxPhotos[0] !== first) return;
    openPhotoLightbox(want === 'after' ? [second, first] : [first, second], want === 'after' ? 1 : 0,
        { captions: [damagePhotoCaption(rec, 'before'), damagePhotoCaption(rec, 'after')], compare: true });
}

// One-shot move of inline photos into damagePhotos, mirroring the work-log
// migration that has already run in production.
//
// Order matters and is deliberate: the photo document is written FIRST and the
// inline copy cleared only after that write is confirmed. Interrupted halfway,
// the photo exists in two places — never in none. The flag is only set once the
// whole pass succeeds, so a failure simply retries on the next snapshot instead
// of leaving records stranded.
let _dmgPhotoMigrationRunning = false;
function migrateDamagePhotosIfNeeded() {
    if (_dmgPhotoMigrationRunning) return;
    if (!isOwner || !isOwner()) return;
    if (localStorage.getItem(DAMAGE_PHOTOS_SPLIT_KEY) === '1') return;
    if (!window.cloud || !window.cloud.saveDamagePhoto) return;
    if (!Array.isArray(globalDamages) || globalDamages.length === 0) return;

    const pending = globalDamages.filter(d => d.photo);
    if (pending.length === 0) {
        localStorage.setItem(DAMAGE_PHOTOS_SPLIT_KEY, '1');
        return;
    }
    if (!navigator.onLine) return;   // retried on the next snapshot

    _dmgPhotoMigrationRunning = true;
    console.log(`[dmg-photos] moving photos out of ${pending.length} damage records...`);
    (async () => {
        let moved = 0;
        for (const d of pending) {
            const photo = d.photo;
            await window.cloud.saveDamagePhoto(d.id, photo);
            _dmgPhotoCache.set(d.id, photo);
            await window.cloud.saveDamage({ ...d, photo: '', hasPhoto: true });
            moved++;
        }
        return moved;
    })().then(moved => {
        localStorage.setItem(DAMAGE_PHOTOS_SPLIT_KEY, '1');
        try {
            logEvent({
                action: 'migrate',
                unitName: '-',
                field: 'damage photo',
                after: `${moved} record(s) moved to the damagePhotos collection`
            });
        } catch (e) {}
        console.log(`[dmg-photos] done — ${moved} damage records migrated`);
    }).catch(err => {
        console.error('[dmg-photos] migration failed:', err);
        if (err && err.code === 'permission-denied') showDamageRulesBanner();
    }).finally(() => {
        _dmgPhotoMigrationRunning = false;
    });
}

// Renders a damage record's photos: Before (the damage) and After (the
// repair), each a button carrying the fetch — never an <img> holding the image
// itself. opts.addAfter adds a "+ After" button on a repaired record that has
// no After photo yet, for whoever may edit damage records.
function damagePhotoButtons(rec, opts) {
    const dash = '<span style="color:var(--text-light);font-size:11px">—</span>';
    if (!rec) return dash;
    // Carries a word, not just the icon: a one-glyph button is a poor tap
    // target on a phone, and it disappears entirely if the icon font does not
    // load — which is exactly when a field device is on a bad connection.
    const btns = [];
    if (damageHasPhoto(rec)) {
        btns.push(`<button type="button" class="wl-photo-btn dmg-ph dmg-ph--before" title="Photo of the damage (before repair)"
            aria-label="View the photo before repair"
            onclick="event.stopPropagation();openDamagePhotos(${jsArg(rec.id)}, 'before', this)"><i class="fas fa-image"></i> Before</button>`);
    }
    if (damageHasAfterPhoto(rec)) {
        btns.push(`<button type="button" class="wl-photo-btn dmg-ph dmg-ph--after" title="Photo after repair"
            aria-label="View the photo after repair"
            onclick="event.stopPropagation();openDamagePhotos(${jsArg(rec.id)}, 'after', this)"><i class="fas fa-image"></i> After</button>`);
    } else if (opts && opts.addAfter && rec.resolved && hasAccess('damage', 'edit')) {
        btns.push(`<button type="button" class="wl-photo-btn dmg-ph dmg-ph--add" title="Add a photo of the repaired unit"
            aria-label="Add the photo after repair"
            onclick="event.stopPropagation();openDamageRepair(${jsArg(rec.id)})">+ After</button>`);
    }
    return btns.length ? `<span class="dmg-ph-group">${btns.join('')}</span>` : dash;
}

// ---- Lightbox (view full-size photo) ----
// Takes one photo or a whole set. A work log can hold four, and they are now
// fetched together, so paging through them beats opening each separately.
// opts.captions labels each photo (Before / After); opts.compare offers a
// side-by-side view of the set.
let _lightboxPhotos = [];
let _lightboxIndex = 0;
let _lightboxCaptions = [];
let _lightboxCanCompare = false;
let _lightboxCompare = false;

function openPhotoLightbox(src, index, opts) {
    const raw = Array.isArray(src) ? src : [src];
    const caps = (opts && Array.isArray(opts.captions)) ? opts.captions : [];
    // Captions stay paired with their photo when an empty one is dropped.
    const pairs = raw.map((s, i) => [s, caps[i] || '']).filter(p => p[0]);
    if (!pairs.length) return;
    const box = document.getElementById('photoLightbox');
    if (!box) return;
    _lightboxPhotos = pairs.map(p => p[0]);
    _lightboxCaptions = pairs.map(p => p[1]);
    _lightboxIndex = Math.min(Math.max(Number(index) || 0, 0), pairs.length - 1);
    _lightboxCanCompare = !!(opts && opts.compare) && pairs.length > 1;
    _lightboxCompare = false;
    renderPhotoLightbox();
    box.classList.add('open');
}

function renderPhotoLightbox() {
    const compare = _lightboxCompare && _lightboxCanCompare;
    const box = document.getElementById('photoLightbox');
    if (box) box.classList.toggle('photo-lightbox--compare', compare);
    const img = document.getElementById('photoLightboxImg');
    if (img) {
        img.src = _lightboxPhotos[_lightboxIndex] || '';
        img.alt = _lightboxCaptions[_lightboxIndex] || 'Photo';
        img.style.display = compare ? 'none' : '';
    }
    // Built as nodes, not markup: a caption carries a date typed by a person.
    const cmp = document.getElementById('photoLightboxCompare');
    if (cmp) {
        cmp.textContent = '';
        cmp.style.display = compare ? '' : 'none';
        if (compare) _lightboxPhotos.forEach((src, i) => {
            const fig = document.createElement('figure');
            fig.className = 'photo-lightbox__fig';
            fig.title = 'Show this photo on its own';
            fig.onclick = e => { e.stopPropagation(); _lightboxCompare = false; _lightboxIndex = i; renderPhotoLightbox(); };
            const im = document.createElement('img');
            im.src = src;
            im.alt = _lightboxCaptions[i] || 'Photo';
            fig.appendChild(im);
            if (_lightboxCaptions[i]) {
                const cap = document.createElement('figcaption');
                cap.textContent = _lightboxCaptions[i];
                fig.appendChild(cap);
            }
            cmp.appendChild(fig);
        });
    }
    const caption = document.getElementById('photoLightboxCaption');
    if (caption) {
        const text = compare ? '' : (_lightboxCaptions[_lightboxIndex] || '');
        caption.textContent = text;
        caption.style.display = text ? '' : 'none';
    }
    const many = _lightboxPhotos.length > 1 && !compare;
    ['photoLightboxPrev', 'photoLightboxNext'].forEach(id => {
        const el = document.getElementById(id);
        if (el) el.style.display = many ? '' : 'none';
    });
    const count = document.getElementById('photoLightboxCount');
    if (count) {
        count.style.display = many ? '' : 'none';
        count.textContent = `${_lightboxIndex + 1} / ${_lightboxPhotos.length}`;
    }
    const mode = document.getElementById('photoLightboxMode');
    if (mode) {
        mode.style.display = _lightboxCanCompare ? '' : 'none';
        mode.innerHTML = compare ? '<i class="fas fa-square"></i> One at a time'
                                 : '<i class="fas fa-table-columns"></i> Side by side';
    }
}

function togglePhotoLightboxCompare() {
    if (!_lightboxCanCompare) return;
    _lightboxCompare = !_lightboxCompare;
    renderPhotoLightbox();
}

// Wraps around, so holding one arrow never dead-ends.
function stepPhotoLightbox(delta) {
    if (_lightboxPhotos.length < 2 || _lightboxCompare) return;
    const n = _lightboxPhotos.length;
    _lightboxIndex = (_lightboxIndex + delta + n) % n;
    renderPhotoLightbox();
}

function closePhotoLightbox() {
    const box = document.getElementById('photoLightbox');
    if (box) box.classList.remove('open', 'photo-lightbox--compare');
    const cmp = document.getElementById('photoLightboxCompare');
    if (cmp) cmp.textContent = '';
    _lightboxPhotos = [];
    _lightboxCaptions = [];
    _lightboxCanCompare = false;
    _lightboxCompare = false;
}

document.addEventListener('keydown', e => {
    const box = document.getElementById('photoLightbox');
    if (!box || !box.classList.contains('open')) return;
    // Stopped here: the global Escape handler runs next and would close the
    // dialog underneath too — with an unsaved photo in it.
    if (e.key === 'Escape')     { closePhotoLightbox(); e.stopImmediatePropagation(); return; }
    if (e.key === 'ArrowLeft')  { stepPhotoLightbox(-1); }
    if (e.key === 'ArrowRight') { stepPhotoLightbox(1); }
});

// ============================================================
// UNIT PROFILE (Profil Unit) — one panel with everything about a unit
// ============================================================

function closeUnitProfile() {
    document.getElementById('unitProfileModal').classList.remove('open');
}

// ---- Global unit search (topbar) — jumps straight to a unit's profile ----
function closeGlobalSearch() {
    const box = document.getElementById('globalSearchResults');
    if (box) { box.innerHTML = ''; box.style.display = 'none'; }
    document.body.classList.remove('gsearch-open');
}

function renderGlobalSearchResults() {
    const input = document.getElementById('globalSearch');
    const box = document.getElementById('globalSearchResults');
    if (!input || !box) return;
    const q = input.value.toLowerCase().trim();
    if (!q) { closeGlobalSearch(); return; }
    const hits = globalData.filter(u => (isHeavy(u)
        ? `${u.name} ${u.sn} ${u.brand || ''} ${u.model} ${u.site} ${u.machineType || ''} ${u.assetCode || ''}`
        : `${u.name} ${u.sn} ${u.model} ${u.site}`).toLowerCase().includes(q)).slice(0, 8);
    if (!hits.length) {
        box.innerHTML = '<div class="global-search__empty">No matching units</div>';
        // 'block', not '': the stylesheet hides the box by default, so
        // clearing the inline style kept every result invisible.
        box.style.display = 'block';
        document.body.classList.add('gsearch-open');
        return;
    }
    // Buttons, so Tab and the arrow keys reach every result, not only the first.
    box.innerHTML = hits.map(u => `
        <button type="button" class="global-search__item" onclick="openUnitFromSearch(${jsArg(u.id)})">
            <span class="global-search__name">${escapeHtml(u.name || '(unnamed)')}</span>
            <span class="global-search__meta"><span class="mono">${escapeHtml(u.sn || '')}</span>${u.site ? ' · ' + escapeHtml(u.site) : ''}${isHeavy(u) ? ' · ' + escapeHtml(UNIT_GROUPS.heavy.shortLabel) : ''}</span>
        </button>`).join('');
    box.style.display = 'block';
    document.body.classList.add('gsearch-open');
}

function openUnitFromSearch(id) {
    closeGlobalSearch();
    const input = document.getElementById('globalSearch');
    if (input) input.value = '';
    showUnitProfile(id);
}

function showUnitProfile(id) {
    const u = globalData.find(d => d.id === id);
    if (!u) { showToast(unitOutsideScope(id) ? 'This unit is outside your access (or no longer exists)' : 'Unit not found', 'warning'); return; }
    document.getElementById('unitProfileModal').dataset.unitId = id;

    document.getElementById('unitProfileTitle').textContent = u.name || u.sn || 'Unit Profile';
    const profSub = document.getElementById('unitProfileSub');
    if (profSub) profSub.textContent = [isHeavy(u) ? [u.brand, u.model].filter(Boolean).join(' ') : u.model, u.site].filter(Boolean).join(' · ');
    document.getElementById('unitProfileEditBtn').onclick = () => { closeUnitProfile(); editUnit(id); };
    document.getElementById('unitProfileHistoryBtn').onclick = () => showHistory(id);

    const snLc = (u.sn || '').toLowerCase();
    const dash = '<span style="color:var(--text-light)">—</span>';
    const val = v => v ? escapeHtml(v) : dash;

    // When the unit's implement text matches a record in the Implements
    // database, show its key specs under the value.
    const impMatch = matchImplementForUnit(u.implement);
    const impDetail = impMatch
        ? [impMatch.brand, impMatch.code, impMatch.workingWidth ? `WW ${impMatch.workingWidth}` : '']
            .filter(Boolean).map(escapeHtml).join(' · ')
        : '';
    const impVal = u.implement
        ? `<span style="text-align:right">${escapeHtml(u.implement)}${impDetail ? `<div style="font-size:11px;color:var(--text-light);margin-top:2px">${impDetail}</div>` : ''}</span>`
        : dash;

    const heavyUnit = isHeavy(u);
    const snCell = u.sn ? `<span style="font-family:var(--font-mono);font-size:12px">${escapeHtml(u.sn)}</span>` : dash;
    const catCell = u.userCategory ? `<span class="badge badge-cat" style="font-size:10px">${escapeHtml(u.userCategory)}</span>` : dash;
    const identity = (heavyUnit ? [
        ['Group', `<span class="badge badge-cat" style="font-size:10px">${escapeHtml(UNIT_GROUPS.heavy.label)}</span>`],
        ['Brand', val(u.brand)],
        ['Model', val(u.model)],
        ['Serial Number', snCell],
        ['Machine Type', val(u.machineType)],
        ['Asset No.', val(u.assetCode)],
        ['Work Tool', val(u.workTool)],
        ['Site', val(u.site)],
        ['Year Received', val(u.yearReceived)],
        ['User Category', catCell]
    ] : [
        ['Model', val(u.model)],
        ['Serial Number', u.sn ? `<span style="font-family:var(--font-mono);font-size:12px">${escapeHtml(u.sn)}</span>` : dash],
        ['Implement', impVal],
        ['Site', val(u.site)],
        ['Year Received', val(u.yearReceived)],
        ['User Category', u.userCategory ? `<span class="badge badge-cat" style="font-size:10px">${escapeHtml(u.userCategory)}</span>` : dash]
    ]).map(([l, v]) => `<div class="profile-row"><dt class="profile-row__label">${l}</dt><dd>${v}</dd></div>`).join('');

    const statusBadge = isGood(u.status)
        ? '<span class="badge badge-good"><i class="fas fa-check"></i> Good</span>'
        : `<span class="badge badge-breakdown"><i class="fas fa-xmark"></i> ${escapeHtml(u.status || 'Breakdown')}</span>`;
    // The unit's own group's components: an excavator used to show four red
    // John Deere chips it never had.
    const compRow = groupDef(unitGroupOf(u)).components.map(c => {
        const label = c.label;
        const good = isGood(u[c.key]);
        const state = good ? 'Good' : (clean(u[c.key]) ? escapeHtml(clean(u[c.key])) : 'Not set');
        return `<div class="profile-comp ${good ? 'ok' : 'bad'}"><i class="fas fa-${good ? 'circle-check' : 'circle-xmark'}" aria-hidden="true"></i> ${label}<span class="profile-comp__state">${state}</span></div>`;
    }).join('');
    const dmg = globalDamages
        .filter(r => r.unitId === id || (snLc && (r.sn || '').toLowerCase() === snLc))
        .sort((a, b) => (b.date || '').localeCompare(a.date || ''));
    // A unit in breakdown leads with why, for how long, and a way to its open
    // damage records (design F callout).
    const downFor = !isGood(u.status) && u.breakdownStartedAt ? `Down ${formatDuration(Date.now() - u.breakdownStartedAt)}` : '';
    const openDmg = dmg.filter(r => !r.resolved).length;
    const dmgLink = openDmg && hasAccess('damage', 'view')
        ? `<button type="button" class="profile-note__link" onclick="closeUnitProfile(); goDecision(${jsArg(`damage:${unitGroupOf(u)}:unit:${id}`)})">${
            openDmg === 1 ? 'Open damage record' : `Open ${openDmg} damage records`}</button>` : '';
    const bdReason = !isGood(u.status)
        ? `<div class="profile-note profile-note--bad"><i class="fas fa-triangle-exclamation" aria-hidden="true"></i>
            <div><strong>${escapeHtml(u.status || 'Breakdown')}${u.breakdownReason ? ' — ' + escapeHtml(u.breakdownReason) : ''}</strong>${downFor ? `<span class="profile-note__sub">${downFor}</span>` : ''}${dmgLink}</div></div>` : '';
    const stray = strayGroupFields(u);
    const strayNote = stray.length
        ? `<div class="profile-note"><i class="fas fa-triangle-exclamation"></i> This unit carries ${stray.length} field(s) belonging to another group — see Decision Inbox → Data Check.</div>` : '';

    const licenses = ['gps', 'display'].map(kind => {
        const label = kind === 'gps' ? 'GPS License' : 'Display License';
        const end = getLicenseEndDate(u, kind);
        return `<div class="profile-row profile-row--lic"><span class="profile-row__label">${label}</span>
            <span style="display:flex;gap:8px;align-items:center;flex-wrap:wrap;justify-content:flex-end">${licenseTypeBadge(u, kind)} ${licenseBadgeFor(u, kind)}${end ? ` <span style="font-size:11.5px;color:var(--text-secondary)">exp ${escapeHtml(end)}</span>` : ''}</span></div>`;
    }).join('');

    const dmgHtml = dmg.length ? dmg.map(r => `
        <div class="profile-item">
            <span class="profile-item__date">${escapeHtml(r.date || '')}</span>
            <span class="badge badge-breakdown" style="font-size:10px">${escapeHtml(damageTypeLabel(r.damageType))}</span>
            ${r.component ? `<span class="badge badge-cat" style="font-size:10px">${escapeHtml(r.component)}</span>` : ''}
            <span class="profile-item__text" title="${escapeHtml(r.description || '')}">${escapeHtml((r.description || '').slice(0, 60))}</span>
            ${damageHasPhoto(r) || damageHasAfterPhoto(r) ? damagePhotoButtons(r) : ''}
        </div>`).join('')
        : '<div class="profile-empty">No damage records yet.</div>';

    const dist = globalLicenseStock
        .filter(r => r.txnType === 'OUT' && (r.unitId === id || (snLc && (r.sn || '').toLowerCase() === snLc)))
        .sort((a, b) => (b.date || '').localeCompare(a.date || ''));
    const distHtml = dist.length ? dist.map(r => `
        <div class="profile-item">
            <span class="profile-item__date">${escapeHtml(r.date || '')}</span>
            <span class="badge badge-good" style="font-size:10px">${escapeHtml(r.licenseType || '')}</span>
            <span style="font-size:12px">× ${Number(r.qty) || 0}</span>
            ${r.note ? `<span class="profile-item__text" title="${escapeHtml(r.note)}">${escapeHtml(r.note.slice(0, 40))}</span>` : ''}
        </div>`).join('')
        : '<div class="profile-empty">No license distributions yet.</div>';

    const hist = u.downtimeHistory || [];
    const downParts = hist.slice(-5).reverse().map(iv =>
        `<div class="profile-item"><span class="profile-item__date">${new Date(iv.start).toLocaleDateString()}</span><span style="font-size:12px">${formatDuration(iv.durationMs)}</span></div>`);
    if (u.breakdownStartedAt) {
        downParts.unshift(`<div class="profile-item"><span class="badge badge-breakdown" style="font-size:10px">In breakdown</span><span style="font-size:12px">${formatDuration(Date.now() - u.breakdownStartedAt)}</span></div>`);
    }
    const downHtml = downParts.length ? downParts.join('') : '<div class="profile-empty">No downtime history.</div>';

    // Who has worked on this machine — newest first, capped like the other lists.
    const work = workLogsForUnit(u.id, u.sn);
    const workHtml = work.length ? work.slice(0, 8).map(w => `
        <div class="profile-item">
            <span class="profile-item__date">${escapeHtml(w.date || '')}</span>
            <span style="font-size:12px"><strong>${escapeHtml(memberNameOf(w))}</strong></span>
            <span style="font-size:12px;color:var(--text-light)">${escapeHtml(formatMinutes(workLogMinutes(w)))}</span>
            ${w.task ? `<span class="profile-item__text" title="${escapeHtml(w.task)}">${escapeHtml(w.task.slice(0, 40))}</span>` : ''}
        </div>`).join('')
        : '<div class="profile-empty">No work reports for this unit yet.</div>';

    // Devices from the warehouse currently fitted to this machine.
    const fitted = devicesForUnit(u.id);
    const fittedHtml = fitted.length ? fitted.map(d => `
        <div class="profile-item">
            <span class="badge badge-cat" style="font-size:10px">${escapeHtml(d.type || 'Device')}</span>
            <span style="font-family:monospace;font-size:12px">${escapeHtml(d.sn || '')}</span>
            ${d.note ? `<span class="profile-item__text" title="${escapeHtml(d.note)}">${escapeHtml(d.note.slice(0, 30))}</span>` : ''}
        </div>`).join('')
        : '<div class="profile-empty">No warehouse devices registered to this unit.</div>';

    // Design F: status and parts first (with the breakdown callout), then
    // licences, then the identity as a two-column list; the record lists
    // follow as cards.
    document.getElementById('unitProfileBody').innerHTML = `
        <div class="profile-grid">
            <div class="profile-section profile-section--status">
                <div class="profile-section__title">Status</div>
                ${bdReason || `<div class="profile-status">${statusBadge}</div>`}
                <div class="profile-section__title profile-section__title--sub">${heavyUnit ? 'Components' : 'Parts'}</div>
                <div class="profile-comps">${compRow}</div>
                ${strayNote}
                ${heavyUnit ? '' : `<div class="profile-section__title profile-section__title--sub">Licenses</div>
                ${licenses}`}
            </div>
            <div class="profile-section profile-section--identity">
                <div class="profile-section__title">Identity</div>
                <dl class="profile-dl">${identity}</dl>
                ${u.remarks ? `<div class="profile-note">${escapeHtml(u.remarks)}</div>` : ''}
            </div>
            <div class="profile-section">
                <div class="profile-section__title">Damage History (${dmg.length})</div>
                <div class="profile-list">${dmgHtml}</div>
            </div>
            ${heavyUnit ? '' : `<div class="profile-section">
                <div class="profile-section__title">License Distribution (${dist.length})</div>
                <div class="profile-list">${distHtml}</div>
            </div>`}
            <div class="profile-section">
                <div class="profile-section__title">Attachments</div>
                <div class="profile-attach">${renderAttachCell(u)}</div>
            </div>
            <div class="profile-section">
                <div class="profile-section__title">Downtime</div>
                <div class="profile-list">${downHtml}</div>
            </div>
            <div class="profile-section">
                <div class="profile-section__title">Team Work (${work.length})</div>
                <div class="profile-list">${workHtml}</div>
            </div>
            <div class="profile-section">
                <div class="profile-section__title">Installed Devices (${fitted.length})</div>
                <div class="profile-list">${fittedHtml}</div>
            </div>
        </div>`;

    document.getElementById('unitProfileModal').classList.add('open');
}

// ---- Storage ----
function loadDamages() {
    try {
        const raw = localStorage.getItem(DAMAGE_STORAGE_KEY);
        applyUnitScopeToData({ damages: raw ? JSON.parse(raw) : [] });
    } catch (e) {
        applyUnitScopeToData({ damages: [] });
    }
    updateDamageCount();
    return globalDamages.length > 0;
}

function saveDamages() {
    if (isUnitScoped()) return;
    try {
        localStorage.setItem(DAMAGE_STORAGE_KEY, JSON.stringify(globalDamages));
        checkStorageUsage(); // photos are the main storage driver
    } catch (e) {
        showToast('Storage is full. Damage record not saved.', 'error');
    }
}

function updateDamageCount() {
    const el = document.getElementById('damageCount');
    if (el) el.textContent = `${globalDamages.length} damage records`;
}

// Apply the current search + type filter and sort newest-first. Shared by the
// table renderer and the CSV export so both stay in sync.
// Kerusakan opens per equipment group from the sidebar. '' = both.
let damageGroup = '';

// A record follows its live unit; one whose unit is gone keeps the group it
// was stamped with (heavy records carry unitGroup:'heavy', tractor ones none).
function damageGroupOfRecord(d) {
    const u = liveUnitFor(d);
    if (u) return unitGroupOf(u);
    return d && d.unitGroup === 'heavy' ? 'heavy' : 'tractor';
}

function setDamageGroup(g) {
    const sc = effectiveUnitScope();
    if (sc === 'tractor' || sc === 'heavy') g = sc;
    damageGroup = (g === 'tractor' || g === 'heavy') ? g : '';
    const sel = document.getElementById('damageGroupFilter');
    if (sel && sel.value !== damageGroup) sel.value = damageGroup;
    if (currentView === 'damage') { populateDamageUnitSelect(); renderDamageTable(); }
    markActiveNav();
}

// One unit's records, opened from its "N open damage" chip or Data Check —
// matched by the live unit, as the chip counts them, not by search text (a
// corrected SN, or SN1 also matching SN10). Typing a search drops it.
let damageUnitFilter = '';
function clearDamageUnitFilter() {
    damageUnitFilter = '';
    renderDamageTable();
}

// The Repair filter: '' any, 'open', 'repaired'.
function damageRepairMatch(d, val) {
    if (val === 'open') return !d.resolved;
    if (val === 'repaired') return !!d.resolved;
    return true;
}

// opts.anyRepair leaves the Repair filter out — the summary tiles count both
// sides of it.
function getFilteredDamages(opts) {
    const query = (document.getElementById('damageSearch')?.value || '').toLowerCase().trim();
    const typeVal = (document.getElementById('damageTypeFilter')?.value || '');
    const repairVal = opts && opts.anyRepair ? '' : (document.getElementById('damageRepairFilter')?.value || '');

    let rows = [...globalDamages];
    if (damageUnitFilter) rows = rows.filter(d => (liveUnitFor(d) || {}).id === damageUnitFilter);
    if (damageGroup) rows = rows.filter(d => damageGroupOfRecord(d) === damageGroup);
    if (typeVal) rows = rows.filter(d => d.damageType === typeVal);
    if (repairVal) rows = rows.filter(d => damageRepairMatch(d, repairVal));
    if (query) rows = rows.filter(d => {
        const lu = liveUnitFor(d);
        return `${lu ? (lu.name || '') + ' ' + (lu.sn || '') : ''} ${d.unitName} ${d.sn} ${d.site} ${d.damageType} ${d.component} ${d.description}`
            .toLowerCase().includes(query);
    });

    rows.sort((a, b) => {
        const da = a.date || '', db = b.date || '';
        if (da !== db) return da < db ? 1 : -1;          // date desc
        return (b.createdAt || 0) - (a.createdAt || 0);   // tie-break newest-first
    });
    return rows;
}

// ---- Unit picker ----
// Single source of truth for how a unit is shown/typed in the damage picker.
function damageUnitLabel(u) {
    return `${u.name || '(no name)'}${u.sn ? ' — ' + u.sn : ''}`;
}

// Fill the searchable datalist behind the #dmgUnit input. With selectedId, also
// pre-fill the input with that unit's label (used when editing).
function populateDamageUnitSelect(selectedId) {
    const input = document.getElementById('dmgUnit');
    const list = document.getElementById('dmgUnitList');
    if (!input || !list) return;
    // Opened from one group's menu, the suggestions are that group's units.
    // Typing any other unit still works — this narrows the list, not the form.
    const units = [...globalData]
        .filter(u => !damageGroup || unitGroupOf(u) === damageGroup || u.id === selectedId)
        .sort((a, b) => (a.name || '').localeCompare(b.name || ''));
    list.innerHTML = units.map(u =>
        `<option value="${escapeHtml(damageUnitLabel(u))}"></option>`
    ).join('');
    if (selectedId) {
        const u = globalData.find(x => x.id === selectedId);
        input.value = u ? damageUnitLabel(u) : '';
    } else {
        input.value = '';
    }
}

// Resolve the free-typed picker text back to a unit: exact label match first,
// then fall back to matching the serial number after the "—" separator.
function resolveDamageUnit(val) {
    val = (val || '').trim();
    if (!val) return null;
    const lc = val.toLowerCase();

    // 1. Full "Nama — SN" label, as offered by the datalist.
    let u = globalData.find(x => damageUnitLabel(x).toLowerCase() === lc);
    // 2. Serial number after the "—" separator (partially typed label).
    if (!u && val.includes('—')) {
        const sn = val.split('—').pop().trim().toLowerCase();
        if (sn) u = globalData.find(x => (x.sn || '').toLowerCase() === sn);
    }
    // 3/4. Plain nickname or plain serial number — the field's own hint says
    // "ketik nama atau SN", so accept either on its own.
    if (!u) u = globalData.find(x => (x.name || '').toLowerCase() === lc);
    if (!u) u = globalData.find(x => (x.sn || '').toLowerCase() === lc);
    return u || null;
}

// Find the CURRENT unit for a saved record (damage / license distribution) so
// renames in the unit database reflect everywhere. Matches by unitId first,
// then by serial number; returns null if the unit no longer exists (caller
// falls back to the stored snapshot).
function liveUnitFor(rec) {
    if (!rec) return null;
    if (rec.unitId) {
        const u = globalData.find(x => x.id === rec.unitId);
        if (u) return u;
    }
    if (rec.sn) {
        const sn = (rec.sn || '').toLowerCase();
        const u = globalData.find(x => (x.sn || '').toLowerCase() === sn);
        if (u) return u;
    }
    return null;
}

// On a heavy unit: what this open record holds, and whether the unit agrees.
function damageUnitChip(d, unit) {
    if (d.resolved || !unit || !isHeavy(unit)) return '';
    const field = damageHeldField(d, unit);
    if (!field) return '';
    const what = field === 'status' ? 'Unit' : damageFieldLabel(field);
    return isBrokenValue(field === 'status' ? unit.status : unit[field])
        ? `<span class="dmg-unit-chip dmg-unit-chip--down" title="Held in Breakdown by this damage">${escapeHtml(what)}: Breakdown</span>`
        : `<span class="dmg-unit-chip dmg-unit-chip--off" title="The unit is Good while this damage is still open — see Data Check">${escapeHtml(what)} is Good</span>`;
}

// Open damage records per unit, counted once per render of a unit table
// (a per-row search over every record made a table of hundreds slow).
let _openDmgIdx = null;
function openDamageCountFor(unit) {
    if (!_openDmgIdx) {
        _openDmgIdx = new Map();
        (globalDamages || []).forEach(d => {
            if (d.resolved) return;
            const u = liveUnitFor(d);
            if (u) _openDmgIdx.set(u.id, (_openDmgIdx.get(u.id) || 0) + 1);
        });
    }
    return _openDmgIdx.get(unit.id) || 0;
}
// The Unit Database's "N open damage" chips, updated without rebuilding the
// table (a rebuild drops the ticked rows an open Bulk Edit works on).
function refreshOpenDamageChips() {
    _openDmgIdx = null;
    document.querySelectorAll('#editBody .inline-edit[data-field="name"][data-id]').forEach(el => {
        const unit = globalData.find(u => u.id === el.dataset.id);
        const td = el.closest('td');
        if (!unit || !td) return;
        td.querySelectorAll('.dmg-open-chip').forEach(c => c.remove());
        const html = openDamageChipFor(unit);
        if (html) td.insertAdjacentHTML('beforeend', html);
    });
}

function openDamageChipFor(unit) {
    if (!unit || !isHeavy(unit) || !hasAccess('damage', 'view')) return '';
    const n = openDamageCountFor(unit);
    if (!n) return '';
    return ` <button type="button" class="dmg-open-chip" title="Open damage records on this unit — open Damage"
        onclick="event.stopPropagation(); goDecision(${jsArg('damage:heavy:unit:' + unit.id)})"><i class="fas fa-screwdriver-wrench"></i> ${n} open damage</button>`;
}

// ---- Render ----
// "23 Oct" this year, "23 Oct 2025" before it. The ISO date stays in the
// cell's title, the CSV and the forms.
function damageDayLabel(iso) {
    const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(iso || '');
    if (!m) return iso || '';
    const label = `${+m[3]} ${MONTH_NAMES[+m[2] - 1]}`;
    return m[1] === toISODate().slice(0, 4) ? label : `${label} ${m[1]}`;
}

// Chip colour per stored damage type (the words come from damageTypeLabel).
const DAMAGE_TYPE_CHIP = { Mekanis: 'mech', Software: 'soft', 'Device Precision': 'device' };
// The row's "⋯" actions button, and the one whose menu is open now.
const DAMAGE_MORE_ICON = '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="5" cy="12" r="1"></circle><circle cx="12" cy="12" r="1"></circle><circle cx="19" cy="12" r="1"></circle></svg>';
let _dmgMenuBtn = null;

// The four tiles over the table, from the records in the current group,
// search, type and unit filter. Repair time counts whole days from the
// damage date to the repair date — both are calendar dates, no hours.
function renderDamageKpis(rows) {
    const set = (id, v) => { const el = document.getElementById(id); if (el) el.textContent = v; };
    const isDay = v => /^\d{4}-\d{2}-\d{2}$/.test(v || '');
    const month = toISODate().slice(0, 7);
    let open = 0, down = 0, doneMonth = 0, days = 0, timed = 0;
    rows.forEach(d => {
        if (!d.resolved) {
            open++;
            // Holding its unit (or one of its components) in Breakdown now.
            const u = liveUnitFor(d);
            const f = damageHeldField(d, u);
            if (f && isBrokenValue(f === 'status' ? u.status : u[f])) down++;
            return;
        }
        if (String(d.resolvedAt || '').slice(0, 7) === month) doneMonth++;
        if (isDay(d.date) && isDay(d.resolvedAt) && d.resolvedAt >= d.date) {
            days += (Date.parse(d.resolvedAt) - Date.parse(d.date)) / 86400000;
            timed++;
        }
    });
    set('dmgKpiOpen', open);
    set('dmgKpiDown', down);
    set('dmgKpiRepaired', doneMonth);
    set('dmgKpiRepairedLabel', `Repaired in ${new Date().toLocaleString('en-US', { month: 'long' })}`);
    let avg = '—';
    if (timed) {
        const v = days / timed;
        const r = v < 10 ? Math.round(v * 10) / 10 : Math.round(v);
        avg = r === 0 ? 'Same day' : `${r} ${r === 1 ? 'day' : 'days'}`;
    }
    set('dmgKpiAvg', avg);
    const tile = document.getElementById('dmgKpiAvgTile');
    if (tile) tile.title = timed
        ? `From the damage date to the repair date, over ${timed} repaired record${timed === 1 ? '' : 's'}`
        : 'No repaired record with both dates yet';
}

function renderDamageTable() {
    closeDamageMenu();
    updateDamageCount();
    // A re-render (search, filter, a cloud snapshot) draws fresh, unticked
    // rows — so the selection is dropped with them. Re-reading the OLD boxes
    // here kept "Delete selected" armed for rows no longer on screen.
    document.querySelectorAll('.damage-check').forEach(cb => { cb.checked = false; });
    selectedDamageIds.clear();
    updateSelectedDamageCount();

    const selectAllBox = document.getElementById('selectAllDamage');
    if (selectAllBox) selectAllBox.checked = false;

    // The tiles count both sides of the Repair filter; the table applies it.
    const base = getFilteredDamages({ anyRepair: true });
    renderDamageKpis(base);
    const repairVal = document.getElementById('damageRepairFilter')?.value || '';
    const rows = repairVal ? base.filter(d => damageRepairMatch(d, repairVal)) : base;
    const tbody = document.getElementById('damageBody');
    if (!tbody) return;
    const unitChip = document.getElementById('damageUnitFilterChip');
    if (unitChip) {
        const fu = damageUnitFilter ? globalData.find(u => u.id === damageUnitFilter) : null;
        unitChip.hidden = !damageUnitFilter;
        unitChip.innerHTML = damageUnitFilter
            ? `Unit: ${escapeHtml(fu ? fu.name || fu.sn || '' : '—')} <i class="fas fa-xmark" aria-hidden="true"></i>` : '';
    }

    const hasFilter = (document.getElementById('damageSearch')?.value || '') ||
                      (document.getElementById('damageTypeFilter')?.value || '') || repairVal || damageUnitFilter;

    // "14 damage records", or "Showing 3 of 14 records" of the group shown.
    const countEl = document.getElementById('damageCount');
    if (countEl && hasFilter) {
        const all = damageGroup ? globalDamages.filter(d => damageGroupOfRecord(d) === damageGroup).length : globalDamages.length;
        countEl.textContent = `Showing ${rows.length} of ${all} records`;
    } else if (countEl) {
        countEl.textContent = `${rows.length} damage record${rows.length === 1 ? '' : 's'}`;
    }

    if (rows.length === 0) {
        tbody.innerHTML = `<tr><td colspan="8" class="dmg-empty">${
            hasFilter ? 'No damage records match the filter'
                      : 'No damage records yet. Click <strong>Report damage</strong> to get started.'
        }</td></tr>`;
        return;
    }

    tbody.innerHTML = rows.map((d, i) => {
        const lu = liveUnitFor(d);
        const uName = lu ? (lu.name || '') : (d.unitName || '');
        const uSn   = lu ? (lu.sn || '')   : (d.sn || '');
        const uSite = lu ? (lu.site || '') : (d.site || '');
        const id = jsArg(d.id);
        const meta = [uSite, uSn].filter(Boolean).map(escapeHtml).join(' · ');
        // A unit still in the database opens its profile; a deleted one is
        // just its stored name.
        const unitName = lu
            ? `<button type="button" class="dmg-unit__name dmg-unit__link" title="View unit profile" onclick="showUnitProfile(${jsArg(lu.id)})">${escapeHtml(uName || uSn) || '—'}</button>`
            : `<span class="dmg-unit__name">${escapeHtml(uName || uSn) || '—'}</span>`;
        const desc = d.description || '';
        const what = (d.component ? `<span class="dmg-what__comp">${escapeHtml(d.component)}</span>` : '')
            + (desc ? `<span class="dmg-what__desc" title="${escapeHtml(desc)}">${escapeHtml(desc)}</span>` : '');
        const repair = d.resolved
            ? `<span class="dmg-state badge dmg-state--done"${d.resolvedAt ? ` title="Repaired ${escapeHtml(d.resolvedAt)}"` : ''}><span class="dmg-state__dot" aria-hidden="true"></span>Repaired${
                d.resolvedAt ? ` <span class="dmg-state__when">${escapeHtml(damageDayLabel(d.resolvedAt))}</span>` : ''}</span>`
            : `<span class="dmg-state badge dmg-state--open"><span class="dmg-state__dot" aria-hidden="true"></span>Open</span>${damageUnitChip(d, lu)}`;
        const who = escapeHtml(`${uName || uSn || 'unit'}, ${d.date || ''}`);
        // Row actions: one "⋯" menu on a desktop row (design F), the same
        // buttons laid out in the card on a phone. Every one needs edit access.
        const act = (cls, icon, text, call, title) =>
            `<button type="button" class="dmg-menu__item${cls}"${title ? ` title="${title}"` : ''} onclick="closeDamageMenu();${call}(${id})"><i class="fas ${icon}" aria-hidden="true"></i><span class="dmg-menu__text">${text}</span></button>`;
        const actions = (d.resolved
                ? act(' dmg-menu__item--main', 'fa-rotate-left', 'Reopen', 'reopenDamage', 'Reopen — the repair did not hold')
                : act(' dmg-menu__item--main', 'fa-wrench', 'Mark as repaired', 'openDamageRepair', 'Mark as done &amp; restore unit status'))
            + act(' dmg-menu__item--icon', 'fa-pen', 'Edit', 'editDamage', '')
            + act(' dmg-menu__item--icon dmg-menu__item--danger', 'fa-trash', 'Delete', 'deleteDamage', '');
        return `
        <tr class="${d.resolved ? 'dmg-row dmg-row--done' : 'dmg-row'}">
            <td class="col-check"><input type="checkbox" class="damage-check" data-id="${escapeHtml(d.id)}" aria-label="Select damage record: ${who}" onchange="updateSelectedDamageCount()"></td>
            <td data-label="Date" class="dmg-date"><span title="${escapeHtml(d.date || '')}">${escapeHtml(damageDayLabel(d.date))}</span>${queuedTag('damages', d.id)}</td>
            <td data-label="Unit" class="dmg-unit">${unitName}${meta ? `<span class="dmg-unit__meta">${meta}</span>` : ''}</td>
            <td data-label="Type" class="dmg-type-cell"><span class="dmg-type badge dmg-type--${DAMAGE_TYPE_CHIP[d.damageType] || 'other'}">${escapeHtml(damageTypeLabel(d.damageType)) || '—'}</span></td>
            <td data-label="What happened" class="dmg-what">${what || '<span class="dmg-none">—</span>'}</td>
            <td data-label="Photos" class="dmg-photos">${damagePhotoButtons(d, { addAfter: true })}</td>
            <td data-label="Repair" class="dmg-repair-cell">${repair}</td>
            <td class="col-actions dmg-act-cell">
                <div class="dmg-actions editonly--damage">
                    <button type="button" class="dmg-more" aria-expanded="false" aria-controls="dmgMenu${i}"
                        aria-label="Actions for the damage on ${who}" title="Actions" onclick="toggleDamageMenu(this, event)">${DAMAGE_MORE_ICON}</button>
                    <div class="dmg-menu" id="dmgMenu${i}">${actions}</div>
                </div>
            </td>
        </tr>`;
    }).join('');
}

// ---- Row actions menu ----
// The "⋯" button on a desktop row opens its menu fixed to the screen, so the
// table's own scroll box does not clip it near the bottom. One is open at a
// time; Escape, a click or focus elsewhere, scrolling and a re-render close
// it. On a phone the button is hidden and the menu's buttons sit in the card.
// (DAMAGE_MORE_ICON and _dmgMenuBtn are declared with the render helpers.)

// Opened from the keyboard (Enter / Space: a click with no pointer detail),
// the first item takes the focus; a mouse click leaves it on the button.
function toggleDamageMenu(btn, ev) {
    const wasOpen = _dmgMenuBtn === btn;
    closeDamageMenu();
    const menu = btn && btn.nextElementSibling;
    if (wasOpen || !menu) return;
    _dmgMenuBtn = btn;
    btn.setAttribute('aria-expanded', 'true');
    menu.classList.add('is-open');
    const r = btn.getBoundingClientRect();
    const h = menu.offsetHeight, w = menu.offsetWidth;
    const below = r.bottom + 4 + h <= window.innerHeight - 8;
    menu.style.top = `${Math.max(8, below ? r.bottom + 4 : r.top - 4 - h)}px`;
    menu.style.left = `${Math.max(8, Math.min(r.right - w, window.innerWidth - w - 8))}px`;
    const first = menu.querySelector('button');
    if (first && !(ev && ev.detail > 0)) first.focus({ preventScroll: true });
}

function closeDamageMenu(refocus) {
    const btn = _dmgMenuBtn;
    if (!btn) return;
    _dmgMenuBtn = null;
    btn.setAttribute('aria-expanded', 'false');
    const menu = btn.nextElementSibling;
    if (menu) {
        menu.classList.remove('is-open');
        menu.style.top = '';
        menu.style.left = '';
    }
    if (refocus && btn.isConnected) btn.focus();
}

document.addEventListener('click', e => {
    if (_dmgMenuBtn && !_dmgMenuBtn.parentElement.contains(e.target)) closeDamageMenu();
});
document.addEventListener('focusin', e => {
    if (_dmgMenuBtn && !_dmgMenuBtn.parentElement.contains(e.target)) closeDamageMenu();
});
// Fixed to the screen, so it would float away from its row.
window.addEventListener('scroll', () => closeDamageMenu(), true);
window.addEventListener('resize', () => closeDamageMenu());
document.addEventListener('keydown', e => {
    if (!_dmgMenuBtn) return;
    const items = [..._dmgMenuBtn.nextElementSibling.querySelectorAll('button')];
    const at = items.indexOf(document.activeElement);
    if (e.key === 'Escape') {
        // Only the menu: the global handler would close a dialog as well.
        e.stopImmediatePropagation();
        closeDamageMenu(true);
    } else if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
        e.preventDefault();
        const step = e.key === 'ArrowDown' ? 1 : -1;
        items[(at + step + items.length) % items.length].focus({ preventScroll: true });
    } else if (e.key === 'Home' || e.key === 'End') {
        e.preventDefault();
        items[e.key === 'Home' ? 0 : items.length - 1].focus({ preventScroll: true });
    }
});

// The Repair filter starts at "Any" each time Damage is opened. A link from
// another page (an "N open damage" chip, Data Check) means "show this unit's
// records", and a "Repaired" left over from last time would hide them.
let _dmgLastView = '';
document.addEventListener('ot:view', e => {
    const view = e.detail && e.detail.view;
    if (view === 'damage' && _dmgLastView !== 'damage') {
        const sel = document.getElementById('damageRepairFilter');
        if (sel && sel.value) { sel.value = ''; renderDamageTable(); }
    }
    _dmgLastView = view;
});

// ---- Selection ----
function toggleSelectAllDamages() {
    const checked = document.getElementById('selectAllDamage').checked;
    document.querySelectorAll('.damage-check').forEach(cb => { cb.checked = checked; });
    updateSelectedDamageCount();
}

function updateSelectedDamageCount() {
    selectedDamageIds.clear();
    document.querySelectorAll('.damage-check:checked').forEach(cb => selectedDamageIds.add(cb.dataset.id));
    const count = selectedDamageIds.size;
    const countEl = document.getElementById('selectedDamageCount');
    const btn = document.getElementById('btnDeleteSelectedDamage');
    if (countEl) countEl.textContent = count;
    if (btn) btn.style.display = count > 0 ? '' : 'none';
}

// ---- Component sub-field ----
// The component list applies to every damage type (mechanical, software,
// device precision), so the field stays visible; it is always optional.
function onDamageTypeChange() {
    const group = document.getElementById('dmgComponentGroup');
    if (group) group.style.display = '';
}

// ---- Modal: Add / Edit ----
function showAddDamageForm() {
    if (!requireEdit('damage')) return;
    document.getElementById('damageModalTitle').textContent = 'Report damage';
    document.getElementById('editDamageId').value = '';
    document.getElementById('damageForm').reset();
    document.getElementById('dmgDate').value = toISODate();
    populateDamageUnitSelect();
    renderDamageComponentOptions();
    onDamageTypeChange();
    _dmgFormGen++;
    _dmgPhotoBusy = 0;
    _dmgPhotoData = '';
    _dmgPhotoDirty = false;
    _dmgPhotoLoading = false;
    // A new record is open, not repaired — its After photo comes with
    // "Mark done", so the slot is shown only when editing.
    _dmgAfterData = '';
    _dmgAfterDirty = false;
    _dmgAfterLoading = false;
    showDamageAfterSlot(false);
    setDamagePhotoPreview();
    const bdGroup = document.getElementById('dmgSetBreakdownGroup');
    if (bdGroup) bdGroup.style.display = '';
    const rep = document.getElementById('dmgAlreadyRepairedRow');
    if (rep) rep.style.display = '';
    onDamageAlreadyRepairedChange();
    document.getElementById('damageModal').classList.add('open');
}

// A damage that is fixed already is recorded as done and never puts the unit
// into Breakdown, so the "set Breakdown" box does not apply to it.
function onDamageAlreadyRepairedChange() {
    const on = !!document.getElementById('dmgAlreadyRepaired')?.checked;
    const date = document.getElementById('dmgRepairedDate');
    if (date) {
        date.disabled = !on;
        if (on && !date.value) date.value = toISODate();
    }
    const bd = document.getElementById('dmgSetBreakdown');
    if (bd) bd.disabled = on;
}

function editDamage(id) {
    if (!requireEdit('damage')) return;
    const rec = globalDamages.find(d => d.id === id);
    if (!rec) return;

    document.getElementById('damageModalTitle').textContent = 'Edit damage';
    document.getElementById('editDamageId').value = id;
    document.getElementById('dmgDate').value = rec.date || '';
    // Prefer the current unit (by id or serial) so a renamed unit shows its new
    // name; fall back to the stored snapshot if the unit was deleted.
    const liveDmg = liveUnitFor(rec);
    populateDamageUnitSelect(liveDmg ? liveDmg.id : rec.unitId);
    const dmgUnitInput = document.getElementById('dmgUnit');
    if (dmgUnitInput && !dmgUnitInput.value) {
        dmgUnitInput.value = `${rec.unitName || ''}${rec.sn ? ' — ' + rec.sn : ''}`;
    }
    document.getElementById('dmgType').value = rec.damageType || '';
    renderDamageComponentOptions();
    // Keep a component that was deleted from the list still selectable here.
    const compSel = document.getElementById('dmgComponent');
    if (rec.component && !Array.from(compSel.options).some(o => o.value === rec.component)) {
        compSel.insertAdjacentHTML('beforeend', `<option value="${escapeHtml(rec.component)}">${escapeHtml(rec.component)}</option>`);
    }
    compSel.value = rec.component || '';
    document.getElementById('dmgDescription').value = rec.description || '';
    onDamageTypeChange();
    _dmgFormGen++;
    _dmgPhotoBusy = 0;
    _dmgPhotoData = rec.photo || '';
    _dmgPhotoDirty = false;
    _dmgPhotoLoading = !_dmgPhotoData && damageHasPhoto(rec);
    _dmgAfterData = '';
    _dmgAfterDirty = false;
    _dmgAfterLoading = damageHasAfterPhoto(rec);
    showDamageAfterSlot(true);
    setDamagePhotoPreview();
    // An open record that says what it holds can be linked or unlinked here;
    // older records and repaired ones keep their link as it is.
    const bdGroup = document.getElementById('dmgSetBreakdownGroup');
    const linkable = !rec.resolved && Object.prototype.hasOwnProperty.call(rec, 'drove');
    if (bdGroup) bdGroup.style.display = linkable ? '' : 'none';
    const bd = document.getElementById('dmgSetBreakdown');
    if (bd) { bd.checked = linkable && !!rec.drove; bd.disabled = false; }
    const rep = document.getElementById('dmgAlreadyRepairedRow');
    if (rep) rep.style.display = 'none';
    const repBox = document.getElementById('dmgAlreadyRepaired');
    if (repBox) repBox.checked = false;
    document.getElementById('damageModal').classList.add('open');

    if (_dmgPhotoLoading) loadDamageSlot('before', id);
    if (_dmgAfterLoading) loadDamageSlot('after', id);
}

// The photos live in documents of their own, so they arrive after the form
// does. A result is dropped once the form was closed or opened again (for
// this record or another), and never overwrites a photo the user already
// changed in that slot — their choice must not be undone by a fetch they
// started before making it.
function loadDamageSlot(side, id) {
    const gen = _dmgFormGen;
    const after = side === 'after';
    const current = () => gen === _dmgFormGen && document.getElementById('damageModal').classList.contains('open');
    (after ? loadDamageAfterPhoto : loadDamagePhoto)(id).then(photo => {
        if (!current()) return;
        if (after) { _dmgAfterLoading = false; if (!_dmgAfterDirty) _dmgAfterData = photo; }
        else { _dmgPhotoLoading = false; if (!_dmgPhotoDirty) _dmgPhotoData = photo; }
        setDamagePhotoPreview(side);
    }).catch(err => {
        console.error(`[damage] ${side} photo load failed:`, err);
        if (!current()) return;
        if (after) _dmgAfterLoading = false; else _dmgPhotoLoading = false;
        setDamagePhotoPreview(side);
        showToast(`Existing ${after ? 'After ' : ''}photo failed to load — it is still saved`, 'warning');
    });
}

function showDamageAfterSlot(show) {
    const g = document.getElementById('dmgAfterGroup');
    if (g) g.style.display = show ? '' : 'none';
}

function saveDamage(event) {
    event.preventDefault();
    if (!requireEdit('damage')) return;
    if (_dmgPhotoBusy > 0) { showToast('The photo is still being processed — save again in a moment', 'warning'); return; }
    // Refused before anything is written, so the record never says it has an
    // After photo that was not sent.
    const afterBlock = _dmgAfterDirty && document.getElementById('editDamageId').value ? damageAfterPhotoBlocker() : '';
    if (afterBlock) { showToast(afterBlock, 'warning'); return; }

    const id = document.getElementById('editDamageId').value;
    const unit = resolveDamageUnit(document.getElementById('dmgUnit').value);
    if (!unit) { showToast('Pick a unit from the list (type a name or SN)', 'warning'); return; }

    // A component of the other group is refused in both directions: GPS on an
    // excavator would flip a field it does not own, Camera AI on a tractor
    // would do the same the other way. Editing only the text of a legacy record
    // that is already like that stays allowed.
    const comp = document.getElementById('dmgComponent').value;
    const old = id ? globalDamages.find(d => d.id === id) : null;
    const moved = !old || comp !== (old.component || '') || ((liveUnitFor(old) || {}).id !== unit.id);
    if (comp && moved && componentGroupConflict(comp, unit)) {
        const own = groupDef(unitGroupOf(unit)).shortLabel;
        showToast(`Component "${comp}" does not belong to ${own} — pick a ${own} component`, 'warning');
        return;
    }

    const type = document.getElementById('dmgType').value;
    // Setting a COMPONENT to Breakdown needs to know which group's components
    // the unit has. For a unit whose group is unreadable nobody knows, so
    // refuse before the record is saved rather than save it half-linked.
    if (!id && !document.getElementById('dmgAlreadyRepaired')?.checked && hasUnreadableGroup(unit)
        && document.getElementById('dmgSetBreakdown')?.checked) {
        const f = damageTargetField(type, comp, unit);
        if (f && f !== DAMAGE_DRIVES_NOTHING && (TRACTOR_ONLY_FIELDS.includes(f) || HEAVY_ONLY_FIELDS.includes(f))) {
            showToast(`This unit's group ("${plainText(unit.unitGroup)}") is not recognised — set it first via Check Data, `
                + 'or save without ticking "set Breakdown"', 'warning');
            return;
        }
    }
    const data = {
        date: document.getElementById('dmgDate').value,
        unitId: unit.id,
        unitName: unit.name || '',
        sn: unit.sn || '',
        site: unit.site || '',
        damageType: type,
        component: document.getElementById('dmgComponent').value,
        description: document.getElementById('dmgDescription').value.trim(),
        // Only the flag lives on the record; the image goes to damagePhotos.
        hasPhoto: _dmgPhotoDirty ? !!_dmgPhotoData
                                 : damageHasPhoto(globalDamages.find(d => d.id === id))
    };
    // Untouched photos are left exactly as they are — not re-read, not
    // rewritten, not cleared. Writing photo:'' unconditionally would wipe a
    // legacy inline photo that has not been migrated yet, on a save that only
    // meant to fix a typo.
    if (_dmgPhotoDirty) data.photo = '';
    // Same for the After photo: the flag changes only when that slot did.
    if (_dmgAfterDirty && id) data.hasAfterPhoto = !!_dmgAfterData;
    // The unit's group, on every record (v167): accounts limited to one group
    // read only records that carry theirs. Restamped when a record moves.
    data.unitGroup = hasUnreadableGroup(unit) ? '' : unitGroupOf(unit);
    // What an edit does to the unit(s): give back what it held, take hold of
    // the new place. Worked out before anything is written.
    const link = id ? _planDamageEdit(old, data, unit) : null;
    if (link) Object.assign(data, link.recFields);
    // "Already repaired on …": a record of damage that is fixed already. It
    // never touches the unit — adding it open and marking it done would log a
    // breakdown of a few seconds that never happened.
    const repairedOn = !id && document.getElementById('dmgAlreadyRepaired')?.checked
        ? (document.getElementById('dmgRepairedDate').value || '') : '';
    if (!id && document.getElementById('dmgAlreadyRepaired')?.checked) {
        if (!repairedOn) { showToast('Fill in the date it was repaired', 'warning'); return; }
        if (repairedOn < data.date) { showToast('The repair date is before the damage date', 'warning'); return; }
        if (repairedOn > toISODate()) { showToast('The repair date is in the future', 'warning'); return; }
    }

    // Kept in case the server refuses the save — see rememberUnsent.
    const snap = _snapDamage();
    const unsentLabel = `damage record — ${data.unitName || data.sn || 'unit'}, ${data.date}`;
    const onFail = err => rememberUnsent(unsentLabel, err, () => _reopenDamage(snap));
    const idx = id ? globalDamages.findIndex(d => d.id === id) : -1;
    const savedId = id || generateDamageId();
    // A photo being added or replaced goes out BEFORE the record. Writes from
    // one phone reach the server in order, so no other device sees the record
    // change (and drop its copy of the photo) before the new photo is there,
    // and the record's "waiting to send" mark stays on until the photo is
    // through too. A removal goes AFTER, so the record never points at a
    // photo that is already gone.
    if (!id || idx !== -1) {
        if (_dmgPhotoDirty && _dmgPhotoData) sendDamageBeforePhoto(savedId, _dmgPhotoData);
        if (_dmgAfterDirty && id && _dmgAfterData) sendDamageAfterPhoto({ id, ...data }, _dmgAfterData);
    }
    if (id) {
        if (idx !== -1) {
            globalDamages[idx] = { ...globalDamages[idx], ...data, updatedAt: Date.now() };
            saveDamages();
            cloudPushDamage(globalDamages[idx], onFail);
            logEvent({
                action: 'update',
                unitId: unit.id,
                unitName: `[Damage] ${data.unitName}`,
                field: data.damageType + (data.component ? ` / ${data.component}` : ''),
                after: data.date
            });
            showToast('Damage record updated', 'success');
            _runDamageEdit(globalDamages[idx], link, unit);
        }
    } else {
        const newRec = { id: savedId, ...data, resolved: !!repairedOn, resolvedAt: repairedOn, createdAt: Date.now(), updatedAt: Date.now() };
        // What this record holds in Breakdown, if anything: 'status', a
        // component field, or ''. "Mark done" gives back exactly that — it
        // used to restore the unit's status even for a record that never set
        // it, clearing somebody else's breakdown and its reason.
        const setBd = !repairedOn && !!document.getElementById('dmgSetBreakdown')?.checked;
        const plan = setBd ? planDamageHold(newRec, unit) : null;
        newRec.drove = plan ? plan.field : '';
        // Left unticked on purpose: Data Check does not ask about it later.
        if (!setBd && !repairedOn) newRec.noHold = true;
        globalDamages.push(newRec);
        saveDamages();
        cloudPushDamage(newRec, onFail);
        logEvent({
            action: 'add',
            unitId: unit.id,
            unitName: `[Damage] ${data.unitName}`,
            field: data.damageType + (data.component ? ` / ${data.component}` : ''),
            after: data.date
        });
        if (repairedOn) logEvent({ action: 'update', unitId: unit.id, unitName: `[Damage] ${data.unitName}`,
                                   field: 'Repair', before: '', after: `Done (${repairedOn})` });
        showToast(repairedOn ? `Damage record added as repaired on ${repairedOn}` : 'Damage record added', 'success');

        // The record goes out first; then the unit (or the component) is put
        // into Breakdown so the dashboard and downtime tracking reflect it.
        if (plan && plan.fields && !_applyDamageLink(unit.id, plan.fields, _unlinkOnRefused(newRec.id, plan.field, unit.name || unit.sn))) {
            newRec.drove = '';
            saveDamages();
            cloudPushDamage(newRec);
            showToast(`"${unit.name || unit.sn}" was not set to Breakdown — this record is not linked to it`, 'warning');
        } else if (plan) {
            showDamageHoldToast(plan, unit, data.component);
        }
    }

    if (!id || idx !== -1) {
        if (_dmgPhotoDirty && !_dmgPhotoData) sendDamageBeforePhoto(savedId, '');
        if (_dmgAfterDirty && id && !_dmgAfterData) sendDamageAfterPhoto({ id, ...data }, '');
    }

    closeDamageModal(true);
    renderDamageTable();
}

// Editing an open record that says what it holds. The "set Breakdown" box is
// shown, ticked when it holds something. Moving the record to another unit,
// naming another place, or unticking gives back what it held; ticking, or the
// new place, takes hold. Older records (no drove) and repaired ones keep
// today's rule: moved to another unit, they hold nothing.
function _planDamageEdit(prev, data, unit) {
    const none = { recFields: {}, release: null, hold: null, reason: null };
    if (!prev) return none;
    const oldUnit = liveUnitFor(prev);
    if (prev.resolved) {
        return prev.drove && (oldUnit || {}).id !== unit.id ? { ...none, recFields: { drove: '' } } : none;
    }
    const draft = { ...prev, ...data };
    const t = damageTargetField(draft.damageType, draft.component, unit);
    const newField = t === DAMAGE_DRIVES_NOTHING ? '' : (t || 'status');
    if (!Object.prototype.hasOwnProperty.call(prev, 'drove')) {
        // An older record, read through the mapping. Same place: it stays as
        // it is. Moved, or naming another place: ask about the old place as
        // marking it done would, then it holds the new place like any record.
        const oldField = damageHeldField(prev, oldUnit);
        if (oldUnit && oldUnit.id === unit.id && oldField === newField) return none;
        let release = null;
        if (oldUnit && oldField) {
            const others = openDamageHolders(oldUnit, oldField, new Set([prev.id])).length;
            if (others) release = { unit: oldUnit, field: oldField };
            else if (isBrokenValue(oldField === 'status' ? oldUnit.status : oldUnit[oldField])
                && confirm(`Also restore the unit ${oldField === 'status' ? 'status' : 'component ' + (prev.component || oldField)} of "${oldUnit.name || oldUnit.sn}" to Good?\n\n`
                    + 'This older record does not say whether it put the unit into Breakdown. Cancel = leave the unit as is.')) {
                release = { unit: oldUnit, field: oldField };
            }
        }
        const hold = planDamageHold(draft, unit);
        return { recFields: { drove: hold.field, noHold: false }, release, hold, reason: null };
    }
    const want = !!document.getElementById('dmgSetBreakdown')?.checked;
    const oldField = prev.drove || '';
    // Unticked when the form opened and still unticked: a plain edit. The
    // record keeps its own link fields — it must not turn into "left
    // unticked on purpose", which Data Check never asks about.
    if (!want && !oldField) return none;
    if (want && oldField && oldUnit && oldUnit.id === unit.id && oldField === newField) {
        // Still holding the same place; only its reason may follow the new text.
        const reason = oldField === 'status' && unit.breakdownDamageId === prev.id ? damageBreakdownReason(draft) : '';
        return { ...none, reason: reason && reason !== unit.breakdownReason ? reason : null };
    }
    const release = oldField && oldUnit ? { unit: oldUnit, field: oldField } : null;
    if (!want) return { recFields: { drove: '', noHold: true }, release, hold: null, reason: null };
    // A different place or a different unit: planning it before the release
    // cannot be affected by it.
    const hold = planDamageHold(draft, unit);
    return { recFields: { drove: hold.field, noHold: false }, release, hold, reason: null };
}

function _runDamageEdit(rec, link, unit) {
    if (!link) return;
    if (link.release) {
        const r = releaseDamageOnUnit(rec, link.release.unit, link.release.field);
        const name = link.release.unit.name || link.release.unit.sn;
        if (r.outcome === 'restored') showToast(`"${name}" ${damageFieldLabel(link.release.field)} set back to Good`, 'info');
        else if (r.outcome === 'kept') showToast(`"${name}" stays Breakdown — ${r.others} other open damage record(s)`, 'info');
    }
    if (link.hold && link.hold.fields && !_applyDamageLink(unit.id, link.hold.fields,
            _unlinkOnRefused(rec.id, link.hold.field, unit.name || unit.sn))) {
        rec.drove = '';
        saveDamages();
        cloudPushDamage(rec);
        showToast(`"${unit.name || unit.sn}" was not set to Breakdown — this record is not linked to it`, 'warning');
    } else if (link.hold) {
        showDamageHoldToast(link.hold, unit, rec.component);
    }
    if (link.reason) _applyDamageLink(unit.id, { breakdownReason: link.reason });
}

function showDamageHoldToast(plan, unit, component) {
    const name = unit.name || unit.sn || '';
    if (plan.outcome === 'flipped') {
        showToast(`${plan.field === 'status' ? 'Unit status' : `Unit component ${component}`} "${name}" set to Breakdown`, 'info');
    } else if (plan.outcome === 'joined') {
        showToast(`"${name}" was already Breakdown — it stays Breakdown until this damage is done too`, 'info');
    } else if (plan.outcome === 'manual') {
        showToast(`"${name}" was already Breakdown (set by hand) — this record leaves it as it is`, 'info');
    } else if (plan.outcome === 'adopted') {
        showToast(`"${name}" was still Breakdown from a damage that is done — this record now holds it`, 'info');
    }
}

// Writes (or, with an empty photo, removes) a record's Before photo.
function sendDamageBeforePhoto(recId, photo) {
    _dmgPhotoCache.set(recId, photo);
    // Offline, the service worker can still be serving a firebase-init.js
    // from before this collection existed. Say so rather than failing
    // silently on a save that otherwise looks like it worked.
    if (!window.cloud.saveDamagePhoto) {
        showToast('Reload the page — an old version is still active, photo not sent yet', 'warning');
        return;
    }
    const write = photo
        ? window.cloud.saveDamagePhoto(recId, photo)
        : window.cloud.deleteDamagePhoto(recId);
    write.catch(err => {
        console.error('[damage] photo save failed:', err);
        if (err && err.code === 'permission-denied') showDamageRulesBanner();
        showToast('Record saved, but the photo failed to send', 'error');
    });
}

// Which place on the unit does a damage record drive? This is the contract the
// damage form states: "Device Precision → komponen terkait; tipe lain → status
// unit". A Mekanis/Software failure hits the unit itself even when a component
// is named, so its downtime is tracked and its description is kept as the
// breakdown reason. Returns a unit field name, or null meaning `status`.
// What a damage record drives on its unit: a component field, null (the unit's
// status), or DAMAGE_DRIVES_NOTHING. The last one exists for a legacy record
// that names a John Deere component on a heavy unit — flipping gps on an
// excavator is exactly the corruption this guards against, and flipping its
// status instead would claim a breakdown nobody reported.
// For a tractor the result is today's mapping, verbatim.
const DAMAGE_DRIVES_NOTHING = '__nothing__';
function damageTargetField(damageType, component, unit) {
    if (unit && isHeavy(unit)) {
        if (damageType !== 'Device Precision') return null;
        const h = heavyComponentField(component);
        if (h) return h;
        return componentUnitField(component) ? DAMAGE_DRIVES_NOTHING : null;
    }
    const compField = componentUnitField(component);
    return (damageType === 'Device Precision' && compField) ? compField : null;
}

// ---- Damage ↔ unit status ----
// A damage record holds one place on its unit in Breakdown — the status, or a
// component — while it is open, and gives it back when it is done. The unit
// returns to Good only when the LAST open record holding that place is done or
// deleted; a breakdown set by hand before the damage was recorded is never
// taken over, so marking the damage done does not set it Good.

// What a damage record may change on its unit, and all a Damage editor who
// cannot edit units may write there (firestore.rules, damageLinkOnly). Real
// unit edits keep going through updateUnit and its firewall.
const DAMAGE_LINK_FIELDS = ['status', 'breakdownReason', 'breakdownStartedAt', 'downtimeHistory',
    'breakdownDamageId', ...COMPONENT_KEYS, ...HEAVY_COMPONENT_KEYS];

function isBrokenValue(v) { return clean(v).toLowerCase() === 'breakdown'; }

function damageBreakdownReason(d) {
    return `${d.damageType}${d.component ? ' / ' + d.component : ''}: ${d.description || '-'}`.slice(0, 600);
}

// The place an OPEN record holds on its unit: 'status', a component field, or
// ''. Records since v120 say so in `drove`; older ones are read through
// today's mapping, as resolveDamage always read them.
function damageHeldField(d, unit) {
    if (!d || d.resolved || !unit) return '';
    if (Object.prototype.hasOwnProperty.call(d, 'drove')) return d.drove || '';
    const t = damageTargetField(d.damageType, d.component, unit);
    return t === DAMAGE_DRIVES_NOTHING ? '' : (t || 'status');
}

// Open records on this unit that hold `field`, oldest first.
function openDamageHolders(unit, field, excludeIds) {
    if (!unit || !field) return [];
    return globalDamages.filter(d => {
        if (d.resolved || (excludeIds && excludeIds.has(d.id))) return false;
        const u = liveUnitFor(d);
        return !!u && u.id === unit.id && damageHeldField(d, u) === field;
    }).sort((a, b) => String(a.date || '').localeCompare(String(b.date || '')) || (a.createdAt || 0) - (b.createdAt || 0));
}

// Is there ANOTHER still-open damage record on the same unit holding the same
// place (component field, or null for the unit's status)? If so, resolving
// this one must not flip that place back to Good. A record that never put
// anything into Breakdown (drove '') no longer counts.
function hasOtherOpenDamage(rec, unit, compField) {
    if (!unit || compField === DAMAGE_DRIVES_NOTHING) return false;
    return openDamageHolders(unit, compField || 'status', new Set([rec.id])).length > 0;
}

// Writes what a damage record changes on its unit. Allowed to a Damage editor
// who cannot edit units — the server lets them write exactly these fields —
// and sent as the changed fields only, so a copy of the unit hours old cannot
// put back anything else. Returns true when the unit changed here.
function _applyDamageLink(unitId, fields, onRefused) {
    if (!hasAccess('damage', 'edit') && !hasAccess('editUnits', 'edit')) return false;
    const idx = globalData.findIndex(u => u.id === unitId);
    if (idx === -1) return false;
    const before = { ...globalData[idx] };
    const allowed = {};
    Object.keys(fields || {}).forEach(k => {
        if (DAMAGE_LINK_FIELDS.includes(k)) allowed[k] = fields[k];
        else console.warn(`[damage] ${k} is not a damage-to-unit field — dropped`);
    });
    const guarded = guardUnitFields(before, allowed);
    if (!Object.keys(guarded).length) return false;
    const unit = { ...before, ...guarded };
    // Its own array: trackStatusChange appends the closed interval in place,
    // and on the shared one the diff below would see no change and leave the
    // interval out of the write — the next snapshot would then drop it.
    if (Array.isArray(unit.downtimeHistory)) unit.downtimeHistory = unit.downtimeHistory.slice();
    if (guarded.status !== undefined && guarded.status !== before.status) {
        trackStatusChange(unit, before.status, guarded.status);
    }
    const partial = { id: unitId };
    DAMAGE_LINK_FIELDS.forEach(k => {
        if (JSON.stringify(before[k] === undefined ? null : before[k]) !== JSON.stringify(unit[k] === undefined ? null : unit[k])) {
            partial[k] = unit[k] === undefined ? null : unit[k];
        }
    });
    if (Object.keys(partial).length === 1) return false;
    globalData[idx] = unit;
    saveToStorage(globalData);
    _sendDamageLink(partial, unit, onRefused);
    recordChange({ type: 'updated', detail: `Unit "${unit.name}" updated` });
    Object.keys(guarded).forEach(field => {
        if (field === 'downtimeHistory' || field === 'breakdownStartedAt' || field === 'breakdownDamageId') return;
        if (!sameStoredValue(before[field], unit[field])) {
            logEvent({ action: 'update', unitId, unitName: unit.name, field, before: before[field], after: unit[field] });
        }
    });
    return true;
}

// onRefused: run when the server refuses — a hold that never landed must not
// leave its record claiming it (it would later set a hand-set Breakdown Good).
function _sendDamageLink(partial, unit, onRefused) {
    if (suppressCloudWrites || !window.cloud?.isReady) return;
    const send = typeof window.cloud.updateUnitsFields === 'function'
        ? window.cloud.updateUnitsFields([partial]) : window.cloud.saveUnits([partial]);
    Promise.resolve(send).catch(err => {
        cloudWriteFailed(err, {
            what: 'unit status (from damage)',
            label: unit.name || unit.sn || '-',
            unitId: unit.id,
            resync: resyncUnits
        });
        if (onRefused) { try { onRefused(err); } catch (e) { console.error('[damage] unlink after refusal failed:', e); } }
    });
}

// The record a refused hold was for goes back to "not linked" (or to what it
// was before), if it still holds that place. Looked up by id: a snapshot has
// usually replaced the object by the time the answer comes.
function _unlinkOnRefused(recId, field, unitLabel, prev) {
    return () => {
        const r = globalDamages.find(d => d.id === recId);
        if (!r || r.resolved || r.drove !== field) return;
        r.drove = prev ? prev.drove || '' : '';
        r.noHold = prev ? !!prev.noHold : false;
        r.updatedAt = Date.now();
        saveDamages();
        cloudPushDamage(r);
        if (currentView === 'damage') renderDamageTable();
        showToast(`"${unitLabel}" was not set to Breakdown — this record is not linked to it`, 'warning');
    };
}

// What recording (or reopening) this record would do to its unit, without
// doing it: { field, fields, outcome }. field is the place the record will
// hold ('' = none); fields is the unit write, or null.
//   flipped — the place was running and goes into Breakdown;
//   joined  — other open records already hold it in Breakdown; it stays;
//   manual  — it is in Breakdown with no open record behind it (set by hand):
//             left alone, its reason kept, and not held by this record.
function planDamageHold(rec, unit) {
    if (!unit) return { field: '', fields: null, outcome: 'none' };
    const t = damageTargetField(rec.damageType, rec.component, unit);
    if (t === DAMAGE_DRIVES_NOTHING) return { field: '', fields: null, outcome: 'none' };
    const field = t || 'status';
    const cur = field === 'status' ? unit.status : unit[field];
    if (!isBrokenValue(cur)) {
        return { field, outcome: 'flipped', fields: field === 'status'
            ? { status: 'Breakdown', breakdownReason: damageBreakdownReason(rec), breakdownDamageId: rec.id }
            : { [field]: 'Breakdown' } };
    }
    if (openDamageHolders(unit, field, new Set([rec.id])).length) return { field, fields: null, outcome: 'joined' };
    // Still Breakdown from a damage record that is done, deleted or no longer
    // holds it (an older tab, or a release the server refused): not a
    // breakdown set by hand, so this record takes it over.
    if (field === 'status' && unit.breakdownDamageId) {
        const src = globalDamages.find(d => d.id === unit.breakdownDamageId);
        if (unit.breakdownDamageId === rec.id || !src || src.resolved || damageHeldField(src, liveUnitFor(src)) !== 'status') {
            const fields = {};
            const reason = damageBreakdownReason(rec);
            if (unit.breakdownReason !== reason) fields.breakdownReason = reason;
            if (unit.breakdownDamageId !== rec.id) fields.breakdownDamageId = rec.id;
            return { field, fields: Object.keys(fields).length ? fields : null, outcome: 'adopted' };
        }
    }
    return { field: '', fields: null, outcome: 'manual' };
}

// This record stops holding `field` on its unit (done, deleted, moved,
// unlinked). The place goes back to Good only when no other open record
// holds it; while others do, the unit's reason passes to the oldest of them
// if it was this record's. excludeIds: records leaving at the same time (a
// bulk delete). Returns { outcome: 'restored'|'kept'|'none'|'refused', others }.
function releaseDamageOnUnit(rec, unit, field, excludeIds) {
    if (!unit || !field) return { outcome: 'none', others: 0, field };
    const skip = new Set(excludeIds || []);
    skip.add(rec.id);
    const others = openDamageHolders(unit, field, skip);
    if (others.length) {
        if (field === 'status') {
            const leaving = id => (id === rec.id ? rec : globalDamages.find(d => d.id === id));
            // Put Breakdown before v162 no id was kept, but the reason is the
            // leaving record's own text; a reason typed by hand never matches.
            const owned = unit.breakdownDamageId
                ? skip.has(unit.breakdownDamageId)
                : [...skip].some(id => { const r = leaving(id); return !!r && clean(unit.breakdownReason) === clean(damageBreakdownReason(r)); });
            if (owned) _applyDamageLink(unit.id, { breakdownReason: damageBreakdownReason(others[0]), breakdownDamageId: others[0].id });
        }
        return { outcome: 'kept', others: others.length, field };
    }
    const cur = field === 'status' ? unit.status : unit[field];
    if (isGood(cur)) return { outcome: 'none', others: 0, field };
    return _applyDamageLink(unit.id, { [field]: 'Good' }) ? { outcome: 'restored', others: 0, field } : { outcome: 'refused', others: 0, field };
}

function damageFieldLabel(field) {
    return field === 'status' ? 'status' : (COMPONENT_LABELS[field] || field);
}

// Put the unit (or the damaged component) into Breakdown. Kept for callers
// that only need the label: '' when nothing changed.
function _applyDamageBreakdown(unitId, damageType, component, description) {
    const unit = globalData.find(u => u.id === unitId);
    const p = planDamageHold({ id: '', damageType, component, description }, unit);
    if (!p.fields) return '';
    if (p.field === 'status') delete p.fields.breakdownDamageId;
    if (!_applyDamageLink(unitId, p.fields)) return '';
    return p.field === 'status' ? 'Unit status' : `Unit component ${component}`;
}

// Mark a damage record repaired: flag it resolved and restore the unit /
// component this damage put into Breakdown (downtime duration is recorded
// automatically by trackStatusChange inside updateUnit).
// opts.confirmed: the caller already asked (the "Mark as repaired" dialog).
// opts.extra: fields written with the same record write (hasAfterPhoto).
// Returns true when the record was marked repaired.
function resolveDamage(id, opts) {
    opts = opts || {};
    if (!requireEdit('damage')) return false;
    const rec = globalDamages.find(d => d.id === id);
    if (!rec || rec.resolved) return false;
    if (!opts.confirmed && !confirm(`Mark the damage on unit "${rec.unitName}" (${rec.date}) as repaired?`)) return false;

    rec.resolved = true;
    rec.resolvedAt = toISODate();
    if (opts.extra) Object.assign(rec, opts.extra);
    rec.updatedAt = Date.now();
    saveDamages();
    cloudPushDamage(rec);
    logEvent({
        action: 'update',
        unitId: rec.unitId,
        unitName: `[Damage] ${rec.unitName}`,
        field: 'Repair',
        before: 'Open',
        after: `Done (${rec.resolvedAt})`
    });

    const res = _releaseOnClose(rec, liveUnitFor(rec));
    const restored = res.outcome === 'restored';
    const blocked = res.outcome === 'kept';

    renderDamageTable();
    if (opts.quiet) return true;
    const withPhoto = opts.extra && opts.extra.hasAfterPhoto ? ' with the After photo' : '';
    const what = res.field && res.field !== 'status' ? damageFieldLabel(res.field) : 'unit status';
    if (blocked) {
        showToast(`Damage marked as done${withPhoto} — ${what} not restored because other damage is still open`, 'warning');
    } else if (restored) {
        showToast(`Damage marked as done${withPhoto} — ${what} restored`, 'success');
    } else {
        showToast(`Damage marked as done${withPhoto}`, 'success');
    }
    return true;
}

// A record leaves the open list (marked done, or deleted): give back what it
// held. Records since v120 say what that is; for older ones, ask before
// touching the unit rather than assume.
function _releaseOnClose(rec, unit, excludeIds) {
    const nothing = { outcome: 'none', others: 0 };
    if (!unit) return nothing;
    if (Object.prototype.hasOwnProperty.call(rec, 'drove')) {
        return rec.drove ? releaseDamageOnUnit(rec, unit, rec.drove, excludeIds) : nothing;
    }
    const t = damageTargetField(rec.damageType, rec.component, unit);
    if (t === DAMAGE_DRIVES_NOTHING || isGood(t ? unit[t] : unit.status)) return nothing;
    const skip = new Set(excludeIds || []);
    skip.add(rec.id);
    // Others still hold it: it stays Breakdown whatever the answer.
    if (openDamageHolders(unit, t || 'status', skip).length) return releaseDamageOnUnit(rec, unit, t || 'status', excludeIds);
    if (!confirm(`Also restore the unit ${t ? 'component ' + (rec.component || t) : 'status'} of "${unit.name || unit.sn}" to Good?\n\n`
        + 'This older record does not say whether it put the unit into Breakdown. Cancel = leave the unit as is.')) return nothing;
    return releaseDamageOnUnit(rec, unit, t || 'status', excludeIds);
}

// What closing this open record would do to its unit, in words — for the
// repair dialog and the delete question. '' when it changes nothing.
function damageCloseEffect(rec, excludeIds) {
    const unit = liveUnitFor(rec);
    if (!unit || rec.resolved) return '';
    const field = damageHeldField(rec, unit);
    if (!field || !Object.prototype.hasOwnProperty.call(rec, 'drove')) return '';
    const name = unit.name || unit.sn || '';
    const skip = new Set(excludeIds || []);
    skip.add(rec.id);
    const others = openDamageHolders(unit, field, skip).length;
    if (others) return `"${name}" stays Breakdown — ${others} other open damage record(s)`;
    if (isGood(field === 'status' ? unit.status : unit[field])) return '';
    return field === 'status' ? `"${name}" goes back to Good` : `"${name}" ${damageFieldLabel(field)} goes back to Good`;
}

// A record marked done by mistake, or a repair that did not hold. Open again,
// it takes hold of its place on the unit as a new record would.
function reopenDamage(id) {
    if (!requireEdit('damage')) return;
    const rec = globalDamages.find(d => d.id === id);
    if (!rec || !rec.resolved) return;
    const unit = liveUnitFor(rec);
    // Held something before (or is an older record that does not say): put
    // that back. One left unticked on purpose stays unlinked.
    const intends = !rec.noHold;
    const plan = unit && intends ? planDamageHold({ ...rec, resolved: false }, unit) : null;
    const name = unit ? (unit.name || unit.sn) : (rec.unitName || rec.sn || '');
    if (!confirm(`Reopen the damage on "${name}" (${rec.date})?`
        + (plan && plan.outcome === 'flipped' ? `\n\nThe unit ${plan.field === 'status' ? 'status' : damageFieldLabel(plan.field)} goes to Breakdown.` : ''))) return;
    const was = rec.resolvedAt || '';
    rec.resolved = false;
    rec.resolvedAt = '';
    rec.drove = plan ? plan.field : '';
    rec.updatedAt = Date.now();
    saveDamages();
    cloudPushDamage(rec);
    logEvent({ action: 'update', unitId: rec.unitId, unitName: `[Damage] ${rec.unitName}`,
               field: 'Repair', before: `Done${was ? ' (' + was + ')' : ''}`, after: 'Open (reopened)' });
    const linked = !(plan && plan.fields) || _applyDamageLink(unit.id, plan.fields, _unlinkOnRefused(rec.id, plan.field, name));
    if (!linked) {
        rec.drove = '';
        saveDamages();
        cloudPushDamage(rec);
    }
    renderDamageTable();
    showToast('Damage reopened', 'success');
    if (plan && linked) showDamageHoldToast(plan, unit, rec.component);
}

// ---- "Mark as repaired" dialog — and the After photo ----
// "Mark done" used to be a bare confirm(); now it is the moment the photo of
// the repaired unit is taken. Two modes:
//   'resolve' — an open record: mark it repaired, optionally with the photo;
//   'photo'   — add (or replace) the After photo only, e.g. on a record that
//               was marked done before this dialog existed.
let _repairId = '';
let _repairMode = 'resolve';
let _repairPhoto = '';
let _repairGen = 0;
let _repairBusy = 0;       // photos being shrunk for the open dialog

// Returns true when the dialog is open for this record.
function openDamageRepair(id, opts) {
    if (!requireEdit('damage')) return false;
    const rec = globalDamages.find(d => d.id === id);
    if (!rec) return false;
    opts = opts || {};
    // Already open with a photo not saved yet (the "not sent" notice stays
    // clickable above dialogs): ask before it is replaced.
    const modal = document.getElementById('damageRepairModal');
    if (modal.classList.contains('open') && _repairPhoto && (_repairId !== id || (opts.photo && opts.photo !== _repairPhoto))) {
        closeDamageRepair();
        if (modal.classList.contains('open')) return false;
    }
    _repairGen++;
    _repairBusy = 0;
    _repairId = id;
    _repairMode = (opts.mode === 'photo' || rec.resolved) ? 'photo' : 'resolve';
    _repairPhoto = opts.photo || '';
    const lu = liveUnitFor(rec);
    const uName = lu ? (lu.name || lu.sn || '') : (rec.unitName || rec.sn || '');
    const title = document.getElementById('damageRepairTitle');
    if (title) title.innerHTML = _repairMode === 'resolve'
        ? '<i class="fas fa-wrench"></i> Mark as repaired'
        : `<i class="fas fa-camera"></i> ${damageHasAfterPhoto(rec) ? 'Replace the After photo' : 'Add the After photo'}`;
    const sum = document.getElementById('damageRepairSummary');
    if (sum) {
        const desc = rec.description || '';
        sum.innerHTML = `
            <div class="dmg-repair__unit"><strong>${escapeHtml(uName)}</strong>
                <span class="dmg-repair__meta">${escapeHtml(rec.date || '')} · ${escapeHtml(damageTypeLabel(rec.damageType))}${rec.component ? ' / ' + escapeHtml(rec.component) : ''}</span></div>
            ${desc ? `<div class="dmg-repair__desc">${escapeHtml(desc.length > 160 ? desc.slice(0, 160) + '…' : desc)}</div>` : ''}
            ${damageHasPhoto(rec) ? `<div class="dmg-repair__before">${damagePhotoButtons({ id: rec.id, photo: rec.photo, hasPhoto: rec.hasPhoto })}</div>` : ''}`;
    }
    const opt = document.getElementById('dmgRepairOptional');
    if (opt) opt.style.display = _repairMode === 'resolve' ? '' : 'none';
    const effect = document.getElementById('dmgRepairEffect');
    if (effect) {
        const e = _repairMode === 'resolve' ? damageCloseEffect(rec) : '';
        effect.textContent = e ? `After this: ${e}.` : '';
        effect.hidden = !e;
    }
    const hint = document.getElementById('dmgRepairHint');
    if (hint) hint.textContent = _repairMode === 'resolve'
        ? 'A photo of the repaired part, taken now, is shown next to the damage photo as Before / After.'
        : 'Shown next to the damage photo as Before / After.';
    const btn = document.getElementById('damageRepairSave');
    if (btn) btn.innerHTML = _repairMode === 'resolve'
        ? '<i class="fas fa-check"></i> Mark as repaired'
        : '<i class="fas fa-check"></i> Save photo';
    const input = document.getElementById('dmgRepairInput');
    if (input) input.value = '';
    setRepairPhotoPreview();
    modal.classList.add('open');
    return true;
}

async function handleRepairPhotoChange(event) {
    const file = event.target.files && event.target.files[0];
    event.target.value = '';
    if (!file) return;
    if (!file.type.startsWith('image/')) {
        showToast('The file must be an image (photo)', 'warning');
        return;
    }
    const gen = _repairGen;
    _repairBusy++;
    setRepairPhotoPreview();
    try {
        const data = await compressImageToDataURL(file);
        // Closed, or reopened for another record, while the photo was shrinking.
        if (gen !== _repairGen || !document.getElementById('damageRepairModal').classList.contains('open')) return;
        _repairPhoto = data;
    } catch (err) {
        showToast(err.message || 'Failed to process the photo', 'error');
    } finally {
        if (gen === _repairGen) { _repairBusy = Math.max(0, _repairBusy - 1); setRepairPhotoPreview(); }
    }
}

function setRepairPhotoPreview() {
    const wrap = document.getElementById('dmgRepairPreviewWrap');
    const img = document.getElementById('dmgRepairPreview');
    if (!wrap || !img) return;
    // A camera photo takes a second or two to shrink on a phone; saving in
    // that gap used to mark the repair done without its photo.
    const busy = document.getElementById('dmgRepairLoading');
    if (busy) busy.style.display = _repairBusy > 0 ? '' : 'none';
    const save = document.getElementById('damageRepairSave');
    if (save) save.disabled = _repairBusy > 0;
    if (_repairPhoto) { img.src = _repairPhoto; wrap.style.display = ''; }
    else { img.removeAttribute('src'); wrap.style.display = 'none'; }
}

function removeRepairPhoto() {
    _repairPhoto = '';
    setRepairPhotoPreview();
}

function closeDamageRepair(force) {
    const modal = document.getElementById('damageRepairModal');
    if (!modal) return;
    // Taken on this phone and nowhere else until it is saved.
    if (!force && _repairPhoto && modal.classList.contains('open') &&
        !confirm('The After photo is not saved yet and will be lost. Close anyway?')) {
        return;
    }
    modal.classList.remove('open');
    _repairGen++;
    _repairBusy = 0;
    _repairId = '';
    _repairPhoto = '';
    setRepairPhotoPreview();
}

function saveDamageRepair() {
    if (!requireEdit('damage')) return;
    const rec = globalDamages.find(d => d.id === _repairId);
    if (!rec) {
        closeDamageRepair(true);
        showToast('This damage record no longer exists', 'warning');
        return;
    }
    if (_repairBusy > 0) { showToast('The photo is still being processed — a moment', 'warning'); return; }
    const photo = _repairPhoto;
    // Refused before anything is written: the record must never say it has an
    // After photo that was never sent.
    const block = photo ? damageAfterPhotoBlocker() : '';
    if (block) { showToast(block, 'warning'); return; }
    if (_repairMode === 'resolve' && !rec.resolved) {
        // The photo goes first, so no device ever sees the record say it has
        // an After photo the server does not have yet.
        if (photo) sendDamageAfterPhoto(rec, photo);
        resolveDamage(rec.id, { confirmed: true, extra: photo ? { hasAfterPhoto: true } : null });
        closeDamageRepair(true);
        return;
    }
    if (!photo) {
        // Marked repaired on another device while this dialog was open.
        if (_repairMode === 'resolve') {
            closeDamageRepair(true);
            renderDamageTable();
            showToast('Already marked as repaired (on another device)', 'info');
            return;
        }
        showToast('Choose a photo first', 'warning');
        return;
    }
    const had = damageHasAfterPhoto(rec);
    sendDamageAfterPhoto(rec, photo);
    rec.hasAfterPhoto = true;
    rec.updatedAt = Date.now();
    saveDamages();
    cloudPushDamage(rec);
    logEvent({
        action: 'update',
        unitId: rec.unitId,
        unitName: `[Damage] ${rec.unitName}`,
        field: 'After photo',
        before: had ? 'previous photo' : '',
        after: had ? 'replaced' : 'added'
    });
    closeDamageRepair(true);
    renderDamageTable();
    showToast(had ? 'After photo replaced' : 'After photo saved', 'success');
}

// Why an After photo cannot be sent from here right now, or '' when it can.
// Asked BEFORE the record is touched — setting hasAfterPhoto for a photo that
// only ever existed in this tab's memory would show every other device an
// After button that answers "not found", for good.
function damageAfterPhotoBlocker() {
    if (!window.cloud?.isReady) return 'Not connected yet — the After photo cannot be sent. Try again in a moment';
    // Offline, the service worker can still be serving a firebase-init.js
    // from before the After photo existed.
    if (typeof window.cloud.saveDamageAfterPhoto !== 'function' || typeof window.cloud.deleteDamageAfterPhoto !== 'function') {
        return 'Reload the page — an old version is still active and cannot send the After photo';
    }
    return '';
}

// Writes (or, with an empty photo, removes) a record's After photo. Callers
// check damageAfterPhotoBlocker() first. A refused write keeps the photo: the
// "not sent" notice reopens the dialog with it.
function sendDamageAfterPhoto(rec, photo) {
    if (!rec || !rec.id) return;
    const recId = rec.id;
    if (suppressCloudWrites || damageAfterPhotoBlocker()) return;
    if (photo) _dmgAfterCache.set(recId, photo); else _dmgAfterCache.delete(recId);
    const write = photo
        ? window.cloud.saveDamageAfterPhoto(recId, photo)
        : window.cloud.deleteDamageAfterPhoto(recId);
    Promise.resolve(write).catch(err => {
        console.error('[damage] after photo save failed:', err);
        if (err && err.code === 'permission-denied') showDamageRulesBanner();
        if (!photo) { showToast('Record saved, but removing the After photo failed', 'error'); return; }
        const label = `After photo — ${rec.unitName || rec.sn || 'unit'}, ${rec.date || ''}`;
        const keep = () => rememberUnsent(label, err, () => {
            if (!globalDamages.some(d => d.id === recId)) {
                showToast('This damage record no longer exists — its After photo could not be kept', 'warning');
                return;
            }
            // Declined (another unsaved photo is open): keep this one listed.
            if (!openDamageRepair(recId, { mode: 'photo', photo })) keep();
        });
        keep();
    });
}

function closeDamageModal(force) {
    // A photo taken for a damage record exists only on this phone until the
    // record is saved; X, Cancel and the Back button used to drop it silently.
    const added = (_dmgPhotoDirty && _dmgPhotoData) || (_dmgAfterDirty && _dmgAfterData);
    const open = document.getElementById('damageModal').classList.contains('open');
    if (!force && open && (_dmgPhotoDirty || _dmgAfterDirty)) {
        if (!confirm(added ? 'The photo is not saved yet and will be lost. Close anyway?'
                           : 'The photo change is not saved yet. Close anyway?')) return;
    } else if (!force && open && !okToDiscardTyping('damageForm')) {
        return;
    }
    document.getElementById('damageModal').classList.remove('open');
}

// ---- Delete ----
// A record's photos (Before and After) live in documents of their own.
// Leaving them behind would orphan them: nothing else ever reads or removes a
// photo whose record is gone.
function dropDamagePhotos(rec) {
    if (!rec || !rec.id) return;
    _dmgPhotoCache.delete(rec.id);
    _dmgAfterCache.delete(rec.id);
    if (damageHasPhoto(rec)) _dropPhotoDoc('deleteDamagePhoto', rec.id);
    if (damageHasAfterPhoto(rec)) _dropPhotoDoc('deleteDamageAfterPhoto', rec.id);
}

function deleteDamage(id) {
    if (!requireEdit('damage')) return;
    const rec = globalDamages.find(d => d.id === id);
    if (!rec) return;
    // An open record still holding its unit gives it back, as "Mark done" does.
    const effect = damageCloseEffect(rec);
    if (!confirm(`Delete the damage record for unit "${rec.unitName}" (${rec.date})?${effect ? `\n\n${effect}.` : ''}`)) return;

    const unit = !rec.resolved ? liveUnitFor(rec) : null;
    globalDamages = globalDamages.filter(d => d.id !== id);
    saveDamages();
    cloudDeleteDamage(id);
    dropDamagePhotos(rec);
    logEvent({
        action: 'delete',
        unitId: rec.unitId,
        unitName: `[Damage] ${rec.unitName}`,
        before: rec.damageType + (rec.component ? ` / ${rec.component}` : '')
    });
    if (unit) _releaseOnClose(rec, unit);
    renderDamageTable();
    showToast('Damage record deleted', 'success');
}

function deleteSelectedDamages() {
    if (!requireEdit('damage')) return;
    const count = selectedDamageIds.size;
    if (count === 0) return;
    const idSet = new Set(selectedDamageIds);
    // Open records that say what they hold give it back — once per unit and
    // place, after ALL the selected records are counted out, so two records on
    // one unit set it Good once instead of each finding the other still open.
    const releases = new Map();
    globalDamages.filter(d => idSet.has(d.id) && !d.resolved && Object.prototype.hasOwnProperty.call(d, 'drove') && d.drove)
        .forEach(d => {
            const u = liveUnitFor(d);
            if (u && !releases.has(u.id + '|' + d.drove)) releases.set(u.id + '|' + d.drove, { rec: d, unit: u, field: d.drove });
        });
    const back = [...releases.values()].filter(r =>
        !openDamageHolders(r.unit, r.field, idSet).length && !isGood(r.field === 'status' ? r.unit.status : r.unit[r.field]));
    const placeLabel = r => (r.unit.name || r.unit.sn) + (r.field === 'status' ? '' : ' ' + damageFieldLabel(r.field));
    // Older records do not say what they hold: asked about once, as deleting
    // one of them alone asks.
    const legacy = new Map();
    globalDamages.filter(d => idSet.has(d.id) && !d.resolved && !Object.prototype.hasOwnProperty.call(d, 'drove'))
        .forEach(d => {
            const u = liveUnitFor(d);
            const f = u ? damageHeldField(d, u) : '';
            const key = u && f ? u.id + '|' + f : '';
            if (!key || releases.has(key) || legacy.has(key)) return;
            if (!isBrokenValue(f === 'status' ? u.status : u[f]) || openDamageHolders(u, f, idSet).length) return;
            legacy.set(key, { rec: d, unit: u, field: f });
        });
    if (!confirm(`Delete ${count} selected damage record(s)?`
        + (back.length ? `\n\nBack to Good: ${back.slice(0, 5).map(placeLabel).join(', ')}${back.length > 5 ? ', …' : ''}.` : ''))) return;
    const restoreLegacy = legacy.size > 0 && confirm(`${legacy.size} older record(s) do not say whether they put their unit into Breakdown: `
        + `${[...legacy.values()].slice(0, 5).map(placeLabel).join(', ')}${legacy.size > 5 ? ', …' : ''}.\n\n`
        + 'Also restore those to Good? Cancel = leave them as they are.');

    const removed = globalDamages.filter(d => idSet.has(d.id));
    globalDamages = globalDamages.filter(d => !idSet.has(d.id));
    saveDamages();
    removed.forEach(rec => cloudDeleteDamage(rec.id));
    removed.forEach(dropDamagePhotos);
    removed.forEach(rec => logEvent({
        action: 'delete',
        unitId: rec.unitId,
        unitName: `[Damage] ${rec.unitName}`,
        before: rec.damageType + (rec.component ? ` / ${rec.component}` : '')
    }));
    releases.forEach(r => releaseDamageOnUnit(r.rec, r.unit, r.field, idSet));
    if (restoreLegacy) legacy.forEach(r => releaseDamageOnUnit(r.rec, r.unit, r.field, idSet));
    renderDamageTable();
    showToast(`${count} damage record(s) deleted`, 'success');
}

// ---- Export report (CSV, opens in Excel via UTF-8 BOM) ----
function exportDamageCSV() {
    if (!canCsv('export')) return;
    const rows = getFilteredDamages();
    if (rows.length === 0) { showToast('No damage data to export', 'warning'); return; }
    const headers = ['No', 'Date', 'Unit', 'Serial Number', 'Site', 'Damage Type', 'Component', 'Description', 'Photo Before', 'Photo After', 'Repair'];
    const dataRows = rows.map((d, i) => {
        const lu = liveUnitFor(d);
        return [
            i + 1, d.date || '',
            lu ? (lu.name || '') : (d.unitName || ''),
            lu ? (lu.sn || '') : (d.sn || ''),
            lu ? (lu.site || '') : (d.site || ''),
            d.damageType || '', d.component || '', d.description || '',
            damageHasPhoto(d) ? 'Yes' : '', damageHasAfterPhoto(d) ? 'Yes' : '',
            d.resolved ? `Done ${d.resolvedAt || ''}`.trim() : 'Open'
        ];
    });
    const csv = [headers, ...dataRows].map(row =>
        row.map(csvCell).join(',')).join('\n');
    const blob = new Blob(['﻿' + csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `damage_report_${toISODate()}.csv`;
    a.click();
    URL.revokeObjectURL(url);
    showToast(`Exported ${rows.length} damage record(s) to CSV`, 'success');
}

// ---- Export photos (ZIP, one folder per unit nickname) ----
// A ZIP built here, stored (not compressed: JPEG photos are compressed
// already), so no library has to be downloaded for it.
const _CRC32_TABLE = (() => {
    const t = new Uint32Array(256);
    for (let n = 0; n < 256; n++) {
        let c = n;
        for (let k = 0; k < 8; k++) c = c & 1 ? 0xEDB88320 ^ (c >>> 1) : c >>> 1;
        t[n] = c >>> 0;
    }
    return t;
})();
function _crc32(bytes) {
    let c = 0xFFFFFFFF;
    for (let i = 0; i < bytes.length; i++) c = _CRC32_TABLE[(c ^ bytes[i]) & 0xFF] ^ (c >>> 8);
    return (c ^ 0xFFFFFFFF) >>> 0;
}
// files: [{ name: 'folder/file.jpg', data: Uint8Array }] → Blob (application/zip)
function makeZip(files) {
    const enc = new TextEncoder();
    const now = new Date();
    const dosTime = (now.getHours() << 11) | (now.getMinutes() << 5) | (now.getSeconds() >> 1);
    const dosDate = ((now.getFullYear() - 1980) << 9) | ((now.getMonth() + 1) << 5) | now.getDate();
    const parts = [], central = [];
    let offset = 0;
    files.forEach(f => {
        const name = enc.encode(f.name);
        const crc = _crc32(f.data);
        const local = new DataView(new ArrayBuffer(30));
        local.setUint32(0, 0x04034b50, true); local.setUint16(4, 20, true); local.setUint16(6, 0x0800, true);
        local.setUint16(8, 0, true); local.setUint16(10, dosTime, true); local.setUint16(12, dosDate, true);
        local.setUint32(14, crc, true); local.setUint32(18, f.data.length, true); local.setUint32(22, f.data.length, true);
        local.setUint16(26, name.length, true); local.setUint16(28, 0, true);
        parts.push(local, name, f.data);
        const cen = new DataView(new ArrayBuffer(46));
        cen.setUint32(0, 0x02014b50, true); cen.setUint16(4, 20, true); cen.setUint16(6, 20, true); cen.setUint16(8, 0x0800, true);
        cen.setUint16(10, 0, true); cen.setUint16(12, dosTime, true); cen.setUint16(14, dosDate, true);
        cen.setUint32(16, crc, true); cen.setUint32(20, f.data.length, true); cen.setUint32(24, f.data.length, true);
        cen.setUint16(28, name.length, true); cen.setUint32(42, offset, true);
        central.push(cen, name);
        offset += 30 + name.length + f.data.length;
    });
    const cenSize = central.reduce((n, p) => n + p.byteLength, 0);
    const end = new DataView(new ArrayBuffer(22));
    end.setUint32(0, 0x06054b50, true); end.setUint16(8, files.length, true); end.setUint16(10, files.length, true);
    end.setUint32(12, cenSize, true); end.setUint32(16, offset, true);
    return new Blob([...parts, ...central, end], { type: 'application/zip' });
}
function _dataUrlBytes(url) {
    const m = /^data:([^;,]+)?(;base64)?,(.*)$/s.exec(String(url || ''));
    if (!m || !m[2]) return null;
    const bin = atob(m[3]);
    const out = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
    return { bytes: out, ext: /png/.test(m[1] || '') ? 'png' : /webp/.test(m[1] || '') ? 'webp' : 'jpg' };
}
// Safe as a folder or file name on Windows, macOS and phones.
function _zipName(s, max) {
    return String(s || '').replace(/[\\/:*?"<>|\u0000-\u001f]+/g, '-').replace(/\s+/g, ' ').trim().slice(0, max || 60) || 'unnamed';
}
async function exportDamagePhotosZip() {
    if (!canCsv('export')) return;
    const rows = getFilteredDamages().filter(d => damageHasPhoto(d) || damageHasAfterPhoto(d));
    if (!rows.length) { showToast('No photos in the damage records listed', 'warning'); return; }
    const sides = rows.reduce((n, d) => n + (damageHasPhoto(d) ? 1 : 0) + (damageHasAfterPhoto(d) ? 1 : 0), 0);
    if (!confirm(`Download ${sides} photo(s) of ${rows.length} damage record(s) as one ZIP, one folder per unit?`)) return;
    // One folder per unit nickname; two units with the same nickname get the SN added.
    const folderOf = new Map(), usedFolder = new Map();
    const folderFor = d => {
        const u = liveUnitFor(d);
        const key = u ? 'u:' + u.id : 'r:' + (d.unitId || d.sn || d.unitName || '');
        if (folderOf.has(key)) return folderOf.get(key);
        let name = _zipName(u ? (u.name || u.sn) : (d.unitName || d.sn || 'Unknown unit'));
        if (usedFolder.has(name.toLowerCase())) name = _zipName(`${name} (${(u && u.sn) || d.sn || key})`);
        usedFolder.set(name.toLowerCase(), key);
        folderOf.set(key, name);
        return name;
    };
    const files = [], usedFile = new Set(), list = [['Folder', 'File', 'Unit', 'Serial Number', 'Date', 'Damage Type', 'Component', 'Side', 'Repair', 'Description']];
    let missing = 0, done = 0;
    showLoading(true);
    try {
        for (const d of rows) {
            for (const side of ['before', 'after']) {
                if (side === 'before' ? !damageHasPhoto(d) : !damageHasAfterPhoto(d)) continue;
                let photo = '';
                try { photo = side === 'before' ? await loadDamagePhoto(d.id) : await loadDamageAfterPhoto(d.id); } catch (_) { photo = ''; }
                const got = _dataUrlBytes(photo);
                done++;
                if (!got) { missing++; continue; }
                const folder = folderFor(d);
                const base = _zipName([d.date || 'no-date', damageTypeLabel(d.damageType), d.component, side].filter(Boolean).join('_'), 90);
                let file = `${base}.${got.ext}`, n = 2;
                while (usedFile.has((folder + '/' + file).toLowerCase())) file = `${base}_${n++}.${got.ext}`;
                usedFile.add((folder + '/' + file).toLowerCase());
                files.push({ name: `${folder}/${file}`, data: got.bytes });
                const lu = liveUnitFor(d);
                list.push([folder, file, lu ? lu.name || '' : d.unitName || '', lu ? lu.sn || '' : d.sn || '', d.date || '',
                    damageTypeLabel(d.damageType), d.component || '', side === 'before' ? 'Before' : 'After',
                    d.resolved ? `Done ${d.resolvedAt || ''}`.trim() : 'Open', d.description || '']);
            }
        }
    } finally {
        showLoading(false);
    }
    if (!files.length) { showToast('The photos could not be loaded — check the connection and try again', 'error'); return; }
    files.push({ name: 'photo_list.csv', data: new TextEncoder().encode('\uFEFF' + list.map(r => r.map(csvCell).join(',')).join('\n')) });
    const url = URL.createObjectURL(makeZip(files));
    const a = document.createElement('a');
    a.href = url;
    a.download = `damage_photos_${toISODate()}.zip`;
    a.click();
    setTimeout(() => URL.revokeObjectURL(url), 10000);
    showToast(`${files.length - 1} photo(s) in ${folderOf.size} unit folder(s)` + (missing ? ` — ${missing} could not be loaded` : ''), missing ? 'warning' : 'success');
}

// ---- Cloud ----
function cloudPushDamage(rec, onFail) {
    if (suppressCloudWrites || !window.cloud?.isReady || !rec) return;
    window.cloud.saveDamage(rec).catch(err => {
        cloudWriteFailed(err, {
            what: 'damage',
            label: `[Damage] ${rec.unitName || '-'}`,
            unitId: rec.unitId || '',
            resync: resyncDamages
        });
        if (onFail) onFail(err);
    });
}

function cloudDeleteDamage(id) {
    if (suppressCloudWrites || !window.cloud?.isReady || !id) return;
    window.cloud.deleteDamage(id).catch(err => cloudWriteFailed(err, {
        what: 'delete damage',
        label: '[Damage] -',
        resync: resyncDamages
    }));
}

function applyCloudDamagesSnapshot(items) {
    _markLoaded('damages');
    clearRulesBanner('damageRecords');
    console.log(`[cloud] damage snapshot received — ${items.length} docs`);

    if (_firstDamageSnapshot && items.length === 0 && globalDamages.length > 0 && !isUnitScoped()) {
        console.warn(`[cloud] first damage snapshot is empty but local has ${globalDamages.length} — keeping local, re-uploading`);
        _firstDamageSnapshot = false;
        window.cloud.saveDamages(globalDamages).catch(err => {
            console.error('[cloud] re-upload damages after empty snapshot failed:', err);
        });
        return;
    }
    _firstDamageSnapshot = false;

    // A record changed on another device — a Before or After photo may have
    // been replaced with it. Forget this device's copy, so the next open
    // fetches what is there now rather than the old picture.
    const seenAt = new Map(globalDamages.map(d => [d.id, d.updatedAt]));
    items.forEach(d => {
        if (seenAt.has(d.id) && seenAt.get(d.id) !== d.updatedAt) {
            _dmgPhotoCache.delete(d.id);
            _dmgAfterCache.delete(d.id);
        }
    });

    suppressCloudWrites = true;
    try {
        applyUnitScopeToData({ damages: items });
        if (!isUnitScoped()) { try { localStorage.setItem(DAMAGE_STORAGE_KEY, JSON.stringify(items)); } catch (e) {} }
        if (currentView === 'damage') {
            renderDamageTable();
        } else {
            updateDamageCount();
            // The dashboard shows damage stats too — on a fresh device the
            // units arrive first, and this section stayed hidden until
            // something else happened to redraw the page.
            if (currentView === 'dashboard' && globalData.length) renderDamageStats();
            // Heavy rows carry an "open damage" count: refreshed in place, so
            // ticked rows and an open Bulk Edit keep their selection.
            if (currentView === 'editUnits' && effectiveEditGroup() === 'heavy') refreshOpenDamageChips();
            // Heavy and "All" dashboard rows carry it too.
            if (currentView === 'dashboard' && globalData.length && effectiveDashGroup() !== 'tractor') renderTable(filteredData);
        }
    } finally {
        suppressCloudWrites = false;
    }
    scheduleDecisionRefresh();

    // Outside the suppress window on purpose: the migration's writes must
    // actually reach Firestore.
    migrateDamagePhotosIfNeeded();
}

// ============================================================
// LICENSE STOCK (STOK LISENSI)
// ============================================================

function generateLicenseId() {
    return 'lic_' + Date.now() + '_' + Math.random().toString(36).substr(2, 5);
}

// ---- Storage ----
function loadLicenseStock() {
    if (!unitScopeAllows('tractor')) { globalLicenseStock = []; updateLicenseCount(); return false; }
    try {
        const raw = localStorage.getItem(LICENSE_STORAGE_KEY);
        globalLicenseStock = raw ? JSON.parse(raw) : [];
    } catch (e) {
        globalLicenseStock = [];
    }
    updateLicenseCount();
    return globalLicenseStock.length > 0;
}

function saveLicenseStockLocal() {
    try {
        localStorage.setItem(LICENSE_STORAGE_KEY, JSON.stringify(globalLicenseStock));
    } catch (e) {
        showToast('Storage full. License stock not saved.', 'error');
    }
}

function updateLicenseCount() {
    const el = document.getElementById('licenseCount');
    if (el) el.textContent = `${globalLicenseStock.length} transactions`;
}

// All distinct license types: defaults plus any already used in the data.
// "Jenis Lisensi" is a free-text field with a datalist, so nothing stops
// someone typing "sf-rtk" instead of picking "SF-RTK". Without folding, that
// becomes a SEPARATE stock bucket: the real type keeps counting the units it
// already handed out (looks over-stocked) while the phantom one goes negative
// and fires a false "stok habis" alert. Fold on this key everywhere.
function licenseTypeKey(raw) {
    return (raw || '').trim().replace(/\s+/g, ' ').toLowerCase();
}

// Preferred spelling for a type: a known default wins, otherwise the spelling
// already stored for that type, otherwise the text as typed (tidied).
function canonicalLicenseType(raw) {
    const key = licenseTypeKey(raw);
    if (!key) return '';
    const known = LICENSE_TYPE_DEFAULTS.find(t => licenseTypeKey(t) === key);
    if (known) return known;
    const seen = globalLicenseStock.find(r => licenseTypeKey(r.licenseType) === key);
    const src = seen ? seen.licenseType : raw;
    return (src || '').trim().replace(/\s+/g, ' ');
}

function allLicenseTypes() {
    const byKey = new Map();
    LICENSE_TYPE_DEFAULTS.forEach(t => byKey.set(licenseTypeKey(t), t));
    globalLicenseStock.forEach(r => {
        const key = licenseTypeKey(r.licenseType);
        if (key && !byKey.has(key)) byKey.set(key, (r.licenseType || '').trim().replace(/\s+/g, ' '));
    });
    return [...byKey.values()].sort((a, b) => a.localeCompare(b));
}

// Per-type stock summary: { type: { in, out, sisa } }.
// Keyed case-insensitively so records already saved with a different casing
// merge into one bucket without needing the stored data to be rewritten.
function computeLicenseSummary() {
    const known = new Map(LICENSE_TYPE_DEFAULTS.map(t => [licenseTypeKey(t), t]));
    const acc = {};   // key -> { label, in, out }
    globalLicenseStock.forEach(r => {
        const key = licenseTypeKey(r.licenseType) || '(tanpa jenis)';
        if (!acc[key]) {
            acc[key] = {
                label: known.get(key) || (r.licenseType || '').trim().replace(/\s+/g, ' ') || '(no type)',
                in: 0, out: 0
            };
        }
        const q = Number(r.qty) || 0;
        if (r.txnType === 'OUT') acc[key].out += q;
        else acc[key].in += q;
    });
    const map = {};
    Object.values(acc).forEach(v => {
        map[v.label] = { in: v.in, out: v.out, sisa: v.in - v.out };
    });
    return map;
}

// Stock against the minimum the dashboard warns at (LICENSE_LOW_STOCK_THRESHOLD).
function licenseStockLevel(left) {
    const min = LICENSE_LOW_STOCK_THRESHOLD;
    if (left < min) return { tone: 'bad', label: 'Low' };
    if (left === min) return { tone: 'warn', label: 'At minimum' };
    return { tone: 'good', label: 'OK' };
}

// GPS or display, from the requirement options (SF-* / G5 *); '' if neither.
function licenseKindOf(type) {
    const k = licenseTypeKey(type);
    if (LIC_REQ_OPTIONS.gps.some(t => t && licenseTypeKey(t) === k)) return 'gps';
    if (LIC_REQ_OPTIONS.display.some(t => t && licenseTypeKey(t) === k)) return 'display';
    return '';
}

const FP_ICON_GPS = '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="12" r="7"></circle><circle cx="12" cy="12" r="2.5"></circle><path d="M12 2v3"></path><path d="M12 19v3"></path><path d="M2 12h3"></path><path d="M19 12h3"></path></svg>';
const FP_ICON_DISPLAY = '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="3" y="4" width="18" height="12" rx="2"></rect><path d="M8 20h8"></path><path d="M12 16v4"></path></svg>';

function renderLicenseSummary() {
    const el = document.getElementById('licenseSummary');
    if (!el) return;
    renderLicenseExpiring();
    const map = computeLicenseSummary();
    const KIND_ORDER = { gps: 0, display: 1, '': 2 };
    const types = Object.keys(map).sort((a, b) =>
        KIND_ORDER[licenseKindOf(a)] - KIND_ORDER[licenseKindOf(b)] || a.localeCompare(b));
    if (types.length === 0) {
        el.innerHTML = '<div class="license-summary__empty">No license stock data yet.</div>';
        refreshLicensePlan();
        return;
    }
    const min = LICENSE_LOW_STOCK_THRESHOLD;
    el.innerHTML = types.map(t => {
        const s = map[t];
        const lv = licenseStockLevel(s.sisa);
        const kind = licenseKindOf(t);
        const pct = Math.round(Math.min(1, Math.max(0, s.sisa) / min) * 100);
        return `
        <div class="fp-stock">
            <div class="fp-stock__head">
                <span class="fp-stock__type">${kind === 'gps' ? FP_ICON_GPS : kind === 'display' ? FP_ICON_DISPLAY : '<i class="fas fa-key" aria-hidden="true"></i>'}
                    <span>${kind === 'gps' ? 'GPS · ' : kind === 'display' ? 'Display · ' : ''}<span class="fp-nowrap">${escapeHtml(t)}</span></span></span>
                <span class="fp-chip fp-chip--${lv.tone}">${lv.label}</span>
            </div>
            <div class="fp-stock__big">${s.sisa} <span>in stock · keep ${min}</span></div>
            <div class="fp-bar fp-bar--${lv.tone}" aria-hidden="true"><span style="width:${pct}%"></span></div>
            <div class="fp-stock__sub">${s.in} in · ${s.out} distributed</div>
        </div>`;
    }).join('');
    refreshLicensePlan();
}

// ---- Expiring soon: unit licenses expired or ending within 30 days ----
// The same list the dashboard alerts and the email report use: tractors only,
// and a premium license already on its fallback tier is not an alert.
let _licExpiringAll = false;
const LIC_EXPIRING_LIMIT = 6;

function licenseExpiringRows() {
    const rows = [];
    globalData.filter(u => !isHeavy(u)).forEach(unit => {
        ['gps', 'display'].forEach(kind => {
            const end = getLicenseEndDate(unit, kind);
            if (!end || effectiveLicense(unit, kind).downgraded) return;
            const s = getExpiryStatus(end);
            if (s.kind === 'expired' || s.kind === 'soon') rows.push({ unit, kind, end, s });
        });
    });
    return rows.sort((a, b) => a.s.daysLeft - b.s.daysLeft || String(a.unit.name || '').localeCompare(String(b.unit.name || '')));
}

function toggleLicenseExpiringAll() {
    _licExpiringAll = !_licExpiringAll;
    renderLicenseExpiring();
}

function renderLicenseExpiring() {
    const list = document.getElementById('licExpiringList');
    if (!list) return;
    const rows = licenseExpiringRows();
    const more = document.getElementById('licExpiringMore');
    if (more) {
        more.hidden = rows.length <= LIC_EXPIRING_LIMIT;
        more.textContent = _licExpiringAll ? 'Show fewer' : `Show all ${rows.length}`;
        more.setAttribute('aria-expanded', String(_licExpiringAll));
    }
    if (!rows.length) {
        list.innerHTML = '<li class="fp-list__empty">No unit license expires in the next 30 days.</li>';
        return;
    }
    const iconExpired = '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="3" y="4" width="18" height="18" rx="2"></rect><path d="M16 2v4"></path><path d="M8 2v4"></path><path d="M3 10h18"></path><path d="m14.5 13.5-5 5"></path><path d="m9.5 13.5 5 5"></path></svg>';
    const iconSoon = '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M21 10.5V6a2 2 0 0 0-2-2H5a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h5.5"></path><path d="M16 2v4"></path><path d="M8 2v4"></path><path d="M3 10h8"></path><circle cx="17.5" cy="17.5" r="4.5"></circle><path d="M17.5 15.5v2l1.5 1"></path></svg>';
    list.innerHTML = (_licExpiringAll ? rows : rows.slice(0, LIC_EXPIRING_LIMIT)).map(({ unit, kind, end, s }) => {
        const expired = s.kind === 'expired';
        const name = unit.name || unit.sn || '-';
        const type = kind === 'display' ? unit.licenseDisplay : unit.gpsLicense;
        const kindLabel = kind === 'display' ? 'Display' : 'GPS';
        const what = `${kindLabel}${type ? ' ' + type : ''}`;
        // The unit and GPS / Display on top, the license type and the date below.
        const when = [type || '', expired ? `Expired ${fpShortDate(end)}`
            : `${fpShortDate(end)} · ${s.daysLeft === 0 ? 'today' : `in ${s.daysLeft} day${s.daysLeft === 1 ? '' : 's'}`}`].filter(Boolean).join(' · ');
        return `<li class="fp-list__item">
            <span class="fp-list__icon fp-list__icon--${expired ? 'bad' : 'info'}" aria-hidden="true">${expired ? iconExpired : iconSoon}</span>
            <span class="fp-list__text">
                <span class="fp-list__name">${escapeHtml(name)} · ${kindLabel}</span>
                <span class="fp-list__meta${expired ? ' fp-list__meta--bad' : ''}" title="${escapeHtml(end)}">${escapeHtml(when)}</span>
            </span>
            <button type="button" class="btn btn-sm ${expired ? 'btn-primary' : 'btn-secondary'} editonly editonly--license"
                aria-label="Renew the ${escapeHtml(what)} license of ${escapeHtml(name)}" onclick="renewLicenseFor(${jsArg(unit.id)}, ${jsArg(kind)})">Renew</button>
        </li>`;
    }).join('');
}

// Renew = distribute a license to that unit: the distribution form, filled in
// with the unit and the license type it has now.
function renewLicenseFor(unitId, kind) {
    const u = globalData.find(x => x.id === unitId);
    if (!u) return;
    showAddLicenseForm('OUT');
    if (!document.getElementById('licenseModal').classList.contains('open')) return;   // view-only
    document.getElementById('licenseModalTitle').textContent = 'Renew License';
    const type = canonicalLicenseType(kind === 'display' ? u.licenseDisplay : u.gpsLicense);
    if (type) document.getElementById('licType').value = type;
    populateLicenseUnitList(damageUnitLabel(u));
    document.getElementById('licNote').value = 'Renewal';
}

// "Email report" on this page: the dashboard's sender (it marks only the
// dashboard's button as sending), with this button held until it is done.
function sendLicenseReportFromPage(btn) {
    const dash = document.getElementById('btnEmailAlert');
    sendLicenseAlertEmail();
    if (!btn || !dash || !dash.disabled) return;   // not sent: no settings or nothing to report
    btn.disabled = true;
    const done = new MutationObserver(() => {
        if (dash.disabled) return;
        btn.disabled = false;
        done.disconnect();
    });
    done.observe(dash, { attributes: true, attributeFilter: ['disabled'] });
}

// Unit snapshots change which unit licenses are expiring.
document.addEventListener('ot:data', () => { if (currentView === 'licenseStock') renderLicenseExpiring(); });

// ---- Filtering / sort (newest date first) ----
function getFilteredLicenseStock() {
    const query = (document.getElementById('licenseSearch')?.value || '').toLowerCase().trim();
    const txnVal = (document.getElementById('licenseTxnFilter')?.value || '');
    const typeVal = (document.getElementById('licenseTypeFilter')?.value || '');

    let rows = [...globalLicenseStock];
    if (txnVal) rows = rows.filter(r => r.txnType === txnVal);
    // Folded so filtering by "SF-RTK" also catches rows stored as "sf-rtk".
    if (typeVal) rows = rows.filter(r => licenseTypeKey(r.licenseType) === licenseTypeKey(typeVal));
    if (query) rows = rows.filter(r =>
        `${r.licenseType} ${r.unitName} ${r.sn} ${r.note}`.toLowerCase().includes(query));

    rows.sort((a, b) => {
        const da = a.date || '', db = b.date || '';
        if (da !== db) return da < db ? 1 : -1;
        return (b.createdAt || 0) - (a.createdAt || 0);
    });
    return rows;
}

// ---- Render table ----
// The Status Unit cell: does the unit's licence match this distribution?
// Only the latest distribution per unit licence can be "Tersinkron" or
// "Belum"; earlier ones are history ("Digantikan").
const LIC_STATUS = {
    sync:       { cls: 'ok',    icon: 'circle-check',        label: 'Synced',
                  tip: () => 'The unit license already matches this distribution' },
    update:     { cls: 'todo',  icon: 'clock',               label: 'Not synced',
                  tip: () => 'The unit license does not match yet — press Sync to Units' },
    newer:      { cls: 'info',  icon: 'arrow-up',            label: 'Unit is newer',
                  tip: i => `Unit is valid until ${i.row.now.end}, later than this distribution — not overwritten` },
    superseded: { cls: 'muted', icon: 'clock-rotate-left',   label: 'Superseded',
                  tip: i => `A newer distribution (${i.by.date}) already sets this unit's license` },
    noUnit:     { cls: 'warn',  icon: 'triangle-exclamation', label: 'Unit missing',
                  tip: () => 'Unit not found (by id or serial number)' },
    notTractor: { cls: 'muted', icon: 'ban',                 label: 'Not Agricultural',
                  tip: () => `SF/G5 licenses are only for ${UNIT_GROUPS.tractor.label}` },
    noDate:     { cls: 'warn',  icon: 'triangle-exclamation', label: 'Invalid date',
                  tip: () => 'The distribution date is empty or unreadable (must be YYYY-MM-DD) — fix it so it can be applied to the unit' }
};
function licenseSyncCell(info) {
    const d = info && LIC_STATUS[info.code];
    if (!d) return '<span style="color:var(--text-light);font-size:11px">—</span>';
    return `<span class="lic-status lic-status--${d.cls}" title="${escapeHtml(d.tip(info))}"><i class="fas fa-${d.icon}"></i> ${escapeHtml(d.label)}</span>`;
}

function renderLicenseStockTable() {
    updateLicenseCount();
    const syncPlan = licenseSyncPlan();
    updateLicenseSyncBadge(syncPlan);
    // A re-render (search, filter, a cloud snapshot) draws fresh, unticked
    // rows — so the selection is dropped with them. Re-reading the OLD boxes
    // here kept "Delete selected" armed for rows no longer on screen.
    document.querySelectorAll('.license-check').forEach(cb => { cb.checked = false; });
    selectedLicenseIds.clear();
    updateSelectedLicenseCount();

    const selectAllBox = document.getElementById('selectAllLicense');
    if (selectAllBox) selectAllBox.checked = false;

    const rows = getFilteredLicenseStock();
    const tbody = document.getElementById('licenseBody');
    if (!tbody) return;

    const hasFilter = (document.getElementById('licenseSearch')?.value || '') ||
                      (document.getElementById('licenseTxnFilter')?.value || '') ||
                      (document.getElementById('licenseTypeFilter')?.value || '');

    if (rows.length === 0) {
        tbody.innerHTML = `<tr><td colspan="11" style="text-align:center;padding:24px;color:var(--text-secondary)">${
            hasFilter ? 'No transactions match the filter'
                      : 'No license stock transactions yet. Click <strong>Add stock</strong> or <strong>Distribute</strong>.'
        }</td></tr>`;
        return;
    }

    tbody.innerHTML = rows.map((r, i) => {
        const isOut = r.txnType === 'OUT';
        const badge = isOut
            ? '<span class="fp-chip fp-chip--neutral" title="Distributed to a unit">Out</span>'
            : '<span class="fp-chip fp-chip--good" title="Stock in">In</span>';
        const note = r.note || '';
        const noteShort = note.length > 40 ? note.slice(0, 40) + '…' : note;
        const lu = isOut ? liveUnitFor(r) : null;
        const uName = isOut ? (lu ? (lu.name || '') : (r.unitName || '')) : '';
        const uSn   = isOut ? (lu ? (lu.sn || '')   : (r.sn || '')) : '';
        return `
        <tr>
            <td class="col-check"><input type="checkbox" class="license-check" data-id="${escapeHtml(r.id)}" onchange="updateSelectedLicenseCount()"></td>
            <td>${i + 1}</td>
            <td data-label="Date" style="white-space:nowrap">${escapeHtml(r.date || '')}</td>
            <td data-label="Transaction">${badge}</td>
            <td data-label="Type"><strong>${escapeHtml(r.licenseType || '')}</strong></td>
            <td data-label="Quantity" class="fp-qty">${isOut ? '−' : '+'}${Number(r.qty) || 0}</td>
            <td data-label="Unit"${isOut ? '' : ' class="fp-empty"'}>${isOut ? escapeHtml(uName) : '<span style="color:var(--text-light);font-size:11px">—</span>'}</td>
            <td data-label="SN" style="font-family:monospace;font-size:12px"${isOut ? '' : ' class="fp-empty"'}>${isOut ? escapeHtml(uSn) : '<span style="color:var(--text-light);font-size:11px">—</span>'}</td>
            <td data-label="Unit Status"${isOut ? '' : ' class="fp-empty"'}>${isOut ? licenseSyncCell(syncPlan.recStatus.get(r.id)) : '<span style="color:var(--text-light);font-size:11px">—</span>'}</td>
            <td data-label="Notes" style="max-width:200px;font-size:12px;color:var(--text-secondary)" title="${escapeHtml(note)}"${note ? '' : ' class="fp-empty"'}>${escapeHtml(noteShort) || '<span style="color:var(--text-light)">—</span>'}</td>
            <td class="col-actions">
                <div class="row-actions">
                    <button class="btn btn-secondary" title="Edit" aria-label="Edit this transaction" onclick="editLicenseStock(${jsArg(r.id)})"><i class="fas fa-pen" aria-hidden="true"></i></button>
                    <button class="btn btn-secondary" title="Delete" aria-label="Delete this transaction" onclick="deleteLicenseStock(${jsArg(r.id)})"><i class="fas fa-trash" style="color:var(--danger)" aria-hidden="true"></i></button>
                </div>
            </td>
        </tr>`;
    }).join('');
}

// ---- Selection ----
function toggleSelectAllLicense() {
    const checked = document.getElementById('selectAllLicense').checked;
    document.querySelectorAll('.license-check').forEach(cb => { cb.checked = checked; });
    updateSelectedLicenseCount();
}

function updateSelectedLicenseCount() {
    selectedLicenseIds.clear();
    document.querySelectorAll('.license-check:checked').forEach(cb => selectedLicenseIds.add(cb.dataset.id));
    const count = selectedLicenseIds.size;
    const countEl = document.getElementById('selectedLicenseCount');
    const btn = document.getElementById('btnDeleteSelectedLicense');
    if (countEl) countEl.textContent = count;
    if (btn) btn.style.display = count > 0 ? '' : 'none';
}

// ---- Pickers ----
function populateLicenseTypeList() {
    const types = allLicenseTypes();
    const list = document.getElementById('licTypeList');
    if (list) list.innerHTML = types.map(t => `<option value="${escapeHtml(t)}"></option>`).join('');
    // Also keep the toolbar type filter in sync.
    const filter = document.getElementById('licenseTypeFilter');
    if (filter) {
        const cur = filter.value;
        filter.innerHTML = '<option value="">All Types</option>' +
            types.map(t => `<option value="${escapeHtml(t)}">${escapeHtml(t)}</option>`).join('');
        filter.value = cur;
    }
}

function populateLicenseUnitList(selectedLabel) {
    const input = document.getElementById('licUnit');
    const list = document.getElementById('licUnitList');
    if (!input || !list) return;
    // SF/G5 licences are John Deere only: heavy equipment is never offered.
    const units = globalData.filter(u => !isHeavy(u)).sort((a, b) => (a.name || '').localeCompare(b.name || ''));
    list.innerHTML = units.map(u => `<option value="${escapeHtml(damageUnitLabel(u))}"></option>`).join('');
    input.value = selectedLabel || '';
}

function onLicenseTxnChange() {
    const type = document.getElementById('licTxnType').value;
    const group = document.getElementById('licUnitGroup');
    if (group) group.style.display = (type === 'OUT') ? '' : 'none';
}

// ---- Modal: Add / Edit ----
function showAddLicenseForm(txnType) {
    if (!requireEdit('licenseStock')) return;
    document.getElementById('licenseModalTitle').textContent =
        txnType === 'OUT' ? 'Distribute License' : 'Add License Stock';
    document.getElementById('editLicenseId').value = '';
    document.getElementById('licenseForm').reset();
    document.getElementById('licTxnType').value = txnType || 'IN';
    document.getElementById('licDate').value = toISODate();
    document.getElementById('licQty').value = '1';
    populateLicenseTypeList();
    populateLicenseUnitList('');
    onLicenseTxnChange();
    document.getElementById('licenseModal').classList.add('open');
}

function editLicenseStock(id) {
    if (!requireEdit('licenseStock')) return;
    const rec = globalLicenseStock.find(r => r.id === id);
    if (!rec) return;

    document.getElementById('licenseModalTitle').textContent = 'Edit License Transaction';
    document.getElementById('editLicenseId').value = id;
    populateLicenseTypeList();
    document.getElementById('licTxnType').value = rec.txnType || 'IN';
    document.getElementById('licDate').value = rec.date || '';
    document.getElementById('licType').value = rec.licenseType || '';
    document.getElementById('licQty').value = rec.qty || 1;
    // Prefer the current unit (by id or serial) so renames show; fall back to
    // the stored snapshot if the unit was deleted.
    const liveLic = rec.txnType === 'OUT' ? liveUnitFor(rec) : null;
    const label = liveLic
        ? damageUnitLabel(liveLic)
        : (rec.txnType === 'OUT' ? `${rec.unitName || ''}${rec.sn ? ' — ' + rec.sn : ''}` : '');
    populateLicenseUnitList(label);
    document.getElementById('licNote').value = rec.note || '';
    onLicenseTxnChange();
    document.getElementById('licenseModal').classList.add('open');
}

// Which unit license field-group a stock license type belongs to.
// Folded, so a record saved as "sf-rtk" still links to the unit's GPS licence
// instead of being written off as a non-standard type.
function _licenseKindForType(type) {
    const k = licenseTypeKey(type);
    if (k === 'sf-rtk' || k === 'sf-1') return 'gps';
    if (k === 'g5 advance' || k === 'g5 basic') return 'display';
    return null; // custom type — not a standard unit license
}

// ---- Distribution → unit licence ----
// A distribution (OUT) sets its unit's licence: type, start = distribution
// date, expiry = start + 1 year. That flows into expiry status, License
// Alerts and the auto-downgrade.
//
// Everything here is DIFF-based. For each unit + licence kind the plan works
// out what the unit should hold according to its latest distribution, compares
// that with what it holds now, and only a difference is ever written. The old
// "Sync ke Unit" rewrote every unit that had ever received a distribution —
// 55 writes to fix 3 — and in doing so re-stamped units whose licence had been
// renewed by hand, and bounced correctly downgraded units back to SF-RTK so the
// auto-downgrade had to write them down again.

const _LIC_FIELDS = {
    gps:     { type: 'gpsLicense',     start: 'gpsLicenseStartDate',     end: 'gpsLicenseEndDate',
               expiredAt: 'gpsLicenseExpiredAt',     premium: 'SF-RTK',     fallback: 'SF-1',     label: 'GPS' },
    display: { type: 'licenseDisplay', start: 'displayLicenseStartDate', end: 'displayLicenseEndDate',
               expiredAt: 'displayLicenseExpiredAt', premium: 'G5 Advance', fallback: 'G5 Basic', label: 'Display' }
};

// What the unit's licence of `kind` should be, given the distribution that
// last set it. An expired premium tier is described in the state the
// auto-downgrade leaves it in (fallback tier, no expiry, the old expiry
// archived) — so a unit that was correctly downgraded reads as in sync, and a
// back-dated handover is written straight into that state instead of as a
// premium licence that is already dead.
// A distribution date the plan can trust: exactly YYYY-MM-DD, and a real day.
// '9/15/2024' would otherwise sort as a string ('9' > '1') and be read
// month-first by new Date() — wrong for a team that writes 15/09/2024.
function isoDistributionDate(v) {
    const s = String(v == null ? '' : v).trim();
    if (!/^\d{4}-\d{2}-\d{2}$/.test(s)) return '';
    return toISODate(parseLocalDate(s)) === s ? s : '';   // rejects 2026-02-30
}
// A unit's stored licence date, read the way the rest of the app reads it,
// so comparisons happen on YYYY-MM-DD. null = set but unreadable.
function isoUnitDate(v) {
    if (v == null || String(v).trim() === '') return '';
    const d = parseLocalDate(v);
    return d ? toISODate(d) : null;
}

function distributionTarget(rec, kind) {
    const F = _LIC_FIELDS[kind];
    const start = isoDistributionDate(rec.date);
    const end = addOneYearISO(start);
    // The canonical spelling: 'sf-rtk' from a CSV must land as 'SF-RTK', or
    // the unit form's select shows nothing and the auto-downgrade (exact
    // match) never fires.
    const premium = licenseTypeKey(rec.licenseType) === licenseTypeKey(F.premium);
    if (premium && getExpiryStatus(end).kind === 'expired') {
        return { type: F.fallback, start, end: '', expiredAt: end, downgraded: true };
    }
    return { type: premium ? F.premium : F.fallback, start, end, expiredAt: '', downgraded: false };
}

// The unit fields that put `target` in place. Only fields that differ are
// returned, so an in-sync licence produces {} and nothing is written.
function distributionFields(unit, kind, target) {
    const F = _LIC_FIELDS[kind];
    const out = {};
    // Type compared EXACTLY, so a unit holding 'sf-rtk' is corrected.
    if ((unit[F.type] || '') !== target.type) out[F.type] = target.type;
    // Dates compared as what the app shows: GPS falls back to the legacy
    // licenseStartDate / licenseEndDate, so a legacy-only unit that already
    // matches is in sync, not a no-op "update".
    const curStart = kind === 'gps' ? (unit.gpsLicenseStartDate || unit.licenseStartDate || '') : (unit[F.start] || '');
    if (isoUnitDate(curStart) !== target.start) out[F.start] = target.start;
    if (isoUnitDate(getLicenseEndDate(unit, kind)) !== target.end) {
        out[F.end] = target.end;
        // An emptied gpsLicenseEndDate would resurrect the legacy field.
        if (kind === 'gps' && !target.end && unit.licenseEndDate) out.licenseEndDate = '';
    }
    if (target.downgraded && isoUnitDate(unit[F.expiredAt]) !== target.expiredAt) out[F.expiredAt] = target.expiredAt;
    return out;
}

// One row of the plan: where this unit's licence stands against its latest
// distribution.
//   sync  — already what the distribution says; nothing to write
//   update — differs, and the distribution is at least as recent: write it
//   newer — the unit holds a LATER expiry than its latest distribution (renewed
//           by hand, or the distribution was deleted/edited): left alone
//           unless someone ticks it
function _licenseSyncRow(rec, unit, kind) {
    const target = distributionTarget(rec, kind);
    const fields = distributionFields(unit, kind, target);
    const eff = effectiveLicense(unit, kind);
    const unitExpiry = eff.end || '';
    const unitIso = isoUnitDate(unitExpiry);
    const targetExpiry = target.downgraded ? target.expiredAt : target.end;
    let status = 'update';
    if (!Object.keys(fields).length) status = 'sync';
    // An expiry nobody can read is not overwritten on a guess.
    else if (unitIso === null) status = 'newer';
    else if (unitIso && targetExpiry && unitIso > targetExpiry) status = 'newer';
    return { key: unit.id + '|' + kind, rec, unit, kind, target, fields, status,
             now: { type: eff.type || '', end: unitExpiry, downgraded: !!eff.downgraded, premium: eff.premium } };
}

// The whole plan: latest distribution per LIVE unit + kind. Units are resolved
// by id and then serial number (liveUnitFor), so a distribution to a unit that
// was deleted and imported again still reaches it.
function licenseSyncPlan() {
    const latest = new Map();   // `${unit.id}|${kind}` -> { rec, unit, kind }
    const skipped = { noUnit: 0, notTractor: 0, noDate: 0 };
    // Where each distribution stands, for the Status Unit column: a skip
    // reason, or the key of the unit licence it competes for.
    const recStatus = new Map();   // rec.id -> { code, by? }
    globalLicenseStock.forEach(r => {
        if (r.txnType !== 'OUT') return;
        const kind = _licenseKindForType(r.licenseType);
        if (!kind) return;
        const unit = liveUnitFor(r);
        if (!unit) { skipped.noUnit++; recStatus.set(r.id, { code: 'noUnit' }); return; }
        // The write boundary: no licence lands on heavy equipment, nor on a
        // unit whose group nobody can read.
        if (isHeavy(unit) || hasUnreadableGroup(unit)) { skipped.notTractor++; recStatus.set(r.id, { code: 'notTractor' }); return; }
        // Without a date the target would be "today + 1 year" — different
        // every day, so the unit could never read as in sync.
        const iso = isoDistributionDate(r.date);
        if (!iso) { skipped.noDate++; recStatus.set(r.id, { code: 'noDate' }); return; }
        const key = unit.id + '|' + kind;
        recStatus.set(r.id, { key });
        const cur = latest.get(key);
        // date → createdAt → id. The id tie-break keeps the result stable:
        // without it two same-day records with the same createdAt resolve by
        // whatever order Firestore happened to return.
        const newer = !cur
            || iso > cur.iso
            || (iso === cur.iso && (
                   (r.createdAt || 0) > (cur.rec.createdAt || 0)
                || ((r.createdAt || 0) === (cur.rec.createdAt || 0) && String(r.id) > String(cur.rec.id))
               ));
        if (newer) latest.set(key, { rec: r, iso, unit, kind });
    });
    const rows = [...latest.values()].map(x => _licenseSyncRow(x.rec, x.unit, x.kind))
        .sort((a, b) => (a.unit.name || '').localeCompare(b.unit.name || '') || a.kind.localeCompare(b.kind));
    // Only the LATEST distribution per unit licence decides it; every earlier
    // one is 'superseded' — correct history, nothing to sync.
    const rowByKey = new Map(rows.map(r => [r.key, r]));
    recStatus.forEach((info, id) => {
        if (!info.key) return;
        const row = rowByKey.get(info.key);
        if (row.rec.id === id) { info.code = row.status; info.row = row; }
        else { info.code = 'superseded'; info.by = row.rec; }
    });
    return { rows, skipped, recStatus };
}

// Writes the chosen rows, one updateUnit per unit (GPS and Display together).
// Re-plans first: the table may have changed since the preview was drawn, and
// a row that has meanwhile come into sync must not be written again.
//
// `shown` (optional): key -> { status, sig } as the preview displayed it. A
// row is written only if it still reads exactly the same — a unit renewed on
// another device while the preview was open turns 'update' into 'newer', and
// writing it anyway would move that renewal backwards.
function _applyLicenseSync(keys, shown) {
    const want = new Set(keys);
    const byUnit = new Map();
    let stale = 0;
    licenseSyncPlan().rows.forEach(row => {
        if (!want.has(row.key) || row.status === 'sync') return;
        const was = shown && shown.get(row.key);
        if (shown && (!was || was.status !== row.status || was.sig !== JSON.stringify(row.fields))) { stale++; return; }
        const f = byUnit.get(row.unit.id) || {};
        byUnit.set(row.unit.id, Object.assign(f, row.fields));
    });
    let n = 0;
    byUnit.forEach((fields, unitId) => { if (updateUnit(unitId, fields)) n++; });
    return shown ? { written: n, stale } : n;
}

// Apply ONE distribution to its unit — the Distribusi form's and the CSV
// import's path. Refuses to move a licence BACKWARDS, so back-filling an old
// handover can't expire a unit that has since been renewed — unless
// opts.force, which the form passes only when the unit's licence came from the
// very record being edited (correcting its date must be able to go back).
// Returns 'applied' | 'unchanged' | 'skipped-older' | false.
function applyDistributedLicenseToUnit(rec, opts) {
    if (!rec || rec.txnType !== 'OUT' || !rec.unitId) return false;
    const kind = _licenseKindForType(rec.licenseType);
    if (!kind) return false;
    const unit = globalData.find(u => u.id === rec.unitId);
    // The write boundary: whatever path reached here, no licence lands on a
    // heavy unit (or one whose group is unreadable).
    if (!unit || isHeavy(unit) || hasUnreadableGroup(unit)) return false;
    if (!isoDistributionDate(rec.date)) return false;
    const row = _licenseSyncRow(rec, unit, kind);
    if (row.status === 'sync') return 'unchanged';
    if (row.status === 'newer' && !(opts && opts.force)) return 'skipped-older';
    return updateUnit(unit.id, row.fields) ? 'applied' : false;
}

// Number of unit licences that differ from their latest distribution — shown
// on the Sync button so nobody has to press it to find out.
function updateLicenseSyncBadge(plan) {
    const el = document.getElementById('licSyncCount');
    if (!el) return;
    let n = 0;
    try { n = (plan || licenseSyncPlan()).rows.filter(r => r.status === 'update').length; } catch (_) { n = 0; }
    el.textContent = n;
    el.hidden = n === 0;
    // Entry already syncs itself (form, CSV import, edits, deletes), so the
    // button is a repair tool: shown only while something needs repairing.
    const btn = document.getElementById('licSyncBtn');
    if (btn) btn.style.display = n === 0 ? 'none' : '';
}

let _licSyncKeys = [];
let _licSyncShown = new Map();

// "Sync ke Unit": shows what WOULD change and writes only what is ticked.
// Rows already in sync are counted but never written; rows where the unit
// holds a later expiry are listed unticked.
function syncDistributionsToUnits() {
    if (!requireEdit('licenseStock')) return;
    if (!hasAccess('editUnits', 'edit')) {
        showToast('Sync to Units changes unit data — requires edit access on Edit Units', 'warning');
        return;
    }
    const { rows, skipped } = licenseSyncPlan();
    const todo = rows.filter(r => r.status !== 'sync');
    const inSync = rows.length - todo.length;
    const skipNote = [
        skipped.noUnit ? `${skipped.noUnit} with unit not found` : '',
        skipped.noDate ? `${skipped.noDate} with invalid date` : '',
        skipped.notTractor ? `${skipped.notTractor} to non-${UNIT_GROUPS.tractor.shortLabel} units` : ''
    ].filter(Boolean).join(', ');
    if (!rows.length) {
        showToast('No standard distributions (SF-RTK/SF-1/G5) to sync to units'
            + (skipNote ? ` (${skipNote})` : ''), 'info');
        return;
    }
    if (!todo.length) {
        showToast(`All ${inSync} unit licenses already match their latest distribution — nothing written`
            + (skipNote ? ` · skipped: ${skipNote}` : ''), 'success');
        return;
    }

    _licSyncKeys = todo.map(r => r.key);
    _licSyncShown = new Map(todo.map(r => [r.key, { status: r.status, sig: JSON.stringify(r.fields) }]));
    const fmt = (type, end) => `${escapeHtml(type || '—')}${end ? ` <span class="lic-sync__date">until ${escapeHtml(end)}</span>` : ''}`;
    document.getElementById('licSyncBody').innerHTML = todo.map((r, i) => {
        const t = r.target;
        // A downgraded target has no expiry of its own: say which premium
        // licence ran out and when, instead of pinning that date on SF-1.
        const toCell = t.downgraded
            ? `${escapeHtml(t.type)} <span class="lic-sync__date">(${escapeHtml(r.rec.licenseType)} expired ${escapeHtml(t.expiredAt)})</span>`
            : fmt(t.type, t.end);
        // Same for what the unit holds now: a written-down premium is shown as
        // the premium that ran out, not as a fallback "valid until" a dead date.
        const nowCell = r.now.downgraded
            ? `${escapeHtml(r.now.type)} <span class="lic-sync__date">(${escapeHtml(r.now.premium)} expired ${escapeHtml(r.now.end)})</span>`
            : fmt(r.now.type, r.now.end);
        const nowExpired = getExpiryStatus(r.now.end).kind === 'expired';
        const why = r.status === 'newer'
            ? (isoUnitDate(r.now.end) === null
                ? `Expiry date on the unit is unreadable ("${escapeHtml(r.now.end)}") — not overwritten without a check`
                : nowExpired
                ? `License on the unit is newer (${r.now.downgraded ? escapeHtml(r.now.premium) + ' ' : ''}expires ${escapeHtml(r.now.end)}) — leave it unless it is wrong`
                : `Unit is already valid for longer (until ${escapeHtml(r.now.end)}) — leave it unless it is wrong`)
            : (t.downgraded ? `Distribution ${escapeHtml(r.rec.date)} has expired — recorded as ${escapeHtml(t.type)} (auto-downgraded)`
                            : `Distribution ${escapeHtml(r.rec.date)}`);
        return `<tr class="${r.status === 'newer' ? 'lic-sync__row--newer' : ''}">
            <td class="col-check" data-label="Apply"><input type="checkbox" class="lic-sync-check" data-i="${i}"${r.status === 'update' ? ' checked' : ''}
                aria-label="Apply to ${escapeHtml(r.unit.name || r.unit.sn || '')}" onchange="updateLicSyncApplyLabel()"></td>
            <td data-label="Unit"><span class="lic-sync__unit"><strong>${escapeHtml(r.unit.name || '')}</strong><span class="lic-sync__sn">${escapeHtml(r.unit.sn || '')}</span></span></td>
            <td data-label="License">${_LIC_FIELDS[r.kind].label}</td>
            <td data-label="Current">${nowCell}</td>
            <td data-label="Change To">${toCell}</td>
            <td data-label="Details" class="lic-sync__why">${why}</td>
        </tr>`;
    }).join('');
    const nUpdate = todo.filter(r => r.status === 'update').length;
    const nNewer = todo.length - nUpdate;
    document.getElementById('licSyncSummary').textContent =
        `${nUpdate} need updating` + (nNewer ? ` · ${nNewer} unit(s) valid for longer (unticked)` : '')
        + ` · ${inSync} already match and are left untouched` + (skipNote ? ` · skipped: ${skipNote}` : '');
    updateLicSyncApplyLabel();
    rememberFocus();
    document.getElementById('licSyncModal').classList.add('open');
}

function updateLicSyncApplyLabel() {
    const n = document.querySelectorAll('#licSyncBody .lic-sync-check:checked').length;
    const btn = document.getElementById('licSyncApplyBtn');
    if (!btn) return;
    btn.disabled = n === 0;
    btn.innerHTML = `<i class="fas fa-link"></i> Apply ${n} change(s)`;
}

function closeLicSyncModal() {
    _licSyncKeys = [];
    _licSyncShown = new Map();
    document.getElementById('licSyncModal').classList.remove('open');
}

function applyLicSyncSelection() {
    if (!requireEdit('licenseStock')) return;
    const keys = [...document.querySelectorAll('#licSyncBody .lic-sync-check:checked')]
        .map(cb => _licSyncKeys[Number(cb.dataset.i)]).filter(Boolean);
    const shown = _licSyncShown;
    closeLicSyncModal();
    if (!keys.length) return;
    const { written: n, stale } = _applyLicenseSync(keys, shown);
    showToast((n ? `Licenses of ${n} unit(s) updated from their latest distribution` : 'Nothing written')
        + (stale ? ` · ${stale} row(s) skipped because the data changed since the preview — open Sync to Units again` : ''),
        stale ? 'warning' : (n ? 'success' : 'info'));
    renderLicenseStockTable();
    if (currentView === 'dashboard') updateDashboard(filteredData);
    else if (currentView === 'editUnits') renderEditTable();
}

// Is `rec` the distribution a unit's licence currently comes from — does the
// unit hold exactly what it would write? Read BEFORE the ledger changes.
function _drivenBy(rec) {
    if (!rec || rec.txnType !== 'OUT') return null;
    const kind = _licenseKindForType(rec.licenseType);
    if (!kind || !isoDistributionDate(rec.date)) return null;
    const unit = liveUnitFor(rec);
    if (!unit || isHeavy(unit) || hasUnreadableGroup(unit)) return null;
    return _licenseSyncRow(rec, unit, kind).status === 'sync' ? { rec, unit, kind } : null;
}

// A distribution that set a unit's licence was deleted, moved to another
// unit, changed to another licence kind, or turned into stock-in. One licence
// cannot sit on two units, and nothing else will ever point at this one: the
// plan only sees units that still HAVE a distribution. So ask, once for the
// whole batch — put each unit back on its previous distribution, or clear the
// licence when there is none. Cancel leaves everything as it is, and says so.
function _releaseDistributions(list) {
    const seen = new Set();
    const items = (list || []).filter(Boolean).filter(d => {
        const k = d.unit.id + '|' + d.kind;
        if (seen.has(k)) return false;
        seen.add(k); return true;
    }).map(d => {
        const unit = globalData.find(u => u.id === d.unit.id);
        if (!unit) return null;
        const row = licenseSyncPlan().rows.find(r => r.key === unit.id + '|' + d.kind);
        const F = _LIC_FIELDS[d.kind];
        let fields;
        if (row) fields = row.fields;
        else {
            fields = { [F.type]: '', [F.start]: '', [F.end]: '' };
            if (unit[F.expiredAt]) fields[F.expiredAt] = '';
            if (d.kind === 'gps' && unit.licenseStartDate) fields.licenseStartDate = '';
            if (d.kind === 'gps' && unit.licenseEndDate) fields.licenseEndDate = '';
        }
        if (!Object.keys(fields).length) return null;
        return { unit, kind: d.kind, row, fields,
                 line: `· ${unit.name || unit.sn} (${F.label}): ` + (row
                     ? `back to ${row.target.type} from the ${row.rec.date} distribution`
                     : 'cleared — no other distribution') };
    }).filter(Boolean);
    if (!items.length) return;
    if (!hasAccess('editUnits', 'edit')) {
        showToast(`${items.length} unit(s) still hold a license from this distribution — Unit edit access is needed to fix it`, 'warning');
        return;
    }
    const lines = items.slice(0, 6).map(i => i.line).join('\n') + (items.length > 6 ? `\n… and ${items.length - 6} more` : '');
    if (!confirm(`${items.length} unit(s) still hold a license from the distribution just changed/deleted:\n\n${lines}\n\n`
        + 'OK = fix the unit licenses · Cancel = leave them as they are')) {
        showToast(`Licenses of ${items.length} unit(s) left as is — they still hold a license from that distribution`, 'warning');
        return;
    }
    let n = 0;
    items.forEach(i => { if (updateUnit(i.unit.id, i.fields)) n++; });
    showToast(`Licenses of ${n} unit(s) fixed`, 'success');
}

function saveLicenseStock(event) {
    event.preventDefault();
    if (!requireEdit('licenseStock')) return;

    const id = document.getElementById('editLicenseId').value;
    // Snapshot BEFORE any mutation — used to decide whether this save should
    // touch the unit's own licence at all (editing only the note must not).
    const prevRec = id ? { ...(globalLicenseStock.find(r => r.id === id) || {}) } : null;
    // Did the unit's licence come from THIS record? Then correcting its date
    // (a typo'd year) must be able to move the licence back as well, instead
    // of being refused as "older". Decided before anything is mutated.
    const prevDriven = _drivenBy(prevRec);
    const prevDrove = !!prevDriven;
    const prevUnit = prevDriven && prevDriven.unit;
    const prevKind = prevDriven && prevDriven.kind;
    const txnType = document.getElementById('licTxnType').value;
    const typedType = document.getElementById('licType').value.trim();
    // Snap to the existing spelling so a stray "sf-rtk" doesn't open a second
    // stock bucket for a type that already exists.
    const licenseType = canonicalLicenseType(typedType);
    const qty = Math.max(1, parseInt(document.getElementById('licQty').value, 10) || 1);
    if (!licenseType) { showToast('Enter the license type', 'warning'); return; }
    if (typedType && licenseType !== typedType) {
        showToast(`License type normalised to "${plainText(licenseType)}"`, 'info');
    }

    const data = {
        date: document.getElementById('licDate').value,
        txnType,
        licenseType,
        qty,
        unitId: '', unitName: '', sn: '',
        note: document.getElementById('licNote').value.trim()
    };

    if (txnType === 'OUT') {
        const unit = resolveDamageUnit(document.getElementById('licUnit').value);
        if (!unit) { showToast('Pick the target unit from the list (type a name or SN)', 'warning'); return; }
        // A legacy row that already points at this heavy unit stays editable;
        // applyDistributedLicenseToUnit still refuses to write to the unit.
        const legacy = prevRec && prevRec.unitId === unit.id;
        if (isHeavy(unit) && !legacy) {
            showToast(`Unit "${plainText(unit.name)}" is Heavy Equipment — SF/G5 licenses are only for ${UNIT_GROUPS.tractor.label}`, 'warning');
            return;
        }
        data.unitId = unit.id;
        data.unitName = unit.name || '';
        data.sn = unit.sn || '';

        // Warn (but allow) if distributing more than current remaining stock.
        const sum = computeLicenseSummary()[licenseType];
        let sisa = sum ? sum.sisa : 0;
        if (id) { // editing an existing OUT — add its old qty back to available
            const old = globalLicenseStock.find(r => r.id === id);
            // Folded: the stored row may carry a different casing than the
            // canonical type, and missing that would understate the stock the
            // edit frees up and warn about a shortage that isn't real.
            if (old && old.txnType === 'OUT' &&
                licenseTypeKey(old.licenseType) === licenseTypeKey(licenseType)) {
                sisa += (Number(old.qty) || 0);
            }
        }
        if (qty > sisa) {
            if (!confirm(`Not enough "${licenseType}" stock (${sisa} remaining). Save anyway?`)) return;
        }
    }

    if (id) {
        const idx = globalLicenseStock.findIndex(r => r.id === id);
        if (idx !== -1) {
            globalLicenseStock[idx] = { ...globalLicenseStock[idx], ...data, updatedAt: Date.now() };
            saveLicenseStockLocal();
            cloudPushLicense(globalLicenseStock[idx]);
            logEvent({
                action: 'update',
                unitId: data.unitId || '',
                unitName: `[License] ${data.licenseType}`,
                field: txnType === 'OUT' ? `Distribution → ${data.unitName}` : 'Stock in',
                after: `${qty} (${data.date})`
            });
            showToast('License transaction updated', 'success');
        }
    } else {
        const newRec = { id: generateLicenseId(), ...data, createdAt: Date.now(), updatedAt: Date.now() };
        globalLicenseStock.push(newRec);
        saveLicenseStockLocal();
        cloudPushLicense(newRec);
        logEvent({
            action: 'add',
            unitId: data.unitId || '',
            unitName: `[License] ${data.licenseType}`,
            field: txnType === 'OUT' ? `Distribution → ${data.unitName}` : 'Stock in',
            after: `${qty} (${data.date})`
        });
        showToast(txnType === 'OUT' ? 'License distribution recorded' : 'License stock added', 'success');
    }

    // Connect distribution → the unit's own license (type + dates).
    // Only on create, or when the edit actually changed unit / type / date —
    // fixing a typo in the note must not re-stamp the unit's licence.
    const licenseRelevantChange = !prevRec
        || prevRec.txnType !== txnType
        || (prevRec.unitId || '') !== (data.unitId || '')
        || (prevRec.licenseType || '') !== licenseType
        || (prevRec.date || '') !== (data.date || '');
    if (txnType === 'OUT' && licenseRelevantChange) {
        const kindKey = _licenseKindForType(licenseType);
        const sameTarget = prevDrove && prevUnit.id === data.unitId && prevKind === kindKey;
        const applied = applyDistributedLicenseToUnit({ txnType, unitId: data.unitId, licenseType, date: data.date },
                                                      { force: sameTarget });
        const kind = kindKey === 'display' ? 'Display' : 'GPS';
        const tgt = kindKey && data.date ? distributionTarget({ licenseType, date: data.date }, kindKey) : null;
        if (applied === 'applied' && tgt && tgt.downgraded) {
            showToast(`${kind} license of unit "${plainText(data.unitName)}": ${plainText(licenseType)} from ${plainText(data.date)} already expired ${plainText(tgt.expiredAt)} — recorded as ${plainText(tgt.type)}`, 'info');
        } else if (applied === 'applied') {
            showToast(`${kind} license of unit "${plainText(data.unitName)}" set to ${plainText(licenseType)} (valid for 1 year)`, 'info');
        } else if (applied === 'unchanged') {
            showToast(`${kind} license of unit "${plainText(data.unitName)}" already matches — not changed`, 'info');
        } else if (applied === 'skipped-older') {
            showToast(`${kind} license of unit "${plainText(data.unitName)}" not changed — the unit is already valid for longer`, 'warning');
        } else if (!kindKey) {
            showToast(`"${plainText(licenseType)}" is not a standard unit license — recorded in stock only`, 'warning');
        } else if (!hasAccess('editUnits', 'edit')) {
            showToast(`Distribution recorded, but the ${kind} license of unit "${plainText(data.unitName)}" was not changed — requires edit access on Edit Units`, 'warning');
        } else {
            showToast(`Distribution recorded, but the ${kind} license of unit "${plainText(data.unitName)}" was not changed — check the unit in Check Data`, 'warning');
        }
    }
    // Moved to another unit or licence kind, or turned into stock-in: the old
    // unit still holds what this record gave it.
    if (prevDrove && licenseRelevantChange && !(txnType === 'OUT' && prevUnit.id === data.unitId
            && prevKind === _licenseKindForType(licenseType))) {
        _releaseDistributions([prevDriven]);
    }

    closeLicenseModal();
    populateLicenseTypeList();
    renderLicenseSummary();
    renderLicenseStockTable();
}

function closeLicenseModal() {
    document.getElementById('licenseModal').classList.remove('open');
}

// ---- Delete ----
function deleteLicenseStock(id) {
    if (!requireEdit('licenseStock')) return;
    const rec = globalLicenseStock.find(r => r.id === id);
    if (!rec) return;
    if (!confirm(`Delete license transaction "${rec.licenseType}" (${rec.date})?`)) return;

    const driven = _drivenBy(rec);
    globalLicenseStock = globalLicenseStock.filter(r => r.id !== id);
    saveLicenseStockLocal();
    cloudDeleteLicense(id);
    logEvent({
        action: 'delete',
        unitId: rec.unitId || '',
        unitName: `[License] ${rec.licenseType}`,
        before: rec.txnType === 'OUT' ? `Distribution → ${rec.unitName}` : 'Stock in'
    });
    showToast('License transaction deleted', 'success');
    _releaseDistributions([driven]);
    renderLicenseSummary();
    renderLicenseStockTable();
}

function deleteSelectedLicenseStock() {
    if (!requireEdit('licenseStock')) return;
    const count = selectedLicenseIds.size;
    if (count === 0) return;
    if (!confirm(`Delete ${count} selected license transaction(s)?`)) return;

    const idSet = new Set(selectedLicenseIds);
    const removed = globalLicenseStock.filter(r => idSet.has(r.id));
    const driven = removed.map(_drivenBy);
    globalLicenseStock = globalLicenseStock.filter(r => !idSet.has(r.id));
    saveLicenseStockLocal();
    removed.forEach(rec => cloudDeleteLicense(rec.id));
    removed.forEach(rec => logEvent({
        action: 'delete',
        unitId: rec.unitId || '',
        unitName: `[License] ${rec.licenseType}`,
        before: rec.txnType === 'OUT' ? `Distribution → ${rec.unitName}` : 'Stock in'
    }));
    showToast(`${count} license transaction(s) deleted`, 'success');
    _releaseDistributions(driven);
    renderLicenseSummary();
    renderLicenseStockTable();
}

// ---- Export report (CSV, opens in Excel via UTF-8 BOM) ----
function exportLicenseStockCSV() {
    if (!canCsv('export')) return;
    const rows = getFilteredLicenseStock();
    if (rows.length === 0) { showToast('No license data to export', 'warning'); return; }
    const headers = ['No', 'Date', 'Transaction', 'License Type', 'Quantity', 'Unit', 'Serial Number', 'Notes'];
    const dataRows = rows.map((r, i) => {
        const lu = r.txnType === 'OUT' ? liveUnitFor(r) : null;
        return [
            i + 1, r.date || '', r.txnType === 'OUT' ? 'Distribution' : 'In',
            r.licenseType || '', Number(r.qty) || 0,
            r.txnType === 'OUT' ? (lu ? (lu.name || '') : (r.unitName || '')) : '',
            r.txnType === 'OUT' ? (lu ? (lu.sn || '') : (r.sn || '')) : '',
            r.note || ''
        ];
    });
    const csv = [headers, ...dataRows].map(row =>
        row.map(csvCell).join(',')).join('\n');
    const blob = new Blob(['﻿' + csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `license_stock_${toISODate()}.csv`;
    a.click();
    URL.revokeObjectURL(url);
    showToast(`Exported ${rows.length} license transaction(s) to CSV`, 'success');
}

// ---- Import (CSV, append-only ledger) ----
function parseLicenseTxnType(s) {
    const v = (s || '').toString().trim().toLowerCase();
    if (['out', 'distribusi', 'keluar', 'distribution'].includes(v)) return 'OUT';
    return 'IN'; // masuk / in / empty default
}

function downloadLicenseTemplate() {
    if (!canCsv('export')) return;
    const headers = ['Date', 'Transaction', 'License Type', 'Quantity', 'Unit', 'Serial Number', 'Notes'];
    const sample = [
        ['2026-04-06', 'In', 'SF-RTK', '50', '', '', 'PO.GPA.2026.04.01343'],
        ['2026-05-11', 'Distribution', 'G5 Advance', '1', 'GGCH001G', '', 'Installed on unit']
    ];
    const csv = [headers, ...sample].map(row =>
        row.map(csvCell).join(',')).join('\n');
    const blob = new Blob(['﻿' + csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'license_stock_template.csv';
    a.click();
    URL.revokeObjectURL(url);
}

// A ledger date from a CSV, as YYYY-MM-DD. ISO passes through; D/M/YYYY
// (also with '-' or '.') is read DAY-first — how this team, and Excel in an
// Indonesian locale, writes dates. new Date('01/10/2025') would read it as
// January 10. Anything else is kept as typed, and the Status Unit column
// flags it "Tanggal tidak valid" instead of guessing.
function csvLicenseDate(raw) {
    const s = String(raw == null ? '' : raw).trim();
    if (!s) return '';
    if (isoDistributionDate(s)) return s;
    const m = /^(\d{1,2})[\/.\-](\d{1,2})[\/.\-](\d{4})$/.exec(s);
    if (m) {
        const iso = `${m[3]}-${m[2].padStart(2, '0')}-${m[1].padStart(2, '0')}`;
        if (isoDistributionDate(iso)) return iso;
    }
    return s;
}

// What makes two ledger rows the same transaction: day, direction, licence
// type, quantity, the unit (by serial number, else name) and the note.
function licenseTxnKey(r) {
    const who = String((r && (r.sn || r.unitName)) || '').trim().toLowerCase();
    return [r && r.date, r && r.txnType, licenseTypeKey(r && r.licenseType), Number(r && r.qty) || 0, who,
            String((r && r.note) || '').trim().toLowerCase()].join('|');
}

function handleLicenseCSVImport(file) {
    if (!canCsv('full')) return;
    if (!requireEdit('licenseStock')) return;
    showLoading(true);
    Papa.parse(file, {
        header: true,
        skipEmptyLines: true,
        complete: result => {
            const today = toISODate();
            const added = [];
            let rejected = 0;
            let heavyRejected = 0;
            let duplicates = 0;
            const importSync = { applied: 0, newer: 0, noAccess: 0 };
            // Re-importing the exported file (or importing it again because the
            // first try seemed to hang on a weak signal) doubled every IN and
            // OUT, and the Purchase Plan then subtracted the doubled stock and
            // told the team to buy too few. A row identical to one already in
            // the ledger is left out — counted, not just matched: two genuine
            // identical deliveries on one day are two rows, and re-importing
            // that file skips both, while importing it the first time adds both.
            const inLedger = new Map();
            globalLicenseStock.forEach(r => { const k = licenseTxnKey(r); inLedger.set(k, (inLedger.get(k) || 0) + 1); });

            result.data.forEach(row => {
                // Same spelling rule as the Distribusi form: 'sf-rtk' is SF-RTK.
                const licenseType = canonicalLicenseType((getValAny(row, ['Jenis Lisensi', 'License', 'License Type']) || '').toString());
                if (!licenseType) { rejected++; return; }

                const txnType = parseLicenseTxnType(getValAny(row, ['Jenis', 'Type', 'Transaksi', 'Transaction']));
                const qty = Math.max(1, parseInt(getValAny(row, ['Jumlah', 'Qty', 'Quantity']), 10) || 1);
                const date = csvLicenseDate(getValAny(row, ['Tanggal', 'Date'])) || today;
                const note = (getValAny(row, ['Catatan', 'Note', 'Notes', 'Remarks']) || '').toString().trim();

                const rec = {
                    id: generateLicenseId(),
                    date, txnType, licenseType, qty,
                    unitId: '', unitName: '', sn: '',
                    note,
                    createdAt: Date.now(), updatedAt: Date.now()
                };

                if (txnType === 'OUT') {
                    const snCsv = (getValAny(row, ['Serial Number', 'SN']) || '').toString().trim();
                    const nameCsv = (getValAny(row, ['Unit', 'Nickname']) || '').toString().trim();
                    // Matched against the agricultural units; a row whose SN or
                    // name belongs to a heavy unit is rejected outright rather
                    // than stored unlinked — an unlinked row still carries the
                    // SN, and liveUnitFor would resolve it back to that unit.
                    const bySn = u => (u.sn || '').toLowerCase() === snCsv.toLowerCase();
                    const byName = u => (u.name || '').toLowerCase() === nameCsv.toLowerCase();
                    let unit = null;
                    if (snCsv) {
                        unit = globalData.find(u => !isHeavy(u) && bySn(u));
                        if (!unit && globalData.some(u => isHeavy(u) && bySn(u))) { heavyRejected++; return; }
                    }
                    if (!unit && nameCsv) {
                        unit = globalData.find(u => !isHeavy(u) && byName(u));
                        if (!unit && globalData.some(u => isHeavy(u) && byName(u))) { heavyRejected++; return; }
                    }
                    if (unit) {
                        rec.unitId = unit.id; rec.unitName = unit.name || ''; rec.sn = unit.sn || '';
                    } else {
                        rec.unitName = nameCsv; rec.sn = snCsv;
                    }
                }
                const key = licenseTxnKey(rec);
                if (inLedger.get(key) > 0) { inLedger.set(key, inLedger.get(key) - 1); duplicates++; return; }
                added.push(rec);
            });

            if (added.length > 0) {
                globalLicenseStock.push(...added);
                saveLicenseStockLocal();
                // The unit licences this import writes, as they were before.
                // Filled in below; a refused batch puts them back too, or the
                // units would keep licences whose distributions never landed.
                const unitUndo = new Map();   // unitId -> { field: oldValue }
                if (!suppressCloudWrites && window.cloud?.isReady) {
                    // Same rollback as the implements import above: a refused
                    // batch must not keep rendering as if it had landed.
                    const addedIds = new Set(added.map(o => o.id));
                    window.cloud.saveLicenses(added).catch(err => {
                        globalLicenseStock = globalLicenseStock.filter(o => !addedIds.has(o.id));
                        saveLicenseStockLocal();
                        unitUndo.forEach((fields, unitId) => updateUnit(unitId, fields));
                        if (unitUndo.size) { renderEditTable(); updateDashboard(filteredData = applyFilterLogic()); }
                        renderLicenseSummary();
                        renderLicenseStockTable();
                        cloudWriteFailed(err, {
                            what: `import ${added.length} license transaction(s)`,
                            label: '[License] Import CSV',
                            resync: resyncLicenses
                        });
                    });
                }
                logEvent({ action: 'add', unitName: '[License] Import CSV', after: `${added.length} transaction(s)` });
                // Imported distributions go straight to their units, like the
                // Distribusi form — but only where an imported row is now the
                // LATEST for that unit licence and nothing newer is on the
                // unit. Rows that were already out of sync before the import
                // are left for the Sync preview: nobody has looked at them.
                const addedIds = new Set(added.map(o => o.id));
                const importRows = licenseSyncPlan().rows.filter(r => addedIds.has(r.rec.id));
                const todo = importRows.filter(r => r.status === 'update');
                importSync.newer = importRows.filter(r => r.status === 'newer').length;
                if (todo.length && hasAccess('editUnits', 'edit')) {
                    todo.forEach(r => {
                        const u = globalData.find(x => x.id === r.unit.id);
                        if (!u) return;
                        const prev = unitUndo.get(u.id) || {};
                        Object.keys(r.fields).forEach(f => { if (!(f in prev)) prev[f] = u[f] != null ? u[f] : ''; });
                        unitUndo.set(u.id, prev);
                    });
                    importSync.applied = _applyLicenseSync(todo.map(r => r.key));
                } else if (todo.length) {
                    importSync.noAccess = todo.length;
                }
                populateLicenseTypeList();
                renderLicenseSummary();
                renderLicenseStockTable();
            }

            showLoading(false);
            const msg = `License import: ${added.length} added` + (rejected ? `, ${rejected} skipped (empty license type)` : '')
                + (duplicates ? `, ${duplicates} skipped (already in the ledger)` : '')
                + (heavyRejected ? `, ${heavyRejected} skipped (Heavy Equipment unit — SF/G5 licenses are only for ${UNIT_GROUPS.tractor.shortLabel})` : '')
                + (importSync.applied ? ` · licenses of ${importSync.applied} unit(s) updated too` : '')
                + (importSync.newer ? ` · ${importSync.newer} unit(s) not changed (valid for longer)` : '')
                + (importSync.noAccess ? ` · ${importSync.noAccess} unit license(s) not applied yet (Unit edit access required)` : '');
            showToast(msg, added.length ? 'success' : 'warning');
        },
        error: err => {
            showToast('Failed to read CSV: ' + err.message, 'error');
            showLoading(false);
        }
    });
}

