function addDamageComponent(event) {
    if (event) event.preventDefault();
    if (!requireEdit('damage')) return;
    const input = document.getElementById('newComponentName');
    const name = (input.value || '').trim();
    if (!name) { showToast('Enter a component name', 'warning'); return; }
    const exists = damageComponents.some(c => (c.name || '').toLowerCase() === name.toLowerCase());
    if (exists) { showToast(`Component "${name}" already exists`, 'warning'); return; }
    // Heavy components are built in and keyed to heavy fields; a custom one of
    // the same name would put 'Camera AI' in front of every tractor.
    if (heavyComponentField(name)) {
        showToast(`"${name}" is already built in for Heavy Equipment — no need to add it`, 'warning');
        return;
    }

    const comp = {
        id: `dcmp_${Date.now()}_${Math.random().toString(36).slice(2, 6)}`,
        name,
        // Custom components aren't tied to a unit status column; a damage on
        // them flips the unit's overall status instead.
        unitField: DAMAGE_COMPONENT_FIELD[name] || '',
        createdAt: Date.now()
    };
    input.value = '';
    cloudWrite(
        { action: 'add', unitName: '-', field: 'damage component', after: name },
        cloudCall('saveDamageComponent', comp),
        `Component "${name}" added`,
        err => {
        console.error('[damage-components] save failed:', err);
        const code = (err && err.code) || 'unknown';
        if (code === 'permission-denied') {
            showToast('Firestore rules are blocking damageComponents — see the guide', 'error');
            showDamageComponentRulesBanner();
        } else {
            showToast(`Failed to save component (${code})`, 'error');
        }
        }
    );
}

function deleteDamageComponent(id) {
    if (!requireEdit('damage')) return;
    const comp = damageComponents.find(c => c.id === id);
    if (!comp) return;
    const inUse = globalDamages.filter(d => d.component === comp.name).length;
    const prompt = inUse > 0
        ? `Delete component "${comp.name}"?\n${inUse} damage record(s) use it (existing data stays saved).`
        : `Delete component "${comp.name}"?`;
    if (!confirm(prompt)) return;
    cloudWrite(
        { action: 'delete', unitName: '-', field: 'damage component', before: comp.name },
        cloudCall('deleteDamageComponent', id),
        `Component "${comp.name}" deleted`,
        err => {
        console.error('[damage-components] delete failed:', err);
        const code = (err && err.code) || 'unknown';
        if (code === 'permission-denied') {
            showToast('Firestore rules are blocking damageComponents — see the guide', 'error');
            showDamageComponentRulesBanner();
        } else {
            showToast(`Failed to delete component (${code})`, 'error');
        }
        }
    );
}

function initCloudSync() {
    if (cloudInitialized) return;
    if (!window.cloud?.isReady) return;
    cloudInitialized = true;

    console.log('[cloud] initializing sync...');

    // Only the owner should bulk-migrate local→cloud. Viewers and pending
    // users must never push their (possibly stale) local data up.
    const canMigrate = currentUserDoc && currentUserDoc.role === 'owner';

    const startSubscriptions = () => {
        cloudUnitsUnsub = window.cloud.subscribeUnits(applyCloudUnitsSnapshot, err => {
            const lbl = document.getElementById('connectionLabel');
            if (lbl) lbl.textContent = 'Cloud offline';
        }, scopeQueryGroup());
        // Implements and licences are agricultural; a heavy-equipment-only
        // account does not read them (the rules refuse it anyway).
        if (unitScopeAllows('tractor')) cloudImplUnsub = window.cloud.subscribeImplements(applyCloudImplementsSnapshot, err => {
            console.warn('[cloud] implements offline');
        });
        if (window.cloud.subscribeDamages) {
            cloudDamageUnsub = window.cloud.subscribeDamages((list, queued) => { setQueued('damages', queued); applyCloudDamagesSnapshot(list); }, err => {
                console.warn('[cloud] damage records offline:', err && err.code);
                if (err && err.code === 'permission-denied') {
                    showDamageRulesBanner();
                    showToast('Damage is blocked by Firestore rules — see the Damage panel', 'warning');
                }
            }, scopeQueryGroup());
        }
        if (window.cloud.subscribeLicenses && unitScopeAllows('tractor')) {
            cloudLicenseUnsub = window.cloud.subscribeLicenses(applyCloudLicenseSnapshot, err => {
                console.warn('[cloud] license stock offline:', err && err.code);
                if (err && err.code === 'permission-denied') {
                    showLicenseRulesBanner();
                    showToast('License Stock is blocked by Firestore rules — see the License Stock panel', 'warning');
                }
            });
        }
        // History is deliberately NOT subscribed here. See
        // startHistorySubscription() for why.
        if (window.cloud.subscribeDamageComponents) {
            cloudDamageComponentsUnsub = window.cloud.subscribeDamageComponents(
                applyCloudDamageComponentsSnapshot,
                err => {
                    console.warn('[cloud] damageComponents offline:', err && err.code);
                    if (err && err.code === 'permission-denied') {
                        showDamageComponentRulesBanner();
                    }
                }
            );
        }
        if (window.cloud.subscribeDevices) {
            cloudDevicesUnsub = window.cloud.subscribeDevices(
                applyCloudDevicesSnapshot,
                err => {
                    console.warn('[cloud] devices offline:', err && err.code);
                    if (err && err.code === 'permission-denied') showWarehouseRulesBanner();
                }
            );
        }
        if (window.cloud.subscribeStockItems) {
            cloudStockUnsub = window.cloud.subscribeStockItems(
                applyCloudStockSnapshot,
                err => {
                    console.warn('[cloud] stockItems offline:', err && err.code);
                    if (err && err.code === 'permission-denied') showWarehouseRulesBanner();
                }
            );
        }
        if (window.cloud.subscribeVehicles) {
            cloudVehiclesUnsub = window.cloud.subscribeVehicles(
                applyCloudVehiclesSnapshot,
                err => {
                    console.warn('[cloud] vehicles offline:', err && err.code);
                    if (err && err.code === 'permission-denied') showWarehouseRulesBanner();
                }
            );
        }
        if (window.cloud.subscribeFuelLogs) {
            cloudFuelUnsub = window.cloud.subscribeFuelLogs(
                applyCloudFuelSnapshot,
                err => {
                    console.warn('[cloud] fuelLogs offline:', err && err.code);
                    if (err && err.code === 'permission-denied') showWarehouseRulesBanner();
                }
            );
        }
        if (window.cloud.subscribeTeamMembers) {
            cloudTeamMembersUnsub = window.cloud.subscribeTeamMembers(
                applyCloudTeamMembersSnapshot,
                err => {
                    console.warn('[cloud] teamMembers offline:', err && err.code);
                    if (err && err.code === 'permission-denied') showTeamRulesBanner();
                }
            );
        }
        if (window.cloud.subscribeShifts) startShiftsSubscription();
        // Reports and leave are read only by the areas firestore.rules lets
        // read them — subscribing without the right would just fail and put
        // up a "rules not published" banner that is not true.
        const canReadLogs = ['teamLog', 'teamLogApprove', 'leader'].some(a => hasAccess(a, 'view'));
        if (window.cloud.subscribeWorkLogs && canReadLogs) {
            cloudWorkLogsUnsub = window.cloud.subscribeWorkLogs(
                (list, queued) => { setQueued('workLogs', queued); applyCloudWorkLogsSnapshot(list); },
                err => {
                    console.warn('[cloud] workLogs offline:', err && err.code);
                    if (err && err.code === 'permission-denied') showTeamRulesBanner();
                }
            );
        }
        // Checks are read by whoever checks, approves, or reads the inbox —
        // the same set firestore.rules lets read them.
        const canReadChecks = ['inspection', 'inspectionApprove', 'leader'].some(a => hasAccess(a, 'view')) && unitScopeAllows('heavy');
        if (window.cloud.subscribeInspections && canReadChecks) {
            cloudInspectionsUnsub = window.cloud.subscribeInspections(
                applyCloudInspectionsSnapshot,
                err => console.warn('[cloud] inspections offline:', err && err.code)
            );
            cloudInspectionPlansUnsub = window.cloud.subscribeInspectionPlans(
                applyCloudInspectionPlansSnapshot,
                err => console.warn('[cloud] inspectionPlans offline:', err && err.code)
            );
        }
        if (window.cloud.subscribeLeaveRequests && (canReadLogs || hasAccess('teamShift', 'view'))) {
            cloudLeaveUnsub = window.cloud.subscribeLeaveRequests(
                (list, queued) => { setQueued('leaveRequests', queued); applyCloudLeaveSnapshot(list); },
                err => {
                    console.warn('[cloud] leaveRequests offline:', err && err.code);
                    if (err && err.code === 'permission-denied') showTeamRulesBanner();
                }
            );
        }
        if (window.cloud.subscribeLicenseRequirements && unitScopeAllows('tractor')) {
            cloudLicenseReqUnsub = window.cloud.subscribeLicenseRequirements(
                applyLicenseRequirementsSnapshot,
                err => console.warn('[cloud] licenseRequirements offline:', err && err.code)
            );
        }
        if (window.cloud.subscribeMasterLists) {
            cloudMasterListsUnsub = window.cloud.subscribeMasterLists(
                applyMasterListsSnapshot,
                err => console.warn('[cloud] masterLists offline:', err && err.code)
            );
        }
        if (window.cloud.subscribeUserCategories) {
            cloudUserCategoriesUnsub = window.cloud.subscribeUserCategories(
                applyCloudUserCategoriesSnapshot,
                err => {
                    console.warn('[cloud] userCategories offline:', err && err.code);
                    // Permission-denied here means the Firestore rules are
                    // missing — the Manage Categories modal (if open) should
                    // show the banner so the owner knows what to paste.
                    if (err && err.code === 'permission-denied') {
                        showCategoryRulesBanner();
                    }
                }
            );
        }
    };

    if (canMigrate) {
        migrateLocalToCloudIfNeeded().finally(startSubscriptions);
    } else {
        // Non-owners: never write, only read. Disable the local-first guard
        // so the cloud snapshot is the source of truth.
        _firstUnitsSnapshot = false;
        _firstImplSnapshot = false;
        _firstDamageSnapshot = false;
        _firstLicenseSnapshot = false;
        startSubscriptions();
    }
}

// ============================================================
// AUTHENTICATION & ROLE GATING
// ============================================================

function setupAuth() {
    if (authInitialized) return;
    authInitialized = true;
    if (!window.cloud?.onAuthChange) return;

    window.cloud.onAuthChange(async user => {
        if (!user) {
            // Signed out — show login, tear down sync, clear in-memory data
            currentUser = null;
            currentUserDoc = null;
            applyScopeChange();
            clearSessionClock();
            stopWatchingOwnUserDoc();
            tearDownCloudSync();
            showAuthGate('signin');
            return;
        }

        // Enforce the daily session window on the persisted login.
        if (!checkDailySession()) return;

        currentUser = user;
        // Before anything in this session logs or renders: a shared browser may
        // still hold unsynced audit rows belonging to whoever signed in last.
        pruneForeignLocalAudit(user.uid);

        // Look up (or create) the Firestore profile document for this user.
        let profile;
        try {
            profile = await window.cloud.getUserDoc(user.uid);
            if (!profile) {
                profile = await window.cloud.createUserDoc(user);
            } else if ((window.cloud.isOwnerAccount ? window.cloud.isOwnerAccount(user) : window.cloud.isOwnerEmail(user.email)) &&
                       (profile.role !== 'owner' || profile.status !== 'active')) {
                // Owner allowlist takes precedence — repair the doc.
                profile = await window.cloud.ensureOwnerDoc(user);
            }
        } catch (e) {
            console.error('[auth] could not load/create user doc:', e);
            showAuthError('signInError', 'Could not load your account profile. Please try again.');
            try { await window.cloud.signOutUser(); } catch (_) {}
            return;
        }

        currentUserDoc = profile;

        // Pending users: park them on the waiting screen. Waiting for approval
        // is not a session, so stop the 24h clock — otherwise approval at hour
        // 23 would hand the user a single hour instead of a full day.
        if (profile.status !== 'active') {
            clearSessionClock();
            showPendingGate(user.email);
            return;
        }

        // A login RESTORED on this device (reload, reopened phone) does not get
        // to take the account's session slot back: only a sign-in the person
        // just typed does. Otherwise yesterday's phone, reopened, silently
        // kicked today's laptop — and a phone the owner signed out
        // ("Keluarkan") walked straight back in.
        const held = profile.activeSession;
        const mine = mySessionId();
        const explicit = _explicitSignIn;
        _explicitSignIn = false;
        if (!explicit && held && held.id && held.id !== mine) {
            handleSessionTakenOver(held);
            return;
        }

        // Active user — show app, gate UI by role, start cloud sync.
        if (!localStorage.getItem(SESSION_START_KEY)) startSessionClock();
        hideAuthGates();
        applyRoleGating();
        renderUserPill();
        // Claim the slot WITHOUT waiting: Firestore settles the write only
        // once the server acknowledges it, so awaiting here meant a device
        // opened offline (or on a weak signal) never started cloud sync at
        // all. The local write lands in the cache at once, so the watcher
        // below already sees this device's id.
        if (!held || held.id !== mine) claimActiveSession(user.uid, held);
        if (await protectDeviceForScope(user.uid)) return;
        watchOwnUserDoc(user.uid);
        maybeInitCloudSync();
    });
}

function tearDownCloudSync() {
    _loadedParts.clear();
    // Photo caches belong to the session: the next account on this browser,
    // or this one later, must fetch what is on the server now.
    try { _wlPhotoCache.clear(); _leaveDocCache.clear(); _dmgPhotoCache.clear(); _dmgAfterCache.clear(); _fuelPhotoCache.clear(); } catch (_) {}
    if (cloudUnitsUnsub) { try { cloudUnitsUnsub(); } catch (_) {} cloudUnitsUnsub = null; }
    if (cloudImplUnsub) { try { cloudImplUnsub(); } catch (_) {} cloudImplUnsub = null; }
    if (cloudDamageUnsub) { try { cloudDamageUnsub(); } catch (_) {} cloudDamageUnsub = null; }
    if (cloudLicenseUnsub) { try { cloudLicenseUnsub(); } catch (_) {} cloudLicenseUnsub = null; }
    if (cloudUsersUnsub) { try { cloudUsersUnsub(); } catch (_) {} cloudUsersUnsub = null; }
    if (cloudHistoryUnsub) { try { cloudHistoryUnsub(); } catch (_) {} cloudHistoryUnsub = null; }
    // Claims belong to the session that made them; a new sign-in must not
    // inherit them and warn about its own writes.
    _shiftPendingWrites.clear();
    if (cloudUserCategoriesUnsub) { try { cloudUserCategoriesUnsub(); } catch (_) {} cloudUserCategoriesUnsub = null; }
    if (cloudMasterListsUnsub) { try { cloudMasterListsUnsub(); } catch (_) {} cloudMasterListsUnsub = null; }
    if (cloudLicenseReqUnsub) { try { cloudLicenseReqUnsub(); } catch (_) {} cloudLicenseReqUnsub = null; }
    // What was typed belongs to the account that typed it.
    if (typeof clearUnsent === 'function') clearUnsent();
    licenseRequirements = [];
    masterLists = { site: [], brand: [], heavyBrand: [], company: [] };
    if (cloudDamageComponentsUnsub) { try { cloudDamageComponentsUnsub(); } catch (_) {} cloudDamageComponentsUnsub = null; }
    if (cloudDevicesUnsub) { try { cloudDevicesUnsub(); } catch (_) {} cloudDevicesUnsub = null; }
    if (cloudStockUnsub) { try { cloudStockUnsub(); } catch (_) {} cloudStockUnsub = null; }
    warehouseDevices = [];
    stockLedger = [];
    if (cloudVehiclesUnsub) { try { cloudVehiclesUnsub(); } catch (_) {} cloudVehiclesUnsub = null; }
    if (cloudFuelUnsub) { try { cloudFuelUnsub(); } catch (_) {} cloudFuelUnsub = null; }
    vehicles = [];
    fuelLogs = [];
    if (cloudTeamMembersUnsub) { try { cloudTeamMembersUnsub(); } catch (_) {} cloudTeamMembersUnsub = null; }
    if (cloudShiftsUnsub) { try { cloudShiftsUnsub(); } catch (_) {} cloudShiftsUnsub = null; }
    _shiftWindowStart = '';
    if (cloudWorkLogsUnsub) { try { cloudWorkLogsUnsub(); } catch (_) {} cloudWorkLogsUnsub = null; }
    if (cloudLeaveUnsub) { try { cloudLeaveUnsub(); } catch (_) {} cloudLeaveUnsub = null; }
    if (cloudInspectionsUnsub) { try { cloudInspectionsUnsub(); } catch (_) {} cloudInspectionsUnsub = null; }
    if (cloudInspectionPlansUnsub) { try { cloudInspectionPlansUnsub(); } catch (_) {} cloudInspectionPlansUnsub = null; }
    inspections = [];
    insQueuedIds = new Set();
    Object.keys(_queued).forEach(k => { _queued[k] = new Set(); });
    renderQueuedPill();
    inspectionPlans = [];
    _insPhotoCache.clear();
    teamMembers = [];
    teamShifts = [];
    workLogs = [];
    leaveRequests = [];
    _leaveDocCache.clear();
    cloudHistory = [];
    userCategories = [];
    _firstUserCategoriesSnapshot = true;
    damageComponents = [];
    _firstDamageComponentsSnapshot = true;
    // Entries queued but not yet pushed still carry the outgoing user's
    // actorUid. Firestore requires actorUid == request.auth.uid, so sending
    // them after the next person signs in gets the whole batch refused — and
    // the outgoing user's real actions vanish along with it. Drop them here;
    // logEvent has already written them to the local cache.
    if (_historyFlushTimer) { clearTimeout(_historyFlushTimer); _historyFlushTimer = null; }
    _historyPushQueue.length = 0;
    _historyRetryDelay = 0;
    cloudInitialized = false;
}

// The local audit cache lives in the browser, and getAuditLog() merges it into
// whatever the signed-in user sees. On a shared device that meant the next
// person read the previous person's unsynced rows, rendered under the previous
// person's name and indistinguishable from real ones. Anything belonging to
// somebody else is dropped as soon as we know who is signing in; the user's
// own rows survive a sign-out and come back.
function pruneForeignLocalAudit(uid) {
    try {
        const log = JSON.parse(localStorage.getItem(AUDIT_LOG_KEY) || '[]');
        const mine = log.filter(e => e && e.actorUid === uid);
        if (mine.length !== log.length) {
            localStorage.setItem(AUDIT_LOG_KEY, JSON.stringify(mine));
            console.log(`[audit] dropped ${log.length - mine.length} cached entries from another account`);
        }
    } catch (e) { /* ignore */ }
}

function showAuthGate(tab) {
    releaseAuthBusy();
    document.getElementById('authGate').style.display = 'flex';
    document.getElementById('pendingGate').style.display = 'none';
    document.body.classList.add('auth-blocked');
    if (tab) switchAuthTab(tab);
}

function showPendingGate(email) {
    releaseAuthBusy();
    document.getElementById('authGate').style.display = 'none';
    const el = document.getElementById('pendingGate');
    el.style.display = 'flex';
    document.body.classList.add('auth-blocked');
    const emailEl = document.getElementById('pendingEmail');
    if (emailEl) emailEl.textContent = email || '';
}

function hideAuthGates() {
    releaseAuthBusy();
    document.getElementById('authGate').style.display = 'none';
    document.getElementById('pendingGate').style.display = 'none';
    document.body.classList.remove('auth-blocked');
}

function switchAuthTab(tab) {
    const isSignIn = tab === 'signin';
    [['authTabSignIn', isSignIn], ['authTabSignUp', !isSignIn]].forEach(([id, on]) => {
        const b = document.getElementById(id);
        b.classList.toggle('active', on);
        b.setAttribute('aria-pressed', on ? 'true' : 'false');
    });
    const title = document.getElementById('authTitle');
    if (title) title.textContent = isSignIn ? 'Sign in' : 'Create account';
    const sub = document.getElementById('authSub');
    if (sub) sub.textContent = isSignIn ? 'Use the email your account was created with.' : 'Use your work email. The owner approves new accounts.';
    document.getElementById('signInForm').style.display = isSignIn ? '' : 'none';
    document.getElementById('signUpForm').style.display = isSignIn ? 'none' : '';
    showAuthError('signInError', '');
    showAuthError('signUpError', '');
}

function showAuthError(id, msg) {
    const el = document.getElementById(id);
    if (!el) return;
    el.textContent = msg || '';
    el.style.display = msg ? 'block' : 'none';
}

function friendlyAuthError(err) {
    const code = (err && err.code) || '';
    const map = {
        'auth/invalid-email': 'That email address is not valid.',
        'auth/user-not-found': 'No account found for that email.',
        'auth/wrong-password': 'Incorrect password.',
        'auth/invalid-credential': 'Email or password is incorrect.',
        'auth/email-already-in-use': 'An account with that email already exists.',
        'auth/weak-password': 'Password is too weak (min 6 characters).',
        'auth/network-request-failed': 'Network error — check your connection.',
        'auth/too-many-requests': 'Too many failed attempts — this account is locked for a while. Wait 15–30 minutes, or use "Forgot password?" to reset it.',
        'auth/user-disabled': 'This account has been disabled. Ask the owner to enable it.',
        'auth/missing-password': 'Enter your password.',
        'auth/invalid-login-credentials': 'Email or password is incorrect.'
    };
    return map[code] || (err && err.message) || 'Authentication failed.';
}

// "The password is right but it won't let me in" is nearly always the text
// in the box not being what the person thinks: a capital letter the phone
// added, a space a keyboard or password manager appended, Caps Lock. Say
// which, instead of only "incorrect".
function signInHint(email, password) {
    const tips = [];
    if (/^\s|\s$/.test(password)) tips.push('your password starts or ends with a space');
    if (/^[A-Z][^A-Z]*$/.test(password)) tips.push('only the first letter is a capital — the phone may have added it');
    if (password && password === password.toUpperCase() && /[A-Z]/.test(password) && !/[a-z]/.test(password)) tips.push('it is all capitals — is Caps Lock on?');
    if (email !== email.toLowerCase()) tips.push('the email has capital letters (that is fine, but check the spelling)');
    return tips.length ? ` Check: ${tips.join('; ')}. Tap "Show" to see what you typed.` : ' Tap "Show" to see what you typed, or use "Forgot password?".';
}

function togglePasswordVisibility(inputId, btn) {
    const el = document.getElementById(inputId);
    if (!el) return;
    const show = el.type === 'password';
    el.type = show ? 'text' : 'password';
    if (btn) {
        btn.setAttribute('aria-pressed', show ? 'true' : 'false');
        btn.setAttribute('aria-label', show ? 'Hide password' : 'Show password');
        btn.textContent = show ? 'Hide' : 'Show';
    }
}

async function handleForgotPassword() {
    showAuthError('signInError', '');
    const email = (document.getElementById('signInEmail').value || '').trim();
    if (!email) { showAuthError('signInError', 'Type your email above first, then tap "Forgot password?".'); document.getElementById('signInEmail').focus(); return; }
    if (!window.cloud?.sendPasswordReset) { showAuthError('signInError', STALE_CLIENT_MSG); return; }
    try {
        showLoading(true);
        await window.cloud.sendPasswordReset(email);
        showAuthNotice(`If an account exists for ${email}, a password-reset link has been sent. Check the inbox and the spam folder.`);
    } catch (err) {
        // Not revealing whether an address has an account: only real
        // problems (bad address, network, rate limit) are reported.
        if (err && (err.code === 'auth/user-not-found' || err.code === 'auth/invalid-credential')) {
            showAuthNotice(`If an account exists for ${email}, a password-reset link has been sent. Check the inbox and the spam folder.`);
        } else {
            showAuthError('signInError', friendlyAuthError(err));
        }
    } finally {
        showLoading(false);
    }
}

function showAuthNotice(msg) {
    const el = document.getElementById('signInNotice');
    if (!el) return;
    el.textContent = msg || '';
    el.style.display = msg ? '' : 'none';
}

// ---- Daily session expiry (re-login required after 24h) ----
const SESSION_MAX_MS = 24 * 60 * 60 * 1000; // 24 hours
const SESSION_START_KEY = 'tractorSessionStart';
let _sessionTimer = null;

function startSessionClock() {
    localStorage.setItem(SESSION_START_KEY, String(Date.now()));
}

// ============================================================
// ONE ACTIVE SESSION PER ACCOUNT
// ------------------------------------------------------------
// The newest sign-in wins: it writes its own id into the account document,
// and every other device — which is watching that document — sees an id that
// is not its own and signs itself out. Newest-wins rather than first-wins on
// purpose: a tab closed without signing out, or a lost phone, would otherwise
// hold the account hostage until the session aged out.
//
// The id lives in localStorage, which is shared between tabs of the same
// browser, so several tabs on one device count as one session and do not
// fight each other.
//
// This is enforced by the app, not by the database: it stops an account being
// shared across two phones, but it is not a defence against someone editing
// the client. Hard enforcement would need a server.
// ============================================================

const SESSION_ID_KEY = 'tractorSessionId';
let _mySessionId = '';
let _userDocUnsub = null;
let _sessionTakenOver = false;
let _explicitSignIn = false;   // set by the sign-in / sign-up forms
// The session id the server still holds after this device's claim was
// refused. Not a takeover: it was there before this sign-in.
let _claimRefusedId = null;

function mySessionId() {
    if (_mySessionId) return _mySessionId;
    let id = '';
    try { id = localStorage.getItem(SESSION_ID_KEY) || ''; } catch (e) { /* private mode */ }
    if (!id) {
        id = 's_' + Date.now() + '_' + Math.random().toString(36).slice(2, 10);
        try { localStorage.setItem(SESSION_ID_KEY, id); } catch (e) { /* ignore */ }
    }
    _mySessionId = id;
    return id;
}

// Coarse, human-readable label so the audit trail says something useful.
// Deliberately not a fingerprint.
function deviceLabel() {
    const ua = navigator.userAgent || '';
    const os = /Android/i.test(ua) ? 'Android'
        : /iPhone|iPad|iPod/i.test(ua) ? 'iOS'
        : /Windows/i.test(ua) ? 'Windows'
        : /Mac OS X/i.test(ua) ? 'macOS'
        : /Linux/i.test(ua) ? 'Linux' : 'Perangkat lain';
    const browser = /Edg\//.test(ua) ? 'Edge'
        : /OPR\//.test(ua) ? 'Opera'
        : /Chrome\//.test(ua) ? 'Chrome'
        : /Safari\//.test(ua) ? 'Safari'
        : /Firefox\//.test(ua) ? 'Firefox' : 'Browser';
    return `${browser} · ${os}`;
}

// `held` is the session the account document held when this sign-in began.
async function claimActiveSession(uid, held) {
    if (!window.cloud?.claimSession) return;
    _claimRefusedId = null;
    try {
        await window.cloud.claimSession(uid, {
            id: mySessionId(),
            startedAt: Date.now(),
            device: deviceLabel()
        });
    } catch (e) {
        // Sign-in still works; the single-session rule just is not enforced
        // for this device.
        console.warn('[session] could not claim session:', e && e.code);
        if (e && e.code === 'permission-denied') {
            // The refused write is rolled back in the cache, so the watcher
            // is about to see the old id again. Without this it read that as
            // a takeover and signed out a sign-in that had just succeeded.
            // Set before the watcher hears of it: Firestore settles the write
            // promise ahead of the listener events for the same rollback.
            if (currentUser && currentUser.uid === uid) _claimRefusedId = (held && held.id) || null;
            showToast(claimRefusedMessage(held), 'warning');
        }
    }
}

// Blame the published rules only when nothing shows they ever accepted a
// claim. A live (not revoked) session id on the account was written by one of
// its own sign-ins, so the rules took that claim — re-publishing them would
// change nothing, and telling someone to would send them looking in the wrong
// place.
function claimRefusedMessage(held) {
    const claimedBefore = !!(held && held.id && !String(held.id).startsWith('revoked_'));
    if (claimedBefore) return 'This device could not take over the session for this account — another device may still be signed in';
    return isOwner()
        ? 'Single-session rule is not active yet — re-publish firestore.rules'
        : 'Single-session rule is not active yet — ask the Super Admin to re-publish firestore.rules';
}

// Watch this user's own document: session takeovers, plus role and access
// changes, now reach them without a reload.
function watchOwnUserDoc(uid) {
    if (_userDocUnsub || !window.cloud?.subscribeUserDoc) return;
    _userDocUnsub = window.cloud.subscribeUserDoc(uid, doc => {
        if (_sessionTakenOver) return;
        // The account was removed or rejected while this device had it open:
        // stop showing the data it already loaded.
        if (!doc) { handleSessionTakenOver({ id: 'revoked_deleted' }); return; }

        const active = doc.activeSession;
        if (active && active.id && active.id !== mySessionId() && active.id !== _claimRefusedId) {
            handleSessionTakenOver(active);
            return;
        }

        // Role/status/access changed under us — apply it live.
        const before = currentUserDoc || {};
        currentUserDoc = doc;
        if (doc.status !== 'active') {
            showPendingGate(doc.email || '');
            return;
        }
        if (JSON.stringify(before.access) !== JSON.stringify(doc.access) || before.role !== doc.role) {
            applyRoleGating();
            renderUserPill();
            if (isUnitScoped()) protectDeviceForScope(uid);
            // Which collections this account may read changed: subscribe again.
            if (cloudInitialized) { tearDownCloudSync(); cloudInitialized = false; maybeInitCloudSync(); }
            // The teardown dropped the history stream an open History needs.
            const hm = document.getElementById('historyModal');
            if (hm && hm.classList.contains('open') && hasAccess('history', 'view')) startHistorySubscription();
            showToast('Your access rights were updated by an admin', 'info');
        }
    }, err => console.warn('[session] user doc watch failed:', err && err.code));
}

function stopWatchingOwnUserDoc() {
    if (_userDocUnsub) { try { _userDocUnsub(); } catch (_) {} _userDocUnsub = null; }
    _claimRefusedId = null;
}

async function handleSessionTakenOver(active) {
    if (_sessionTakenOver) return;
    _sessionTakenOver = true;
    stopWatchingOwnUserDoc();
    tearDownCloudSync();
    clearSessionClock();

    const revoked = String(active.id || '').startsWith('revoked_');
    const where = active.device ? ` (${active.device})` : '';
    const msg = revoked
        ? 'Your session was ended by an admin. Please sign in again.'
        : `You were signed out because this account was opened on another device${where}.`;

    try { await window.cloud.signOutUser(); } catch (e) { /* gate still shows below */ }
    currentUser = null;
    currentUserDoc = null;
    applyScopeChange();
    showAuthGate('signin');
    showAuthError('signInError', msg);
    // Cleared so the next sign-in on this device is not treated as a takeover.
    _sessionTakenOver = false;
}

function clearSessionClock() {
    localStorage.removeItem(SESSION_START_KEY);
    if (_sessionTimer) { clearTimeout(_sessionTimer); _sessionTimer = null; }
    if (_sessionWarnTimer) { clearTimeout(_sessionWarnTimer); _sessionWarnTimer = null; }
    if (_expiryWatch) { clearInterval(_expiryWatch); _expiryWatch = null; }
    _expiryDue = false;
    _sessionWarnSnoozed = false;
    hideSessionBanner();
}

// ---- Warning before, and no sign-out in the middle of something ----
// The day's session used to end without a word, at whatever hour yesterday's
// sign-in had been — often first thing in the field. On return from the
// camera app the sign-in screen covered a half-filled inspection, and with
// no signal there was no signing in again: the offline queue built for that
// place could not be used. Now there is a warning half an hour ahead, and an
// ended session waits for the open form to be closed and for a signal.
const SESSION_WARN_MS = 30 * 60 * 1000;
let _sessionWarnTimer = null;
let _expiryWatch = null;
let _expiryDue = false;

function _sessionEndsAt() {
    const start = parseInt(localStorage.getItem(SESSION_START_KEY), 10);
    return start && !isNaN(start) ? start + SESSION_MAX_MS : 0;
}

let _sessionWarnSnoozed = false;   // "Later" on the early warning

function showSessionBanner(kind) {
    if (kind === 'soon' && _sessionWarnSnoozed) return;
    let bar = document.getElementById('sessionBanner');
    if (!bar) {
        bar = document.createElement('div');
        bar.id = 'sessionBanner';
        bar.className = 'session-banner';
        bar.setAttribute('role', 'status');
        document.body.appendChild(bar);
    }
    const end = _sessionEndsAt();
    const hhmm = end ? new Date(end).toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' }) : '';
    const text = kind === 'ended'
        ? (navigator.onLine
            ? 'Your daily session has ended. Save or close what you are working on — you will then be asked to sign in again.'
            : 'Your daily session has ended. Keep working — you will be asked to sign in again once you have signal and have closed the open form.')
        : `Your daily session ends at ${hhmm}. Sign in again now while you have signal, so it does not end in the field.`;
    bar.dataset.kind = kind;
    bar.innerHTML = `<i class="fas fa-clock"></i><span>${escapeHtml(text)}</span>`
        + '<button type="button" class="btn btn-primary btn-sm" onclick="renewSessionNow()">Sign in again</button>'
        + (kind === 'soon' ? '<button type="button" class="btn btn-secondary btn-sm" onclick="snoozeSessionBanner()">Later</button>' : '');
}
function snoozeSessionBanner() { _sessionWarnSnoozed = true; hideSessionBanner(); }
function hideSessionBanner() {
    const bar = document.getElementById('sessionBanner');
    if (bar) bar.remove();
}

// "Sign in again" from the banner: a fresh sign-in starts a fresh 24h day.
async function renewSessionNow() {
    if (!navigator.onLine) { showToast('No signal — signing in needs a connection. Try again when you have signal.', 'warning'); return; }
    if (userIsBusy() && !confirm('A form is still open. Sign out now to sign in again? Anything not saved yet will be lost.')) return;
    const email = (currentUser && currentUser.email) || '';
    try { await window.cloud.signOutUser(); } catch (_) {}
    const el = document.getElementById('signInEmail');
    if (el && email) el.value = email;
}

// The 24 hours are up: sign out now, or as soon as nothing is open and there
// is a signal to sign back in with. Returns true when it had to wait.
function requestExpiry() {
    if (!userIsBusy() && navigator.onLine) { expireSession(); return false; }
    _expiryDue = true;
    showSessionBanner('ended');
    if (!_expiryWatch) {
        _expiryWatch = setInterval(() => {
            if (_expiryDue && !userIsBusy() && navigator.onLine) {
                clearInterval(_expiryWatch); _expiryWatch = null;
                expireSession();
            }
        }, 5000);
    }
    return true;
}

let _expiring = false;

async function expireSession() {
    if (_expiring) return;
    _expiring = true;
    _expiryDue = false;
    hideSessionBanner();
    if (_sessionTimer) { clearTimeout(_sessionTimer); _sessionTimer = null; }
    showToast('Daily session ended — please sign in again', 'warning');
    try {
        await window.cloud.signOutUser();
        // onAuthChange(null) clears the clock; do it here too in case it
        // doesn't fire (e.g. no listener yet).
        clearSessionClock();
    } catch (_) {
        // Offline: the sign-out call failed. Do NOT clear the start timestamp
        // — that would grandfather a brand-new 24h window on the next check
        // and let an expired session run indefinitely. Lock the UI now and
        // leave the expired stamp in place so the next check expires again.
        currentUser = null;
        currentUserDoc = null;
        applyScopeChange();
        tearDownCloudSync();
        showAuthGate('signin');
    }
    _expiring = false;
}

// Returns true while the session is valid; logs out and returns false if the
// 24-hour window has passed. Also arms a timer to auto-logout when it does.
function checkDailySession() {
    let start = parseInt(localStorage.getItem(SESSION_START_KEY), 10);
    if (!start || isNaN(start)) {
        // Grandfather an already-persisted login: start counting from now.
        start = Date.now();
        localStorage.setItem(SESSION_START_KEY, String(start));
    }
    const elapsed = Date.now() - start;
    // Ended: out now, or — mid-form or with no signal — once that is over.
    if (elapsed >= SESSION_MAX_MS) return requestExpiry();
    if (_sessionTimer) clearTimeout(_sessionTimer);
    _sessionTimer = setTimeout(requestExpiry, SESSION_MAX_MS - elapsed);
    if (_sessionWarnTimer) clearTimeout(_sessionWarnTimer);
    const left = SESSION_MAX_MS - elapsed;
    if (left <= SESSION_WARN_MS) showSessionBanner('soon');
    else { hideSessionBanner(); _sessionWarnTimer = setTimeout(() => showSessionBanner('soon'), left - SESSION_WARN_MS); }
    return true;
}

// A sleeping device or a discarded background tab delays setTimeout by however
// long it was out, so the timer alone can leave an expired session running.
// Re-check the wall clock whenever the tab comes back to the foreground.
function watchSessionOnResume() {
    const recheck = () => { if (currentUser) checkDailySession(); };
    document.addEventListener('visibilitychange', () => { if (!document.hidden) recheck(); });
    window.addEventListener('focus', recheck);
}
watchSessionOnResume();

async function handleSignIn(event) {
    event.preventDefault();
    showAuthError('signInError', '');
    showAuthNotice('');
    const email = document.getElementById('signInEmail').value.trim();
    const password = document.getElementById('signInPassword').value;
    try {
        setAuthBusy('signInForm', 'Signing in…', 'Signing in… on a weak signal this can take a while');
        _explicitSignIn = true;
        // A fresh 24h window BEFORE signing in: Firebase calls the auth
        // listener before signIn() resolves, and the listener checks the
        // window. A stamp left over from an expired session (an offline
        // expiry keeps it on purpose) signed the person straight back out
        // with "Daily session ended", whatever password they typed.
        startSessionClock();
        await window.cloud.signIn(email, password);
        startSessionClock(); // fresh 24h window
        // onAuthChange will take over from here.
    } catch (err) {
        _explicitSignIn = false;
        clearSessionClock();
        const code = err && err.code;
        const wrong = code === 'auth/invalid-credential' || code === 'auth/wrong-password' || code === 'auth/invalid-login-credentials';
        releaseAuthBusy();
        showAuthError('signInError', friendlyAuthError(err) + (wrong ? signInHint(email, password) : ''));
    }
}

async function handleSignUp(event) {
    event.preventDefault();
    showAuthError('signUpError', '');
    const name = document.getElementById('signUpName').value.trim();
    const email = document.getElementById('signUpEmail').value.trim();
    const password = document.getElementById('signUpPassword').value;
    try {
        setAuthBusy('signUpForm', 'Creating account…', 'Creating the account…');
        _explicitSignIn = true;
        const user = await window.cloud.signUp(email, password, name);
        startSessionClock(); // fresh 24h window
        // Eagerly create the user doc so the owner sees them in the pending list.
        await window.cloud.createUserDoc(user, name);
        // onAuthChange will pick up the new user and route to pending/app.
    } catch (err) {
        releaseAuthBusy();
        showAuthError('signUpError', friendlyAuthError(err));
    }
}

async function handleSignOut() {
    // Firestore holds a signed-out account's queued writes until that same
    // account signs in here again — they are not lost, but they do not move.
    const ins = inspections.filter(r => insQueuedIds.has(r.id)).length;
    const parts = queuedSummary(ins);
    if (parts.length && !confirm(`Not sent yet: ${parts.join(', ')}.\n\nIf you sign out now they stay on this device and are only sent after YOU sign in again here — not when someone else signs in. Sign out anyway?`)) return;
    try {
        await window.cloud.signOutUser();
    } catch (e) { /* ignore */ }
}

// For a shared computer. The app keeps units, damage records, implements,
// licences and the change log in this browser for offline use — readable by
// the next person with the browser's developer tools whatever their access.
// This removes them (and the offline database) after signing out.
const DEVICE_DATA_KEYS = [STORAGE_KEY, DAMAGE_STORAGE_KEY, IMPLEMENTS_STORAGE_KEY, LICENSE_STORAGE_KEY,
    BACKUP_RING_KEY, AUDIT_LOG_KEY, PENDING_CHANGES_KEY];
async function handleSignOutErase() {
    const ins = inspections.filter(r => insQueuedIds.has(r.id)).length;
    const parts = queuedSummary(ins);
    if (!confirm('Sign out and erase this app\'s data on this device?\n\n'
        + 'Use this on a shared computer: the records kept here for offline use are removed, so the next person '
        + 'cannot read them. Files attached to units are kept.'
        + (parts.length ? `\n\nNot sent yet — these will be LOST: ${parts.join(', ')}.` : ''))) return;
    try { await window.cloud.signOutUser(); } catch (e) { /* ignore */ }
    // Other open tabs of the app drop what they hold in memory.
    try { localStorage.setItem(ERASE_BROADCAST_KEY, String(Date.now())); } catch (_) {}
    if (!await eraseDeviceData()) {
        try { sessionStorage.setItem(ERASE_INCOMPLETE_KEY, '1'); } catch (_) {}
    }
    appReload();
}

const ERASE_BROADCAST_KEY = 'tractorEraseBroadcast';
const ERASE_INCOMPLETE_KEY = 'tractorEraseIncomplete';
// The app's offline copies, then Firestore's offline database. true when both
// are gone. The database cannot be cleared while the app is open in another
// tab; Firestore is stopped either way, so the caller reloads the page.
async function eraseDeviceData() {
    DEVICE_DATA_KEYS.forEach(k => { try { localStorage.removeItem(k); } catch (_) {} });
    try { sessionStorage.removeItem(PENDING_CHANGES_KEY); } catch (_) {}
    if (!window.cloud || typeof window.cloud.eraseLocalCache !== 'function') return false;
    try { return !!await window.cloud.eraseLocalCache(); }
    catch (e) { console.warn('[cloud] offline database not erased:', e); return false; }
}

// A limited account must not find the other group's records on its device:
// the offline copies and Firestore's offline database may hold what an
// unlimited session (this account before the limit, or another person) read
// here. The first time a limited account uses this device under its limit,
// both are cleared and the page reloads — unless something is still waiting
// to be sent; then it is left for a later sign-in. Tried once per account and
// limit, so another open tab cannot make it reload over and over.
const DEVICE_SCOPE_KEY = 'tractorDeviceScope';
const DEVICE_SCOPE_TRIED_KEY = 'tractorDeviceScopeTried';
async function protectDeviceForScope(uid) {
    const sc = effectiveUnitScope();
    const want = sc === 'all' ? 'all' : `${uid}:${sc}`;
    let have = null, tried = null;
    try { have = localStorage.getItem(DEVICE_SCOPE_KEY); tried = localStorage.getItem(DEVICE_SCOPE_TRIED_KEY); } catch (_) {}
    if (sc === 'all') {
        try { if (have !== 'all') localStorage.setItem(DEVICE_SCOPE_KEY, 'all'); } catch (_) {}
        return false;
    }
    if (have === want) return false;
    if (tried === want) {
        showToast('Data from another account may still be saved on this device — close the other tabs of this app and use "Sign out & erase this device"', 'warning');
        return false;
    }
    const ins = inspections.filter(r => insQueuedIds.has(r.id)).length;
    if (queuedSummary(ins).length) return false;
    try { localStorage.setItem(DEVICE_SCOPE_TRIED_KEY, want); } catch (_) {}
    const done = await eraseDeviceData();
    if (done) { try { localStorage.setItem(DEVICE_SCOPE_KEY, want); } catch (_) {} }
    appReload();
    return true;
}

function renderUserPill() {
    if (!currentUserDoc) return;
    const pill = document.getElementById('userPill');
    if (!pill) return;
    pill.style.display = '';
    const name = currentUserDoc.displayName || currentUserDoc.email || 'User';
    document.getElementById('userPillName').textContent = name;
    const avatar = document.getElementById('userPillAvatar');
    if (avatar) avatar.textContent = (Array.from(name.trim())[0] || '?').toUpperCase();
    const label = roleLabel(currentUserDoc.role);
    document.getElementById('userPillRole').textContent = label;
    pill.dataset.role = currentUserDoc.role;
    document.getElementById('userMenuEmail').textContent = currentUserDoc.email || '';
    document.getElementById('userMenuRoleLabel').textContent = isUnitScoped()
        ? `${label} account · ${unitScopeLabel(effectiveUnitScope())} · ${APP_VERSION}`
        : `${label} account · ${APP_VERSION}`;
}

// The account menu at the foot of the sidebar: account details and both
// sign-out actions. It closes on the next click outside it, or on Escape.
let _userMenuClose = null;
function toggleUserMenu() {
    const menu = document.getElementById('userMenu');
    if (!menu) return;
    const open = !menu.classList.contains('open');
    menu.classList.toggle('open', open);
    const btn = document.getElementById('userPillBtn');
    if (btn) btn.setAttribute('aria-expanded', open ? 'true' : 'false');
    if (_userMenuClose) {
        document.removeEventListener('click', _userMenuClose);
        document.removeEventListener('keydown', _userMenuClose);
        _userMenuClose = null;
    }
    if (!open) return;
    const close = e => {
        if (e.type === 'keydown' ? e.key !== 'Escape' : document.getElementById('userPill').contains(e.target)) return;
        toggleUserMenu();
        if (e.type === 'keydown' && btn) btn.focus();
    };
    _userMenuClose = close;
    // Added after this click has finished, or it would close the menu at once.
    setTimeout(() => {
        if (_userMenuClose !== close) return;
        document.addEventListener('click', close);
        document.addEventListener('keydown', close);
    }, 0);
}

function isOwner() {
    return currentUserDoc && currentUserDoc.role === 'owner';
}

// ============================================================
// PER-USER ACCESS (privilege per area)
// ============================================================
// Configurable areas the owner can restrict per user. Users management stays
// owner-only; the Dashboard is always available to any active user.
const ACCESS_AREAS = [
    { key: 'editUnits',    label: 'Unit Database',     levels: ['none', 'view', 'edit'] },
    { key: 'implements',   label: 'Implements',     levels: ['none', 'view', 'edit'] },
    { key: 'damage',       label: 'Damage',      levels: ['none', 'view', 'edit'] },
    { key: 'licenseStock', label: 'License Stock',  levels: ['none', 'view', 'edit'] },
    // The Tim page is three separate permissions, not one. A KHL may need to
    // read the roster and file their own daily report while having no say over
    // the shift schedule, which a single team-wide level cannot express.
    { key: 'teamShift',    label: 'Shift Schedule',   levels: ['none', 'view', 'edit'] },
    { key: 'teamLog',      label: 'Daily Report', levels: ['none', 'view', 'edit'] },
    { key: 'teamMembers',  label: 'Member List', levels: ['none', 'view', 'edit'] },
    // Separate from teamLog on purpose: a checker should be able to approve a
    // report without being able to rewrite the thing they are checking.
    { key: 'teamLogApprove', label: 'Report Approval', levels: ['none', 'edit'] },
    { key: 'warehouse',    label: 'Warehouse',         levels: ['none', 'view', 'edit'] },
    // Heavy-equipment checks: the technician who checks and files, and —
    // separately, for the same reason as teamLogApprove — the supervisor who
    // approves or sends a report back.
    { key: 'inspection',        label: 'Heavy Equipment Inspection',  levels: ['none', 'view', 'edit'] },
    { key: 'inspectionApprove', label: 'Inspection Approval', levels: ['none', 'edit'] },
    // Read-only by nature: it shows what other areas already allow, nothing more.
    { key: 'leader',       label: 'Decision Inbox', levels: ['none', 'view'] },
    { key: 'history',      label: 'History',        levels: ['none', 'view'] }
];

// Which access areas back each navigable view. A view opens when the user can
// view at least one of them — the Tim page is reachable through any of its
// three areas. Several places used to hardcode this list; keeping the mapping
// in one place stops them drifting apart when an area is added.
const VIEW_AREAS = {
    editUnits:    ['editUnits'],
    implements:   ['implements'],
    damage:       ['damage'],
    licenseStock: ['licenseStock'],
    team:         ['teamShift', 'teamLog', 'teamMembers', 'teamLogApprove'],
    warehouse:    ['warehouse'],
    inspection:   ['inspection', 'inspectionApprove'],
    leader:       ['leader']
};
const GATED_VIEWS = Object.keys(VIEW_AREAS);
// Every area that holds data (i.e. everything except the read-only audit log).
// 'leader' is view-only and 'history' is the audit log: neither is a place
// where data is edited, so neither counts towards "can this person edit".
const DATA_AREAS = ACCESS_AREAS
    .filter(a => a.key !== 'history' && a.key !== 'leader')
    .map(a => a.key);
// area key → <body> dataset flag used by the editonly--* CSS rules.
const RO_FLAGS = {
    editUnits: 'roEditunits', implements: 'roImplements', damage: 'roDamage',
    licenseStock: 'roLicense', teamShift: 'roTeamshift', teamLog: 'roTeamlog',
    teamMembers: 'roTeammembers', teamLogApprove: 'roTeamapprove',
    warehouse: 'roWarehouse', inspection: 'roInspection'
};
const _LVL_RANK = { none: 0, view: 1, edit: 2 };

// ---- Roles ----
// 'owner' keeps its internal key: the owner e-mail allowlist and the Firestore
// rules are written against it, so only its label changed to Super Admin.
// Staff / PBT / KHL grant nothing on their own — they are labels, and the owner
// sets every area explicitly in the Akses dialog.
const ROLES = [
    { key: 'owner', label: 'Super Admin' },
    { key: 'staff', label: 'Staff' },
    { key: 'pbt',   label: 'PBT' },
    { key: 'khl',   label: 'KHL' }
];
// Roles from before the four-level model. Still honoured exactly as they were,
// so no existing account silently gains or loses access; the Users table flags
// them so an owner can move each person over deliberately.
const LEGACY_ROLES = [
    { key: 'team',   label: 'Team' },
    { key: 'viewer', label: 'Viewer' }
];
function roleLabel(key) {
    const r = ROLES.concat(LEGACY_ROLES).find(x => x.key === key);
    return r ? r.label : (key || '—');
}
function isLegacyRole(key) {
    return LEGACY_ROLES.some(r => r.key === key);
}

// Level a role grants for an area when the user has no explicit override.
function roleDefaultAccess(role, area) {
    if (role === 'owner') return 'edit';
    // Legacy role: keep the old behaviour untouched.
    if (role === 'team')  return area === 'history' ? 'view' : 'edit';
    // staff / pbt / khl / viewer / pending — nothing until the owner grants it.
    return 'none';
}

// True when the user can open a given view — any one of its areas is enough.
function canViewView(view) {
    return (VIEW_AREAS[view] || []).some(a => hasAccess(a, 'view'));
}

// The level stored for an area (explicit access override → role default),
// before the unit-group limit below. The Access dialog shows this one.
function grantedAccess(area, user = currentUserDoc) {
    if (!user) return 'none';
    if (user.role === 'owner') return 'edit';
    const explicit = user.access && user.access[area];
    return explicit || roleDefaultAccess(user.role, area);
}

// ---- Unit-group limit (v165) ----
// An account can be limited to one unit group. It then sees only that group's
// units and damage records, may not edit units or damage (view only), and the
// areas that belong to the other group close. Stored as access.unitScope;
// absent (or null) = all groups. Anything else — '' or an unknown word —
// fails closed: no units at all, the same reading firestore.rules gives it.
const UNIT_SCOPES = ['all', 'tractor', 'heavy'];
const AREA_GROUP = { implements: 'tractor', licenseStock: 'tractor', inspection: 'heavy', inspectionApprove: 'heavy' };
function effectiveUnitScope(user = currentUserDoc) {
    if (!user || user.role === 'owner') return 'all';
    const a = user.access || {};
    if (!Object.prototype.hasOwnProperty.call(a, 'unitScope') || a.unitScope == null) return 'all';
    return UNIT_SCOPES.includes(a.unitScope) ? a.unitScope : 'none';
}
function isUnitScoped(user = currentUserDoc) { return effectiveUnitScope(user) !== 'all'; }
function unitScopeAllows(g, user = currentUserDoc) {
    const sc = effectiveUnitScope(user);
    return sc === 'all' || sc === g;
}
function unitScopeLabel(sc) {
    return sc === 'tractor' ? `${UNIT_GROUPS.tractor.label} only`
         : sc === 'heavy' ? `${UNIT_GROUPS.heavy.label} only`
         : sc === 'none' ? 'No unit group' : 'All groups';
}

// Effective level of a user for an area: what is granted, narrowed by the
// unit-group limit.
function effectiveAccess(area, user = currentUserDoc) {
    const lv = grantedAccess(area, user);
    if (lv === 'none' || !user || user.role === 'owner') return lv;
    const sc = effectiveUnitScope(user);
    if (sc === 'all') return lv;
    if (AREA_GROUP[area] && AREA_GROUP[area] !== sc) return 'none';
    if ((area === 'editUnits' || area === 'damage') && lv === 'edit') return 'view';
    return lv;
}

// Does the user meet at least `min` access ('view' or 'edit') for an area?
function hasAccess(area, min, user = currentUserDoc) {
    if (user && user.role === 'owner') return true;
    return _LVL_RANK[effectiveAccess(area, user)] >= _LVL_RANK[min];
}

// ---- CSV export/import capability (separate none/export/full privilege) ----
const CSV_LEVELS = ['none', 'export', 'full'];
const _CSV_RANK = { none: 0, export: 1, full: 2 };
// Same shape as roleDefaultAccess: only the legacy 'team' role carries a
// default, the new roles start at none and are granted explicitly.
function roleDefaultCsv(role) { return (role === 'owner' || role === 'team') ? 'full' : 'none'; }
function effectiveCsv(user = currentUserDoc) {
    if (!user) return 'none';
    if (user.role === 'owner') return 'full';
    return (user.access && user.access.csv) || roleDefaultCsv(user.role);
}
// min = 'export' (can export) or 'full' (can import). Shows a toast when denied.
function canCsv(min, notify = true) {
    if (currentUserDoc && currentUserDoc.role === 'owner') return true;
    const ok = _CSV_RANK[effectiveCsv()] >= _CSV_RANK[min];
    if (!ok && notify) {
        showToast(min === 'full'
            ? 'You do not have permission to import CSV'
            : 'You do not have permission to export CSV', 'warning');
    }
    return ok;
}

// True when the user can edit at least one data area — by role OR by an
// explicit per-area grant. A viewer the owner gave 'edit' on one area is an
// editor, so gating must not go by role alone.
function canEditAnyArea() {
    return DATA_AREAS.some(a => hasAccess(a, 'edit'));
}

function applyRoleGating() {
    const owner = isOwner();
    const scopeChanged = applyScopeChange();
    if (scopeChanged) {
        // Whatever is open was drawn for the old limit.
        const prof = document.getElementById('unitProfileModal');
        if (prof && prof.classList.contains('open') && !globalData.some(u => u.id === prof.dataset.unitId)) closeUnitProfile();
        closeGlobalSearch();
        const gs = document.getElementById('globalSearch'); if (gs) gs.value = '';
        const hm = document.getElementById('historyModal');
        if (hm && hm.classList.contains('open')) {
            if (hasAccess('history', 'view')) showHistory(hm.dataset.unitId || undefined); else closeHistory();
        }
        if (document.getElementById('masterListsModal')?.classList.contains('open')) {
            if (MASTER_KINDS.some(canViewMasterList)) openMasterLists(); else closeMasterLists();
        }
        editSortState = { key: null, asc: true }; editToolFilter = ''; editMissingFilter = '';
        ['editSearch', 'editStatusFilter', 'editSiteFilter'].forEach(id => { const el = document.getElementById(id); if (el) el.value = ''; });
        populateEditFilters();
    }

    // Owner-only navigation links
    document.querySelectorAll('[data-owner-only]').forEach(el => {
        el.style.display = owner ? '' : 'none';
    });

    applyAccessVisibility();

    // If the user lost access to the current view, send them to the dashboard.
    if ((!owner && currentView === 'users') ||
        (GATED_VIEWS.includes(currentView) && !canViewView(currentView))) {
        navigateTo('dashboard');
    }

    // Re-render any visible table to refresh its action buttons / editability
    if (currentView === 'editUnits') renderEditTable();
    if (currentView === 'implements') renderImplementsTable();
    if (scopeChanged) {
        updateDamageCount();
        if (currentView === 'dashboard') {
            const empty = document.getElementById('emptyState');
            const content = document.getElementById('dashboardContent');
            if (empty) empty.style.display = globalData.length ? 'none' : '';
            if (content) content.style.display = globalData.length ? 'block' : 'none';
            // A redraw only: the licence downgrade and the daily e-mail run
            // from fresh cloud data (applyCloudUnitsSnapshot), not from here.
            if (globalData.length) { populateFilters(); filteredData = applyFilterLogic(); updateDashboard(filteredData); updateNavGroups(); }
        } else if (currentView === 'damage') {
            renderDamageTable();
        }
        renderUserPill();
        scheduleDecisionRefresh();
    }
    document.dispatchEvent(new CustomEvent('ot:gating'));
}

// Hide sidebar links the user can't view, and flag view-only areas on <body>
// so edit-only controls (Add buttons, inline editing) can be CSS-hidden.
function applyAccessVisibility() {
    document.querySelectorAll('.nav__link[data-view]').forEach(el => {
        const v = el.getAttribute('data-view');
        if (GATED_VIEWS.includes(v)) {
            el.style.display = canViewView(v) ? '' : 'none';
        }
    });
    updateDecisionBadge();
    const navHistory = document.getElementById('navHistory');
    if (navHistory) navHistory.style.display = hasAccess('history', 'view') ? '' : 'none';
    const navMaster = document.getElementById('navMasterLists');
    if (navMaster) navMaster.style.display = MASTER_KINDS.some(k => canViewMasterList(k)) ? '' : 'none';
    // The owner can change someone's access while they are signed in. Hiding
    // the menu is not enough — the stream has to stop too.
    if (!hasAccess('history', 'view')) stopHistorySubscription();

    // data-ro-<area>="1" whenever the user may NOT edit that area — including
    // no access at all, so the edit controls stay hidden even if the section
    // is somehow reachable.
    Object.entries(RO_FLAGS).forEach(([area, flag]) => {
        if (!hasAccess(area, 'edit')) document.body.dataset[flag] = '1';
        else delete document.body.dataset[flag];
    });

    // CSV capability flags → hide export/import buttons.
    if (canCsv('export', false)) delete document.body.dataset.nocsvexport; else document.body.dataset.nocsvexport = '1';
    if (canCsv('full', false))   delete document.body.dataset.nocsvimport; else document.body.dataset.nocsvimport = '1';
    updateNavGroups();
}

// Gate an edit action. With an `area` it checks per-area edit access; without,
// it falls back to canEditAnyArea() — an explicit per-area grant counts, so
// this must not go by role alone.
function requireEdit(area) {
    const ok = area ? hasAccess(area, 'edit') : canEditAnyArea();
    if (!ok) {
        showToast('View-only access — ask the owner for edit rights', 'warning');
        return false;
    }
    return true;
}

// ============================================================
// USER MANAGEMENT (Khusus owner)
// ============================================================

function ensureUsersSubscription() {
    if (!isOwner()) return;
    if (cloudUsersUnsub) return;
    if (!window.cloud || !window.cloud.subscribeUsers) {
        console.warn('[users] subscribeUsers tidak ada — firebase-init.js lama masih disajikan');
        showToast(STALE_CLIENT_MSG, 'warning');
        return;
    }
    cloudUsersUnsub = window.cloud.subscribeUsers(users => {
        allUsers = users;
        if (currentView === 'users') renderUsersView();
    }, err => {
        console.warn('[cloud] users subscription error:', err);
    });
}

// Compact, Indonesian, no seconds — the default toLocaleString() renders
// "8/19/2026, 2:16:34 PM", which is US-formatted and wide enough to crowd the
// action column out of the row.
function formatUserTime(ms) {
    if (!ms) return '—';
    const d = new Date(ms);
    if (isNaN(d.getTime())) return '—';
    return d.toLocaleString('en-GB', {
        day: '2-digit', month: 'short', year: 'numeric',
        hour: '2-digit', minute: '2-digit'
    });
}

// "Diubah oleh" repeats the same address on every row, and the domain is the
// noisy half. Show the local part; the full address stays in the tooltip.
function shortActor(value) {
    const v = (value || '').trim();
    if (!v) return '—';
    const at = v.indexOf('@');
    return at > 0 ? v.slice(0, at) : v;
}

function renderUsersView() {
    renderGroupStampNotice();
    if (!isOwner()) return;
    const pending = allUsers.filter(u => u.status !== 'active');
    const active  = allUsers.filter(u => u.status === 'active');

    document.getElementById('usersCount').textContent =
        `${allUsers.length} user(s) · ${pending.length} pending`;

    // Summary chips — one per current role, plus legacy roles only while any
    // account still holds one, so the row disappears once everyone is moved.
    const countOf = key => active.filter(u => u.role === key).length;
    const icons = { owner: 'crown', staff: 'user-tie', pbt: 'user-gear', khl: 'user' };
    let chips = ROLES.map(r =>
        `<div class="user-chip user-chip--${r.key}"><i class="fas fa-${icons[r.key] || 'user'}"></i> ${countOf(r.key)} ${escapeHtml(r.label)}</div>`
    ).join('');
    const legacyTotal = LEGACY_ROLES.reduce((n, r) => n + countOf(r.key), 0);
    if (legacyTotal > 0) {
        chips += `<div class="user-chip user-chip--legacy" title="Legacy role — assign them a new role"><i class="fas fa-clock-rotate-left"></i> ${legacyTotal} legacy role</div>`;
    }
    chips += `<div class="user-chip user-chip--pending"><i class="fas fa-hourglass-half"></i> ${pending.length} Pending</div>`;
    document.getElementById('usersSummary').innerHTML = chips;

    // Pending table
    const pendingBody = document.getElementById('pendingUsersBody');
    // Any sign-in rewrites a user document and re-renders this table. The
    // owner's pick in a pending row must survive that, or "Setujui" a moment
    // later approves the person as KHL.
    const pickedRole = {};
    pendingBody.querySelectorAll('select[id^="approveRole_"]').forEach(sel => {
        pickedRole[sel.id.slice('approveRole_'.length)] = sel.value;
    });
    if (pending.length === 0) {
        pendingBody.innerHTML = `<tr><td colspan="5" style="text-align:center;padding:20px;color:var(--text-secondary)">No pending registrations</td></tr>`;
    } else {
        pendingBody.innerHTML = pending.map((u, i) => `
            <tr>
                <td>${i + 1}</td>
                <td data-label="Name"><strong>${escapeHtml(u.displayName || '—')}</strong></td>
                <td data-label="Email"><span class="user-cell-email" title="${escapeHtml(u.email || '')}">${escapeHtml(u.email || '')}</span></td>
                <td data-label="Registered"><span class="user-cell-time">${formatUserTime(u.createdAt)}</span></td>
                <td class="col-actions">
                    <div class="row-actions row-actions--labeled">
                        <select class="form-select user-role-select" id="approveRole_${escapeHtml(u.uid)}"
                                aria-label="Role for ${escapeHtml(u.email || '')}">
                            ${ROLES.filter(r => r.key !== 'owner').map(r =>
                                `<option value="${r.key}"${r.key === (pickedRole[u.uid] || 'khl') ? ' selected' : ''}>${escapeHtml(r.label)}</option>`).join('')}
                        </select>
                        <button class="btn btn-success btn-sm" title="Approve with the selected role" onclick="approveUser(${jsArg(u.uid)})">
                            <i class="fas fa-check"></i> Approve
                        </button>
                        <button class="btn btn-secondary btn-sm row-actions__icon" title="Reject and delete registration" onclick="rejectUser(${jsArg(u.uid)})">
                            <i class="fas fa-xmark" style="color:var(--danger)"></i>
                        </button>
                    </div>
                </td>
            </tr>`).join('');
    }

    // Active table
    const activeBody = document.getElementById('activeUsersBody');
    if (active.length === 0) {
        activeBody.innerHTML = `<tr><td colspan="7" style="text-align:center;padding:20px;color:var(--text-secondary)">No active users yet</td></tr>`;
    } else {
        activeBody.innerHTML = active.map((u, i) => {
            const isMe = currentUser && u.uid === currentUser.uid;
            const isOwnerRow = u.role === 'owner';
            const legacy = isLegacyRole(u.role);

            // Your own Super Admin row stays locked so you cannot lock yourself
            // out; every other row is changeable, including demoting another
            // Super Admin — a promotion by mistake has to be undoable.
            let roleSelect;
            if (isOwnerRow && isMe) {
                roleSelect = `<span class="badge badge-good"><i class="fas fa-crown"></i> ${escapeHtml(roleLabel('owner'))}</span>`;
            } else {
                // A legacy role is offered only to the account that still holds
                // it, so it is never handed out again but also never silently
                // swapped underneath someone.
                const opts = ROLES.map(r =>
                    `<option value="${r.key}" ${u.role === r.key ? 'selected' : ''}>${escapeHtml(r.label)}</option>`)
                    .concat(legacy ? [`<option value="${u.role}" selected>${escapeHtml(roleLabel(u.role))} (legacy role)</option>`] : [])
                    .join('');
                roleSelect = `<select class="form-select user-role-select" title="Role is only a label — set permissions with the Access button"
                           onchange="changeUserRole(${jsArg(u.uid)}, this.value)">${opts}</select>`;
            }

            // A new role grants nothing by itself, so an account can sit active
            // with no way in. Say so where the owner will see it.
            const noAccess = !isOwnerRow &&
                ACCESS_AREAS.every(a => effectiveAccess(a.key, u) === 'none');
            const roleNote = (legacy
                ? '<div class="user-role-note user-role-note--legacy">Legacy role — assign a new role</div>'
                : (noAccess ? '<div class="user-role-note user-role-note--warn">No access granted yet</div>' : ''))
                + (!isOwnerRow && isUnitScoped(u) ? `<div class="user-role-note">${escapeHtml(unitScopeLabel(effectiveUnitScope(u)))}</div>` : '');

            // Which device currently holds this account's single session slot.
            const sess = u.activeSession;
            const live = sess && sess.id && !String(sess.id).startsWith('revoked_');
            // escapeHtml: the device string is written by the signed-in user
            // themselves, about their own account — anyone active can put
            // markup there, and this row is rendered in the Super Admin's view.
            const sessionTitle = escapeHtml(live
                ? `Sign out of active device (${String(sess.device || 'unknown').slice(0, 80)}${sess.startedAt ? ' · signed in ' + formatUserTime(sess.startedAt) : ''})`
                : 'Sign out of all devices');

            return `
            <tr>
                <td>${i + 1}</td>
                <td data-label="Name"><strong>${escapeHtml(u.displayName || '—')}</strong>${isMe ? ' <span style="font-size:11px;color:var(--text-secondary)">(You)</span>' : ''}</td>
                <td data-label="Email"><span class="user-cell-email" title="${escapeHtml(u.email || '')}">${escapeHtml(u.email || '')}</span></td>
                <td data-label="Role">${roleSelect}${roleNote}</td>
                <td data-label="Last Updated"><span class="user-cell-time">${formatUserTime(u.updatedAt)}</span></td>
                <td data-label="Updated By"><span class="user-cell-actor" title="${escapeHtml(u.updatedBy || '')}">${escapeHtml(shortActor(u.updatedBy))}</span></td>
                <td class="col-actions">
                    ${isOwnerRow
                        ? '<span class="user-cell-protected">protected</span>'
                        : `<div class="row-actions row-actions--labeled">
                            <button class="btn btn-secondary btn-sm" title="Set access per menu" onclick="openAccessModal(${jsArg(u.uid)})"><i class="fas fa-sliders"></i> Access</button>
                            <button class="btn btn-secondary btn-sm row-actions__icon" title="${sessionTitle}" onclick="forceSignOutUser(${jsArg(u.uid)})"><i class="fas fa-right-from-bracket"></i></button>
                            <button class="btn btn-secondary btn-sm row-actions__icon" title="Remove user" onclick="removeUser(${jsArg(u.uid)})"><i class="fas fa-user-minus" style="color:var(--danger)"></i></button>
                           </div>`}
                </td>
            </tr>`;
        }).join('');
    }
}

// ---- Unit groups stored on every record (v167) ----
// Accounts limited to one group can only read units and damage records the
// server can see the group of. Older units have none (it meant Agricultural)
// and older tractor damage records neither: the owner stores them once here.
function unstampedGroupRecords() {
    const units = globalData.filter(u => {
        const k = normalizeGroupKey(u.unitGroup);
        return k !== null && u.unitGroup !== (k || 'tractor');
    });
    const damages = globalDamages.filter(d => (d.unitGroup || '') !== damageGroupStamp(d));
    const unreadable = globalData.filter(hasUnreadableGroup).length;
    return { units, damages, unreadable };
}
function renderGroupStampNotice() {
    const box = document.getElementById('groupStampNotice');
    if (!box) return;
    const { units, damages, unreadable } = isOwner() ? unstampedGroupRecords() : { units: [], damages: [], unreadable: 0 };
    const limited = (allUsers || []).some(u => u.role !== 'owner' && isUnitScoped(u));
    const historyLeft = isOwner() && !_historyStampedHere();
    box.hidden = !units.length && !damages.length && !unreadable && !historyLeft;
    if (box.hidden) { box.innerHTML = ''; return; }
    const missing = units.length + damages.length;
    box.innerHTML = `<i class="fas fa-layer-group" aria-hidden="true"></i>
        <div class="group-stamp-notice__text">
            ${missing ? `<strong>${units.length} unit(s) and ${damages.length} damage record(s) do not store their unit group yet.</strong>
            Accounts limited to one group cannot see them until it is stored${limited ? ' — and such accounts exist now' : ''}.`
            : historyLeft ? '<strong>Older history rows do not store their unit group yet.</strong> Accounts limited to one group see only newer history until it is stored.' : ''}
            ${unreadable ? `${missing ? '<br>' : ''}<strong>${unreadable} unit(s) have a group that is not recognised</strong> — no limited account can see them; set it in Data Check.` : ''}
        </div>
        ${missing || historyLeft ? '<button type="button" class="btn btn-primary btn-sm" onclick="storeUnitGroups()"><i class="fas fa-check"></i> Store unit groups</button>' : ''}`;
}
// The history back-fill reads the whole log, so it is remembered per device
// once it has gone through, rather than counted on every visit.
const HISTORY_STAMPED_KEY = 'tractorHistoryGroupsStored_v1';
function _historyStampedHere() { try { return localStorage.getItem(HISTORY_STAMPED_KEY) === '1'; } catch (_) { return false; } }
// Older history rows: the group each belongs to, added once (rules allow the
// owner exactly that field while it is missing). Rows whose unit is gone stay
// as they are — readable by unlimited accounts only.
async function storeHistoryGroups() {
    if (!isOwner() || !window.cloud?.isReady || typeof window.cloud.getAllHistory !== 'function'
        || typeof window.cloud.updateHistoryFields !== 'function') return 0;
    const all = await window.cloud.getAllHistory();
    const parts = (all || []).filter(e => e && e.id && !('unitGroup' in e))
        .map(e => ({ id: e.id, unitGroup: historyGroupOf(e) }))
        .filter(p => ['tractor', 'heavy', 'shared'].includes(p.unitGroup));
    if (parts.length) await window.cloud.updateHistoryFields(parts);
    try { localStorage.setItem(HISTORY_STAMPED_KEY, '1'); } catch (_) {}
    return parts.length;
}
// Writes only the group, as a partial update, on the records that lack it.
async function storeUnitGroups() {
    if (!isOwner()) return;
    const { units, damages } = unstampedGroupRecords();
    const historyLeft = !_historyStampedHere();
    if (!units.length && !damages.length && !historyLeft) { showToast('Every unit and damage record already stores its group', 'info'); return; }
    if (!confirm(`Store the unit group on ${units.length} unit(s) and ${damages.length} damage record(s)`
        + (historyLeft ? ', and on older history rows' : '') + '?\n\n'
        + 'Accounts limited to one group can only read records that carry it. Nothing else on the records changes.')) return;
    const unitParts = units.map(u => ({ id: u.id, unitGroup: storedUnitGroup(u) }));
    const dmgParts = damages.map(d => ({ id: d.id, unitGroup: damageGroupStamp(d) }));
    unitParts.forEach(p => { const u = globalData.find(x => x.id === p.id); if (u) u.unitGroup = p.unitGroup; });
    dmgParts.forEach(p => { const d = globalDamages.find(x => x.id === p.id); if (d) d.unitGroup = p.unitGroup; });
    saveToStorage(globalData);
    saveDamages();
    if (!suppressCloudWrites && window.cloud?.isReady) {
        if (unitParts.length) {
            const send = typeof window.cloud.updateUnitsFields === 'function' ? window.cloud.updateUnitsFields : window.cloud.saveUnits;
            Promise.resolve(send.call(window.cloud, unitParts)).catch(err => cloudWriteFailed(err, { what: 'unit groups', label: '[Master] Unit groups', resync: resyncUnits }));
        }
        if (dmgParts.length) {
            const send = typeof window.cloud.updateDamagesFields === 'function' ? window.cloud.updateDamagesFields : window.cloud.saveDamages;
            Promise.resolve(send.call(window.cloud, dmgParts)).catch(err => cloudWriteFailed(err, { what: 'damage groups', label: '[Master] Unit groups', resync: resyncDamages }));
        }
    }
    let rows = 0;
    if (historyLeft) {
        try { rows = await storeHistoryGroups(); }
        catch (err) {
            console.error('[cloud] history groups not stored:', err);
            showToast(err && err.code === 'permission-denied'
                ? 'History rows were not updated — publish the new firestore.rules first, then press Store unit groups again'
                : 'History rows were not updated — try again', 'warning');
        }
    }
    logEvent({ action: 'update', unitName: '[Master] Unit groups', field: 'unitGroup',
               after: `stored on ${unitParts.length} unit(s), ${dmgParts.length} damage record(s), ${rows} history row(s)` });
    showToast(`Unit group stored on ${unitParts.length} unit(s), ${dmgParts.length} damage record(s), ${rows} history row(s)`, 'success');
    renderGroupStampNotice();
}

// ---- Per-user access editor (owner) ----
function openAccessModal(uid) {
    if (!isOwner()) return;
    const user = allUsers.find(u => u.uid === uid);
    if (!user) return;
    document.getElementById('accessUserUid').value = uid;
    document.getElementById('accessUserName').textContent = user.displayName || user.email || uid;
    const labels = { none: 'None', view: 'View', edit: 'Edit' };
    const rawScope = user.access ? user.access.unitScope : undefined;
    const knownScope = rawScope == null || UNIT_SCOPES.includes(rawScope);
    const sc = rawScope == null ? 'all' : (knownScope ? rawScope : '');
    let rows = `<div class="access-row access-row--scope">
            <span class="access-row__label">Unit group <small>what this person can see</small></span>
            <select class="form-select access-select" data-area="unitScope" onchange="refreshAccessScopeNote()">
                ${knownScope ? '' : `<option value="" selected disabled>No unit group (stored: ${escapeHtml(String(rawScope))})</option>`}
                ${UNIT_SCOPES.map(k => `<option value="${k}" ${k === sc ? 'selected' : ''}>${escapeHtml(unitScopeLabel(k))}</option>`).join('')}
            </select>
        </div>
        <div class="access-presets">
            <button type="button" class="btn btn-secondary btn-sm" onclick="applyAccessPreset('tractor')">View only — ${escapeHtml(UNIT_GROUPS.tractor.shortLabel)}</button>
            <button type="button" class="btn btn-secondary btn-sm" onclick="applyAccessPreset('heavy')">View only — ${escapeHtml(UNIT_GROUPS.heavy.shortLabel)}</button>
        </div>
        <p class="access-scope-note" id="accessScopeNote" hidden></p>`;
    rows += ACCESS_AREAS.map(area => {
        const cur = grantedAccess(area.key, user);
        const opts = area.levels.map(l => `<option value="${l}" ${l === cur ? 'selected' : ''}>${labels[l]}</option>`).join('');
        return `<div class="access-row" data-row-area="${area.key}">
            <span class="access-row__label">${escapeHtml(area.label)}<small class="access-row__applies" hidden></small></span>
            <select class="form-select access-select" data-area="${area.key}" onchange="refreshAccessScopeNote()">${opts}</select>
        </div>`;
    }).join('');
    // CSV export/import capability (its own level set)
    const csvLabels = { none: 'None', export: 'Export only', full: 'Export + Import' };
    const curCsv = effectiveCsv(user);
    rows += `<div class="access-row">
        <span class="access-row__label">CSV Export/Import</span>
        <select class="form-select access-select" data-area="csv">${CSV_LEVELS.map(l => `<option value="${l}" ${l === curCsv ? 'selected' : ''}>${csvLabels[l]}</option>`).join('')}</select>
    </div>`;
    document.getElementById('accessGrid').innerHTML = rows;
    refreshAccessScopeNote();
    document.getElementById('accessModal').classList.add('open');
}

// What the chosen unit group does to the rows below, shown next to them. The
// stored levels stay as they are, so setting "All groups" again gives back
// exactly what was granted.
function refreshAccessScopeNote() {
    const grid = document.getElementById('accessGrid');
    if (!grid) return;
    const sel = grid.querySelector('[data-area="unitScope"]');
    const sc = sel ? sel.value : 'all';
    const note = document.getElementById('accessScopeNote');
    if (note) {
        note.hidden = sc === 'all';
        note.textContent = sc === 'all' ? ''
            : !UNIT_SCOPES.includes(sc) ? 'The stored unit group is not recognised, so this account sees no units. Pick a group.'
            : `Sees only ${groupDef(sc).label} units and their damage records. `
              + 'Unit Database and Damage are view only; the other group\'s menus close.';
    }
    const probe = { role: 'staff', access: { unitScope: sc } };
    grid.querySelectorAll('[data-row-area]').forEach(row => {
        const area = row.dataset.rowArea;
        const granted = row.querySelector('.access-select').value;
        probe.access[area] = granted;
        const applies = effectiveAccess(area, probe);
        const tag = row.querySelector('.access-row__applies');
        if (tag) {
            tag.hidden = applies === granted;
            tag.textContent = applies === granted ? '' : ` → ${applies === 'none' ? 'None' : applies === 'view' ? 'View' : 'Edit'} with this group`;
        }
    });
}

// A ready-made view-only account for one group: the unit group, View on the
// fleet menus that group uses. Team, warehouse and CSV rows are left alone.
function applyAccessPreset(g) {
    const grid = document.getElementById('accessGrid');
    if (!grid) return;
    const set = (area, v) => { const el = grid.querySelector(`[data-area="${area}"]`); if (el) el.value = v; };
    set('unitScope', g);
    set('editUnits', 'view');
    set('damage', 'view');
    if (g === 'tractor') { set('implements', 'view'); set('licenseStock', 'view'); }
    else { set('inspection', 'view'); }
    refreshAccessScopeNote();
}

function closeAccessModal() {
    document.getElementById('accessModal').classList.remove('open');
}

async function saveAccess() {
    if (!isOwner()) return;
    const uid = document.getElementById('accessUserUid').value;
    const user = allUsers.find(u => u.uid === uid);
    if (!user) return;
    const access = {};
    document.querySelectorAll('#accessGrid .access-select').forEach(sel => {
        access[sel.dataset.area] = sel.value;
    });
    if (!UNIT_SCOPES.includes(access.unitScope)) { showToast('Pick a unit group first', 'warning'); return; }
    try {
        const fn = cloudFn('updateUserAccess');
        if (!fn) return;
        await fn(uid, access, currentUserDoc.email);
        logEvent({
            action: 'update',
            unitId: uid,
            unitName: `[User] ${user.displayName || user.email}`,
            field: 'access',
            after: [`Unit group:${unitScopeLabel(access.unitScope || 'all')}`,
                    ...ACCESS_AREAS.map(a => `${a.label}:${access[a.key]}`), `CSV:${access.csv}`].join(', ')
        });
        showToast(`Access for "${user.displayName || user.email}" updated`, 'success');
        closeAccessModal();
    } catch (e) {
        showToast('Failed to save access: ' + e.message, 'error');
    }
}

async function approveUser(uid, role) {
    if (!isOwner()) return;
    const user = allUsers.find(u => u.uid === uid);
    if (!user) return;
    // Role comes from the picker in that user's own pending row.
    if (!role) {
        const sel = document.getElementById('approveRole_' + uid);
        role = sel ? sel.value : 'khl';
    }
    if (!ROLES.some(r => r.key === role) || role === 'owner') {
        showToast('Unknown role', 'warning');
        return;
    }
    const label = roleLabel(role);
    try {
        await window.cloud.updateUserRole(uid, role, 'active', currentUserDoc.email);
        logEvent({
            action: 'approve',
            unitId: uid,
            unitName: `[User] ${user.displayName || user.email}`,
            field: 'role',
            before: 'pending',
            after: label
        });
        // The new roles carry no access, so approving alone leaves them with an
        // empty app — point the owner straight at the next step.
        showToast(`${user.email} approved as ${label} — set their access rights with the Access button`, 'success');
    } catch (e) {
        console.error('[users] approve failed:', e);
        showToast('Failed to approve user — ' + e.message, 'error');
    }
}

async function rejectUser(uid) {
    if (!isOwner()) return;
    const user = allUsers.find(u => u.uid === uid);
    if (!user) return;
    if (!confirm(`Reject and delete ${user.email}?\n\nTheir Firebase account remains, but they lose access to the dashboard.`)) return;
    try {
        await window.cloud.deleteUserDoc(uid);
        logEvent({
            action: 'reject',
            unitId: uid,
            unitName: `[User] ${user.displayName || user.email}`,
            before: 'pending',
            after: 'rejected'
        });
        showToast(`Rejected ${user.email}`, 'success');
    } catch (e) {
        showToast('Failed to reject user — ' + e.message, 'error');
    }
}

async function changeUserRole(uid, newRole) {
    if (!isOwner()) return;
    const user = allUsers.find(u => u.uid === uid);
    if (!user) return;
    if (user.uid === currentUser.uid && user.role === 'owner') {
        showToast("You cannot change your own owner role.", 'warning');
        renderUsersView();
        return;
    }
    const oldRole = user.role;
    if (oldRole === newRole) return;

    const before = roleLabel(oldRole);
    const after  = roleLabel(newRole);

    // Super Admin is unrestricted by design and can manage every other account,
    // so granting it deserves a deliberate yes.
    if (newRole === 'owner' &&
        !confirm(`Make ${user.email} a Super Admin?\n\nA Super Admin has full access to all data and can change or delete other accounts, including revoking your access. Only grant this to someone you fully trust.`)) {
        renderUsersView();
        return;
    }
    if (oldRole === 'owner' &&
        !confirm(`Demote ${user.email} from Super Admin to ${after}?\n\nTheir access will then follow the per-menu settings, and the new role grants no access until you set it.`
            + (isUnitScoped({ ...user, role: newRole }) ? `\n\nTheir stored unit group then applies: ${unitScopeLabel(effectiveUnitScope({ ...user, role: newRole }))}.` : ''))) {
        renderUsersView();
        return;
    }

    try {
        await window.cloud.updateUserRole(uid, newRole, 'active', currentUserDoc.email);
        logEvent({
            action: 'role-change',
            unitId: uid,
            unitName: `[User] ${user.displayName || user.email}`,
            field: 'role',
            before,
            after
        });
        const needsAccess = newRole !== 'owner' &&
            ACCESS_AREAS.every(a => effectiveAccess(a.key, { ...user, role: newRole }) === 'none');
        showToast(needsAccess
            ? `${user.email} is now ${after} — no access yet, set it with the Access button`
            : `${user.email} is now ${after}`, 'success');
    } catch (e) {
        showToast('Failed to change role — ' + e.message, 'error');
    }
}

// Owner-initiated remote sign-out. Writes a session id no device can match,
// so whoever is signed in is dropped on their next snapshot.
async function forceSignOutUser(uid) {
    if (!isOwner()) return;
    const user = allUsers.find(u => u.uid === uid);
    if (!user) return;
    if (currentUser && uid === currentUser.uid) {
        showToast('Use the account menu to sign out of this device', 'warning');
        return;
    }
    const sess = user.activeSession;
    // A revoked slot carries "Signed out by …" in its device field: not a
    // device, so it is neither shown as one nor logged as the one signed out.
    const live = sess && sess.id && !String(sess.id).startsWith('revoked_');
    const where = (live && sess.device) ? `\n\nActive device: ${sess.device}` : '';
    if (!confirm(`Sign ${user.email} out of all devices?${where}\n\nThey will have to sign in again. Their data is not deleted.`)) return;
    try {
        const fn = cloudFn('revokeUserSession');
        if (!fn) return;
        await fn(uid, currentUserDoc.email);
        logEvent({
            action: 'update',
            unitId: uid,
            unitName: `[User] ${user.displayName || user.email}`,
            field: 'Session',
            before: (live && sess.device) || 'active',
            after: 'signed out'
        });
        showToast(`${user.email} signed out of all devices`, 'success');
    } catch (e) {
        showToast('Failed to end session — ' + e.message, 'error');
    }
}

async function removeUser(uid) {
    if (!isOwner()) return;
    const user = allUsers.find(u => u.uid === uid);
    if (!user) return;
    if (user.role === 'owner') { showToast('The owner cannot be removed', 'warning'); return; }
    if (!confirm(`Remove ${user.email} from the dashboard?\n\nTheir Firebase account remains, but they lose all access.`)) return;
    try {
        await window.cloud.deleteUserDoc(uid);
        logEvent({
            action: 'remove',
            unitId: uid,
            unitName: `[User] ${user.displayName || user.email}`,
            before: user.role,
            after: 'removed'
        });
        showToast(`${user.email} removed`, 'success');
    } catch (e) {
        showToast('Failed to remove user — ' + e.message, 'error');
    }
}

// ============================================================
// CLOUD-READY HOOK
// ============================================================
// Cloud sync used to start as soon as the SDK was ready. Now it waits for
// the auth state to be known, so Firestore reads happen with a logged-in user.

function maybeInitCloudSync() {
    if (_cloudReadyFired && _localDataLoaded && currentUser && currentUserDoc?.status === 'active') {
        initCloudSync();
        ensureUsersSubscription();
    }
}

// ============================================================
// TEAM OPERATIONS — members, shift schedule, daily work logs
// ------------------------------------------------------------
// All three collections are cloud-only (like userCategories and
// damageComponents): there is no legacy local data to migrate, so Firestore
// stays the single source of truth and its IndexedDB persistence covers
// offline reads. Each part is gated by its own access area: teamShift for the
// schedule, teamLog for the daily reports, teamMembers for the roster.
// ============================================================

const SHIFT_TYPES = [
    { key: 'pagi',  label: 'Morning',  hours: '07:00–15:00' },
    { key: 'siang', label: 'Afternoon', hours: '15:00–23:00' },
    { key: 'malam', label: 'Night', hours: '23:00–07:00' },
    { key: 'libur', label: 'Off', hours: '—' }
];
const SHIFT_LABEL = SHIFT_TYPES.reduce((m, s) => { m[s.key] = s.label; return m; }, {});
const DAY_NAMES = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
const MONTH_NAMES = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

let teamTab = 'shift';      // 'shift' | 'worklog'
let teamWeekStart = null;   // ISO date of the Monday of the visible week

// ---- Week helpers (all local-date, via parseLocalDate/toISODate) ----
function startOfWeekISO(dateLike) {
    const d = parseLocalDate(dateLike) || new Date();
    d.setDate(d.getDate() - ((d.getDay() + 6) % 7)); // Monday = 0
    return toISODate(d);
}

function addDaysISO(iso, n) {
    const d = parseLocalDate(iso);
    if (!d) return iso;
    d.setDate(d.getDate() + n);
    return toISODate(d);
}

function weekDates(startIso) {
    return Array.from({ length: 7 }, (_, i) => addDaysISO(startIso, i));
}

function dayLabel(iso) {
    const d = parseLocalDate(iso);
    return d ? `${DAY_NAMES[d.getDay()]} ${d.getDate()}` : iso;
}

function weekRangeLabel(startIso) {
    const a = parseLocalDate(startIso);
    const b = parseLocalDate(addDaysISO(startIso, 6));
    if (!a || !b) return '';
    const sameMonth = a.getMonth() === b.getMonth() && a.getFullYear() === b.getFullYear();
    return sameMonth
        ? `${a.getDate()} – ${b.getDate()} ${MONTH_NAMES[b.getMonth()]} ${b.getFullYear()}`
        : `${a.getDate()} ${MONTH_NAMES[a.getMonth()]} – ${b.getDate()} ${MONTH_NAMES[b.getMonth()]} ${b.getFullYear()}`;
}

// ---- Member helpers ----
function generateMemberId() {
    return 'tm_' + Date.now() + '_' + Math.random().toString(36).substr(2, 5);
}

function generateWorkLogId() {
    return 'wl_' + Date.now() + '_' + Math.random().toString(36).substr(2, 5);
}

// ---- Field documentation photos ----
// A work log carries several photos in one Firestore document, so each gets a
// far tighter budget than the single damage photo: 4 × 200KB leaves headroom
// under the 1MB document limit even with a long description alongside.
const WORKLOG_PHOTO_MAX = 4;
const WORKLOG_PHOTO_OPTS = { maxDim: 1024, maxBytes: 200 * 1024, quality: 0.7 };

// Above this, a shift that wraps past midnight is more likely a typo than a
// real night shift, so we ask. Not a hard limit — a genuine long shift must
// still be recordable.
const WORKLOG_LONG_SHIFT_MIN = 16 * 60;
const WORKLOG_PHOTOS_TOTAL_BYTES = 800 * 1024;

// Photos live in their own collection, one document per report, fetched only
// when somebody opens them. They used to sit inside the work log itself — and
// since subscribeWorkLogs streams the whole collection with no limit(), that
// meant every device re-downloaded every photo ever taken, on every app open.
// Measured: one field photo compresses to ~96KB, so an eight-person team was
// pulling roughly 33MB a month back down the wire for nothing.
//
// The report keeps only photoCount, so the table can still show how many there
// are without loading a single byte of image.
const _wlPhotoCache = new Map();   // logId -> data URLs

function workLogPhotoCount(rec) {
    if (!rec) return 0;
    // Reports written before the split still carry their photos inline.
    // An empty array means the inline copy was cleared on migration, so fall
    // through to photoCount rather than reporting zero.
    if (Array.isArray(rec.photos) && rec.photos.length) return rec.photos.length;
    return Number(rec.photoCount) || 0;
}

// Inline (old shape) → cache → one getDoc. Rejects when offline and the
// document was never cached; callers surface that rather than spinning.
async function loadWorkLogPhotos(id) {
    const rec = workLogs.find(w => w.id === id);
    if (rec && Array.isArray(rec.photos) && rec.photos.length) return rec.photos.slice();
    if (_wlPhotoCache.has(id)) return _wlPhotoCache.get(id).slice();
    if (!window.cloud || !window.cloud.getWorkLogPhotos) return [];
    const photos = await window.cloud.getWorkLogPhotos(id);
    _wlPhotoCache.set(id, photos);
    return photos.slice();
}

// ---- Multiple units per report ----
// Reports used to carry one unit (unitId/unitName/sn). They now carry a list,
// and this reads either shape so existing rows keep working.
function workLogUnits(rec) {
    if (rec && Array.isArray(rec.units) && rec.units.length) return rec.units;
    if (rec && rec.unitId) return [{ id: rec.unitId, name: rec.unitName || '', sn: rec.sn || '' }];
    return [];
}

// Display names, preferring the live unit record over the stored copy so a
// renamed unit reads correctly on old reports.
function workLogUnitNames(rec) {
    return workLogUnits(rec).map(u => {
        const live = liveUnitFor({ unitId: u.id, sn: u.sn });
        return live ? (live.name || '') : (u.name || '');
    }).filter(Boolean);
}

// ---- Report approval ----
// Three states, because two would leave a rejected report with nowhere to go:
// the person who filed it would never learn what to fix.
const APPROVAL_STATES = {
    draft:    { label: 'Draft',        tone: 'muted'   },
    pending:  { label: 'Pending',      tone: 'warning' },
    approved: { label: 'Approved',     tone: 'success' },
    revision: { label: 'Needs Revision', tone: 'danger'  }
};

// Reports written before approval existed carry no field; they have genuinely
// never been checked, so they read as pending rather than as approved.
function workLogApproval(w) {
    const a = w && w.approval;
    return APPROVAL_STATES[a] ? a : 'pending';
}

// ---- Submission workflow ----
// Draf → Kirim → Menunggu → Disetujui, or back to the author as Perlu Revisi.
// Only a draft or a record sent back can be changed: a pending record is
// with the checker (the author may withdraw it to a draft first), and an
// approved one stays as approved unless the checker reopens it with a
// revision request. The owner is exempt, as everywhere else. firestore.rules
// enforces the same transitions — these only decide what the screen offers.
function approvalOpen(rec) {
    const st = workLogApproval(rec);
    return st === 'draft' || st === 'revision';
}

function myUid() {
    return (currentUser && currentUser.uid) || '';
}

function isMyRecord(rec) {
    return !!(rec && rec.createdByUid && myUid() && rec.createdByUid === myUid());
}

// A draft has not been handed in: it does not count as a report filed, an
// hour worked or a day off — and it is nobody else's business yet.
function isSubmitted(rec) {
    return workLogApproval(rec) !== 'draft';
}

function visibleToMe(rec) {
    return isSubmitted(rec) || isOwner() || isMyRecord(rec) || !rec.createdByUid;
}

// `areas` names the grants behind a record kind: the daily report and leave
// use teamLog / teamLogApprove, heavy-equipment checks use inspection /
// inspectionApprove. Same flow, same rules, different people.
const TEAM_AREAS = { edit: 'teamLog', approve: 'teamLogApprove' };

function canEditTeamRecord(rec, areas = TEAM_AREAS) {
    if (!hasAccess(areas.edit, 'edit')) return false;
    return isOwner() || approvalOpen(rec);
}

// Withdrawing belongs to whoever sent it. Records from before authors were
// recorded have no sender to match, so any editor may pull those back.
function canWithdrawTeamRecord(rec, areas = TEAM_AREAS) {
    if (!hasAccess(areas.edit, 'edit') || workLogApproval(rec) !== 'pending') return false;
    return isOwner() || !rec.createdByUid || isMyRecord(rec);
}

// Why the edit button is shut, in the words the person needs.
function lockedReason(rec, noun, areas = TEAM_AREAS) {
    const st = workLogApproval(rec);
    if (st === 'pending') {
        return canWithdrawTeamRecord(rec, areas)
            ? `${noun} is pending approval — withdraw it first to change it`
            : `${noun} is pending approval and cannot be changed yet`;
    }
    if (st === 'approved') return `${noun} is already approved — ask a supervisor to reopen it with Request Revision`;
    return '';
}

function canApproveWorkLogs(areas = TEAM_AREAS) {
    return hasAccess(areas.approve, 'edit');
}

// Checking your own work is not a check. Blocked on the account that filed the
// report AND on the account that sent this version of it: an open record (a
// draft, or one sent back) may be changed by any editor, so the filer alone
// does not say whose words are waiting — someone holding both grants could
// otherwise rewrite a colleague's sent-back report, send it, and approve it.
// Not blocked on the team member it is about — an admin may legitimately file
// on someone else's behalf. Owners are exempt so a one-person setup is not
// deadlocked. firestore.rules holds the same line, and since v149 refuses a
// new record without its author — so a record with none is an old one, from
// before authors were recorded, and stays checkable as it always was.
//
// Returns why the signed-in account may not check `w`, or '' when it may.
function selfCheckBlock(w) {
    const me = myUid();
    if (!w || !me) return 'unknown';
    if (w.createdByUid && w.createdByUid === me) return 'filed';
    if (w.submittedByUid && w.submittedByUid === me) return 'sent';
    return '';
}

function canApproveThisLog(w, areas = TEAM_AREAS) {
    if (!canApproveWorkLogs(areas)) return false;
    if (isOwner()) return true;
    return !selfCheckBlock(w);
}

// The refusal in the words the person needs. `verb` is approve / review.
function selfCheckMessage(w, noun, verb) {
    const why = selfCheckBlock(w);
    if (why === 'unknown') return `You must be signed in to ${verb} this ${noun}`;
    if (why === 'sent') return `You submitted this ${noun} yourself — someone else must ${verb} it`;
    return `You filed this ${noun} yourself — someone else must ${verb} it`;
}

// Who sends a record for checking signs as its sender (firestore.rules checks
// it is the signed-in account). A draft has not been sent, so it keeps
// whatever an earlier round recorded.
function submittedByFor(existing, asDraft) {
    if (!asDraft) return myUid();
    return (existing && existing.submittedByUid) || '';
}

// ---- Paddock area ----
// Free text with suggestions gathered from what has already been entered, the
// same approach as company names.
function allPaddocks() {
    const seen = new Map();
    workLogs.forEach(w => {
        const p = ((w && w.paddock) || '').trim();
        if (p && !seen.has(p.toLowerCase())) seen.set(p.toLowerCase(), p);
    });
    return [...seen.values()].sort((a, b) => a.localeCompare(b));
}

// The form lists active members only, but a record may belong to someone who
// has since left. Without their option the select silently falls back to
// "— Pilih anggota —", and the record cannot be saved at all.
function ensureMemberOption(selId, memberId) {
    const sel = document.getElementById(selId);
    if (!sel || !memberId) return;
    if (![...sel.options].some(o => o.value === memberId)) {
        const m = memberById(memberId);
        if (!m) return;
        const opt = document.createElement('option');
        opt.value = memberId;
        opt.textContent = `${m.name || '(unnamed)'} (inactive)`;
        sel.appendChild(opt);
    }
    sel.value = memberId;
}

function activeMembers() {
    return teamMembers.filter(m => m.active !== false);
}

// ---- Companies ----
// Free text on the member record with suggestions, rather than a fixed list:
// a third company can be added by typing it, without a code change.
const DEFAULT_COMPANIES = ['PT. Global Papua Abadi', 'PT. Murni Nusantara Mandiri'];
const NO_COMPANY = '(No company)';

function companyOf(m) {
    return canonicalCompany((m && m.company) || '');
}

// One spelling per company, whatever the case: "pt. global papua abadi" and
// "PT. Global Papua Abadi" split the recap, the shift grid and the filters
// into two companies, and filtering by one dropped the other's reports.
function canonicalCompany(raw) {
    const c = String(raw || '').trim().replace(/\s+/g, ' ');
    const k = c.toLowerCase();
    if (!k) return '';
    const d = DEFAULT_COMPANIES.find(x => x.toLowerCase() === k);
    if (d) return d;
    const m = teamMembers.find(x => String(x.company || '').trim().replace(/\s+/g, ' ').toLowerCase() === k);
    return m ? String(m.company).trim().replace(/\s+/g, ' ') : c;
}

// The two seeded names plus anything already typed, de-duplicated
// case-insensitively so "PT. Global" and "pt. global" do not split a group.
function allCompanies() {
    const seen = new Map();
    DEFAULT_COMPANIES.forEach(c => seen.set(c.toLowerCase(), c));
    teamMembers.forEach(m => {
        const c = companyOf(m);
        if (c && !seen.has(c.toLowerCase())) seen.set(c.toLowerCase(), c);
    });
    return [...seen.values()].sort((a, b) => a.localeCompare(b));
}

// Active members grouped by company, named companies first (alphabetical) and
// anyone without one collected at the end rather than silently hidden.
function membersByCompany() {
    const groups = new Map();
    activeMembers().forEach(m => {
        const key = companyOf(m) || NO_COMPANY;
        if (!groups.has(key)) groups.set(key, []);
        groups.get(key).push(m);
    });
    return [...groups.entries()].sort((a, b) => {
        if (a[0] === NO_COMPANY) return 1;
        if (b[0] === NO_COMPANY) return -1;
        return a[0].localeCompare(b[0]);
    });
}

// Company for a work log: the member's current one, falling back to the value
// stored on the record so rows survive a member being deleted or moved.
function companyOfRecord(rec) {
    const m = rec && rec.memberId ? memberById(rec.memberId) : null;
    return m ? companyOf(m) : canonicalCompany((rec && rec.company) || '');
}

function memberById(id) {
    return teamMembers.find(m => m.id === id) || null;
}

// Name for display: live member record first, then the name denormalized onto
// the record, so a deleted member still reads correctly in old rows.
function memberNameOf(rec) {
    const m = rec && rec.memberId ? memberById(rec.memberId) : null;
    return m ? m.name : ((rec && rec.memberName) || '(deleted member)');
}

// ---- Cloud snapshots ----
function applyCloudTeamMembersSnapshot(list) {
    _markLoaded('teamMembers');
    teamMembers = (list || []).slice().sort((a, b) =>
        (a.name || '').localeCompare(b.name || ''));
    // Company suggestions and the report filter are derived from the roster,
    // so they have to be rebuilt whenever it changes.
    if (currentView === 'team') { populateWorkLogFilters(); renderTeamView(); }
    const modal = document.getElementById('teamMembersModal');
    if (modal && modal.classList.contains('open')) renderTeamMembersList();
}

function applyCloudShiftsSnapshot(list) {
    _markLoaded('shifts');
    reportShiftOverwrites(list);
    teamShifts = list || [];
    if (currentView === 'team' && teamTab === 'shift') renderShiftGrid();
    scheduleDecisionRefresh();
}

function applyCloudWorkLogsSnapshot(list) {
    _markLoaded('workLogs');
    workLogs = (list || []).slice().sort((a, b) =>
        String(b.date || '').localeCompare(String(a.date || '')) ||
        ((b.createdAt || 0) - (a.createdAt || 0)));
    if (currentView === 'team') {
        populateWorkLogFilters();
        if (teamTab === 'worklog') renderWorkLogTable();
    }
    scheduleDecisionRefresh();
    migrateWorkLogPhotosIfNeeded();
}

// One-shot migration: move photos that still sit inside a work log out to
// workLogPhotos/{id}. Same shape as applyLicenseDatesIfNeeded() above —
// owner only, guarded by a localStorage flag so it never runs twice.
//
// Order matters: the photo document is written FIRST and the inline copy is
// cleared only after that write is acknowledged. Interrupted halfway, the
// worst case is a report that has its photos in both places — which reads
// correctly either way — never one that has them in neither.
//
// Done now, while the feature is days old and the data is small. Every month
// this waits, the migration gets more expensive and the daily waste gets
// bigger.
let _wlPhotoMigrationRunning = false;
function migrateWorkLogPhotosIfNeeded() {
    if (_wlPhotoMigrationRunning) return;
    if (!isOwner || !isOwner()) return;
    if (localStorage.getItem(WL_PHOTOS_SPLIT_KEY) === '1') return;
    if (!window.cloud || !window.cloud.saveWorkLogPhotos) return;
    if (!Array.isArray(workLogs) || workLogs.length === 0) return;

    const pending = workLogs.filter(w => Array.isArray(w.photos) && w.photos.length);
    if (pending.length === 0) {
        localStorage.setItem(WL_PHOTOS_SPLIT_KEY, '1');
        return;
    }
    if (!navigator.onLine) return;   // retried on the next snapshot

    _wlPhotoMigrationRunning = true;
    console.log(`[wl-photos] moving photos out of ${pending.length} work logs...`);
    (async () => {
        let moved = 0;
        for (const w of pending) {
            const photos = w.photos.slice();
            await window.cloud.saveWorkLogPhotos(w.id, photos);
            _wlPhotoCache.set(w.id, photos);
            await window.cloud.saveWorkLog({ ...w, photos: [], photoCount: photos.length });
            moved++;
        }
        return moved;
    })().then(moved => {
        localStorage.setItem(WL_PHOTOS_SPLIT_KEY, '1');
        try {
            logEvent({
                action: 'migrate',
                unitName: '-',
                field: 'report photos',
                after: `${moved} report(s) moved to the workLogPhotos collection`
            });
        } catch (e) {}
        console.log(`[wl-photos] done — ${moved} work logs migrated`);
    }).catch(err => {
        // No flag set, so the next snapshot tries again from where it stopped.
        console.error('[wl-photos] migration failed:', err);
        if (err && err.code === 'permission-denied') showTeamRulesBanner();
    }).finally(() => {
        _wlPhotoMigrationRunning = false;
    });
}

function showTeamRulesBanner() {
    const slot = document.querySelector('.team-rules-slot');
    if (!slot || slot.querySelector('.category-rules-banner')) return;
    const banner = document.createElement('div');
    banner.className = 'category-rules-banner';
    banner.innerHTML = `
        <strong><i class="fas fa-triangle-exclamation"></i> Firestore rules are blocking Team data.</strong>
        <p>Your project's rules do not yet allow access to the <code>teamMembers</code>,
        <code>shifts</code> and <code>workLogs</code> collections. Republish the
        <code>firestore.rules</code> file from this repo in
        <em>Firebase Console → Firestore → Rules</em>, then reload the page.</p>`;
    slot.appendChild(banner);
}

// ---- View shell ----
// One map instead of the ternary that used to be here. That ternary read
// `tab === 'shift' ? canShift : canLog`, so anything that was not 'shift' fell
// through to canLog — correct by accident for two tabs, and silently wrong for
// the next one.
const TEAM_TABS = {
    shift:   { area: 'teamShift', panel: 'teamShiftPanel',   render: () => renderShiftGrid() },
    worklog: { area: 'teamLog',   panel: 'teamWorkLogPanel', render: () => renderWorkLogTable() },
    leave:   { area: 'teamLog',   panel: 'teamLeavePanel',   render: () => renderLeaveTable() }
};

function switchTeamTab(tab) {
    teamTab = TEAM_TABS[tab] ? tab : 'shift';
    renderTeamView();
}

function renderTeamView() {
    const canTab = key => {
        const t = TEAM_TABS[key];
        if (!t) return false;
        // An approver may hold teamLogApprove WITHOUT teamLog — the rules
        // support exactly that split. Without this the inbox sent them to
        // approve reports and requests on a tab they could not open.
        if (t.area === 'teamLog' && hasAccess('teamLogApprove', 'edit')) return true;
        return hasAccess(t.area, 'view');
    };
    const canMembers = hasAccess('teamMembers', 'view');
    const anyTab = Object.keys(TEAM_TABS).some(canTab);

    // Land on a tab the user can actually open — the page is reachable through
    // any one of the areas, so the stored tab may not be permitted.
    if (!canTab(teamTab)) {
        teamTab = Object.keys(TEAM_TABS).find(canTab) || teamTab;
    }

    // Scoped to this page. Kotak Keputusan and Gudang reuse the .team-tab
    // class for styling, and an unscoped sweep hid every one of their tabs the
    // moment anyone opened Tim — canTab() knows nothing about 'inbox' or
    // 'devices', so it answered false for all of them.
    document.querySelectorAll('#viewTeam .team-tab').forEach(btn => {
        const key = btn.dataset.tab;
        const allowed = canTab(key);
        btn.style.display = allowed ? '' : 'none';
        const on = allowed && key === teamTab;
        btn.classList.toggle('active', on);
        btn.setAttribute('aria-selected', on ? 'true' : 'false');
    });

    const membersBtn = document.getElementById('btnTeamMembers');
    if (membersBtn) membersBtn.style.display = canMembers ? '' : 'none';

    Object.entries(TEAM_TABS).forEach(([key, t]) => {
        const panel = document.getElementById(t.panel);
        if (panel) panel.style.display = (canTab(key) && key === teamTab) ? '' : 'none';
    });

    // Reachable via Daftar Anggota alone — no tab is permitted, so say so
    // instead of showing blank panels.
    const emptyPanel = document.getElementById('teamNoPanel');
    if (emptyPanel) emptyPanel.style.display = anyTab ? 'none' : '';

    const active = TEAM_TABS[teamTab];
    if (active && canTab(teamTab)) active.render();
    updateMyTeamNotices();
}

// ============================================================
// SHIFT SCHEDULE
// ============================================================

function shiftFor(memberId, date) {
    const rec = teamShifts.find(s => s.id === `${date}_${memberId}`);
    // Only a known shift key: the value becomes part of a class name, and a
    // stored "pagi\"><img onerror=…>" would otherwise break out of it.
    return rec && Object.prototype.hasOwnProperty.call(SHIFT_LABEL, rec.shift) ? rec.shift : '';
}

// "Diisi Budi · 14 Sep 09:12" for the cell tooltip. Two people can edit the
// same cell and the last one wins, so who set it is worth being able to see
// without opening History.
function shiftSetByLabel(memberId, date) {
    const rec = teamShifts.find(s => s.id === `${date}_${memberId}`);
    if (!rec || !rec.updatedBy) return '';
    const when = rec.updatedAt ? new Date(rec.updatedAt).toLocaleString('en-GB',
        { day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' }) : '';
    return `Set by ${rec.updatedBy}${when ? ' · ' + when : ''}`;
}

// ---- Shift subscription window ----
// One document per person per day, forever: eight people make ~2,900 a year,
// ~8,800 by year three, and every one of them was pulled down to draw a single
// week. The listener now covers a rolling window instead, and widens itself if
// somebody pages back past the edge — so the schedule still works however far
// back they go, it just fetches that range when they ask for it.
const SHIFT_WINDOW_DAYS = 120;   // roughly four months back
let _shiftWindowStart = '';

function shiftWindowFor(weekStart) {
    const byToday = addDaysISO(toISODate(), -SHIFT_WINDOW_DAYS);
    const byWeek = addDaysISO(weekStart || toISODate(), -28);
    return byWeek < byToday ? byWeek : byToday;
}

function startShiftsSubscription(weekStart) {
    if (!window.cloud || !window.cloud.subscribeShifts) return;
    _shiftWindowStart = shiftWindowFor(weekStart || teamWeekStart);
    if (cloudShiftsUnsub) { try { cloudShiftsUnsub(); } catch (_) {} cloudShiftsUnsub = null; }
    cloudShiftsUnsub = window.cloud.subscribeShifts(
        applyCloudShiftsSnapshot,
        err => {
            console.warn('[cloud] shifts offline:', err && err.code);
            if (err && err.code === 'permission-denied') showTeamRulesBanner();
        },
        _shiftWindowStart
    );
}

// Called before rendering a week: if it falls outside what the listener
// covers, widen and resubscribe. Without this the grid would quietly render
// an empty week that actually has shifts in it.
function ensureShiftWindowCovers(weekStart) {
    if (!_shiftWindowStart || !weekStart) return;
    if (weekStart >= _shiftWindowStart) return;
    console.log(`[shifts] widening window back to cover ${weekStart}`);
    startShiftsSubscription(weekStart);
}

function shiftWeekShift(delta) {
    if (!teamWeekStart) teamWeekStart = startOfWeekISO(toISODate());
    teamWeekStart = addDaysISO(teamWeekStart, delta * 7);
    ensureShiftWindowCovers(teamWeekStart);
    renderShiftGrid();
}

function shiftWeekToday() {
    teamWeekStart = startOfWeekISO(toISODate());
    renderShiftGrid();
}

function renderShiftGrid() {
    if (!teamWeekStart) teamWeekStart = startOfWeekISO(toISODate());
    const dates = weekDates(teamWeekStart);
    const today = toISODate();
    const canEdit = hasAccess('teamShift', 'edit');

    const label = document.getElementById('shiftWeekLabel');
    if (label) label.textContent = weekRangeLabel(teamWeekStart);

    const head = document.getElementById('shiftHead');
    if (head) {
        head.innerHTML = `<tr><th class="shift-grid__member">Member</th>${
            dates.map(d => `<th class="${d === today ? 'is-today' : ''}">${escapeHtml(dayLabel(d))}</th>`).join('')
        }</tr>`;
    }

    const body = document.getElementById('shiftBody');
    const foot = document.getElementById('shiftFoot');
    if (!body) return;

    const members = activeMembers();
    if (members.length === 0) {
        body.innerHTML = `<tr><td colspan="8" style="text-align:center;padding:24px;color:var(--text-secondary)">
            No active team members yet. Click <strong>Manage Members</strong> to add some.
        </td></tr>`;
        if (foot) foot.innerHTML = '';
        return;
    }

    // Per-day duty counts for a set of members; 'libur' is time off, not duty.
    const dutyCells = (list, extraClass) => dates.map(d => {
        // Someone on APPROVED leave is not on duty, whatever the schedule says
        // — the same rule weekStats().onDuty already follows.
        const counts = SHIFT_TYPES.filter(s => s.key !== 'libur')
            .map(s => ({ s, n: list.filter(m => shiftFor(m.id, d) === s.key && !leaveOn(m.id, d)).length }));
        const working = counts.reduce((a, c) => a + c.n, 0);
        const detail = counts.map(c => `${c.s.label} ${c.n}`).join(' · ');
        return `<td class="${extraClass}${d === today ? ' is-today' : ''}" title="${escapeHtml(detail)}">
            <strong>${working}</strong> <span class="shift-foot__detail">${escapeHtml(detail)}</span>
        </td>`;
    }).join('');

    const memberRow = m => {
        const cells = dates.map(d => {
            const cur = shiftFor(m.id, d);
            const cls = `shift-cell${cur ? ' shift-cell--' + cur : ''}${d === today ? ' is-today' : ''}`;
            const by = shiftSetByLabel(m.id, d);
            // Izin/sakit yang sudah disetujui ditandai DI SAMPING pilihan
            // shift, tidak menggantikannya. Menulis otomatis ke koleksi shifts
            // akan menimpa jadwal yang sudah diisi — dan koleksi itu berjendela
            // 120 hari, jadi izin yang lebih lama tidak punya sel untuk ditulisi
            // sama sekali. Jadwalnya tetap milik penyusun jadwal.
            const lv = leaveOn(m.id, d);
            const lvBadge = lv
                ? `<span class="shift-leave shift-leave--${escapeHtml(lv.type || 'izin')}">${escapeHtml(leaveTypeLabel(lv))}</span>`
                : '';
            const lvNote = lv
                ? `${leaveTypeLabel(lv)} ${leaveRangeLabel(lv)}${lv.reason ? ' — ' + lv.reason : ''}`
                : '';
            const tip = [by, lvNote].filter(Boolean).join(' · ');
            const byAttr = tip ? ` title="${escapeHtml(tip)}"` : '';
            if (!canEdit) {
                return `<td class="${cls}"${byAttr}>${lvBadge}${cur
                    ? `<span class="shift-badge shift-badge--${cur}">${escapeHtml(SHIFT_LABEL[cur] || cur)}</span>`
                    : '<span class="shift-empty">—</span>'}</td>`;
            }
            const opts = ['<option value="">—</option>'].concat(
                SHIFT_TYPES.map(s =>
                    `<option value="${s.key}"${s.key === cur ? ' selected' : ''}>${escapeHtml(s.label)}</option>`)
            ).join('');
            return `<td class="${cls}"${byAttr}>${lvBadge}
                <select class="shift-select shift-select--${cur || 'none'}"
                        aria-label="Shift ${escapeHtml(m.name)} on ${escapeHtml(d)}"
                        onchange="setShift(${jsArg(m.id)},${jsArg(d)},this.value)">${opts}</select>
            </td>`;
        }).join('');
        const fill = canEdit ? `<select class="shift-fill" aria-label="Fill the week for ${escapeHtml(m.name)}"
                title="Fill the whole week in one click" onchange="quickFillShiftRow(${jsArg(m.id)}, this.value); this.value=''">
                <option value="">Fill week…</option>
                ${SHIFT_FILL_PATTERNS.map(p => `<option value="${p.key}">${escapeHtml(p.label)}</option>`).join('')}
            </select>` : '';
        return `<tr>
            <th scope="row" class="shift-grid__member">
                <strong>${escapeHtml(m.name)}</strong>
                ${m.jobTitle ? `<span class="shift-grid__job" title="${escapeHtml(m.jobTitle)}">${escapeHtml(m.jobTitle)}</span>` : ''}
                ${fill}
            </th>${cells}
        </tr>`;
    };

    // One block per company: a heading row carrying that company's own duty
    // counts, then its members.
    body.innerHTML = membersByCompany().map(([company, list]) => `
        <tr class="shift-group">
            <th scope="row" class="shift-grid__member shift-group__name">
                ${escapeHtml(company)}
                <span class="shift-group__count">${list.length} people</span>
            </th>${dutyCells(list, 'shift-group__cell')}
        </tr>
        ${list.map(memberRow).join('')}`).join('');

    if (foot) {
        foot.innerHTML = `<tr><th scope="row" class="shift-grid__member">Total on duty</th>${
            dutyCells(members, '')
        }</tr>`;
    }
}

// Cells this device has written and not yet seen confirmed. See setShift.
const _shiftPendingWrites = new Map();
const SHIFT_CLAIM_MS = 60000;

function shiftActorName() {
    if (!currentUser) return '';
    return (currentUserDoc && currentUserDoc.displayName)
        || currentUser.displayName
        || (currentUser.email || '').split('@')[0]
        || '';
}

// Compare the snapshot against what we just wrote. Anything that came back
// different, from somebody else, is an overwrite the person needs to be told
// about — silently flipping the grid under them is how a supervisor ends up
// believing a shift is set when it is not.
function reportShiftOverwrites(list) {
    if (_shiftPendingWrites.size === 0) return;
    const now = Date.now();
    const byId = new Map((list || []).map(s => [s.id, s]));
    const myUid = (currentUser && currentUser.uid) || '';
    _shiftPendingWrites.forEach((mine, id) => {
        if (now - mine.at > SHIFT_CLAIM_MS) { _shiftPendingWrites.delete(id); return; }
        if (!byId.has(id) && mine.shift === '') { _shiftPendingWrites.delete(id); return; }
        const server = byId.get(id);
        const serverShift = server ? (server.shift || '') : '';
        if (serverShift === mine.shift) { _shiftPendingWrites.delete(id); return; }
        // Different value — but only shout if somebody else put it there.
        // Our own pending write simply has not landed yet.
        if (server && server.updatedByUid && server.updatedByUid !== myUid) {
            const who = server.updatedBy || 'someone else';
            const label = serverShift ? (SHIFT_LABEL[serverShift] || serverShift) : 'empty';
            showToast(`${who} just changed the schedule for ${mine.memberName} on ${mine.date} to ${label}`, 'warning');
            _shiftPendingWrites.delete(id);
        }
    });
}

function setShift(memberId, date, shiftKey) {
    if (!requireEdit('teamShift')) { renderShiftGrid(); return; }
    const m = memberById(memberId);
    if (!m) return;

    const id = `${date}_${memberId}`;
    const prev = teamShifts.find(s => s.id === id) || null;
    if ((prev ? prev.shift : '') === (shiftKey || '')) return;

    const before = prev ? (SHIFT_LABEL[prev.shift] || prev.shift) : '—';
    const after = shiftKey ? (SHIFT_LABEL[shiftKey] || shiftKey) : '—';

    // Optimistic update so the grid responds instantly. Replace rather than
    // mutate, so the rollback snapshot stays a valid earlier state.
    const snapshot = teamShifts.slice();
    teamShifts = teamShifts.filter(s => s.id !== id);
    const rec = shiftKey ? {
        id, date, memberId,
        memberName: m.name,
        shift: shiftKey,
        createdAt: prev ? (prev.createdAt || Date.now()) : Date.now(),
        updatedAt: Date.now(),
        // Who last touched this cell. The shift document id is deterministic
        // (`${date}_${memberId}`), so two supervisors editing the same person
        // on the same day write the same document and the later one wins with
        // no warning to either. A real merge needs transactions and is bigger
        // than the problem; knowing you were overwritten is what was missing.
        updatedBy: shiftActorName(),
        updatedByUid: (currentUser && currentUser.uid) || ''
    } : null;
    if (rec) teamShifts.push(rec);
    // Remember what we just sent, so the snapshot coming back can be compared
    // against it. Cleared as soon as it is checked, or after SHIFT_CLAIM_MS.
    _shiftPendingWrites.set(id, {
        shift: shiftKey || '', at: Date.now(),
        memberName: m.name, date
    });
    renderShiftGrid();

    if (!window.cloud || !window.cloud.saveShift) {
        showToast('Cloud not ready — shift change not saved', 'warning');
        teamShifts = snapshot;
        renderShiftGrid();
        return;
    }

    cloudWrite(
        { action: 'update', unitName: `[Team] ${m.name}`, field: `Shift ${date}`, before, after },
        rec ? cloudCall('saveShift', rec) : cloudCall('deleteShift', id),
        null,
        err => {
            console.error('[team] shift save failed:', err);
            _shiftPendingWrites.delete(id);
            teamShifts = snapshot;
            renderShiftGrid();
            if (err && err.code === 'permission-denied') showTeamRulesBanner();
            showToast('Failed to save shift — change reverted', 'error');
        }
    );
}

// ---- Quick fill ----
// Filling a week cell by cell is 7 clicks per person. A row can be filled
// with one pattern, and the whole week copied from the week before. Each is
// ONE batch write and ONE history row, not one per cell.
const SHIFT_FILL_PATTERNS = [
    { key: 'pagi',  label: 'Morning Mon–Sat · Sun Off' },
    { key: 'siang', label: 'Afternoon Mon–Sat · Sun Off' },
    { key: 'malam', label: 'Night Mon–Sat · Sun Off' },
    { key: 'pagi7',  label: 'Morning every day' },
    { key: 'malam7', label: 'Night every day' },
    { key: 'copy',  label: 'Same as last week' },
    { key: 'clear', label: 'Clear this week' }
];

// changes: [{ memberId, date, shift }] — shift '' clears the cell.
function applyShiftChanges(changes, what) {
    if (!requireEdit('teamShift')) { renderShiftGrid(); return 0; }
    const real = [];
    changes.forEach(c => {
        const m = memberById(c.memberId);
        if (!m) return;
        const id = `${c.date}_${c.memberId}`;
        const prev = teamShifts.find(s => s.id === id) || null;
        if ((prev ? prev.shift : '') === (c.shift || '')) return;
        real.push({ ...c, id, m, prev });
    });
    if (!real.length) { showToast('Nothing to change — the week already looks like that', 'info'); return 0; }

    const snapshot = teamShifts.slice();
    const ids = new Set(real.map(c => c.id));
    teamShifts = teamShifts.filter(s => !ids.has(s.id));
    const sets = [], dels = [];
    const now = Date.now();
    real.forEach(c => {
        if (c.shift) {
            const rec = { id: c.id, date: c.date, memberId: c.memberId, memberName: c.m.name, shift: c.shift,
                createdAt: c.prev ? (c.prev.createdAt || now) : now, updatedAt: now,
                updatedBy: shiftActorName(), updatedByUid: (currentUser && currentUser.uid) || '' };
            teamShifts.push(rec);
            sets.push(rec);
        } else {
            dels.push(c.id);
        }
        _shiftPendingWrites.set(c.id, { shift: c.shift || '', at: now, memberName: c.m.name, date: c.date });
    });
    renderShiftGrid();

    const people = new Set(real.map(c => c.m.name));
    cloudWrite(
        { action: 'update', unitName: people.size === 1 ? `[Team] ${[...people][0]}` : '[Team] Shift schedule',
          field: `Shift ${weekRangeLabel(teamWeekStart)}`, before: '', after: `${what} — ${real.length} cell(s)` },
        cloudCall('saveShiftChanges', sets, dels),
        `${real.length} shift cell(s) saved`,
        err => {
            console.error('[team] shift batch failed:', err);
            real.forEach(c => _shiftPendingWrites.delete(c.id));
            teamShifts = snapshot;
            renderShiftGrid();
            if (err && err.code === 'permission-denied') showTeamRulesBanner();
            showToast('Failed to save the shifts — changes reverted', 'error');
        }
    );
    return real.length;
}

function _lastWeekChanges(members) {
    const dates = weekDates(teamWeekStart);
    const out = [];
    members.forEach(m => dates.forEach(d => {
        const prev = shiftFor(m.id, addDaysISO(d, -7));
        if (prev) out.push({ memberId: m.id, date: d, shift: prev });
    }));
    return out;
}

function quickFillShiftRow(memberId, key) {
    if (!key) return;
    const m = memberById(memberId);
    if (!m) return;
    if (!teamWeekStart) teamWeekStart = startOfWeekISO(toISODate());
    const dates = weekDates(teamWeekStart);
    let changes;
    if (key === 'copy') {
        ensureShiftWindowCovers(addDaysISO(teamWeekStart, -7));
        changes = _lastWeekChanges([m]);
        if (!changes.length) { showToast(`${m.name} has no shifts last week to copy`, 'warning'); renderShiftGrid(); return; }
    } else if (key === 'clear') {
        if (!dates.some(d => shiftFor(m.id, d))) { renderShiftGrid(); return; }
        if (!confirm(`Clear every shift of ${m.name} for ${weekRangeLabel(teamWeekStart)}?`)) { renderShiftGrid(); return; }
        changes = dates.map(d => ({ memberId: m.id, date: d, shift: '' }));
    } else {
        const every = key.endsWith('7');
        const shift = every ? key.slice(0, -1) : key;
        const sunday = d => { const x = parseLocalDate(d); return !!x && x.getDay() === 0; };
        changes = dates.map(d => ({ memberId: m.id, date: d, shift: !every && sunday(d) ? 'libur' : shift }));
    }
    const pat = SHIFT_FILL_PATTERNS.find(p => p.key === key);
    applyShiftChanges(changes, pat ? pat.label : key);
}

function copyLastWeekShifts() {
    if (!requireEdit('teamShift')) return;
    if (!teamWeekStart) teamWeekStart = startOfWeekISO(toISODate());
    ensureShiftWindowCovers(addDaysISO(teamWeekStart, -7));
    const members = activeMembers();
    const changes = _lastWeekChanges(members);
    if (!changes.length) { showToast('Last week has no shifts to copy', 'warning'); return; }
    const differ = changes.filter(c => shiftFor(c.memberId, c.date) !== c.shift);
    if (!differ.length) { showToast('This week already matches last week', 'info'); return; }
    const replaced = differ.filter(c => shiftFor(c.memberId, c.date)).length;
    if (!confirm(`Copy last week's schedule into ${weekRangeLabel(teamWeekStart)}?\n\n`
        + `${differ.length} cell(s) will be filled`
        + (replaced ? `, ${replaced} of them replacing a shift already set this week.` : '.')
        + `\nCells that were empty last week are left as they are.`)) return;
    applyShiftChanges(differ, 'Copied from last week');
}

function exportShiftCSV() {
    if (!canCsv('export')) return;
    const members = activeMembers();
    if (members.length === 0) { showToast('No team members to export yet', 'warning'); return; }
    const dates = weekDates(teamWeekStart || startOfWeekISO(toISODate()));
    const headers = ['Company', 'Member', 'Job Title', ...dates.map(d => `${dayLabel(d)} (${d})`)];
    // Exported in the same company order the grid shows, so the file reads the
    // same way as the screen.
    const rows = membersByCompany().flatMap(([company, list]) => list.map(m => [
        company === NO_COMPANY ? '' : company,
        m.name || '', m.jobTitle || '',
        ...dates.map(d => {
            const s = shiftFor(m.id, d);
            return s ? (SHIFT_LABEL[s] || s) : '';
        })
    ]));
    const csv = toCSV(headers, rows);
    const blob = new Blob(['﻿' + csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `shift_schedule_${dates[0]}_to_${dates[6]}.csv`;
    a.click();
    URL.revokeObjectURL(url);
    showToast(`Exported shift schedule for ${members.length} member(s) to CSV`, 'success');
}

// ============================================================
// TEAM MEMBERS (master list — may include people without an account)
// ============================================================

function openTeamMembersModal() {
    renderTeamMembersList();
    document.getElementById('teamMembersModal').classList.add('open');
}

function closeTeamMembersModal() {
    document.getElementById('teamMembersModal').classList.remove('open');
}

function renderTeamMembersList() {
    const list = document.getElementById('teamMembersList');
    if (!list) return;
    const canEdit = hasAccess('teamMembers', 'edit');
    // Keep the shared company suggestions current — a company typed on one row
    // should be offered on the next.
    const dl = document.getElementById('companyList');
    if (dl) dl.innerHTML = companySuggestions().map(c => `<option value="${escapeHtml(c)}"></option>`).join('');
    if (teamMembers.length === 0) {
        list.innerHTML = `<li class="category-empty">No team members yet.</li>`;
        return;
    }
    list.innerHTML = teamMembers.map(m => `
        <li class="category-item member-item${m.active === false ? ' is-inactive' : ''}">
            <span class="category-item__name member-item__info">
                <strong>${escapeHtml(m.name)}</strong>
                ${(m.jobTitle || m.active === false) ? `<span class="member-item__meta">
                    ${m.jobTitle ? `<span class="member-item__job" title="${escapeHtml(m.jobTitle)}">${escapeHtml(m.jobTitle)}</span>` : ''}
                    ${m.active === false ? '<span class="member-item__off">Inactive</span>' : ''}
                </span>` : ''}
                ${canEdit
                    ? `<input class="form-input member-item__company" list="companyList"
                              value="${escapeHtml(companyOf(m))}" placeholder="Company…" maxlength="80"
                              aria-label="Company of ${escapeHtml(m.name)}"
                              onchange="setMemberCompany(${jsArg(m.id)}, this.value)">`
                    : `<span class="member-item__job">${escapeHtml(companyOf(m) || NO_COMPANY)}</span>`}
            </span>
            ${canEdit ? `<span class="row-actions row-actions--labeled">
                <button class="btn btn-secondary btn-sm" onclick="toggleTeamMember(${jsArg(m.id)})">
                    ${m.active === false ? 'Activate' : 'Deactivate'}
                </button>
                <button class="btn btn-secondary btn-sm row-actions__icon" title="Delete member" aria-label="Delete ${escapeHtml(m.name)}"
                        onclick="deleteTeamMember(${jsArg(m.id)})">
                    <i class="fas fa-trash" style="color:var(--danger)"></i>
                </button>
            </span>` : ''}
        </li>`).join('');
}

// Change one member's company from the roster list. Company is the only field
// editable in place — it is the one that has to be set for people who were
// added before companies existed, and retyping a name would orphan their
// shifts, which are keyed by member id.
function setMemberCompany(id, value) {
    if (!requireEdit('teamMembers')) { renderTeamMembersList(); return; }
    const m = memberById(id);
    if (!m) return;
    const rc = checkMasterValue('company', value, companyOf(m));
    if (!rc.ok) {
        showToast(`Company "${rc.value}" ${masterNotInList('company')}`, 'warning');
        renderTeamMembersList();
        return;
    }
    const company = rc.value;
    const before = companyOf(m);
    if (before === company) { renderTeamMembersList(); return; }

    // Optimistic, like setShift: replace the record rather than mutate it, so
    // the rollback snapshot stays a valid earlier state. Without this the grid
    // and the company suggestions would lag until the Firestore snapshot lands,
    // and a second edit would compare against a stale value.
    const snapshot = teamMembers.slice();
    const rec = { ...m, company, updatedAt: Date.now() };
    teamMembers = teamMembers.map(x => (x.id === id ? rec : x));
    renderTeamMembersList();
    if (currentView === 'team') renderTeamView();

    cloudWrite(
        { action: 'update', unitName: `[Team] ${m.name}`, field: 'Company',
          before: before || '—', after: company || '—' },
        cloudCall('saveTeamMember', rec),
        null,
        err => {
            console.error('[team] company save failed:', err);
            teamMembers = snapshot;
            renderTeamMembersList();
            if (currentView === 'team') renderTeamView();
            if (err && err.code === 'permission-denied') showTeamRulesBanner();
            showToast('Failed to save company — change reverted', 'error');
        }
    );
}

function addTeamMember(event) {
    event.preventDefault();
    if (!requireEdit('teamMembers')) return;
    const nameEl = document.getElementById('newMemberName');
    const jobEl = document.getElementById('newMemberJob');
    const compEl = document.getElementById('newMemberCompany');
    const name = (nameEl.value || '').trim();
    const jobTitle = (jobEl.value || '').trim();
    const rc = checkMasterValue('company', (compEl && compEl.value) || '', null);
    if (!rc.ok) { showToast(`Company "${rc.value}" ${masterNotInList('company')}`, 'warning'); if (compEl) compEl.focus(); return; }
    const company = rc.value;
    if (!name) { showToast('Member name cannot be empty', 'warning'); return; }
    if (teamMembers.some(m => (m.name || '').toLowerCase() === name.toLowerCase())) {
        showToast(`Member "${name}" already exists`, 'warning');
        return;
    }
    const rec = { id: generateMemberId(), name, jobTitle, company, active: true, createdAt: Date.now() };
    cloudWrite(
        { action: 'create', unitName: `[Team] ${name}`, field: 'Member', before: '', after: jobTitle || name },
        cloudCall('saveTeamMember', rec),
        `Member "${name}" added`,
        err => {
            console.error('[team] member save failed:', err);
            if (err && err.code === 'permission-denied') showTeamRulesBanner();
            showToast('Failed to save member', 'error');
        }
    );
    nameEl.value = '';
    jobEl.value = '';
    // The company is deliberately kept: several people from the same company
    // are usually added in a row.
    nameEl.focus();
}

function toggleTeamMember(id) {
    if (!requireEdit('teamMembers')) return;
    const m = memberById(id);
    if (!m) return;
    const nextActive = m.active === false;
    cloudWrite(
        { action: 'update', unitName: `[Team] ${m.name}`, field: 'Member status',
          before: m.active === false ? 'Inactive' : 'Active',
          after: nextActive ? 'Active' : 'Inactive' },
        cloudCall('saveTeamMember', { ...m, active: nextActive, updatedAt: Date.now() }),
        null,
        err => {
            console.error('[team] member toggle failed:', err);
            showToast('Failed to change member status', 'error');
        }
    );
}

function deleteTeamMember(id) {
    if (!requireEdit('teamMembers')) return;
    const m = memberById(id);
    if (!m) return;
    // teamShifts only holds the subscribed window now, so counting it would
    // understate the real number — say what happens instead of a figure that
    // would be wrong. Work logs are still loaded in full, so that count stands.
    const hasShifts = teamShifts.some(s => s.memberId === id);
    const logCount = workLogs.filter(w => w.memberId === id).length;
    const warn = (hasShifts || logCount)
        ? `\n\nTheir shift schedule${logCount ? ` and ${logCount} daily report(s)` : ''} will be kept, but their name will show as "(deleted member)". To simply take them off the schedule, use Deactivate.`
        : '';
    if (!confirm(`Delete member "${m.name}"?${warn}`)) return;

    cloudWrite(
        { action: 'delete', unitName: `[Team] ${m.name}`, field: 'Member', before: m.jobTitle || m.name, after: '' },
        cloudCall('deleteTeamMember', id),
        `Member "${m.name}" deleted`,
        err => {
            console.error('[team] member delete failed:', err);
            showToast('Failed to delete member', 'error');
        }
    );
}

// ============================================================
// DAILY WORK LOGS
// ============================================================

// "HH:MM" → minutes since midnight, or null when unparseable.
// Guards the two ways the hours on a daily report go wrong in the field.
//
// workLogMinutes wraps a negative difference to +24h so a night shift counts
// correctly — which means typing 08:00–07:00 instead of 07:00–08:00 records
// TWENTY-THREE hours, silently, straight into the "Total Jam Kerja" KPI and the
// monthly per-company recap. And filling only one of the two times records zero
// minutes while the report still looks filed.
//
// A wrap is asked about rather than refused: a real night shift has to stay
// recordable. Returns false when the save should stop.
function checkWorkLogHours(start, end) {
    const s = parseHHMM(start);
    const e = parseHHMM(end);

    if ((s == null) !== (e == null)) {
        showToast('Fill in both the start and end time, or leave both empty', 'warning');
        return false;
    }
    if (s == null) return true;          // both blank — allowed on purpose

    if (s === e) {
        return confirm('The start and end times are the same, so this report counts as 0 hours. Save anyway?');
    }
    const mins = e - s < 0 ? e - s + 24 * 60 : e - s;
    if (e - s < 0 && mins >= WORKLOG_LONG_SHIFT_MIN) {
        return confirm(`Work hours read as ${formatMinutes(mins)} because the end time is earlier than the start time.\n\n`
            + 'If this is a night shift that runs past midnight, press OK.\n'
            + 'If the times are swapped, press Cancel and fix them.');
    }
    return true;
}

function parseHHMM(v) {
    const m = /^(\d{1,2}):(\d{2})$/.exec(String(v || '').trim());
    if (!m) return null;
    const h = +m[1], mi = +m[2];
    if (h > 23 || mi > 59) return null;
    return h * 60 + mi;
}

// Duration in minutes. An end time earlier than the start is read as crossing
// midnight (the night shift runs 23:00–07:00), not as a negative duration.
function workLogMinutes(log) {
    const s = parseHHMM(log && log.start);
    const e = parseHHMM(log && log.end);
    if (s == null || e == null) return 0;
    const diff = e - s;
    return diff < 0 ? diff + 24 * 60 : diff;
}

function formatMinutes(min) {
    if (!min) return '0h';
    const h = Math.floor(min / 60), m = min % 60;
    if (!h) return `${m}m`;
    return m ? `${h}h ${m}m` : `${h}h`;
}

function populateWorkLogFilters() {
    const sel = document.getElementById('wlMemberFilter');
    if (sel) {
        const keep = sel.value;
        sel.innerHTML = '<option value="">All Members</option>' +
            teamMembers.map(m =>
                `<option value="${escapeHtml(m.id)}">${escapeHtml(m.name)}</option>`).join('');
        if (keep && sel.querySelector(`option[value="${CSS.escape(keep)}"]`)) sel.value = keep;
    }
    const formSel = document.getElementById('wlMember');
    if (formSel) {
        const keep = formSel.value;
        formSel.innerHTML = '<option value="">— Select member —</option>' +
            activeMembers().map(m =>
                `<option value="${escapeHtml(m.id)}">${escapeHtml(m.name)}</option>`).join('');
        if (keep && formSel.querySelector(`option[value="${CSS.escape(keep)}"]`)) formSel.value = keep;
        // A form open on an inactive member's record keeps that member.
        else if (keep && document.getElementById('workLogModal').classList.contains('open')) ensureMemberOption('wlMember', keep);
    }
    const list = document.getElementById('wlUnitList');
    if (list) {
        list.innerHTML = [...globalData]
            .sort((a, b) => (a.name || '').localeCompare(b.name || ''))
            .map(u => `<option value="${escapeHtml(damageUnitLabel(u))}"></option>`).join('');
    }
    // Company suggestions, shared by the roster modal and the report filter.
    const comps = allCompanies();
    const dl = document.getElementById('companyList');
    if (dl) dl.innerHTML = companySuggestions().map(c => `<option value="${escapeHtml(c)}"></option>`).join('');
    const pdl = document.getElementById('paddockList');
    if (pdl) pdl.innerHTML = allPaddocks().map(p => `<option value="${escapeHtml(p)}"></option>`).join('');
    const compFilter = document.getElementById('wlCompanyFilter');
    if (compFilter) {
        const keep = compFilter.value;
        compFilter.innerHTML = '<option value="">All Companies</option>' +
            comps.map(c => `<option value="${escapeHtml(c)}">${escapeHtml(c)}</option>`).join('') +
            `<option value="__none__">${escapeHtml(NO_COMPANY)}</option>`;
        if (keep && compFilter.querySelector(`option[value="${CSS.escape(keep)}"]`)) compFilter.value = keep;
    }
}

function getFilteredWorkLogs() {
    const from = (document.getElementById('wlFrom')?.value || '').trim();
    const to = (document.getElementById('wlTo')?.value || '').trim();
    const member = (document.getElementById('wlMemberFilter')?.value || '');
    const company = (document.getElementById('wlCompanyFilter')?.value || '');
    const approval = (document.getElementById('wlApprovalFilter')?.value || '');
    const mine = !!document.getElementById('wlMineFilter')?.checked;
    const q = (document.getElementById('wlSearch')?.value || '').toLowerCase().trim();

    return workLogs.filter(w => {
        if (!visibleToMe(w)) return false;
        if (mine && !isMyRecord(w)) return false;
        if (from && String(w.date || '') < from) return false;
        if (to && String(w.date || '') > to) return false;
        if (member && w.memberId !== member) return false;
        if (company) {
            const c = companyOfRecord(w);
            if (company === '__none__' ? !!c : c !== company) return false;
        }
        if (approval && workLogApproval(w) !== approval) return false;
        if (q) {
            const hay = [memberNameOf(w), companyOfRecord(w), w.paddock,
                         ...workLogUnitNames(w), w.task, w.issue]
                .join(' ').toLowerCase();
            if (!hay.includes(q)) return false;
        }
        return true;
    });
}

function renderWorkLogTable() {
    const rows = getFilteredWorkLogs();
    const tbody = document.getElementById('workLogBody');
    if (!tbody) return;

    // KPI strip
    const totalMin = rows.reduce((a, w) => a + workLogMinutes(w), 0);
    const today = toISODate();
    const reportedToday = new Set(
        workLogs.filter(w => w.date === today && w.memberId && isSubmitted(w)).map(w => w.memberId)
    ).size;
    const activeCount = activeMembers().length;

    const setText = (id, v) => { const el = document.getElementById(id); if (el) el.textContent = v; };
    setText('wlKpiCount', rows.length);
    setText('wlKpiHours', formatMinutes(totalMin));
    // Orang yang izin/sakitnya sudah disetujui hari ini dikeluarkan dari
    // penyebutnya. Sebelumnya mereka terbaca sebagai orang yang lalai melapor,
    // padahal ketidakhadirannya justru sudah dicatat dan disetujui.
    const onLeaveToday = [...membersOnLeave(today)]
        .filter(id => activeMembers().some(m => m.id === id)).length;
    const expected = Math.max(0, activeCount - onLeaveToday);
    setText('wlKpiToday', `${reportedToday} / ${expected}`);
    const todaySub = document.getElementById('wlKpiTodaySub');
    if (todaySub) {
        todaySub.textContent = onLeaveToday
            ? `Active members who reported · ${onLeaveToday} on leave/sick`
            : 'Active members who reported';
    }
    // Counts the whole log, not the filtered slice: a backlog you have filtered
    // out of sight is exactly the backlog worth showing.
    setText('wlKpiPending', workLogs.filter(w => workLogApproval(w) === 'pending').length);
    setText('workLogCount', `${rows.length} ${rows.length === 1 ? 'report' : 'reports'}`);

    const canEdit = hasAccess('teamLog', 'edit');
    const hasFilter = (document.getElementById('wlFrom')?.value || '') ||
                      (document.getElementById('wlTo')?.value || '') ||
                      (document.getElementById('wlMemberFilter')?.value || '') ||
                      (document.getElementById('wlCompanyFilter')?.value || '') ||
                      (document.getElementById('wlApprovalFilter')?.value || '') ||
                      document.getElementById('wlMineFilter')?.checked ||
                      (document.getElementById('wlSearch')?.value || '');

    if (rows.length === 0) {
        tbody.innerHTML = `<tr><td colspan="12" style="text-align:center;padding:24px;color:var(--text-secondary)">${
            hasFilter ? 'No reports match the filter'
                      : 'No daily reports yet. Click <strong>Add Report</strong> to get started.'
        }</td></tr>`;
        return;
    }

    tbody.innerHTML = rows.map((w, i) => {
        const names = workLogUnitNames(w);
        const photoCount = workLogPhotoCount(w);
        const task = w.task || '';
        const taskShort = task.length > 60 ? task.slice(0, 60) + '…' : task;
        const issue = w.issue || '';
        const issueShort = issue.length > 40 ? issue.slice(0, 40) + '…' : issue;
        const jam = (w.start || w.end) ? `${escapeHtml(w.start || '?')}–${escapeHtml(w.end || '?')}` : '—';
        return `
        <tr>
            <td>${i + 1}</td>
            <td data-label="Date" style="white-space:nowrap">${escapeHtml(w.date || '')}${queuedTag('workLogs', w.id)}</td>
            <td data-label="Member"><strong>${escapeHtml(memberNameOf(w))}</strong></td>
            <td data-label="Company" style="font-size:12px">${(() => {
                const c = companyOfRecord(w);
                return c ? escapeHtml(c) : '<span style="color:var(--text-light)">—</span>';
            })()}</td>
            <td data-label="Work Hours" style="white-space:nowrap;font-variant-numeric:tabular-nums">
                ${jam}<span class="wl-duration">${escapeHtml(formatMinutes(workLogMinutes(w)))}</span></td>
            <td data-label="Unit">${names.length
                ? names.map(n => `<span class="badge badge-cat" style="font-size:10px">${escapeHtml(n)}</span>`).join(' ')
                : '<span style="color:var(--text-light);font-size:11px">—</span>'}</td>
            <td data-label="Paddock" style="font-size:12px">${w.paddock
                ? escapeHtml(w.paddock)
                : '<span style="color:var(--text-light)">—</span>'}</td>
            <td data-label="Work Description" style="max-width:150px;font-size:12px" title="${escapeHtml(task)}">${escapeHtml(taskShort)}</td>
            <td data-label="Issues" style="max-width:110px;font-size:12px;color:var(--text-secondary)" title="${escapeHtml(issue)}">${
                issueShort ? escapeHtml(issueShort) : '<span style="color:var(--text-light)">—</span>'}</td>
            <td data-label="Approval">${(() => {
                return approvalCell(w, 'report', 'approveWorkLog', 'reviseWorkLog');
            })()}</td>
            <td data-label="Photos">${photoCount
                ? `<button type="button" class="wl-photo-btn" title="View ${photoCount} photo(s)"
                        aria-label="View ${photoCount} photo(s)"
                        onclick="openWorkLogPhotos(${jsArg(w.id)}, this)"><i class="fas fa-image"></i> ${photoCount}</button>`
                : '<span style="color:var(--text-light);font-size:11px">—</span>'}</td>
            <td class="col-actions">
                ${canEdit ? rowActionsFor(w, 'Report', 'editWorkLog', 'deleteWorkLog', 'withdrawWorkLog') : ''}
            </td>
        </tr>`;
    }).join('');
}

// The Persetujuan cell, shared by reports and leave. The checker approves only
// what was actually sent, and may send back what is waiting or reopen what
// was already approved — the one way an approved record becomes editable.
function approvalCell(rec, noun, approveFn, reviseFn, areas = TEAM_AREAS) {
    const st = workLogApproval(rec);
    const meta = st === 'approved'
        ? `Approved by ${rec.approvedBy || '-'}${rec.approvedAt ? ' · ' + formatUserTime(rec.approvedAt) : ''}`
        : st === 'revision' ? (rec.revisionNote || 'Needs revision')
        : st === 'draft' ? 'Not submitted' : 'Not reviewed yet';
    // One block, one width: the badge on top and the buttons sharing the same
    // width beneath it, so every row lines up whatever its state.
    let html = `<span class="appr appr--${st}" title="${escapeHtml(meta)}">${escapeHtml(APPROVAL_STATES[st].label)}</span>`;
    if (st === 'revision' && rec.revisionNote) {
        html += `<span class="appr-note" title="${escapeHtml(rec.revisionNote)}">${escapeHtml(rec.revisionNote.slice(0, 60))}</span>`;
    }
    if (canApproveThisLog(rec, areas) && (st === 'pending' || st === 'approved')) {
        html += `<span class="appr-actions">
            ${st === 'pending' ? `<button class="btn appr-btn appr-btn--ok" title="Approve ${noun}" aria-label="Approve ${noun}" onclick="${approveFn}(${jsArg(rec.id)})"><i class="fas fa-check"></i></button>` : ''}
            <button class="btn appr-btn appr-btn--rev" title="${st === 'approved' ? 'Reopen — request revision' : 'Request revision'}" aria-label="Request revision for ${noun}" onclick="${reviseFn}(${jsArg(rec.id)})"><i class="fas fa-rotate-left"></i>${st === 'approved' ? ' Reopen' : ''}</button>
        </span>`;
    }
    return `<div class="appr-cell">${html}</div>`;
}

// Edit / delete while the record is open; a padlock (and, for the sender, a
// withdraw button) while it is with the checker or approved.
function rowActionsFor(rec, noun, editFn, deleteFn, withdrawFn, areas = TEAM_AREAS) {
    if (canEditTeamRecord(rec, areas)) {
        return `<div class="row-actions">
            <button class="btn btn-secondary" title="Edit" aria-label="Edit" onclick="${editFn}(${jsArg(rec.id)})"><i class="fas fa-pen"></i></button>
            <button class="btn btn-secondary" title="Delete" aria-label="Delete" onclick="${deleteFn}(${jsArg(rec.id)})"><i class="fas fa-trash" style="color:var(--danger)"></i></button>
        </div>`;
    }
    const why = lockedReason(rec, noun, areas);
    return `<div class="row-actions">
        ${canWithdrawTeamRecord(rec, areas) ? `<button class="btn btn-secondary" title="Withdraw to draft" aria-label="Withdraw to draft" onclick="${withdrawFn}(${jsArg(rec.id)})"><i class="fas fa-arrow-rotate-left"></i></button>` : ''}
        <span class="row-lock" title="${escapeHtml(why)}" aria-label="${escapeHtml(why)}"><i class="fas fa-lock"></i></span>
    </div>`;
}

function clearWorkLogFilter() {
    ['wlFrom', 'wlTo', 'wlSearch'].forEach(id => {
        const el = document.getElementById(id);
        if (el) el.value = '';
    });
    ['wlMemberFilter', 'wlCompanyFilter', 'wlApprovalFilter'].forEach(id => {
        const sel = document.getElementById(id);
        if (sel) sel.value = '';
    });
    const mine = document.getElementById('wlMineFilter');
    if (mine) mine.checked = false;
    renderWorkLogTable();
}

// ---- Work log form: unit chips + documentation photos ----
// Held outside the DOM while the modal is open, like _dmgPhotoData.
let _wlUnits = [];   // [{ id, name, sn }]
let _wlPhotos = [];  // data URLs
// Set only when a photo is actually added or removed. saveWorkLog writes the
// photo document only then — so editing just the description never rewrites
// (or, worse, wipes) photos that may not even have finished loading yet.
let _wlPhotosDirty = false;
let _wlPhotosLoading = false;
let _wlPhotosFailed = false;   // the stored photos never arrived — see setPhotoAddState
let _wlPhotosGen = 0;          // bumped each time the form opens or closes

// Stored photos and letters arrive after the form opens. Saving a changed set
// REPLACES the stored one, so adding a page before the old ones are on screen
// — or after they failed to arrive — would silently throw the old ones away.
// The add button therefore waits for them, and stays shut if they never come.
// Removing needs no guard: until they arrive there is nothing to remove.
function setPhotoAddState(btnId, loading, failed, what) {
    // The input too: its <label> opens the picker even with the button off.
    const input = document.getElementById(btnId === 'lvDocAddBtn' ? 'lvDocInput' : 'wlPhotoInput');
    if (input) input.disabled = !!(loading || failed);
    const btn = document.getElementById(btnId);
    if (!btn) return;
    btn.disabled = !!(loading || failed);
    btn.title = loading ? `Wait for the existing ${what.toLowerCase()} to finish loading`
        : failed ? `Existing ${what.toLowerCase()} failed to load — close and reopen to change them` : '';
}

function renderWorkLogUnitChips() {
    const wrap = document.getElementById('wlUnitChips');
    if (!wrap) return;
    wrap.innerHTML = _wlUnits.length
        ? _wlUnits.map((u, i) => `
            <span class="unit-chip">
                ${escapeHtml(u.name || u.sn || '(unit)')}
                <button type="button" class="unit-chip__x" aria-label="Remove ${escapeHtml(u.name || u.sn)}"
                        title="Remove from list" onclick="removeWorkLogUnit(${i})">&times;</button>
            </span>`).join('')
        : '<span class="unit-chip__empty">No units selected</span>';
}

function addWorkLogUnit() {
    const input = document.getElementById('wlUnit');
    if (!input) return;
    const raw = (input.value || '').trim();
    if (!raw) return;
    const unit = resolveDamageUnit(raw);
    if (!unit) {
        showToast(`Unit "${raw}" not found — pick one from the list`, 'warning');
        return;
    }
    if (_wlUnits.some(u => u.id === unit.id)) {
        showToast(`${unit.name || unit.sn} is already in the list`, 'warning');
        input.value = '';
        return;
    }
    _wlUnits.push({ id: unit.id, name: unit.name || '', sn: unit.sn || '' });
    input.value = '';
    input.focus();
    renderWorkLogUnitChips();
}

function removeWorkLogUnit(index) {
    _wlUnits.splice(index, 1);
    renderWorkLogUnitChips();
}

function renderWorkLogPhotos() {
    const wrap = document.getElementById('wlPhotoPreviews');
    const count = document.getElementById('wlPhotoCount');
    if (count) count.textContent = `${_wlPhotos.length}/${WORKLOG_PHOTO_MAX}`;
    setPhotoAddState('wlPhotoAddBtn', _wlPhotosLoading, _wlPhotosFailed, 'Photos');
    if (!wrap) return;
    if (_wlPhotosLoading && !_wlPhotos.length) {
        wrap.innerHTML = '<span class="wl-photo__loading"><i class="fas fa-spinner fa-spin"></i> Loading photos…</span>';
        return;
    }
    if (_wlPhotosFailed) {
        wrap.innerHTML = '<span class="wl-photo__loading"><i class="fas fa-triangle-exclamation"></i> '
            + 'Existing photos failed to load and are still saved. Close and reopen to change them.</span>';
        return;
    }
    wrap.innerHTML = _wlPhotos.map((src, i) => `
        <div class="wl-photo">
            <img src="${escapeHtml(safeImageSrc(src))}" alt="Photo ${i + 1}" onclick="openPhotoLightbox(_wlPhotos, ${i})">
            <button type="button" class="wl-photo__x" aria-label="Delete photo ${i + 1}"
                    title="Delete photo" onclick="removeWorkLogPhoto(${i})">&times;</button>
        </div>`).join('');
}

async function handleWorkLogPhotoChange(event) {
    const files = [...(event.target.files || [])];
    event.target.value = '';
    if (!files.length) return;
    if (_wlPhotosLoading || _wlPhotosFailed) return;
    const gen = _wlPhotosGen;

    for (const file of files) {
        if (_wlPhotos.length >= WORKLOG_PHOTO_MAX) {
            showToast(`Maximum ${WORKLOG_PHOTO_MAX} photos per report`, 'warning');
            break;
        }
        if (!file.type.startsWith('image/')) {
            showToast(`"${file.name}" is not an image — skipped`, 'warning');
            continue;
        }
        try {
            const data = await compressImageToDataURL(file, WORKLOG_PHOTO_OPTS);
            // Closed, or reopened on another report, while compressing.
            if (gen !== _wlPhotosGen) return;
            // Firestore rejects a document over 1MB outright, so stop before
            // the write fails rather than after.
            const total = _wlPhotos.reduce((n, p) => n + p.length, 0) + data.length;
            if (total > WORKLOG_PHOTOS_TOTAL_BYTES) {
                showToast('Total photo size is at the limit — delete one first', 'warning');
                break;
            }
            _wlPhotos.push(data);
            _wlPhotosDirty = true;
        } catch (err) {
            showToast(err.message || `Failed to process "${file.name}"`, 'error');
        }
    }
    renderWorkLogPhotos();
}

function removeWorkLogPhoto(index) {
    _wlPhotos.splice(index, 1);
    _wlPhotosDirty = true;
    renderWorkLogPhotos();
}

// ---- Opening documentation from the table ----
// One fetch per report, then cached for the session. Offline against a report
// whose photos were never cached, this fails — and says so plainly instead of
// leaving a button spinning forever.
async function openWorkLogPhotos(id, btn) {
    const original = btn ? btn.innerHTML : '';
    if (btn) { btn.disabled = true; btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i>'; }
    try {
        const photos = await loadWorkLogPhotos(id);
        if (!photos.length) { showToast('Photos not found', 'warning'); return; }
        openPhotoLightbox(photos);
    } catch (err) {
        console.error('[team] work log photos load failed:', err);
        showToast(navigator.onLine
            ? 'Failed to load documentation photos'
            : 'Photos need a signal to load', 'error');
    } finally {
        if (btn) { btn.disabled = false; btn.innerHTML = original; }
    }
}

function showAddWorkLogForm() {
    if (!requireEdit('teamLog')) return;
    if (activeMembers().length === 0) {
        showToast('Add team members first via Manage Members', 'warning');
        return;
    }
    document.getElementById('workLogModalTitle').textContent = 'Add Daily Report';
    document.getElementById('editWorkLogId').value = '';
    document.getElementById('workLogForm').reset();
    _wlUnits = [];
    _wlPhotosGen++;
    _wlPhotos = [];
    _wlPhotosDirty = false;
    _wlPhotosLoading = false;
    _wlPhotosFailed = false;
    populateWorkLogFilters();
    renderWorkLogUnitChips();
    renderWorkLogPhotos();
    document.getElementById('wlDate').value = toISODate();
    showRevisionNote('wlRevisionNote', null);
    document.getElementById('workLogModal').classList.add('open');
}

// The checker's note, shown inside the form the author fixes it in — so the
// request does not have to be remembered from a table cell.
function showRevisionNote(elId, rec) {
    const el = document.getElementById(elId);
    if (!el) return;
    const st = rec ? workLogApproval(rec) : '';
    const note = rec && rec.revisionNote;
    if (!note || (st !== 'revision' && st !== 'draft')) { el.style.display = 'none'; el.textContent = ''; return; }
    el.innerHTML = '';
    const head = document.createElement('strong');
    head.textContent = `Revision requested${rec.reviewedBy ? ' by ' + rec.reviewedBy : ''}: `;
    el.appendChild(head);
    el.appendChild(document.createTextNode(note));
    el.style.display = '';
}

function editWorkLog(id) {
    if (!requireEdit('teamLog')) return;
    const w = workLogs.find(x => x.id === id);
    if (!w) return;
    if (!canEditTeamRecord(w)) { showToast(lockedReason(w, 'Report'), 'warning'); return; }
    document.getElementById('workLogModalTitle').textContent =
        workLogApproval(w) === 'revision' ? 'Revise Daily Report' : 'Edit Daily Report';
    showRevisionNote('wlRevisionNote', w);
    document.getElementById('editWorkLogId').value = w.id;
    populateWorkLogFilters();
    document.getElementById('wlDate').value = w.date || '';
    document.getElementById('wlMember').value = w.memberId || '';
    ensureMemberOption('wlMember', w.memberId);
    document.getElementById('wlStart').value = w.start || '';
    document.getElementById('wlEnd').value = w.end || '';
    // Copies, so cancelling the modal leaves the stored record untouched.
    _wlUnits = workLogUnits(w).map(u => ({ ...u }));
    const gen = ++_wlPhotosGen;
    _wlPhotos = [];
    _wlPhotosDirty = false;
    _wlPhotosFailed = false;
    // Photos arrive separately; until they do the strip shows a placeholder.
    // Nothing is lost if they never arrive — see _wlPhotosDirty in saveWorkLog.
    _wlPhotosLoading = workLogPhotoCount(w) > 0;
    document.getElementById('wlUnit').value = '';
    document.getElementById('wlPaddock').value = w.paddock || '';
    renderWorkLogUnitChips();
    renderWorkLogPhotos();
    document.getElementById('wlTask').value = w.task || '';
    document.getElementById('wlIssue').value = w.issue || '';
    document.getElementById('workLogModal').classList.add('open');

    if (_wlPhotosLoading) {
        // Always the server's copy for an EDIT: saving replaces the stored
        // set, and a session cache from before another device added a photo
        // would quietly drop it.
        _wlPhotoCache.delete(id);
        loadWorkLogPhotos(id).then(photos => {
            // The modal may have been closed or reopened on another report
            // while the fetch was in flight — only fill what still applies.
            if (gen !== _wlPhotosGen) return;
            _wlPhotos = photos.slice();   // a copy: the session cache must not see edits
            _wlPhotosLoading = false;
            renderWorkLogPhotos();
        }).catch(err => {
            console.error('[team] work log photos load failed:', err);
            if (gen !== _wlPhotosGen) return;
            _wlPhotosLoading = false;
            _wlPhotosFailed = true;
            renderWorkLogPhotos();
            showToast(navigator.onLine
                ? 'Existing photos failed to load — they are still saved'
                : 'Existing photos need a signal to load — they are still saved', 'warning');
        });
    }
}

function closeWorkLogModal(force) {
    // Photos are compressed on the device and exist nowhere else until the
    // report is saved, so closing after shooting four of them in the field is
    // the most expensive discard in the app. saveWorkLog passes force.
    if (!force && _wlPhotosDirty && _wlPhotos.length) {
        if (!confirm(`${_wlPhotos.length} photo(s) not saved yet and will be lost. Close anyway?`)) return;
    } else if (!force && !okToDiscardTyping('workLogForm')) {
        return;
    }
    _wlPhotosGen++;
    _wlPhotosDirty = false;
    document.getElementById('workLogModal').classList.remove('open');
}

// mode 'draft' keeps it with the author; anything else sends it for checking.
function saveWorkLog(event, mode) {
    if (event) event.preventDefault();
    if (!requireEdit('teamLog')) return;
    const asDraft = mode === 'draft';

    const id = document.getElementById('editWorkLogId').value;
    const memberId = document.getElementById('wlMember').value;
    const member = memberById(memberId);
    if (!member) { showToast('Select a team member first', 'warning'); return; }

    const date = document.getElementById('wlDate').value;
    const start = document.getElementById('wlStart').value;
    const end = document.getElementById('wlEnd').value;
    const task = (document.getElementById('wlTask').value || '').trim();
    // A draft may be half-written; what is sent for checking may not.
    if (!task && !asDraft) { showToast('Work description cannot be empty', 'warning'); return; }
    if (!checkWorkLogHours(start, end)) return;
    // The native max= is the first line of defence, but a report filed decades
    // out skews the monthly recap badly enough to be worth a second one.
    if (date && date > toISODate()) {
        showToast('Report date cannot be in the future — check the year', 'warning');
        return;
    }

    // A unit left typed but not added is an easy mistake to make, so fold it in
    // rather than dropping it silently.
    const pending = (document.getElementById('wlUnit').value || '').trim();
    if (pending) {
        addWorkLogUnit();
        if ((document.getElementById('wlUnit').value || '').trim()) return; // unresolved
    }
    const units = _wlUnits.map(u => ({ ...u }));

    const existing = id ? workLogs.find(w => w.id === id) : null;
    // Sent or approved while the form was open (another device, or the
    // checker): the server would refuse the write, so say why here instead.
    if (existing && !canEditTeamRecord(existing)) {
        showToast(lockedReason(existing, 'Report'), 'warning');
        return;
    }
    const rec = {
        id: id || generateWorkLogId(),
        date,
        memberId,
        memberName: member.name,
        company: companyOf(member),
        start, end,
        units,
        // First unit mirrored into the old single-unit fields so anything still
        // reading them — the unit profile cross-link, older exports — keeps working.
        unitId: units.length ? units[0].id : '',
        unitName: units.length ? (units[0].name || '') : '',
        sn: units.length ? (units[0].sn || '') : '',
        paddock: (document.getElementById('wlPaddock').value || '').trim(),
        // Only the count lives on the report; the images go to workLogPhotos.
        photoCount: _wlPhotosDirty ? _wlPhotos.length : workLogPhotoCount(existing),
        task,
        issue: (document.getElementById('wlIssue').value || '').trim(),
        createdAt: existing ? (existing.createdAt || Date.now()) : Date.now(),
        updatedAt: Date.now(),
        // Who filed it — needed so an approver cannot sign off their own work.
        createdByUid: existing ? (existing.createdByUid || '') : ((currentUser && currentUser.uid) || ''),
        createdByEmail: existing ? (existing.createdByEmail || '') : ((currentUser && currentUser.email) || ''),
        // Saving never keeps an approval: an approved report changed by the
        // owner goes back for checking like any other. The checker's note
        // stays on a draft, so it is still there when the fix is finished.
        approval: asDraft ? 'draft' : 'pending',
        approvedBy: '', approvedByEmail: '', approvedAt: 0,
        revisionNote: asDraft && existing ? (existing.revisionNote || '') : '',
        submittedAt: asDraft ? (existing ? (existing.submittedAt || 0) : 0) : Date.now(),
        submittedByUid: submittedByFor(existing, asDraft)
    };
    // Untouched photos are left exactly as they are — not re-read, not
    // rewritten, not cleared. That is what makes it safe to save while the
    // photos are still loading, and it keeps a description fix from costing a
    // 800KB write. The inline copy on an older report is cleared only when the
    // user actually changes the photos, or by migrateWorkLogPhotos().
    if (_wlPhotosDirty) rec.photos = [];

    const wasApproved = existing && workLogApproval(existing) === 'approved';

    // Photos FIRST. firestore.rules lets a photo document change only while
    // its report is a draft or sent back, and writes from one device reach
    // the server in order — so the photos have to land before the report
    // that locks them.
    if (_wlPhotosDirty) {
        const photos = _wlPhotos.slice();
        _wlPhotoCache.set(rec.id, photos);
        // Offline, the service worker can still be serving a firebase-init.js
        // from before this collection existed. Say so rather than throwing
        // halfway through a save that otherwise looks like it worked.
        if (!window.cloud.saveWorkLogPhotos) {
            showToast('Reload the page — an old version is still active, photos not sent', 'warning');
        } else {
            const write = photos.length
                ? window.cloud.saveWorkLogPhotos(rec.id, photos)
                : window.cloud.deleteWorkLogPhotos(rec.id);
            write.catch(err => {
                console.error('[team] work log photos save failed:', err);
                if (err && err.code === 'permission-denied') showTeamRulesBanner();
                showToast('Report saved, but the photos failed to send', 'error');
            });
        }
    }

    const snap = _snapWorkLog();
    cloudWrite(
        {
            action: existing ? 'update' : 'create',
            unitId: rec.unitId,
            unitName: `[Daily Report] ${member.name}`,
            field: `Report ${rec.date}${asDraft ? ' (draft)' : ''}`,
            before: existing ? (existing.task || '') : '',
            after: rec.task
        },
        cloudCall('saveWorkLog', rec),
        asDraft ? 'Draft report saved — not submitted yet'
            : wasApproved ? 'Report resubmitted — needs review again'
            : 'Report submitted — pending approval',
        err => {
            console.error('[team] work log save failed:', err);
            if (err && err.code === 'permission-denied' && isOwner()) showTeamRulesBanner();
            rememberUnsent(`daily report — ${member.name}, ${rec.date}`, err, () => _reopenWorkLog(snap));
        }
    );

    closeWorkLogModal(true);
}

// Tarik kembali: a sent record comes back to its author as a draft, before
// anyone has checked it. Nothing else on it changes.
function withdrawWorkLog(id) {
    const w = workLogs.find(x => x.id === id);
    if (!w) return;
    if (!canWithdrawTeamRecord(w)) { showToast('This report cannot be withdrawn', 'warning'); return; }
    if (!confirm(`Withdraw the report for ${memberNameOf(w)} (${w.date}) to a draft?\n\nThe report can then be changed and submitted again.`)) return;
    cloudWrite(
        { action: 'update', unitId: w.unitId || '',
          unitName: `[Daily Report] ${memberNameOf(w)}`,
          field: `Approval ${w.date}`, before: 'Pending', after: 'Draft (withdrawn)' },
        cloudCall('saveWorkLog', { ...w, approval: 'draft', updatedAt: Date.now() }),
        'Report withdrawn to draft',
        err => {
            console.error('[team] withdraw failed:', err);
            if (err && err.code === 'permission-denied') showTeamRulesBanner();
            showToast('Failed to withdraw — it may already have been reviewed', 'error');
        }
    );
}

function deleteWorkLog(id) {
    if (!requireEdit('teamLog')) return;
    const w = workLogs.find(x => x.id === id);
    if (!w) return;
    if (!canEditTeamRecord(w)) { showToast(lockedReason(w, 'Report'), 'warning'); return; }
    if (!confirm(`Delete the report for ${memberNameOf(w)} on ${w.date}?`)) return;
    // Otherwise the photo document is orphaned: invisible, but still billed for
    // and still downloaded by anyone who happens to request that id.
    if (workLogPhotoCount(w) > 0 && window.cloud.deleteWorkLogPhotos) {
        _wlPhotoCache.delete(id);
        window.cloud.deleteWorkLogPhotos(id).catch(err =>
            console.error('[team] work log photos delete failed:', err));
    }
    cloudWrite(
        { action: 'delete', unitId: w.unitId || '',
          unitName: `[Daily Report] ${memberNameOf(w)}`,
          field: `Report ${w.date}`, before: w.task || '', after: '' },
        cloudCall('deleteWorkLog', id),
        'Report deleted',
        err => {
            console.error('[team] work log delete failed:', err);
            showToast('Failed to delete report', 'error');
        }
    );
}

function approveWorkLog(id) {
    const w = workLogs.find(x => x.id === id);
    if (!w) return;
    if (!canApproveWorkLogs()) {
        showToast('You do not have the right to approve reports', 'warning');
        return;
    }
    if (!canApproveThisLog(w)) {
        showToast(selfCheckMessage(w, 'report', 'approve'), 'warning');
        return;
    }
    if (workLogApproval(w) !== 'pending') {
        showToast('Only submitted reports can be approved', 'warning');
        return;
    }

    const rec = {
        ...w,
        approval: 'approved',
        approvedBy: (currentUserDoc && currentUserDoc.displayName) || (currentUser && currentUser.email) || '',
        approvedByEmail: (currentUser && currentUser.email) || '',
        approvedAt: Date.now(),
        revisionNote: '',
        updatedAt: Date.now()
    };
    cloudWrite(
        { action: 'update', unitId: rec.unitId || '',
          unitName: `[Daily Report] ${memberNameOf(rec)}`,
          field: `Approval ${rec.date}`,
          before: APPROVAL_STATES[workLogApproval(w)].label,
          after: APPROVAL_STATES.approved.label },
        cloudCall('saveWorkLog', rec),
        'Report approved',
        err => {
            console.error('[team] approve failed:', err);
            if (err && err.code === 'permission-denied') showTeamRulesBanner();
            showToast('Failed to approve report', 'error');
        }
    );
}

function reviseWorkLog(id) {
    const w = workLogs.find(x => x.id === id);
    if (!w) return;
    if (!canApproveWorkLogs()) {
        showToast('You do not have the right to approve reports', 'warning');
        return;
    }
    if (!canApproveThisLog(w)) {
        showToast(selfCheckMessage(w, 'report', 'review'), 'warning');
        return;
    }
    const stNow = workLogApproval(w);
    if (stNow !== 'pending' && stNow !== 'approved') {
        showToast('This report has not been submitted or has already been sent back', 'warning');
        return;
    }
    // The note is the whole point of this state — without it the person is
    // told "wrong" and nothing else.
    const note = prompt(`What needs fixing in the report for ${memberNameOf(w)} (${w.date})?`,
        w.revisionNote || '');
    if (note === null) return;
    if (!note.trim()) { showToast('Write the reason so it can be fixed', 'warning'); return; }

    const rec = {
        ...w,
        approval: 'revision',
        revisionNote: note.trim(),
        approvedBy: '', approvedByEmail: '', approvedAt: 0,
        reviewedBy: (currentUserDoc && currentUserDoc.displayName) || (currentUser && currentUser.email) || '',
        reviewedAt: Date.now(),
        updatedAt: Date.now()
    };
    cloudWrite(
        { action: 'update', unitId: rec.unitId || '',
          unitName: `[Daily Report] ${memberNameOf(rec)}`,
          field: `Approval ${rec.date}`,
          before: APPROVAL_STATES[workLogApproval(w)].label,
          after: `${APPROVAL_STATES.revision.label} — ${rec.revisionNote}` },
        cloudCall('saveWorkLog', rec),
        'Report marked as needing revision',
        err => {
            console.error('[team] revise failed:', err);
            if (err && err.code === 'permission-denied') showTeamRulesBanner();
            showToast('Failed to mark report', 'error');
        }
    );
}

function exportWorkLogCSV() {
    if (!canCsv('export')) return;
    const rows = getFilteredWorkLogs();
    if (rows.length === 0) { showToast('No reports to export', 'warning'); return; }
    const headers = ['No', 'Date', 'Company', 'Member', 'Job Title', 'Start', 'End', 'Duration (hours)',
                     'Paddock Area', 'Unit', 'Serial Number', 'Photo Count', 'Work Description', 'Issues',
                     'Approval', 'Approved By', 'Revision Notes'];
    const dataRows = rows.map((w, i) => {
        const m = w.memberId ? memberById(w.memberId) : null;
        const us = workLogUnits(w);
        return [
            i + 1, w.date || '', companyOfRecord(w), memberNameOf(w), m ? (m.jobTitle || '') : '',
            w.start || '', w.end || '',
            (workLogMinutes(w) / 60).toFixed(2),
            w.paddock || '',
            // Several units share one cell, separated so the column stays readable.
            workLogUnitNames(w).join(' | '),
            us.map(u => u.sn || '').filter(Boolean).join(' | '),
            workLogPhotoCount(w),
            w.task || '', w.issue || '',
            APPROVAL_STATES[workLogApproval(w)].label,
            w.approvedBy || '', w.revisionNote || ''
        ];
    });
    const csv = toCSV(headers, dataRows);
    const blob = new Blob(['﻿' + csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `daily_report_${toISODate()}.csv`;
    a.click();
    URL.revokeObjectURL(url);
    showToast(`Exported ${rows.length} report(s) to CSV`, 'success');
}

// Work logs attached to one unit, newest first — used by the unit profile so
// "who has worked on this machine" is answerable from the unit's own page.
function workLogsForUnit(unitId, sn) {
    const snLc = (sn || '').toLowerCase();
    // A report can list several units, so match any of them — not just the
    // first one mirrored into the legacy unitId field.
    return workLogs.filter(w => isSubmitted(w) && workLogUnits(w).some(u =>
        (unitId && u.id === unitId) || (snLc && (u.sn || '').toLowerCase() === snLc)
    ));
}

// ============================================================
// IZIN / SAKIT — leave and sick-day requests
// ------------------------------------------------------------
// A third team record, alongside the shift schedule and the daily report.
// It exists because the schedule's 'libur' cell cannot answer the questions
// that matter here: it has no date range, no scanned letter, no note and no
// approval — it is one enum value on one day.
//
// Access rides on the SAME two areas as the daily report: teamLog to file one,
// teamLogApprove to approve one. The people are the same people and the
// approver is the same approver, so there is no new permission to hand out.
//
// Scanned letters go to the workLogPhotos collection (see the getTeamDocs
// aliases in firebase-init.js) — same shape, same area, and no fourth path
// waiting on a rules publish.
// ============================================================

// Stored as KEYS, never as the label. Translating or rewording a label must
// not rewrite what is in the database — the Good/Breakdown values elsewhere in
// this app are the cautionary example.
const LEAVE_TYPES = [
    { key: 'izin',  label: 'Leave',                  tone: 'info',    needsDoc: true  },
    { key: 'sakit', label: 'Sick',                   tone: 'warning', needsDoc: true  },
    { key: 'alpa',  label: 'Absent (no notice)',     tone: 'danger', needsDoc: false }
];
const LEAVE_LABEL = LEAVE_TYPES.reduce((m, t) => { m[t.key] = t.label; return m; }, {});
const LEAVE_DOC_MAX = 4;                       // lembar surat per pengajuan
const LEAVE_LONG_DAYS = 30;                    // di atas ini, minta konfirmasi

function generateLeaveId() {
    return 'lv_' + Date.now() + '_' + Math.random().toString(36).substr(2, 5);
}

function leaveTypeLabel(rec) {
    return LEAVE_LABEL[rec && rec.type] || (rec && rec.type) || '-';
}

function leaveTypeTone(rec) {
    const t = LEAVE_TYPES.find(x => x.key === (rec && rec.type));
    return t ? t.tone : 'info';
}

// Both ends inclusive: a request for the 5th to the 5th is one day, not zero.
function leaveDays(from, to) {
    const a = parseLocalDate(from);
    const b = parseLocalDate(to || from);
    if (!a || !b) return 0;
    const n = Math.round((b - a) / 86400000) + 1;
    return n > 0 ? n : 0;
}

function leaveCovers(rec, date) {
    if (!rec || !rec.dateFrom || !date) return false;
    return date >= rec.dateFrom && date <= (rec.dateTo || rec.dateFrom);
}

// Only APPROVED requests count as being away. A pending one is a claim, not a
// fact, and letting it mark the schedule would let anyone empty the roster by
// filing a request nobody has looked at yet.
function leaveOn(memberId, date) {
    return leaveRequests.find(r =>
        r.memberId === memberId &&
        workLogApproval(r) === 'approved' &&
        leaveCovers(r, date)) || null;
}

function membersOnLeave(date) {
    const d = date || toISODate();
    return new Set(leaveRequests
        .filter(r => workLogApproval(r) === 'approved' && leaveCovers(r, d))
        .map(r => r.memberId));
}

// Anything not yet refused still occupies the days it claims. A request sent
// back for revision is excluded: it is not standing.
function overlappingLeave(memberId, from, to, exceptId) {
    const a = from;
    const b = to || from;
    return leaveRequests.filter(r =>
        r.memberId === memberId &&
        r.id !== exceptId &&
        isSubmitted(r) &&
        workLogApproval(r) !== 'revision' &&
        a <= (r.dateTo || r.dateFrom) && b >= r.dateFrom);
}

function leaveDocCount(rec) {
    return Number(rec && rec.docCount) || 0;
}

const _leaveDocCache = new Map();              // leaveId -> data URLs

// Fetched one document at a time, only when someone opens it. The collection
// this reads is never subscribed; see firebase-init.js.
async function loadLeaveDocs(id) {
    if (_leaveDocCache.has(id)) return _leaveDocCache.get(id);
    const fn = window.cloud && (window.cloud.getTeamDocs || window.cloud.getWorkLogPhotos);
    if (!fn) return [];
    const pages = await fn.call(window.cloud, id);
    const list = Array.isArray(pages) ? pages : [];
    _leaveDocCache.set(id, list);
    return list;
}

function applyCloudLeaveSnapshot(list) {
    _markLoaded('leaveRequests');
    leaveRequests = (list || []).slice().sort((a, b) =>
        String(b.dateFrom || '').localeCompare(String(a.dateFrom || '')) ||
        ((b.createdAt || 0) - (a.createdAt || 0)));
    if (currentView === 'team') {
        populateLeaveFilters();
        if (teamTab === 'leave') renderLeaveTable();
        // An approved request marks the schedule, so the grid has to redraw.
        if (teamTab === 'shift') renderShiftGrid();
    }
    // Without this the pending count never reaches the sidebar badge.
    scheduleDecisionRefresh();
}

function populateLeaveFilters() {
    const memberSel = document.getElementById('lvMemberFilter');
    if (memberSel) {
        const keep = memberSel.value;
        memberSel.innerHTML = '<option value="">All Members</option>'
            + teamMembers.map(m => `<option value="${escapeHtml(m.id)}">${escapeHtml(m.name)}</option>`).join('');
        if (keep && memberSel.querySelector(`option[value="${CSS.escape(keep)}"]`)) memberSel.value = keep;
    }
    const formSel = document.getElementById('lvMember');
    if (formSel) {
        const keep = formSel.value;
        formSel.innerHTML = '<option value="">— Select member —</option>'
            + activeMembers().map(m => `<option value="${escapeHtml(m.id)}">${escapeHtml(m.name)}</option>`).join('');
        if (keep && formSel.querySelector(`option[value="${CSS.escape(keep)}"]`)) formSel.value = keep;
        // A form open on an inactive member's record keeps that member.
        else if (keep && document.getElementById('leaveModal').classList.contains('open')) ensureMemberOption('lvMember', keep);
    }
    const compSel = document.getElementById('lvCompanyFilter');
    if (compSel) {
        const keep = compSel.value;
        const companies = allCompanies();
        compSel.innerHTML = '<option value="">All Companies</option>'
            + companies.map(c => `<option value="${escapeHtml(c)}">${escapeHtml(c)}</option>`).join('')
            + `<option value="__none__">${escapeHtml(NO_COMPANY)}</option>`;
        if (keep && compSel.querySelector(`option[value="${CSS.escape(keep)}"]`)) compSel.value = keep;
    }
}

// A request OVERLAPPING the from/to window counts, unlike the work log where a
// record sits on a single day. Someone filtering "September" wants the sick
// leave that started in August and ran into it.
function getFilteredLeave() {
    const from = (document.getElementById('lvFrom')?.value || '').trim();
    const to = (document.getElementById('lvTo')?.value || '').trim();
    const member = (document.getElementById('lvMemberFilter')?.value || '');
    const company = (document.getElementById('lvCompanyFilter')?.value || '');
    const approval = (document.getElementById('lvApprovalFilter')?.value || '');
    const type = (document.getElementById('lvTypeFilter')?.value || '');
    const mine = !!document.getElementById('lvMineFilter')?.checked;
    const q = (document.getElementById('lvSearch')?.value || '').toLowerCase().trim();

    return leaveRequests.filter(r => {
        if (!visibleToMe(r)) return false;
        if (mine && !isMyRecord(r)) return false;
        const a = String(r.dateFrom || '');
        const b = String(r.dateTo || r.dateFrom || '');
        if (from && b < from) return false;
        if (to && a > to) return false;
        if (member && r.memberId !== member) return false;
        if (type && r.type !== type) return false;
        if (company) {
            const c = companyOfRecord(r);
            if (company === '__none__' ? !!c : c !== company) return false;
        }
        if (approval && workLogApproval(r) !== approval) return false;
        if (q) {
            const hay = [memberNameOf(r), companyOfRecord(r), leaveTypeLabel(r), r.reason]
                .join(' ').toLowerCase();
            if (!hay.includes(q)) return false;
        }
        return true;
    });
}

function clearLeaveFilter() {
    ['lvFrom', 'lvTo', 'lvMemberFilter', 'lvCompanyFilter', 'lvApprovalFilter', 'lvTypeFilter', 'lvSearch']
        .forEach(id => { const el = document.getElementById(id); if (el) el.value = ''; });
    const mine = document.getElementById('lvMineFilter');
    if (mine) mine.checked = false;
    renderLeaveTable();
}

function leaveRangeLabel(r) {
    const a = r.dateFrom || '-';
    const b = r.dateTo || r.dateFrom || '';
    return (!b || b === a) ? a : `${a} → ${b}`;
}

function renderLeaveTable() {
    const rows = getFilteredLeave();
    const tbody = document.getElementById('leaveBody');
    if (!tbody) return;

    const setText = (id, v) => { const el = document.getElementById(id); if (el) el.textContent = v; };
    setText('lvKpiCount', rows.length);
    setText('lvKpiDays', rows.reduce((a, r) => a + (Number(r.days) || leaveDays(r.dateFrom, r.dateTo)), 0));
    // Pending is counted over EVERY request, not the filtered slice: a filter
    // must not be able to make the backlog look empty.
    setText('lvKpiPending', leaveRequests.filter(r => workLogApproval(r) === 'pending').length);
    setText('lvKpiToday', membersOnLeave().size);

    const counter = document.getElementById('leaveCount');
    if (counter) counter.textContent = `${rows.length} ${rows.length === 1 ? 'request' : 'requests'}`;

    const canEdit = hasAccess('teamLog', 'edit');
    const filterOn = ['lvFrom', 'lvTo', 'lvMemberFilter', 'lvCompanyFilter',
                      'lvApprovalFilter', 'lvTypeFilter', 'lvSearch']
        .some(id => (document.getElementById(id)?.value || '') !== '')
        || !!document.getElementById('lvMineFilter')?.checked;

    if (rows.length === 0) {
        tbody.innerHTML = `<tr><td colspan="10" style="text-align:center;padding:24px;color:var(--text-secondary)">${
            filterOn
                ? `No requests match the filter.
                   <button class="btn btn-secondary btn-sm" style="margin-left:8px" onclick="clearLeaveFilter()">
                       <i class="fas fa-filter-circle-xmark"></i> Clear filter</button>`
                : 'No leave or sick requests yet.'
        }</td></tr>`;
        return;
    }

    // Every <td> carries data-label except No and col-actions: style.css hides
    // an unlabelled cell entirely on a phone, so a forgotten label does not
    // look broken, the column just disappears on the device the team uses.
    tbody.innerHTML = rows.map((r, i) => {
        const docs = leaveDocCount(r);
        const days = Number(r.days) || leaveDays(r.dateFrom, r.dateTo);
        return `
        <tr>
            <td>${i + 1}</td>
            <td data-label="Type"><span class="lv-type lv-type--${escapeHtml(r.type || 'izin')}">${escapeHtml(leaveTypeLabel(r))}</span></td>
            <td data-label="Member"><strong>${escapeHtml(memberNameOf(r))}</strong></td>
            <td data-label="Company">${escapeHtml(companyOfRecord(r) || '—')}</td>
            <td data-label="Date">${escapeHtml(leaveRangeLabel(r))}</td>
            <td data-label="Days">${days}</td>
            <td data-label="Notes" style="max-width:220px;font-size:12px;color:var(--text-secondary)"
                title="${escapeHtml(r.reason || '')}">${escapeHtml((r.reason || '').slice(0, 60)) || '—'}</td>
            <td data-label="Letter">${docs
                ? `<button type="button" class="wl-photo-btn" title="View ${docs} letter page(s)"
                        aria-label="View ${docs} letter page(s)"
                        onclick="openLeaveDocs(${jsArg(r.id)}, this)"><i class="fas fa-file-image"></i> ${docs}</button>`
                : '<span style="color:var(--text-light)">—</span>'}</td>
            <td data-label="Approval">${queuedTag('leaveRequests', r.id)}${approvalCell(r, 'request', 'approveLeave', 'reviseLeave')}</td>
            <td class="col-actions">
                ${canEdit ? rowActionsFor(r, 'Request', 'editLeave', 'deleteLeave', 'withdrawLeave') : ''}
            </td>
        </tr>`;
    }).join('');
}

// ---- Form ----
let _lvDocs = [];
let _lvDocsDirty = false;
let _lvDocsLoading = false;
let _lvDocsFailed = false;   // the stored letters never arrived — see setPhotoAddState
let _lvDocsGen = 0;          // bumped each time the form opens or closes

function renderLeaveDocs() {
    const count = document.getElementById('lvDocCount');
    if (count) count.textContent = `${_lvDocs.length}/${LEAVE_DOC_MAX}`;
    setPhotoAddState('lvDocAddBtn', _lvDocsLoading, _lvDocsFailed, 'Letters');
    const wrap = document.getElementById('lvDocPreviews');
    if (!wrap) return;
    if (_lvDocsLoading && !_lvDocs.length) {
        wrap.innerHTML = '<span class="wl-photo__loading"><i class="fas fa-spinner fa-spin"></i> Loading letters…</span>';
        return;
    }
    if (_lvDocsFailed) {
        wrap.innerHTML = '<span class="wl-photo__loading"><i class="fas fa-triangle-exclamation"></i> '
            + 'Existing letters failed to load and are still saved. Close and reopen to change them.</span>';
        return;
    }
    wrap.innerHTML = _lvDocs.map((src, i) => `
        <div class="wl-photo">
            <img src="${escapeHtml(safeImageSrc(src))}" alt="Letter page ${i + 1}" onclick="openPhotoLightbox(_lvDocs, ${i})">
            <button type="button" class="wl-photo__x" aria-label="Delete letter page ${i + 1}"
                    title="Delete this page" onclick="removeLeaveDoc(${i})">&times;</button>
        </div>`).join('');
}

async function handleLeaveDocChange(event) {
    const files = [...(event.target.files || [])];
    event.target.value = '';
    if (_lvDocsLoading || _lvDocsFailed) return;
    const gen = _lvDocsGen;
    for (const file of files) {
        if (_lvDocs.length >= LEAVE_DOC_MAX) {
            showToast(`Maximum ${LEAVE_DOC_MAX} letter pages`, 'warning');
            break;
        }
        // Nothing in this app reads PDFs, so say that rather than failing
        // silently on a file someone scanned straight from a printer.
        if (!file.type.startsWith('image/')) {
            showToast(`"${file.name}" skipped — the letter must be a photo or scanned image, not a PDF`, 'warning');
            continue;
        }
        try {
            const data = await compressImageToDataURL(file, WORKLOG_PHOTO_OPTS);
            // Closed, or reopened on another request, while compressing.
            if (gen !== _lvDocsGen) return;
            const total = _lvDocs.reduce((a, d) => a + d.length, 0) + data.length;
            if (total > WORKLOG_PHOTOS_TOTAL_BYTES) {
                showToast('Letter is too large — reduce the number of pages', 'warning');
                break;
            }
            _lvDocs.push(data);
            _lvDocsDirty = true;
        } catch (err) {
            showToast(String(err && err.message ? err.message : err), 'error');
        }
    }
    renderLeaveDocs();
}

function removeLeaveDoc(index) {
    _lvDocs.splice(index, 1);
    _lvDocsDirty = true;
    renderLeaveDocs();
}

async function openLeaveDocs(id, btn) {
    const old = btn ? btn.innerHTML : '';
    if (btn) { btn.disabled = true; btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i>'; }
    try {
        const pages = await loadLeaveDocs(id);
        if (!pages.length) { showToast('Letter not found', 'warning'); return; }
        openPhotoLightbox(pages, 0);
    } catch (err) {
        console.error('[izin] gagal memuat surat:', err);
        showToast(navigator.onLine
            ? 'Failed to load letter'
            : 'The letter needs a signal to load', 'warning');
    } finally {
        if (btn) { btn.disabled = false; btn.innerHTML = old; }
    }
}

function showAddLeaveForm() {
    if (!requireEdit('teamLog')) return;
    populateLeaveFilters();
    document.getElementById('leaveForm').reset();
    document.getElementById('editLeaveId').value = '';
    document.getElementById('leaveModalTitle').innerHTML =
        '<i class="fas fa-user-clock"></i> Add Leave / Sick Request';
    document.getElementById('lvDateFrom').value = toISODate();
    document.getElementById('lvType').value = 'izin';
    _lvDocsGen++;
    _lvDocs = []; _lvDocsDirty = false; _lvDocsLoading = false; _lvDocsFailed = false;
    renderLeaveDocs();
    showRevisionNote('lvRevisionNote', null);
    rememberFocus();
    document.getElementById('leaveModal').classList.add('open');
}

function editLeave(id) {
    if (!requireEdit('teamLog')) return;
    const r = leaveRequests.find(x => x.id === id);
    if (!r) return;
    if (!canEditTeamRecord(r)) { showToast(lockedReason(r, 'Request'), 'warning'); return; }
    populateLeaveFilters();
    document.getElementById('editLeaveId').value = r.id;
    document.getElementById('leaveModalTitle').innerHTML = workLogApproval(r) === 'revision'
        ? '<i class="fas fa-user-clock"></i> Revise Leave / Sick Request'
        : '<i class="fas fa-user-clock"></i> Edit Leave / Sick Request';
    showRevisionNote('lvRevisionNote', r);
    document.getElementById('lvMember').value = r.memberId || '';
    ensureMemberOption('lvMember', r.memberId);
    document.getElementById('lvType').value = r.type || 'izin';
    document.getElementById('lvDateFrom').value = r.dateFrom || '';
    document.getElementById('lvDateTo').value = r.dateTo || '';
    document.getElementById('lvReason').value = r.reason || '';

    const gen = ++_lvDocsGen;
    _lvDocs = []; _lvDocsDirty = false; _lvDocsFailed = false;
    _lvDocsLoading = leaveDocCount(r) > 0;
    renderLeaveDocs();
    rememberFocus();
    document.getElementById('leaveModal').classList.add('open');
    if (_lvDocsLoading) {
        _leaveDocCache.delete(r.id);   // fresh copy for an edit — see editWorkLog
        loadLeaveDocs(r.id).then(pages => {
            // The form may have been closed, or reopened on another request,
            // while the fetch was in flight — only fill the one it was for.
            if (gen !== _lvDocsGen) return;
            _lvDocs = pages.slice();
            _lvDocsLoading = false;
            renderLeaveDocs();
        }).catch(err => {
            if (gen !== _lvDocsGen) return;
            console.error('[izin] gagal memuat surat:', err);
            _lvDocsLoading = false;
            _lvDocsFailed = true;
            renderLeaveDocs();
            showToast('Existing letters failed to load — they are still saved, and saving now will not change them', 'warning');
        });
    }
}

function closeLeaveModal(force) {
    if (!force && _lvDocsDirty && _lvDocs.length) {
        if (!confirm(`${_lvDocs.length} letter page(s) not saved yet and will be lost. Close anyway?`)) return;
    } else if (!force && !okToDiscardTyping('leaveForm')) {
        return;
    }
    _lvDocsGen++;
    _lvDocsDirty = false;
    document.getElementById('leaveModal').classList.remove('open');
}

// Rejects with a toast, warns-but-allows with confirm() — the same split the
// work log validation uses. Refusing too much costs as much as accepting too
// much: an extended illness and a corrected date really do overlap.
function checkLeaveRange(memberId, type, from, to, exceptId, docCount) {
    if (!memberId) { showToast('Select a member first', 'warning'); return false; }
    if (!from) { showToast('Start date is required', 'warning'); return false; }
    const end = to || from;
    if (end < from) {
        showToast('End date is earlier than the start date', 'warning');
        return false;
    }
    const days = leaveDays(from, end);
    if (days > LEAVE_LONG_DAYS) {
        if (!confirm(`This request is ${days} days (${from} to ${end}).\n\n`
            + 'If it really is that long, press OK. If a date was mistyped, press Cancel and fix it.')) {
            return false;
        }
    }
    const clash = overlappingLeave(memberId, from, end, exceptId);
    if (clash.length) {
        const list = clash.slice(0, 3)
            .map(c => `· ${leaveTypeLabel(c)} ${leaveRangeLabel(c)} (${APPROVAL_STATES[workLogApproval(c)].label})`)
            .join('\n');
        if (!confirm(`These dates overlap an existing request:\n\n${list}\n\n`
            + 'If this is an intentional extension, press OK.')) {
            return false;
        }
    }
    if (type === 'alpa' && docCount > 0) {
        if (!confirm('Absent means away WITHOUT notice, but a letter is attached.\n\n'
            + 'If there really is a letter, the type may be Leave or Sick. Save as Absent anyway?')) {
            return false;
        }
    }
    return true;
}

function saveLeave(event, mode) {
    if (event) event.preventDefault();
    if (!requireEdit('teamLog')) return;
    const asDraft = mode === 'draft';

    const id = document.getElementById('editLeaveId').value;
    const existing = id ? leaveRequests.find(x => x.id === id) : null;
    if (existing && !canEditTeamRecord(existing)) {
        showToast(lockedReason(existing, 'Request'), 'warning');
        return;
    }
    const memberId = document.getElementById('lvMember').value;
    const type = document.getElementById('lvType').value;
    const from = document.getElementById('lvDateFrom').value;
    const to = document.getElementById('lvDateTo').value || from;
    const reason = document.getElementById('lvReason').value.trim();

    const docCount = _lvDocsDirty ? _lvDocs.length : leaveDocCount(existing);
    if (!checkLeaveRange(memberId, type, from, to, id || null, docCount)) return;

    const member = memberById(memberId);
    if (!member) { showToast('Member not found', 'warning'); return; }

    const rec = {
        id: id || generateLeaveId(),
        memberId,
        memberName: member.name,
        company: member.company || '',
        type,
        dateFrom: from,
        dateTo: to,
        days: leaveDays(from, to),
        reason,
        docCount,
        // Saving never keeps an approval. Without this, someone could get
        // three days approved and then change which three days.
        approval: asDraft ? 'draft' : 'pending',
        approvedBy: '', approvedByEmail: '', approvedAt: 0,
        revisionNote: asDraft && existing ? (existing.revisionNote || '') : '',
        submittedAt: asDraft ? (existing ? (existing.submittedAt || 0) : 0) : Date.now(),
        submittedByUid: submittedByFor(existing, asDraft),
        createdBy: existing ? (existing.createdBy || '') : ((currentUserDoc && currentUserDoc.displayName) || (currentUser && currentUser.email) || ''),
        createdByUid: existing ? (existing.createdByUid || '') : ((currentUser && currentUser.uid) || ''),
        createdAt: existing ? (existing.createdAt || Date.now()) : Date.now(),
        updatedAt: Date.now()
    };

    const wasApproved = existing && workLogApproval(existing) === 'approved';

    // Letters FIRST, while the request is still open — see saveWorkLog.
    if (_lvDocsDirty) {
        const pages = _lvDocs.slice();
        _leaveDocCache.set(rec.id, pages);
        const save = cloudFn('saveTeamDocs') && cloudFn('deleteTeamDocs');
        if (save) {
            const write = pages.length
                ? window.cloud.saveTeamDocs(rec.id, pages)
                : window.cloud.deleteTeamDocs(rec.id);
            write.catch(err => {
                console.error('[izin] surat save failed:', err);
                if (err && err.code === 'permission-denied') showTeamRulesBanner();
                showToast('Request saved, but the letter failed to send', 'error');
            });
        }
    }

    const snap = _snapLeave();
    cloudWrite(
        {
            action: existing ? 'update' : 'create',
            unitId: '',
            unitName: `[Leave] ${member.name}`,
            field: `${leaveTypeLabel(rec)} ${leaveRangeLabel(rec)}${asDraft ? ' (draft)' : ''}`,
            before: existing ? `${leaveTypeLabel(existing)} ${leaveRangeLabel(existing)}` : '',
            after: `${rec.days} day(s)${reason ? ' — ' + reason : ''}`
        },
        cloudCall('saveLeaveRequest', rec),
        asDraft ? 'Draft request saved — not submitted yet'
            : wasApproved ? 'Request resubmitted — needs review again'
            : 'Request submitted — pending approval',
        err => {
            console.error('[izin] save failed:', err);
            if (err && err.code === 'permission-denied' && isOwner()) showTeamRulesBanner();
            rememberUnsent(`${leaveTypeLabel(rec).toLowerCase()} request — ${member.name}, ${leaveRangeLabel(rec)}`, err, () => _reopenLeave(snap));
        }
    );

    closeLeaveModal(true);
}

function withdrawLeave(id) {
    const r = leaveRequests.find(x => x.id === id);
    if (!r) return;
    if (!canWithdrawTeamRecord(r)) { showToast('This request cannot be withdrawn', 'warning'); return; }
    if (!confirm(`Withdraw the ${leaveTypeLabel(r)} request for ${memberNameOf(r)} (${leaveRangeLabel(r)}) to a draft?`)) return;
    cloudWrite(
        { action: 'update', unitId: '',
          unitName: `[Leave] ${memberNameOf(r)}`,
          field: `Approval ${leaveRangeLabel(r)}`, before: 'Pending', after: 'Draft (withdrawn)' },
        cloudCall('saveLeaveRequest', { ...r, approval: 'draft', updatedAt: Date.now() }),
        'Request withdrawn to draft',
        err => {
            console.error('[izin] withdraw failed:', err);
            if (err && err.code === 'permission-denied') showTeamRulesBanner();
            showToast('Failed to withdraw — it may already have been reviewed', 'error');
        }
    );
}

function deleteLeave(id) {
    if (!requireEdit('teamLog')) return;
    const r = leaveRequests.find(x => x.id === id);
    if (!r) return;
    if (!canEditTeamRecord(r)) { showToast(lockedReason(r, 'Request'), 'warning'); return; }
    if (!confirm(`Delete the ${leaveTypeLabel(r)} request for ${memberNameOf(r)} (${leaveRangeLabel(r)})?`)) return;
    // Otherwise the letter document is orphaned: invisible, still billed for.
    if (leaveDocCount(r) > 0 && window.cloud.deleteTeamDocs) {
        _leaveDocCache.delete(id);
        window.cloud.deleteTeamDocs(id).catch(err =>
            console.error('[izin] surat delete failed:', err));
    }
    cloudWrite(
        { action: 'delete', unitId: '',
          unitName: `[Leave] ${memberNameOf(r)}`,
          field: `${leaveTypeLabel(r)} ${leaveRangeLabel(r)}`,
          before: `${r.days || 0} day(s)`, after: '' },
        cloudCall('deleteLeaveRequest', id),
        'Request deleted',
        err => {
            console.error('[izin] delete failed:', err);
            if (err && err.code === 'permission-denied') showTeamRulesBanner();
            showToast('Failed to delete request', 'error');
        }
    );
}

// ---- Approval ----
// Reuses workLogApproval / APPROVAL_STATES / canApproveThisLog wholesale,
// including the rule that you cannot approve a request you filed yourself
// unless you are the owner.
function approveLeave(id) {
    const r = leaveRequests.find(x => x.id === id);
    if (!r) return;
    if (!canApproveWorkLogs()) {
        showToast('You do not have the right to approve requests', 'warning');
        return;
    }
    if (!canApproveThisLog(r)) {
        showToast(selfCheckMessage(r, 'request', 'approve'), 'warning');
        return;
    }
    if (workLogApproval(r) !== 'pending') {
        showToast('Only submitted requests can be approved', 'warning');
        return;
    }

    const rec = {
        ...r,
        approval: 'approved',
        approvedBy: (currentUserDoc && currentUserDoc.displayName) || (currentUser && currentUser.email) || '',
        approvedByEmail: (currentUser && currentUser.email) || '',
        approvedAt: Date.now(),
        revisionNote: '',
        updatedAt: Date.now()
    };
    cloudWrite(
        { action: 'approve', unitId: '',
          unitName: `[Leave] ${memberNameOf(rec)}`,
          field: `Approval ${leaveRangeLabel(rec)}`,
          before: APPROVAL_STATES[workLogApproval(r)].label,
          after: APPROVAL_STATES.approved.label },
        cloudCall('saveLeaveRequest', rec),
        'Request approved',
        err => {
            console.error('[izin] approve failed:', err);
            if (err && err.code === 'permission-denied') showTeamRulesBanner();
            showToast('Failed to approve request', 'error');
        }
    );
}

function reviseLeave(id) {
    const r = leaveRequests.find(x => x.id === id);
    if (!r) return;
    if (!canApproveWorkLogs()) {
        showToast('You do not have the right to review this request', 'warning');
        return;
    }
    if (!canApproveThisLog(r)) {
        showToast(selfCheckMessage(r, 'request', 'review'), 'warning');
        return;
    }
    const stNow = workLogApproval(r);
    if (stNow !== 'pending' && stNow !== 'approved') {
        showToast('This request has not been submitted or has already been sent back', 'warning');
        return;
    }
    const note = prompt('What needs to be fixed?', r.revisionNote || '');
    if (note === null) return;
    if (!note.trim()) {
        showToast('Write what needs to be fixed first', 'warning');
        return;
    }
    const rec = {
        ...r,
        approval: 'revision',
        revisionNote: note.trim(),
        approvedBy: '', approvedByEmail: '', approvedAt: 0,
        reviewedBy: (currentUserDoc && currentUserDoc.displayName) || (currentUser && currentUser.email) || '',
        reviewedAt: Date.now(),
        updatedAt: Date.now()
    };
    cloudWrite(
        { action: 'reject', unitId: '',
          unitName: `[Leave] ${memberNameOf(rec)}`,
          field: `Approval ${leaveRangeLabel(rec)}`,
          before: APPROVAL_STATES[workLogApproval(r)].label,
          after: `${APPROVAL_STATES.revision.label} — ${note.trim()}` },
        cloudCall('saveLeaveRequest', rec),
        'Request sent back for revision',
        err => {
            console.error('[izin] revise failed:', err);
            if (err && err.code === 'permission-denied') showTeamRulesBanner();
            showToast('Failed to send revision request', 'error');
        }
    );
}

function exportLeaveCSV() {
    if (!canCsv('export')) return;
    const rows = getFilteredLeave();
    if (rows.length === 0) { showToast('No requests to export', 'warning'); return; }
    const headers = ['No', 'Type', 'Member', 'Company', 'Start Date', 'End Date',
                     'Days', 'Remarks', 'Letter Pages', 'Approval', 'Approved By',
                     'Revision Notes', 'Recorded By'];
    const body = rows.map((r, i) => [
        i + 1,
        leaveTypeLabel(r),
        memberNameOf(r),
        companyOfRecord(r) || '',
        r.dateFrom || '',
        r.dateTo || r.dateFrom || '',
        Number(r.days) || leaveDays(r.dateFrom, r.dateTo),
        r.reason || '',
        leaveDocCount(r),
        APPROVAL_STATES[workLogApproval(r)].label,
        r.approvedBy || '',
        r.revisionNote || '',
        r.createdBy || ''
    ]);
    const csv = toCSV(headers, body);
    const blob = new Blob(['﻿' + csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `leave_sick_${toISODate()}.csv`;
    a.click();
    URL.revokeObjectURL(url);
    showToast(`Exported ${rows.length} request(s) to CSV`, 'success');
}

// ============================================================
// WAREHOUSE — serial-tracked devices + quantity-counted stock
// ------------------------------------------------------------
// Two shapes, because the fleet needs both. A GPS receiver is worth
// following one by one: which serial number, and where it is right now.
// A box of filters is not — only how many are left matters.
//
// Both collections are cloud-only, like the team ones, and both sit behind
// the single 'warehouse' access area.
// ============================================================

const DEVICE_STATUSES = [
    { key: 'warehouse', label: 'In Warehouse', tone: 'info' },
    { key: 'installed', label: 'Installed',  tone: 'success' },
    // Handed over to a division (the recipient), not installed on a unit.
    { key: 'allocated', label: 'Allocated',  tone: 'info' },
    { key: 'damaged',   label: 'Damaged',    tone: 'danger' },
    { key: 'repair',    label: 'In Repair',  tone: 'warning' },
    { key: 'retired',   label: 'Retired',    tone: 'muted' }
];
const DEVICE_STATUS_LABEL = DEVICE_STATUSES.reduce((m, s) => { m[s.key] = s.label; return m; }, {});
const DEFAULT_DEVICE_TYPES = ['GPS / StarFire', 'Display', 'Steering Sensor', 'JDLink', 'Weather Station'];
const STOCK_LOW_THRESHOLD = 5;   // "sisa" at or below this is flagged

let warehouseTab = 'devices';    // 'devices' | 'stock' | 'vehicles'

function generateDeviceId() {
    return 'dev_' + Date.now() + '_' + Math.random().toString(36).substr(2, 5);
}
function generateStockId() {
    return 'stk_' + Date.now() + '_' + Math.random().toString(36).substr(2, 5);
}

// ---- Suggestion lists, gathered from what is already in use ----
function _mergeSuggestions(defaults, values) {
    const seen = new Map();
    (defaults || []).forEach(v => seen.set(v.toLowerCase(), v));
    (values || []).forEach(raw => {
        const v = (raw || '').trim();
        if (v && !seen.has(v.toLowerCase())) seen.set(v.toLowerCase(), v);
    });
    return [...seen.values()].sort((a, b) => a.localeCompare(b));
}
function allDeviceTypes() {
    // Camera AI, Telematic Box and the rest are devices too, but only worth
    // suggesting once heavy equipment exists.
    const defaults = hasHeavyUnits()
        ? DEFAULT_DEVICE_TYPES.concat(UNIT_GROUPS.heavy.components.map(c => c.label))
        : DEFAULT_DEVICE_TYPES;
    return _mergeSuggestions(defaults, warehouseDevices.map(d => d.type));
}
function allWarehouseLocations() {
    return _mergeSuggestions([], [
        ...warehouseDevices.map(d => d.location),
        ...stockLedger.map(r => r.location)
    ]);
}
function allStockItemNames() {
    return _mergeSuggestions([], stockLedger.map(r => r.itemName));
}

// ---- Cloud snapshots ----
function applyCloudDevicesSnapshot(list) {
    _markLoaded('devices');
    warehouseDevices = (list || []).slice().sort((a, b) =>
        (a.type || '').localeCompare(b.type || '') || (a.sn || '').localeCompare(b.sn || ''));
    if (currentView === 'warehouse') { populateWarehouseFilters(); renderWarehouseView(); }
    scheduleDecisionRefresh();
}

function applyCloudStockSnapshot(list) {
    _markLoaded('stockItems');
    stockLedger = (list || []).slice().sort((a, b) =>
        String(b.date || '').localeCompare(String(a.date || '')) ||
        ((b.createdAt || 0) - (a.createdAt || 0)));
    if (currentView === 'warehouse') { populateWarehouseFilters(); renderWarehouseView(); }
    scheduleDecisionRefresh();
}

function showWarehouseRulesBanner() {
    const slot = document.querySelector('.warehouse-rules-slot');
    if (!slot || slot.querySelector('.category-rules-banner')) return;
    const banner = document.createElement('div');
    banner.className = 'category-rules-banner';
    banner.innerHTML = `
        <strong><i class="fas fa-triangle-exclamation"></i> Firestore rules are blocking Inventory data.</strong>
        <p>Your project's rules do not yet allow access to the <code>devices</code> and
        <code>stockItems</code> collections. Republish the <code>firestore.rules</code> file from this repo in
        <em>Firebase Console → Firestore → Rules</em>, then reload the page.</p>`;
    slot.appendChild(banner);
}

// ---- View shell ----
function switchWarehouseTab(tab) {
    warehouseTab = ['stock', 'vehicles'].includes(tab) ? tab : 'devices';
    renderWarehouseView();
}

function renderWarehouseView() {
    document.querySelectorAll('.wh-tab').forEach(btn => {
        // Never trust another page to have left these visible.
        btn.style.display = '';
        const on = btn.dataset.tab === warehouseTab;
        btn.classList.toggle('active', on);
        btn.setAttribute('aria-selected', on ? 'true' : 'false');
    });
    const devPanel = document.getElementById('whDevicePanel');
    const stkPanel = document.getElementById('whStockPanel');
    const vehPanel = document.getElementById('whVehiclePanel');
    if (devPanel) devPanel.style.display = (warehouseTab === 'devices') ? '' : 'none';
    if (stkPanel) stkPanel.style.display = (warehouseTab === 'stock') ? '' : 'none';
    if (vehPanel) vehPanel.style.display = (warehouseTab === 'vehicles') ? '' : 'none';

    if (warehouseTab === 'devices') renderDeviceTable();
    else if (warehouseTab === 'vehicles') renderVehicleView();
    else renderStockView();
}

function populateWarehouseFilters() {
    const fill = (id, values, allLabel) => {
        const sel = document.getElementById(id);
        if (!sel) return;
        const keep = sel.value;
        sel.innerHTML = `<option value="">${escapeHtml(allLabel)}</option>` +
            values.map(v => `<option value="${escapeHtml(v)}">${escapeHtml(v)}</option>`).join('');
        if (keep && sel.querySelector(`option[value="${CSS.escape(keep)}"]`)) sel.value = keep;
    };
    fill('devTypeFilter', allDeviceTypes(), 'All Types');
    fill('devLocationFilter', allWarehouseLocations(), 'All Locations');
    fill('stkLocationFilter', allWarehouseLocations(), 'All Locations');
    fill('stkItemFilter', allStockItemNames(), 'All Items');

    const dl = (id, values) => {
        const el = document.getElementById(id);
        if (el) el.innerHTML = values.map(v => `<option value="${escapeHtml(v)}"></option>`).join('');
    };
    dl('deviceTypeList', allDeviceTypes());
    dl('warehouseLocationList', allWarehouseLocations());
    dl('devDivisionList', [...new Set(warehouseDevices.map(d => (d.division || '').trim()).filter(Boolean))].sort((a, b) => a.localeCompare(b)));
    dl('stockItemList', allStockItemNames());

    const unitOpts = [...globalData]
        .sort((a, b) => (a.name || '').localeCompare(b.name || ''))
        .map(u => `<option value="${escapeHtml(damageUnitLabel(u))}"></option>`).join('');
    dl('devUnitList', []);
    const du = document.getElementById('devUnitList');
    if (du) du.innerHTML = unitOpts;
    const su = document.getElementById('stkUnitList');
    if (su) su.innerHTML = unitOpts;
}

// ============================================================
// DEVICES (serial-tracked)
// ============================================================

// Where a device physically is, in one readable phrase.
function deviceWhere(d) {
    if (!d) return '—';
    if (d.status === 'installed') {
        if (d.unitId) {
            const live = globalData.find(u => u.id === d.unitId);
            return live ? (live.name || d.unitName || '—') : (d.unitName || '—');
        }
        return d.siteName || 'Installed (location not set)';
    }
    if (d.status === 'allocated') return d.division ? `Division: ${d.division}` : 'Allocated (division not set)';
    return d.location || '—';
}

// X/Y are free text so UTM easting/northing works as well as decimal
// degrees. Only when both look like real lat/long is a map link offered —
// UTM values fall outside these ranges, so they never produce a wrong pin.
function deviceMapLink(d) {
    const x = parseFloat(d && d.posX), y = parseFloat(d && d.posY);
    if (!isFinite(x) || !isFinite(y)) return '';
    if (Math.abs(y) > 90 || Math.abs(x) > 180) return '';
    if (x === 0 && y === 0) return '';
    return `https://www.google.com/maps?q=${y},${x}`;
}

function getFilteredDevices() {
    const status = document.getElementById('devStatusFilter')?.value || '';
    const type = document.getElementById('devTypeFilter')?.value || '';
    const loc = document.getElementById('devLocationFilter')?.value || '';
    const q = (document.getElementById('devSearch')?.value || '').toLowerCase().trim();
    return warehouseDevices.filter(d => {
        if (status && d.status !== status) return false;
        if (type && d.type !== type) return false;
        if (loc && (d.location || '') !== loc) return false;
        if (q) {
            const hay = [d.sn, d.type, d.brand, d.model, d.location, d.siteName,
                         deviceWhere(d), d.note].join(' ').toLowerCase();
            if (!hay.includes(q)) return false;
        }
        return true;
    });
}

function renderDeviceTable() {
    const rows = getFilteredDevices();
    const tbody = document.getElementById('deviceBody');
    if (!tbody) return;

    // KPI strip counts the whole warehouse, not the filtered slice — it is a
    // standing summary, not a reflection of the filters.
    const setText = (id, v) => { const el = document.getElementById(id); if (el) el.textContent = v; };
    DEVICE_STATUSES.forEach(s => {
        setText('devKpi_' + s.key, warehouseDevices.filter(d => d.status === s.key).length);
    });
    setText('deviceCount', `${rows.length} devices`);

    const canEdit = hasAccess('warehouse', 'edit');
    const hasFilter = (document.getElementById('devStatusFilter')?.value || '') ||
                      (document.getElementById('devTypeFilter')?.value || '') ||
                      (document.getElementById('devLocationFilter')?.value || '') ||
                      (document.getElementById('devSearch')?.value || '');

    if (rows.length === 0) {
        tbody.innerHTML = `<tr><td colspan="9" style="text-align:center;padding:24px;color:var(--text-secondary)">${
            hasFilter ? 'No devices match the filter'
                      : 'No devices yet. Click <strong>Add Device</strong> to get started.'
        }</td></tr>`;
        return;
    }

    tbody.innerHTML = rows.map((d, i) => {
        const st = DEVICE_STATUSES.find(s => s.key === d.status) || DEVICE_STATUSES[0];
        const map = deviceMapLink(d);
        const pos = (d.posX || d.posY)
            ? `${escapeHtml(d.posX || '—')}, ${escapeHtml(d.posY || '—')}${
                map ? ` <a href="${map}" target="_blank" rel="noopener" title="Open in map"><i class="fas fa-map-location-dot"></i></a>` : ''}`
            : '<span style="color:var(--text-light)">—</span>';
        return `
        <tr>
            <td>${i + 1}</td>
            <td data-label="Serial Number" style="font-family:monospace;font-size:12px">${escapeHtml(d.sn || '')}</td>
            <td data-label="Type">${d.type ? `<span class="badge badge-cat" style="font-size:10px">${escapeHtml(d.type)}</span>` : '<span style="color:var(--text-light)">—</span>'}</td>
            <td data-label="Brand / Model" style="font-size:12px">${escapeHtml([d.brand, d.model].filter(Boolean).join(' ')) || '<span style="color:var(--text-light)">—</span>'}</td>
            <td data-label="Status"><span class="wh-status wh-status--${st.key}">${escapeHtml(st.label)}</span></td>
            <td data-label="Location" style="font-size:12px">${escapeHtml(deviceWhere(d))}</td>
            <td data-label="Coordinates" style="font-size:12px;white-space:nowrap">${pos}</td>
            <td data-label="Notes" style="max-width:130px;font-size:12px;color:var(--text-secondary)" title="${escapeHtml(d.note || '')}">${
                d.note ? escapeHtml(d.note) : '<span style="color:var(--text-light)">—</span>'}</td>
            <td class="col-actions">
                ${canEdit ? `<div class="row-actions">
                    <button class="btn btn-secondary" title="Edit" aria-label="Edit device" onclick="editDevice(${jsArg(d.id)})"><i class="fas fa-pen"></i></button>
                    <button class="btn btn-secondary" title="Delete" aria-label="Delete device" onclick="deleteDevice(${jsArg(d.id)})"><i class="fas fa-trash" style="color:var(--danger)"></i></button>
                </div>` : ''}
            </td>
        </tr>`;
    }).join('');
}

function clearDeviceFilter() {
    ['devStatusFilter', 'devTypeFilter', 'devLocationFilter'].forEach(id => {
        const el = document.getElementById(id); if (el) el.value = '';
    });
    const s = document.getElementById('devSearch'); if (s) s.value = '';
    renderDeviceTable();
}

// Which fields the form shows depends on the status: a device in the
// warehouse needs a shelf, an installed one needs a unit or a map position.
function onDeviceStatusChange() {
    const status = document.getElementById('devStatus').value;
    const installed = status === 'installed';
    const allocated = status === 'allocated';
    const locGroup = document.getElementById('devLocationGroup');
    const instGroup = document.getElementById('devInstallGroup');
    const divGroup = document.getElementById('devDivisionGroup');
    if (locGroup) locGroup.style.display = installed || allocated ? 'none' : '';
    if (instGroup) instGroup.style.display = installed ? '' : 'none';
    if (divGroup) divGroup.style.display = allocated ? '' : 'none';
}

function showAddDeviceForm() {
    if (!requireEdit('warehouse')) return;
    document.getElementById('deviceModalTitle').textContent = 'Add Device';
    document.getElementById('editDeviceId').value = '';
    document.getElementById('deviceForm').reset();
    document.getElementById('devStatus').value = 'warehouse';
    populateWarehouseFilters();
    onDeviceStatusChange();
    document.getElementById('deviceModal').classList.add('open');
}

function editDevice(id) {
    if (!requireEdit('warehouse')) return;
    const d = warehouseDevices.find(x => x.id === id);
    if (!d) return;
    document.getElementById('deviceModalTitle').textContent = 'Edit Device';
    document.getElementById('editDeviceId').value = d.id;
    populateWarehouseFilters();
    document.getElementById('devSn').value = d.sn || '';
    document.getElementById('devType').value = d.type || '';
    document.getElementById('devBrand').value = d.brand || '';
    document.getElementById('devModel').value = d.model || '';
    document.getElementById('devStatus').value = d.status || 'warehouse';
    document.getElementById('devLocation').value = d.location || '';
    document.getElementById('devDivision').value = d.division || '';
    const live = d.unitId ? globalData.find(u => u.id === d.unitId) : null;
    document.getElementById('devUnit').value = live ? damageUnitLabel(live) : (d.unitName || '');
    document.getElementById('devSite').value = d.siteName || '';
    document.getElementById('devPosX').value = d.posX || '';
    document.getElementById('devPosY').value = d.posY || '';
    document.getElementById('devNote').value = d.note || '';
    onDeviceStatusChange();
    document.getElementById('deviceModal').classList.add('open');
}

function closeDeviceModal() {
    document.getElementById('deviceModal').classList.remove('open');
}

function saveDevice(event) {
    event.preventDefault();
    if (!requireEdit('warehouse')) return;

    const id = document.getElementById('editDeviceId').value;
    const sn = (document.getElementById('devSn').value || '').trim();
    if (!sn) { showToast('Serial number cannot be empty', 'warning'); return; }
    // The serial number is the identity here, so a duplicate would make
    // "where is this device" unanswerable.
    const clash = warehouseDevices.find(d =>
        d.id !== id && (d.sn || '').toLowerCase() === sn.toLowerCase());
    if (clash) { showToast(`SN "${sn}" is already registered`, 'warning'); return; }

    const status = document.getElementById('devStatus').value || 'warehouse';
    const installed = status === 'installed';
    const allocated = status === 'allocated';
    const division = allocated ? (document.getElementById('devDivision').value || '').trim() : '';
    if (allocated && !division) { showToast('Fill in the division that receives the device', 'warning'); return; }

    let unit = null;
    const unitRaw = (document.getElementById('devUnit').value || '').trim();
    const before = id ? warehouseDevices.find(d => d.id === id) : null;
    if (installed && unitRaw) {
        unit = resolveDamageUnit(unitRaw);
        // Linked to a unit this account cannot see (another group) and left as
        // it was: keep that link rather than refuse the save or drop it.
        if (!unit && before && before.unitId && unitRaw === (before.unitName || '') && unitOutsideScope(before.unitId)) unit = { id: before.unitId, name: before.unitName };
        if (!unit) {
            showToast(`Unit "${unitRaw}" not found — pick one from the list`, 'warning');
            return;
        }
    }
    const siteName = installed ? (document.getElementById('devSite').value || '').trim() : '';
    if (installed && !unit && !siteName) {
        showToast('Installed device: fill in the unit or the installation site', 'warning');
        return;
    }

    const existing = id ? warehouseDevices.find(d => d.id === id) : null;
    const rec = {
        id: id || generateDeviceId(),
        sn,
        type: (document.getElementById('devType').value || '').trim(),
        brand: (document.getElementById('devBrand').value || '').trim(),
        model: (document.getElementById('devModel').value || '').trim(),
        status,
        location: installed || allocated ? '' : (document.getElementById('devLocation').value || '').trim(),
        division,
        unitId: unit ? unit.id : '',
        unitName: unit ? (unit.name || '') : '',
        siteName,
        posX: installed ? (document.getElementById('devPosX').value || '').trim() : '',
        posY: installed ? (document.getElementById('devPosY').value || '').trim() : '',
        note: (document.getElementById('devNote').value || '').trim(),
        createdAt: existing ? (existing.createdAt || Date.now()) : Date.now(),
        updatedAt: Date.now()
    };

    cloudWrite(
        {
            action: existing ? 'update' : 'create',
            unitId: rec.unitId,
            unitName: `[Inventory] ${rec.type || 'Device'} ${rec.sn}`,
            field: 'Device',
            before: existing ? `${DEVICE_STATUS_LABEL[existing.status] || existing.status} · ${deviceWhere(existing)}` : '',
            after: `${DEVICE_STATUS_LABEL[rec.status] || rec.status} · ${deviceWhere(rec)}`
        },
        cloudCall('saveDevice', rec),
        existing ? 'Device updated' : 'Device added',
        err => {
            console.error('[warehouse] device save failed:', err);
            if (err && err.code === 'permission-denied') showWarehouseRulesBanner();
            showToast('Failed to save device', 'error');
        }
    );

    closeDeviceModal();
}

function deleteDevice(id) {
    if (!requireEdit('warehouse')) return;
    const d = warehouseDevices.find(x => x.id === id);
    if (!d) return;
    if (!confirm(`Delete device ${d.type || ''} SN ${d.sn}?\n\nIts history in the audit log is kept.`)) return;
    cloudWrite(
        { action: 'delete',
          unitName: `[Inventory] ${d.type || 'Device'} ${d.sn}`,
          field: 'Device',
          before: `${DEVICE_STATUS_LABEL[d.status] || d.status} · ${deviceWhere(d)}`,
          after: '' },
        cloudCall('deleteDevice', id),
        'Device deleted',
        err => {
            console.error('[warehouse] device delete failed:', err);
            showToast('Failed to delete device', 'error');
        }
    );
}

function exportDeviceCSV() {
    if (!canCsv('export')) return;
    const rows = getFilteredDevices();
    if (rows.length === 0) { showToast('No devices to export', 'warning'); return; }
    const headers = ['No', 'Serial Number', 'Type', 'Brand', 'Model', 'Status',
                     'Warehouse Location', 'Installed on Unit', 'Installation Site', 'Position X', 'Position Y', 'Notes', 'Division'];
    const dataRows = rows.map((d, i) => [
        i + 1, d.sn || '', d.type || '', d.brand || '', d.model || '',
        DEVICE_STATUS_LABEL[d.status] || d.status || '',
        d.location || '',
        d.unitId ? deviceWhere(d) : '',
        d.siteName || '', d.posX || '', d.posY || '', d.note || '', d.division || ''
    ]);
    const csv = toCSV(headers, dataRows);
    const blob = new Blob(['﻿' + csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `perangkat_gudang_${toISODate()}.csv`;
    a.click();
    URL.revokeObjectURL(url);
    showToast(`Exported ${rows.length} devices to CSV`, 'success');
}

// Devices fitted to one tractor — surfaced on the unit profile.
function devicesForUnit(unitId) {
    if (!unitId) return [];
    return warehouseDevices.filter(d => d.status === 'installed' && d.unitId === unitId);
}

// ============================================================
// VEHICLES & FUEL — company motorbikes and every refuel
// ------------------------------------------------------------
// A vehicle starts from its handover: the date and the odometer reading on
// that day. After that, each refuel is one record — date, liters, odometer,
// and optionally a photo of the receipt. Distance and consumption follow
// from consecutive odometer readings:
//   distance  = this refuel's km − the previous reading (handover first)
//   km / L    = that distance ÷ this refuel's liters
// The second assumes the tank is filled each time, so it is shown as an
// estimate. A reading below the one before it is flagged rather than refused
// — the record may be the one that is right — and so is a consumption far
// from the vehicle's usual.
// ============================================================

const VEHICLE_TYPES = ['Motorbike', 'Car', 'Other'];
// Records created here whose create the server refused. Queued writes settle
// in order, so a delete made offline right after learns it here and does not
// put back a record that exists nowhere.
const _refusedCreates = new Set();
const FUEL_UNUSUAL_FACTOR = 2;        // km/L outside ×½ … ×2 of the vehicle's median
const FUEL_BIG_JUMP_KM = 1500;        // a refuel this far from the last one asks first

let vehicles = [];
let fuelLogs = [];
let _fuelPhotoData = '';
let _fuelPhotoDirty = false;
let _fuelPhotoLoading = false;
let _fuelFormGen = 0;
let _fuelPhotoBusy = 0;
const _fuelPhotoCache = new Map();    // fuel record id -> data URL

function generateVehicleId() { return 'veh_' + Date.now() + '_' + Math.random().toString(36).substr(2, 5); }
function generateFuelId() { return 'fuel_' + Date.now() + '_' + Math.random().toString(36).substr(2, 5); }

function fmtNum(n, digits) {
    const v = Number(n);
    if (!isFinite(v)) return '—';
    return v.toLocaleString('en-US', { minimumFractionDigits: digits || 0, maximumFractionDigits: digits || 0 });
}
function fmtKm(n) { return `${fmtNum(n)} km`; }

// Typed on an Indonesian phone, "3,5" means three and a half and "9.012"
// means nine thousand and twelve. A number field read "3,5" as 35 and
// "9.012" as 9.012, so both fields are text and parsed here.
// Liters: one decimal mark, ',' or '.', at most two decimals. NaN otherwise.
function parseLiters(raw) {
    const t = String(raw == null ? '' : raw).trim().replace(/\s+/g, '');
    if (!/^\d+([.,]\d{1,2})?$/.test(t)) return NaN;
    return Number(t.replace(',', '.'));
}
// Odometer: whole km, optionally grouped by '.', ',' or spaces in threes.
function parseKm(raw) {
    const t = String(raw == null ? '' : raw).trim().replace(/\s+/g, '');
    if (/^\d+$/.test(t)) return Number(t);
    if (/^\d{1,3}([.,]\d{3})+$/.test(t)) return Number(t.replace(/[.,]/g, ''));
    return NaN;
}
function fmtLiters(n) { return `${fmtNum(n, 2).replace(/\.?0+$/, '')} L`; }
function vehicleLabel(v) {
    if (!v) return '—';
    const bm = [v.brand, v.model].filter(Boolean).join(' ');
    return bm ? `${v.plate} · ${bm}` : (v.plate || '—');
}

// ---- Cloud snapshots ----
function applyCloudVehiclesSnapshot(list) {
    _markLoaded('vehicles');
    vehicles = (list || []).slice().sort((a, b) =>
        ((a.status === 'retired') - (b.status === 'retired')) || (a.plate || '').localeCompare(b.plate || ''));
    if (currentView === 'warehouse' && warehouseTab === 'vehicles') renderVehicleView();
    scheduleDecisionRefresh();
}
function applyCloudFuelSnapshot(list) {
    _markLoaded('fuelLogs');
    // A record changed elsewhere may carry a new receipt photo.
    const seenAt = new Map(fuelLogs.map(r => [r.id, r.updatedAt]));
    (list || []).forEach(r => { if (seenAt.has(r.id) && seenAt.get(r.id) !== r.updatedAt) _fuelPhotoCache.delete(r.id); });
    fuelLogs = (list || []).slice();
    if (currentView === 'warehouse' && warehouseTab === 'vehicles') renderVehicleView();
    scheduleDecisionRefresh();
}

// ---- The arithmetic ----
// Records of one vehicle in the order they happened, each with what follows
// from the reading before it.
// logs: an alternative list (the form checks what a save would change).
function fuelHistory(vehicleId, logs) {
    const v = vehicles.find(x => x.id === vehicleId);
    const startKm = v ? Number(v.startKm) || 0 : 0;
    const recs = (logs || fuelLogs).filter(r => r.vehicleId === vehicleId)
        .slice().sort((a, b) => String(a.date || '').localeCompare(String(b.date || '')) ||
                                 (Number(a.km) || 0) - (Number(b.km) || 0) ||
                                 (a.createdAt || 0) - (b.createdAt || 0));
    const handover = v ? v.handoverDate || '' : '';
    // The next record is measured from the highest reading so far (one
    // mistyped low value must not double-count the distance after it), and
    // the date that reading was taken.
    let prev = startKm, prevDate = handover;
    let carry = 0;            // liters of mistyped low readings
    let lastMeasured = null;  // the record the last distance was measured on
    let baseline = false;     // a fill at the handover reading was seen
    const out = recs.map(r => {
        const km = Number(r.km) || 0;
        const liters = Number(r.liters) || 0;
        const flags = [];
        let distance = km - prev;
        // used: the liters this record's distance is divided by (full tank
        // to full tank); null when it measured no distance.
        const x = { rec: r, km, liters, distance, kmPerL: null, used: null, flags, prevKm: prev, prevDate };
        if (km < startKm) flags.push('belowStart');
        if (distance < 0) {
            flags.push('back'); x.distance = null;
            // Its true reading lies inside the next span, so its fuel was used
            // there — unless it is from before the handover.
            if (!(handover && (r.date || '') < handover)) carry += liters;
        } else if (distance === 0) {
            if (!lastMeasured && !baseline) {
                // Filled at the handover reading: the full tank the first
                // distance is measured from. Not a mistake, and not consumption.
                baseline = true;
            } else {
                flags.push('noDistance');
                // A top-up at the same reading completes the fill before it.
                if (lastMeasured) {
                    lastMeasured.used += liters;
                    lastMeasured.kmPerL = lastMeasured.distance / lastMeasured.used;
                }
            }
        } else {
            x.used = liters + carry;
            carry = 0;
            x.kmPerL = x.used > 0 ? distance / x.used : null;
            lastMeasured = x;
        }
        if (km >= prev) { prev = km; prevDate = r.date || ''; }
        return x;
    });
    const rates = out.map(x => x.kmPerL).filter(x => x != null).sort((a, b) => a - b);
    if (rates.length >= 3) {
        const mid = rates.length >> 1;
        const median = rates.length % 2 ? rates[mid] : (rates[mid - 1] + rates[mid]) / 2;
        out.forEach(x => {
            if (x.kmPerL != null && (x.kmPerL > median * FUEL_UNUSUAL_FACTOR || x.kmPerL < median / FUEL_UNUSUAL_FACTOR)) x.flags.push('unusual');
        });
    }
    return out;
}

function vehicleStats(v, month) {
    const hist = fuelHistory(v.id);
    const startKm = Number(v.startKm) || 0;
    const latestKm = hist.reduce((m, x) => Math.max(m, x.km), startKm);
    const totalLiters = hist.reduce((s, x) => s + x.liters, 0);
    // Only fuel with a measured distance after it goes into the average: not a
    // fill at the handover reading, nor one after the last good reading.
    const measured = hist.filter(x => x.used != null);
    const usedLiters = measured.reduce((s, x) => s + x.used, 0);
    const usedKm = measured.reduce((s, x) => s + x.distance, 0);
    const inMonth = month ? hist.filter(x => String(x.rec.date || '').slice(0, 7) === month) : [];
    return {
        hist, startKm, latestKm,
        totalKm: latestKm - startKm,
        totalLiters,
        usedLiters,
        avgKmPerL: usedLiters > 0 && usedKm > 0 ? usedKm / usedLiters : null,
        last: hist.length ? hist[hist.length - 1] : null,
        flagged: hist.filter(x => x.flags.length).length,
        monthLiters: inMonth.reduce((s, x) => s + x.liters, 0),
        monthKm: inMonth.reduce((s, x) => s + (x.distance > 0 ? x.distance : 0), 0),
        monthFills: inMonth.length
    };
}

const FUEL_FLAG_TEXT = {
    back: 'Odometer lower than the reading before',
    belowStart: 'Odometer below the handover reading',
    noDistance: 'Same odometer as the reading before',
    unusual: 'Consumption far from this vehicle\'s usual'
};

// ---- Rendering ----
function populateFuelFilters() {
    const sel = document.getElementById('fuelVehicleFilter');
    if (sel) {
        const keep = sel.value;
        sel.innerHTML = '<option value="">All Vehicles</option>' +
            vehicles.map(v => `<option value="${escapeHtml(v.id)}">${escapeHtml(vehicleLabel(v))}</option>`).join('');
        if (keep && sel.querySelector(`option[value="${CSS.escape(keep)}"]`)) sel.value = keep;
    }
    const holders = document.getElementById('vehHolderList');
    if (holders) holders.innerHTML = _mergeSuggestions([], [...activeMembers().map(m => m.name), ...vehicles.map(v => v.holder)])
        .map(n => `<option value="${escapeHtml(n)}"></option>`).join('');
}

function renderVehicleView() {
    populateFuelFilters();
    const month = toISODate().slice(0, 7);
    const active = vehicles.filter(v => v.status !== 'retired');
    const stats = new Map(vehicles.map(v => [v.id, vehicleStats(v, month)]));
    const setText = (id, v) => { const el = document.getElementById(id); if (el) el.textContent = v; };
    let mLit = 0, mKm = 0, mFills = 0, flagged = 0;
    stats.forEach(s => { mLit += s.monthLiters; mKm += s.monthKm; mFills += s.monthFills; flagged += s.flagged; });
    setText('vehKpi_count', active.length);
    setText('vehKpi_liters', fmtLiters(mLit));
    setText('vehKpi_fills', `${mFills} refuel${mFills === 1 ? '' : 's'}`);
    setText('vehKpi_km', fmtKm(mKm));
    setText('vehKpi_flags', flagged);

    const canEdit = hasAccess('warehouse', 'edit');
    const cards = document.getElementById('vehicleCards');
    if (cards) {
        cards.innerHTML = vehicles.length ? vehicles.map(v => {
            const s = stats.get(v.id);
            const retired = v.status === 'retired';
            const lastLine = s.last
                ? `Last refuel ${escapeHtml(s.last.rec.date || '')} · ${fmtLiters(s.last.liters)} at ${fmtKm(s.last.km)}`
                : 'No refuel logged yet';
            return `
            <article class="vehicle-card${retired ? ' vehicle-card--retired' : ''}">
                <header class="vehicle-card__head">
                    <div>
                        <div class="vehicle-card__plate"><i class="fas fa-${v.type === 'Car' ? 'car' : 'motorcycle'}"></i> ${escapeHtml(v.plate || '')}</div>
                        <div class="vehicle-card__sub">${escapeHtml([v.brand, v.model].filter(Boolean).join(' ') || v.type || '')}${v.holder ? ' · ' + escapeHtml(v.holder) : ''}</div>
                    </div>
                    ${retired ? '<span class="wh-status wh-status--retired">Retired</span>' : ''}
                </header>
                <dl class="vehicle-card__stats">
                    <div><dt>Odometer now</dt><dd>${fmtKm(s.latestKm)}</dd></div>
                    <div><dt>Since handover</dt><dd>${fmtKm(s.totalKm)}</dd></div>
                    <div><dt>Fuel total</dt><dd>${fmtLiters(s.totalLiters)}</dd></div>
                    <div><dt>Average</dt><dd>${s.avgKmPerL != null ? '≈ ' + fmtNum(s.avgKmPerL, 1) + ' km/L' : '—'}${
                        s.avgKmPerL != null && s.totalLiters - s.usedLiters > 0.005
                            ? `<small class="vehicle-card__aside" title="Fuel with no measured distance after it (a fill at the handover reading, or since the last good reading) is not in the average">excl. ${fmtLiters(s.totalLiters - s.usedLiters)}</small>` : ''}</dd></div>
                </dl>
                <p class="vehicle-card__meta">Handover ${escapeHtml(v.handoverDate || '—')} at ${fmtKm(s.startKm)} · ${lastLine}${
                    s.flagged ? ` · <span class="vehicle-card__flag"><i class="fas fa-triangle-exclamation"></i> ${s.flagged} to check</span>` : ''}</p>
                ${v.note ? `<p class="vehicle-card__meta vehicle-card__note">${escapeHtml(v.note)}</p>` : ''}
                <div class="vehicle-card__actions">
                    ${canEdit && !retired ? `<button class="btn btn-primary btn-sm" onclick="showFuelForm(${jsArg(v.id)})"><i class="fas fa-gas-pump"></i> Log Fuel</button>` : ''}
                    <button class="btn btn-secondary btn-sm" onclick="showVehicleHistory(${jsArg(v.id)})"><i class="fas fa-list"></i> Records</button>
                    ${canEdit ? `<button class="btn btn-secondary btn-sm" onclick="editVehicle(${jsArg(v.id)})"><i class="fas fa-pen"></i> Edit</button>
                    <button class="btn btn-secondary btn-sm" title="Delete vehicle" aria-label="Delete vehicle ${escapeHtml(v.plate || '')}" onclick="deleteVehicle(${jsArg(v.id)})"><i class="fas fa-trash" style="color:var(--danger)"></i></button>` : ''}
                </div>
            </article>`;
        }).join('') : `<div class="vehicle-empty">No vehicles yet.${canEdit ? ' Click <strong>Add Vehicle</strong> and enter the handover date and the odometer reading on that day.' : ''}</div>`;
    }
    renderFuelTable();
}

function getFilteredFuelRows() {
    const vid = document.getElementById('fuelVehicleFilter')?.value || '';
    const month = document.getElementById('fuelMonthFilter')?.value || '';
    const rows = [];
    vehicles.forEach(v => {
        if (vid && v.id !== vid) return;
        fuelHistory(v.id).forEach(x => {
            if (month && String(x.rec.date || '').slice(0, 7) !== month) return;
            rows.push({ ...x, vehicle: v });
        });
    });
    // Records whose vehicle was deleted elsewhere still show, unmeasured.
    if (!vid) fuelLogs.filter(r => !vehicles.some(v => v.id === r.vehicleId)).forEach(r => {
        if (month && String(r.date || '').slice(0, 7) !== month) return;
        rows.push({ rec: r, km: Number(r.km) || 0, liters: Number(r.liters) || 0, distance: null, kmPerL: null, flags: [], vehicle: null });
    });
    return rows.sort((a, b) => String(b.rec.date || '').localeCompare(String(a.rec.date || '')) || b.km - a.km);
}

function renderFuelTable() {
    const tbody = document.getElementById('fuelBody');
    if (!tbody) return;
    const rows = getFilteredFuelRows();
    const count = document.getElementById('fuelCount');
    if (count) count.textContent = `${rows.length} record${rows.length === 1 ? '' : 's'}`;
    if (!rows.length) {
        const filtered = (document.getElementById('fuelVehicleFilter')?.value || '') || (document.getElementById('fuelMonthFilter')?.value || '');
        tbody.innerHTML = `<tr><td colspan="10" style="text-align:center;padding:24px;color:var(--text-secondary)">${
            filtered ? 'No fuel records match the filter' : 'No fuel records yet. Use <strong>Log Fuel</strong> after each refuel.'}</td></tr>`;
        return;
    }
    const canEdit = hasAccess('warehouse', 'edit');
    const dash = '<span style="color:var(--text-light)">—</span>';
    tbody.innerHTML = rows.map((x, i) => {
        const r = x.rec;
        const flags = x.flags.map(f => `<span class="fuel-flag" title="${escapeHtml(FUEL_FLAG_TEXT[f] || f)}"><i class="fas fa-triangle-exclamation"></i> ${escapeHtml(FUEL_FLAG_TEXT[f] || f)}</span>`).join('');
        return `
        <tr${x.flags.length ? ' class="row-flagged"' : ''}>
            <td>${i + 1}</td>
            <td data-label="Date" style="white-space:nowrap">${escapeHtml(r.date || '')}</td>
            <td data-label="Vehicle"><strong>${escapeHtml(x.vehicle ? x.vehicle.plate : (r.vehiclePlate || '(deleted vehicle)'))}</strong></td>
            <td data-label="Odometer" class="num">${fmtKm(x.km)}</td>
            <td data-label="Distance" class="num">${x.distance != null ? '+' + fmtKm(x.distance) : dash}</td>
            <td data-label="Liters" class="num">${fmtLiters(x.liters)}</td>
            <td data-label="km / L" class="num">${x.kmPerL != null ? '≈ ' + fmtNum(x.kmPerL, 1) : dash}</td>
            <td data-label="Receipt">${r.hasPhoto ? `<button type="button" class="wl-photo-btn" title="View receipt" aria-label="View receipt photo" onclick="openFuelPhoto(${jsArg(r.id)}, this)"><i class="fas fa-image"></i> Photo</button>` : dash}</td>
            <td data-label="Notes" style="max-width:220px;font-size:12px;color:var(--text-secondary);white-space:normal">${flags}${r.note ? `<div>${escapeHtml(r.note)}</div>` : (flags ? '' : dash)}</td>
            <td class="col-actions">${canEdit ? `<div class="row-actions">
                <button class="btn btn-secondary" title="Edit" aria-label="Edit fuel record" onclick="editFuelLog(${jsArg(r.id)})"><i class="fas fa-pen"></i></button>
                <button class="btn btn-secondary" title="Delete" aria-label="Delete fuel record" onclick="deleteFuelLog(${jsArg(r.id)})"><i class="fas fa-trash" style="color:var(--danger)"></i></button>
            </div>` : ''}</td>
        </tr>`;
    }).join('');
}

function clearFuelFilter() {
    ['fuelVehicleFilter', 'fuelMonthFilter'].forEach(id => { const el = document.getElementById(id); if (el) el.value = ''; });
    renderVehicleView();
}

function showVehicleHistory(id) {
    const sel = document.getElementById('fuelVehicleFilter');
    if (sel) sel.value = id;
    const m = document.getElementById('fuelMonthFilter');
    if (m) m.value = '';
    renderVehicleView();
    document.getElementById('fuelTable')?.closest('.table-card')?.scrollIntoView({ behavior: 'smooth', block: 'start' });
}

// ---- Vehicle form ----
function showAddVehicleForm() {
    if (!requireEdit('warehouse')) return;
    document.getElementById('vehicleModalTitle').innerHTML = '<i class="fas fa-motorcycle"></i> Add Vehicle';
    document.getElementById('vehicleForm').reset();
    document.getElementById('editVehicleId').value = '';
    document.getElementById('vehType').value = 'Motorbike';
    document.getElementById('vehStatus').value = 'active';
    document.getElementById('vehHandover').value = toISODate();
    populateFuelFilters();
    document.getElementById('vehicleModal').classList.add('open');
}

function editVehicle(id) {
    if (!requireEdit('warehouse')) return;
    const v = vehicles.find(x => x.id === id);
    if (!v) return;
    document.getElementById('vehicleModalTitle').innerHTML = '<i class="fas fa-motorcycle"></i> Edit Vehicle';
    document.getElementById('editVehicleId').value = v.id;
    populateFuelFilters();
    document.getElementById('vehPlate').value = v.plate || '';
    document.getElementById('vehType').value = VEHICLE_TYPES.includes(v.type) ? v.type : 'Other';
    document.getElementById('vehBrand').value = v.brand || '';
    document.getElementById('vehModel').value = v.model || '';
    document.getElementById('vehHandover').value = v.handoverDate || '';
    document.getElementById('vehStartKm').value = v.startKm != null ? v.startKm : '';
    document.getElementById('vehHolder').value = v.holder || '';
    document.getElementById('vehStatus').value = v.status === 'retired' ? 'retired' : 'active';
    document.getElementById('vehNote').value = v.note || '';
    document.getElementById('vehicleModal').classList.add('open');
}

function closeVehicleModal(force) {
    const m = document.getElementById('vehicleModal');
    if (!force && m.classList.contains('open') && !okToDiscardTyping('vehicleForm')) return;
    m.classList.remove('open');
}

function saveVehicle(event) {
    event.preventDefault();
    if (!requireEdit('warehouse')) return;
    const id = document.getElementById('editVehicleId').value;
    const plate = (document.getElementById('vehPlate').value || '').trim();
    if (!plate) { showToast('Fill in the plate number or a name', 'warning'); return; }
    const clash = vehicles.find(v => v.id !== id && (v.plate || '').toLowerCase() === plate.toLowerCase());
    if (clash) { showToast(`"${plate}" is already registered`, 'warning'); return; }
    const startKm = parseKm(document.getElementById('vehStartKm').value);
    if (!isFinite(startKm)) { showToast('Odometer at handover must be a whole number of km, e.g. 8880', 'warning'); return; }
    const handoverDate = document.getElementById('vehHandover').value;
    if (!handoverDate) { showToast('Fill in the handover date', 'warning'); return; }
    const existing = id ? vehicles.find(v => v.id === id) : null;
    // Records below the new handover reading would all turn into "below start".
    if (existing && startKm !== Number(existing.startKm)) {
        const below = fuelLogs.filter(r => r.vehicleId === id && Number(r.km) < startKm).length;
        if (below && !confirm(`${below} fuel record(s) have an odometer below ${fmtKm(startKm)}. Change the handover reading anyway?`)) return;
    }
    const rec = {
        id: id || generateVehicleId(),
        plate,
        type: document.getElementById('vehType').value || 'Motorbike',
        brand: (document.getElementById('vehBrand').value || '').trim(),
        model: (document.getElementById('vehModel').value || '').trim(),
        handoverDate,
        startKm: Math.round(startKm),
        holder: (document.getElementById('vehHolder').value || '').trim(),
        status: document.getElementById('vehStatus').value === 'retired' ? 'retired' : 'active',
        note: (document.getElementById('vehNote').value || '').trim(),
        createdAt: existing ? (existing.createdAt || Date.now()) : Date.now(),
        updatedAt: Date.now()
    };
    // Shown at once; the snapshot confirms it.
    const idx = vehicles.findIndex(v => v.id === rec.id);
    if (idx === -1) vehicles.push(rec); else vehicles[idx] = rec;
    cloudWrite(
        { action: existing ? 'update' : 'create', unitName: `[Vehicle] ${plate}`, field: 'Vehicle',
          before: existing ? `${existing.brand || ''} · handover ${existing.handoverDate || ''} at ${fmtKm(existing.startKm)}` : '',
          after: `${rec.brand || ''} · handover ${rec.handoverDate} at ${fmtKm(rec.startKm)}${rec.status === 'retired' ? ' · retired' : ''}` },
        cloudCall('saveVehicle', rec),
        existing ? 'Vehicle updated' : 'Vehicle added',
        err => {
            console.error('[vehicles] save failed:', err);
            if (!existing) _refusedCreates.add('veh:' + rec.id);
            if (err && err.code === 'permission-denied') showWarehouseRulesBanner();
            showToast('Failed to save the vehicle', 'error');
            const i = vehicles.findIndex(x => x.id === rec.id);
            if (i !== -1 && vehicles[i] === rec) { if (existing) vehicles[i] = existing; else vehicles.splice(i, 1); }
            renderVehicleView();
        }
    );
    closeVehicleModal(true);
    renderVehicleView();
}

function deleteVehicle(id) {
    if (!requireEdit('warehouse')) return;
    const v = vehicles.find(x => x.id === id);
    if (!v) return;
    const n = fuelLogs.filter(r => r.vehicleId === id).length;
    if (n) { showToast(`${v.plate} has ${n} fuel record(s) — set its status to Retired instead`, 'warning'); return; }
    if (!confirm(`Delete vehicle ${v.plate}?`)) return;
    vehicles = vehicles.filter(x => x.id !== id);
    cloudWrite({ action: 'delete', unitName: `[Vehicle] ${v.plate}`, field: 'Vehicle', before: vehicleLabel(v), after: '' },
        cloudCall('deleteVehicle', id), 'Vehicle deleted',
        err => {
            console.error('[vehicles] delete failed:', err);
            showToast('Failed to delete the vehicle', 'error');
            if (_refusedCreates.delete('veh:' + id)) return;
            if (!vehicles.some(x => x.id === id)) { vehicles.push(v); renderVehicleView(); }
        });
    renderVehicleView();
}

// ---- Fuel form ----
function _fuelVehicleOptions(selectedId) {
    const sel = document.getElementById('fuelVehicle');
    if (!sel) return;
    const usable = vehicles.filter(v => v.status !== 'retired' || v.id === selectedId);
    sel.innerHTML = (usable.length > 1 ? '<option value="">— Select vehicle —</option>' : '') +
        usable.map(v => `<option value="${escapeHtml(v.id)}">${escapeHtml(vehicleLabel(v))}</option>`).join('');
    if (selectedId) sel.value = selectedId;
}

// What saving this record would do, worked out on the history itself, so the
// form says exactly what the table will then show: the reading just before
// it in time, whether it would be marked, and which later record would be.
function _fuelPreview(cand) {
    const others = fuelLogs.filter(r => r.id !== cand.id);
    const beforeFlags = new Map(fuelHistory(cand.vehicleId, others).map(x => [x.rec.id, x.flags.join('|')]));
    const hist = fuelHistory(cand.vehicleId, others.concat([cand]));
    const me = hist.find(x => x.rec.id === cand.id);
    const newlyFlagged = hist.filter(x => x.rec.id !== cand.id && x.flags.includes('back') &&
                                          !(beforeFlags.get(x.rec.id) || '').includes('back'));
    return { me, newlyFlagged };
}

// A fill already logged on the same day at a higher reading: a lower one
// typed now sorts before it, so nothing would be marked — but it is more
// often a mistyped reading than an earlier fill. Asked only when the reading
// or date is new, so editing that earlier fill asks nothing.
function _fuelSameDayHigher(id, vehicleId, date, km) {
    const existing = fuelLogs.find(r => r.id === id);
    if (existing && existing.vehicleId === vehicleId && existing.date === date && Number(existing.km) === Math.round(km)) return null;
    return fuelLogs.filter(r => r.vehicleId === vehicleId && r.id !== id && r.date === date && (Number(r.km) || 0) > km)
        .reduce((m, r) => (!m || Number(r.km) > Number(m.km) ? r : m), null);
}

function updateFuelKmHint() {
    const hint = document.getElementById('fuelKmHint');
    if (!hint) return;
    const vid = document.getElementById('fuelVehicle').value;
    hint.className = 'form-hint';
    if (!vid) { hint.textContent = ''; return; }
    const raw = document.getElementById('fuelKm').value;
    const km = parseKm(raw);
    const date = document.getElementById('fuelDate').value || toISODate();
    const id = document.getElementById('editFuelId').value || '__new__';
    const v = vehicles.find(x => x.id === vid);
    if (v && v.handoverDate && date < v.handoverDate) {
        hint.textContent = `Handover reading: ${fmtKm(v.startKm)} on ${v.handoverDate} — this date is before the handover`;
        hint.classList.add('form-hint--bad');
        return;
    }
    // With no reading typed yet, preview after everything on that date, to
    // find the latest reading up to and including it.
    const p = _fuelPreview({ id, vehicleId: vid, date, km: isFinite(km) ? km : Number.MAX_SAFE_INTEGER, liters: 0, createdAt: Date.now() });
    const prevWhat = p.me.prevDate ? ` on ${p.me.prevDate}` : '';
    let text = `Previous reading: ${fmtKm(p.me.prevKm)}${prevWhat}`;
    if (raw.trim() === '') { hint.textContent = text; return; }
    const sameDay = isFinite(km) ? _fuelSameDayHigher(id, vid, date, km) : null;
    if (!isFinite(km)) { text += ' — type the odometer as a whole number of km'; hint.classList.add('form-hint--bad'); }
    else if (p.me.flags.includes('back')) { text += ` — this is ${fmtKm(p.me.prevKm - km)} LOWER`; hint.classList.add('form-hint--bad'); }
    else if (sameDay) { text = `${fmtKm(sameDay.km)} is already logged on ${date} — was ${fmtKm(km)} an earlier fill that day?`; hint.classList.add('form-hint--bad'); }
    else if (p.newlyFlagged.length) { text += ` — but ${fmtKm(km)} is HIGHER than the later reading ${fmtKm(p.newlyFlagged[0].km)} on ${p.newlyFlagged[0].rec.date}`; hint.classList.add('form-hint--bad'); }
    else { text += ` — +${fmtKm(km - p.me.prevKm)} since then`; hint.classList.add('form-hint--ok'); }
    hint.textContent = text;
}

function _openFuelModal() {
    _fuelFormGen++;
    _fuelPhotoBusy = 0;
    document.getElementById('fuelModal').classList.add('open');
}

function showFuelForm(vehicleId) {
    if (!requireEdit('warehouse')) return;
    const usable = vehicles.filter(v => v.status !== 'retired');
    if (!usable.length) {
        showToast(vehicles.length ? 'All vehicles are retired — edit one and set it to In use to log fuel' : 'Add a vehicle first', 'warning');
        return;
    }
    document.getElementById('fuelModalTitle').innerHTML = '<i class="fas fa-gas-pump"></i> Log Fuel';
    document.getElementById('fuelForm').reset();
    document.getElementById('editFuelId').value = '';
    _fuelVehicleOptions(vehicleId || (usable.length === 1 ? usable[0].id : ''));
    document.getElementById('fuelDate').value = toISODate();
    _fuelPhotoData = ''; _fuelPhotoDirty = false; _fuelPhotoLoading = false;
    setFuelPhotoPreview();
    updateFuelKmHint();
    _openFuelModal();
}

function editFuelLog(id) {
    if (!requireEdit('warehouse')) return;
    const r = fuelLogs.find(x => x.id === id);
    if (!r) return;
    document.getElementById('fuelModalTitle').innerHTML = '<i class="fas fa-gas-pump"></i> Edit Fuel Record';
    document.getElementById('editFuelId').value = r.id;
    _fuelVehicleOptions(r.vehicleId);
    document.getElementById('fuelDate').value = r.date || '';
    document.getElementById('fuelLiters').value = r.liters != null ? r.liters : '';
    document.getElementById('fuelKm').value = r.km != null ? r.km : '';
    document.getElementById('fuelNote').value = r.note || '';
    _fuelPhotoData = ''; _fuelPhotoDirty = false; _fuelPhotoLoading = !!r.hasPhoto;
    setFuelPhotoPreview();
    updateFuelKmHint();
    _openFuelModal();
    if (_fuelPhotoLoading) {
        const gen = _fuelFormGen;
        loadFuelPhoto(id).then(photo => {
            if (gen !== _fuelFormGen) return;
            _fuelPhotoLoading = false;
            if (!_fuelPhotoDirty) _fuelPhotoData = photo;
            setFuelPhotoPreview();
        }).catch(err => {
            console.error('[fuel] photo load failed:', err);
            if (gen !== _fuelFormGen) return;
            _fuelPhotoLoading = false;
            setFuelPhotoPreview();
            showToast('Existing receipt photo failed to load — it is still saved', 'warning');
        });
    }
}

function closeFuelModal(force) {
    const m = document.getElementById('fuelModal');
    const open = m.classList.contains('open');
    if (!force && open && _fuelPhotoDirty) {
        if (!confirm(_fuelPhotoData ? 'The receipt photo is not saved yet and will be lost. Close anyway?'
                                    : 'The photo change is not saved yet. Close anyway?')) return;
    } else if (!force && open && !okToDiscardTyping('fuelForm')) {
        return;
    }
    _fuelFormGen++;
    _fuelPhotoBusy = 0;
    m.classList.remove('open');
}

async function handleFuelPhotoChange(event) {
    const file = event.target.files && event.target.files[0];
    event.target.value = '';
    if (!file) return;
    if (!file.type.startsWith('image/')) { showToast('The file must be an image (photo)', 'warning'); return; }
    const gen = _fuelFormGen;
    _fuelPhotoBusy++;
    try {
        const data = await compressImageToDataURL(file);
        if (gen !== _fuelFormGen || !document.getElementById('fuelModal').classList.contains('open')) return;
        _fuelPhotoData = data; _fuelPhotoDirty = true; _fuelPhotoLoading = false;
        setFuelPhotoPreview();
    } catch (err) {
        showToast(err.message || 'Failed to process the photo', 'error');
    } finally {
        if (gen === _fuelFormGen) _fuelPhotoBusy = Math.max(0, _fuelPhotoBusy - 1);
    }
}

function setFuelPhotoPreview() {
    const wrap = document.getElementById('fuelPhotoPreviewWrap');
    const img = document.getElementById('fuelPhotoPreview');
    const loading = document.getElementById('fuelPhotoLoading');
    if (loading) loading.style.display = (_fuelPhotoLoading && !_fuelPhotoData) ? '' : 'none';
    if (!wrap || !img) return;
    if (_fuelPhotoData) { img.src = _fuelPhotoData; wrap.style.display = ''; }
    else { img.removeAttribute('src'); wrap.style.display = 'none'; }
}

function removeFuelPhoto() {
    _fuelPhotoData = ''; _fuelPhotoDirty = true; _fuelPhotoLoading = false;
    setFuelPhotoPreview();
}

async function loadFuelPhoto(id) {
    if (_fuelPhotoCache.get(id)) return _fuelPhotoCache.get(id);
    if (!window.cloud || typeof window.cloud.getFuelPhoto !== 'function') return '';
    const photo = await window.cloud.getFuelPhoto(id);
    if (photo) _fuelPhotoCache.set(id, photo);
    return photo;
}

async function openFuelPhoto(id, btn) {
    const r = fuelLogs.find(x => x.id === id);
    const v = r && vehicles.find(x => x.id === r.vehicleId);
    const original = btn ? btn.innerHTML : '';
    if (btn) { btn.disabled = true; btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i>'; }
    let photo = '';
    try {
        photo = await loadFuelPhoto(id);
    } catch (err) {
        console.error('[fuel] photo load failed:', err);
        showToast(navigator.onLine ? 'Failed to load the receipt photo' : 'The photo needs a signal to load', 'error');
        return;
    } finally {
        if (btn) { btn.disabled = false; btn.innerHTML = original; }
    }
    if (!photo) { showToast('Photo not found', 'warning'); return; }
    openPhotoLightbox(photo, 0, { captions: [`Receipt · ${r ? r.date : ''}${v ? ' · ' + v.plate : ''}`] });
}

// Why a receipt photo cannot be sent from here right now, or ''.
function fuelPhotoBlocker() {
    if (!window.cloud?.isReady) return 'Not connected yet — the receipt photo cannot be sent. Try again in a moment';
    if (typeof window.cloud.saveFuelPhoto !== 'function') return 'Reload the page — an old version is still active and cannot send the photo';
    return '';
}

// recordP: the record's own write. A photo refused along with its record
// says nothing — the "Not saved" notice covers both, and reopening sends the
// photo again.
function _sendFuelPhoto(recId, photo, recordP) {
    if (photo) _fuelPhotoCache.set(recId, photo); else _fuelPhotoCache.delete(recId);
    if (suppressCloudWrites || !window.cloud?.isReady) return;
    const call = photo ? cloudCall('saveFuelPhoto', recId, photo) : cloudCall('deleteFuelPhoto', recId);
    Promise.resolve(call).catch(err => {
        console.error('[fuel] photo save failed:', err);
        if (err && err.code === 'permission-denied') showWarehouseRulesBanner();
        Promise.resolve(recordP).then(
            () => showToast(photo ? 'Record saved, but the receipt photo failed to send' : 'Record saved, but removing the photo failed', 'error'),
            () => {});
    });
}

function saveFuelLog(event) {
    event.preventDefault();
    if (!requireEdit('warehouse')) return;
    if (_fuelPhotoBusy > 0) { showToast('The photo is still being processed — save again in a moment', 'warning'); return; }
    const id = document.getElementById('editFuelId').value;
    const vehicleId = document.getElementById('fuelVehicle').value;
    const v = vehicles.find(x => x.id === vehicleId);
    if (!v) { showToast('Pick a vehicle', 'warning'); return; }
    const date = document.getElementById('fuelDate').value;
    if (!date) { showToast('Fill in the date', 'warning'); return; }
    if (date > toISODate()) { showToast('The date is in the future', 'warning'); return; }
    const litRaw = document.getElementById('fuelLiters').value;
    const liters = parseLiters(litRaw);
    if (!isFinite(liters)) { showToast('Liters must be a number like 3.5 or 3,5', 'warning'); return; }
    if (!(liters > 0)) { showToast('Liters must be more than 0', 'warning'); return; }
    const km = parseKm(document.getElementById('fuelKm').value);
    if (!isFinite(km)) { showToast('Fill in the odometer as a whole number of km, e.g. 9012', 'warning'); return; }
    if (_fuelPhotoDirty && _fuelPhotoData) {
        const block = fuelPhotoBlocker();
        if (block) { showToast(block, 'warning'); return; }
    }
    const existing = id ? fuelLogs.find(r => r.id === id) : null;
    // Asked about, not refused: it may be this record that is right and an
    // earlier one that was mistyped. Worked out in date order, so editing an
    // older record (a note, a late photo) asks nothing.
    const p = _fuelPreview({ id: id || '__new__', vehicleId, date, km: Math.round(km), liters, createdAt: existing ? existing.createdAt : Date.now() });
    if (date < (v.handoverDate || '')) {
        if (!confirm(`The date is before the handover (${v.handoverDate} at ${fmtKm(v.startKm)}).${p.me.flags.includes('back') ? ' It will be marked to check.' : ''}\n\nSave anyway?`)) return;
    } else if (p.me.flags.includes('back')) {
        if (!confirm(`The odometer ${fmtKm(km)} is LOWER than the reading before it, ${fmtKm(p.me.prevKm)}${p.me.prevDate ? ' on ' + p.me.prevDate : ''}.\n\nSave anyway? It will be marked to check.`)) return;
    } else {
        const sameDay = _fuelSameDayHigher(id || '__new__', vehicleId, date, km);
        if (sameDay && !confirm(`There is already a fill on ${date} at ${fmtKm(sameDay.km)}. Was ${fmtKm(km)} an earlier fill that day?\n\nSave anyway?`)) return;
    }
    if (p.newlyFlagged.length && !confirm(`The odometer ${fmtKm(km)} is HIGHER than the later reading ${fmtKm(p.newlyFlagged[0].km)} on ${p.newlyFlagged[0].rec.date}, which would then be marked to check.\n\nSave anyway?`)) return;
    if (p.me.distance != null && p.me.distance > FUEL_BIG_JUMP_KM && !confirm(`${fmtKm(p.me.distance)} since the reading before (${fmtKm(p.me.prevKm)}). Is the odometer ${fmtKm(km)} right?`)) return;
    // A typo in liters (an extra digit) is the other common mistake.
    const maxBefore = fuelLogs.filter(r => r.vehicleId === vehicleId && r.id !== id).reduce((m, r) => Math.max(m, Number(r.liters) || 0), 0);
    const tankish = v.type === 'Motorbike' ? 10 : 80;
    if ((liters > tankish || (maxBefore > 0 && liters > maxBefore * 2.5)) &&
        !confirm(`${fmtLiters(liters)} is a lot for one refuel of ${v.plate}${maxBefore ? ` (largest so far ${fmtLiters(maxBefore)})` : ''}. Is it right?`)) return;

    const rec = {
        id: id || generateFuelId(),
        vehicleId,
        vehiclePlate: v.plate || '',
        date,
        liters: Math.round(liters * 100) / 100,
        km: Math.round(km),
        hasPhoto: _fuelPhotoDirty ? !!_fuelPhotoData : !!(existing && existing.hasPhoto),
        note: (document.getElementById('fuelNote').value || '').trim(),
        createdAt: existing ? (existing.createdAt || Date.now()) : Date.now(),
        createdBy: existing ? (existing.createdBy || '') : ((currentUser && currentUser.email) || ''),
        updatedAt: Date.now()
    };
    // The photo goes before the record, so no device sees the record point at
    // a photo the server does not have yet. A removal goes after.
    // Its result is only known later; the photo's failure message waits for it.
    let recordDone;
    const recordP = new Promise((res, rej) => { recordDone = { res, rej }; });
    recordP.catch(() => {});
    if (_fuelPhotoDirty && _fuelPhotoData) _sendFuelPhoto(rec.id, _fuelPhotoData, recordP);
    // Kept in case the server refuses: the "Not saved" notice reopens it.
    const snap = { vals: captureFormState('fuelForm'), photo: _fuelPhotoDirty ? _fuelPhotoData : null };
    const idx = fuelLogs.findIndex(r => r.id === rec.id);
    if (idx === -1) fuelLogs.push(rec); else fuelLogs[idx] = rec;
    cloudWrite(
        { action: existing ? 'update' : 'create', unitName: `[Vehicle] ${v.plate}`, field: 'Fuel',
          before: existing ? `${existing.date} · ${fmtLiters(existing.liters)} at ${fmtKm(existing.km)}` : '',
          after: `${rec.date} · ${fmtLiters(rec.liters)} at ${fmtKm(rec.km)}` },
        Promise.resolve(cloudCall('saveFuelLog', rec)).then(v => { recordDone.res(); return v; }, e => { recordDone.rej(e); throw e; }),
        existing ? 'Fuel record updated' : 'Fuel logged',
        err => {
            console.error('[fuel] save failed:', err);
            // Deleted here before the server refused it: that delete must not
            // bring back a record the server never had.
            if (!existing) _refusedCreates.add('fuel:' + rec.id);
            if (err && err.code === 'permission-denied') showWarehouseRulesBanner();
            // Shown at once, so taken back at once — unless a snapshot has
            // already replaced it with what the server holds.
            const i = fuelLogs.findIndex(r => r.id === rec.id);
            if (i !== -1 && fuelLogs[i] === rec) { if (existing) fuelLogs[i] = existing; else fuelLogs.splice(i, 1); }
            renderVehicleView();
            rememberUnsent(`fuel record — ${v.plate}, ${rec.date}`, err, () => _reopenFuel(snap));
        }
    );
    if (_fuelPhotoDirty && !_fuelPhotoData && existing && existing.hasPhoto) _sendFuelPhoto(rec.id, '', recordP);
    closeFuelModal(true);
    renderVehicleView();
}

function _reopenFuel(snap) {
    const m = document.getElementById('fuelModal');
    // The notice sits above the dialog: another refuel may be half typed.
    if (m.classList.contains('open')) {
        closeFuelModal();
        if (m.classList.contains('open')) return false;
    }
    const id = snap.vals.editFuelId;
    if (id && fuelLogs.some(r => r.id === id)) editFuelLog(id); else showFuelForm(snap.vals.fuelVehicle);
    if (!m.classList.contains('open')) return false;
    applyFormState(snap.vals);
    if (snap.photo != null) { _fuelPhotoData = snap.photo || ''; _fuelPhotoDirty = true; _fuelPhotoLoading = false; setFuelPhotoPreview(); }
    updateFuelKmHint();
    _formReopened.add('fuelForm');
    return true;
}

function deleteFuelLog(id) {
    if (!requireEdit('warehouse')) return;
    const r = fuelLogs.find(x => x.id === id);
    if (!r) return;
    const v = vehicles.find(x => x.id === r.vehicleId);
    const plate = v ? v.plate : (r.vehiclePlate || '');
    if (!confirm(`Delete the fuel record of ${plate} on ${r.date} (${fmtLiters(r.liters)} at ${fmtKm(r.km)})?`)) return;
    fuelLogs = fuelLogs.filter(x => x.id !== id);
    const deleting = cloudCall('deleteFuelLog', id);
    cloudWrite({ action: 'delete', unitName: `[Vehicle] ${plate}`, field: 'Fuel', before: `${r.date} · ${fmtLiters(r.liters)} at ${fmtKm(r.km)}`, after: '' },
        deleting, 'Fuel record deleted',
        err => {
            console.error('[fuel] delete failed:', err);
            showToast('Failed to delete the fuel record', 'error');
            if (_refusedCreates.delete('fuel:' + id)) return;
            if (!fuelLogs.some(x => x.id === id)) { fuelLogs.push(r); renderVehicleView(); }
        });
    // Queued right behind the record's delete (same area, same rules), so it
    // also goes out when the phone is offline and closed before the ack.
    if (r.hasPhoto) { _fuelPhotoCache.delete(id); _dropPhotoDoc('deleteFuelPhoto', id); }
    renderVehicleView();
}

function exportFuelCSV() {
    if (!canCsv('export')) return;
    const rows = getFilteredFuelRows().slice().reverse();
    if (!rows.length) { showToast('No fuel records to export', 'warning'); return; }
    const headers = ['No', 'Date', 'Vehicle', 'Brand', 'Model', 'Odometer (km)', 'Distance (km)', 'Liters', 'km/L (estimate)', 'To check', 'Receipt photo', 'Notes'];
    const body = rows.map((x, i) => [
        i + 1, x.rec.date || '', x.vehicle ? x.vehicle.plate : (x.rec.vehiclePlate || ''),
        x.vehicle ? x.vehicle.brand || '' : '', x.vehicle ? x.vehicle.model || '' : '',
        x.km, x.distance != null ? x.distance : '', x.liters, x.kmPerL != null ? Math.round(x.kmPerL * 10) / 10 : '',
        x.flags.map(f => FUEL_FLAG_TEXT[f] || f).join('; '), x.rec.hasPhoto ? 'Yes' : '', x.rec.note || ''
    ]);
    const blob = new Blob(['﻿' + toCSV(headers, body)], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `fuel_log_${toISODate()}.csv`;
    a.click();
    URL.revokeObjectURL(url);
    showToast(`Exported ${rows.length} fuel record(s) to CSV`, 'success');
}

// ============================================================
// STOCK (counted by quantity)
// ============================================================

// Remaining per item, optionally within one location. IN adds, OUT removes.
// Warns, but lets the owner through: a stocktake can legitimately find the
// ledger behind reality. Editing an existing OUT adds its old quantity back to
// what is available, or the edit would warn about a shortage it is itself
// creating.
function checkStockBalance(itemName, qty, existing) {
    const key = (itemName || '').trim().toLowerCase();
    const row = stockSummary().find(s => s.name.toLowerCase() === key);
    let available = row ? row.qty : 0;
    if (existing && existing.txnType === 'OUT' &&
        (existing.itemName || '').trim().toLowerCase() === key) {
        available += Number(existing.qty) || 0;
    }
    if (qty <= available) return true;
    return confirm(`Only ${available} of "${itemName}" left in stock, but ${qty} going out.\n\n`
        + 'The balance will go negative. Usually this is because the item name differs slightly '
        + 'from an existing one.\n\nSave anyway?');
}

function stockSummary(location) {
    const totals = new Map();
    stockLedger.forEach(r => {
        if (location && (r.location || '') !== location) return;
        const name = (r.itemName || '').trim();
        if (!name) return;
        const key = name.toLowerCase();
        const qty = (Number(r.qty) || 0) * (r.txnType === 'OUT' ? -1 : 1);
        const cur = totals.get(key) || { name, qty: 0 };
        cur.qty += qty;
        totals.set(key, cur);
    });
    return [...totals.values()].sort((a, b) => a.name.localeCompare(b.name));
}

function getFilteredStock() {
    const from = (document.getElementById('stkFrom')?.value || '').trim();
    const to = (document.getElementById('stkTo')?.value || '').trim();
    const item = document.getElementById('stkItemFilter')?.value || '';
    const loc = document.getElementById('stkLocationFilter')?.value || '';
    const type = document.getElementById('stkTypeFilter')?.value || '';
    const q = (document.getElementById('stkSearch')?.value || '').toLowerCase().trim();
    return stockLedger.filter(r => {
        if (from && String(r.date || '') < from) return false;
        if (to && String(r.date || '') > to) return false;
        if (item && (r.itemName || '') !== item) return false;
        if (loc && (r.location || '') !== loc) return false;
        if (type && r.txnType !== type) return false;
        if (q) {
            const hay = [r.itemName, r.location, r.unitName, r.note].join(' ').toLowerCase();
            if (!hay.includes(q)) return false;
        }
        return true;
    });
}

function renderStockView() {
    const loc = document.getElementById('stkLocationFilter')?.value || '';
    const summary = stockSummary(loc);
    const sumEl = document.getElementById('stockSummary');
    if (sumEl) {
        sumEl.innerHTML = summary.length
            ? summary.map(s => `
                <div class="stock-chip${s.qty <= 0 ? ' stock-chip--out' : (s.qty <= STOCK_LOW_THRESHOLD ? ' stock-chip--low' : '')}">
                    <span class="stock-chip__name">${escapeHtml(s.name)}</span>
                    <span class="stock-chip__qty">${s.qty}</span>
                </div>`).join('')
            : '<div class="stock-empty">No items recorded yet.</div>';
    }

    const rows = getFilteredStock();
    const tbody = document.getElementById('stockBody');
    if (!tbody) return;
    const countEl = document.getElementById('stockCount');
    if (countEl) countEl.textContent = `${rows.length} transactions`;

    const canEdit = hasAccess('warehouse', 'edit');
    if (rows.length === 0) {
        tbody.innerHTML = `<tr><td colspan="8" style="text-align:center;padding:24px;color:var(--text-secondary)">
            No stock transactions yet. Click <strong>Record In/Out</strong> to get started.
        </td></tr>`;
        return;
    }

    tbody.innerHTML = rows.map((r, i) => `
        <tr>
            <td>${i + 1}</td>
            <td data-label="Date" style="white-space:nowrap">${escapeHtml(r.date || '')}</td>
            <td data-label="Type"><span class="wh-txn wh-txn--${r.txnType === 'OUT' ? 'out' : 'in'}">${r.txnType === 'OUT' ? 'Out' : 'In'}</span></td>
            <td data-label="Item"><strong>${escapeHtml(r.itemName || '')}</strong></td>
            <td data-label="Quantity" style="white-space:nowrap">${Number(r.qty) || 0}</td>
            <td data-label="Location" style="font-size:12px">${escapeHtml(r.location || '') || '<span style="color:var(--text-light)">—</span>'}</td>
            <td data-label="For Unit" style="font-size:12px">${escapeHtml(r.unitName || '') || '<span style="color:var(--text-light)">—</span>'}</td>
            <td class="col-actions">
                ${canEdit ? `<div class="row-actions">
                    <button class="btn btn-secondary" title="Edit" aria-label="Edit transaction" onclick="editStockItem(${jsArg(r.id)})"><i class="fas fa-pen"></i></button>
                    <button class="btn btn-secondary" title="Delete" aria-label="Delete transaction" onclick="deleteStockItem(${jsArg(r.id)})"><i class="fas fa-trash" style="color:var(--danger)"></i></button>
                </div>` : ''}
            </td>
        </tr>`).join('');
}

function clearStockFilter() {
    ['stkFrom', 'stkTo', 'stkSearch'].forEach(id => {
        const el = document.getElementById(id); if (el) el.value = '';
    });
    ['stkItemFilter', 'stkLocationFilter', 'stkTypeFilter'].forEach(id => {
        const el = document.getElementById(id); if (el) el.value = '';
    });
    renderStockView();
}

function onStockTxnChange() {
    const isOut = document.getElementById('stkTxnType').value === 'OUT';
    const g = document.getElementById('stkUnitGroup');
    if (g) g.style.display = isOut ? '' : 'none';
}

function showAddStockForm() {
    if (!requireEdit('warehouse')) return;
    document.getElementById('stockModalTitle').textContent = 'Record Stock In/Out';
    document.getElementById('editStockId').value = '';
    document.getElementById('stockForm').reset();
    populateWarehouseFilters();
    document.getElementById('stkDate').value = toISODate();
    document.getElementById('stkTxnType').value = 'IN';
    onStockTxnChange();
    document.getElementById('stockModal').classList.add('open');
}

function editStockItem(id) {
    if (!requireEdit('warehouse')) return;
    const r = stockLedger.find(x => x.id === id);
    if (!r) return;
    document.getElementById('stockModalTitle').textContent = 'Edit Stock Transaction';
    document.getElementById('editStockId').value = r.id;
    populateWarehouseFilters();
    document.getElementById('stkDate').value = r.date || '';
    document.getElementById('stkTxnType').value = r.txnType || 'IN';
    document.getElementById('stkItem').value = r.itemName || '';
    document.getElementById('stkQty').value = Number(r.qty) || 1;
    document.getElementById('stkLocation').value = r.location || '';
    const live = r.unitId ? globalData.find(u => u.id === r.unitId) : null;
    document.getElementById('stkUnit').value = live ? damageUnitLabel(live) : (r.unitName || '');
    document.getElementById('stkNote').value = r.note || '';
    onStockTxnChange();
    document.getElementById('stockModal').classList.add('open');
}

function closeStockModal() {
    document.getElementById('stockModal').classList.remove('open');
}

function saveStockItem(event) {
    event.preventDefault();
    if (!requireEdit('warehouse')) return;

    const id = document.getElementById('editStockId').value;
    const itemName = (document.getElementById('stkItem').value || '').trim();
    if (!itemName) { showToast('Fill in the item name', 'warning'); return; }
    const qty = Math.max(1, parseInt(document.getElementById('stkQty').value, 10) || 1);
    const txnType = document.getElementById('stkTxnType').value === 'OUT' ? 'OUT' : 'IN';

    let unit = null;
    const unitRaw = (document.getElementById('stkUnit').value || '').trim();
    const before = id ? stockLedger.find(r => r.id === id) : null;
    if (txnType === 'OUT' && unitRaw) {
        unit = resolveDamageUnit(unitRaw);
        if (!unit && before && before.unitId && unitRaw === (before.unitName || '') && unitOutsideScope(before.unitId)) unit = { id: before.unitId, name: before.unitName };
        if (!unit) {
            showToast(`Unit "${unitRaw}" not found — clear it or pick one from the list`, 'warning');
            return;
        }
    }

    const existing = id ? stockLedger.find(r => r.id === id) : null;

    // Taking out more than the ledger holds means either a miscount or, more
    // often, a typo in the item name that created a phantom item whose real
    // counterpart never gets decremented. The licence ledger already warns
    // like this (saveLicenseStock); the warehouse one did not, and
    // stockSummary would happily render a negative balance.
    if (txnType === 'OUT' && !checkStockBalance(itemName, qty, existing)) return;

    const rec = {
        id: id || generateStockId(),
        date: document.getElementById('stkDate').value,
        txnType,
        itemName,
        qty,
        location: (document.getElementById('stkLocation').value || '').trim(),
        unitId: unit ? unit.id : '',
        unitName: unit ? (unit.name || '') : '',
        note: (document.getElementById('stkNote').value || '').trim(),
        createdAt: existing ? (existing.createdAt || Date.now()) : Date.now(),
        updatedAt: Date.now()
    };

    cloudWrite(
        {
            action: existing ? 'update' : 'create',
            unitId: rec.unitId,
            unitName: `[Inventory] ${rec.itemName}`,
            field: txnType === 'OUT' ? 'Stock out' : 'Stock in',
            before: existing ? `${existing.txnType} ${existing.qty}` : '',
            after: `${txnType} ${qty}${rec.location ? ' @ ' + rec.location : ''}`
        },
        cloudCall('saveStockItem', rec),
        existing ? 'Transaction updated' : 'Transaction recorded',
        err => {
            console.error('[warehouse] stock save failed:', err);
            if (err && err.code === 'permission-denied') showWarehouseRulesBanner();
            showToast('Failed to save transaction', 'error');
        }
    );

    closeStockModal();
}

function deleteStockItem(id) {
    if (!requireEdit('warehouse')) return;
    const r = stockLedger.find(x => x.id === id);
    if (!r) return;
    if (!confirm(`Delete stock-${r.txnType === 'OUT' ? 'out' : 'in'} transaction ${r.qty} ${r.itemName} (${r.date})?`)) return;
    cloudWrite(
        { action: 'delete',
          unitName: `[Inventory] ${r.itemName}`,
          field: 'Stock transaction',
          before: `${r.txnType} ${r.qty}`,
          after: '' },
        cloudCall('deleteStockItem', id),
        'Transaction deleted',
        err => {
            console.error('[warehouse] stock delete failed:', err);
            showToast('Failed to delete transaction', 'error');
        }
    );
}

function exportStockCSV() {
    if (!canCsv('export')) return;
    const rows = getFilteredStock();
    if (rows.length === 0) { showToast('No transactions to export', 'warning'); return; }
    const headers = ['No', 'Date', 'Type', 'Item', 'Quantity', 'Location', 'For Unit', 'Notes'];
    const dataRows = rows.map((r, i) => [
        i + 1, r.date || '', r.txnType === 'OUT' ? 'Out' : 'In',
        r.itemName || '', Number(r.qty) || 0, r.location || '', r.unitName || '', r.note || ''
    ]);
    const csv = toCSV(headers, dataRows);
    const blob = new Blob(['﻿' + csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `stok_gudang_${toISODate()}.csv`;
    a.click();
    URL.revokeObjectURL(url);
    showToast(`Exported ${rows.length} transactions to CSV`, 'success');
}


// ============================================================
// KOTAK KEPUTUSAN — everything waiting on the person in charge
// ------------------------------------------------------------
// Nothing here is newly computed: the licence alerts, the low-stock lists and
// the downtime clocks already existed, each on its own page. What was missing
// was one place that answers "what needs me today", so a backlog on a page
// nobody opened stayed invisible.
//
// Every group is gated by the area it reads from, so this page never becomes a
// way around the access model.
// ============================================================

const LEADER_BREAKDOWN_DAYS = 3;   // a unit down longer than this needs a call

function _daysSince(ms) {
    if (!ms) return 0;
    return Math.floor((Date.now() - ms) / 86400000);
}

// Returns [{ key, title, icon, tone, total, items:[{text, sub}], goto }]
// Only non-empty groups come back — an empty inbox should look empty.
function decisionGroups() {
    const groups = [];
    const add = g => { if (g.total > 0) groups.push(g); };

    // ---- Laporan harian menunggu diperiksa ----
    if (hasAccess('teamLog', 'view') || hasAccess('teamLogApprove', 'edit')) {
        const pending = workLogs.filter(w => workLogApproval(w) === 'pending');
        add({
            key: 'approval', icon: 'clipboard-check', tone: 'warning',
            title: 'Reports pending approval',
            total: pending.length,
            items: pending.slice(0, 6).map(w => ({
                text: `${memberNameOf(w)} · ${w.date}`,
                sub: (w.task || '').slice(0, 70)
            })),
            goto: 'approval'
        });

        const revision = workLogs.filter(w => workLogApproval(w) === 'revision');
        add({
            key: 'revision', icon: 'rotate-left', tone: 'danger',
            title: 'Reports sent back for revision, not yet fixed',
            total: revision.length,
            items: revision.slice(0, 6).map(w => ({
                text: `${memberNameOf(w)} · ${w.date}`,
                sub: w.revisionNote || ''
            })),
            goto: 'revision'
        });

        // Izin / sakit menunggu persetujuan. Digerbang sama dengan laporan,
        // karena areanya memang sama.
        const izin = leaveRequests.filter(r => workLogApproval(r) === 'pending');
        add({
            key: 'leave', icon: 'user-clock', tone: 'warning',
            title: 'Leave / sick requests pending approval',
            total: izin.length,
            items: izin.slice(0, 6).map(r => ({
                text: `${memberNameOf(r)} · ${leaveTypeLabel(r)}`,
                sub: `${leaveRangeLabel(r)} — ${Number(r.days) || leaveDays(r.dateFrom, r.dateTo)} day(s)`
            })),
            goto: 'leave'
        });
    }

    // ---- Pengecekan alat berat ----
    if (['inspection', 'inspectionApprove', 'leader'].some(x => hasAccess(x, 'view'))) {
        const today = toISODate();
        const st = inspectableUnits().map(u => ({ u, s: inspectionStatusFor(u, today) }));
        const late = st.filter(x => x.s.key === 'overdue').sort((a, b) => a.s.days - b.s.days);
        add({
            key: 'insOverdue', icon: 'clipboard-check', tone: 'danger',
            title: 'Heavy equipment overdue for inspection',
            total: late.length,
            items: late.slice(0, 6).map(x => ({ text: x.u.name || x.u.sn || '-', sub: `${x.s.label} · last checked ${x.s.last.date}` })),
            goto: 'inspection:overdue'
        });
        const soon = st.filter(x => x.s.key === 'soon').sort((a, b) => a.s.days - b.s.days);
        add({
            key: 'insSoon', icon: 'calendar-check', tone: 'warning',
            title: `Heavy equipment inspection due (≤${INSPECTION_SOON_DAYS} days)`,
            total: soon.length,
            items: soon.slice(0, 6).map(x => ({ text: x.u.name || x.u.sn || '-', sub: `${x.s.label} · ${x.s.next}` })),
            goto: 'inspection:soon'
        });
        const waiting = inspections.filter(r => workLogApproval(r) === 'pending');
        add({
            key: 'insPending', icon: 'clipboard-list', tone: 'warning',
            title: 'Check reports pending approval',
            total: waiting.length,
            items: waiting.slice(0, 6).map(r => ({ text: `${inspectionUnitLabel(r)} · ${r.date}`, sub: inspectionResultSummary(r).text })),
            goto: 'inspection:pending'
        });
        if (hasAccess('damage', 'edit')) {
            const unapplied = inspections.filter(inspectionNeedsApply);
            add({
                key: 'insApply', icon: 'screwdriver-wrench', tone: 'danger',
                title: 'Approved check findings not yet logged in Damage',
                total: unapplied.length,
                items: unapplied.slice(0, 6).map(r => ({ text: `${inspectionUnitLabel(r)} · ${r.date}`, sub: inspectionResultSummary(r).text })),
                goto: 'inspection:approved'
            });
        }
    }

    // ---- Lisensi habis / segera habis ----
    if (hasAccess('editUnits', 'view')) {
        const alerts = _buildAlertList();
        add({
            key: 'license', icon: 'key', tone: alerts.expiredCount ? 'danger' : 'warning',
            title: alerts.expiredCount
                ? `Expired licenses (${alerts.expiredCount}) and expiring soon (${alerts.soonCount})`
                : 'Licenses expiring soon',
            total: alerts.total,
            // _buildAlertList already sorts soonest-first and formats each line.
            items: alerts.lines.slice(0, 6).map(line => {
                const p = line.split(' | ');
                return { text: `${p[1] || '-'} · ${p[4] || '-'}`, sub: `${p[6] || ''} — ${p[7] || ''}` };
            }),
            // Licences are agricultural-only.
            goto: hasHeavyUnits() ? 'editUnits:tractor' : 'editUnits'
        });

        // ---- Unit breakdown terlalu lama ----
        const stuck = globalData
            .filter(u => u.breakdownStartedAt && _daysSince(u.breakdownStartedAt) >= LEADER_BREAKDOWN_DAYS)
            .sort((a, b) => a.breakdownStartedAt - b.breakdownStartedAt);
        add({
            key: 'breakdown', icon: 'triangle-exclamation', tone: 'danger',
            title: `Units in breakdown over ${LEADER_BREAKDOWN_DAYS} days`,
            total: stuck.length,
            items: stuck.slice(0, 6).map(u => ({
                text: u.name || u.sn || '(no name)',
                sub: `${_daysSince(u.breakdownStartedAt)} day(s) · ${u.site || '-'}${u.breakdownReason ? ' · ' + u.breakdownReason : ''}${isHeavy(u) ? ' · ' + UNIT_GROUPS.heavy.shortLabel : ''}`
            })),
            // With a heavy unit in the list, open the dashboard on "Semua" so
            // the unit is actually on screen when the link lands.
            goto: dashTargetFor(stuck)
        });
    }

    // ---- Stok lisensi menipis ----
    if (hasAccess('licenseStock', 'view')) {
        const low = _lowStockList();
        add({
            key: 'licenseStock', icon: 'layer-group', tone: 'warning',
            title: 'License stock running low',
            total: low.length,
            items: low.slice(0, 6).map(l => ({ text: l.type, sub: `${l.sisa} left` })),
            goto: 'licenseStock'
        });
    }

    // ---- Gudang: barang habis, dan perangkat yang tidak sehat ----
    if (hasAccess('warehouse', 'view')) {
        const low = stockSummary('').filter(s => s.qty <= STOCK_LOW_THRESHOLD);
        add({
            key: 'stock', icon: 'boxes-stacked',
            tone: low.some(s => s.qty <= 0) ? 'danger' : 'warning',
            title: 'Items out of stock or running low',
            total: low.length,
            items: low.slice(0, 6).map(s => ({
                text: s.name,
                sub: s.qty <= 0 ? 'out of stock' : `${s.qty} left`
            })),
            goto: 'warehouseStock'
        });

        const unwell = warehouseDevices.filter(d => d.status === 'damaged' || d.status === 'repair');
        add({
            key: 'devices', icon: 'microchip', tone: 'warning',
            title: 'Devices damaged or in repair',
            total: unwell.length,
            items: unwell.slice(0, 6).map(d => ({
                text: `${d.type || 'Device'} · ${d.sn || ''}`,
                sub: `${DEVICE_STATUS_LABEL[d.status] || d.status}${d.note ? ' · ' + d.note.slice(0, 40) : ''}`
            })),
            goto: 'warehouseDevices'
        });

        // Fuel records whose odometer or consumption looks wrong, last 60 days.
        const since = toISODate(new Date(Date.now() - 60 * 86400000));
        const odd = [];
        vehicles.forEach(v => fuelHistory(v.id).forEach(x => {
            if (x.flags.length && String(x.rec.date || '') >= since) odd.push({ v, x });
        }));
        odd.sort((a, b) => String(b.x.rec.date || '').localeCompare(String(a.x.rec.date || '')));
        add({
            key: 'fuel', icon: 'gas-pump', tone: 'warning',
            title: 'Fuel records to check',
            total: odd.length,
            items: odd.slice(0, 6).map(({ v, x }) => ({
                text: `${v.plate} · ${x.rec.date || ''} · ${fmtKm(x.km)}`,
                sub: x.flags.map(f => FUEL_FLAG_TEXT[f] || f).join(' · ')
            })),
            goto: 'warehouseVehicles'
        });
    }

    // ---- Pendaftar menunggu disetujui ----
    if (isOwner()) {
        const pendingUsers = allUsers.filter(u => u.status !== 'active');
        add({
            key: 'users', icon: 'user-plus', tone: 'info',
            title: 'Registrations pending approval',
            total: pendingUsers.length,
            items: pendingUsers.slice(0, 6).map(u => ({
                text: u.displayName || u.email || '(no name)',
                sub: u.email || ''
            })),
            goto: 'users'
        });

        // An approved account with no area granted cannot do anything; that is
        // a half-finished action, so it belongs here too.
        const noAccess = allUsers.filter(u =>
            u.status === 'active' && u.role !== 'owner' &&
            ACCESS_AREAS.every(a => effectiveAccess(a.key, u) === 'none'));
        add({
            key: 'noaccess', icon: 'user-lock', tone: 'warning',
            title: 'Active accounts without access',
            total: noAccess.length,
            items: noAccess.slice(0, 6).map(u => ({
                text: u.displayName || u.email || '(no name)',
                sub: `${roleLabel(u.role)} — cannot open anything yet`
            })),
            goto: 'users'
        });
    }

    return groups;
}

function decisionTotal() {
    return decisionGroups().reduce((n, g) => n + g.total, 0);
}

// Each group knows where its work actually lives; landing on the right tab with
// the right filter already applied is the difference between a list and a tool.
function goDecision(target) {
    // Group-aware links. They switch the group for this session only — a link
    // must not change the device's saved default — and do nothing when
    // navigateTo refused the view for lack of access.
    if (typeof target === 'string' && target.startsWith('editUnits:')) {
        navigateTo('editUnits');
        if (currentView === 'editUnits') switchEditUnitsGroup(target.slice(10), { persist: false });
        return;
    }
    if (typeof target === 'string' && target.startsWith('missing:')) {
        const [, g, f] = target.split(':');
        navigateTo('editUnits');
        if (currentView !== 'editUnits') return;
        switchEditUnitsGroup(g, { persist: false });
        setEditMissingFilter(f, true);
        return;
    }
    if (typeof target === 'string' && target.startsWith('inspection:')) {
        navigateTo('inspection');
        if (currentView !== 'inspection') return;
        const what = target.slice(11);
        if (what === 'overdue' || what === 'soon') {
            inspectionTab = 'status';
            const f = document.getElementById('insStatusFilter');
            if (f) f.value = what;
        } else {
            inspectionTab = 'reports';
            const f = document.getElementById('insApprovalFilter');
            if (f) f.value = what;
        }
        renderInspectionView();
        return;
    }
    if (typeof target === 'string' && target.startsWith('damage:')) {
        const [, g, ...q] = target.split(':');
        navigateTo('damage');
        if (currentView !== 'damage') return;
        const byUnit = q[0] === 'unit';
        damageUnitFilter = byUnit ? q.slice(1).join(':') : '';
        const search = document.getElementById('damageSearch');
        if (search) search.value = byUnit ? '' : q.join(':');
        const type = document.getElementById('damageTypeFilter');
        if (type) type.value = '';
        setDamageGroup(g);
        renderDamageTable();
        return;
    }
    if (typeof target === 'string' && target.startsWith('dashboard:')) {
        navigateTo('dashboard');
        if (currentView === 'dashboard') setDashGroup(target.slice(10), { persist: false });
        return;
    }
    switch (target) {
        case 'leave': {
            navigateTo('team');
            switchTeamTab('leave');
            const f = document.getElementById('lvApprovalFilter');
            if (f) { f.value = 'pending'; renderLeaveTable(); }
            break;
        }
        case 'approval':
        case 'revision': {
            navigateTo('team');
            switchTeamTab('worklog');
            const f = document.getElementById('wlApprovalFilter');
            if (f) { f.value = target === 'approval' ? 'pending' : 'revision'; renderWorkLogTable(); }
            break;
        }
        case 'teamLog':
            navigateTo('team');
            switchTeamTab('worklog');
            break;
        case 'warehouseStock':
            navigateTo('warehouse');
            switchWarehouseTab('stock');
            break;
        case 'warehouseDevices':
            navigateTo('warehouse');
            switchWarehouseTab('devices');
            break;
        case 'warehouseVehicles':
            // A filter left from earlier could hide the record to check.
            ['fuelVehicleFilter', 'fuelMonthFilter'].forEach(id => { const el = document.getElementById(id); if (el) el.value = ''; });
            navigateTo('warehouse');
            switchWarehouseTab('vehicles');
            break;
        default:
            navigateTo(target);
    }
}

function renderDecisionInbox() {
    const wrap = document.getElementById('decisionGroups');
    if (!wrap) return;
    const groups = decisionGroups();
    const total = groups.reduce((n, g) => n + g.total, 0);
    // Handling something here changes the count, so the badge has to follow —
    // otherwise it keeps advertising work that is already done.
    updateDecisionBadge();

    const stamp = document.getElementById('printStamp');
    if (stamp) stamp.textContent = `Printed ${formatUserTime(Date.now())}`;

    const countEl = document.getElementById('decisionTotal');
    if (countEl) countEl.textContent = total;
    const subEl = document.getElementById('decisionTotalSub');
    if (subEl) {
        subEl.textContent = total === 0
            ? 'Nothing awaiting your decision'
            : `Across ${groups.length} sections`;
    }

    if (groups.length === 0) {
        wrap.innerHTML = `<div class="decision-clear">
            <i class="fas fa-circle-check"></i>
            <div>
                <strong>Nothing pending.</strong>
                <p>All reports have been reviewed, no license or stock needs action,
                and no unit has been down too long.</p>
            </div>
        </div>`;
        return;
    }

    wrap.innerHTML = groups.map(g => `
        <div class="decision-card decision-card--${g.tone}">
            <div class="decision-card__head">
                <span class="decision-card__title">
                    <i class="fas fa-${g.icon}"></i> ${escapeHtml(g.title)}
                </span>
                <span class="decision-card__count">${g.total}</span>
            </div>
            <ul class="decision-list">
                ${g.items.map(it => `
                    <li>
                        <span class="decision-list__text">${escapeHtml(it.text)}</span>
                        ${it.sub ? `<span class="decision-list__sub">${escapeHtml(it.sub)}</span>` : ''}
                    </li>`).join('')}
                ${g.total > g.items.length
                    ? `<li class="decision-list__more">…and ${g.total - g.items.length} more</li>`
                    : ''}
            </ul>
            <button class="btn btn-secondary btn-sm" onclick="goDecision(${jsArg(g.goto)})">
                Handle <i class="fas fa-arrow-right"></i>
            </button>
        </div>`).join('');
}

// Snapshots arrive in bursts at sign-in, and the inbox reads every collection,
// so recomputing per snapshot would be wasteful. One pass once the dust
// settles is enough.
let _decisionTimer = null;
function scheduleDecisionRefresh() {
    if (_decisionTimer) return;
    _decisionTimer = setTimeout(() => {
        _decisionTimer = null;
        updateDecisionBadge();
        // Every leader tab, not only the inbox: Rekap Perusahaan and
        // Ringkasan Mingguan used to stay at "Belum ada laporan" after the
        // reports arrived — on the page people print for invoicing.
        if (currentView === 'leader') renderLeaderView();
    }, 250);
}

// The sidebar badge is what makes this page get opened at all.
function updateDecisionBadge() {
    updateMyTeamNotices();
    updateInspectionBadge();
    const el = document.getElementById('decisionBadge');
    if (!el) return;
    if (!canViewView('leader')) { el.style.display = 'none'; return; }
    const n = decisionTotal();
    el.textContent = n > 99 ? '99+' : String(n);
    el.style.display = n > 0 ? '' : 'none';
    updateMenuButtonLabel();
}

// On a phone the counts live in the closed menu; the menu button carries a
// dot (style.css) and says what is waiting. The bell in the top bar and Inbox
// in the phone's bottom bar carry the decisions; More carries the counts that
// sit inside the menu.
function updateMenuButtonLabel() {
    const shown = id => { const b = document.getElementById(id); return b && b.style.display !== 'none' && b.textContent.trim() ? b.textContent.trim() : ''; };
    const dec = shown('decisionBadge'), ins = shown('inspectionBadge'), team = shown('teamBadge');
    const inMenu = [ins && `${ins} check reports`, team && `${team} reports to revise`].filter(Boolean);
    const parts = (dec ? [`${dec} decisions waiting`] : []).concat(inMenu);
    const btn = document.querySelector('.topbar__burger');
    if (btn) {
        btn.setAttribute('aria-label', parts.length ? `Menu — ${parts.join(', ')}` : 'Menu');
        btn.classList.toggle('has-pending', parts.length > 0);
    }
    const bell = document.getElementById('topbarBell');
    if (bell) {
        bell.hidden = !canViewView('leader');
        bell.classList.toggle('has-pending', !!dec);
        bell.setAttribute('aria-label', dec ? `Decision inbox, ${dec} waiting` : 'Decision inbox');
    }
    const count = document.getElementById('bottomNavInboxCount');
    if (count) { count.textContent = dec; count.hidden = !dec; }
    const inbox = document.getElementById('bottomNavInbox');
    if (inbox) inbox.setAttribute('aria-label', dec ? `Inbox, ${dec} waiting` : 'Inbox');
    const more = document.querySelector('.bottom-nav__more');
    if (more) {
        more.classList.toggle('has-pending', inMenu.length > 0);
        more.setAttribute('aria-label', inMenu.length ? `More pages — ${inMenu.join(', ')}` : 'More pages');
    }
}

// ============================================================
// THE SENDER'S SIDE OF APPROVAL
// ------------------------------------------------------------
// Kotak Keputusan tells the checker what is waiting. This tells the person
// who sent it what came back: a badge on Tim and on the tab, a "Perlu
// direvisi" box above the table with the checker's note and a fix button,
// and a toast when something is sent back or approved — once when the app
// opens, then as it happens.
// ============================================================
const _myNotice = { uid: '', primed: new Set(), revision: new Set() };
const TEAM_NOTICE_KINDS = {
    worklog: { part: 'workLogs',      noun: 'report',   list: () => workLogs,      edit: 'editWorkLog',
               box: 'wlMyNotice', tab: 'wlTabBadge', label: r => `${r.date || '-'} · ${memberNameOf(r)}` },
    leave:   { part: 'leaveRequests', noun: 'request', list: () => leaveRequests, edit: 'editLeave',
               box: 'lvMyNotice', tab: 'lvTabBadge', label: r => `${leaveTypeLabel(r)} ${leaveRangeLabel(r)} · ${memberNameOf(r)}` },
    // Its own menu, so its revisions count on its own badge, not on Tim's.
    inspection: { part: 'inspections', noun: 'inspection report', list: () => inspections, edit: 'editInspection',
               box: 'insMyNotice', tab: 'insTabBadge', area: 'inspection', ownNav: true,
               label: r => `${r.date || '-'} · ${inspectionUnitLabel(r)}` }
};

function approvalSeenKey() { return 'teamApprovalSeen:' + myUid(); }

function updateMyTeamNotices() {
    const uid = myUid();
    if (_myNotice.uid !== uid) {
        _myNotice.uid = uid;
        _myNotice.primed.clear();
        _myNotice.revision.clear();
    }
    let totalRevision = 0;
    Object.entries(TEAM_NOTICE_KINDS).forEach(([kind, k]) => {
        const mine = uid ? k.list().filter(isMyRecord) : [];
        const rev = mine.filter(r => workLogApproval(r) === 'revision');
        if (!k.ownNav) totalRevision += rev.length;
        const tab = document.getElementById(k.tab);
        if (tab) { tab.textContent = String(rev.length); tab.style.display = rev.length ? '' : 'none'; }
        renderMyNoticeBox(kind, mine);
        announceMyChanges(kind, mine, rev);
    });
    const nav = document.getElementById('teamBadge');
    if (nav) {
        nav.textContent = totalRevision > 99 ? '99+' : String(totalRevision);
        nav.style.display = totalRevision ? '' : 'none';
        nav.title = totalRevision ? `${totalRevision} need your revision` : '';
    }
    updateMenuButtonLabel();
}

function renderMyNoticeBox(kind, mine) {
    const k = TEAM_NOTICE_KINDS[kind];
    const box = document.getElementById(k.box);
    if (!box) return;
    const rev = mine.filter(r => workLogApproval(r) === 'revision');
    const pending = mine.filter(r => workLogApproval(r) === 'pending').length;
    const drafts = mine.filter(r => workLogApproval(r) === 'draft').length;
    if (!rev.length && !pending && !drafts) { box.style.display = 'none'; box.innerHTML = ''; return; }
    const canFix = hasAccess(k.area || 'teamLog', 'edit');
    const facts = [
        drafts ? `${drafts} draft(s) not yet submitted` : '',
        pending ? `${pending} ${k.noun}(s) pending approval` : ''
    ].filter(Boolean).join(' · ');
    box.innerHTML = `
        ${rev.length ? `<div class="my-notice__head"><i class="fas fa-rotate-left"></i>
            Needs revision (${rev.length}) — your ${escapeHtml(k.noun)}(s) sent back by your supervisor</div>
        <ul class="my-notice__list">${rev.slice(0, 8).map(r => `
            <li><div><strong>${escapeHtml(k.label(r))}</strong>
                <span class="my-notice__note">${escapeHtml(r.revisionNote || 'No notes')}${r.reviewedBy ? ' — ' + escapeHtml(r.reviewedBy) : ''}</span></div>
                ${canFix ? `<button class="btn btn-primary btn-sm" onclick="${k.edit}(${jsArg(r.id)})"><i class="fas fa-pen"></i> Fix</button>` : ''}
            </li>`).join('')}</ul>` : ''}
        ${facts ? `<div class="my-notice__facts"><i class="fas fa-circle-info"></i> ${escapeHtml(facts)}
            <button type="button" class="btn btn-secondary btn-sm" onclick="showMineOnly(${jsArg(kind)})">Show mine</button></div>` : ''}`;
    box.classList.toggle('my-notice--alert', rev.length > 0);
    box.style.display = '';
}

function showMineOnly(kind) {
    const id = { leave: 'lvMineFilter', inspection: 'insMineFilter' }[kind] || 'wlMineFilter';
    const cb = document.getElementById(id);
    if (cb) cb.checked = true;
    if (kind === 'leave') renderLeaveTable();
    else if (kind === 'inspection') { inspectionTab = 'reports'; renderInspectionView(); }
    else renderWorkLogTable();
}

// Waits for the collection to arrive from the server: on the cached copy
// alone, everything would be announced again on every open.
function announceMyChanges(kind, mine, rev) {
    const k = TEAM_NOTICE_KINDS[kind];
    if (!_myNotice.uid || !_loadedParts.has(k.part)) return;
    const first = !_myNotice.primed.has(kind);
    _myNotice.primed.add(kind);

    const fresh = rev.filter(r => !_myNotice.revision.has(kind + ':' + r.id));
    _myNotice.revision.forEach(key => {
        if (key.startsWith(kind + ':') && !rev.some(r => key === kind + ':' + r.id)) _myNotice.revision.delete(key);
    });
    rev.forEach(r => _myNotice.revision.add(kind + ':' + r.id));
    if (fresh.length) {
        showToast(first
            ? `${rev.length} of your ${k.noun}(s) need revision — open Team to fix them`
            : fresh.length === 1
                ? `${k.noun[0].toUpperCase() + k.noun.slice(1)} ${k.label(fresh[0])} needs revision: ${fresh[0].revisionNote || ''}`
                : `${fresh.length} of your ${k.noun}(s) need revision`, 'warning');
    }

    // Approvals since the last one this account was told about. The first
    // time ever there is no mark, and the whole history is not news.
    let seen = 0;
    try { seen = Number(localStorage.getItem(approvalSeenKey() + ':' + kind)) || 0; } catch (_) {}
    const approved = mine.filter(r => workLogApproval(r) === 'approved');
    const newest = approved.reduce((m, r) => Math.max(m, Number(r.approvedAt) || 0), 0);
    if (seen) {
        const news = approved.filter(r => (Number(r.approvedAt) || 0) > seen);
        if (news.length) {
            showToast(news.length === 1
                ? `${k.noun[0].toUpperCase() + k.noun.slice(1)} ${k.label(news[0])} approved${news[0].approvedBy ? ' by ' + news[0].approvedBy : ''}`
                : `${news.length} of your ${k.noun}(s) have been approved`, 'success');
        }
    }
    const mark = Math.max(seen, newest) || Date.now();
    if (mark !== seen) {
        try { localStorage.setItem(approvalSeenKey() + ':' + kind, String(mark)); } catch (_) {}
    }
}


// ============================================================
// REKAP PER PERUSAHAAN + RINGKASAN MINGGUAN
// ------------------------------------------------------------
// Both read only what the daily reports already carry. The company recap
// exists because the hours are billable between two PTs and nothing was ever
// adding them up; the weekly summary exists because "how did this week go"
// should not require opening five pages.
// ============================================================

let leaderTab = 'inbox';        // 'inbox' | 'company' | 'week'
let recapMonth = '';            // 'YYYY-MM'
let weekAnchor = '';            // ISO date inside the week being shown

function currentMonthISO() {
    return toISODate().slice(0, 7);
}

function monthLabel(iso) {
    const m = /^(\d{4})-(\d{2})$/.exec(iso || '');
    if (!m) return iso || '';
    return `${MONTH_NAMES[+m[2] - 1]} ${m[1]}`;
}

// ---- B2: per-company recap ----
// One row per company for the chosen month. Reports whose member has no
// company yet are grouped rather than dropped, so the totals always add up to
// the month's real figures.
function companyRecap(monthISO) {
    const rows = new Map();
    workLogs.forEach(w => {
        const d = String(w.date || '');
        if (monthISO && d.slice(0, 7) !== monthISO) return;
        if (!isSubmitted(w)) return;
        const key = companyOfRecord(w) || NO_COMPANY;
        const cur = rows.get(key) || {
            company: key, minutes: 0, reports: 0,
            approved: 0, pending: 0, revision: 0,
            units: new Set(), members: new Set()
        };
        cur.minutes += workLogMinutes(w);
        cur.reports += 1;
        cur[workLogApproval(w)] += 1;
        workLogUnits(w).forEach(u => cur.units.add(u.id || u.sn || ''));
        if (w.memberId) cur.members.add(w.memberId);
        rows.set(key, cur);
    });
    return [...rows.values()]
        .map(r => ({ ...r, units: r.units.size, members: r.members.size }))
        .sort((a, b) => b.minutes - a.minutes);
}

function renderCompanyRecap() {
    if (!recapMonth) recapMonth = currentMonthISO();
    const picker = document.getElementById('recapMonth');
    if (picker && picker.value !== recapMonth) picker.value = recapMonth;
    const label = document.getElementById('recapMonthLabel');
    if (label) label.textContent = monthLabel(recapMonth);

    const rows = companyRecap(recapMonth);
    const tbody = document.getElementById('recapBody');
    if (!tbody) return;

    if (rows.length === 0) {
        tbody.innerHTML = `<tr><td colspan="8" style="text-align:center;padding:24px;color:var(--text-secondary)">
            No daily reports in ${escapeHtml(monthLabel(recapMonth))}.
        </td></tr>`;
        const f = document.getElementById('recapFoot');
        if (f) f.innerHTML = '';
        return;
    }

    tbody.innerHTML = rows.map((r, i) => `
        <tr>
            <td>${i + 1}</td>
            <td data-label="Company"><strong>${escapeHtml(r.company)}</strong></td>
            <td data-label="Member">${r.members}</td>
            <td data-label="Reports">${r.reports}</td>
            <td data-label="Total Hours" style="white-space:nowrap"><strong>${escapeHtml(formatMinutes(r.minutes))}</strong></td>
            <td data-label="Units Handled">${r.units}</td>
            <td data-label="Approved"><span class="appr appr--approved">${r.approved}</span></td>
            <td data-label="Outstanding">
                ${r.pending ? `<span class="appr appr--pending">${r.pending} pending</span> ` : ''}
                ${r.revision ? `<span class="appr appr--revision">${r.revision} revision</span>` : ''}
                ${(!r.pending && !r.revision) ? '<span style="color:var(--text-light)">—</span>' : ''}
            </td>
        </tr>`).join('');

    // A totals row is what makes this usable for invoicing: the figure at the
    // bottom is the one that goes on the sheet.
    const tot = rows.reduce((a, r) => ({
        members: a.members + r.members, reports: a.reports + r.reports,
        minutes: a.minutes + r.minutes, units: a.units + r.units,
        approved: a.approved + r.approved
    }), { members: 0, reports: 0, minutes: 0, units: 0, approved: 0 });
    const foot = document.getElementById('recapFoot');
    if (foot) {
        foot.innerHTML = `<tr>
            <th scope="row" colspan="2">Total</th>
            <td>${tot.members}</td>
            <td>${tot.reports}</td>
            <td style="white-space:nowrap"><strong>${escapeHtml(formatMinutes(tot.minutes))}</strong></td>
            <td>${tot.units}</td>
            <td>${tot.approved}</td>
            <td></td>
        </tr>`;
    }
}

function shiftRecapMonth(delta) {
    if (!recapMonth) recapMonth = currentMonthISO();
    const [y, m] = recapMonth.split('-').map(Number);
    const d = new Date(y, m - 1 + delta, 1);
    recapMonth = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;
    renderCompanyRecap();
}

function onRecapMonthChange() {
    const el = document.getElementById('recapMonth');
    if (el && el.value) recapMonth = el.value;
    renderCompanyRecap();
}

function exportRecapCSV() {
    if (!canCsv('export')) return;
    const rows = companyRecap(recapMonth);
    if (rows.length === 0) { showToast('No data to export', 'warning'); return; }
    const headers = ['Company', 'Month', 'Members', 'Reports', 'Total Hours',
                     'Total Hours (decimal)', 'Units Handled', 'Approved', 'Pending', 'Needs Revision'];
    const dataRows = rows.map(r => [
        r.company, monthLabel(recapMonth), r.members, r.reports,
        formatMinutes(r.minutes), (r.minutes / 60).toFixed(2),
        r.units, r.approved, r.pending, r.revision
    ]);
    const csv = toCSV(headers, dataRows);
    const blob = new Blob(['﻿' + csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `rekap_perusahaan_${recapMonth}.csv`;
    a.click();
    URL.revokeObjectURL(url);
    showToast(`Exported recap for ${monthLabel(recapMonth)}`, 'success');
}

// ---- B3: this week against last week ----
function weekStats(weekStartISO) {
    const days = weekDates(weekStartISO);
    const inWeek = v => days.includes(String(v || '').slice(0, 10));
    const logs = workLogs.filter(w => inWeek(w.date) && isSubmitted(w));
    return {
        reports: logs.length,
        minutes: logs.reduce((n, w) => n + workLogMinutes(w), 0),
        people: new Set(logs.map(w => w.memberId).filter(Boolean)).size,
        damages: globalDamages.filter(d => inWeek(d.date)).length,
        resolved: globalDamages.filter(d => d.resolved && inWeek(d.resolvedAt)).length,
        // Seseorang yang shiftnya terisi tetapi izin/sakitnya sudah disetujui
        // TIDAK bertugas. Tanpa pengurangan ini, orang yang sakit tetap
        // terhitung masuk — jadwalnya memang tidak dihapus, dan memang tidak
        // boleh dihapus.
        onDuty: teamShifts.filter(s =>
            inWeek(s.date) && s.shift && s.shift !== 'libur' &&
            !leaveOn(s.memberId, s.date)).length,
        onLeave: teamShifts.filter(s => inWeek(s.date) && leaveOn(s.memberId, s.date)).length,
        stockOut: stockLedger
            .filter(r => r.txnType === 'OUT' && inWeek(r.date))
            .reduce((n, r) => n + (Number(r.qty) || 0), 0)
    };
}

function renderWeekSummary() {
    if (!weekAnchor) weekAnchor = startOfWeekISO(toISODate());
    const thisStart = startOfWeekISO(weekAnchor);
    const lastStart = addDaysISO(thisStart, -7);
    const now = weekStats(thisStart);
    const prev = weekStats(lastStart);

    const label = document.getElementById('weekSummaryLabel');
    if (label) label.textContent = weekRangeLabel(thisStart);
    const prevLabel = document.getElementById('weekSummaryPrev');
    if (prevLabel) prevLabel.textContent = `vs ${weekRangeLabel(lastStart)}`;

    // Fewer breakdowns is good, more hours is good — direction is not the same
    // for every row, so each one says which way is better.
    const metrics = [
        { key: 'reports',  label: 'Daily reports',     fmt: v => String(v),        better: 'up' },
        { key: 'minutes',  label: 'Work hours logged', fmt: v => formatMinutes(v), better: 'up' },
        { key: 'people',   label: 'Members reporting',  fmt: v => String(v),        better: 'up' },
        { key: 'onDuty',   label: 'Person-days on duty', fmt: v => String(v),       better: 'up' },
        { key: 'damages',  label: 'New damage',         fmt: v => String(v),        better: 'down' },
        { key: 'resolved', label: 'Damage resolved',    fmt: v => String(v),        better: 'up' },
        { key: 'stockOut', label: 'Items out of warehouse', fmt: v => String(v),      better: 'flat' }
    ];

    const wrap = document.getElementById('weekSummaryGrid');
    if (!wrap) return;
    wrap.innerHTML = metrics.map(m => {
        const a = now[m.key], b = prev[m.key];
        const diff = a - b;
        let tone = 'flat', arrow = '→';
        if (diff !== 0 && m.better !== 'flat') {
            const good = m.better === 'up' ? diff > 0 : diff < 0;
            tone = good ? 'good' : 'bad';
            arrow = diff > 0 ? '▲' : '▼';
        } else if (diff !== 0) {
            arrow = diff > 0 ? '▲' : '▼';
        }
        const deltaText = diff === 0
            ? 'same'
            : `${arrow} ${m.key === 'minutes' ? formatMinutes(Math.abs(diff)) : Math.abs(diff)}`;
        return `
        <div class="week-metric">
            <div class="week-metric__label">${escapeHtml(m.label)}</div>
            <div class="week-metric__value">${escapeHtml(m.fmt(a))}</div>
            <div class="week-metric__delta week-metric__delta--${tone}">
                ${escapeHtml(deltaText)}
                <span class="week-metric__prev">last week ${escapeHtml(m.fmt(b))}</span>
            </div>
        </div>`;
    }).join('');

    // Fleet health has no weekly history to compare against — the app stores
    // current status, not snapshots — so it is shown as a plain "right now"
    // figure rather than a fake trend.
    const good = globalData.filter(u => isGood(u.status)).length;
    const health = document.getElementById('weekHealth');
    if (health) {
        health.innerHTML = globalData.length
            ? `<strong>${pct(good, globalData.length)}%</strong> of units healthy right now
               (${good} of ${globalData.length}) — a current figure, not a weekly comparison`
            : 'No unit data yet.';
    }
}

function shiftSummaryWeek(delta) {
    if (!weekAnchor) weekAnchor = startOfWeekISO(toISODate());
    weekAnchor = addDaysISO(startOfWeekISO(weekAnchor), delta * 7);
    // The summary compares against the week BEFORE the one shown, so the
    // listener has to reach a week further back than the label says.
    ensureShiftWindowCovers(addDaysISO(startOfWeekISO(weekAnchor), -7));
    renderWeekSummary();
}

// ---- tabs ----
// ============================================================
// PERIKSA DATA — finds records that are already wrong
// ------------------------------------------------------------
// Validation stops new mistakes; this finds the ones already stored. Each
// check is a small pure function returning findings, so each can be tested on
// its own and a wrong one can be removed without touching the others.
//
// Nothing here writes except the whitespace tidy-up, which is the only fix
// that cannot change what a value means. Everything else points at the record
// and leaves the judgement to a person.
// ============================================================

// Characters that survive .trim() and make two identical-looking strings
// different to a computer. This is not hypothetical: a unit name carrying one
// of these is what made a migration rewrite a record that already matched.
const INVISIBLE_RE = /[ ​-‍﻿]/;

function dc(kind, label, detail, goTo, extra) {
    return { kind, label, detail, goTo, ...(extra || {}) };
}

// Two records claiming the same serial number. Worse than untidy: SN is the
// key a CSV import matches on, so a duplicate makes every later import
// ambiguous about which record it is updating.
function dcDuplicateSerials() {
    const out = [];
    const scan = (list, what, goTo) => {
        const seen = new Map();
        (list || []).forEach(r => {
            const sn = (r.sn || '').trim().toLowerCase();
            if (!sn) return;
            if (seen.has(sn)) {
                out.push(dc('sn-ganda', `${what}: ${r.sn}`,
                    `Used by "${seen.get(sn)}" and "${r.name || r.type || '-'}"`,
                    goTo === 'editUnits' ? unitEditTarget(r) : goTo));
            } else {
                seen.set(sn, r.name || r.type || '-');
            }
        });
    };
    scan(globalData, 'Unit', 'editUnits');
    scan(warehouseDevices, 'Device', 'warehouseDevices');
    return out;
}

function dcInvisibleCharacters() {
    const out = [];
    globalData.forEach(u => {
        ['name', 'sn', 'site'].forEach(f => {
            const v = u[f];
            if (typeof v !== 'string' || !v) return;
            if (INVISIBLE_RE.test(v) || v !== v.trim()) {
                out.push(dc('spasi', `Unit ${u.name || u.sn || u.id}`,
                    `Field "${f}" has extra spaces or invisible characters`, unitEditTarget(u),
                    { unitId: u.id, field: f, fixable: true }));
            }
        });
    });
    return out;
}

// "PT. GPA" and "PT GPA" split one company into two rows in the recap, and
// nothing on screen shows why the totals look wrong. Grouped by a key that
// ignores case, punctuation and spacing.
function dcSiteVariants() {
    const groups = new Map();
    globalData.forEach(u => {
        const raw = (u.site || '').trim();
        if (!raw) return;
        const key = raw.toLowerCase().replace(/[^a-z0-9]/g, '');
        if (!key) return;
        const g = groups.get(key) || new Map();
        g.set(raw, (g.get(raw) || 0) + 1);
        groups.set(key, g);
    });
    const out = [];
    groups.forEach(variants => {
        if (variants.size < 2) return;
        const parts = [...variants.entries()]
            .sort((a, b) => b[1] - a[1])
            .map(([v, n]) => `"${v}" (${n})`);
        out.push(dc('site-beda-tipis', 'Site name spelled several ways',
            parts.join(' · '), 'editUnits', { merge: { field: 'site', values: [...variants.keys()] } }));
    });
    return out;
}

// A member with no company, or a unit with no site, silently drops out of the
// per-company recap — the numbers simply come up short with no row to explain it.
function dcMissingCompany() {
    const out = [];
    (teamMembers || []).forEach(m => {
        if (m.active === false) return;
        if (!(companyOf(m) || '').trim()) {
            out.push(dc('tanpa-perusahaan', `Member: ${m.name}`,
                'No company set — their hours are not in any recap', 'team'));
        }
    });
    globalData.forEach(u => {
        if (!(u.site || '').trim()) {
            out.push(dc('tanpa-site', `Unit: ${u.name || u.sn || u.id}`,
                'No site set — not counted in the per-company split', unitEditTarget(u),
                { unitId: u.id }));
        }
    });
    return out;
}

// Leftovers from before the hours were validated on save.
function dcWorkLogHours() {
    const out = [];
    (workLogs || []).forEach(w => {
        const s = parseHHMM(w.start), e = parseHHMM(w.end);
        const who = `${memberNameOf(w)} · ${w.date}`;
        if ((s == null) !== (e == null)) {
            out.push(dc('jam-sebelah', `Report: ${who}`, 'Only one of the times is filled in', 'teamLog'));
            return;
        }
        if (s == null) return;
        const mins = workLogMinutes(w);
        if (mins === 0) {
            out.push(dc('jam-nol', `Report: ${who}`, 'Counts as 0 hours', 'teamLog'));
        } else if (mins >= WORKLOG_LONG_SHIFT_MIN) {
            out.push(dc('jam-panjang', `Report: ${who}`,
                `Counts as ${formatMinutes(mins)} — the times may be swapped`, 'teamLog'));
        }
    });
    return out;
}

function dcFutureDates() {
    const today = toISODate();
    const out = [];
    const scan = (list, what, goTo) => (list || []).forEach(r => {
        if (r.date && r.date > today) {
            out.push(dc('tanggal-depan', `${what}: ${r.date}`,
                'Date is in the future — the year may be mistyped', goTo));
        }
    });
    scan(workLogs, 'Report', 'teamLog');
    scan(globalDamages, 'Damage', 'damage');
    scan(stockLedger, 'Stock', 'warehouseStock');
    scan(globalLicenseStock, 'License', 'licenseStock');
    return out;
}

// A licence that starts and expires on the same day is not a real record. It
// is the signature of the Excel migrations that were removed in v100 — all 52
// rows of their payload had start == end — so this is how to tell whether they
// ever managed to run somewhere before they were deleted.
function dcLicenceDates() {
    const out = [];
    globalData.forEach(u => {
        const pairs = [
            ['GPS', u.gpsLicenseStartDate, u.gpsLicenseEndDate],
            ['Display', u.displayLicenseStartDate, u.displayLicenseEndDate]
        ];
        pairs.forEach(([label, from, to]) => {
            if (!from || !to) return;
            const name = u.name || u.sn || u.id;
            if (from === to) {
                out.push(dc('lisensi-sehari', `Unit: ${name}`,
                    `${label} license starts and expires on the same day (${from})`, 'editUnits',
                    { unitId: u.id }));
            } else if (to < from) {
                out.push(dc('lisensi-terbalik', `Unit: ${name}`,
                    `${label} license expires (${to}) before it starts (${from})`, 'editUnits',
                    { unitId: u.id }));
            }
        });
    });
    return out;
}

function dcOrphanDamage() {
    const ids = new Set(globalData.map(u => u.id));
    const sns = new Set(globalData.map(u => (u.sn || '').toLowerCase()).filter(Boolean));
    return (globalDamages || []).filter(d => {
        if (d.unitId && ids.has(d.unitId)) return false;
        if (d.sn && sns.has(String(d.sn).toLowerCase())) return false;
        return true;
    }).map(d => dc('kerusakan-yatim', `Damage: ${d.unitName || d.sn || '-'}`,
        'The unit no longer exists — this record cannot be traced', 'damage'));
}

function dcNegativeStock() {
    return stockSummary().filter(s => s.qty < 0).map(s =>
        dc('stok-minus', `Stock: ${s.name}`,
            `Balance ${s.qty} — usually the item name differs slightly from an existing one`,
            'warehouseStock'));
}

// Izin dan sakit yang sudah disetujui tetapi tidak ada suratnya. Alpa
// dikecualikan: alpa memang berarti tanpa keterangan, jadi menandainya akan
// menghasilkan temuan yang tidak pernah bisa diselesaikan.
//
// Ini membaca docCount di record induknya, bukan koleksi suratnya — koleksi itu
// tidak pernah dilanggan, dan semua pemeriksaan di sini membaca larik di memori
// secara sinkron.
function dcLeaveWithoutDoc() {
    return (leaveRequests || [])
        .filter(r => r.type !== 'alpa'
            && workLogApproval(r) === 'approved'
            && leaveDocCount(r) === 0)
        .map(r => dc('izin-tanpa-surat',
            `${leaveTypeLabel(r)}: ${memberNameOf(r)}`,
            `Approved for ${leaveRangeLabel(r)} but no letter is attached.`,
            'leave'));
}

// Sisa dari data sebelum validasi rentang ada. Tanggal selesai lebih awal dari
// tanggal mulai membuat jumlah harinya nol dan penanda di grid shift tidak
// pernah muncul.
function dcLeaveReversed() {
    return (leaveRequests || [])
        .filter(r => r.dateFrom && r.dateTo && r.dateTo < r.dateFrom)
        .map(r => dc('izin-terbalik',
            `${leaveTypeLabel(r)}: ${memberNameOf(r)}`,
            `End date (${r.dateTo}) is earlier than start date (${r.dateFrom}).`,
            'leave'));
}

// A unit carrying the other group's fields — e.g. an excavator saved from a
// v108 tab that still thought it was a tractor, with gps:'Breakdown'. The
// values are never read for the unit's own group, so clearing them cannot
// change what the unit means; that is why this one is fixable in bulk.
function dcUnitGroupFields() {
    const out = [];
    globalData.forEach(u => {
        // Only a value that is set AND unreadable. 'Alat Berat' is not
        // canonical but reads correctly, so it is not flagged. Such a unit
        // gets no "stray fields" finding: which fields are stray depends on
        // the group nobody knows yet, and clearing them would wipe real data.
        if (hasUnreadableGroup(u)) {
            const guess = guessUnitGroup(u);
            out.push(dc('kelompok-tak-dikenal', `Unit: ${u.name || u.sn || u.id}`,
                `Unknown group "${u.unitGroup}" — read as ${UNIT_GROUPS.tractor.label}, and cannot be edited until its group is set`
                + (guess ? `. Its contents match ${UNIT_GROUPS[guess].label}.` : '.'),
                unitEditTarget(u), { unitId: u.id, setGroup: true }));
            return;
        }
        const stray = strayGroupFields(u);
        if (stray.length) {
            const g = groupDef(unitGroupOf(u));
            out.push(dc('kelompok-silang', `${g.shortLabel}: ${u.name || u.sn || u.id}`,
                `${g.shortLabel} carries fields of another group: ${stray.map(x => `${COMPONENT_LABELS[x.field] || UNIT_FIELD_LABELS[x.field] || x.field}=${x.value}`).join(', ')}`,
                unitEditTarget(u), { unitId: u.id, fixable: true, stray: stray.map(x => x.field) }));
        }
    });
    return out;
}

// What a unit of unknown group most likely is, judged by which group's own
// fields carry a value. null when both or neither do — then only a person can
// say, and the prompt offers no default.
function guessUnitGroup(u) {
    const has = f => !sameStoredValue(u[f], '');
    const heavy = HEAVY_ONLY_FIELDS.some(has);
    const tractor = TRACTOR_ONLY_FIELDS.some(has);
    if (heavy && !tractor) return 'heavy';
    if (tractor && !heavy) return 'tractor';
    return null;
}

// Records elsewhere that point across groups: a licence handed to heavy
// equipment, or a damage record naming a component the unit does not have.
function dcGroupReferences() {
    const out = [];
    (globalLicenseStock || []).forEach(r => {
        if (r.txnType !== 'OUT') return;
        const u = liveUnitFor(r);
        if (u && isHeavy(u)) out.push(dc('lisensi-alat-berat', `License: ${u.name || u.sn}`,
            `${r.licenseType || 'License'} distributed to a ${UNIT_GROUPS.heavy.shortLabel} unit — SF/G5 licenses are for ${UNIT_GROUPS.tractor.shortLabel} only`,
            'licenseStock'));
    });
    (globalDamages || []).forEach(r => {
        const u = liveUnitFor(r);
        if (u && r.component && componentGroupConflict(r.component, u)) out.push(dc('kerusakan-komponen-silang',
            `Damage: ${u.name || u.sn}`,
            `Component "${r.component}" does not belong to ${groupDef(unitGroupOf(u)).shortLabel}`, 'damage'));
    });
    return out;
}

// Heavy units whose status (or a component) disagrees with their open damage
// records. Never fixed on its own: a person picks, unit by unit, what is true
// — the unit is broken (set Breakdown and link the records) or the repair is
// done (mark the records done). A unit still in Breakdown because of a damage
// that is done or deleted is offered "Set Good". A record left unticked on
// purpose is not asked about.
function dcDamageStatusSync() {
    const out = [];
    const byUnit = new Map();
    (globalDamages || []).forEach(d => {
        if (d.resolved) return;
        const lu = liveUnitFor(d);
        if (!lu || !isHeavy(lu)) return;
        if (!byUnit.has(lu.id)) byUnit.set(lu.id, []);
        byUnit.get(lu.id).push(d);
    });
    const brief = recs => recs.slice(0, 3).map(d => `${d.damageType}${d.component ? ' / ' + d.component : ''} (${d.date})`).join('; ')
        + (recs.length > 3 ? '; …' : '');
    globalData.filter(isHeavy).forEach(u => {
        const name = u.name || u.sn || u.id;
        const goTo = `damage:heavy:unit:${u.id}`;
        const recs = byUnit.get(u.id) || [];
        ['status', ...HEAVY_COMPONENT_KEYS].forEach(field => {
            if (isBrokenValue(field === 'status' ? u.status : u[field])) return;
            const about = recs.filter(d => {
                if (damageHeldField(d, u) === field) return true;
                // Never linked (refused, or an account without unit rights
                // before v162) — unless left unticked on purpose.
                if (!Object.prototype.hasOwnProperty.call(d, 'drove') || d.drove || d.noHold) return false;
                const t = damageTargetField(d.damageType, d.component, u);
                return t !== DAMAGE_DRIVES_NOTHING && (t || 'status') === field;
            });
            if (!about.length) return;
            out.push(dc('kerusakan-status', `${UNIT_GROUPS.heavy.shortLabel}: ${name}`,
                `${field === 'status' ? 'Status' : damageFieldLabel(field)} is Good, but ${about.length} damage record(s) are still open: ${brief(about)}`,
                goTo, { unitId: u.id, syncFix: 'hold', field, damageIds: about.map(d => d.id) }));
        });
        if (isBrokenValue(u.status) && u.breakdownDamageId && !recs.some(d => damageHeldField(d, u) === 'status')) {
            const src = (globalDamages || []).find(d => d.id === u.breakdownDamageId);
            if (!src || src.resolved) out.push(dc('kerusakan-status', `${UNIT_GROUPS.heavy.shortLabel}: ${name}`,
                `Status is Breakdown, but the damage that set it is ${src ? `marked done (${src.resolvedAt || '-'})` : 'deleted'} and no open damage holds it`,
                goTo, { unitId: u.id, syncFix: 'release', field: 'status' }));
        }
    });
    return out;
}

// Data Check's fix for one finding above, as the person chose it.
function fixDamageSync(unitId, field, action) {
    if (!requireEdit('damage')) return;
    const kind = action === 'release' ? 'release' : 'hold';
    const item = dcDamageStatusSync().find(i => i.unitId === unitId && i.field === field && i.syncFix === kind);
    const unit = globalData.find(u => u.id === unitId);
    if (!item || !unit) { showToast('Already in order', 'info'); renderDataCheck(); return; }
    const name = unit.name || unit.sn || '';
    const what = field === 'status' ? 'status' : damageFieldLabel(field);
    const recs = (item.damageIds || []).map(id => globalDamages.find(d => d.id === id)).filter(Boolean)
        .sort((a, b) => String(a.date || '').localeCompare(String(b.date || '')) || (a.createdAt || 0) - (b.createdAt || 0));
    if (action === 'hold') {
        if (!confirm(`Set the ${what} of "${name}" to Breakdown?\n\n${recs.length} open damage record(s) will hold it there; `
            + 'marking the last of them done sets it Good again.')) return;
        const prev = new Map(recs.map(d => [d.id, { drove: d.drove, noHold: d.noHold }]));
        recs.forEach(d => {
            if (d.drove === field && !d.noHold) return;
            d.drove = field;
            d.noHold = false;
            d.updatedAt = Date.now();
            cloudPushDamage(d);
        });
        saveDamages();
        const fields = field === 'status'
            ? { status: 'Breakdown', breakdownReason: damageBreakdownReason(recs[0]), breakdownDamageId: recs[0].id }
            : { [field]: 'Breakdown' };
        const undo = () => recs.forEach(d => _unlinkOnRefused(d.id, field, name, prev.get(d.id))());
        if (_applyDamageLink(unitId, fields, undo)) showToast(`"${name}" ${what} set to Breakdown`, 'success');
        else { undo(); showToast(`"${name}" was not changed`, 'warning'); }
    } else if (action === 'done') {
        if (!confirm(`Mark ${recs.length} open damage record(s) on "${name}" as done?\n\nThe unit stays Good.`)) return;
        let n = 0;
        recs.forEach(d => { if (resolveDamage(d.id, { confirmed: true, quiet: true })) n++; });
        showToast(`${n} damage record(s) marked as done`, 'success');
    } else {
        if (!confirm(`Set "${name}" back to Good?\n\nThe damage that put it into Breakdown is done, and no open damage holds it.`)) return;
        if (_applyDamageLink(unitId, { status: 'Good' })) showToast(`"${name}" set back to Good`, 'success');
        else showToast(`"${name}" was not changed`, 'warning');
    }
    renderDataCheck();
    scheduleDecisionRefresh();
}

const DATA_CHECKS = [
    { key: 'sn',       label: 'Duplicate serial numbers',   run: dcDuplicateSerials },
    { key: 'spasi',    label: 'Spaces / invisible characters', run: dcInvisibleCharacters },
    { key: 'site',     label: 'Site names spelled differently', run: dcSiteVariants },
    { key: 'kosong',   label: 'Company / site not set', run: dcMissingCompany },
    { key: 'jam',      label: 'Unusual report hours',       run: dcWorkLogHours },
    { key: 'tanggal',  label: 'Dates in the future',        run: dcFutureDates },
    { key: 'lisensi',  label: 'Odd license dates',          run: dcLicenceDates },
    { key: 'yatim',    label: 'Damage without a unit',      run: dcOrphanDamage },
    { key: 'stok',     label: 'Negative stock balance',     run: dcNegativeStock },
    { key: 'surat',    label: 'Leave / sick without letter', run: dcLeaveWithoutDoc },
    { key: 'izin-tgl', label: 'Reversed leave range',        run: dcLeaveReversed },
    { key: 'kelompok', label: 'Unit group fields mismatch', run: dcUnitGroupFields },
    { key: 'kelompok-ref', label: 'License / damage in wrong group', run: dcGroupReferences },
    { key: 'mirip',    label: 'Similar spellings',          run: dcSimilarSpellings },
    { key: 'kurang',   label: 'Key fields not filled',      run: dcMissingKeyFields },
    { key: 'impl-db',  label: 'Implement not in the Implements list', run: dcImplementNotInList },
    { key: 'master',   label: 'Not in a master list',       run: dcNotInMasterLists },
    { key: 'kerusakan-status', label: 'Heavy unit status vs open damage', run: dcDamageStatusSync }
];

function runDataChecks() {
    return DATA_CHECKS.map(c => {
        let items = [];
        // One broken check must not take the whole page down with it.
        try { items = c.run() || []; }
        catch (err) { console.error(`[periksa] ${c.key} gagal:`, err); }
        return { ...c, items };
    });
}

function renderDataCheck() {
    const host = document.getElementById('dataCheckBody');
    if (!host) return;
    const groups = runDataChecks();
    const total = groups.reduce((n, g) => n + g.items.length, 0);
    // Two fixers, each with its own button: invisible characters, and fields
    // that belong to the other unit group.
    const fixable = groups.reduce((n, g) => n + g.items.filter(i => i.fixable && i.kind !== 'kelompok-silang').length, 0);
    const strayFixable = groups.reduce((n, g) => n + g.items.filter(i => i.kind === 'kelompok-silang').length, 0);
    const groupFixBtn = document.getElementById('dataCheckGroupFixBtn');
    if (groupFixBtn) {
        groupFixBtn.style.display = strayFixable ? '' : 'none';
        groupFixBtn.textContent = `Clear other-group fields on ${strayFixable} unit(s)`;
    }
    const groupUnknown = groups.reduce((n, g) => n + g.items.filter(i => i.setGroup).length, 0);
    const groupSetBtn = document.getElementById('dataCheckGroupSetBtn');
    if (groupSetBtn) {
        groupSetBtn.style.display = groupUnknown ? '' : 'none';
        groupSetBtn.textContent = `Set group for ${groupUnknown} unit(s)`;
    }

    const summary = document.getElementById('dataCheckSummary');
    if (summary) {
        summary.textContent = total === 0
            ? 'Nothing suspicious — your data is clean.'
            : `${total} item(s) to look at, in ${groups.filter(g => g.items.length).length} group(s).`;
    }
    const implFix = groups.reduce((n, g) => n + g.items.filter(i => i.implFix).length, 0);
    const implBtn = document.getElementById('dataCheckImplFixBtn');
    if (implBtn) {
        implBtn.style.display = implFix && hasAccess('editUnits', 'edit') ? '' : 'none';
        implBtn.textContent = 'Match implements to the Implements list';
    }
    const fixBtn = document.getElementById('dataCheckFixBtn');
    if (fixBtn) {
        fixBtn.style.display = fixable ? '' : 'none';
        fixBtn.textContent = `Clean up ${fixable} hidden space(s)`;
    }

    if (total === 0) { host.innerHTML = ''; return; }

    host.innerHTML = groups.filter(g => g.items.length).map(g => `
        <div class="datacheck-group">
            <h4>${escapeHtml(g.label)} <span class="datacheck-count">${g.items.length}</span></h4>
            <table class="data-table table--cardable">
                <thead><tr><th>Item</th><th>Details</th><th></th></tr></thead>
                <tbody>${g.items.map(i => `<tr>
                    <td data-label="Item">${escapeHtml(i.label)}</td>
                    <td data-label="Details">${escapeHtml(i.detail)}</td>
                    <td data-label="" style="white-space:nowrap">${damageSyncButtons(i)}${i.merge && canMergeField(i.merge.field)
                        ? `<button type="button" class="btn btn-primary btn-sm" title="Merge these spellings into one"
                            onclick="openValueMerge(${jsArg(i.merge.field)}, ${jsArgList(i.merge.values)})"><i class="fas fa-object-group"></i> Merge…</button> ` : ''}<button type="button" class="btn btn-secondary btn-sm"
                        onclick="goDecision(${jsArg(i.goTo)})">Open</button></td>
                </tr>`).join('')}</tbody>
            </table>
        </div>`).join('');
}

function damageSyncButtons(i) {
    if (!i.syncFix || !hasAccess('damage', 'edit')) return '';
    const a = (action, label, cls) => `<button type="button" class="btn ${cls} btn-sm"
        onclick="fixDamageSync(${jsArg(i.unitId)}, ${jsArg(i.field)}, ${jsArg(action)})">${label}</button> `;
    return i.syncFix === 'release'
        ? a('release', 'Set Good', 'btn-primary')
        : a('hold', 'Set Breakdown', 'btn-primary') + a('done', 'Mark done', 'btn-secondary');
}

// The one automatic fix. Trimming whitespace and stripping zero-width
// characters cannot change what a value means, which is why it is safe to do
// in bulk; every other finding needs a person to decide. Writes go through
// updateUnit, so they are gated by canWriteUnits() and land in the history
// like any other edit.
function fixInvisibleCharacters() {
    if (!requireEdit('editUnits')) return;
    const found = dcInvisibleCharacters().filter(i => i.fixable);
    if (!found.length) { showToast('Nothing to tidy up', 'info'); return; }
    if (!confirm(`Tidy up ${found.length} value(s) with extra spaces or invisible characters?\n\n`
        + 'The text stays the same — only the hidden characters are removed.')) return;

    const byUnit = new Map();
    found.forEach(i => {
        const u = globalData.find(x => x.id === i.unitId);
        if (!u) return;
        const cleaned = String(u[i.field]).replace(new RegExp(INVISIBLE_RE.source, 'g'), '').trim();
        if (cleaned === u[i.field]) return;
        const fields = byUnit.get(i.unitId) || {};
        fields[i.field] = cleaned;
        byUnit.set(i.unitId, fields);
    });

    let n = 0;
    byUnit.forEach((fields, id) => { if (updateUnit(id, fields)) n++; });
    showToast(n ? `${n} unit(s) tidied up` : 'Nothing changed', n ? 'success' : 'info');
    renderDataCheck();
}

// Asks, unit by unit, which group a unit of unknown group belongs to, and
// writes only the answer. Its fields stay as they are: once the group is known,
// any that belong to the other group show up as "field kelompok lain" and are
// cleared by the button next to this one — a second, visible step.
function setUnreadableGroups() {
    if (!requireEdit('editUnits')) return;
    const found = dcUnitGroupFields().filter(i => i.setGroup);
    if (!found.length) { showToast('No groups need to be set', 'info'); return; }
    let n = 0;
    for (const i of found) {
        const u = globalData.find(x => x.id === i.unitId);
        if (!u || !hasUnreadableGroup(u)) continue;
        const guess = guessUnitGroup(u);
        const filled = [...HEAVY_ONLY_FIELDS, ...TRACTOR_ONLY_FIELDS]
            .filter(f => !sameStoredValue(u[f], ''))
            .slice(0, 6)
            .map(f => `${COMPONENT_LABELS[f] || UNIT_FIELD_LABELS[f] || f}=${u[f]}`).join(', ');
        const answer = prompt(`Unit "${u.name || u.sn || u.id}" has group "${u.unitGroup}", which is not recognised.\n`
            + (filled ? `Contents: ${filled}\n` : '')
            + `\nType 1 for ${UNIT_GROUPS.tractor.label}, 2 for ${UNIT_GROUPS.heavy.label}.\n`
            + 'Leave empty or Cancel to skip this unit.',
            guess === 'heavy' ? '2' : guess === 'tractor' ? '1' : '');
        const to = String(answer == null ? '' : answer).trim() === '1' ? 'tractor'
                 : String(answer == null ? '' : answer).trim() === '2' ? 'heavy' : null;
        if (!to) continue;
        if (updateUnit(u.id, { unitGroup: to }, { setGroup: true })) {
            n++;
            // Its damage records were stamped '' (group unknown): they take it now.
            const parts = globalDamages.filter(d => (liveUnitFor(d) || {}).id === u.id && d.unitGroup !== to)
                .map(d => { d.unitGroup = to; return { id: d.id, unitGroup: to }; });
            if (parts.length) {
                saveDamages();
                if (!suppressCloudWrites && window.cloud?.isReady) {
                    const send = typeof window.cloud.updateDamagesFields === 'function' ? window.cloud.updateDamagesFields : window.cloud.saveDamages;
                    Promise.resolve(send.call(window.cloud, parts)).catch(err => cloudWriteFailed(err, { what: 'damage groups', label: '[Master] Unit groups', resync: resyncDamages }));
                }
            }
        }
    }
    showToast(n ? `Group set for ${n} unit(s)` : 'Nothing changed', n ? 'success' : 'info');
    renderEditTable();
    renderDataCheck();
}

// The second safe fix: clearing values a unit's own group never reads. Goes
// through updateUnit with clearStray, the one case the write firewall lets a
// field of the other group through — and only as ''.
function fixStrayGroupFields() {
    if (!requireEdit('editUnits')) return;
    const found = dcUnitGroupFields().filter(i => i.kind === 'kelompok-silang');
    if (!found.length) { showToast('Nothing to clean up', 'info'); return; }
    if (!confirm(`Clear fields belonging to another group on ${found.length} unit(s)?\n\n`
        + 'Those values are never read for the unit\'s own group, so the unit\'s meaning does not change.')) return;
    let n = 0;
    found.forEach(i => {
        const fields = {};
        i.stray.forEach(f => { fields[f] = ''; });
        if (updateUnit(i.unitId, fields, { clearStray: true })) n++;
    });
    showToast(n ? `${n} unit(s) cleaned up` : 'Nothing changed', n ? 'success' : 'info');
    renderDataCheck();
}

function switchLeaderTab(tab) {
    leaderTab = ['company', 'week', 'check'].includes(tab) ? tab : 'inbox';
    renderLeaderView();
}

function renderLeaderView() {
    document.querySelectorAll('.leader-tab').forEach(btn => {
        // Never trust another page to have left these visible.
        btn.style.display = '';
        const on = btn.dataset.tab === leaderTab;
        btn.classList.toggle('active', on);
        btn.setAttribute('aria-selected', on ? 'true' : 'false');
    });
    const panels = { inbox: 'leaderInboxPanel', company: 'leaderCompanyPanel',
                     week: 'leaderWeekPanel', check: 'leaderCheckPanel' };
    Object.entries(panels).forEach(([key, id]) => {
        const el = document.getElementById(id);
        if (el) el.style.display = (key === leaderTab) ? '' : 'none';
    });
    if (leaderTab === 'inbox') renderDecisionInbox();
    else if (leaderTab === 'company') renderCompanyRecap();
    else if (leaderTab === 'check') renderDataCheck();
    else renderWeekSummary();
}

// ============================================================
// PENGECEKAN ALAT BERAT — heavy-equipment checks
// ------------------------------------------------------------
// A technician checks a heavy unit's four components (Camera AI, Telematic
// Box, Switch Limiter, Rotary Lamp), one photo each, and files a report that
// goes through the same Draf → Kirim → Menunggu → Disetujui / Perlu Revisi
// flow as the daily report — on its own two grants (inspection /
// inspectionApprove), enforced in firestore.rules.
//
// The next check is due INSPECTION_INTERVAL_DAYS after the ACTUAL check date
// of the unit's latest sent report — not the scheduled date — so a check
// done three days late moves the next one with it. A schedule (inspectionPlans)
// lists the units to check on a day; a unit can always be checked outside it.
//
// Components found broken reach the damage log only once a report is
// approved, and only through someone allowed to write it (see
// applyInspectionFindings).
// ============================================================
const INS_AREAS = { edit: 'inspection', approve: 'inspectionApprove' };
const INSPECTION_INTERVAL_DAYS = 14;
const INSPECTION_SOON_DAYS = 3;
// Four photos share one document under Firestore's 1 MB cap.
const INS_PHOTO_OPTS = { maxDim: 1024, maxBytes: 200 * 1024, quality: 0.7 };
const INS_RESULT = { good: 'Good', bad: 'Damaged' };
const _insPhotoCache = new Map();   // report id -> { componentKey: dataURL }
let inspectionTab = 'status';

function inspectionComponents() { return UNIT_GROUPS.heavy.components; }

function inspectableUnits() {
    return globalData.filter(u => isHeavy(u))
        .sort((a, b) => String(a.name || '').localeCompare(String(b.name || '')));
}

function generateInspectionId() {
    return 'ins_' + Date.now() + '_' + Math.random().toString(36).substr(2, 5);
}
function generateInspectionPlanId() {
    return 'inp_' + Date.now() + '_' + Math.random().toString(36).substr(2, 5);
}

function addDaysISO(iso, n) {
    const d = parseLocalDate(iso);
    if (!d) return '';
    d.setDate(d.getDate() + n);
    return toISODate(d);
}

function daysFromTo(fromIso, toIso) {
    const a = parseLocalDate(fromIso), b = parseLocalDate(toIso);
    if (!a || !b) return 0;
    return Math.round((b - a) / 86400000);
}

function canPlanInspections() {
    return hasAccess('inspection', 'edit') || hasAccess('inspectionApprove', 'edit');
}

function inspectionUnitLabel(rec) {
    const live = liveUnitFor({ unitId: rec.unitId, sn: rec.sn });
    return (live && live.name) || rec.unitName || rec.sn || '(unit)';
}

// A sent report counts as the unit having been checked — waiting, approved,
// or sent back to have the REPORT fixed (the check itself happened). A draft
// does not: nothing has been handed in.
function lastInspectionFor(unitId) {
    let best = null;
    inspections.forEach(r => {
        if (r.unitId !== unitId || !isSubmitted(r) || !r.date) return;
        if (!best || r.date > best.date || (r.date === best.date && (r.submittedAt || 0) > (best.submittedAt || 0))) best = r;
    });
    return best;
}

function inspectionStatusFor(unit, today) {
    today = today || toISODate();
    const last = lastInspectionFor(unit.id);
    if (!last) return { key: 'never', label: 'Never checked', last: null, next: '', days: null };
    const next = addDaysISO(last.date, INSPECTION_INTERVAL_DAYS);
    const days = daysFromTo(today, next);
    if (days < 0) return { key: 'overdue', label: `${-days} days overdue`, last, next, days };
    if (days <= INSPECTION_SOON_DAYS) return { key: 'soon', label: days === 0 ? 'Today' : `in ${days} days`, last, next, days };
    return { key: 'ok', label: `in ${days} days`, last, next, days };
}

function inspectionBadBits(rec) {
    return inspectionComponents().filter(c => (rec.results || {})[c.key] === 'bad');
}

function inspectionResultSummary(rec) {
    const bad = inspectionBadBits(rec);
    if (!bad.length) return { tone: 'good', text: 'All good' };
    return { tone: 'bad', text: `${bad.length} damaged: ${bad.map(c => c.label).join(', ')}` };
}

// Done for a plan: a sent report linked to it, or any sent report of that
// unit on or after the plan date (checked "outside" the plan still counts).
function planUnitDone(plan, unitId) {
    return inspections.some(r => r.unitId === unitId && isSubmitted(r)
        && (r.planId === plan.id || (r.date && r.date >= plan.date)));
}

function planProgress(plan) {
    // A unit deleted since the schedule was made can no longer be checked;
    // left in, it held the plan at "x/y · overdue" for good. One already
    // checked still counts — its report exists.
    const known = globalData.length ? new Set(globalData.map(u => u.id)) : null;
    const ids = (plan.unitIds || []).filter(id => !known || known.has(id) || planUnitDone(plan, id));
    const done = ids.filter(id => planUnitDone(plan, id)).length;
    return { done, total: ids.length };
}

// The open plan a check of this unit belongs to: the earliest one that lists
// it and is not yet done for it.
function openPlanFor(unitId) {
    return inspectionPlans
        .filter(p => (p.unitIds || []).includes(unitId) && !planUnitDone(p, unitId))
        .sort((a, b) => String(a.date).localeCompare(String(b.date)))[0] || null;
}

// ---- Snapshots ----
// Reports filed on this device that the server has not acknowledged yet —
// a check done where there is no signal. Firestore keeps them in its
// on-device queue (it survives closing the app) and sends them by itself.
let insQueuedIds = new Set();

function applyCloudInspectionsSnapshot(list, queuedIds) {
    _markLoaded('inspections');
    const before = insQueuedIds.size;
    insQueuedIds = new Set(queuedIds || []);
    if (before && !insQueuedIds.size) showToast('All inspection reports have been sent', 'success');
    renderQueuedPill();
    inspections = (list || []).slice().sort((a, b) =>
        String(b.date || '').localeCompare(String(a.date || '')) || ((b.createdAt || 0) - (a.createdAt || 0)));
    if (currentView === 'inspection') renderInspectionView();
    if (currentView === 'editUnits') renderEditTable();
    scheduleDecisionRefresh();
}

function applyCloudInspectionPlansSnapshot(list) {
    _markLoaded('inspectionPlans');
    inspectionPlans = (list || []).slice().sort((a, b) => String(b.date || '').localeCompare(String(a.date || '')));
    if (currentView === 'inspection') renderInspectionView();
    scheduleDecisionRefresh();
}

// ---- View ----
function switchInspectionTab(tab) {
    inspectionTab = ['status', 'plans', 'reports'].includes(tab) ? tab : 'status';
    renderInspectionView();
}

function renderInspectionView() {
    const panels = { status: 'insStatusPanel', plans: 'insPlansPanel', reports: 'insReportsPanel' };
    document.querySelectorAll('#viewInspection .ins-tab').forEach(btn => {
        const on = btn.dataset.tab === inspectionTab;
        btn.classList.toggle('active', on);
        btn.setAttribute('aria-selected', on ? 'true' : 'false');
    });
    Object.entries(panels).forEach(([k, id]) => {
        const el = document.getElementById(id);
        if (el) el.style.display = k === inspectionTab ? '' : 'none';
    });
    document.querySelectorAll('#viewInspection .insplan-edit').forEach(b => { b.style.display = canPlanInspections() ? '' : 'none'; });

    const today = toISODate();
    const st = inspectableUnits().map(u => inspectionStatusFor(u, today));
    const setText = (id, v) => { const el = document.getElementById(id); if (el) el.textContent = v; };
    setText('insKpiOverdue', st.filter(s => s.key === 'overdue').length);
    setText('insKpiSoon', st.filter(s => s.key === 'soon').length);
    setText('insKpiNever', st.filter(s => s.key === 'never').length);
    const pending = inspections.filter(r => workLogApproval(r) === 'pending').length;
    setText('insKpiPending', pending);
    // Tab pills: reports waiting for a decision, schedules with units left.
    const pill = (id, n) => { const el = document.getElementById(id); if (el) { el.textContent = n; el.hidden = !n; } };
    pill('insPendingCount', pending);
    pill('insPlanOpenCount', inspectionPlans.filter(p => { const pr = planProgress(p); return pr.done < pr.total; }).length);

    if (inspectionTab === 'status') renderInspectionStatus();
    else if (inspectionTab === 'plans') renderInspectionPlans();
    else renderInspectionReports();
    renderInspectionSyncNotice();
    updateMyTeamNotices();
}

// A unit snapshot moves units in and out of the list, and an access change
// decides who sees "Log check" and "Review": redraw the open page.
document.addEventListener('ot:data', () => { if (currentView === 'inspection') renderInspectionView(); });
document.addEventListener('ot:gating', () => { if (currentView === 'inspection') renderInspectionView(); });

function renderInspectionSyncNotice() {
    const el = document.getElementById('insSyncNotice');
    if (el) {
        const n = inspections.filter(r => insQueuedIds.has(r.id)).length;
        const offline = !navigator.onLine;
        // Without the persistent cache the queue lives only in this tab.
        const volatile = !!(window.cloud && window.cloud.cacheMode && window.cloud.cacheMode !== 'persistent-multitab');
        let html = '';
        if (n) {
            html = `<i class="fas fa-cloud-arrow-up"></i><strong>${n} ${n === 1 ? 'report is' : 'reports are'} waiting to be sent.</strong> ${
                offline ? 'They are saved on this device and will be sent automatically when the signal returns.'
                        : 'Sending now…'} ${
                volatile ? 'Keep this tab open until they are sent.' : 'You can close the app — they will be sent the next time it is opened with a signal.'}`;
        } else if (offline) {
            html = '<i class="fas fa-wifi"></i>No signal — you can still fill in check reports. They are saved on this device and sent when the signal returns.';
        }
        el.innerHTML = html;
        el.className = 'ins-sync' + (n ? '' : ' ins-sync--offline');
        el.style.display = html ? '' : 'none';
    }
    const m = document.getElementById('insModalOffline');
    if (m) m.style.display = navigator.onLine ? 'none' : '';
}

const INS_STATUS_ORDER = { overdue: 0, soon: 1, never: 2, ok: 3 };

function insStatusBadge(s) {
    return `<span class="ins-st ins-st--${s.key}" title="${escapeHtml(s.next ? 'Next check ' + s.next : 'No check report submitted yet')}">${escapeHtml(s.label)}</span>`;
}

// "5 Oct" — with the year when it is not this year. Tables keep the ISO date
// in the cell's title.
function fpShortDate(iso) {
    const d = parseLocalDate(iso);
    if (!d) return iso || '';
    const opts = { day: 'numeric', month: 'short' };
    if (d.getFullYear() !== new Date().getFullYear()) opts.year = 'numeric';
    return d.toLocaleDateString('en-GB', opts);
}

// Status chips above the table. #insStatusFilter (hidden) keeps the choice.
const INS_STATUS_CHIPS = [['', 'All'], ['overdue', 'Overdue'], ['soon', 'Due soon'], ['never', 'Never checked'], ['ok', 'OK']];

function setInspectionStatusFilter(key) {
    const sel = document.getElementById('insStatusFilter');
    if (sel) sel.value = key || '';
    renderInspectionStatus();
}

function renderInspectionStatusChips(all, filter) {
    const box = document.getElementById('insStatusChips');
    if (!box) return;
    // Redrawn on every click: keep the keyboard on the chip just pressed.
    const hadFocus = box.contains(document.activeElement);
    box.innerHTML = INS_STATUS_CHIPS.map(([k, label]) => {
        const n = k ? all.filter(x => x.s.key === k).length : all.length;
        return `<button type="button" class="fp-chip-btn" aria-pressed="${filter === k}" onclick="setInspectionStatusFilter(${jsArg(k)})">${escapeHtml(label)} · ${n}</button>`;
    }).join('');
    if (hadFocus) box.querySelector('[aria-pressed="true"]')?.focus();
}

const FP_ICON_EXCAVATOR = '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="2" y="16" width="12" height="4.5" rx="2.25"></rect><path d="M3.5 16v-3.5h8.5V16"></path><path d="M5.5 12.5V9h4l1.5 3.5"></path><path d="M12 12.5l4.5-7 3.5 3"></path><path d="M20 8.5l1.5 5.5h-4"></path></svg>';

// Next check: the due date as a chip, and the schedule the unit is on.
function insNextCell(u, s) {
    const plan = openPlanFor(u.id);
    const planned = plan ? `Planned ${fpShortDate(plan.date)}` : '';
    if (s.key === 'never') {
        return plan ? `<span class="ins-st ins-st--planned" title="${escapeHtml('Schedule ' + plan.date)}">${escapeHtml(planned)}</span>`
                    : '<span class="ins-st ins-st--never" title="No check report submitted yet">Not planned</span>';
    }
    const text = s.key === 'overdue' ? s.label : s.key === 'soon' ? `${fpShortDate(s.next)} · ${s.label}` : fpShortDate(s.next);
    const sub = [s.key === 'overdue' ? `Was due ${fpShortDate(s.next)}` : '', planned].filter(Boolean).join(' · ');
    return `<span class="ins-st ins-st--${s.key}" title="${escapeHtml('Next check ' + s.next + (s.key === 'ok' ? ' · ' + s.label : ''))}">${escapeHtml(text)}</span>${
        sub ? `<span class="fp-sub">${escapeHtml(sub)}</span>` : ''}`;
}

function renderInspectionStatus() {
    const tbody = document.getElementById('insStatusBody');
    if (!tbody) return;
    const filter = document.getElementById('insStatusFilter')?.value || '';
    const q = (document.getElementById('insStatusSearch')?.value || '').toLowerCase().trim();
    const today = toISODate();
    const canCheck = hasAccess('inspection', 'edit');
    const canPlan = canPlanInspections();
    const all = inspectableUnits().map(u => ({ u, s: inspectionStatusFor(u, today) }));
    renderInspectionStatusChips(all, filter);
    const rows = all
        .filter(({ u, s }) => (!filter || s.key === filter)
            && (!q || `${u.name} ${u.sn} ${u.assetCode || ''} ${u.machineType || ''} ${u.site || ''}`.toLowerCase().includes(q)))
        .sort((a, b) => (INS_STATUS_ORDER[a.s.key] - INS_STATUS_ORDER[b.s.key])
            || ((a.s.days == null ? 0 : a.s.days) - (b.s.days == null ? 0 : b.s.days))
            || String(a.u.name || '').localeCompare(String(b.u.name || '')));
    const count = document.getElementById('insStatusCount');
    if (count) count.textContent = rows.length === all.length ? '' : `${rows.length} of ${all.length} units`;
    if (!rows.length) {
        tbody.innerHTML = `<tr><td colspan="5" style="text-align:center;padding:24px;color:var(--text-secondary)">${
            all.length ? 'No units match the filter' : 'No Heavy Equipment units in the Unit Database yet.'}</td></tr>`;
        return;
    }
    tbody.innerHTML = rows.map(({ u, s }) => {
        const name = u.name || u.sn || '-';
        const last = s.last;
        const appr = last ? workLogApproval(last) : '';
        const res = last ? inspectionResultSummary(last) : null;
        // A report still waiting is reviewed in Reports, by whoever may approve
        // it; a unit never checked and on no schedule is planned first.
        const review = last && appr === 'pending' && canApproveThisLog(last, INS_AREAS);
        const plan = !last && canPlan && !openPlanFor(u.id);
        const main = review
            ? `<button type="button" class="btn btn-secondary btn-sm" aria-label="Review the check report of ${escapeHtml(name)}" onclick="showInspectionHistory(${jsArg(u.id)})">Review</button>`
            : plan
            ? `<button type="button" class="btn btn-secondary btn-sm" aria-label="Plan a check for ${escapeHtml(name)}" onclick="planInspectionFor(${jsArg(u.id)})">Plan check</button>`
            : canCheck
            ? `<button type="button" class="btn ${s.key === 'overdue' ? 'btn-primary' : 'btn-secondary'} btn-sm" aria-label="Log a check for ${escapeHtml(name)}" onclick="showInspectionForm(${jsArg(u.id)})">Log check</button>`
            : '';
        return `<tr>
            <td data-label="Unit"><div class="fp-unit">
                <span class="fp-unit__icon" aria-hidden="true">${FP_ICON_EXCAVATOR}</span>
                <span class="fp-unit__text"><strong>${escapeHtml(name)}</strong><span class="fp-sub">${escapeHtml([u.machineType, u.assetCode].filter(Boolean).join(' · ') || '—')}</span></span>
            </div></td>
            <td data-label="Site" class="fp-muted">${escapeHtml(u.site || '—')}</td>
            <td data-label="Last check">${last ? `<div class="fp-stack">
                <span title="${escapeHtml(last.date)}">${escapeHtml(fpShortDate(last.date))}</span>
                <span class="fp-sub fp-sub--${res.tone}" title="${escapeHtml(res.text)}">${escapeHtml(res.text)}</span>
                ${appr !== 'approved' ? `<span class="fp-sub fp-sub--${appr}">${escapeHtml(appr === 'pending' ? 'Waiting for approval' : APPROVAL_STATES[appr].label)}</span>` : ''}
            </div>` : '<span class="fp-muted">Never checked</span>'}</td>
            <td data-label="Next check"><div class="fp-stack">${insNextCell(u, s)}</div></td>
            <td class="col-actions"><div class="fp-actions">
                ${main}
                <button type="button" class="btn btn-secondary btn-sm fp-icon-btn" title="Check history" aria-label="Check history for ${escapeHtml(name)}" onclick="showInspectionHistory(${jsArg(u.id)})"><i class="fas fa-clock-rotate-left" aria-hidden="true"></i><span class="fp-btn-label">History</span></button>
            </div></td>
        </tr>`;
    }).join('');
}

function showInspectionHistory(unitId) {
    const u = globalData.find(x => x.id === unitId);
    inspectionTab = 'reports';
    const s = document.getElementById('insReportSearch');
    if (s) s.value = u ? (u.name || u.sn || '') : '';
    renderInspectionView();
}

// ---- Schedule ----
function renderInspectionPlans() {
    const tbody = document.getElementById('insPlanBody');
    if (!tbody) return;
    const today = toISODate();
    const canCheck = hasAccess('inspection', 'edit');
    const canPlan = canPlanInspections();
    if (!inspectionPlans.length) {
        tbody.innerHTML = `<tr><td colspan="6" style="text-align:center;padding:24px;color:var(--text-secondary)">No inspection schedules yet.${
            canPlan ? ' Click <strong>Plan a check</strong> to get started.' : ''}</td></tr>`;
        return;
    }
    tbody.innerHTML = inspectionPlans.map((p, i) => {
        const pr = planProgress(p);
        const late = pr.done < pr.total && p.date < today;
        const chips = (p.unitIds || []).map(id => {
            const u = globalData.find(x => x.id === id);
            const done = planUnitDone(p, id);
            const name = u ? (u.name || u.sn) : '(unit deleted)';
            const btn = !done && u && canCheck
                ? ` <button type="button" class="ins-chip__go" title="Check ${escapeHtml(name)}" aria-label="Check ${escapeHtml(name)}" onclick="showInspectionForm(${jsArg(id)}, ${jsArg(p.id)})"><i class="fas fa-clipboard-check"></i></button>` : '';
            return `<span class="ins-chip ${done ? 'ins-chip--done' : ''}">${done ? '<i class="fas fa-check"></i> ' : ''}${escapeHtml(name)}${btn}</span>`;
        }).join('');
        return `<tr>
            <td>${i + 1}</td>
            <td data-label="Date" style="white-space:nowrap">${escapeHtml(p.date || '')}${p.date === today ? ' <span class="ins-st ins-st--soon">Today</span>' : ''}</td>
            <td data-label="Unit"><div class="ins-chips">${chips}</div></td>
            <td data-label="Progress"><span class="ins-st ins-st--${pr.done === pr.total ? 'ok' : late ? 'overdue' : 'soon'}">${pr.done}/${pr.total}${late ? ' · overdue' : pr.done === pr.total ? ' · done' : ''}</span></td>
            <td data-label="Notes" style="font-size:12px;color:var(--text-secondary)">${escapeHtml(p.note || '') || '—'}</td>
            <td class="col-actions">${canPlan ? `<div class="row-actions">
                <button class="btn btn-secondary" title="Edit schedule" aria-label="Edit schedule" onclick="showInspectionPlanForm(${jsArg(p.id)})"><i class="fas fa-pen"></i></button>
                <button class="btn btn-secondary" title="Delete schedule" aria-label="Delete schedule" onclick="deleteInspectionPlan(${jsArg(p.id)})"><i class="fas fa-trash" style="color:var(--danger)"></i></button>
            </div>` : ''}</td>
        </tr>`;
    }).join('');
}

let _insPlanPick = new Set();

function showInspectionPlanForm(id) {
    if (!canPlanInspections()) { showToast('You do not have access to create inspection schedules', 'warning'); return; }
    const p = id ? inspectionPlans.find(x => x.id === id) : null;
    document.getElementById('editInspectionPlanId').value = p ? p.id : '';
    document.getElementById('inspectionPlanTitle').innerHTML = p
        ? '<i class="fas fa-calendar-check"></i> Edit Inspection Schedule'
        : '<i class="fas fa-calendar-plus"></i> Create Inspection Schedule';
    document.getElementById('insPlanDate').value = p ? (p.date || '') : toISODate();
    document.getElementById('insPlanNote').value = p ? (p.note || '') : '';
    document.getElementById('insPlanSearch').value = '';
    _insPlanPick = new Set(p ? (p.unitIds || []) : []);
    renderInspectionPlanPicker();
    document.getElementById('inspectionPlanModal').classList.add('open');
}

// "Plan check" on a unit's row: a new schedule with that unit ticked.
function planInspectionFor(unitId) {
    showInspectionPlanForm();
    if (!document.getElementById('inspectionPlanModal').classList.contains('open')) return;
    _insPlanPick.add(unitId);
    renderInspectionPlanPicker();
}

function closeInspectionPlanModal() {
    document.getElementById('inspectionPlanModal').classList.remove('open');
}

function renderInspectionPlanPicker() {
    const wrap = document.getElementById('insPlanPick');
    if (!wrap) return;
    const q = (document.getElementById('insPlanSearch')?.value || '').toLowerCase().trim();
    const today = toISODate();
    const units = inspectableUnits()
        .map(u => ({ u, s: inspectionStatusFor(u, today) }))
        .filter(({ u }) => !q || `${u.name} ${u.sn} ${u.assetCode || ''} ${u.site || ''}`.toLowerCase().includes(q))
        .sort((a, b) => INS_STATUS_ORDER[a.s.key] - INS_STATUS_ORDER[b.s.key] || String(a.u.name || '').localeCompare(String(b.u.name || '')));
    wrap.innerHTML = units.length ? units.map(({ u, s }) => `
        <label class="ins-pick">
            <input type="checkbox" data-id="${escapeHtml(u.id)}" ${_insPlanPick.has(u.id) ? 'checked' : ''}
                   onchange="toggleInspectionPlanUnit(this.dataset.id, this.checked)">
            <span class="ins-pick__name">${escapeHtml(u.name || u.sn || '-')}<span class="ins-sub">${escapeHtml([u.machineType, u.site].filter(Boolean).join(' · '))}</span></span>
            ${insStatusBadge(s)}
        </label>`).join('')
        : '<p class="ins-sub" style="padding:8px 0">No matching Heavy Equipment units.</p>';
    const c = document.getElementById('insPlanPickCount');
    if (c) c.textContent = `(${_insPlanPick.size} selected)`;
}

function toggleInspectionPlanUnit(id, on) {
    if (on) _insPlanPick.add(id); else _insPlanPick.delete(id);
    const c = document.getElementById('insPlanPickCount');
    if (c) c.textContent = `(${_insPlanPick.size} selected)`;
}

function selectDueInspectionUnits() {
    const today = toISODate();
    let n = 0;
    inspectableUnits().forEach(u => {
        const k = inspectionStatusFor(u, today).key;
        if ((k === 'overdue' || k === 'soon' || k === 'never') && !_insPlanPick.has(u.id)) { _insPlanPick.add(u.id); n++; }
    });
    renderInspectionPlanPicker();
    showToast(n ? `${n} due unit(s) added` : 'No unselected units are due', 'info');
}

function saveInspectionPlan(event) {
    if (event) event.preventDefault();
    if (!canPlanInspections()) return;
    const id = document.getElementById('editInspectionPlanId').value;
    const date = document.getElementById('insPlanDate').value;
    if (!isoDistributionDate(date)) { showToast('Schedule date is required', 'warning'); return; }
    const unitIds = [..._insPlanPick].filter(uid => globalData.some(u => u.id === uid && isHeavy(u)));
    if (!unitIds.length) { showToast('Select at least one unit', 'warning'); return; }
    const existing = id ? inspectionPlans.find(p => p.id === id) : null;
    const rec = {
        id: id || generateInspectionPlanId(),
        date, unitIds,
        note: (document.getElementById('insPlanNote').value || '').trim().slice(0, 120),
        createdBy: existing ? (existing.createdBy || '') : ((currentUserDoc && currentUserDoc.displayName) || (currentUser && currentUser.email) || ''),
        createdByUid: existing ? (existing.createdByUid || '') : myUid(),
        createdAt: existing ? (existing.createdAt || Date.now()) : Date.now(),
        updatedAt: Date.now()
    };
    cloudWrite(
        { action: existing ? 'update' : 'create', unitName: '[Inspection] Schedule', field: `Schedule ${date}`,
          before: existing ? `${(existing.unitIds || []).length} unit` : '', after: `${unitIds.length} unit` },
        cloudCall('saveInspectionPlan', rec),
        existing ? 'Schedule updated' : `Schedule ${date} created — ${unitIds.length} unit(s)`,
        err => {
            console.error('[ins] plan save failed:', err);
            showToast('Failed to save schedule' + (err && err.code === 'permission-denied' ? ' — republish firestore.rules' : ''), 'error');
        }
    );
    closeInspectionPlanModal();
}

function deleteInspectionPlan(id) {
    if (!canPlanInspections()) return;
    const p = inspectionPlans.find(x => x.id === id);
    if (!p) return;
    if (!confirm(`Delete schedule ${p.date} (${(p.unitIds || []).length} unit(s))?\n\nInspection reports already filed are kept.`)) return;
    cloudWrite(
        { action: 'delete', unitName: '[Inspection] Schedule', field: `Schedule ${p.date}`, before: `${(p.unitIds || []).length} unit`, after: '' },
        cloudCall('deleteInspectionPlan', id),
        'Schedule deleted',
        err => { console.error('[ins] plan delete failed:', err); showToast('Failed to delete schedule', 'error'); }
    );
}

// ---- Reports table ----
function getFilteredInspections() {
    const approval = document.getElementById('insApprovalFilter')?.value || '';
    const mine = !!document.getElementById('insMineFilter')?.checked;
    const q = (document.getElementById('insReportSearch')?.value || '').toLowerCase().trim();
    return inspections.filter(r => {
        if (!visibleToMe(r)) return false;
        if (mine && !isMyRecord(r)) return false;
        if (approval && workLogApproval(r) !== approval) return false;
        if (q) {
            const u = liveUnitFor({ unitId: r.unitId, sn: r.sn }) || {};
            const hay = [inspectionUnitLabel(r), r.sn, u.assetCode, r.createdBy, r.note,
                         ...Object.values(r.notes || {})].join(' ').toLowerCase();
            if (!hay.includes(q)) return false;
        }
        return true;
    });
}

function inspectionNeedsApply(r) {
    return workLogApproval(r) === 'approved' && inspectionBadBits(r).length > 0 && !r.appliedAt;
}

function renderInspectionReports() {
    const tbody = document.getElementById('insReportBody');
    if (!tbody) return;
    const rows = getFilteredInspections();
    const count = document.getElementById('insReportCount');
    if (count) count.textContent = `${rows.length} ${rows.length === 1 ? 'report' : 'reports'}`;
    const canEdit = hasAccess('inspection', 'edit');
    if (!rows.length) {
        tbody.innerHTML = `<tr><td colspan="9" style="text-align:center;padding:24px;color:var(--text-secondary)">${
            inspections.length ? 'No reports match the filter' : 'No inspection reports yet.'}</td></tr>`;
        return;
    }
    tbody.innerHTML = rows.map((r, i) => {
        const plan = r.planId ? inspectionPlans.find(p => p.id === r.planId) : null;
        const res = inspectionComponents().map(c => {
            const v = (r.results || {})[c.key];
            return `<span class="ins-res ins-res--${v === 'bad' ? 'bad' : v === 'good' ? 'good' : 'none'}" title="${escapeHtml(((r.notes || {})[c.key]) || '')}">${escapeHtml(c.label)}: ${escapeHtml(INS_RESULT[v] || '—')}</span>`;
        }).join('');
        const photos = Number(r.photoCount) || 0;
        const apply = inspectionNeedsApply(r) && hasAccess('damage', 'edit')
            ? `<button class="btn btn-secondary btn-sm ins-apply" title="Log damaged components in the Damage menu" onclick="applyInspectionFindings(${jsArg(r.id)})"><i class="fas fa-screwdriver-wrench"></i> To Damage</button>` : '';
        return `<tr>
            <td>${i + 1}</td>
            <td data-label="Check Date" style="white-space:nowrap">${escapeHtml(r.date || '')}</td>
            <td data-label="Unit"><strong>${escapeHtml(inspectionUnitLabel(r))}</strong></td>
            <td data-label="Component Results"><div class="ins-res-list">${res}</div>${r.note ? `<div class="ins-sub" title="${escapeHtml(r.note)}">${escapeHtml(r.note.slice(0, 60))}</div>` : ''}</td>
            <td data-label="Schedule">${plan ? `<span class="ins-tag">Schedule ${escapeHtml(plan.date)}</span>` : r.planId ? '<span class="ins-tag">Schedule deleted</span>' : '<span class="ins-tag ins-tag--adhoc">Unscheduled</span>'}</td>
            <td data-label="Inspector" style="font-size:12px">${escapeHtml(r.createdBy || '—')}</td>
            <td data-label="Approval">${insQueuedIds.has(r.id) ? '<span class="ins-tag ins-tag--queued" title="Saved on this device, not yet on the server"><i class="fas fa-cloud-arrow-up"></i> Waiting to send</span> ' : ''}${approvalCell(r, 'check report', 'approveInspection', 'reviseInspection', INS_AREAS)}${
                r.appliedAt ? '<div class="ins-sub"><i class="fas fa-check"></i> Logged in Damage</div>' : ''}</td>
            <td data-label="Photo">${photos
                ? `<button type="button" class="wl-photo-btn" title="View ${photos} photo(s)" aria-label="View ${photos} photo(s)" onclick="openInspectionPhotos(${jsArg(r.id)}, this)"><i class="fas fa-image"></i> ${photos}</button>`
                : '<span style="color:var(--text-light)">—</span>'}</td>
            <td class="col-actions">${apply}${canEdit ? rowActionsFor(r, 'Inspection report', 'editInspection', 'deleteInspection', 'withdrawInspection', INS_AREAS) : ''}</td>
        </tr>`;
    }).join('');
}

async function loadInspectionPhotos(id) {
    if (_insPhotoCache.has(id)) return _insPhotoCache.get(id);
    const fn = window.cloud && window.cloud.getInspectionPhotos;
    if (!fn) return {};
    const photos = await window.cloud.getInspectionPhotos(id);
    _insPhotoCache.set(id, photos || {});
    return photos || {};
}

async function openInspectionPhotos(id, btn) {
    const old = btn ? btn.innerHTML : '';
    if (btn) { btn.disabled = true; btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i>'; }
    try {
        const photos = await loadInspectionPhotos(id);
        const list = inspectionComponents().map(c => safeImageSrc(photos[c.key])).filter(Boolean);
        if (!list.length) { showToast('Photo not found', 'warning'); return; }
        openPhotoLightbox(list, 0);
    } catch (err) {
        console.error('[ins] photos load failed:', err);
        showToast(navigator.onLine ? 'Failed to load photo' : 'Photos need a signal to load', 'warning');
    } finally {
        if (btn) { btn.disabled = false; btn.innerHTML = old; }
    }
}

// ---- Form ----
let _insPhotos = {};          // componentKey -> dataURL
let _insPhotosDirty = false;
let _insPhotosLoading = false;
let _insPhotosFailed = false;
let _insGen = 0;
let _insResults = {};         // componentKey -> 'good' | 'bad'

function populateInspectionUnitSelect(selectedId) {
    const sel = document.getElementById('insUnit');
    if (!sel) return;
    const units = inspectableUnits();
    sel.innerHTML = '<option value="">— Select heavy equipment unit —</option>' + units.map(u =>
        `<option value="${escapeHtml(u.id)}">${escapeHtml(u.name || u.sn)}${u.assetCode ? ' · ' + escapeHtml(u.assetCode) : ''}</option>`).join('');
    if (selectedId) {
        if (![...sel.options].some(o => o.value === selectedId)) {
            const u = globalData.find(x => x.id === selectedId);
            const opt = document.createElement('option');
            opt.value = selectedId;
            opt.textContent = u ? (u.name || u.sn) : '(unit deleted)';
            sel.appendChild(opt);
        }
        sel.value = selectedId;
    }
    sel.onchange = () => updateInspectionPlanTag();
}

// Which schedule this check belongs to — shown, and recalculated when the unit
// changes on a new report. An edited report keeps the plan it was filed under.
function updateInspectionPlanTag() {
    const tag = document.getElementById('insPlanTag');
    const planInput = document.getElementById('insPlanId');
    if (!tag || !planInput) return;
    if (!document.getElementById('editInspectionId').value) {
        const unitId = document.getElementById('insUnit').value;
        const forced = planInput.dataset.forced || '';
        const plan = forced && inspectionPlans.find(p => p.id === forced && (p.unitIds || []).includes(unitId))
            || (unitId ? openPlanFor(unitId) : null);
        planInput.value = plan ? plan.id : '';
    }
    const plan = planInput.value ? inspectionPlans.find(p => p.id === planInput.value) : null;
    tag.style.display = document.getElementById('insUnit').value ? '' : 'none';
    tag.className = 'ins-plan-tag' + (plan ? '' : ' ins-plan-tag--adhoc');
    tag.textContent = plan ? `Part of schedule ${plan.date}` : 'Unscheduled — still resets the next check date';
}

function renderInspectionComponents(rec) {
    const wrap = document.getElementById('insComponents');
    if (!wrap) return;
    wrap.innerHTML = inspectionComponents().map(c => {
        const v = _insResults[c.key] || '';
        const note = rec && rec.notes ? (rec.notes[c.key] || '') : '';
        return `<div class="ins-comp" data-key="${escapeHtml(c.key)}">
            <div class="ins-comp__head">
                <strong>${escapeHtml(c.label)}</strong>
                <div class="ins-seg" role="radiogroup" aria-label="Condition of ${escapeHtml(c.label)}">
                    <label class="ins-seg__opt ins-seg__opt--good"><input type="radio" name="insRes_${escapeHtml(c.key)}" value="good" ${v === 'good' ? 'checked' : ''}
                        onchange="setInspectionResult(${jsArg(c.key)}, 'good')"> Good</label>
                    <label class="ins-seg__opt ins-seg__opt--bad"><input type="radio" name="insRes_${escapeHtml(c.key)}" value="bad" ${v === 'bad' ? 'checked' : ''}
                        onchange="setInspectionResult(${jsArg(c.key)}, 'bad')"> Damaged</label>
                </div>
            </div>
            <div class="ins-comp__body">
                <div class="ins-photo" id="insPhoto_${escapeHtml(c.key)}"></div>
                <input type="text" class="form-input ins-comp__note" id="insNote_${escapeHtml(c.key)}" maxlength="200"
                       placeholder="${v === 'bad' ? 'Required: describe the damage' : 'Notes (optional)'}" value="${escapeHtml(note)}">
            </div>
        </div>`;
    }).join('');
    inspectionComponents().forEach(c => renderInspectionPhoto(c.key));
}

function setInspectionResult(key, v) {
    _insResults[key] = v;
    const note = document.getElementById('insNote_' + key);
    if (note) note.placeholder = v === 'bad' ? 'Required: describe the damage' : 'Notes (optional)';
}

function renderInspectionPhoto(key) {
    const box = document.getElementById('insPhoto_' + key);
    if (!box) return;
    const src = safeImageSrc(_insPhotos[key]);
    const off = _insPhotosLoading || _insPhotosFailed;
    if (_insPhotosLoading && !src) {
        box.innerHTML = '<span class="ins-photo__empty"><i class="fas fa-spinner fa-spin"></i></span>';
        return;
    }
    box.innerHTML = src
        ? `<img src="${src}" alt="Photo ${escapeHtml(key)}" onclick="openPhotoLightbox(safeImageSrc(_insPhotos[${jsArg(key)}]))">
           ${off ? '' : `<button type="button" class="ins-photo__x" aria-label="Delete photo" title="Delete photo" onclick="removeInspectionPhoto(${jsArg(key)})">&times;</button>`}`
        : `<label class="ins-photo__add ${off ? 'is-off' : ''}" title="${_insPhotosFailed ? 'Old photo failed to load' : 'Take / choose photo'}">
               <i class="fas fa-camera"></i><span>Photo</span>
               <input type="file" accept="image/*" capture="environment" ${off ? 'disabled' : ''} style="display:none"
                      onchange="handleInspectionPhoto(${jsArg(key)}, event)">
           </label>`;
}

async function handleInspectionPhoto(key, event) {
    const file = event.target.files && event.target.files[0];
    event.target.value = '';
    if (!file || _insPhotosLoading || _insPhotosFailed) return;
    if (!file.type.startsWith('image/')) { showToast('File must be an image (photo)', 'warning'); return; }
    const gen = _insGen;
    try {
        const data = await compressImageToDataURL(file, INS_PHOTO_OPTS);
        if (gen !== _insGen) return;
        _insPhotos[key] = data;
        _insPhotosDirty = true;
        renderInspectionPhoto(key);
    } catch (err) {
        showToast(err.message || 'Failed to process photo', 'error');
    }
}

function removeInspectionPhoto(key) {
    delete _insPhotos[key];
    _insPhotosDirty = true;
    renderInspectionPhoto(key);
}

function _openInspectionModal(rec, unitId, planId) {
    _insGen++;
    _insPhotos = {}; _insPhotosDirty = false; _insPhotosFailed = false;
    _insPhotosLoading = !!(rec && Number(rec.photoCount) > 0);
    _insResults = rec ? { ...(rec.results || {}) } : {};
    document.getElementById('inspectionForm').reset();
    document.getElementById('editInspectionId').value = rec ? rec.id : '';
    const planInput = document.getElementById('insPlanId');
    planInput.value = rec ? (rec.planId || '') : '';
    planInput.dataset.forced = rec ? '' : (planId || '');
    document.getElementById('inspectionModalTitle').innerHTML = !rec
        ? '<i class="fas fa-clipboard-check"></i> Inspection Report'
        : workLogApproval(rec) === 'revision'
            ? '<i class="fas fa-clipboard-check"></i> Revise Inspection Report'
            : '<i class="fas fa-clipboard-check"></i> Edit Inspection Report';
    populateInspectionUnitSelect(rec ? rec.unitId : (unitId || ''));
    // A report's unit is what its photos and its 14-day clock are about.
    document.getElementById('insUnit').disabled = !!rec;
    const plan = planId ? inspectionPlans.find(p => p.id === planId) : null;
    const today = toISODate();
    document.getElementById('insDate').value = rec ? (rec.date || '') : (plan && plan.date < today ? plan.date : today);
    document.getElementById('insDate').max = today;
    document.getElementById('insNote').value = rec ? (rec.note || '') : '';
    showRevisionNote('insRevisionNote', rec);
    renderInspectionComponents(rec);
    updateInspectionPlanTag();
    renderInspectionSyncNotice();
    document.getElementById('inspectionModal').classList.add('open');

    if (_insPhotosLoading) {
        const gen = _insGen;
        _insPhotoCache.delete(rec.id);   // the server's copy for an edit — see editWorkLog
        loadInspectionPhotos(rec.id).then(photos => {
            if (gen !== _insGen) return;
            _insPhotos = { ...(photos || {}) };
            _insPhotosLoading = false;
            inspectionComponents().forEach(c => renderInspectionPhoto(c.key));
        }).catch(err => {
            console.error('[ins] photos load failed:', err);
            if (gen !== _insGen) return;
            _insPhotosLoading = false;
            _insPhotosFailed = true;
            inspectionComponents().forEach(c => renderInspectionPhoto(c.key));
            showToast('Existing photos failed to load — they are still saved. Close and reopen to change them.', 'warning');
        });
    }
}

function showInspectionForm(unitId, planId) {
    if (!requireEdit('inspection')) return;
    if (!inspectableUnits().length) { showToast('No Heavy Equipment units in the Unit Database yet', 'warning'); return; }
    if (currentView !== 'inspection' && canViewView('inspection')) navigateTo('inspection');
    _openInspectionModal(null, unitId, planId);
}

function editInspection(id) {
    if (!requireEdit('inspection')) return;
    const r = inspections.find(x => x.id === id);
    if (!r) return;
    if (!canEditTeamRecord(r, INS_AREAS)) { showToast(lockedReason(r, 'Inspection report', INS_AREAS), 'warning'); return; }
    _openInspectionModal(r);
}

function closeInspectionModal(force) {
    if (!force && _insPhotosDirty && Object.keys(_insPhotos).length) {
        if (!confirm(`${Object.keys(_insPhotos).length} photo(s) not saved yet and will be lost. Close anyway?`)) return;
    } else if (!force && !okToDiscardTyping('inspectionForm')) {
        return;
    }
    _insGen++;
    _insPhotosDirty = false;
    document.getElementById('inspectionModal').classList.remove('open');
}

function saveInspection(event, mode) {
    if (event) event.preventDefault();
    if (!requireEdit('inspection')) return;
    const asDraft = mode === 'draft';
    const id = document.getElementById('editInspectionId').value;
    const existing = id ? inspections.find(x => x.id === id) : null;
    if (existing && !canEditTeamRecord(existing, INS_AREAS)) {
        showToast(lockedReason(existing, 'Inspection report', INS_AREAS), 'warning');
        return;
    }
    const unitId = existing ? existing.unitId : document.getElementById('insUnit').value;
    const unit = globalData.find(u => u.id === unitId);
    if (!unit && !existing) { showToast('Select a heavy equipment unit first', 'warning'); return; }
    if (unit && !isHeavy(unit)) { showToast('This inspection is for Heavy Equipment units only', 'warning'); return; }
    const date = document.getElementById('insDate').value;
    if (!isoDistributionDate(date)) { showToast('Check date is required', 'warning'); return; }
    if (date > toISODate()) { showToast('Check date cannot be in the future', 'warning'); return; }
    if (_insPhotosLoading) { showToast('Wait for the existing photos to finish loading', 'warning'); return; }

    const notes = {};
    inspectionComponents().forEach(c => {
        notes[c.key] = (document.getElementById('insNote_' + c.key)?.value || '').trim().slice(0, 200);
    });
    const results = {};
    inspectionComponents().forEach(c => { if (_insResults[c.key]) results[c.key] = _insResults[c.key]; });

    // Sent for checking: every component has a verdict and a photo, and a
    // broken one says what is wrong. A draft may be half-done.
    if (!asDraft) {
        const missing = inspectionComponents().filter(c => !results[c.key]).map(c => c.label);
        if (missing.length) { showToast(`Choose Good/Damaged for: ${missing.join(', ')}`, 'warning'); return; }
        const noPhoto = _insPhotosFailed ? [] : inspectionComponents().filter(c => !_insPhotos[c.key]).map(c => c.label);
        if (noPhoto.length) { showToast(`Photo required for: ${noPhoto.join(', ')}`, 'warning'); return; }
        const noNote = inspectionComponents().filter(c => results[c.key] === 'bad' && !notes[c.key]).map(c => c.label);
        if (noNote.length) { showToast(`Describe the damage: ${noNote.join(', ')}`, 'warning'); return; }
    }

    const photoKeys = _insPhotosDirty
        ? inspectionComponents().map(c => c.key).filter(k => _insPhotos[k])
        : (existing ? (existing.photoKeys || []) : []);
    const rec = {
        id: id || generateInspectionId(),
        unitId,
        unitName: unit ? (unit.name || '') : (existing.unitName || ''),
        sn: unit ? (unit.sn || '') : (existing.sn || ''),
        date,
        planId: document.getElementById('insPlanId').value || '',
        results, notes,
        note: (document.getElementById('insNote').value || '').trim().slice(0, 500),
        photoKeys,
        photoCount: photoKeys.length,
        approval: asDraft ? 'draft' : 'pending',
        approvedBy: '', approvedByEmail: '', approvedAt: 0,
        revisionNote: asDraft && existing ? (existing.revisionNote || '') : '',
        submittedAt: asDraft ? (existing ? (existing.submittedAt || 0) : 0) : Date.now(),
        submittedByUid: submittedByFor(existing, asDraft),
        createdBy: existing ? (existing.createdBy || '') : ((currentUserDoc && currentUserDoc.displayName) || (currentUser && currentUser.email) || ''),
        createdByUid: existing ? (existing.createdByUid || '') : myUid(),
        createdByEmail: existing ? (existing.createdByEmail || '') : ((currentUser && currentUser.email) || ''),
        createdAt: existing ? (existing.createdAt || Date.now()) : Date.now(),
        updatedAt: Date.now()
    };

    // Photos FIRST, while the report is still open — firestore.rules locks the
    // photo document once its report is sent. See saveWorkLog.
    if (_insPhotosDirty) {
        const photos = {};
        photoKeys.forEach(k => { photos[k] = _insPhotos[k]; });
        _insPhotoCache.set(rec.id, photos);
        const fn = photoKeys.length ? cloudFn('saveInspectionPhotos') : cloudFn('deleteInspectionPhotos');
        if (fn) {
            (photoKeys.length ? fn(rec.id, photos) : fn(rec.id)).catch(err => {
                console.error('[ins] photos save failed:', err);
                showToast('Report saved, but the photos failed to upload', 'error');
            });
        }
    }

    const bad = inspectionBadBits(rec);
    const snap = _snapInspection(rec);
    cloudWrite(
        { action: existing ? 'update' : 'create', unitId,
          unitName: `[Inspection] ${rec.unitName}`,
          field: `Check ${date}${asDraft ? ' (draft)' : ''}`,
          before: existing ? inspectionResultSummary(existing).text : '',
          after: bad.length ? `${bad.length} damaged: ${bad.map(c => c.label).join(', ')}` : (Object.keys(results).length === inspectionComponents().length ? 'All good' : 'Incomplete') },
        cloudCall('saveInspection', rec),
        asDraft ? 'Inspection report draft saved — not submitted yet'
            : `Inspection report submitted — next check ${addDaysISO(date, INSPECTION_INTERVAL_DAYS)}`,
        err => {
            console.error('[ins] save failed:', err);
            rememberUnsent(`inspection report — ${rec.unitName || rec.unitId}, ${date}`, err, () => _reopenInspection(snap));
        }
    );
    closeInspectionModal(true);
}

function withdrawInspection(id) {
    const r = inspections.find(x => x.id === id);
    if (!r) return;
    if (!canWithdrawTeamRecord(r, INS_AREAS)) { showToast('This inspection report cannot be withdrawn', 'warning'); return; }
    if (!confirm(`Withdraw the inspection report for ${inspectionUnitLabel(r)} (${r.date}) back to draft?`)) return;
    cloudWrite(
        { action: 'update', unitId: r.unitId, unitName: `[Inspection] ${inspectionUnitLabel(r)}`,
          field: `Approval ${r.date}`, before: 'Pending', after: 'Draft (withdrawn)' },
        cloudCall('saveInspection', { ...r, approval: 'draft', updatedAt: Date.now() }),
        'Inspection report withdrawn to draft',
        err => { console.error('[ins] withdraw failed:', err); showToast('Failed to withdraw — it may already have been reviewed', 'error'); }
    );
}

function deleteInspection(id) {
    if (!requireEdit('inspection')) return;
    const r = inspections.find(x => x.id === id);
    if (!r) return;
    if (!canEditTeamRecord(r, INS_AREAS)) { showToast(lockedReason(r, 'Inspection report', INS_AREAS), 'warning'); return; }
    if (!confirm(`Delete the inspection report for ${inspectionUnitLabel(r)} dated ${r.date}?`)) return;
    if (Number(r.photoCount) > 0 && window.cloud && window.cloud.deleteInspectionPhotos) {
        _insPhotoCache.delete(id);
        window.cloud.deleteInspectionPhotos(id).catch(err => console.error('[ins] photos delete failed:', err));
    }
    cloudWrite(
        { action: 'delete', unitId: r.unitId, unitName: `[Inspection] ${inspectionUnitLabel(r)}`,
          field: `Check ${r.date}`, before: inspectionResultSummary(r).text, after: '' },
        cloudCall('deleteInspection', id),
        'Inspection report deleted',
        err => { console.error('[ins] delete failed:', err); showToast('Failed to delete inspection report', 'error'); }
    );
}

function approveInspection(id) {
    const r = inspections.find(x => x.id === id);
    if (!r) return;
    if (!canApproveWorkLogs(INS_AREAS)) { showToast('You do not have the right to approve inspection reports', 'warning'); return; }
    if (!canApproveThisLog(r, INS_AREAS)) { showToast(selfCheckMessage(r, 'inspection report', 'approve'), 'warning'); return; }
    if (workLogApproval(r) !== 'pending') { showToast('Only submitted reports can be approved', 'warning'); return; }
    const rec = {
        ...r,
        approval: 'approved',
        approvedBy: (currentUserDoc && currentUserDoc.displayName) || (currentUser && currentUser.email) || '',
        approvedByEmail: (currentUser && currentUser.email) || '',
        approvedAt: Date.now(),
        revisionNote: '',
        updatedAt: Date.now()
    };
    const bad = inspectionBadBits(rec);
    cloudWrite(
        { action: 'approve', unitId: r.unitId, unitName: `[Inspection] ${inspectionUnitLabel(r)}`,
          field: `Approval ${r.date}`, before: APPROVAL_STATES[workLogApproval(r)].label, after: APPROVAL_STATES.approved.label },
        cloudCall('saveInspection', rec),
        'Inspection report approved',
        err => { console.error('[ins] approve failed:', err); showToast('Failed to approve inspection report', 'error'); return false; }
    ).then(ok => {
        // Broken components go to the damage log once approved — by whoever
        // is allowed to write it. Anyone else leaves it to the inbox.
        if (ok === false || !bad.length) return;
        const idx = inspections.findIndex(x => x.id === id);
        if (idx !== -1) inspections[idx] = { ...inspections[idx], ...rec };
        if (hasAccess('damage', 'edit')) applyInspectionFindings(id);
        else showToast(`${bad.length} damaged component(s) not yet logged in Damage — needs an account with Damage access`, 'info');
    });
}

function reviseInspection(id) {
    const r = inspections.find(x => x.id === id);
    if (!r) return;
    if (!canApproveWorkLogs(INS_AREAS)) { showToast('You do not have the right to review this inspection report', 'warning'); return; }
    if (!canApproveThisLog(r, INS_AREAS)) { showToast(selfCheckMessage(r, 'inspection report', 'review'), 'warning'); return; }
    const st = workLogApproval(r);
    if (st !== 'pending' && st !== 'approved') { showToast('This inspection report has not been submitted or was already sent back', 'warning'); return; }
    const note = prompt(`What needs fixing in the inspection report for ${inspectionUnitLabel(r)} (${r.date})?`, r.revisionNote || '');
    if (note === null) return;
    if (!note.trim()) { showToast('Write the reason so it can be fixed', 'warning'); return; }
    const rec = {
        ...r,
        approval: 'revision',
        revisionNote: note.trim(),
        approvedBy: '', approvedByEmail: '', approvedAt: 0,
        reviewedBy: (currentUserDoc && currentUserDoc.displayName) || (currentUser && currentUser.email) || '',
        reviewedAt: Date.now(),
        updatedAt: Date.now()
    };
    cloudWrite(
        { action: 'reject', unitId: r.unitId, unitName: `[Inspection] ${inspectionUnitLabel(r)}`,
          field: `Approval ${r.date}`, before: APPROVAL_STATES[st].label, after: `${APPROVAL_STATES.revision.label} — ${rec.revisionNote}` },
        cloudCall('saveInspection', rec),
        'Inspection report sent back for revision',
        err => { console.error('[ins] revise failed:', err); showToast('Failed to send revision request', 'error'); }
    );
}

// Approved findings → the damage log: one record per broken component, with
// that component's photo, and — for whoever may edit units — the component
// put into Breakdown so the dashboard shows it. Stamped on the report so it
// happens once.
const _insApplying = new Set();
async function applyInspectionFindings(id) {
    const r = inspections.find(x => x.id === id);
    if (!r || !inspectionNeedsApply(r) || _insApplying.has(id)) return;
    if (!hasAccess('damage', 'edit')) { showToast('Damage edit access required', 'warning'); return; }
    const unit = liveUnitFor({ unitId: r.unitId, sn: r.sn });
    if (!unit) { showToast('The unit is no longer in the Unit Database', 'warning'); return; }
    _insApplying.add(id);
    try {
        let photos = {};
        try { photos = await loadInspectionPhotos(id); } catch (_) { photos = {}; }
        const ids = [];
        for (const c of inspectionBadBits(r)) {
            const photo = safeImageSrc(photos[c.key]);
            const note = (r.notes || {})[c.key] || '';
            const rec = {
                id: generateDamageId(),
                date: r.date, unitId: unit.id, unitName: unit.name || '', sn: unit.sn || '', site: unit.site || '',
                damageType: 'Device Precision', component: c.label,
                description: `Inspection finding ${r.date}: ${note}`.slice(0, 500),
                hasPhoto: !!photo, unitGroup: 'heavy', fromInspection: r.id,
                resolved: false, resolvedAt: '', createdAt: Date.now(), updatedAt: Date.now(), drove: ''
            };
            // Device Precision on a heavy component: that component goes into
            // Breakdown (the unit status does not), held until the record is done.
            const plan = planDamageHold(rec, unit);
            rec.drove = plan.field;
            globalDamages.push(rec);
            cloudPushDamage(rec);
            if (plan.fields && !_applyDamageLink(unit.id, plan.fields, _unlinkOnRefused(rec.id, plan.field, unit.name || unit.sn))) {
                rec.drove = ''; cloudPushDamage(rec);
            }
            if (photo && window.cloud && window.cloud.saveDamagePhoto) {
                _dmgPhotoCache.set(rec.id, photo);
                window.cloud.saveDamagePhoto(rec.id, photo).catch(err => console.error('[ins] damage photo failed:', err));
            }
            logEvent({ action: 'add', unitId: unit.id, unitName: `[Damage] ${unit.name || ''}`,
                       field: `Device Precision / ${c.label}`, after: `${r.date} (from inspection)` });
            ids.push(rec.id);
        }
        saveDamages();
        const stamp = { ...r, appliedAt: Date.now(),
                        appliedBy: (currentUserDoc && currentUserDoc.displayName) || (currentUser && currentUser.email) || '',
                        appliedDamageIds: ids, updatedAt: Date.now() };
        const idx = inspections.findIndex(x => x.id === id);
        if (idx !== -1) inspections[idx] = stamp;
        cloudCall('saveInspection', stamp).catch(err => console.error('[ins] apply stamp failed:', err));
        showToast(`${ids.length} Damage record(s) created from the inspection report for ${inspectionUnitLabel(r)}`, 'success');
        if (currentView === 'inspection') renderInspectionView();
        if (currentView === 'damage') renderDamageTable();
        scheduleDecisionRefresh();
    } finally {
        _insApplying.delete(id);
    }
}

function exportInspectionCSV() {
    if (!canCsv('export')) return;
    const rows = getFilteredInspections();
    if (!rows.length) { showToast('No inspection reports to export', 'warning'); return; }
    const comps = inspectionComponents();
    const headers = ['No', 'Check Date', 'Unit', 'Serial Number', 'Asset Code',
        ...comps.flatMap(c => [c.label, `${c.label} Notes`]), 'General Notes', 'Schedule', 'Next Check',
        'Inspector', 'Approval', 'Approved By', 'Revision Notes'];
    const body = rows.map((r, i) => {
        const u = liveUnitFor({ unitId: r.unitId, sn: r.sn }) || {};
        const plan = r.planId ? inspectionPlans.find(p => p.id === r.planId) : null;
        return [i + 1, r.date || '', inspectionUnitLabel(r), r.sn || '', u.assetCode || '',
            ...comps.flatMap(c => [INS_RESULT[(r.results || {})[c.key]] || '', (r.notes || {})[c.key] || '']),
            r.note || '', plan ? plan.date : (r.planId ? 'deleted' : 'Unscheduled'),
            isSubmitted(r) ? addDaysISO(r.date, INSPECTION_INTERVAL_DAYS) : '',
            r.createdBy || '', APPROVAL_STATES[workLogApproval(r)].label, r.approvedBy || '', r.revisionNote || ''];
    });
    const blob = new Blob(['﻿' + toCSV(headers, body)], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `pengecekan_alat_berat_${toISODate()}.csv`;
    a.click();
    URL.revokeObjectURL(url);
    showToast(`Exported ${rows.length} inspection reports to CSV`, 'success');
}

// The chip under a heavy unit's name in Unit Database.
function inspectionChipFor(unit) {
    if (!isHeavy(unit) || !['inspection', 'inspectionApprove', 'leader'].some(a => hasAccess(a, 'view'))) return '';
    const s = inspectionStatusFor(unit);
    return `<button type="button" class="ins-st ins-st--${s.key} ins-st--chip" title="${escapeHtml(s.next ? 'Next check ' + s.next : 'Never checked')} — open Inspection"
        onclick="goInspectionFor(${jsArg(unit.id)})"><i class="fas fa-clipboard-check"></i> ${escapeHtml(s.key === 'never' ? 'Not checked' : 'Check: ' + s.label)}</button>`;
}

function goInspectionFor(unitId) {
    navigateTo('inspection');
    if (currentView !== 'inspection') return;
    const u = globalData.find(x => x.id === unitId);
    inspectionTab = 'status';
    const s = document.getElementById('insStatusSearch');
    if (s) s.value = u ? (u.name || u.sn || '') : '';
    const f = document.getElementById('insStatusFilter');
    if (f) f.value = '';
    renderInspectionView();
}

// Sidebar badge: units overdue or due within three days, for whoever checks,
// plus this account's own reports sent back.
function updateInspectionBadge() {
    const el = document.getElementById('inspectionBadge');
    if (!el) return;
    if (!canViewView('inspection')) { el.style.display = 'none'; return; }
    const today = toISODate();
    const due = hasAccess('inspection', 'edit')
        ? inspectableUnits().filter(u => ['overdue', 'soon'].includes(inspectionStatusFor(u, today).key)).length : 0;
    const mine = inspections.filter(r => isMyRecord(r) && workLogApproval(r) === 'revision').length;
    // And, for a supervisor, reports waiting for them.
    const waiting = inspections.filter(r => workLogApproval(r) === 'pending' && canApproveThisLog(r, INS_AREAS)).length;
    const n = due + mine + waiting;
    el.textContent = n > 99 ? '99+' : String(n);
    el.style.display = n ? '' : 'none';
    updateMenuButtonLabel();
}

// ============================================================
// DATA QUALITY — one spelling per thing, and the gaps made visible
// ------------------------------------------------------------
// Free text drifts: "Gessner" and "Geesner", "PT. GPA" and "PT GPA". Each
// variant becomes its own row in every summary. Three tools:
//   - Clean Up Values (valueMergeModal): pick the spellings that mean the
//     same thing and rewrite every record to one of them, with Undo.
//   - Data Check: similar spellings, units missing key fields, implements
//     the Implements list does not know.
//   - Data Completeness card above the Unit Database: % of key fields
//     filled; a chip per gap filters the table to those units.
// ============================================================

// ---- Similar spellings ----
function _simKey(v) { return String(v || '').toLowerCase().replace(/[^a-z0-9]/g, ''); }

function _levenshtein(a, b, max) {
    let prev = Array.from({ length: b.length + 1 }, (_, i) => i);
    for (let i = 1; i <= a.length; i++) {
        const cur = [i];
        let best = i;
        for (let j = 1; j <= b.length; j++) {
            cur[j] = Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
            if (cur[j] < best) best = cur[j];
        }
        if (best > max) return max + 1;
        prev = cur;
    }
    return prev[b.length];
}

// Words of a name, with letters and digits split apart ("A1" → "a", "1").
function _simTokens(v) {
    return String(v || '').toLowerCase()
        .replace(/([a-z])(\d)/g, '$1 $2').replace(/(\d)([a-z])/g, '$1 $2')
        .split(/[^a-z0-9]+/).filter(Boolean);
}
const _ROMAN_RE = /^(i|ii|iii|iv|v|vi|vii|viii|ix|x|xi|xii|xiii|xiv|xv|xvi|xvii|xviii|xix|xx)$/;
// A token that says WHICH one — a number, a numeral, a letter, a short code
// (Afdeling I / II, Blok A / B, 6110B / 6110M, ISJ / ISS, PT. GPA / GPB). Two
// of those that differ are two different things, never a typo of each other.
const _idToken = t => t.length <= 3 || /\d/.test(t) || _ROMAN_RE.test(t);

// Same text once case and punctuation are ignored, or the same identifiers
// with one or two typos in the longer words ("Gessner" / "Geesner").
function similarSpelling(a, b) {
    const x = _simKey(a), y = _simKey(b);
    if (!x || !y) return false;
    if (x === y) return true;
    const ta = _simTokens(a), tb = _simTokens(b);
    if (ta.filter(_idToken).join(' ') !== tb.filter(_idToken).join(' ')) return false;
    const wa = ta.filter(t => !_idToken(t)).join(''), wb = tb.filter(t => !_idToken(t)).join('');
    if (!wa || !wb || wa === wb) return wa === wb && !!wa;
    const min = Math.min(wa.length, wb.length);
    const lim = min >= 8 ? 2 : min >= 5 ? 1 : 0;
    if (!lim || Math.abs(wa.length - wb.length) > lim) return false;
    return _levenshtein(wa, wb, lim) <= lim;
}

// values: Map spelling -> count. Groups of 2+ spellings that look alike,
// most-used first.
function similarValueClusters(values) {
    const list = [...values.entries()];
    const parent = list.map((_, i) => i);
    const find = i => (parent[i] === i ? i : (parent[i] = find(parent[i])));
    for (let i = 0; i < list.length; i++)
        for (let j = i + 1; j < list.length; j++)
            if (similarSpelling(list[i][0], list[j][0])) parent[find(i)] = find(j);
    const groups = new Map();
    list.forEach((e, i) => { const r = find(i); groups.set(r, (groups.get(r) || []).concat([e])); });
    return [...groups.values()].filter(g => g.length > 1)
        .map(g => g.sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0])))
        .sort((a, b) => b.reduce((n, e) => n + e[1], 0) - a.reduce((n, e) => n + e[1], 0));
}

// ---- What can be merged ----
const MERGE_FIELDS = {
    implType:    { label: 'Implement type',  group: 'tractor' },
    implBrand:   { label: 'Implement brand', group: 'tractor' },
    implement:   { label: 'Implement (full text)', group: 'tractor' },
    workTool:    { label: 'Work tool',       group: 'heavy' },
    brand:       { label: 'Brand',           group: 'heavy' },
    machineType: { label: 'Machine type',    group: 'heavy' },
    model:       { label: 'Model',           group: null },
    site:        { label: 'Site',            group: null },
    company:     { label: 'Company (team members)', members: true }
};

function canMergeField(field) {
    const f = MERGE_FIELDS[field];
    return !!f && hasAccess(f.members ? 'teamMembers' : 'editUnits', 'edit');
}

function mergeRecords(field) {
    const f = MERGE_FIELDS[field];
    if (!f) return [];
    if (f.members) return teamMembers || [];
    return f.group ? unitsOfGroup(globalData, f.group) : globalData;
}

function mergeValueOf(rec, field, known) {
    if (field === 'implType' || field === 'implBrand') {
        const p = toolPartsOf(rec, 'tractor', known);
        return field === 'implType' ? p.type : p.brand;
    }
    if (field === 'company') return _toolNorm(companyOf(rec));
    return _toolNorm(rec[field]);
}

function mergeValueCounts(field) {
    const known = _knownImplementBrands();
    const counts = new Map();
    mergeRecords(field).forEach(r => {
        const v = mergeValueOf(r, field, known);
        if (v) counts.set(v, (counts.get(v) || 0) + 1);
    });
    return counts;
}

// The unit fields that change when one record's value becomes `target`.
function _mergedFields(rec, field, target, known) {
    if (field === 'implType' || field === 'implBrand') {
        const p = toolPartsOf(rec, 'tractor', known);
        const type = field === 'implType' ? target : p.type;
        const brand = field === 'implBrand' ? target : p.brand;
        return { implement: brand ? `${type} — ${brand}` : type };
    }
    return { [field]: target };
}

// Records whose value is one of `values` and would actually change.
function mergePlan(field, values, target) {
    const known = _knownImplementBrands();
    const set = new Set(values);
    return mergeRecords(field).filter(r => {
        const v = mergeValueOf(r, field, known);
        return set.has(v) && v !== target;
    }).map(r => ({ rec: r, fields: _mergedFields(r, field, target, known) }));
}

// Several units at once: one storage write, one cloud batch, and a history
// row per changed field exactly as updateUnit writes them.
function updateUnitsBatch(changes) {
    if (!canWriteUnits('updateUnitsBatch')) return [];
    const done = [];
    changes.forEach((fields, id) => {
        const idx = globalData.findIndex(d => d.id === id);
        if (idx === -1) return;
        const before = { ...globalData[idx] };
        const guarded = guardUnitFields(before, fields);
        const keys = Object.keys(guarded).filter(k => !sameStoredValue(before[k], guarded[k]));
        if (!keys.length) return;
        globalData[idx] = { ...before, ...guarded };
        done.push({ before, unit: globalData[idx], keys });
    });
    if (!done.length) return done;
    saveToStorage(globalData);
    // Only what changed goes to the cloud — see updateUnitsFields.
    cloudPushUnitFields(done.map(d => ({ id: d.unit.id, ...Object.fromEntries(d.keys.map(k => [k, d.unit[k] == null ? '' : d.unit[k]])) })));
    recordChange({ type: 'updated', detail: `${done.length} unit(s) updated` });
    done.forEach(d => d.keys.forEach(k => logEvent({
        action: 'update', unitId: d.unit.id, unitName: d.unit.name, field: k, before: d.before[k], after: d.unit[k]
    })));
    return done;
}

// ---- Clean Up Values modal ----
let _vmField = 'implType';
let _vmSelected = new Set();
let _vmAutoTarget = '';
let _vmUndo = null;

function openValueMerge(field, values) {
    const options = Object.keys(MERGE_FIELDS).filter(canMergeField);
    if (!options.length) { showToast('You need edit access to Unit Database or Team Members', 'warning'); return; }
    _vmField = field && options.includes(field) ? field
        : options.includes(effectiveEditGroup() === 'heavy' ? 'workTool' : 'implType')
            ? (effectiveEditGroup() === 'heavy' ? 'workTool' : 'implType') : options[0];
    const sel = document.getElementById('vmField');
    sel.innerHTML = options.map(k => `<option value="${k}">${escapeHtml(MERGE_FIELDS[k].label)}${
        MERGE_FIELDS[k].group ? ` (${escapeHtml(groupDef(MERGE_FIELDS[k].group).shortLabel)})` : ''}</option>`).join('');
    sel.value = _vmField;
    document.getElementById('vmSearch').value = '';
    document.getElementById('vmTarget').value = '';
    document.getElementById('vmResult').innerHTML = '';
    _vmAutoTarget = '';
    _vmSelected = new Set();
    if (Array.isArray(values)) selectMergeValues(values, true);
    renderValueMerge();
    document.getElementById('valueMergeModal').classList.add('open');
}

function closeValueMerge() {
    document.getElementById('valueMergeModal').classList.remove('open');
}

function switchMergeField(field) {
    _vmField = field;
    _vmSelected = new Set();
    _vmAutoTarget = '';
    document.getElementById('vmTarget').value = '';
    document.getElementById('vmResult').innerHTML = '';
    renderValueMerge();
}

// Default target = the most-used selected spelling, unless the person typed
// their own.
function _vmRefreshTarget() {
    const input = document.getElementById('vmTarget');
    if (input.value && input.value !== _vmAutoTarget) return;
    const counts = mergeValueCounts(_vmField);
    const best = [..._vmSelected].sort((a, b) => (counts.get(b) || 0) - (counts.get(a) || 0) || a.localeCompare(b))[0] || '';
    input.value = best;
    _vmAutoTarget = best;
}

function toggleMergeValue(v, on) {
    if (on) _vmSelected.add(v); else _vmSelected.delete(v);
    _vmRefreshTarget();
    renderValueMerge();
}

function selectMergeValues(values, quiet) {
    const counts = mergeValueCounts(_vmField);
    _vmSelected = new Set((values || []).filter(v => counts.has(v)));
    document.getElementById('vmTarget').value = '';
    _vmAutoTarget = '';
    _vmRefreshTarget();
    if (!quiet) renderValueMerge();
}

function renderValueMerge() {
    const counts = mergeValueCounts(_vmField);
    // A selected spelling that no longer exists (merged away) drops out.
    [..._vmSelected].forEach(v => { if (!counts.has(v)) _vmSelected.delete(v); });
    const q = (document.getElementById('vmSearch').value || '').toLowerCase().trim();
    const noun = MERGE_FIELDS[_vmField].members ? 'member' : 'unit';

    const clusters = similarValueClusters(counts);
    document.getElementById('vmSuggest').innerHTML = clusters.length
        ? `<div class="vm-suggest__head"><i class="fas fa-lightbulb"></i> Looks like the same thing — ${clusters.length} suggestion(s)</div>${
            clusters.map(cl => `<div class="vm-suggest__row">
                <span>${cl.map(([v, n]) => `<b>${escapeHtml(v)}</b> <small>${n}</small>`).join(' · ')}</span>
                <button type="button" class="btn btn-secondary btn-sm" onclick="selectMergeValues(${jsArgList(cl.map(e => e[0]))})">Select</button>
            </div>`).join('')}`
        : '<div class="vm-suggest__none">No similar spellings found for this field.</div>';

    const list = [...counts.entries()]
        .filter(([v]) => !q || v.toLowerCase().includes(q) || _vmSelected.has(v))
        .sort((a, b) => _vmSelected.has(b[0]) - _vmSelected.has(a[0]) || b[1] - a[1] || a[0].localeCompare(b[0]));
    document.getElementById('vmList').innerHTML = list.length
        ? list.map(([v, n]) => `<label class="vm-row${_vmSelected.has(v) ? ' is-on' : ''}">
            <input type="checkbox" ${_vmSelected.has(v) ? 'checked' : ''} onchange="toggleMergeValue(${jsArg(v)}, this.checked)">
            <span class="vm-row__name">${escapeHtml(v)}</span>
            <span class="vm-row__count">${n} ${noun}${n === 1 ? '' : 's'}</span>
        </label>`).join('')
        : '<div class="vm-suggest__none">No values match.</div>';
    // A full implement can only become one the Implements list knows.
    const mkind = MERGE_MASTER_KIND[_vmField];
    const targets = _vmField === 'implement' && implementListActive()
        ? [...new Set(globalImplements.map(implementOptionLabel).filter(Boolean))]
        : mkind && masterListActive(mkind) ? masterLists[mkind].slice()
        : [...counts.keys()];
    document.getElementById('vmTargetList').innerHTML = targets.sort()
        .map(v => `<option value="${escapeHtml(v)}"></option>`).join('');

    const target = _toolNorm(document.getElementById('vmTarget').value);
    const plan = target ? mergePlan(_vmField, [..._vmSelected], target) : [];
    const preview = document.getElementById('vmPreview');
    preview.textContent = !_vmSelected.size ? `Tick the spellings to merge (${counts.size} value(s) in use).`
        : !target ? 'Type the spelling to keep.'
        : `${_vmSelected.size} spelling(s) → "${target}" · ${plan.length} ${noun}(s) will change`;
    document.getElementById('vmApplyBtn').disabled = !plan.length;
}

// A licence requirement is keyed by its implement type's NAME. When that name
// changes (Implements edit, or a Clean Up Values merge), the requirement moves
// with it — or the units drop out of the Purchase Plan as "no requirement".
// The new name keeps its own requirement if it already has one. The old one
// is removed only when no implement still carries the old name.
// Returns a sentence for the person, or '' when nothing was there to move.
function _carryLicenseRequirement(fromType, toType) {
    const from = licenseRequirementFor(fromType);
    if (!from || lrSlug(fromType) === lrSlug(toType)) return '';
    if (!hasAccess('licenseStock', 'edit')) return `License requirement of "${_toolNorm(fromType)}" was not moved (needs License Stock edit access)`;
    const to = licenseRequirementFor(toType);
    const oldStillUsed = globalImplements.some(i => lrSlug(i.equipmentType) === lrSlug(fromType));
    let msg;
    if (!to) {
        const rec = { id: lrSlug(toType), type: _toolNorm(toType), gps: from.gps || '', display: from.display || '',
                      updatedAt: Date.now(), updatedBy: (currentUser && currentUser.email) || '' };
        licenseRequirements = licenseRequirements.filter(r => r.id !== rec.id).concat([rec]);
        cloudCall('saveLicenseRequirement', rec).catch(err => cloudWriteFailed(err, { what: 'license requirement', label: `[License] Requirement ${rec.type}` }));
        msg = `License requirement moved to "${rec.type}"`;
    } else {
        msg = `"${_toolNorm(toType)}" kept its own license requirement`;
    }
    if (!oldStillUsed) {
        licenseRequirements = licenseRequirements.filter(r => r.id !== from.id);
        cloudCall('deleteLicenseRequirement', from.id).catch(err => cloudWriteFailed(err, { what: 'license requirement', label: `[License] Requirement ${from.type}` }));
    }
    logEvent({ action: 'update', unitName: `[License] Requirement ${_toolNorm(fromType)}`, field: 'Implement type',
               before: _toolNorm(fromType), after: _toolNorm(toType) });
    refreshLicensePlan();
    return msg;
}

// Puts the requirement set back as it was (Undo of a merge).
function _restoreLicenseRequirements(prev) {
    if (!hasAccess('licenseStock', 'edit')) return;
    const now = new Map(licenseRequirements.map(r => [r.id, r]));
    const was = new Map(prev.map(r => [r.id, r]));
    now.forEach((r, id) => { if (!was.has(id)) cloudCall('deleteLicenseRequirement', id).catch(() => {}); });
    was.forEach((r, id) => {
        const cur = now.get(id);
        if (!cur || cur.gps !== r.gps || cur.display !== r.display) cloudCall('saveLicenseRequirement', r).catch(() => {});
    });
    licenseRequirements = prev.map(r => ({ ...r }));
    refreshLicensePlan();
}

function applyValueMerge() {
    const f = MERGE_FIELDS[_vmField];
    if (!requireEdit(f.members ? 'teamMembers' : 'editUnits')) return;
    let target = _toolNorm(document.getElementById('vmTarget').value);
    if (!target) { showToast('Type the spelling to keep', 'warning'); return; }
    if (_vmField === 'implement') {
        const r = checkImplementValue(target, null);
        if (!r.ok) { showToast(`Implement "${target}" ${IMPLEMENT_NOT_IN_LIST}`, 'warning'); return; }
        target = r.value;
    }
    const mk = MERGE_MASTER_KIND[_vmField];
    if (mk) {
        const r = checkMasterValue(mk, target, null);
        if (!r.ok) { showToast(`${MASTER_DEF[mk].label} "${target}" ${masterNotInList(mk)}`, 'warning'); return; }
        target = r.value;
    }
    const values = [..._vmSelected];
    const plan = mergePlan(_vmField, values, target);
    // With an Implements list in use, an implement's type and brand live on
    // its RECORD there: rewriting only the units' text made them point at a
    // "Type — Brand" the list does not have — off-list, and out of the
    // License Purchase Plan. Rename the records too, and carry the licence
    // requirement over to the new type name.
    const onRecords = (_vmField === 'implType' || _vmField === 'implBrand') && implementListActive();
    const recKey = _vmField === 'implType' ? 'equipmentType' : 'brand';
    const recs = onRecords ? globalImplements.filter(i => values.includes(_toolNorm(i[recKey])) && _toolNorm(i[recKey]) !== target) : [];
    if (recs.length && !requireEdit('implements')) return;
    if (!plan.length && !recs.length) { showToast('Nothing to change', 'info'); return; }
    const noun = f.members ? 'member' : 'unit';
    if (!confirm(`Change ${plan.length} ${noun}(s)${recs.length ? ` and ${recs.length} record(s) in the Implements list` : ''}?\n\n`
        + `${values.filter(v => v !== target).map(v => `"${v}"`).join(', ')}\n→ "${target}"`)) return;
    let recNote = '';
    let recUndo = null;
    if (recs.length) {
        const reqBefore = licenseRequirements.map(r => ({ ...r }));
        const prevRecs = recs.map(r => ({ ...r }));
        recs.forEach(rec => {
            const idx = globalImplements.findIndex(i => i.id === rec.id);
            globalImplements[idx] = { ...rec, [recKey]: target, updatedAt: Date.now() };
            cloudPushImplement(globalImplements[idx]);
            logEvent({ action: 'update', unitId: rec.id, unitName: `[Implement] ${rec.profileName || ''}`,
                       field: recKey === 'brand' ? 'Brand' : 'Type of Equipment', before: rec[recKey], after: target });
        });
        saveImplements();
        if (currentView === 'implements') renderImplementsTable();
        if (_vmField === 'implType') {
            recNote = [...new Set(recs.map(r => _toolNorm(r.equipmentType)))].map(t => _carryLicenseRequirement(t, target)).filter(Boolean).join(' · ');
        }
        recUndo = { recs: prevRecs, reqs: reqBefore };
    }

    let n = 0;
    if (f.members) {
        const prev = plan.map(p => ({ ...p.rec }));
        const recs = plan.map(p => ({ ...p.rec, ...p.fields, updatedAt: Date.now() }));
        n = recs.length;
        _commitMembers(recs, `Company merged into "${target}"`, prev);
        _vmUndo = { members: true, recs: prev, label: `"${target}"` };
    } else {
        const changes = new Map(plan.map(p => [p.rec.id, p.fields]));
        const prevMap = new Map(plan.map(p => [p.rec.id, Object.fromEntries(Object.keys(p.fields).map(k => [k, p.rec[k] == null ? '' : p.rec[k]]))]));
        const done = updateUnitsBatch(changes);
        n = done.length;
        _vmUndo = (n || recUndo) ? { members: false, prev: new Map(done.map(d => [d.unit.id, prevMap.get(d.unit.id)])), label: `"${target}"`, records: recUndo } : null;
    }
    _vmSelected = new Set();
    _vmAutoTarget = '';
    document.getElementById('vmTarget').value = '';
    const recBit = recs.length ? ` and ${recs.length} Implements record(s)` : '';
    document.getElementById('vmResult').innerHTML = (n || recs.length)
        ? `<div class="vm-result"><i class="fas fa-check"></i> ${n} ${noun}(s)${escapeHtml(recBit)} changed to "${escapeHtml(target)}".${recNote ? ` ${escapeHtml(recNote)}.` : ''}
            <button type="button" class="btn btn-secondary btn-sm" onclick="undoValueMerge()"><i class="fas fa-rotate-left"></i> Undo</button></div>`
        : '';
    showToast((n || recs.length) ? `${n} ${noun}(s)${recBit} changed to "${target}"${recNote ? ' · ' + recNote : ''}` : 'Nothing changed', (n || recs.length) ? 'success' : 'info');
    _afterDataFix();
    renderValueMerge();
}

function undoValueMerge() {
    const u = _vmUndo;
    if (!u) return;
    _vmUndo = null;
    let n = 0;
    if (u.members) {
        if (!requireEdit('teamMembers')) return;
        n = u.recs.length;
        _commitMembers(u.recs.map(r => ({ ...r, updatedAt: Date.now() })), `Company merge into ${u.label} undone`);
    } else {
        if (!requireEdit('editUnits')) return;
        n = updateUnitsBatch(u.prev).length;
        if (u.records && hasAccess('implements', 'edit')) {
            u.records.recs.forEach(rec => {
                const idx = globalImplements.findIndex(i => i.id === rec.id);
                if (idx === -1) return;
                globalImplements[idx] = { ...rec, updatedAt: Date.now() };
                cloudPushImplement(globalImplements[idx]);
                n++;
            });
            saveImplements();
            if (currentView === 'implements') renderImplementsTable();
            _restoreLicenseRequirements(u.records.reqs);
        }
    }
    document.getElementById('vmResult').innerHTML = '';
    showToast(n ? `Undone — ${n} record(s) restored` : 'Nothing to undo', n ? 'success' : 'info');
    _afterDataFix();
    renderValueMerge();
}

function _commitMembers(recs, what, rollback) {
    const before = teamMembers.slice();
    const byId = new Map(recs.map(r => [r.id, r]));
    // Only the fields that differ from this device's copy go to the cloud, so
    // a merge (or its Undo) cannot put back a job title or an active flag
    // another device changed in the meantime.
    const partials = recs.map(r => {
        const cur = before.find(m => m.id === r.id) || {};
        const p = { id: r.id };
        Object.keys(r).forEach(k => { if (k !== 'id' && !sameStoredValue(cur[k], r[k])) p[k] = r[k]; });
        return p;
    }).filter(p => Object.keys(p).length > 1);
    teamMembers = teamMembers.map(m => byId.get(m.id) || m);
    const send = typeof window.cloud?.updateTeamMembersFields === 'function' ? 'updateTeamMembersFields' : 'saveTeamMembers';
    cloudWrite(
        { action: 'update', unitName: '[Team] Members', field: 'Company', before: '', after: `${what} — ${recs.length} member(s)` },
        cloudCall(send, partials),
        null,
        err => {
            console.error('[merge] members save failed:', err);
            teamMembers = before;
            if (err && err.code === 'permission-denied') showTeamRulesBanner();
            showToast('Failed to save the members — change reverted', 'error');
            _afterDataFix();
        }
    );
}

function _afterDataFix() {
    if (currentView === 'editUnits') renderEditTable();
    if (document.getElementById('dataCheckBody')) renderDataCheck();
    if (currentView === 'team' && typeof renderShiftGrid === 'function') renderShiftGrid();
}

// ---- Data Check: the new checks ----
function dcSimilarSpellings() {
    const out = [];
    ['implType', 'implBrand', 'brand', 'workTool', 'machineType', 'model', 'site', 'company'].forEach(field => {
        similarValueClusters(mergeValueCounts(field)).forEach(cl => {
            // Case / punctuation-only site variants are dcSiteVariants' job.
            if (field === 'site' && new Set(cl.map(([v]) => _simKey(v))).size < 2) return;
            const def = MERGE_FIELDS[field];
            out.push(dc('ejaan-mirip', `${def.label}${def.group ? ' (' + groupDef(def.group).shortLabel + ')' : ''}: similar spellings`,
                cl.map(([v, n]) => `"${v}" (${n})`).join(' · '),
                field === 'company' ? 'team' : `editUnits:${def.group || 'tractor'}`,
                { merge: { field, values: cl.map(e => e[0]) } }));
        });
    });
    return out;
}

function isFieldMissing(u, f) { return !_toolNorm(u && u[f]); }

function dcMissingKeyFields() {
    const out = [];
    UNIT_GROUP_KEYS.forEach(g => {
        const units = unitsOfGroup(globalData, g);
        (REQUIRED_UNIT_FIELDS[g] || []).forEach(f => {
            if (f === 'site') return;   // listed one by one under "Company / site not set"
            const miss = units.filter(u => isFieldMissing(u, f));
            if (!miss.length) return;
            const names = miss.slice(0, 5).map(u => u.name || u.sn || u.id).join(', ');
            out.push(dc('data-kurang', `${groupDef(g).shortLabel}: no ${REQUIRED_FIELD_LABEL[f]}`,
                `${miss.length} unit(s) — ${names}${miss.length > 5 ? ', …' : ''}`, `missing:${g}:${f}`));
        });
    });
    return out;
}

// Only meaningful once the Implements list is in use. A value the list
// recognises under another spelling ("ISS — Final Cultivator" for "Final
// Cultivator — ISS") is fixable in one click; one it does not know is not.
function dcImplementNotInList() {
    if (!implementListActive()) return [];
    const unknown = new Map(), respell = new Map();
    unitsOfGroup(globalData, 'tractor').forEach(u => {
        const v = _toolNorm(u.implement);
        if (!v) return;
        const imp = findImplementRecord(v);
        if (!imp) unknown.set(v, (unknown.get(v) || 0) + 1);
        else if (implementOptionLabel(imp) !== u.implement) {
            const k = `${v}\u0001${implementOptionLabel(imp)}`;
            respell.set(k, (respell.get(k) || 0) + 1);
        }
    });
    const out = [...unknown.entries()].sort((a, b) => b[1] - a[1]).map(([v, n]) =>
        dc('impl-tak-dikenal', `Implement: ${v}`, `${n} unit(s) — not in the Implements list`, 'implements',
            { merge: { field: 'implement', values: [v] } }));
    respell.forEach((n, k) => {
        const [from, to] = k.split('\u0001');
        out.push(dc('impl-ejaan', `Implement: ${from}`, `${n} unit(s) — the Implements list spells it "${to}"`,
            'editUnits:tractor', { implFix: true }));
    });
    return out;
}

// Rewrites every implement the list recognises to the list's own spelling.
function matchImplementsToList() {
    if (!requireEdit('editUnits')) return;
    const changes = new Map();
    unitsOfGroup(globalData, 'tractor').forEach(u => {
        const imp = u.implement ? findImplementRecord(u.implement) : null;
        if (imp && implementOptionLabel(imp) !== u.implement) changes.set(u.id, { implement: implementOptionLabel(imp) });
    });
    if (!changes.size) { showToast('Every implement already uses the list spelling', 'info'); return; }
    if (!confirm(`Rewrite the implement of ${changes.size} unit(s) to the Implements list spelling?\n\n`
        + 'Only the spelling changes — each unit keeps the same implement.')) return;
    const done = updateUnitsBatch(changes);
    showToast(`${done.length} unit(s) now use the Implements list spelling`, 'success');
    _afterDataFix();
}

// ---- Data Completeness card (Unit Database) ----

function setEditMissingFilter(f, force) {
    editMissingFilter = force ? (f || '') : (editMissingFilter === f ? '' : (f || ''));
    renderEditTable();
}

function renderDataCompleteness() {
    const box = document.getElementById('dataQuality');
    if (!box) return;
    const g = effectiveEditGroup();
    const units = unitsOfGroup(globalData, g);
    const fields = REQUIRED_UNIT_FIELDS[g] || [];
    if (!units.length || !fields.length) { box.style.display = 'none'; box.innerHTML = ''; return; }
    const missing = fields.map(f => ({ f, n: units.filter(u => isFieldMissing(u, f)).length }));
    const gaps = missing.reduce((n, m) => n + m.n, 0);
    const total = units.length * fields.length;
    // Rounded down: 99.6% is not "100%" while one field is still empty.
    const pct = Math.floor((total - gaps) / total * 100);
    const complete = units.filter(u => fields.every(f => !isFieldMissing(u, f))).length;
    const tone = pct >= 95 ? 'good' : pct >= 80 ? 'warn' : 'bad';
    const canFix = Object.keys(MERGE_FIELDS).some(canMergeField) && hasAccess('editUnits', 'edit');
    box.className = `dq dq--${tone}`;
    box.innerHTML = `
        <div class="dq__score">
            <div class="dq__pct">${pct}%</div>
            <div class="dq__text">
                <div class="dq__title">Data Completeness</div>
                <div class="dq__sub">${complete} of ${units.length} unit(s) have every key field
                    (${fields.map(f => REQUIRED_FIELD_LABEL[f]).join(', ')})</div>
                <div class="dq__bar"><span style="width:${pct}%"></span></div>
            </div>
        </div>
        <div class="dq__gaps">
            ${gaps ? missing.filter(m => m.n).map(m => {
                const on = editMissingFilter === m.f;
                return `<button type="button" class="dq-chip${on ? ' is-on' : ''}" aria-pressed="${on}"
                    title="${on ? 'Click again to show all' : 'Show only these units in the table'}"
                    onclick="setEditMissingFilter(${jsArg(m.f)})"><b>${m.n}</b> no ${escapeHtml(REQUIRED_FIELD_LABEL[m.f])}</button>`;
            }).join('') : '<span class="dq__ok"><i class="fas fa-circle-check"></i> Every key field is filled</span>'}
            ${canFix ? `<button type="button" class="btn btn-secondary btn-sm dq__merge" onclick="openValueMerge()"
                title="Merge spellings that mean the same thing"><i class="fas fa-broom"></i> Clean Up Values</button>` : ''}
            ${canViewMasterList('site') ? `<button type="button" class="btn btn-secondary btn-sm dq__master" onclick="openMasterLists('site')"
                title="The agreed list of sites (and brands, companies)"><i class="fas fa-list-check"></i> Master Lists</button>` : ''}
        </div>`;
    box.style.display = '';
}

// ============================================================
// MASTER LISTS — one agreed spelling for Site, Brand and Company
// ------------------------------------------------------------
// Each list is one Firestore document (masterLists/{site|brand|company}).
// While a list is empty anything goes, exactly as before. Once it has
// entries, every place that writes that value — unit form, Bulk Edit,
// inline edit, CSV import, the Implements form/import, team members,
// Clean Up Values — accepts only a list entry and stores the list's own
// spelling ("pt gpa" → "PT. GPA"). A value already on a record is never
// forced off it; Data Check lists those.
// ============================================================

function canEditMasterList(kind) { return (MASTER_DEF[kind] || { edit: [] }).edit.some(a => hasAccess(a, 'edit')); }
const MASTER_GROUP = { heavyBrand: 'heavy', brand: 'tractor' };
function canViewMasterList(kind) {
    if (MASTER_GROUP[kind] && !unitScopeAllows(MASTER_GROUP[kind])) return false;
    return (MASTER_DEF[kind] || { view: [] }).view.some(a => hasAccess(a, 'view')) || canEditMasterList(kind);
}
function masterListActive(kind) { return !!(masterLists[kind] && masterLists[kind].length); }
function masterNotInList(kind) {
    return `is not in the ${MASTER_DEF[kind].label} list — pick one from the list, or add it under Admin → Master Lists first`;
}

// The list entry a typed value means: same text ignoring case, spacing and
// punctuation ("PT GPA" = "PT. GPA"). Returns the entry or null.
function masterMatch(kind, text) {
    const t = _toolNorm(text);
    if (!t) return null;
    const list = masterLists[kind] || [];
    const low = t.toLowerCase();
    return list.find(v => v.toLowerCase() === low)
        || (_simKey(t) ? list.find(v => _simKey(v) === _simKey(t)) : null) || null;
}

function checkMasterValue(kind, text, previous) {
    const t = _toolNorm(text);
    if (!t) return { ok: true, value: '' };
    if (!masterListActive(kind)) return { ok: true, value: t };
    const m = masterMatch(kind, t);
    if (m) return { ok: true, value: m };
    if (previous != null && _toolNorm(previous) === t) return { ok: true, value: previous };
    return { ok: false, value: t };
}

function companySuggestions() { return masterListActive('company') ? masterLists.company.slice() : allCompanies(); }

// Values in use, per list: Map spelling -> count.
function masterUsage(kind) {
    const counts = new Map();
    const add = v => { v = _toolNorm(v); if (v) counts.set(v, (counts.get(v) || 0) + 1); };
    if (kind === 'site') globalData.forEach(u => add(u.site));
    if (kind === 'brand') globalImplements.forEach(i => add(i.brand));
    if (kind === 'heavyBrand') unitsOfGroup(globalData, 'heavy').forEach(u => add(u.brand));
    if (kind === 'company') (teamMembers || []).forEach(m => add(companyOf(m)));
    return counts;
}
const MASTER_USED_NOUN = { site: 'unit', brand: 'implement', heavyBrand: 'unit', company: 'member' };

function applyMasterListsSnapshot(docs) {
    _markLoaded('masterLists');
    const next = { site: [], brand: [], heavyBrand: [], company: [] };
    (docs || []).forEach(d => {
        if (MASTER_KINDS.includes(d.id) && Array.isArray(d.values)) next[d.id] = d.values.map(_toolNorm).filter(Boolean);
    });
    masterLists = next;
    populateMasterDatalists();
    if (document.getElementById('masterListsModal')?.classList.contains('open')) renderMasterLists();
    if (currentView === 'editUnits') renderEditTable();
}

function populateMasterDatalists() {
    const fill = (id, values) => {
        const dl = document.getElementById(id);
        if (dl) dl.innerHTML = values.map(v => `<option value="${escapeHtml(v)}"></option>`).join('');
    };
    const sorted = m => [...m.keys()].sort((a, b) => a.localeCompare(b));
    fill('siteList', masterListActive('site') ? masterLists.site : sorted(masterUsage('site')));
    fill('brandList', masterListActive('brand') ? masterLists.brand : sorted(masterUsage('brand')));
    fill('heavyBrandList', masterListActive('heavyBrand') ? masterLists.heavyBrand : sorted(masterUsage('heavyBrand')));
    fill('companyList', companySuggestions());
}

// ---- Modal ----
let _mlKind = 'site';

function openMasterLists(kind) {
    const kinds = MASTER_KINDS.filter(canViewMasterList);
    if (!kinds.length) { showToast('You do not have access to any master list', 'warning'); return; }
    _mlKind = kind && kinds.includes(kind) ? kind : (kinds.includes(_mlKind) ? _mlKind : kinds[0]);
    document.getElementById('mlNewValue').value = '';
    renderMasterLists();
    document.getElementById('masterListsModal').classList.add('open');
}
function closeMasterLists() { document.getElementById('masterListsModal').classList.remove('open'); }
function switchMasterList(kind) { _mlKind = kind; document.getElementById('mlNewValue').value = ''; renderMasterLists(); }

function renderMasterLists() {
    const tabs = document.getElementById('mlTabs');
    tabs.innerHTML = MASTER_KINDS.filter(canViewMasterList).map(k => `<button type="button" role="tab"
        class="team-tab${k === _mlKind ? ' active' : ''}" aria-selected="${k === _mlKind}" onclick="switchMasterList(${jsArg(k)})">
        ${escapeHtml(MASTER_DEF[k].plural)} <span class="team-tab__count">${masterLists[k].length}</span></button>`).join('');
    const def = MASTER_DEF[_mlKind];
    const canEdit = canEditMasterList(_mlKind);
    const usage = masterUsage(_mlKind);
    const noun = MASTER_USED_NOUN[_mlKind];
    const list = masterLists[_mlKind];
    const usedBy = v => [...usage.entries()].filter(([u]) => _simKey(u) === _simKey(v) || u.toLowerCase() === v.toLowerCase())
        .reduce((n, e) => n + e[1], 0);
    const outside = [...usage.entries()].filter(([v]) => !masterMatch(_mlKind, v)).sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]));

    document.getElementById('mlIntro').textContent = list.length
        ? `${def.hint} Only these ${def.plural.toLowerCase()} can be chosen.`
        : `${def.hint} The list is empty, so any text is accepted. Add entries — or fill it from the values in use — to make it the only choice.`;
    document.getElementById('mlAddForm').style.display = canEdit ? '' : 'none';
    const fillBtn = document.getElementById('mlFillBtn');
    fillBtn.style.display = canEdit && outside.length ? '' : 'none';
    fillBtn.textContent = `Add the ${outside.length} value(s) in use`;

    document.getElementById('mlList').innerHTML = list.length ? list.map(v => {
        const n = usedBy(v);
        return `<li class="category-item ml-item">
            <span class="category-item__name">${escapeHtml(v)} <small class="ml-used">${n ? `${n} ${noun}${n === 1 ? '' : 's'}` : 'not used'}</small></span>
            ${canEdit ? `<span class="row-actions row-actions--labeled">
                <button type="button" class="btn btn-secondary btn-sm" onclick="renameMasterValue(${jsArg(v)})">Rename</button>
                <button type="button" class="btn btn-secondary btn-sm row-actions__icon" title="Remove from the list" aria-label="Remove ${escapeHtml(v)}"
                    onclick="removeMasterValue(${jsArg(v)})"><i class="fas fa-trash" style="color:var(--danger)"></i></button>
            </span>` : ''}
        </li>`;
    }).join('') : `<li class="category-empty">No ${def.plural.toLowerCase()} in the list yet.</li>`;

    const out = document.getElementById('mlOutside');
    out.innerHTML = list.length && outside.length ? `
        <div class="ml-outside__head"><i class="fas fa-triangle-exclamation"></i> In use but not in the list (${outside.length})</div>
        <ul class="categories-list">${outside.map(([v, n]) => `<li class="category-item ml-item">
            <span class="category-item__name">${escapeHtml(v)} <small class="ml-used">${n} ${noun}${n === 1 ? '' : 's'}</small></span>
            ${canEdit ? `<span class="row-actions row-actions--labeled">
                <button type="button" class="btn btn-secondary btn-sm" onclick="addMasterValue(${jsArg(v)})">Add to list</button>
                ${MASTER_MERGE_FIELD[_mlKind] && canMergeField(MASTER_MERGE_FIELD[_mlKind]) ? `<button type="button" class="btn btn-secondary btn-sm"
                    onclick="closeMasterLists(); openValueMerge(${jsArg(MASTER_MERGE_FIELD[_mlKind])}, ${jsArgList([v])})">Merge…</button>` : ''}
            </span>` : ''}</li>`).join('')}</ul>` : '';
}

function _saveMasterList(kind, values, what) {
    const before = masterLists[kind].slice();
    const next = [...new Set(values.map(_toolNorm).filter(Boolean))].sort((a, b) => a.localeCompare(b));
    masterLists = { ...masterLists, [kind]: next };
    populateMasterDatalists();
    renderMasterLists();
    cloudWrite(
        { action: 'update', unitName: `[Master] ${MASTER_DEF[kind].plural}`, field: 'List', before: '', after: what },
        cloudCall('saveMasterList', kind, next, (currentUser && currentUser.email) || ''),
        null,
        err => {
            console.error('[master] save failed:', err);
            masterLists = { ...masterLists, [kind]: before };
            populateMasterDatalists();
            renderMasterLists();
            showToast(err && err.code === 'permission-denied'
                ? 'Refused by the server — publish the latest firestore.rules (Master Lists) and check your access'
                : `Failed to save the ${MASTER_DEF[kind].label} list — change reverted`, 'error');
        }
    );
}

function addMasterValue(value) {
    const kind = _mlKind;
    if (!canEditMasterList(kind)) { showToast('You do not have edit access to this list', 'warning'); return; }
    const input = document.getElementById('mlNewValue');
    const v = _toolNorm(value != null ? value : input.value);
    if (!v) { showToast(`Type a ${MASTER_DEF[kind].label.toLowerCase()} name`, 'warning'); return; }
    if (v.length > 80) { showToast('Keep it under 80 characters', 'warning'); return; }
    const dup = masterMatch(kind, v);
    if (dup) { showToast(`Already in the list as "${dup}"`, 'info'); return; }
    if (masterLists[kind].length >= 500) { showToast('A list can hold at most 500 entries', 'warning'); return; }
    _saveMasterList(kind, masterLists[kind].concat([v]), `Added "${v}"`);
    if (value == null) input.value = '';
    showToast(`"${v}" added to the ${MASTER_DEF[kind].label} list`, 'success');
}

// Seeds the list from what the records already say. Spellings of one thing
// ("PT. GPA", "PT GPA", "PT. GPAA") go in once, as the most-used spelling.
function fillMasterFromUsage() {
    const kind = _mlKind;
    if (!canEditMasterList(kind)) return;
    const usage = masterUsage(kind);
    const outside = new Map([...usage.entries()].filter(([v]) => !masterMatch(kind, v)));
    if (!outside.size) return;
    // Only spellings that ARE the same entry to the list (case, spacing,
    // punctuation — "PT GPA" / "PT. GPA") go in once, as the most-used one.
    // Look-alikes are added as they are and only pointed out: folding them
    // here once kept "Afdeling I" and dropped II to V, and every unit at
    // those afdelings was then refused as off-list.
    const byKey = new Map();
    outside.forEach((n, v) => {
        const k = _simKey(v) || v.toLowerCase();
        const best = byKey.get(k);
        if (!best || n > best[1] || (n === best[1] && v.localeCompare(best[0]) < 0)) byKey.set(k, [v, n]);
    });
    const picks = [...byKey.values()].map(e => e[0]).sort((a, b) => a.localeCompare(b));
    const folded = outside.size - picks.length;
    const lookAlike = similarValueClusters(new Map(picks.map(v => [v, outside.get(v) || 0])))
        .map(cl => cl.map(e => e[0]).join(' / '));
    if (!confirm(`Add ${picks.length} ${MASTER_DEF[kind].label.toLowerCase()}(s) to the list?\n\n${picks.join('\n')}`
        + (folded ? `\n\n${folded} spelling(s) that differ only in capitals, spaces or punctuation were added once.` : '')
        + (lookAlike.length ? `\n\nThese look alike — check whether they are the same thing (Clean Up Values can merge them):\n${lookAlike.join('\n')}` : ''))) return;
    _saveMasterList(kind, masterLists[kind].concat(picks), `Added ${picks.length} value(s) in use`);
    showToast(`${picks.length} value(s) added to the ${MASTER_DEF[kind].label} list`, 'success');
}

function removeMasterValue(v) {
    const kind = _mlKind;
    if (!canEditMasterList(kind)) return;
    const n = [...masterUsage(kind).entries()].filter(([u]) => masterMatch(kind, u) === v).reduce((a, e) => a + e[1], 0);
    if (!confirm(`Remove "${v}" from the ${MASTER_DEF[kind].label} list?`
        + (n ? `\n\n${n} ${MASTER_USED_NOUN[kind]}(s) still use it. They keep the value, and Data Check will list them.` : ''))) return;
    _saveMasterList(kind, masterLists[kind].filter(x => x !== v), `Removed "${v}"`);
}

// Renames the entry AND every record that uses it.
function renameMasterValue(v) {
    const kind = _mlKind;
    if (!canEditMasterList(kind)) return;
    const raw = prompt(`New name for "${v}":`, v);
    const to = _toolNorm(raw);
    if (!to || to === v) return;
    const clash = masterMatch(kind, to);
    if (clash && clash !== v) { showToast(`"${clash}" is already in the list — use Clean Up Values to merge into it`, 'warning'); return; }
    const uses = rec => !!rec && (_toolNorm(rec).toLowerCase() === v.toLowerCase() || _simKey(rec) === _simKey(v));
    let n = 0;
    if (kind === 'site') {
        if (!requireEdit('editUnits')) return;
        const changes = new Map(globalData.filter(u => uses(u.site)).map(u => [u.id, { site: to }]));
        n = updateUnitsBatch(changes).length;
    } else if (kind === 'company') {
        if (!requireEdit('teamMembers')) return;
        const recs = (teamMembers || []).filter(m => uses(companyOf(m))).map(m => ({ ...m, company: to, updatedAt: Date.now() }));
        if (recs.length) _commitMembers(recs, `Company renamed "${v}" → "${to}"`);
        n = recs.length;
    } else if (kind === 'brand') {
        const imps = globalImplements.filter(i => uses(i.brand));
        if (imps.length && !requireEdit('implements')) return;
        // Units name an implement by "Type — Brand", so they follow it.
        const unitChanges = new Map();
        imps.forEach(imp => {
            const next = { ...imp, brand: to, updatedAt: Date.now() };
            globalData.forEach(u => {
                if (unitGroupOf(u) === 'tractor' && u.implement && findImplementRecord(u.implement) === imp)
                    unitChanges.set(u.id, { implement: implementOptionLabel(next) });
            });
        });
        imps.forEach(imp => {
            const idx = globalImplements.findIndex(i => i.id === imp.id);
            globalImplements[idx] = { ...imp, brand: to, updatedAt: Date.now() };
            cloudPushImplement(globalImplements[idx]);
            logEvent({ action: 'update', unitId: imp.id, unitName: `[Implement] ${imp.profileName || ''}`, field: 'Brand', before: imp.brand, after: to });
        });
        if (imps.length) { saveImplements(); if (currentView === 'implements') renderImplementsTable(); }
        if (unitChanges.size && hasAccess('editUnits', 'edit')) updateUnitsBatch(unitChanges);
        n = imps.length;
    } else if (kind === 'heavyBrand') {
        if (!requireEdit('editUnits')) return;
        const changes = new Map(unitsOfGroup(globalData, 'heavy').filter(u => uses(u.brand)).map(u => [u.id, { brand: to }]));
        n = updateUnitsBatch(changes).length;
    }
    _saveMasterList(kind, masterLists[kind].map(x => (x === v ? to : x)), `Renamed "${v}" → "${to}"`);
    showToast(`Renamed to "${to}"${n ? ` — ${n} ${MASTER_USED_NOUN[kind]}(s) updated` : ''}`, 'success');
    _afterDataFix();
}

// ---- Data Check ----
function dcNotInMasterLists() {
    const out = [];
    MASTER_KINDS.forEach(kind => {
        if (!masterListActive(kind)) return;
        [...masterUsage(kind).entries()].filter(([v]) => !masterMatch(kind, v)).sort((a, b) => b[1] - a[1]).forEach(([v, n]) => {
            out.push(dc('master-luar', `${MASTER_DEF[kind].label}: ${v}`,
                `${n} ${MASTER_USED_NOUN[kind]}(s) — not in the ${MASTER_DEF[kind].label} list`,
                kind === 'brand' ? 'implements' : kind === 'company' ? 'team' : kind === 'heavyBrand' ? 'editUnits:heavy' : 'editUnits',
                MASTER_MERGE_FIELD[kind] ? { merge: { field: MASTER_MERGE_FIELD[kind], values: [v] } } : {}));
        });
    });
    return out;
}

// ============================================================
// LICENSE PURCHASE PLAN — what to buy, from what each implement needs
// ------------------------------------------------------------
// Each implement TYPE (no brand) carries a GPS and a display requirement,
// set by the owner of license stock (licenseRequirements/{type key}). Every
// agricultural unit using that type is checked against it on the plan date:
//   - SF-RTK and G5 Advance are paid: missing, a lower tier, or ending before
//     the plan date → one to buy.
//   - SF-1 and G5 Basic are free: a gap there is a setting to fix, not a buy.
//   - G5 Advance covers G5 Basic, SF-RTK covers SF-1.
// What to buy = needed − remaining stock. Distributing a license through the
// stock ledger writes it to the unit, so the plan shrinks by itself.
// ============================================================


function lrSlug(type) {
    return String(type || '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 120) || 'type';
}

function applyLicenseRequirementsSnapshot(list) {
    _markLoaded('licenseRequirements');
    licenseRequirements = (list || []).filter(r => r && r.id);
    refreshLicensePlan();
    if (document.getElementById('licenseReqModal')?.classList.contains('open')) renderLicenseRequirements();
}

function licenseRequirementFor(type) {
    return licenseRequirements.find(r => r.id === lrSlug(type)) || null;
}

function switchLicenseTab(tab) {
    licenseTab = tab === 'plan' ? 'plan' : 'stock';
    document.querySelectorAll('#viewLicenseStock .lic-tab').forEach(b => {
        const on = b.dataset.tab === licenseTab;
        b.classList.toggle('active', on);
        b.setAttribute('aria-selected', on ? 'true' : 'false');
    });
    const stock = document.getElementById('licStockPanel'), plan = document.getElementById('licPlanPanel');
    if (stock) stock.style.display = licenseTab === 'stock' ? '' : 'none';
    if (plan) plan.style.display = licenseTab === 'plan' ? '' : 'none';
    if (licenseTab === 'plan') renderLicensePlan();
}

function _lpUntil() {
    const el = document.getElementById('lpUntil');
    if (el && !el.value) el.value = `${new Date().getFullYear()}-12-31`;
    return (el && el.value) || `${new Date().getFullYear()}-12-31`;
}

// One component (gps / display) of one unit against its requirement.
function lpCheck(unit, kind, need, until) {
    if (!need) return { state: 'na' };
    const have = canonicalLicenseType(kind === 'gps' ? unit.gpsLicense : unit.licenseDisplay);
    const end = getLicenseEndDate(unit, kind);
    const covers = kind === 'gps'
        ? (need === 'SF-1' ? ['SF-1', 'SF-RTK'] : ['SF-RTK'])
        : (need === 'G5 Basic' ? ['G5 Basic', 'G5 Advance'] : ['G5 Advance']);
    const paid = LIC_PAID.includes(need);
    if (covers.includes(have)) {
        if (paid && have === need && isoDistributionDate(end) && end < until) return { state: 'renew', buy: need, have, end };
        return { state: 'ok', have, end };
    }
    if (paid) return { state: have ? 'upgrade' : 'missing', buy: need, have, end };
    return { state: 'free', need, have, end };
}

function licensePlanCompute(until) {
    const known = _knownImplementBrands();
    const rows = [], noReq = new Map();
    unitsOfGroup(globalData, 'tractor').forEach(u => {
        const type = toolPartsOf(u, 'tractor', known).type;
        if (!type) return;
        const req = licenseRequirementFor(type);
        if (!req || (!req.gps && !req.display)) { noReq.set(type, (noReq.get(type) || 0) + 1); return; }
        const gps = lpCheck(u, 'gps', req.gps, until);
        const display = lpCheck(u, 'display', req.display, until);
        rows.push({ u, type, req, gps, display,
            gap: [gps, display].some(c => c.state !== 'ok' && c.state !== 'na') });
    });
    const need = { 'SF-RTK': 0, 'G5 Advance': 0 };
    rows.forEach(r => [r.gps, r.display].forEach(c => { if (c.buy) need[c.buy]++; }));
    const summary = computeLicenseSummary();
    const stockOf = t => {
        const k = Object.keys(summary).find(x => licenseTypeKey(x) === licenseTypeKey(t));
        return k ? Math.max(0, summary[k].sisa) : 0;
    };
    const buy = LIC_PAID.map(t => ({ type: t, need: need[t], stock: stockOf(t), toBuy: Math.max(0, need[t] - stockOf(t)) }));
    return { rows, noReq, buy };
}

function _lpCombo(req) { return [req.gps, req.display].filter(Boolean).join(' + ') || '—'; }

function _lpAction(c, kind) {
    if (c.state === 'ok' || c.state === 'na') return '';
    if (c.state === 'renew') return `<span class="lp-chip lp-chip--renew">Renew ${escapeHtml(c.buy)} (ends ${escapeHtml(c.end)})</span>`;
    if (c.state === 'upgrade') return `<span class="lp-chip lp-chip--buy">Buy ${escapeHtml(c.buy)} (has ${escapeHtml(c.have)})</span>`;
    if (c.state === 'missing') return `<span class="lp-chip lp-chip--buy">Buy ${escapeHtml(c.buy)}</span>`;
    return `<span class="lp-chip lp-chip--free">Set ${escapeHtml(c.need)} (free)</span>`;
}

function _lpHave(c, unit, kind) {
    const have = canonicalLicenseType(kind === 'gps' ? unit.gpsLicense : unit.licenseDisplay);
    const end = getLicenseEndDate(unit, kind);
    return have ? `${escapeHtml(have)}${isoDistributionDate(end) ? `<div class="ins-sub">until ${escapeHtml(end)}</div>` : ''}` : '<span style="color:var(--text-light)">—</span>';
}

function refreshLicensePlan() {
    const badge = document.getElementById('licPlanBadge');
    if (badge) {
        const n = licenseRequirements.length ? licensePlanCompute(_lpUntil()).buy.reduce((a, b) => a + b.toBuy, 0) : 0;
        badge.textContent = n;
        badge.style.display = n ? '' : 'none';
    }
    if (currentView === 'licenseStock' && licenseTab === 'plan') renderLicensePlan();
}

function renderLicensePlan() {
    const host = document.getElementById('lpBody');
    if (!host) return;
    const until = _lpUntil();
    const btn = document.getElementById('lpRulesBtn');
    if (btn) btn.innerHTML = `<i class="fas fa-sliders"></i> License Requirements${licenseRequirements.length ? ` (${licenseRequirements.length})` : ''}`;
    const { rows, noReq, buy } = licensePlanCompute(until);
    const noReqUnits = [...noReq.values()].reduce((a, b) => a + b, 0);
    const noReqNote = noReq.size ? `<div class="ins-sync ins-sync--offline"><i class="fas fa-circle-info"></i>
        ${noReq.size} implement type(s) in use have no requirement yet (${noReqUnits} unit(s)): ${escapeHtml([...noReq.keys()].slice(0, 6).join(', '))}${noReq.size > 6 ? ', …' : ''}.
        Set them under <strong>License Requirements</strong>.</div>` : '';
    if (!rows.length) {
        host.innerHTML = noReqNote + `<div class="table-card"><div class="lp-empty">${licenseRequirements.length
            ? 'No unit uses an implement type that has a requirement.'
            : 'No requirements yet. Click <strong>License Requirements</strong> and choose, per implement type, which GPS and display license it needs.'}</div></div>`;
        refreshLicensePlanBadgeOnly(buy);
        return;
    }

    // Per combination
    const combos = new Map();
    rows.forEach(r => {
        const k = _lpCombo(r.req);
        const c = combos.get(k) || { units: 0, gaps: 0 };
        c.units++; if (r.gap) c.gaps++;
        combos.set(k, c);
    });
    // Per implement type
    const types = new Map();
    rows.forEach(r => {
        const t = types.get(r.type) || { req: r.req, units: 0, rtk: 0, adv: 0, free: 0 };
        t.units++;
        [r.gps, r.display].forEach(c => {
            if (c.buy === 'SF-RTK') t.rtk++;
            if (c.buy === 'G5 Advance') t.adv++;
            if (c.state === 'free') t.free++;
        });
        types.set(r.type, t);
    });
    const gapsOnly = !!document.getElementById('lpGapsOnly')?.checked;
    const unitRows = rows.filter(r => !gapsOnly || r.gap)
        .sort((a, b) => b.gap - a.gap || a.type.localeCompare(b.type) || String(a.u.name).localeCompare(String(b.u.name)));

    host.innerHTML = noReqNote + `
        <div class="lp-cards">
            ${buy.map(b => `<div class="lp-card${b.toBuy ? ' lp-card--buy' : ''}">
                <div class="lp-card__type">${escapeHtml(b.type)}</div>
                <div class="lp-card__big">${b.toBuy}<small> to buy</small></div>
                <div class="lp-card__sub">${b.need} needed · ${b.stock} in stock</div>
            </div>`).join('')}
            ${[...combos.entries()].map(([k, c]) => `<div class="lp-card lp-card--combo">
                <div class="lp-card__type">${escapeHtml(k)}</div>
                <div class="lp-card__big">${c.units}<small> unit(s)</small></div>
                <div class="lp-card__sub">${c.gaps ? `${c.gaps} with a gap` : 'all covered'}</div>
            </div>`).join('')}
        </div>
        <div class="table-card" style="margin-bottom:16px">
            <div class="table-card__header"><h2 class="table-card__title">Per implement type</h2></div>
            <div class="table-wrapper"><table class="data-table table--cardable">
                <thead><tr><th>Implement Type</th><th>Requirement</th><th>Units</th><th>Buy SF-RTK</th><th>Buy G5 Advance</th><th>Free to set</th></tr></thead>
                <tbody>${[...types.entries()].sort((a, b) => (b[1].rtk + b[1].adv) - (a[1].rtk + a[1].adv) || a[0].localeCompare(b[0])).map(([t, v]) => `<tr>
                    <td data-label="Implement Type"><strong>${escapeHtml(t)}</strong></td>
                    <td data-label="Requirement">${escapeHtml(_lpCombo(v.req))}</td>
                    <td data-label="Units">${v.units}</td>
                    <td data-label="Buy SF-RTK">${v.rtk || '—'}</td>
                    <td data-label="Buy G5 Advance">${v.adv || '—'}</td>
                    <td data-label="Free to set">${v.free || '—'}</td>
                </tr>`).join('')}</tbody>
            </table></div>
        </div>
        <div class="table-card">
            <div class="table-card__header"><h2 class="table-card__title">Units <span class="fp-pill">${unitRows.length}</span></h2></div>
            <div class="table-wrapper" style="max-height:600px"><table class="data-table table--cardable" id="lpUnitTable">
                <thead><tr><th>Unit</th><th>Implement Type</th><th>Site</th><th>Needs</th><th>GPS Now</th><th>Display Now</th><th>To Do</th></tr></thead>
                <tbody>${unitRows.length ? unitRows.map(r => `<tr>
                    <td data-label="Unit"><strong class="unit-link" title="View unit profile" onclick="showUnitProfile(${jsArg(r.u.id)})">${escapeHtml(r.u.name || r.u.sn || '-')}</strong></td>
                    <td data-label="Implement Type">${escapeHtml(r.type)}</td>
                    <td data-label="Site">${escapeHtml(r.u.site || '—')}</td>
                    <td data-label="Needs">${escapeHtml(_lpCombo(r.req))}</td>
                    <td data-label="GPS Now">${_lpHave(r.gps, r.u, 'gps')}</td>
                    <td data-label="Display Now">${_lpHave(r.display, r.u, 'display')}</td>
                    <td data-label="To Do">${[_lpAction(r.gps, 'gps'), _lpAction(r.display, 'display')].filter(Boolean).join(' ') || '<span class="lp-chip lp-chip--ok">Covered</span>'}</td>
                </tr>`).join('') : '<tr><td colspan="7" style="text-align:center;padding:24px;color:var(--text-secondary)">Every unit is covered until this date.</td></tr>'}</tbody>
            </table></div>
        </div>`;
    refreshLicensePlanBadgeOnly(buy);
}

function refreshLicensePlanBadgeOnly(buy) {
    const badge = document.getElementById('licPlanBadge');
    if (!badge) return;
    const n = buy.reduce((a, b) => a + b.toBuy, 0);
    badge.textContent = n;
    badge.style.display = n ? '' : 'none';
}

function exportLicensePlanCSV() {
    if (!canCsv('export')) return;
    const until = _lpUntil();
    const { rows, buy } = licensePlanCompute(until);
    if (!rows.length) { showToast('Nothing to export — set License Requirements first', 'warning'); return; }
    const say = c => c.state === 'renew' ? `Renew ${c.buy} (ends ${c.end})` : c.state === 'upgrade' ? `Buy ${c.buy} (has ${c.have})`
        : c.state === 'missing' ? `Buy ${c.buy}` : c.state === 'free' ? `Set ${c.need} (free)` : '';
    const headers = ['Unit', 'Serial Number', 'Implement Type', 'Site', 'Needs', 'GPS Now', 'GPS Until', 'Display Now', 'Display Until', 'To Do'];
    const lines = rows.map(r => [r.u.name || '', r.u.sn || '', r.type, r.u.site || '', _lpCombo(r.req),
        canonicalLicenseType(r.u.gpsLicense) || '', getLicenseEndDate(r.u, 'gps') || '',
        canonicalLicenseType(r.u.licenseDisplay) || '', getLicenseEndDate(r.u, 'display') || '',
        [say(r.gps), say(r.display)].filter(Boolean).join('; ') || 'Covered']);
    lines.push([]);
    lines.push([`Plan until ${until}`]);
    buy.forEach(b => lines.push([b.type, `${b.need} needed`, `${b.stock} in stock`, `${b.toBuy} to buy`]));
    const csv = [headers, ...lines].map(row => row.map(csvCell).join(',')).join('\n');
    const blob = new Blob(['﻿' + csv], { type: 'text/csv;charset=utf-8;' });
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = `license_purchase_plan_${until}.csv`;
    a.click();
    setTimeout(() => URL.revokeObjectURL(a.href), 1000);
    showToast(`Purchase plan exported (${rows.length} unit(s))`, 'success');
}

// ---- Requirements modal ----
function openLicenseRequirements() {
    renderLicenseRequirements();
    document.getElementById('licenseReqModal').classList.add('open');
}
function closeLicenseRequirements() { document.getElementById('licenseReqModal').classList.remove('open'); }

function renderLicenseRequirements() {
    const host = document.getElementById('lrList');
    if (!host) return;
    const canEdit = hasAccess('licenseStock', 'edit');
    const known = _knownImplementBrands();
    // Every implement type: from the Implements list and from what units use.
    const types = new Map();
    globalImplements.forEach(i => { const t = _toolNorm(i.equipmentType); if (t && !types.has(lrSlug(t))) types.set(lrSlug(t), { type: t, units: 0 }); });
    unitsOfGroup(globalData, 'tractor').forEach(u => {
        const t = toolPartsOf(u, 'tractor', known).type;
        if (!t) return;
        const e = types.get(lrSlug(t)) || { type: t, units: 0 };
        e.units++;
        types.set(lrSlug(t), e);
    });
    licenseRequirements.forEach(r => { if (!types.has(r.id)) types.set(r.id, { type: r.type || r.id, units: 0 }); });
    const list = [...types.entries()].sort((a, b) => b[1].units - a[1].units || a[1].type.localeCompare(b[1].type));
    if (!list.length) { host.innerHTML = '<div class="lp-empty">No implement types yet — add implements first.</div>'; return; }
    const sel = (id, kind, cur) => `<select class="form-select form-select--sm" ${canEdit ? '' : 'disabled'}
        aria-label="${kind === 'gps' ? 'GPS' : 'Display'} license for ${escapeHtml(id)}"
        onchange="setLicenseRequirement(${jsArg(id)}, ${jsArg(kind)}, this.value)">
        ${LIC_REQ_OPTIONS[kind].map(v => `<option value="${escapeHtml(v)}"${v === (cur || '') ? ' selected' : ''}>${v ? escapeHtml(v) : (kind === 'gps' ? 'No GPS license' : 'No display license')}</option>`).join('')}
    </select>`;
    host.innerHTML = `<div class="lr-row lr-row--head"><span>Implement type</span><span>GPS</span><span>Display</span></div>` + list.map(([id, e]) => {
        const r = licenseRequirements.find(x => x.id === id) || {};
        return `<div class="lr-row">
            <span class="lr-row__type"><strong>${escapeHtml(e.type)}</strong><small>${e.units} unit(s)</small></span>
            ${sel(e.type, 'gps', r.gps)}${sel(e.type, 'display', r.display)}
        </div>`;
    }).join('');
}

function setLicenseRequirement(type, kind, value) {
    if (!requireEdit('licenseStock')) { renderLicenseRequirements(); return; }
    if (!LIC_REQ_OPTIONS[kind] || !LIC_REQ_OPTIONS[kind].includes(value)) return;
    const id = lrSlug(type);
    const prev = licenseRequirements.find(r => r.id === id) || null;
    const next = { id, type: _toolNorm(type), gps: prev ? (prev.gps || '') : '', display: prev ? (prev.display || '') : '',
        updatedAt: Date.now(), updatedBy: (currentUser && currentUser.email) || '' };
    next[kind] = value;
    const before = licenseRequirements.slice();
    const empty = !next.gps && !next.display;
    licenseRequirements = licenseRequirements.filter(r => r.id !== id).concat(empty ? [] : [next]);
    refreshLicensePlan();
    renderLicenseRequirements();
    cloudWrite(
        { action: 'update', unitName: `[License] Requirement ${next.type}`, field: kind === 'gps' ? 'GPS' : 'Display',
          before: prev ? (prev[kind] || '—') : '—', after: value || '—' },
        empty ? cloudCall('deleteLicenseRequirement', id) : cloudCall('saveLicenseRequirement', next),
        null,
        err => {
            console.error('[license] requirement save failed:', err);
            licenseRequirements = before;
            refreshLicensePlan();
            renderLicenseRequirements();
            showToast(err && err.code === 'permission-denied'
                ? 'Refused by the server — publish the latest firestore.rules (License Requirements)'
                : 'Failed to save the requirement — change reverted', 'error');
        }
    );
}

// ============================================================
// NOT SAVED — keep what was typed when the server refuses a save
// ------------------------------------------------------------
// Forms close the moment Save is pressed: offline, the write is queued and
// that IS saved. But when the server later REFUSES the write, the form was
// long gone — the report, its photos, everything typed in the field — and
// all that was left was a 4-second toast, sometimes in developer words. Now
// the form's contents are kept, and a notice that stays until it is dealt
// with offers to open the form again exactly as it was.
// ============================================================
const _unsent = new Map();   // key -> { label, reason, reopen }
let _unsentSeq = 0;

// Every field of a form, by id — enough to put it back as it was.
function captureFormState(formId) {
    const vals = {};
    document.querySelectorAll(`#${formId} input, #${formId} select, #${formId} textarea`).forEach(el => {
        if (!el.id || el.type === 'file') return;
        vals[el.id] = (el.type === 'checkbox' || el.type === 'radio') ? el.checked : el.value;
    });
    return vals;
}
function applyFormState(vals) {
    Object.keys(vals || {}).forEach(id => {
        const el = document.getElementById(id);
        if (!el) return;
        if (el.type === 'checkbox' || el.type === 'radio') el.checked = !!vals[id];
        else el.value = vals[id];
    });
}

// Why a save did not land, in words for the person holding the phone. The
// rules hint is for the one account that can act on it.
function plainSaveError(err) {
    const code = err && err.code;
    if (code === 'stale-client') return 'an old version of the app is still running — reload the page, then open it again';
    if (code === 'permission-denied') return isOwner()
        ? 'the server refused it — check this account\'s access, or re-publish firestore.rules'
        : 'the server refused it — your access may not allow this, or it was checked or locked in the meantime';
    if (code === 'unavailable' || code === 'deadline-exceeded') return 'the server could not be reached';
    return 'the server refused it';
}

function rememberUnsent(label, err, reopen) {
    const key = 'u' + (++_unsentSeq);
    _unsent.set(key, { label, reason: plainSaveError(err), reopen });
    renderUnsentNotice();
    return key;
}
function reopenUnsent(key) {
    const u = _unsent.get(key);
    if (!u) return;
    // false: the form did not open (no edit access any more, the vehicle was
    // retired, or the user kept a form they were typing in) — keep the entry.
    if (u.reopen() === false) return;
    _unsent.delete(key);
    renderUnsentNotice();
}
function dismissUnsent(key) {
    if (!_unsent.has(key)) return;
    if (!confirm('Discard this unsaved entry? What was typed — and any photos — will be lost.')) return;
    _unsent.delete(key);
    renderUnsentNotice();
}
function renderUnsentNotice() {
    let box = document.getElementById('unsentNotice');
    if (!_unsent.size) { if (box) box.remove(); return; }
    if (!box) {
        box = document.createElement('div');
        box.id = 'unsentNotice';
        box.className = 'unsent-notice';
        box.setAttribute('role', 'alert');
        document.body.appendChild(box);
    }
    box.innerHTML = [..._unsent.entries()].map(([k, u]) => `<div class="unsent-notice__row">
        <i class="fas fa-triangle-exclamation"></i>
        <span class="unsent-notice__text"><strong>Not saved:</strong> ${escapeHtml(u.label)} — ${escapeHtml(u.reason)}. What you typed is kept.</span>
        <span class="unsent-notice__acts">
            <button type="button" class="btn btn-primary btn-sm" onclick="reopenUnsent(${jsArg(k)})">Open it again</button>
            <button type="button" class="btn btn-secondary btn-sm" onclick="dismissUnsent(${jsArg(k)})">Discard</button>
        </span></div>`).join('');
}
function clearUnsent() { _unsent.clear(); renderUnsentNotice(); }

// ---- per form: what to keep, and how to open it again ----
function _snapWorkLog() {
    return { vals: captureFormState('workLogForm'), units: _wlUnits.map(u => ({ ...u })),
             photos: _wlPhotosDirty ? _wlPhotos.slice() : null };
}
function _reopenWorkLog(snap) {
    const id = snap.vals.editWorkLogId;
    const w = id && workLogs.find(x => x.id === id);
    if (w && !snap.photos && canEditTeamRecord(w)) editWorkLog(id); else showAddWorkLogForm();
    applyFormState(snap.vals);
    ensureMemberOption('wlMember', snap.vals.wlMember);
    _wlUnits = snap.units.map(u => ({ ...u }));
    if (snap.photos) { _wlPhotosGen++; _wlPhotos = snap.photos.slice(); _wlPhotosDirty = true; _wlPhotosLoading = false; }
    renderWorkLogUnitChips();
    renderWorkLogPhotos();
    // What it holds was never saved — when it did open (it may be refused).
    const opened = document.getElementById('workLogModal').classList.contains('open');
    if (opened) _formReopened.add('workLogForm');
    return opened;
}
function _snapLeave() {
    return { vals: captureFormState('leaveForm'), docs: _lvDocsDirty ? _lvDocs.slice() : null };
}
function _reopenLeave(snap) {
    const id = snap.vals.editLeaveId;
    const r = id && leaveRequests.find(x => x.id === id);
    if (r && !snap.docs && canEditTeamRecord(r)) editLeave(id); else showAddLeaveForm();
    applyFormState(snap.vals);
    ensureMemberOption('lvMember', snap.vals.lvMember);
    if (snap.docs) { _lvDocsGen++; _lvDocs = snap.docs.slice(); _lvDocsDirty = true; _lvDocsLoading = false; }
    renderLeaveDocs();
    const opened = document.getElementById('leaveModal').classList.contains('open');
    if (opened) _formReopened.add('leaveForm');
    return opened;
}
function _snapInspection(rec) {
    return { rec: { ...rec }, vals: captureFormState('inspectionForm'), results: { ..._insResults },
             photos: _insPhotosDirty ? { ..._insPhotos } : null };
}
function _reopenInspection(snap) {
    _openInspectionModal(snap.rec, snap.rec.unitId, snap.rec.planId);
    applyFormState(snap.vals);
    _insResults = { ...snap.results };
    if (snap.photos) { _insGen++; _insPhotos = { ...snap.photos }; _insPhotosDirty = true; _insPhotosLoading = false; _insPhotosFailed = false; }
    renderInspectionComponents(snap.rec);
    inspectionComponents().forEach(c => renderInspectionPhoto(c.key));
    const opened = document.getElementById('inspectionModal').classList.contains('open');
    if (opened) _formReopened.add('inspectionForm');
    return opened;
}
function _snapDamage() {
    return { vals: captureFormState('damageForm'), photo: _dmgPhotoDirty ? _dmgPhotoData : null, photoDirty: _dmgPhotoDirty,
             after: _dmgAfterDirty ? _dmgAfterData : null, afterDirty: _dmgAfterDirty };
}
function _reopenDamage(snap) {
    const id = snap.vals.editDamageId;
    if (id && globalDamages.some(d => d.id === id)) editDamage(id); else showAddDamageForm();
    applyFormState(snap.vals);
    if (!id) onDamageAlreadyRepairedChange();
    if (snap.photoDirty) { _dmgPhotoData = snap.photo || ''; _dmgPhotoDirty = true; _dmgPhotoLoading = false; setDamagePhotoPreview('before'); }
    if (snap.afterDirty) { _dmgAfterData = snap.after || ''; _dmgAfterDirty = true; _dmgAfterLoading = false; setDamagePhotoPreview('after'); }
    const opened = document.getElementById('damageModal').classList.contains('open');
    if (opened) _formReopened.add('damageForm');
    return opened;
}

// ============================================================
// WAITING TO SEND — everything written offline, not just inspections
// ------------------------------------------------------------
// Daily reports, leave requests and damage records written with no signal
// sit in Firestore's queue on this phone until it reaches the server. Only
// inspections used to show it; the rest showed "Pending" like any sent report
// — and signing out of a shared crew phone held them back unseen until the
// same person signed in on it again. Now each list marks its rows, the top
// bar counts them, and sign-out names them.
// ============================================================
const _queued = { workLogs: new Set(), leaveRequests: new Set(), damages: new Set() };
const QUEUED_NOUN = { workLogs: 'daily report', leaveRequests: 'leave / sick request', damages: 'damage record' };
let _queuedLast = 0;

function setQueued(kind, ids) {
    if (!_queued[kind]) return;
    _queued[kind] = new Set(ids || []);
    renderQueuedPill();
}

function queuedTag(kind, id) {
    return _queued[kind] && _queued[kind].has(id)
        ? '<span class="ins-tag ins-tag--queued q-tag" title="Saved on this device, not yet on the server"><i class="fas fa-cloud-arrow-up"></i> Waiting to send</span>'
        : '';
}

// ["2 daily reports", "1 inspection report", …] — only what is waiting.
function queuedSummary(insCount) {
    const out = [];
    Object.keys(_queued).forEach(k => { const n = _queued[k].size; if (n) out.push(`${n} ${QUEUED_NOUN[k]}${n === 1 ? '' : 's'}`); });
    const ins = insCount == null ? insQueuedIds.size : insCount;
    if (ins) out.push(`${ins} inspection report${ins === 1 ? '' : 's'}`);
    return out;
}

function renderQueuedPill() {
    const parts = queuedSummary();
    const total = Object.values(_queued).reduce((n, s) => n + s.size, 0) + insQueuedIds.size;
    let pill = document.getElementById('queuedPill');
    if (!pill) {
        const host = document.querySelector('.header__status');
        if (!host) return;
        pill = document.createElement('span');
        pill.id = 'queuedPill';
        pill.className = 'queued-pill';
        pill.setAttribute('role', 'status');
        host.appendChild(pill);
    }
    pill.style.display = total ? '' : 'none';
    pill.innerHTML = total ? `<i class="fas fa-cloud-arrow-up"></i> ${total} waiting to send` : '';
    pill.title = total ? `Saved on this device, sent when the signal returns: ${parts.join(', ')}` : '';
    // Inspections say so themselves (applyCloudInspectionsSnapshot).
    const others = total - insQueuedIds.size;
    if (_queuedLast > 0 && total === 0 && _queuedLastOthers > 0) showToast('Everything saved offline has now been sent', 'success');
    _queuedLast = total;
    _queuedLastOthers = others;
}
let _queuedLastOthers = 0;

if (window.cloudReady) {
    _cloudReadyFired = true;
    setupAuth();
} else {
    document.addEventListener('cloud-ready', () => {
        _cloudReadyFired = true;
        setupAuth();
    });
}
